OPENAI_DEFAULT_MODEL = (os.getenv("OPENAI_DEFAULT_MODEL") or "gpt-4o-mini").strip() or "gpt-4o-mini"
GFA_CREATIVE_COPY_DEFAULT_MODEL = "gpt-5.5-2026-04-23"
REVIEW_REPLY_PROMPT_VERSION = review_reply_v3.PROMPT_VERSION


def _openai_prefers_max_completion_tokens(model_name: str | None) -> bool:
    model0 = str(model_name or "").strip().lower()
    return model0.startswith(("gpt-5", "o1", "o3", "o4"))


def _openai_requires_default_temperature(model_name: str | None) -> bool:
    model0 = str(model_name or "").strip().lower()
    return model0.startswith("gpt-5")


def _build_openai_chat_payload(
    *,
    model_name: str,
    messages: list[dict],
    temperature: float = 0.4,
    max_output_tokens: int = 220,
) -> dict:
    payload = {
        "model": str(model_name or "").strip(),
        "messages": list(messages or []),
    }
    if not _openai_requires_default_temperature(model_name):
        payload["temperature"] = float(temperature)
    token_key = "max_completion_tokens" if _openai_prefers_max_completion_tokens(model_name) else "max_tokens"
    payload[token_key] = max(1, int(max_output_tokens or 220))
    return payload


def _is_openai_unsupported_max_tokens_response(resp: requests.Response) -> bool:
    try:
        if int(getattr(resp, "status_code", 0) or 0) != 400:
            return False
    except Exception:
        return False
    try:
        body = resp.json() or {}
    except Exception:
        body = {}
    err = body.get("error") if isinstance(body, dict) else {}
    if not isinstance(err, dict):
        err = {}
    param = str(err.get("param") or "").strip().lower()
    code = str(err.get("code") or "").strip().lower()
    message = str(err.get("message") or getattr(resp, "text", "") or "").strip().lower()
    if param == "max_tokens":
        return True
    if "max_tokens" in message and ("unsupported" in code or "not supported" in message):
        return True
    return False


def _post_openai_chat_completion_compatible(*, api_key: str, payload: dict, timeout: int = 30) -> requests.Response:
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}
    resp = requests.post(
        "https://api.openai.com/v1/chat/completions",
        headers=headers,
        json=payload,
        timeout=timeout,
    )
    if (
        _is_openai_unsupported_max_tokens_response(resp)
        and "max_tokens" in payload
        and "max_completion_tokens" not in payload
    ):
        retry_payload = dict(payload)
        retry_payload["max_completion_tokens"] = retry_payload.pop("max_tokens")
        resp = requests.post(
            "https://api.openai.com/v1/chat/completions",
            headers=headers,
            json=retry_payload,
            timeout=timeout,
        )
    return resp


def _normalize_review_reply_openai_error_message(resp: requests.Response) -> str:
    raw = _safe_err_text(resp)
    try:
        body = resp.json() or {}
    except Exception:
        body = {}
    err = body.get("error") if isinstance(body, dict) else {}
    if not isinstance(err, dict):
        err = {}
    param = str(err.get("param") or "").strip().lower()
    code = str(err.get("code") or "").strip().lower()
    message = str(err.get("message") or raw or "").strip()
    message_low = message.lower()
    if param == "max_tokens" or ("max_tokens" in message_low and ("unsupported" in code or "not supported" in message_low)):
        return (
            "OpenAI 모델 토큰 파라미터 호환 오류입니다. "
            "현재 서버는 자동 호환 재시도를 수행하지만, 선택한 모델이 chat completions 규격과 맞지 않으면 실패할 수 있습니다. "
            "권장 모델(gpt-4o-mini, gpt-4o, gpt-5.4, gpt-5.5)로 다시 시도해 주세요."
        )
    return f"OpenAI 실패({int(getattr(resp, 'status_code', 0) or 0)}) {raw}".strip()


def _today_kst() -> date:
    """
    "오늘"을 KST(Asia/Seoul) 기준으로 계산한다.
    - 프론트(UI)는 로컬(KST) 날짜를 기준으로 '오늘'을 표시/비교한다.
    - 서버가 UTC date.today()를 쓰면 자정 전후에 하루 어긋나 "수집이 안됨"처럼 보일 수 있다.
    """
    try:
        return datetime.now(ZoneInfo("Asia/Seoul")).date()
    except Exception:
        return date.today()
# 캠페인명 정규화/필터 확장
# ----------------------------
# SearchAd 데이터/메타 소스에 따라 캠페인명이 "#SA_..." 또는 "SA_..."처럼 선행 '#' 유무가 달라질 수 있다.
# 조회/필터 시 이 차이로 데이터가 누락되지 않도록, 입력 캠페인명을 variants(원문/선행#제거/선행#추가)로 확장해 매칭한다.
def _campaign_name_variants(name: str) -> set[str]:
    raw = str(name or "").strip()
    if not raw:
        return set()

    stripped = raw.lstrip("#").strip()
    vs: set[str] = set()
    if raw:
        vs.add(raw)
    if stripped:
        vs.add(stripped)
        vs.add(f"#{stripped}")
    return vs


def _expand_campaign_names(names: list[str] | tuple[str, ...] | set[str]) -> list[str]:
    out: set[str] = set()
    for n in names:
        out |= _campaign_name_variants(str(n or ""))
    return sorted(out)


def _campaign_base(name: str) -> str:
    return str(name or "").strip().lstrip("#").strip()


def _campaign_bases(names: set[str] | list[str] | tuple[str, ...]) -> list[str]:
    out: set[str] = set()
    for n in names:
        b = _campaign_base(str(n or ""))
        if b:
            out.add(b)
    return sorted(out)

