# ---- 카테고리 크롤링(job) 취소 플래그 ----
# - "멈춤" 버튼은 서버에 cancel을 요청하고, 크롤러는 키워드/페이지 단위로 이 플래그를 확인해 조기 종료한다.
CRAWL_CANCEL_LOCK = Lock()
CRAWL_CANCELLED_JOB_IDS: set[str] = set()


def _cancel_category_crawl_job(job_id: str) -> None:
    jid = str(job_id or "").strip()
    if not jid:
        return
    with CRAWL_CANCEL_LOCK:
        CRAWL_CANCELLED_JOB_IDS.add(jid)


def _is_category_crawl_cancelled(job_id: str) -> bool:
    jid = str(job_id or "").strip()
    if not jid:
        return False
    with CRAWL_CANCEL_LOCK:
        return jid in CRAWL_CANCELLED_JOB_IDS

