def _list_latest_review_reply_drafts(
    db: Session,
    *,
    status: str | None = None,
    product_url: str | None = None,
    limit: int = 50,
) -> list[ReviewReplyDraftListItem]:
    corpus_rows = _build_review_reply_style_corpus(db, limit=1500)
    status_priority = case(
        (ReviewReplyDraft.status == "approved", 0),
        (ReviewReplyDraft.status == "generated", 1),
        (ReviewReplyDraft.status == "rejected", 2),
        (ReviewReplyDraft.status == "failed", 3),
        (ReviewReplyDraft.status == "superseded", 4),
        else_=9,
    )
    q = db.query(ReviewReplyDraft).order_by(
        status_priority.asc(),
        ReviewReplyDraft.generated_at.desc(),
        ReviewReplyDraft.updated_at.desc(),
        ReviewReplyDraft.draft_id.desc(),
    )
    status0 = str(status or "").strip()
    if status0:
        q = q.filter(ReviewReplyDraft.status == status0)
    rows = q.limit(max(1, min(int(limit or 50) * 5, 1000))).all()

    out: list[ReviewReplyDraftListItem] = []
    seen_review_keys: set[str] = set()
    product_url0 = str(product_url or "").strip()
    for draft_row in rows:
        review_key = str(getattr(draft_row, "review_key", "") or "").strip()
        if not review_key or review_key in seen_review_keys:
            continue
        review_row: NaverReviewRaw | None = (
            db.query(NaverReviewRaw).filter(NaverReviewRaw.review_key == review_key).one_or_none()
        )
        if review_row is None:
            continue
        if product_url0 and str(getattr(review_row, "product_url", "") or "").strip() != product_url0:
            continue
        reply_row: NaverReviewReplyRaw | None = (
            db.query(NaverReviewReplyRaw).filter(NaverReviewReplyRaw.review_key == review_key).one_or_none()
        )
        style_context = _build_review_reply_style_context(
            db,
            review_row=review_row,
            corpus_rows=corpus_rows,
            style_level=int(getattr(draft_row, "style_level", None) or 3),
            style_controls=_parse_review_reply_style_controls(getattr(draft_row, "style_controls_json", None)),
        )
        style_similarity_score = estimate_style_similarity(
            getattr(draft_row, "draft_text", ""),
            (style_context or {}).get("style_profile") or {},
        )
        seen_review_keys.add(review_key)
        out.append(
            _to_review_reply_draft_list_item(
                draft_row,
                review_row=review_row,
                reply_text=(getattr(reply_row, "reply_text", None) if reply_row is not None else None),
                style_context=style_context,
                style_similarity_score=style_similarity_score,
            )
        )
        if len(out) >= max(1, min(int(limit or 50), 200)):
            break
    return out


def _list_review_reply_rejection_history(
    db: Session,
    *,
    product_url: str | None = None,
    date_from: date | None = None,
    date_to: date | None = None,
    rating_filters: list[str] | tuple[str, ...] | None = None,
    limit: int = 200,
) -> list[ReviewReplyDraftListItem]:
    corpus_rows = _build_review_reply_style_corpus(db, product_url=product_url, limit=1500)
    review_rows = (
        _apply_review_scope_filters(
            db.query(NaverReviewRaw),
            model_cls=NaverReviewRaw,
            product_url=product_url,
            date_from=date_from,
            date_to=date_to,
            rating_filters=rating_filters,
            exclude_incomplete_product_page_stubs=True,
        )
        .order_by(
            NaverReviewRaw.review_written_at.desc(),
            NaverReviewRaw.collected_at.desc(),
            NaverReviewRaw.review_key.desc(),
        )
        .all()
    )
    review_map = {
        str(getattr(row, "review_key", "") or "").strip(): row
        for row in review_rows
        if str(getattr(row, "review_key", "") or "").strip()
    }
    review_keys = list(review_map.keys())
    if not review_keys:
        return []
    draft_rows = (
        db.query(ReviewReplyDraft)
        .filter(
            ReviewReplyDraft.review_key.in_(review_keys),
            ReviewReplyDraft.status == "rejected",
            or_(
                ReviewReplyDraft.rejection_comment.isnot(None),
                ReviewReplyDraft.rejection_analysis_json.isnot(None),
            ),
        )
        .order_by(
            ReviewReplyDraft.generated_at.desc(),
            ReviewReplyDraft.updated_at.desc(),
            ReviewReplyDraft.draft_id.desc(),
        )
        .limit(max(1, min(int(limit or 200), 500)))
        .all()
    )
    reply_rows = (
        db.query(NaverReviewReplyRaw)
        .filter(NaverReviewReplyRaw.review_key.in_(review_keys))
        .all()
    )
    reply_map = {
        str(getattr(row, "review_key", "") or "").strip(): row
        for row in reply_rows
        if str(getattr(row, "review_key", "") or "").strip()
    }
    out: list[ReviewReplyDraftListItem] = []
    for draft_row in draft_rows:
        review_key = str(getattr(draft_row, "review_key", "") or "").strip()
        review_row = review_map.get(review_key)
        if review_row is None:
            continue
        reply_row = reply_map.get(review_key)
        style_context = _build_review_reply_style_context(
            db,
            review_row=review_row,
            corpus_rows=corpus_rows,
            style_level=int(getattr(draft_row, "style_level", None) or 3),
            style_controls=_parse_review_reply_style_controls(getattr(draft_row, "style_controls_json", None)),
        )
        style_similarity_score = estimate_style_similarity(
            getattr(draft_row, "draft_text", ""),
            (style_context or {}).get("style_profile") or {},
        )
        out.append(
            _to_review_reply_draft_list_item(
                draft_row,
                review_row=review_row,
                reply_text=(getattr(reply_row, "reply_text", None) if reply_row is not None else None),
                style_context=style_context,
                style_similarity_score=style_similarity_score,
            )
        )
    return out


