def _collection_table_date_expr(safe_table: str, safe_col: str) -> str:
    if safe_table == "tracked_product_manual_keyword" and safe_col == "updated_at":
        # Keyword volume is a KST current-state snapshot. The 04:20 KST schedule
        # writes UTC timestamps on the previous calendar date.
        return f"({safe_col} at time zone 'Asia/Seoul')::date"
    return f"{safe_col}::date"


class CollectionTaskSchedulePayload(BaseModel):
    enabled: bool | None = None
    schedule_enabled: bool | None = None
    schedule_time: str | None = None
    config: dict | None = None


class CollectionRunPayload(BaseModel):
    date: Optional[CollectionDate] = None
    date_from: Optional[CollectionDate] = None
    date_to: Optional[CollectionDate] = None
    mode: str | None = "manual"
    force: bool = False
    collector_device_id: str | None = None
    # ad_rank_diagnosis_cdp: 누락(missing) + 조회실패(failed) 셀만 재수집
    retry_incomplete: bool = False


def _collection_json_dumps(obj: object) -> str:
    return json.dumps(obj, ensure_ascii=False, default=str)


def _collection_json_loads(raw: object) -> object:
    if raw is None:
        return None
    try:
        return json.loads(str(raw or ""))
    except Exception:
        return None


def _collection_effective_target_date(payload: CollectionRunPayload | None = None) -> date:
    if payload and payload.date:
        return payload.date
    if payload and payload.date_from and not payload.date_to:
        return payload.date_from
    return _today_kst() - timedelta(days=1)


def _collection_effective_range(payload: CollectionRunPayload | None = None) -> tuple[date, date]:
    if payload and payload.date_from:
        d0 = payload.date_from
        d1 = payload.date_to or payload.date_from
        if d1 < d0:
            raise HTTPException(status_code=400, detail="date_to must be >= date_from")
        return d0, d1
    d = _collection_effective_target_date(payload)
    return d, d


def _collection_effective_target_for_task(task_id: str, payload: CollectionRunPayload | None = None) -> date:
    if task_id in TODAY_ONLY_SNAPSHOT_TASKS:
        # 순위/노출/상세 메트릭은 보고서류와 달리 현재 화면 기준 스냅샷이다.
        # 명시 날짜가 넘어와도 과거 화면을 재현할 수 없으므로 오늘 데이터로만 수집한다.
        return _today_kst()
    return _collection_effective_target_date(payload)


def _collection_effective_range_for_task(task_id: str, payload: CollectionRunPayload | None = None) -> tuple[date, date]:
    if task_id in TODAY_ONLY_SNAPSHOT_TASKS:
        target = _collection_effective_target_for_task(task_id, payload)
        return target, target
    return _collection_effective_range(payload)


def _collection_review_range_until_today(date_from: date, date_to: date) -> tuple[date, date]:
	today = _today_kst()
	start = date_from
	if start > today:
		start = today
	return start, today


def _gfa_ui_min_report_date(anchor: date | None = None) -> date:
    """
    Naver GFA report UI rejects start dates older than two years.
    Keep collector planning inside that browser-enforced window.
    """
    base = anchor or _today_kst()
    try:
        return base.replace(year=base.year - 2)
    except ValueError:
        # Feb 29 -> Feb 28 on non-leap years.
        return base.replace(year=base.year - 2, day=28)


def _gfa_clamp_report_range(date_from: date, date_to: date) -> tuple[date, date]:
    min_date = _gfa_ui_min_report_date(_today_kst())
    return max(date_from, min_date), date_to


def _collection_has_explicit_dates(payload: CollectionRunPayload | None = None) -> bool:
    return bool(payload and (payload.date or payload.date_from or payload.date_to))


def _collection_parse_date(v: object) -> date | None:
    if isinstance(v, date):
        return v
    s = str(v or "").strip()
    if not s:
        return None
    try:
        return date.fromisoformat(s[:10])
    except Exception:
        return None


def _collection_result_range(result: object, fallback_from: date, fallback_to: date) -> tuple[date, date]:
    if not isinstance(result, dict):
        return fallback_from, fallback_to
    processed_dates = result.get("processed_dates")
    if isinstance(processed_dates, list):
        dates = [_collection_parse_date(v) for v in processed_dates]
        dates = [d for d in dates if d is not None]
        if dates:
            return min(dates), max(dates)
    d0 = _collection_parse_date(result.get("date_from"))
    d1 = _collection_parse_date(result.get("date_to"))
    if d0:
        return d0, d1 or d0
    d = _collection_parse_date(result.get("date"))
    if d:
        return d, d
    nested = result.get("result")
    if isinstance(nested, dict):
        return _collection_result_range(nested, fallback_from, fallback_to)
    return fallback_from, fallback_to


def _collection_task_config(db: Session, task_id: str) -> CollectionTaskConfig:
    meta = COLLECTION_TASK_REGISTRY.get(task_id)
    if not meta:
        raise HTTPException(status_code=404, detail="collection task not found")
    row = db.query(CollectionTaskConfig).filter(CollectionTaskConfig.task_id == task_id).one_or_none()
    if row is None:
        row = CollectionTaskConfig(
            task_id=task_id,
            label=str(meta["label"]),
            domain=str(meta["domain"]),
            source_type=str(meta["source_type"]),
            provider=str(meta.get("provider") or ""),
            target_tables_json=_collection_json_dumps(meta.get("target_tables") or []),
            enabled=True,
            schedule_enabled=bool(meta.get("default_schedule_enabled", False)),
            schedule_time=meta.get("default_schedule_time"),
            freshness_days=int(meta.get("freshness_days") or 0),
            config_json=_collection_json_dumps({}),
        )
        db.add(row)
        db.commit()
        db.refresh(row)
    else:
        changed = False
        desired_tables = _collection_json_dumps(meta.get("target_tables") or [])
        for attr, value in (
            ("label", str(meta["label"])),
            ("domain", str(meta["domain"])),
            ("source_type", str(meta["source_type"])),
            ("provider", str(meta.get("provider") or "")),
            ("target_tables_json", desired_tables),
            ("freshness_days", int(meta.get("freshness_days") or 0)),
        ):
            if getattr(row, attr) != value:
                setattr(row, attr, value)
                changed = True
        if not row.schedule_time and meta.get("default_schedule_time"):
            row.schedule_time = meta.get("default_schedule_time")
            changed = True
        if changed:
            db.commit()
            db.refresh(row)
    return row


def _collection_serialize_job(row: CollectionJobRun | None) -> dict | None:
    if row is None:
        return None
    return {
        "job_id": row.job_id,
        "task_id": row.task_id,
        "run_mode": row.run_mode,
        "source_type": row.source_type,
        "status": row.status,
        "target_date": row.target_date.isoformat() if row.target_date else None,
        "date_from": row.date_from.isoformat() if row.date_from else None,
        "date_to": row.date_to.isoformat() if row.date_to else None,
        "rows_written": row.rows_written,
        "detail": _collection_json_loads(row.detail_json),
        "error": row.error,
        "started_at": row.started_at.isoformat() if row.started_at else None,
        "finished_at": row.finished_at.isoformat() if row.finished_at else None,
    }


def _collection_serialize_ad_rank_job_with_current_persistence(db: Session, row: CollectionJobRun | None) -> dict | None:
    out = _collection_serialize_job(row)
    if not out:
        return out
    detail = out.get("detail")
    if not isinstance(detail, dict):
        detail = {}
        out["detail"] = detail
    # 광고 상품 순위는 과거 리포트가 아니라 현재 노출진단 화면의 today-only
    # 스냅샷이다. 과거 target_date로 생성된 작업 이력이 있어도 UI 완료 판정은
    # 오늘 저장된 row 기준으로 해야 "오늘 수집 필요" 오탐이 나지 않는다.
    target = _today_kst()
    persisted = _collection_persistence_summary(db, "ad_rank_diagnosis_cdp", target, target)
    detail["db_persistence"] = persisted
    out["target_date"] = target.isoformat()
    out["date_from"] = target.isoformat()
    out["date_to"] = target.isoformat()
    status0 = str(out.get("status") or "").strip().upper()
    if status0 in {"SUCCESS", "PARTIAL"}:
        refreshed_status, refreshed_error = _collection_apply_persistence_status(
            "ad_rank_diagnosis_cdp",
            status0,
            int(out.get("rows_written") or 0),
            persisted,
        )
        out["status"] = refreshed_status
        out["error"] = refreshed_error
    return out


def _collection_serialize_task(db: Session, task_id: str, include_pending: bool = True) -> dict:
    meta = COLLECTION_TASK_REGISTRY[task_id]
    cfg = _collection_task_config(db, task_id)
    source_type = str(cfg.source_type or "")
    preferred_runtime = meta.get("preferred_runtime")
    if not preferred_runtime:
        preferred_runtime = "collector_pc" if source_type == "host_cdp" else "nas" if source_type in {"server_api", "server_batch"} else "web_manual"
    today_start_utc = datetime.combine(_today_kst(), datetime.min.time()) - timedelta(hours=9)
    # Overnight Host Agent CDP jobs may still be CLAIMED after KST midnight; surface them
    # so the UI does not look idle while collection continues.
    active_overnight = _collection_find_active_job(db, task_id)
    latest = (
        db.query(CollectionJobRun)
        .filter(CollectionJobRun.task_id == task_id)
        .filter(CollectionJobRun.started_at >= today_start_utc)
        .order_by(CollectionJobRun.started_at.desc())
        .first()
    )
    if active_overnight is not None and (
        latest is None
        or str(getattr(latest, "status", "") or "").upper()
        not in {"QUEUED", "STARTED", "CLAIMED", "UPLOADING", "WAITING_USER"}
        or (getattr(active_overnight, "started_at", None) or datetime.min)
        >= (getattr(latest, "started_at", None) or datetime.min)
    ):
        latest = active_overnight
    latest_success = (
        db.query(CollectionJobRun)
        .filter(CollectionJobRun.task_id == task_id)
        .filter(CollectionJobRun.started_at >= today_start_utc)
        .filter(CollectionJobRun.status == "SUCCESS")
        .order_by(CollectionJobRun.finished_at.desc().nullslast(), CollectionJobRun.started_at.desc())
        .first()
    )
    if task_id == "ad_rank_diagnosis_cdp":
        latest_job = _collection_serialize_ad_rank_job_with_current_persistence(db, latest)
        latest_success_job = _collection_serialize_ad_rank_job_with_current_persistence(db, latest_success)
    else:
        latest_job = _collection_serialize_job(latest) if latest else None
        latest_success_job = _collection_serialize_job(latest_success) if latest_success else None
    return {
        "task_id": task_id,
        "label": cfg.label,
        "domain": cfg.domain,
        "source_type": cfg.source_type,
        "provider": cfg.provider,
        "preferred_runtime": preferred_runtime,
        "fallback_runtime": meta.get("fallback_runtime"),
        "requires_installed_collector": bool(source_type == "host_cdp" or meta.get("requires_installed_collector")),
        "target_tables": _collection_json_loads(cfg.target_tables_json) or list(meta.get("target_tables") or []),
        "enabled": bool(cfg.enabled),
        "schedule_enabled": bool(cfg.schedule_enabled),
        "schedule_time": cfg.schedule_time,
        "freshness_days": int(cfg.freshness_days or 0),
        "description": meta.get("description") or "",
        "runnable": bool(meta.get("runnable")),
        "supports_retry_incomplete": bool(meta.get("supports_retry_incomplete")),
        "latest_job": latest_job,
        "latest_success_job": latest_success_job,
        "pending_collection": _collection_pending_summary(db, task_id) if include_pending else None,
    }


def _collection_job_should_survive_daily_reset(row: CollectionJobRun) -> bool:
    """
    Host Agent가 이미 CLAIMED/UPLOADING 중인 CDP 수집은 자정을 넘어가도 유지한다.
    (shopping_rank_cdp 등 장시간 작업이 daily_reset으로 끊기면 당일 데이터가 비게 된다)
    """
    status = str(getattr(row, "status", "") or "").strip().upper()
    if status not in {"CLAIMED", "UPLOADING", "WAITING_USER"}:
        return False
    return _collection_job_awaits_collector_pc(row)


def _collection_find_active_job(db: Session, task_id: str) -> CollectionJobRun | None:
    return (
        db.query(CollectionJobRun)
        .filter(CollectionJobRun.task_id == task_id)
        .filter(CollectionJobRun.status.in_(["QUEUED", "STARTED", "CLAIMED", "UPLOADING", "WAITING_USER"]))
        .filter(CollectionJobRun.finished_at.is_(None))
        .order_by(CollectionJobRun.started_at.desc())
        .first()
    )


def _collection_reset_stale_daily_jobs(db: Session, *, now_kst: datetime) -> int:
    """
    00:00(KST) 이후에는 전날의 실패/진행중 수집 상태가 오늘 UI/스케줄을 막지 않도록 정리한다.
    이력은 유지하되, 미종료 job은 terminal 상태로 닫고 최신 작업 표시는 오늘 작업만 보게 한다.
    단, Host Agent가 이미 수행 중인 CDP CLAIMED/UPLOADING/WAITING_USER job은 유지한다.
    """
    today_start_utc = datetime.combine(now_kst.date(), datetime.min.time()) - timedelta(hours=9)
    stale_rows = (
        db.query(CollectionJobRun)
        .filter(CollectionJobRun.started_at < today_start_utc)
        .filter(CollectionJobRun.status.in_(["QUEUED", "STARTED", "CLAIMED", "UPLOADING", "WAITING_USER"]))
        .all()
    )
    updated = 0
    reset_collector_job_ids: set[str] = set()
    for row in stale_rows:
        if _collection_job_should_survive_daily_reset(row):
            continue
        detail = _collection_json_loads(row.detail_json) or {}
        if not isinstance(detail, dict):
            detail = {"detail": detail}
        collector_job = detail.get("collector_job")
        if isinstance(collector_job, dict):
            collector_job_id = str(collector_job.get("job_id") or "").strip()
            if collector_job_id:
                reset_collector_job_ids.add(collector_job_id)
            collector_job["status"] = "CANCELLED"
            collector_job["error"] = "daily_reset"
            collector_job["updated_at"] = now_kst.isoformat()
        detail["daily_reset"] = True
        detail["daily_reset_at"] = now_kst.isoformat()
        detail["message"] = "Previous-day unfinished collection job was reset at KST day boundary."
        row.status = "CANCELLED"
        row.error = "daily_reset"
        row.finished_at = datetime.utcnow()
        row.detail_json = _collection_json_dumps(detail)
        db.add(row)
        updated += 1
    if updated:
        db.commit()
    if reset_collector_job_ids:
        with PAGE_METRICS_COLLECTOR_JOB_LOCK:
            for collector_job_id in reset_collector_job_ids:
                job = PAGE_METRICS_COLLECTOR_JOBS.get(collector_job_id)
                if not job:
                    continue
                job["status"] = "CANCELLED"
                job["error"] = "daily_reset"
                job["updated_at"] = now_kst.isoformat()
                PAGE_METRICS_COLLECTOR_JOBS.pop(collector_job_id, None)
    return updated


def _collection_event(db: Session, *, job: CollectionJobRun, level: str, message: str, status: str | None = None, detail: object | None = None) -> None:
    db.add(
        CollectionJobEvent(
            job_id=job.job_id,
            task_id=job.task_id,
            level=level,
            status=status,
            message=message,
            detail_json=_collection_json_dumps(detail) if detail is not None else None,
        )
    )
    db.commit()


def _collection_count_rows_for_date(db: Session, table_name: str, target_date: date) -> int:
    safe_table = str(table_name or "").strip()
    if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_table):
        return 0
    try:
        return int(db.execute(text(f"select count(*) from {safe_table} where date = :d"), {"d": target_date}).scalar() or 0)
    except Exception:
        return 0


def _collection_today_clone_missing_dates(db: Session, *, primary_table: str, source_date: date, max_days: int = TODAY_CLONE_BACKFILL_MAX_DAYS) -> list[date]:
    if _collection_count_rows_for_date(db, primary_table, source_date) <= 0:
        return []
    missing: list[date] = []
    cur = source_date - timedelta(days=1)
    for _ in range(max(1, int(max_days or TODAY_CLONE_BACKFILL_MAX_DAYS))):
        if _collection_count_rows_for_date(db, primary_table, cur) > 0:
            break
        missing.append(cur)
        cur = cur - timedelta(days=1)
    missing.reverse()
    return missing


def _collection_count_page_metric_rows_for_date(db: Session, target_date: date) -> int:
    try:
        return int(
            db.execute(
                text(
                    "select count(*) from tracked_product_page_daily "
                    "where date = :d and rating is not null and review_count is not null"
                ),
                {"d": target_date},
            ).scalar()
            or 0
        )
    except Exception:
        return 0


def _collection_page_metrics_missing_metric_dates(
    db: Session,
    *,
    source_date: date,
    max_days: int = PAGE_METRICS_CLONE_BACKFILL_MAX_DAYS,
) -> list[date]:
    if _collection_count_page_metric_rows_for_date(db, source_date) <= 0:
        return []
    missing: list[date] = []
    cur = source_date - timedelta(days=1)
    for _ in range(max(1, int(max_days or PAGE_METRICS_CLONE_BACKFILL_MAX_DAYS))):
        if _collection_count_page_metric_rows_for_date(db, cur) > 0:
            break
        missing.append(cur)
        cur = cur - timedelta(days=1)
    missing.reverse()
    return missing


def _collection_clone_rank_openapi_today_rows(db: Session, *, source_date: date, target_date: date) -> int:
    result = db.execute(
        text(
            """
            insert into tracked_product_rank_daily (date, product_url, keyword, rank, source, created_at, updated_at)
            select :target_date, product_url, keyword, rank, source, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
            from tracked_product_rank_daily
            where date = :source_date
            on conflict (date, product_url, keyword) do nothing
            """
        ),
        {"source_date": source_date, "target_date": target_date},
    )
    return int(getattr(result, "rowcount", 0) or 0)


