def _collection_clone_page_metrics_today_rows(db: Session, *, source_date: date, target_date: date) -> dict[str, int]:
    page_result = db.execute(
        text(
            """
            insert into tracked_product_page_daily (
                date, product_url, title, price, review_count, rating, delivery, buy_count,
                wish_count, registered_date, recent_purchase_count, recent_purchase_window,
                recent_purchase_status, recent_purchase_7d_count, recent_repurchase_count,
                recent_repurchase_window, recent_repurchase_3m_count, recent_badge_text,
                http_status, error, created_at
            )
            select
                :target_date, product_url, title, price, review_count, rating, delivery, buy_count,
                wish_count, registered_date, recent_purchase_count, recent_purchase_window,
                recent_purchase_status, recent_purchase_7d_count, recent_repurchase_count,
                recent_repurchase_window, recent_repurchase_3m_count, recent_badge_text,
                http_status, error, CURRENT_TIMESTAMP
            from tracked_product_page_daily
            where date = :source_date
            on conflict (date, product_url) do update set
                title = coalesce(tracked_product_page_daily.title, excluded.title),
                price = coalesce(tracked_product_page_daily.price, excluded.price),
                review_count = coalesce(tracked_product_page_daily.review_count, excluded.review_count),
                rating = coalesce(tracked_product_page_daily.rating, excluded.rating),
                delivery = coalesce(tracked_product_page_daily.delivery, excluded.delivery),
                buy_count = coalesce(tracked_product_page_daily.buy_count, excluded.buy_count),
                wish_count = coalesce(tracked_product_page_daily.wish_count, excluded.wish_count),
                registered_date = coalesce(tracked_product_page_daily.registered_date, excluded.registered_date)
            where tracked_product_page_daily.rating is null
               or tracked_product_page_daily.review_count is null
               or tracked_product_page_daily.price is null
            """
        ),
        {"source_date": source_date, "target_date": target_date},
    )
    review_result = db.execute(
        text(
            """
            insert into naver_product_review_daily (
                date, keyword, product_id, product_title, mall_name, rating_avg, rating_count,
                rating_1_cnt, rating_2_cnt, rating_3_cnt, rating_4_cnt, rating_5_cnt, created_at
            )
            select
                :target_date, keyword, product_id, product_title, mall_name, rating_avg, rating_count,
                rating_1_cnt, rating_2_cnt, rating_3_cnt, rating_4_cnt, rating_5_cnt, CURRENT_TIMESTAMP
            from naver_product_review_daily
            where date = :source_date
            on conflict (date, keyword, product_id) do nothing
            """
        ),
        {"source_date": source_date, "target_date": target_date},
    )
    return {
        "tracked_product_page_daily": int(getattr(page_result, "rowcount", 0) or 0),
        "naver_product_review_daily": int(getattr(review_result, "rowcount", 0) or 0),
    }


def _collection_clone_today_snapshot_backfill(db: Session, *, task_id: str, source_date: date) -> dict | None:
    if task_id not in TODAY_CLONE_BACKFILL_TASKS:
        return None
    today = _today_kst()
    if source_date != today:
        return {"skipped": True, "reason": "source_date_is_not_today", "source_date": source_date.isoformat(), "today": today.isoformat()}
    primary_table = {
        "rank_openapi": "tracked_product_rank_daily",
        "ad_rank_diagnosis_cdp": "ad_rank_diagnosis_daily",
        "page_metrics_cdp": "tracked_product_page_daily",
    }.get(task_id)
    if not primary_table:
        return None
    if task_id == "page_metrics_cdp":
        if _collection_count_page_metric_rows_for_date(db, source_date) <= 0:
            return {
                "skipped": True,
                "reason": "source_has_no_review_metrics",
                "source_date": source_date.isoformat(),
                "primary_table": primary_table,
            }
        missing_dates = _collection_page_metrics_missing_metric_dates(db, source_date=source_date)
    else:
        missing_dates = _collection_today_clone_missing_dates(db, primary_table=primary_table, source_date=source_date)
    if not missing_dates:
        return {
            "skipped": True,
            "reason": "no_contiguous_missing_dates_before_today",
            "source_date": source_date.isoformat(),
            "primary_table": primary_table,
        }
    rows_by_date: dict[str, object] = {}
    total_rows = 0
    for d in missing_dates:
        if task_id == "rank_openapi":
            rows = _collection_clone_rank_openapi_today_rows(db, source_date=source_date, target_date=d)
            rows_by_date[d.isoformat()] = rows
            total_rows += rows
        elif task_id == "ad_rank_diagnosis_cdp":
            rows = _collection_clone_ad_rank_today_rows(db, source_date=source_date, target_date=d)
            rows_by_date[d.isoformat()] = rows
            total_rows += rows
        elif task_id == "page_metrics_cdp":
            rows_map = _collection_clone_page_metrics_today_rows(db, source_date=source_date, target_date=d)
            rows_by_date[d.isoformat()] = rows_map
            total_rows += int(rows_map.get("tracked_product_page_daily") or 0)
    db.commit()
    return {
        "ok": True,
        "policy": "today_snapshot_clone_to_contiguous_missing_previous_dates",
        "source_date": source_date.isoformat(),
        "primary_table": primary_table,
        "filled_dates": [d.isoformat() for d in missing_dates],
        "filled_date_count": len(missing_dates),
        "rows_written": total_rows,
        "rows_by_date": rows_by_date,
    }


def _collection_finish_job(db: Session, job: CollectionJobRun, *, status: str, rows_written: int | None = None, detail: object | None = None, error: str | None = None) -> CollectionJobRun:
    status0 = str(status or "").strip().upper() or status
    detail_obj = dict(detail or {}) if isinstance(detail, dict) else ({"result": detail} if detail is not None else None)
    if status0 in {"SUCCESS", "PARTIAL"} and job.task_id in TODAY_CLONE_BACKFILL_TASKS:
        try:
            # Current-state snapshots can be executed from stale retry jobs. Their
            # stored/backfill source must be today's snapshot, not the old job date.
            source_date = _today_kst()
            backfill = _collection_clone_today_snapshot_backfill(db, task_id=job.task_id, source_date=source_date)
            if backfill is not None:
                if detail_obj is None:
                    detail_obj = {}
                detail_obj["today_clone_backfill"] = backfill
        except Exception as exc:
            if detail_obj is None:
                detail_obj = {}
            detail_obj["today_clone_backfill"] = {"ok": False, "error": f"{type(exc).__name__}: {exc}"}
            db.rollback()
    job.status = status0
    job.rows_written = rows_written
    job.detail_json = _collection_json_dumps(detail_obj or {}) if detail_obj is not None else job.detail_json
    job.error = error
    # Collector PC jobs are returned as QUEUED while the host worker is still
    # expected to claim and finish them. Marking them finished here creates
    # orphan CLAIMED rows that are rehydrated forever after refresh/restart.
    if status0 in {"QUEUED", "STARTED", "CLAIMED", "UPLOADING", "WAITING_USER"}:
        job.finished_at = None
    else:
        job.finished_at = datetime.utcnow()
    db.add(job)
    db.commit()
    db.refresh(job)
    return job


def _collection_create_job(db: Session, *, task_id: str, payload: CollectionRunPayload, source_type: str, run_mode: str) -> CollectionJobRun:
    date_from, date_to = _collection_effective_range_for_task(task_id, payload)
    job = CollectionJobRun(
        job_id=str(uuid.uuid4()),
        task_id=task_id,
        run_mode=run_mode,
        source_type=source_type,
        status="STARTED",
        target_date=_collection_effective_target_for_task(task_id, payload),
        date_from=date_from,
        date_to=date_to,
        detail_json=_collection_json_dumps({"request": payload.model_dump(mode="json")}),
    )
    db.add(job)
    db.commit()
    db.refresh(job)
    _collection_event(db, job=job, level="INFO", status="STARTED", message="collection job started")
    return job


def _collection_table_coverage(db: Session, table_name: str, date_col: str = "date") -> dict:
    safe_table = str(table_name or "").strip()
    safe_col = str(date_col or "").strip()
    if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_table) or not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_col):
        return {"table": table_name, "rows": 0}
    try:
        row = db.execute(
            text(f"select count(*)::bigint as rows, min({safe_col})::text as min_date, max({safe_col})::text as max_date from {safe_table}")
        ).mappings().first()
        return {"table": table_name, "rows": int((row or {}).get("rows") or 0), "min_date": (row or {}).get("min_date"), "max_date": (row or {}).get("max_date")}
    except Exception as e:
        return {"table": table_name, "rows": 0, "error": str(e)}


def _collection_table_max_date(db: Session, table_name: str) -> date | None:
    safe_table = str(table_name or "").strip()
    safe_col = str(COLLECTION_TABLE_DATE_COLUMNS.get(safe_table) or "").strip()
    if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_table) or not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_col):
        return None
    try:
        v = db.execute(text(f"select max({safe_col}::date) from {safe_table}")).scalar()
        return _collection_parse_date(v)
    except Exception:
        return None


def _collection_table_min_date(db: Session, table_name: str) -> date | None:
    safe_table = str(table_name or "").strip()
    safe_col = str(COLLECTION_TABLE_DATE_COLUMNS.get(safe_table) or "").strip()
    if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_table) or not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_col):
        return None
    try:
        date_expr = _collection_table_date_expr(safe_table, safe_col)
        v = db.execute(text(f"select min({date_expr}) from {safe_table}")).scalar()
        return _collection_parse_date(v)
    except Exception:
        return None


def _collection_table_source_filter(task_id: str, table_name: str) -> str | None:
    if task_id == "ads_daily" and table_name in ADS_KIND_TABLES.values():
        return "searchad_api"
    return None


def _collection_pending_summary(db: Session, task_id: str) -> dict:
    meta = COLLECTION_TASK_REGISTRY.get(task_id) or {}
    if task_id in TODAY_ONLY_SNAPSHOT_TASKS:
        # Snapshot collectors capture the current state only. Showing historical
        # calendar gaps here is misleading because the run path intentionally
        # does not backfill old dates for these tasks.
        target = _today_kst()
        scan_from = target
    else:
        target = _today_kst() - timedelta(days=1)
        scan_from = max(target - timedelta(days=GFA_PENDING_LOOKBACK_DAYS - 1), _gfa_ui_min_report_date(_today_kst())) if task_id == "gfa_performance_daily" else target - timedelta(days=119)
    pending: set[date] = set()
    by_table: dict[str, list[str]] = {}
    gfa_missing_units_by_date: dict[date, set[str]] | None = None
    for table_name in list(meta.get("target_tables") or []):
        table = str(table_name or "").strip()
        if table not in COLLECTION_TABLE_DATE_COLUMNS:
            continue
        if task_id == "page_metrics_cdp" and table != "tracked_product_page_daily":
            # `naver_product_review_daily` is a derived mirror maintained by a
            # separate backfill task. Page metrics readiness must be judged by
            # the primary fact table only.
            continue
        source_filter = _collection_table_source_filter(task_id, table)
        source_filters = (
            PURCHASE_KEYWORD_COMPLETE_SOURCES
            if task_id == "purchase_keywords" and table == "naver_smartstore_purchase_keyword_daily"
            else ADS_SEARCHWORD_COMPLETE_SOURCES
            if task_id == "ads_searchword_daily" and table == "naver_ad_searchword_daily"
            else ADS_CREATIVE_COMPLETE_SOURCES
            if task_id == "ads_creative_report_daily" and table == "naver_ad_creative_daily"
            else None
        )
        min_date = _collection_table_min_date(db, table)
        d0 = scan_from if task_id == "gfa_performance_daily" else max(scan_from, min_date) if min_date else scan_from
        if task_id == "gfa_performance_daily" and table == "naver_gfa_performance_daily":
            gfa_missing_units_by_date = _collection_gfa_performance_missing_units(db, d0, target, require_payload=True)
            missing = sorted(gfa_missing_units_by_date.keys())
        else:
            missing = _collection_table_missing_dates(db, table, d0, target, source=source_filter, sources=source_filters)
        if missing:
            by_table[table] = [d.isoformat() for d in missing]
            pending.update(missing)
    segments = _collection_contiguous_date_segments(sorted(pending))
    out = {
        "date_from": scan_from.isoformat(),
        "date_to": target.isoformat(),
        "missing_date_count": len(pending),
        "missing_dates_by_table": by_table,
        "missing_segments": [[a.isoformat(), b.isoformat()] for a, b in segments],
        "has_pending": bool(pending),
    }
    if task_id == "gfa_performance_daily" and gfa_missing_units_by_date is not None:
        out["lookback_days"] = GFA_PENDING_LOOKBACK_DAYS
        out["missing_units_by_date"] = {
            d.isoformat(): sorted(units)
            for d, units in sorted(gfa_missing_units_by_date.items(), key=lambda x: x[0])
        }
        out["missing_unit_summary"] = _collection_gfa_missing_unit_summary(gfa_missing_units_by_date)
        out["non_operating_unit_summary"] = _collection_gfa_non_operating_unit_summary(db)
    if task_id == "rank_openapi":
        try:
            rank_summary = _rank_openapi_completion_summary(db, target)
            out.update(rank_summary)
            if int(rank_summary.get("missing_keyword_count") or 0) > 0 or int(rank_summary.get("incomplete_product_count") or 0) > 0:
                out["has_pending"] = True
        except Exception as exc:
            out["rank_completion_error"] = f"{type(exc).__name__}: {exc}"
    return out


def _collection_table_rows_for_range(db: Session, table_name: str, d0: date, d1: date, *, source: str | None = None, sources: tuple[str, ...] | None = None) -> int:
    safe_table = str(table_name or "").strip()
    safe_col = str(COLLECTION_TABLE_DATE_COLUMNS.get(safe_table) or "").strip()
    if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_table) or not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_col):
        return 0
    try:
        source_clause = " and source = :source" if source else " and source = any(:sources)" if sources else ""
        params: dict[str, object] = {"d0": d0, "d1": d1}
        if source:
            params["source"] = source
        if sources:
            params["sources"] = list(sources)
        date_expr = _collection_table_date_expr(safe_table, safe_col)
        return int(
            db.execute(
                text(f"select count(*) from {safe_table} where {date_expr} between :d0 and :d1{source_clause}"),
                params,
            ).scalar()
            or 0
        )
    except Exception:
        return 0


def _collection_table_missing_dates(db: Session, table_name: str, d0: date, d1: date, *, source: str | None = None, sources: tuple[str, ...] | None = None) -> list[date]:
    safe_table = str(table_name or "").strip()
    safe_col = str(COLLECTION_TABLE_DATE_COLUMNS.get(safe_table) or "").strip()
    if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_table) or not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", safe_col):
        return []
    try:
        source_clause = " and source = :source" if source else " and source = any(:sources)" if sources else ""
        params: dict[str, object] = {"d0": d0, "d1": d1}
        if source:
            params["source"] = source
        if sources:
            params["sources"] = list(sources)
        date_expr = _collection_table_date_expr(safe_table, safe_col)
        rows = db.execute(
            text(
                f"""
                select {date_expr} as d, count(*)::bigint as rows
                from {safe_table}
                where {date_expr} between :d0 and :d1{source_clause}
                group by {date_expr}
                """
            ),
            params,
        ).mappings().all()
        counts = {_collection_parse_date(r.get("d")): int(r.get("rows") or 0) for r in rows}
        out: list[date] = []
        cur = d0
        while cur <= d1:
            if int(counts.get(cur) or 0) <= 0:
                out.append(cur)
            cur = cur + timedelta(days=1)
        return out
    except Exception:
        return []


GFA_CONVERSION_COMPLETE_SOURCE = "gfa_report_upload_conversion"
GFA_CONVERSION_COMPLETE_SOURCE_CREATIVE = "gfa_report_upload_conversion_creative"
GFA_CONVERSION_COMPLETE_SOURCE_CAMPAIGN = "gfa_report_upload_conversion_campaign"
GFA_CONVERSION_COMPLETE_SOURCE_ASSET_GROUP = "gfa_report_upload_conversion_asset_group"
GFA_CONVERSION_COMPLETE_SOURCES = (
    GFA_CONVERSION_COMPLETE_SOURCE,
    GFA_CONVERSION_COMPLETE_SOURCE_CREATIVE,
    GFA_CONVERSION_COMPLETE_SOURCE_CAMPAIGN,
    GFA_CONVERSION_COMPLETE_SOURCE_ASSET_GROUP,
)
GFA_REPORT_REQUIRED_UNITS = ("CREATIVE", "CAMPAIGN", "ASSET_GROUP")
GFA_PENDING_LOOKBACK_DAYS = 90


def _gfa_source_to_unit(source: object) -> str | None:
    s = str(source or "").strip()
    if s in {GFA_CONVERSION_COMPLETE_SOURCE, GFA_CONVERSION_COMPLETE_SOURCE_CREATIVE}:
        return "CREATIVE"
    if s == GFA_CONVERSION_COMPLETE_SOURCE_CAMPAIGN:
        return "CAMPAIGN"
    if s == GFA_CONVERSION_COMPLETE_SOURCE_ASSET_GROUP:
        return "ASSET_GROUP"
    return None


def _collection_gfa_performance_missing_units(
    db: Session,
    d0: date,
    d1: date,
    *,
    require_payload: bool = False,
) -> dict[date, set[str]]:
    completion_clause = """
              and campaign_id <> '__no_data__'
              and raw_payload_json is not null
              and btrim(raw_payload_json) not in ('', '{}')
    """ if require_payload else ""
    rows = db.execute(
        text(
            f"""
            select date::date as d, source
            from naver_gfa_performance_daily
            where date::date between :d0 and :d1
              and source = any(:sources)
              {completion_clause}
            group by date::date, source
            """
        ),
        {"d0": d0, "d1": d1, "sources": list(GFA_CONVERSION_COMPLETE_SOURCES)},
    ).mappings().all()
    completed: dict[date, set[str]] = {}
    for r in rows:
        d = _collection_parse_date(r.get("d"))
        unit = _gfa_source_to_unit(r.get("source"))
        if d is not None and unit:
            completed.setdefault(d, set()).add(unit)
    coverage = _collection_gfa_unit_raw_coverage(db)
    coverage_starts = [item.get("min_date") for item in coverage.values() if isinstance(item.get("min_date"), date)]
    reference_from = min(coverage_starts) if coverage_starts else None
    out: dict[date, set[str]] = {}
    cur = d0
    while cur <= d1:
        required = set(GFA_REPORT_REQUIRED_UNITS)
        if isinstance(reference_from, date):
            for unit in GFA_REPORT_REQUIRED_UNITS:
                item = coverage.get(unit) or {}
                min_date = item.get("min_date")
                if isinstance(min_date, date) and min_date > reference_from and cur < min_date:
                    required.discard(unit)
        missing = required - completed.get(cur, set())
        if missing:
            out[cur] = missing
        cur = cur + timedelta(days=1)
    return out


def _collection_gfa_missing_unit_summary(missing_units_by_date: dict[date, set[str]]) -> dict:
    by_unit: dict[str, list[date]] = {unit: [] for unit in GFA_REPORT_REQUIRED_UNITS}
    for d, units in missing_units_by_date.items():
        for unit in units:
            if unit in by_unit:
                by_unit[unit].append(d)
    out: dict[str, dict] = {}
    for unit, dates in by_unit.items():
        sorted_dates = sorted(set(dates))
        segments = _collection_contiguous_date_segments(sorted_dates)
        out[unit] = {
            "missing_date_count": len(sorted_dates),
            "missing_segments": [[a.isoformat(), b.isoformat()] for a, b in segments],
        }
    return out


def _collection_gfa_unit_raw_coverage(db: Session) -> dict[str, dict[str, date | int | None]]:
    rows = db.execute(
        text(
            """
            select source,
                   min(date::date) filter (
                     where campaign_id <> '__no_data__'
                       and raw_payload_json is not null
                       and btrim(raw_payload_json) not in ('', '{}')
                   ) as min_date,
                   max(date::date) filter (
                     where campaign_id <> '__no_data__'
                       and raw_payload_json is not null
                       and btrim(raw_payload_json) not in ('', '{}')
                   ) as max_date,
                   count(distinct date::date) filter (
                     where campaign_id <> '__no_data__'
                       and raw_payload_json is not null
                       and btrim(raw_payload_json) not in ('', '{}')
                   ) as day_count
            from naver_gfa_performance_daily
            where source = any(:sources)
            group by source
            """
        ),
        {"sources": list(GFA_CONVERSION_COMPLETE_SOURCES)},
    ).mappings().all()
    out: dict[str, dict[str, date | int | None]] = {
        unit: {"min_date": None, "max_date": None, "day_count": 0}
        for unit in GFA_REPORT_REQUIRED_UNITS
    }
    for r in rows:
        unit = _gfa_source_to_unit(r.get("source"))
        if not unit:
            continue
        out[unit] = {
            "min_date": _collection_parse_date(r.get("min_date")),
            "max_date": _collection_parse_date(r.get("max_date")),
            "day_count": int(r.get("day_count") or 0),
        }
    return out


def _collection_gfa_non_operating_unit_summary(db: Session) -> dict:
    coverage = _collection_gfa_unit_raw_coverage(db)
    coverage_starts = [item.get("min_date") for item in coverage.values() if isinstance(item.get("min_date"), date)]
    reference_from = min(coverage_starts) if coverage_starts else None
    out: dict[str, dict] = {}
    for unit in GFA_REPORT_REQUIRED_UNITS:
        item = coverage.get(unit) or {}
        min_date = item.get("min_date")
        max_date = item.get("max_date")
        day_count = int(item.get("day_count") or 0)
        entry: dict[str, object] = {
            "raw_date_from": min_date.isoformat() if isinstance(min_date, date) else None,
            "raw_date_to": max_date.isoformat() if isinstance(max_date, date) else None,
            "raw_day_count": day_count,
        }
        if isinstance(reference_from, date) and isinstance(min_date, date) and min_date > reference_from:
            hist_to = min_date - timedelta(days=1)
            hist_dates: list[date] = []
            cur = reference_from
            while cur <= hist_to:
                hist_dates.append(cur)
                cur += timedelta(days=1)
            segments = _collection_contiguous_date_segments(hist_dates)
            entry.update(
                {
                    "non_operating_date_count": len(hist_dates),
                    "non_operating_segments": [[a.isoformat(), b.isoformat()] for a, b in segments],
                    "reason": "advoost_not_operating",
                }
            )
        else:
            entry.update(
                {
                    "non_operating_date_count": 0,
                    "non_operating_segments": [],
                    "reason": None,
                }
            )
        out[unit] = entry
    return {
        "service_name": "ADVoost",
        "reference_from": reference_from.isoformat() if isinstance(reference_from, date) else None,
        "units": out,
    }


def _collection_gfa_performance_missing_dates(
    db: Session,
    d0: date,
    d1: date,
    *,
    require_payload: bool = False,
) -> list[date]:
    """
    GFA 성과보고서는 날짜 row가 있어도 전환 열 없이 받은 파일이면 완료로 보지 않는다.
    전환 필수 헤더 검증을 통과한 업로드 source만 완료 데이터로 인정한다.
    추가 수집 후보를 찾을 때는 require_payload=True로 원본 payload가 있는 실제 성과 행만 완료로 본다.
    """
    try:
        return sorted(_collection_gfa_performance_missing_units(db, d0, d1, require_payload=require_payload).keys())
    except Exception:
        return _collection_table_missing_dates(db, "naver_gfa_performance_daily", d0, d1)


PURCHASE_KEYWORD_COMPLETE_SOURCES = ("smartstore_cdp", "purchase_upload")
ADS_SEARCHWORD_COMPLETE_SOURCES = ("ui_csv_upload",)
ADS_CREATIVE_COMPLETE_SOURCES = ("searchad_api", "creative_upload")


def _collection_purchase_keyword_missing_source_dates(db: Session, d0: date, d1: date) -> list[date]:
    """
    구매 키워드 CDP 수집은 같은 fact 테이블의 commerce 집계(source=purchase_commerce_api)를
    완료 데이터로 보면 안 된다.
    매출 데이터가 있는 날짜 중 원본 키워드(smartstore_cdp 또는 사용자가 올린 purchase_upload)가 없는 날짜만 대상으로 삼는다.
    """
    try:
        sales_rows = db.execute(
            text(
                """
                select date::date as d
                from naver_commerce_product_sales_daily
                where date::date between :d0 and :d1
                group by date::date
                having count(*) > 0
                """
            ),
            {"d0": d0, "d1": d1},
        ).mappings().all()
        sales_dates = {_collection_parse_date(r.get("d")) for r in sales_rows}
        sales_dates = {d for d in sales_dates if d is not None}
        if not sales_dates:
            return []
        keyword_rows = db.execute(
            text(
                """
                select date::date as d
                from naver_smartstore_purchase_keyword_daily
                where date::date between :d0 and :d1
                  and source = any(:sources)
                group by date::date
                having count(*) > 0
                """
            ),
            {"d0": d0, "d1": d1, "sources": list(PURCHASE_KEYWORD_COMPLETE_SOURCES)},
        ).mappings().all()
        keyword_dates = {_collection_parse_date(r.get("d")) for r in keyword_rows}
        keyword_dates = {d for d in keyword_dates if d is not None}
        return sorted(d for d in sales_dates if d not in keyword_dates)
    except Exception:
        return []


def _collection_review_daily_missing_source_dates(db: Session, d0: date, d1: date) -> list[date]:
	"""
	리뷰 일간 스냅샷 보강은 외부 수집이 아니라 page metrics에서 이미 확보한
	리뷰/평점 메트릭을 review_daily로 mirror하는 작업이다.
	따라서 "전체 달력 날짜"가 아니라 원천 메트릭이 있는 날짜 중 스냅샷이 없는 날짜만 대상으로 삼는다.
	"""
	try:
		rows = db.execute(
			text(
				"""
				with source_dates as (
				  select date::date as d
				  from tracked_product_page_daily
				  where date::date between :d0 and :d1
				    and rating is not null
				    and review_count is not null
				  group by date::date
				),
				snapshot_dates as (
				  select date::date as d
				  from naver_product_review_daily
				  where date::date between :d0 and :d1
				  group by date::date
				)
				select s.d
				from source_dates s
				left join snapshot_dates r on r.d = s.d
				where r.d is null
				order by s.d
				"""
			),
			{"d0": d0, "d1": d1},
		).mappings().all()
		return [d for d in (_collection_parse_date(row.get("d")) for row in rows) if d is not None]
	except Exception:
		return []


def _collection_missing_default_payload(db: Session, task_id: str, payload: CollectionRunPayload) -> CollectionRunPayload:
    if _collection_has_explicit_dates(payload):
        return payload
    if task_id in TODAY_ONLY_SNAPSHOT_TASKS:
        # Snapshot collectors can only capture the current state. Do not backfill
        # old missing dates from the central collection hub.
        return payload.model_copy(update={"date": _today_kst(), "date_from": None, "date_to": None})
    if task_id == "qna_collect":
        today = _today_kst()
        return payload.model_copy(update={"date": today, "date_from": today - timedelta(days=89), "date_to": today})
    target = _today_kst() - timedelta(days=1)
    meta = COLLECTION_TASK_REGISTRY.get(task_id) or {}
    if task_id == "purchase_keywords":
        scan_start = target - timedelta(days=119)
        missing_dates = _collection_purchase_keyword_missing_source_dates(db, scan_start, target)
        if missing_dates:
            start = max(min(missing_dates), target - timedelta(days=119))
            return payload.model_copy(update={"date": None, "date_from": start, "date_to": target})
    if task_id == "review_daily_backfill":
        scan_start = target - timedelta(days=364)
        missing_dates = _collection_review_daily_missing_source_dates(db, scan_start, target)
        if missing_dates:
            return payload.model_copy(update={"date": None, "date_from": min(missing_dates), "date_to": target})
    if task_id == "gfa_performance_daily":
        scan_start = max(target - timedelta(days=GFA_PENDING_LOOKBACK_DAYS - 1), _gfa_ui_min_report_date(_today_kst()))
        with SessionLocal() as db:
            missing_dates = _collection_gfa_performance_missing_dates(db, scan_start, target, require_payload=True)
        if missing_dates:
            return payload.model_copy(update={"date": None, "date_from": min(missing_dates), "date_to": target})
    missing_dates: list[date] = []
    for table_name in list(meta.get("target_tables") or []):
        table = str(table_name)
        if table not in COLLECTION_TABLE_DATE_COLUMNS:
            continue
        max_date = _collection_table_max_date(db, table)
        if not max_date:
            missing_dates.append(target)
            continue
        min_date = _collection_table_min_date(db, table) or max_date
        scan_start = max(min_date if min_date <= target else target, target - timedelta(days=119))
        source_filter = _collection_table_source_filter(task_id, table)
        missing_dates.extend(_collection_table_missing_dates(db, table, scan_start, target, source=source_filter))
    if not missing_dates:
        return payload
    start = min(missing_dates)
    # 개별 수집 API의 방어 상한(대부분 120일)에 맞춰 과도한 자동 백필을 막는다. 비연속 누락은 가장 이른 누락일부터 연속 범위로 보강한다.
    start = max(start, target - timedelta(days=119))
    return payload.model_copy(update={"date": None, "date_from": start, "date_to": target})


def _collection_persistence_summary(db: Session, task_id: str, d0: date, d1: date) -> dict:
    meta = COLLECTION_TASK_REGISTRY.get(task_id) or {}
    rows_by_table: dict[str, int] = {}
    empty_dates_by_table: dict[str, list[str]] = {}
    total = 0
    checked_tables: list[str] = []
    for table_name in list(meta.get("target_tables") or []):
        table = str(table_name)
        source_filter = _collection_table_source_filter(task_id, table)
        source_filters = (
            PURCHASE_KEYWORD_COMPLETE_SOURCES
            if task_id == "purchase_keywords" and table == "naver_smartstore_purchase_keyword_daily"
            else ADS_SEARCHWORD_COMPLETE_SOURCES
            if task_id == "ads_searchword_daily" and table == "naver_ad_searchword_daily"
            else ADS_CREATIVE_COMPLETE_SOURCES
            if task_id == "ads_creative_report_daily" and table == "naver_ad_creative_daily"
            else GFA_CONVERSION_COMPLETE_SOURCES
            if task_id == "gfa_performance_daily" and table == "naver_gfa_performance_daily"
            else None
        )
        n = _collection_table_rows_for_range(db, table, d0, d1, source=source_filter, sources=source_filters)
        missing = (
            _collection_gfa_performance_missing_dates(db, d0, d1)
            if task_id == "gfa_performance_daily" and table == "naver_gfa_performance_daily"
            else _collection_table_missing_dates(db, table, d0, d1, source=source_filter, sources=source_filters)
        )
        checked_tables.append(table)
        rows_by_table[table] = n
        if missing:
            empty_dates_by_table[table] = [x.isoformat() for x in missing]
        total += n
    empty_tables = [k for k, v in rows_by_table.items() if int(v or 0) <= 0]
    missing_date_count = sum(len(v or []) for v in empty_dates_by_table.values())
    out = {
        "date_from": d0.isoformat(),
        "date_to": d1.isoformat(),
        "required_date_count": max(0, (d1 - d0).days + 1),
        "checked_tables": checked_tables,
        "rows_total": int(total),
        "rows_by_table": rows_by_table,
        "empty_tables": empty_tables,
        "missing_tables": empty_tables,
        "empty_dates_by_table": empty_dates_by_table,
        "missing_dates_by_table": empty_dates_by_table,
        "missing_date_count": missing_date_count,
        "completion_verified": False,
        "verification_status": "pending",
    }
    if task_id == "rank_openapi" and d0 == d1:
        try:
            out.update(_rank_openapi_completion_summary(db, d0))
        except Exception as exc:
            out["rank_completion_error"] = f"{type(exc).__name__}: {exc}"
    if task_id == "ad_rank_diagnosis_cdp":
        try:
            out.update(_ad_rank_diagnosis_completion_summary(db, d0, d1))
        except Exception as exc:
            out["ad_rank_completion_error"] = f"{type(exc).__name__}: {exc}"
    return out


def _ad_rank_diagnosis_completion_summary(db: Session, d0: date, d1: date) -> dict:
    plan = _ad_rank_collection_plan(db)
    product_urls = {
        str(item.get("product_url") or "").strip()
        for item in (plan.get("products") or [])
        if isinstance(item, dict) and str(item.get("product_url") or "").strip()
    }
    keywords = {
        str(keyword or "").strip()
        for keyword in (plan.get("keywords") or [])
        if str(keyword or "").strip()
    }
    conditions = {
        (
            str(condition.get("gender") or "").strip(),
            str(condition.get("age_band") or "").strip(),
            str(condition.get("placement") or "").strip(),
        )
        for condition in (plan.get("conditions") or [])
        if isinstance(condition, dict)
        and str(condition.get("gender") or "").strip()
        and str(condition.get("age_band") or "").strip()
        and str(condition.get("placement") or "").strip()
    }
    days: list[date] = []
    cur = d0
    while cur <= d1:
        days.append(cur)
        cur += timedelta(days=1)

    expected = {
        (day, product_url, keyword, gender, age_band, placement)
        for day in days
        for product_url in product_urls
        for keyword in keywords
        for gender, age_band, placement in conditions
    }
    expected_units = {
        (day, keyword, gender, age_band, placement)
        for day in days
        for keyword in keywords
        for gender, age_band, placement in conditions
    }
    rows = (
        db.query(
            AdRankDiagnosisDaily.date,
            AdRankDiagnosisDaily.product_url,
            AdRankDiagnosisDaily.keyword,
            AdRankDiagnosisDaily.gender,
            AdRankDiagnosisDaily.age_band,
            AdRankDiagnosisDaily.placement,
            AdRankDiagnosisDaily.status,
        )
        .filter(AdRankDiagnosisDaily.date >= d0, AdRankDiagnosisDaily.date <= d1)
        .all()
    )
    saved = set()
    failed = set()
    ok_products_by_unit: dict[tuple, set[str]] = defaultdict(set)
    failed_units: set[tuple] = set()
    saved_units: set[tuple] = set()
    outside_plan = 0
    for row in rows:
        key = (
            row[0],
            str(row[1] or "").strip(),
            str(row[2] or "").strip(),
            str(row[3] or "").strip(),
            str(row[4] or "").strip(),
            str(row[5] or "").strip(),
        )
        if key not in expected:
            outside_plan += 1
            continue
        unit_key = (row[0], str(row[2] or "").strip(), str(row[3] or "").strip(), str(row[4] or "").strip(), str(row[5] or "").strip())
        saved.add(key)
        saved_units.add(unit_key)
        if str(row[6] or "").strip().lower() == "failed":
            failed.add(key)
            failed_units.add(unit_key)
        else:
            ok_products_by_unit[unit_key].add(str(row[1] or "").strip())
    missing = expected - saved
    expected_product_count = len(product_urls)
    ok_units = {
        unit_key
        for unit_key, unit_products in ok_products_by_unit.items()
        if expected_product_count > 0 and len(unit_products) >= expected_product_count and unit_key not in failed_units
    }
    missing_units = expected_units - ok_units - failed_units
    return {
        "ad_rank_expected_cells": len(expected),
        "ad_rank_saved_cells": len(saved),
        "ad_rank_missing_cells": len(missing),
        "ad_rank_failed_cells": len(failed),
        "ad_rank_ok_cells": max(0, len(saved) - len(failed)),
        "ad_rank_expected_search_units": len(expected_units),
        "ad_rank_saved_search_units": len(saved_units),
        "ad_rank_ok_search_units": len(ok_units),
        "ad_rank_failed_search_units": len(failed_units),
        "ad_rank_missing_search_units": len(missing_units),
        "ad_rank_outside_plan_rows": int(outside_plan),
        "ad_rank_plan_product_count": len(product_urls),
        "ad_rank_plan_keyword_count": len(keywords),
        "ad_rank_plan_condition_count": len(conditions),
    }


def _collection_mark_persistence_verification(persisted: dict | None, *, verified: bool, reason: str | None = None) -> None:
    if not isinstance(persisted, dict):
        return
    persisted["completion_verified"] = bool(verified)
    persisted["verification_status"] = "complete" if verified else "incomplete"
    if reason:
        persisted["verification_reason"] = reason


def _collection_apply_persistence_status(task_id: str, status: str, rows_written: int | None, persisted: dict | None) -> tuple[str, str | None]:
    if status == "QUEUED" or persisted is None:
        return status, None
    persisted_rows = int((persisted or {}).get("rows_total") or 0)
    rows = int(rows_written or 0)
    if status in {"SUCCESS", "PARTIAL"} and persisted_rows <= 0 and rows <= 0:
        _collection_mark_persistence_verification(persisted, verified=False, reason="no_db_rows_saved")
        return "FAILED", "no_db_rows_saved"
    if task_id in {"reviews_collect", "qna_collect"} and status in {"SUCCESS", "PARTIAL"} and (persisted_rows > 0 or rows > 0):
        # Reviews and Q&A are event/update rows, not daily fact rows. A date
        # with no event is valid, so empty-date checks must not turn a
        # successful fetch partial. Reply backfill is handled separately because
        # completion depends on there being no reply targets left.
        _collection_mark_persistence_verification(persisted, verified=status == "SUCCESS", reason="event_rows_verified" if status == "SUCCESS" else "partial_event_rows")
        return "SUCCESS", None
    if task_id in {"gfa_campaign_inventory", "gfa_adgroup_inventory"} and status in {"SUCCESS", "PARTIAL"} and rows > 0:
        # Inventory collection is a current-state snapshot, not a daily fact
        # table. The collector's upload count is the reliable completion signal.
        _collection_mark_persistence_verification(persisted, verified=True, reason="inventory_snapshot_uploaded")
        return "SUCCESS", None
    if task_id == "gfa_creative_detail" and status == "SUCCESS" and rows > 0:
        _collection_mark_persistence_verification(persisted, verified=True, reason="creative_detail_rows_saved")
        return "SUCCESS", None
    if task_id == "page_metrics_cdp" and status in {"SUCCESS", "PARTIAL"}:
        rows_by_table = (persisted or {}).get("rows_by_table") or {}
        try:
            page_rows = int(rows_by_table.get("tracked_product_page_daily") or 0)
        except Exception:
            page_rows = 0
        if page_rows > 0 and rows > 0:
            # `naver_product_review_daily` is also maintained by a separate
            # review snapshot backfill. Page metrics should be judged by the
            # page metrics fact table, not by this optional mirror table.
            _collection_mark_persistence_verification(persisted, verified=status == "SUCCESS", reason="primary_table_verified" if status == "SUCCESS" else "partial_primary_table")
            return status, None
    if task_id == "review_daily_backfill" and status in {"SUCCESS", "PARTIAL"} and (persisted_rows > 0 or rows > 0):
        # This task can only mirror dates where page metrics already have
        # review/rating values. Calendar gaps without source rows are not partial failures.
        _collection_mark_persistence_verification(persisted, verified=True, reason="derived_rows_verified")
        return "SUCCESS", None
    if task_id == "rank_openapi" and status in {"SUCCESS", "PARTIAL"}:
        missing_keywords = int((persisted or {}).get("missing_keyword_count") or 0)
        incomplete_products = int((persisted or {}).get("incomplete_product_count") or 0)
        expected_keywords = int((persisted or {}).get("expected_keyword_count") or 0)
        exposure_anomaly = bool((persisted or {}).get("rank_exposure_anomaly"))
        if expected_keywords > 0 and (missing_keywords > 0 or incomplete_products > 0):
            _collection_mark_persistence_verification(persisted, verified=False, reason="rank_keywords_incomplete")
            return "PARTIAL", None
        if expected_keywords > 0 and exposure_anomaly:
            exposed = int((persisted or {}).get("exposed_keyword_count") or 0)
            previous_exposed = int((persisted or {}).get("previous_exposed_count") or 0)
            baseline_exposed = int((persisted or {}).get("baseline_exposed_count") or previous_exposed or 0)
            baseline_date = str((persisted or {}).get("baseline_date") or "").strip()
            drop_ratio = float((persisted or {}).get("exposure_drop_ratio") or 0)
            _collection_mark_persistence_verification(persisted, verified=False, reason="rank_exposure_anomaly")
            suffix = f",baseline_date={baseline_date}" if baseline_date else ""
            return "PARTIAL", f"rank_exposure_anomaly exposed={exposed},baseline={baseline_exposed}{suffix},drop={drop_ratio:.2%}"
        if expected_keywords > 0 and persisted_rows > 0:
            _collection_mark_persistence_verification(persisted, verified=True, reason="rank_keywords_verified")
            return "SUCCESS", None

    if task_id == "ad_rank_diagnosis_cdp" and status in {"SUCCESS", "PARTIAL"}:
        expected_cells = int((persisted or {}).get("ad_rank_expected_cells") or 0)
        saved_cells = int((persisted or {}).get("ad_rank_saved_cells") or 0)
        missing_cells = int((persisted or {}).get("ad_rank_missing_cells") or 0)
        failed_cells = int((persisted or {}).get("ad_rank_failed_cells") or 0)
        expected_units = int((persisted or {}).get("ad_rank_expected_search_units") or 0)
        ok_units = int((persisted or {}).get("ad_rank_ok_search_units") or 0)
        missing_units = int((persisted or {}).get("ad_rank_missing_search_units") or 0)
        failed_units = int((persisted or {}).get("ad_rank_failed_search_units") or 0)
        if expected_units > 0 and (missing_units > 0 or failed_units > 0):
            _collection_mark_persistence_verification(
                persisted,
                verified=False,
                reason="ad_rank_search_units_incomplete",
            )
            return "PARTIAL", f"ad_rank_search_units_incomplete={ok_units}/{expected_units},failed={failed_units},missing={missing_units}"
        if expected_units > 0 and ok_units >= expected_units:
            _collection_mark_persistence_verification(persisted, verified=True, reason="ad_rank_search_units_verified")
            return "SUCCESS", None
        if expected_cells > 0 and (missing_cells > 0 or failed_cells > 0):
            _collection_mark_persistence_verification(
                persisted,
                verified=False,
                reason="ad_rank_cells_incomplete",
            )
            return "PARTIAL", f"ad_rank_cells_incomplete={saved_cells}/{expected_cells},failed={failed_cells}"
        if expected_cells > 0 and saved_cells >= expected_cells:
            _collection_mark_persistence_verification(persisted, verified=True, reason="ad_rank_cells_verified")
            return "SUCCESS", None

    empty_tables = [str(x) for x in ((persisted or {}).get("empty_tables") or []) if str(x or "").strip()]
    empty_dates_by_table = (persisted or {}).get("empty_dates_by_table")
    has_empty_dates = isinstance(empty_dates_by_table, dict) and any(bool(v) for v in empty_dates_by_table.values())
    if status == "SUCCESS" and (empty_tables or has_empty_dates):
        # 광고 성과처럼 여러 fact 테이블을 한 작업에서 채우는 경우,
        # 일부 테이블/일자가 비면 전체 성공이 아니라 부분 성공으로 보여야 한다.
        if empty_tables:
            _collection_mark_persistence_verification(persisted, verified=False, reason="empty_target_tables")
            return "PARTIAL", f"empty_target_tables={','.join(empty_tables)}"
        _collection_mark_persistence_verification(persisted, verified=False, reason="empty_target_dates")
        return "PARTIAL", "empty_target_dates"
    _collection_mark_persistence_verification(persisted, verified=status == "SUCCESS", reason="required_range_verified" if status == "SUCCESS" else "partial_result")
    return status, None


def _collection_result_rows(result: object) -> int | None:
    if not isinstance(result, dict):
        return None
    for key in ("rows_written", "saved", "saved_reviews", "processed", "total_rows", "analyzed", "raw_upserted_total"):
        try:
            if result.get(key) is not None:
                return int(result.get(key) or 0)
        except Exception:
            pass
    try:
        inserted = sum(int(result.get(k) or 0) for k in ("insertedKeyword", "insertedSearchword", "insertedCreative"))
        if inserted > 0:
            return inserted
    except Exception:
        pass
    try:
        fact_rows = result.get("fact_rows_by_date")
        if isinstance(fact_rows, dict):
            return sum(max(0, int(v or 0)) for v in fact_rows.values())
    except Exception:
        pass
    nested = result.get("result")
    if isinstance(nested, dict):
        return _collection_result_rows(nested)
    return None


def _collection_result_status(result: object) -> str:
    if not isinstance(result, dict):
        return "SUCCESS"
    if result.get("runtime") == "collector_pc" and result.get("queued"):
        return "QUEUED"
    if result.get("ok") is False:
        return "FAILED"
    status = str(result.get("status") or "").strip().upper()
    if status in {"FAILED", "PARTIAL", "SKIPPED", "SUCCESS"}:
        return "SUCCESS" if status == "SKIPPED" else status
    errors = result.get("errors")
    if isinstance(errors, dict) and len(errors) > 0:
        return "PARTIAL"
    if isinstance(errors, list) and len(errors) > 0:
        return "PARTIAL"
    return "SUCCESS"


def _shopping_rank_metrics_ranked_items(metrics: dict) -> list[dict]:
    ranked0 = metrics.get("ranked_items") or []
    if isinstance(ranked0, dict):
        ranked0 = [ranked0]
    if not isinstance(ranked0, list):
        return []
    return [item for item in ranked0 if isinstance(item, dict)]


def _shopping_rank_metrics_rows(metrics: dict) -> list[dict]:
    rows0 = metrics.get("rows") or metrics.get("items") or []
    if isinstance(rows0, dict):
        rows0 = [rows0]
    if not isinstance(rows0, list):
        return []
    return [item for item in rows0 if isinstance(item, dict)]


def _shopping_rank_result_block_reason(metrics: dict) -> str | None:
    """
    Fail closed: if the collector could not read any ranked SERP items, do not
    convert target URLs into rank=0 rows. rank=0 is a valid "not exposed"
    outcome only after a readable SERP exists for that keyword.
    """
    if bool(metrics.get("fatal")):
        return str(metrics.get("error") or "shopping_rank_fatal").strip() or "shopping_rank_fatal"
    err = str(metrics.get("error") or metrics.get("api_error") or "").strip()
    if re.search(r"mobile_search_restricted_or_captcha|shopping_service_restricted|shopping_access_limited|http_403|http_418|http_429|captcha|security|보안|제한|비정상", err, flags=re.I):
        return err
    ranked_items = _shopping_rank_metrics_ranked_items(metrics)
    rows0 = _shopping_rank_metrics_rows(metrics)
    try:
        ranked_count = int(metrics.get("ranked_items_count") or metrics.get("ranked_id_count") or len(ranked_items) or 0)
    except Exception:
        ranked_count = len(ranked_items)
    if rows0 and ranked_count <= 0:
        return "shopping_rank_no_ranked_items"
    return None


def _collection_collector_device_id(payload: CollectionRunPayload, request: Request | None = None) -> str | None:
    raw = str(getattr(payload, "collector_device_id", None) or "").strip()
    if not raw and request is not None:
        try:
            raw = str(request.headers.get("x-erp2-collector-device-id") or "").strip()
        except Exception:
            raw = ""
    if not raw:
        return None
    cleaned = re.sub(r"[^A-Za-z0-9_.:-]+", "-", raw)[:120].strip("-")
    return cleaned or None


def _collection_plain_result(result: object) -> dict:
    if isinstance(result, dict):
        return result
    try:
        if hasattr(result, "model_dump"):
            return result.model_dump(mode="json")  # type: ignore[attr-defined]
    except Exception:
        pass
    try:
        if hasattr(result, "dict"):
            return result.dict()  # type: ignore[attr-defined]
    except Exception:
        pass
    return {"result": result}


def _collection_date_list(d0: date, d1: date, *, max_days: int = 120) -> list[date]:
    if d1 < d0:
        return []
    n = min(max(1, int(max_days)), int((d1 - d0).days) + 1)
    return [d0 + timedelta(days=i) for i in range(n)]


def _rank_openapi_latest_unreadable_keywords(db: Session, target: date) -> set[str]:
    latest = (
        db.query(CollectionJobRun.job_id)
        .filter(
            CollectionJobRun.task_id == "rank_openapi",
            CollectionJobRun.target_date == target,
        )
        .order_by(CollectionJobRun.started_at.desc())
        .first()
    )
    latest_job_id = str(latest[0] or "").strip() if latest else ""
    if not latest_job_id:
        return set()
    events = (
        db.query(CollectionJobEvent.detail_json)
        .filter(
            CollectionJobEvent.job_id == latest_job_id,
            CollectionJobEvent.detail_json.like("%mobile_search_restricted_or_captcha%"),
        )
        .all()
    )
    out: set[str] = set()
    for (detail_json,) in events:
        text = str(detail_json or "")
        m = re.search(r"mobile_organic_result_wait_failed\s+\d+/\d+:\s+(.+?)\s+mobile_search_restricted_or_captcha", text)
        if not m:
            m = re.search(r"mobile_organic_keyword_error\s+\d+/\d+:\s+(.+?)\s+mobile_search_restricted_or_captcha", text)
        if m:
            kw = str(m.group(1) or "").strip()
            if kw:
                out.add(kw)
    return out


def _rank_openapi_completion_summary(db: Session, target: date) -> dict:
    rank_sources = ("openapi", "shopping_rank_mobile_sas_shopping_cdp", SHOPPING_RANK_MOBILE_CDP_SOURCE)
    product_rows = (
        db.query(TrackedProductKeyword.product_url)
        .filter(TrackedProductKeyword.is_active.is_(True))
        .distinct()
        .all()
    )
    product_urls = list(dict.fromkeys([(r[0] or "").strip() for r in product_rows if (r[0] or "").strip()]))[:50]
    product_summaries: list[dict] = []
    expected_total = 0
    collected_total = 0
    exposed_total = 0
    missing_total = 0
    expected_search_keywords: set[str] = set()
    collected_search_keywords: set[str] = set()
    unreadable_keywords = _rank_openapi_latest_unreadable_keywords(db, target)
    for url in product_urls:
        keywords = _resolve_keywords_for_seed(db, seed_product_url=url, payload_keywords=None)
        keywords = [str(kw or "").strip() for kw in keywords if str(kw or "").strip()]
        keywords = list(dict.fromkeys(keywords))
        expected_search_keywords.update(keywords)
        expected = len(keywords)
        expected_total += expected
        if expected <= 0:
            product_summaries.append(
                {
                    "product_url": url,
                    "expected_keywords": 0,
                    "collected_keywords": 0,
                    "exposed_keywords": 0,
                    "missing_keywords": 0,
                    "complete": False,
                    "reason": "no_keywords",
                }
            )
            continue
        rank_filters = _smartstore_product_url_filters(TrackedProductRankDaily, product_url=url)
        rows = (
            db.query(TrackedProductRankDaily.keyword, TrackedProductRankDaily.rank)
            .filter(
                or_(*rank_filters),
                TrackedProductRankDaily.date == target,
                TrackedProductRankDaily.source.in_(rank_sources),
                TrackedProductRankDaily.keyword.in_(keywords),
            )
            .all()
        )
        collected: set[str] = set()
        exposed: set[str] = set()
        for kw, rank_value in rows:
            kw0 = str(kw or "").strip()
            if not kw0:
                continue
            if kw0 not in unreadable_keywords:
                collected.add(kw0)
                collected_search_keywords.add(kw0)
            try:
                if int(rank_value or 0) > 0:
                    exposed.add(kw0)
            except Exception:
                pass
        missing = [kw for kw in keywords if kw not in collected]
        collected_count = len(collected)
        exposed_count = len(exposed)
        missing_count = len(missing)
        collected_total += collected_count
        exposed_total += exposed_count
        missing_total += missing_count
        product_summaries.append(
            {
                "product_url": url,
                "expected_keywords": expected,
                "collected_keywords": collected_count,
                "exposed_keywords": exposed_count,
                "missing_keywords": missing_count,
                "complete": missing_count == 0,
                "missing_keyword_sample": missing[:20],
            }
        )
    incomplete_products = [row for row in product_summaries if not bool(row.get("complete"))]
    previous_exposed_count = 0
    try:
        previous_exposed_count = int(
            db.query(func.count(TrackedProductRankDaily.keyword))
            .filter(
                TrackedProductRankDaily.date == target - timedelta(days=1),
                TrackedProductRankDaily.source.in_(rank_sources),
                TrackedProductRankDaily.rank > 0,
            )
            .scalar()
            or 0
        )
    except Exception:
        previous_exposed_count = 0
    baseline_exposed_count = previous_exposed_count
    baseline_date: date | None = target - timedelta(days=1) if previous_exposed_count > 0 else None
    try:
        baseline_rows = (
            db.query(TrackedProductRankDaily.date, func.count(TrackedProductRankDaily.keyword))
            .filter(
                TrackedProductRankDaily.date >= target - timedelta(days=7),
                TrackedProductRankDaily.date < target,
                TrackedProductRankDaily.source.in_(rank_sources),
                TrackedProductRankDaily.rank > 0,
            )
            .group_by(TrackedProductRankDaily.date)
            .order_by(TrackedProductRankDaily.date.desc())
            .all()
        )
        for d0, count0 in baseline_rows:
            c0 = int(count0 or 0)
            if c0 > 0:
                baseline_date = d0
                baseline_exposed_count = c0
                break
    except Exception:
        baseline_exposed_count = previous_exposed_count
        baseline_date = target - timedelta(days=1) if previous_exposed_count > 0 else None
    # CDP 수집은 rank=0도 "행 저장"으로 남기므로, 파싱/매칭 장애가 있어도 누락 0건으로 보일 수 있다.
    # 최근 정상 노출 규모 대비 급락하면 완료가 아니라 품질 이상(PARTIAL)으로 표기한다.
    exposure_drop_ratio = (
        round((baseline_exposed_count - exposed_total) / baseline_exposed_count, 4)
        if baseline_exposed_count > 0 and exposed_total < baseline_exposed_count
        else 0.0
    )
    exposure_anomaly = bool(baseline_exposed_count >= 50 and exposure_drop_ratio >= 0.6)
    return {
        "rank_products_total": len(product_summaries),
        "rank_products_complete": max(0, len(product_summaries) - len(incomplete_products)),
        "incomplete_product_count": len(incomplete_products),
        "expected_keyword_count": expected_total,
        "collected_keyword_count": collected_total,
        "expected_search_keyword_count": len(expected_search_keywords),
        "collected_search_keyword_count": len(collected_search_keywords),
        "exposed_keyword_count": exposed_total,
        "previous_exposed_count": previous_exposed_count,
        "baseline_exposed_count": baseline_exposed_count,
        "baseline_date": baseline_date.isoformat() if baseline_date else None,
        "exposure_drop_ratio": exposure_drop_ratio,
        "rank_exposure_anomaly": exposure_anomaly,
        "missing_keyword_count": missing_total,
        "incomplete_products": incomplete_products[:20],
    }


SHOPPING_RANK_BLOCK_COOLDOWN_SECONDS = 6 * 60 * 60
SHOPPING_RANK_BLOCK_CACHE_GUIDANCE = "운영 PC의 인터넷 캐시/사이트 데이터를 삭제한 뒤, 최소 6시간 후 소량 키워드로 재시도하세요."


def _rank_openapi_block_reason_from_job(job: CollectionJobRun | object) -> str | None:
    error = str(getattr(job, "error", "") or "").strip()
    detail = _collection_json_loads(str(getattr(job, "detail_json", "") or ""))
    detail_obj = detail if isinstance(detail, dict) else {}
    persisted = detail_obj.get("db_persistence") if isinstance(detail_obj.get("db_persistence"), dict) else {}
    diagnostics = detail_obj.get("collector_diagnostics") if isinstance(detail_obj.get("collector_diagnostics"), dict) else {}
    text = " ".join([
        error,
        _collection_json_dumps(detail_obj) if detail_obj else "",
        str(diagnostics.get("primary_category") or ""),
    ])
    if re.search(
        r"mobile_search_restricted_or_captcha|shopping_rank_no_ranked_items|shopping_service_restricted|shopping_access_limited|http_403|http_418|http_429|captcha|security|보안|제한|비정상",
        text,
        flags=re.I,
    ):
        return "shopping_rank_blocked_or_unreadable"
    # Zero exposure after a completed collector run is a data-quality/matching
    # anomaly, not proof of Naver blocking. The collector can successfully
    # collect ranked cards while all target products remain unmatched.
    # Only explicit block/unreadable signatures above should trigger cooldown.
    return None


def _rank_openapi_cooldown_state(db: Session, *, target_date: date | None = None, now_kst: datetime | None = None) -> dict | None:
    now = now_kst or datetime.now(ZoneInfo("Asia/Seoul"))
    cutoff = now - timedelta(seconds=SHOPPING_RANK_BLOCK_COOLDOWN_SECONDS)
    rows = (
        db.query(CollectionJobRun)
        .filter(
            CollectionJobRun.task_id == "rank_openapi",
            CollectionJobRun.finished_at.isnot(None),
            CollectionJobRun.finished_at >= cutoff,
        )
        .order_by(CollectionJobRun.finished_at.desc())
        .limit(10)
        .all()
    )
    for row in rows:
        if target_date is not None and getattr(row, "target_date", None) != target_date:
            continue
        reason = _rank_openapi_block_reason_from_job(row)
        if not reason:
            continue
        if reason == "shopping_rank_zero_exposure_after_collection":
            row_target = getattr(row, "target_date", None)
            if isinstance(row_target, date):
                try:
                    cdp_exposed = int(
                        db.query(func.count(TrackedProductRankDaily.keyword))
                        .filter(
                            TrackedProductRankDaily.date == row_target,
                            TrackedProductRankDaily.source == "shopping_rank_mobile_sas_shopping_cdp",
                            TrackedProductRankDaily.rank > 0,
                        )
                        .scalar()
                        or 0
                    )
                except Exception:
                    cdp_exposed = 0
                if cdp_exposed > 0:
                    continue
        finished_at = row.finished_at
        if finished_at is None:
            continue
        finished_kst = finished_at.replace(tzinfo=ZoneInfo("Asia/Seoul")) if finished_at.tzinfo is None else finished_at.astimezone(ZoneInfo("Asia/Seoul"))
        cooldown_until = finished_kst + timedelta(seconds=SHOPPING_RANK_BLOCK_COOLDOWN_SECONDS)
        remaining = max(0, int((cooldown_until - now).total_seconds()))
        if remaining <= 0:
            continue
        return {
            "error": "shopping_rank_cooldown_active",
            "reason": reason,
            "cooldown_seconds": SHOPPING_RANK_BLOCK_COOLDOWN_SECONDS,
            "remaining_seconds": remaining,
            "cooldown_until": cooldown_until.isoformat(),
            "last_job_id": getattr(row, "job_id", None),
            "last_status": getattr(row, "status", None),
            "message": f"검색/쇼핑 순위 CDP가 차단/빈 결과를 감지해 최소 6시간 재시도를 차단했습니다. {SHOPPING_RANK_BLOCK_CACHE_GUIDANCE}",
            "cache_guidance": SHOPPING_RANK_BLOCK_CACHE_GUIDANCE,
        }
    return None


ADS_KIND_TABLES = {
    "keyword": "naver_ad_keyword_daily",
    "searchword": "naver_ad_searchword_daily",
    "creative": "naver_ad_creative_daily",
}


def _collection_ads_task_kinds(task_id: str) -> tuple[str, ...]:
    meta = COLLECTION_TASK_REGISTRY.get(task_id) or {}
    kinds = tuple(str(k or "").strip() for k in (meta.get("ads_kinds") or []) if str(k or "").strip())
    if task_id == "ads_daily":
        # 광고 성과(API)는 캠페인/광고그룹 성과뿐 아니라 소재 분석의 원천도 함께 채운다.
        # 특히 NAS DB에 과거 소재ID 합산 row만 남아 있으면 "데이터 있음"으로 판정되지만,
        # 최신 파워링크 화면에서는 키워드 없는 row가 제외되어 소재가 비어 보일 수 있다.
        # 따라서 ads_daily는 항상 creative를 포함한다.
        return tuple(k for k in ("keyword", "searchword", "creative") if k in ADS_KIND_TABLES)
    if kinds:
        return tuple(k for k in kinds if k in ADS_KIND_TABLES)
    return ("keyword", "searchword", "creative")


def _collection_ads_missing_kinds_by_date(db: Session, d0: date, d1: date, *, kinds: tuple[str, ...]) -> dict[date, tuple[str, ...]]:
    dates = _collection_date_list(d0, d1, max_days=366)
    missing_by_kind: dict[str, set[date]] = {}
    requested = tuple(k for k in kinds if k in ADS_KIND_TABLES)
    for kind in requested:
        table = ADS_KIND_TABLES[kind]
        missing_by_kind[kind] = set(_collection_table_missing_dates(db, table, d0, d1, source="searchad_api"))
    out: dict[date, tuple[str, ...]] = {}
    for day in dates:
        missing_kinds = tuple(kind for kind in requested if day in missing_by_kind.get(kind, set()))
        out[day] = missing_kinds
    return out


def _collection_ads_missing_segments(missing_by_date: dict[date, tuple[str, ...]]) -> list[tuple[date, date, tuple[str, ...]]]:
    segments: list[tuple[date, date, tuple[str, ...]]] = []
    cur_start: date | None = None
    cur_end: date | None = None
    cur_kinds: tuple[str, ...] = ()
    for day in sorted(missing_by_date.keys()):
        kinds = tuple(missing_by_date.get(day) or ())
        if not kinds:
            if cur_start is not None and cur_end is not None and cur_kinds:
                segments.append((cur_start, cur_end, cur_kinds))
            cur_start = None
            cur_end = None
            cur_kinds = ()
            continue
        if cur_start is None:
            cur_start = day
            cur_end = day
            cur_kinds = kinds
            continue
        if cur_end is not None and day == cur_end + timedelta(days=1) and kinds == cur_kinds:
            cur_end = day
            continue
        if cur_end is not None and cur_kinds:
            segments.append((cur_start, cur_end, cur_kinds))
        cur_start = day
        cur_end = day
        cur_kinds = kinds
    if cur_start is not None and cur_end is not None and cur_kinds:
        segments.append((cur_start, cur_end, cur_kinds))
    return segments


def _collection_ads_creative_refresh_segments(date_from: date, date_to: date, *, exclude_dates: set[date] | None = None) -> list[tuple[date, date, tuple[str, ...]]]:
    excluded = set(exclude_dates or set())
    by_date: dict[date, tuple[str, ...]] = {}
    cur = date_from
    while cur <= date_to:
        by_date[cur] = () if cur in excluded else ("creative",)
        cur = cur + timedelta(days=1)
    return _collection_ads_missing_segments(by_date)


