@app.put("/collection/tasks/{task_id}/schedule", response_model=dict)
def collection_task_schedule(task_id: str, payload: CollectionTaskSchedulePayload, db: Session = Depends(get_db)):
    row = _collection_task_config(db, task_id)
    if payload.enabled is not None:
        row.enabled = bool(payload.enabled)
    if payload.schedule_enabled is not None:
        row.schedule_enabled = bool(payload.schedule_enabled)
    if payload.schedule_time is not None:
        s = str(payload.schedule_time or "").strip()
        if s and not re.match(r"^\d{2}:\d{2}$", s):
            raise HTTPException(status_code=400, detail="schedule_time must be HH:MM")
        row.schedule_time = s or None
    if payload.config is not None:
        row.config_json = _collection_json_dumps(payload.config)
    row.updated_at = datetime.utcnow()
    db.add(row)
    db.commit()
    return {"ok": True, "task": _collection_serialize_task(db, task_id)}


@app.post("/collection/tasks/{task_id}/run", response_model=dict)
def collection_task_run(task_id: str, request: Request, payload: CollectionRunPayload | None = Body(default=None)):
    payload = payload or CollectionRunPayload()
    return _collection_run_task(task_id, payload, run_mode=str(payload.mode or "manual"), request=request)


def _collection_run_all_task_ids(db: Session, task_ids: set[str] | None = None) -> list[str]:
    selected: list[str] = []
    for task_id, meta in COLLECTION_TASK_REGISTRY.items():
        if task_ids is not None and task_id not in task_ids:
            continue
        if not bool(meta.get("runnable")):
            continue
        cfg = _collection_task_config(db, task_id)
        if not cfg.enabled:
            continue
        selected.append(task_id)
    return selected


def _collection_run_all_once(payload: CollectionRunPayload, *, task_ids: set[str] | None = None, run_mode: str = "run_all") -> list[dict]:
    results: list[dict] = []
    with SessionLocal() as db:
        selected_task_ids = _collection_run_all_task_ids(db, task_ids)
    for task_id in selected_task_ids:
        try:
            results.append({"task_id": task_id, **_collection_run_task(task_id, payload, run_mode=run_mode)})
        except HTTPException as exc:
            results.append({"task_id": task_id, "ok": False, "error": exc.detail, "status_code": exc.status_code})
        except Exception as exc:
            results.append({"task_id": task_id, "ok": False, "error": str(exc)})
    return results


def _collection_run_all_result_failed(result: dict) -> bool:
    if not bool(result.get("ok", True)):
        return True
    job = result.get("job") if isinstance(result.get("job"), dict) else {}
    job_status = str((job or {}).get("status") or "").strip().upper()
    if job_status in {"FAILED", "PARTIAL"}:
        return True
    data = result.get("result") if isinstance(result.get("result"), dict) else {}
    result_status = str((data or {}).get("status") or "").strip().upper()
    if result_status in {"FAILED", "PARTIAL"}:
        return True
    errors = (data or {}).get("errors")
    return (isinstance(errors, dict) and len(errors) > 0) or (isinstance(errors, list) and len(errors) > 0)


def _collection_run_all_failed_task_ids(results: list[dict]) -> set[str]:
    return {
        str(row.get("task_id") or "").strip()
        for row in results
        if str(row.get("task_id") or "").strip() and _collection_run_all_result_failed(row)
    }


def _collection_reset_active_jobs_for_retry(db: Session, *, task_ids: set[str], now_kst: datetime) -> int:
    if not task_ids:
        return 0
    active_rows = (
        db.query(CollectionJobRun)
        .filter(CollectionJobRun.task_id.in_(sorted(task_ids)))
        .filter(CollectionJobRun.status.in_(["QUEUED", "STARTED", "CLAIMED", "UPLOADING", "WAITING_USER"]))
        .filter(CollectionJobRun.finished_at.is_(None))
        .all()
    )
    reset_collector_job_ids: set[str] = set()
    updated = 0
    for row in active_rows:
        detail = _collection_json_loads(row.detail_json) or {}
        if not isinstance(detail, dict):
            detail = {"detail": detail}
        collector_job = detail.get("collector_job")
        if isinstance(collector_job, dict):
            collector_job_id = str(collector_job.get("job_id") or "").strip()
            if collector_job_id:
                reset_collector_job_ids.add(collector_job_id)
            collector_job["status"] = "CANCELLED"
            collector_job["error"] = "run_all_retry_reset"
            collector_job["updated_at"] = now_kst.isoformat()
        detail["run_all_retry_reset"] = True
        detail["run_all_retry_reset_at"] = now_kst.isoformat()
        detail["message"] = "Active job was reset before the one-time run-all retry."
        row.status = "CANCELLED"
        row.error = "run_all_retry_reset"
        row.finished_at = datetime.utcnow()
        row.detail_json = _collection_json_dumps(detail)
        db.add(row)
        updated += 1
    if updated:
        db.commit()
    if reset_collector_job_ids:
        with PAGE_METRICS_COLLECTOR_JOB_LOCK:
            for collector_job_id in reset_collector_job_ids:
                job = PAGE_METRICS_COLLECTOR_JOBS.get(collector_job_id)
                if not job:
                    continue
                job["status"] = "CANCELLED"
                job["error"] = "run_all_retry_reset"
                job["updated_at"] = now_kst.isoformat()
                PAGE_METRICS_COLLECTOR_JOBS.pop(collector_job_id, None)
    return updated


@app.post("/collection/run-all", response_model=dict)
def collection_run_all(payload: CollectionRunPayload | None = Body(default=None), db: Session = Depends(get_db)):
    payload = payload or CollectionRunPayload()
    results = _collection_run_all_once(payload, run_mode="run_all")
    failed_task_ids = _collection_run_all_failed_task_ids(results)
    retry_results: list[dict] = []
    reset_count = 0
    if failed_task_ids:
        reset_count = _collection_reset_active_jobs_for_retry(db, task_ids=failed_task_ids, now_kst=datetime.now(ZoneInfo("Asia/Seoul")))
        retry_payload = payload.model_copy(update={"force": True, "mode": "run_all_retry"})
        retry_results = _collection_run_all_once(retry_payload, task_ids=failed_task_ids, run_mode="run_all_retry")
    final_failed_task_ids = _collection_run_all_failed_task_ids(retry_results) if retry_results else failed_task_ids
    return {
        "ok": len(final_failed_task_ids) == 0,
        "results": results,
        "retry": {
            "attempted": bool(failed_task_ids),
            "reset_count": reset_count,
            "failed_task_ids": sorted(failed_task_ids),
            "results": retry_results,
            "remaining_failed_task_ids": sorted(final_failed_task_ids),
        },
    }


def _collection_scheduler_tick() -> None:
    global COLLECTION_DAILY_RESET_DATE
    now_kst = datetime.now(ZoneInfo("Asia/Seoul"))
    hhmm = now_kst.strftime("%H:%M")
    today_key = now_kst.date().isoformat()
    with SessionLocal() as db:
        if COLLECTION_DAILY_RESET_DATE != today_key:
            reset_count = _collection_reset_stale_daily_jobs(db, now_kst=now_kst)
            COLLECTION_SCHEDULER_LAST_RUN.clear()
            COLLECTION_DAILY_RESET_DATE = today_key
            if reset_count:
                print(f"[collection-scheduler] daily reset closed {reset_count} stale collection job(s)")
        for task_id, meta in COLLECTION_TASK_REGISTRY.items():
            if not bool(meta.get("runnable")):
                continue
            cfg = _collection_task_config(db, task_id)
            if not cfg.enabled or not cfg.schedule_enabled:
                continue
            if str(cfg.schedule_time or "") != hhmm:
                continue
            key = f"{task_id}|{today_key}|{hhmm}"
            if COLLECTION_SCHEDULER_LAST_RUN.get(task_id) == key:
                continue
            COLLECTION_SCHEDULER_LAST_RUN[task_id] = key
            try:
                _collection_run_task(task_id, CollectionRunPayload(mode="schedule"), run_mode="schedule")
            except Exception as exc:
                print(f"[collection-scheduler] {task_id} failed: {exc}")


def _collection_scheduler_worker() -> None:
    while True:
        try:
            _collection_scheduler_tick()
        except Exception as exc:
            print("[collection-scheduler] tick failed:", exc)
        time.sleep(60)


def ensure_product_keyword_limit(
    db: Session,
    *,
    product_url: str,
    new_keywords_count: int,
    max_keywords: int = MAX_KEYWORDS_PER_PRODUCT,
) -> None:
    """
    특정 상품 URL 에 대해 추적 키워드를 최대 max_keywords 개까지만 허용하는 검증 함수.

    - 현재 DB 에 저장된 개수를 조회한 뒤, 새로 추가하려는 개수를 더했을 때
      한도를 초과하면 HTTPException(400)을 발생시킨다.
    """
    # (요청) 추적 키워드 한도 제한 제거
    # - 운영 중 키워드 수가 늘어도 사용자가 막히지 않도록 제한을 두지 않는다.
    # - 기존 한도 로직은 유지보수 차원에서 함수는 남겨두되, 항상 통과하도록 한다.
    return


def ensure_competitor_limit(
    db: Session,
    *,
    tracked_keyword_id: int,
    new_count: int,
    max_competitors: int = MAX_COMPETITORS_PER_TRACKED,
) -> None:
    """
    하나의 추적 키워드(tracked_keyword_id)에 등록할 수 있는 경쟁 상품 수를 제한한다.

    - 현재 등록된 개수를 조회한 뒤, 새로 추가하려는 개수를 더했을 때
      max_competitors 를 초과하면 HTTPException(400)을 발생시킨다.
    """
    existing = (
        db.query(TrackedCompetitorProduct)
        .filter(
            TrackedCompetitorProduct.tracked_keyword_id == tracked_keyword_id,
            TrackedCompetitorProduct.is_active.is_(True),
        )
        .count()
    )
    if existing + new_count > max_competitors:
        raise HTTPException(
            status_code=400,
            detail=(
                f"이 키워드에는 최대 {max_competitors}개의 경쟁 상품만 등록할 수 있습니다. "
                f"(현재 {existing}개 등록됨)"
            ),
        )


@app.on_event("startup")
def on_startup() -> None:
    """
    애플리케이션 시작 시 Analytics DB 기본 테이블을 보장한다.
    """
    try:
        init_db()
    except Exception as e:  # pragma: no cover - 단순 로그용
        # 초기 개발 단계에서는 단순 출력만, 추후 로깅 체계로 교체 가능
        print("Analytics DB 초기화 실패:", e)

    # API 재기동 시 이전 프로세스에서 STARTED로 남은 수집 job을 DB 저장 상태 기준으로 정리한다.
    try:
        with SessionLocal() as s:
            _collection_reset_stale_daily_jobs(s, now_kst=datetime.now(ZoneInfo("Asia/Seoul")))
            updated = (
                s.query(AnalyticsJobRun)
                .filter(
                    AnalyticsJobRun.job_name.like("category-crawl:%"),
                    AnalyticsJobRun.status == "STARTED",
                )
                .update(
                    {
                        "status": "FAILED",
                        "finished_at": datetime.utcnow(),
                        "detail": json.dumps(
                            {"error": "api_restart", "message": "API was restarted; job no longer running"},
                            ensure_ascii=False,
                        ),
                    },
                    synchronize_session=False,
                )
            )
            s.commit()
            if updated:
                print(f"[startup] Marked {updated} stale STARTED category-crawl job(s) as FAILED (api_restart)")
            updated_collection = 0
            stale_collection_jobs = (
                s.query(CollectionJobRun)
                .filter(
                    CollectionJobRun.status.in_(["QUEUED", "STARTED", "CLAIMED", "UPLOADING", "WAITING_USER"]),
                )
                .all()
            )
            for stale in stale_collection_jobs:
                if _collection_job_awaits_collector_pc(stale):
                    detail = _collection_json_loads(stale.detail_json) or {}
                    if not isinstance(detail, dict):
                        detail = {}
                    public = detail.get("collector_job")
                    if isinstance(public, dict):
                        public = dict(public)
                        st = str(public.get("status") or "").strip().upper()
                        if st in {"DONE", "SUCCESS", "FAILED", "PARTIAL", "CANCELLED", "SKIPPED"}:
                            public["status"] = "CLAIMED"
                        elif not st:
                            public["status"] = "CLAIMED"
                        detail["collector_job"] = public
                    detail["api_restart_pending"] = True
                    detail["message"] = "API was restarted; waiting for Host Agent to resume or submit results"
                    stale.status = "CLAIMED"
                    stale.finished_at = None
                    stale.error = None
                    stale.detail_json = _collection_json_dumps(detail)
                    db.add(stale)
                    updated_collection += 1
                    continue
                persisted = None
                final_status = "FAILED"
                error = "api_restart"
                try:
                    d0 = stale.date_from or stale.target_date or _today_kst()
                    d1 = stale.date_to or stale.target_date or d0
                    persisted = _collection_persistence_summary(s, stale.task_id, d0, d1)
                    final_status, persistence_error = _collection_apply_persistence_status(
                        stale.task_id,
                        "SUCCESS",
                        stale.rows_written,
                        persisted,
                    )
                    error = persistence_error
                except Exception:
                    persisted = None
                    final_status = "FAILED"
                    error = "api_restart"
                stale.status = final_status
                stale.finished_at = datetime.utcnow()
                stale.error = error
                prev_detail = _collection_json_loads(stale.detail_json) or {}
                if not isinstance(prev_detail, dict):
                    prev_detail = {}
                stale.detail_json = json.dumps(
                    {
                        "error": "api_restart" if final_status == "FAILED" else None,
                        "message": "API was restarted; collection job status was reconciled from DB persistence",
                        "db_persistence": persisted,
                        "collector_job": prev_detail.get("collector_job"),
                        "api_restart_reconciled": True,
                    },
                    ensure_ascii=False,
                    default=str,
                )
                s.add(stale)
                updated_collection += 1
            s.commit()
            if updated_collection:
                print(f"[startup] Reconciled {updated_collection} stale STARTED collection job(s) after api_restart")
    except Exception as e:
        try:
            with SessionLocal() as s:
                s.rollback()
        except Exception:
            pass
        print("[startup] Failed to clear stale STARTED jobs:", e)

    # REPORT_NOT_READY(20007) 백그라운드 재시도 워커 시작(데몬 스레드)
    # - app 객체 생성 이후에만 실행되어야 한다.
    global _REPORT_NOT_READY_THREAD_STARTED
    try:
        if not _REPORT_NOT_READY_THREAD_STARTED:
            th = threading.Thread(target=_report_not_ready_worker, daemon=True)
            th.start()
            _REPORT_NOT_READY_THREAD_STARTED = True
    except Exception:
        pass

    # 중앙 데이터 수집 스케줄러 시작:
    # NAS에서 가능한 API/배치 작업은 서버가 직접 실행하고, CDP 작업은 설치형 Collector PC로 위임한다.
    global COLLECTION_SCHEDULER_THREAD_STARTED
    try:
        if not COLLECTION_SCHEDULER_THREAD_STARTED:
            th = threading.Thread(target=_collection_scheduler_worker, daemon=True)
            th.start()
            COLLECTION_SCHEDULER_THREAD_STARTED = True
    except Exception:
        pass


def _analytics_health_payload() -> dict:
    db_ok = False
    try:
        with engine.connect() as conn:
            conn.execute(text("SELECT 1"))
        db_ok = True
    except Exception:
        db_ok = False

    try:
        checked_at = datetime.now(ZoneInfo("Asia/Seoul")).isoformat()
    except Exception:
        checked_at = datetime.now().isoformat()

    version = "unknown"
    image_tag_version = re.match(r"^analytics_(\d{8}_\d{6})$", _ANALYTICS_API_IMAGE_TAG or "")
    if image_tag_version:
        version = image_tag_version.group(1)
    elif _ANALYTICS_API_IMAGE_TAG:
        version = _ANALYTICS_API_IMAGE_TAG

    return {
        "service": "marketing-analytics",
        "status": "ok" if db_ok else "error",
        "environment": "production" if os.getenv("REQUIRE_FIREBASE_AUTH") == "1" else "local",
        "version": version,
        "checkedAt": checked_at,
        "database": "ok" if db_ok else "error",
        "ok": db_ok,
        "db": db_ok,
        "build": {
            "time": (_ANALYTICS_API_BUILD_TIME or None),
            "sha": (_ANALYTICS_API_GIT_SHA or None),
            "imageTag": (_ANALYTICS_API_IMAGE_TAG or None),
        },
    }


@app.get("/health")
@app.get("/api/health")
def health():
    """
    헬스체크 엔드포인트.

    - analytics-api 컨테이너가 살아 있는지 확인하는 용도
    - 추후 DB 연결 상태, SearchAd 자격증명 유효성 등을 함께 점검하도록 확장 가능
    """
    return _analytics_health_payload()


# ----------------------------
# Build / Version 증거 (무인증)
# - 되돌림(스택/태그 혼선) 판정을 위한 “증거 3종 세트” 중 API 파트
# - 운영 스크립트/모니터링에서 토큰 없이 호출 가능해야 한다.
# ----------------------------

_ANALYTICS_API_BUILD_TIME = (
    (os.getenv("ANALYTICS_BUILD_TIME") or "").strip()
    or (os.getenv("BUILD_TIME") or "").strip()
    or ""
)
_ANALYTICS_API_GIT_SHA = (
    (os.getenv("ANALYTICS_GIT_SHA") or "").strip()
    or (os.getenv("GIT_SHA") or "").strip()
    or ""
)
_ANALYTICS_API_IMAGE_TAG = (
    (os.getenv("ANALYTICS_IMAGE_TAG") or "").strip()
    or (os.getenv("IMAGE_TAG") or "").strip()
    or ""
)


def _api_version_payload() -> dict:
    # serverTime은 "지금 응답이 살아있다"를 확인하기 위한 값
    # (buildTime과 달리 요청마다 바뀌어도 괜찮다)
    try:
        server_time = datetime.now(ZoneInfo("Asia/Seoul")).isoformat()
    except Exception:
        server_time = datetime.now().isoformat()
    return {
        "status": "ok",
        "imageTag": (_ANALYTICS_API_IMAGE_TAG or None),
        "gitSha": (_ANALYTICS_API_GIT_SHA or None),
        "buildTime": (_ANALYTICS_API_BUILD_TIME or None),
        "serverTime": server_time,
    }


@app.get("/version")
def version_root():
    return _api_version_payload()


@app.get("/api/version")
def version_api_alias():
    return _api_version_payload()


# ----------------------------
# Admin: 버전관리(ERP 스타일)
# - 목적: UI에서 "버전 라벨" 저장 + 백업(설정 스냅샷 다운로드)
# - 버전 라벨은 "배포 태그(imageTag)"와 별개로, 운영자가 관리하는 표시용 문자열이다.
# - backup은 전체 스택(docker save/볼륨) 백업이 아니라, UI/설정 스냅샷을 zip으로 다운로드한다.
# ----------------------------

_APP_VERSION_KEY = "app:version_label"
_SALES_SYNC_DIAGNOSTIC_JOB_NAME = "sales:commerce:sync-diagnostic"
_DIRECT_ORDER_UNSUPPORTED_UNTIL_KEY = "sales:commerce:direct-order:unsupported-until"


def _get_app_version_label(db: Session) -> str:
    row = db.query(AppSetting).filter(AppSetting.key == _APP_VERSION_KEY).one_or_none()
    v = str(row.value or "").strip() if row else ""
    if v:
        return v
    # default: 현재 이미지 태그(증거)로 채운다.
    return str((_ANALYTICS_API_IMAGE_TAG or "").strip() or "1.0.0")


def _set_app_version_label(db: Session, version: str) -> str:
    v = str(version or "").strip()
    if not v:
        raise HTTPException(status_code=400, detail="version_required")
    row = db.query(AppSetting).filter(AppSetting.key == _APP_VERSION_KEY).one_or_none()
    if row is None:
        db.add(AppSetting(key=_APP_VERSION_KEY, value=v))
    else:
        row.value = v
    db.commit()
    return v


def _get_app_setting_value(db: Session, key: str) -> str:
    row = db.query(AppSetting).filter(AppSetting.key == str(key or "")).one_or_none()
    return str(row.value or "").strip() if row else ""


def _set_app_setting_value(db: Session, *, key: str, value: str) -> str:
    k = str(key or "").strip()
    if not k:
        raise HTTPException(status_code=400, detail="app_setting_key_required")
    row = db.query(AppSetting).filter(AppSetting.key == k).one_or_none()
    if row is None:
        db.add(AppSetting(key=k, value=str(value or "")))
    else:
        row.value = str(value or "")
    db.commit()
    return str(value or "")


def _delete_app_setting_value(db: Session, key: str) -> None:
    row = db.query(AppSetting).filter(AppSetting.key == str(key or "")).one_or_none()
    if row is None:
        return
    db.delete(row)
    db.commit()


class AdminVersionPayload(BaseModel):
    version: str = Field(..., description="표시용 버전 라벨 (예: 1.3.0)")


@app.get("/admin/version", response_model=dict)
def admin_get_version_label(request: Request, db: Session = Depends(get_db)):
    require_role_level(request, minimum="ops_admin")
    return {"version": _get_app_version_label(db)}


@app.post("/admin/version", response_model=dict)
def admin_set_version_label(payload: AdminVersionPayload, request: Request, db: Session = Depends(get_db)):
    require_role_level(request, minimum="ops_admin")
    v = _set_app_version_label(db, payload.version)
    return {"ok": True, "version": v}


@app.post("/admin/backup")
def admin_backup_bundle(
    request: Request,
    db: Session = Depends(get_db),
    type: str = Query("ops_code", description="백업 타입: ops_code | db | full"),
):
    """
    백업 번들(zip)을 내려받는다.

    타입:
    - ops_code: 운영코드(설정/증거) 백업(시크릿 포함 가능 → superadmin 전용)
    - db: DB 백업(데이터 보호용 → ops_admin 이상)
    - full: ops_code + db (superadmin 전용)

    주의:
    - 이 엔드포인트는 '호스트 docker save/볼륨 tar' 같은 전체 스택 백업이 아니다.
      (그 기능은 운영 스크립트/호스트 백업에서 수행한다.)
    """
    backup_type = str(type or "").strip().lower()
    if backup_type in ("ops", "ops_code", "code"):
        backup_type = "ops_code"
        require_role_level(request, minimum="superadmin")
    elif backup_type in ("db", "database"):
        backup_type = "db"
        require_role_level(request, minimum="ops_admin")
    elif backup_type in ("full",):
        backup_type = "full"
        require_role_level(request, minimum="superadmin")
    else:
        raise HTTPException(status_code=400, detail="invalid_backup_type")

    # 1) 메타(증거)
    version_label = _get_app_version_label(db)
    api_meta = _api_version_payload()

    def _db_dump_bytes() -> dict:
        """
        Postgres 운영: pg_dump/pg_dumpall로 덤프 생성.
        테스트(SQLite): iterdump로 SQL 생성.
        """
        dialect = ""
        try:
            dialect = str(getattr(db.get_bind().dialect, "name", "") or "").lower()  # type: ignore[attr-defined]
        except Exception:
            dialect = ""

        if "sqlite" in dialect:
            # 테스트 환경: in-memory sqlite 덤프
            try:
                raw_conn = db.connection().connection  # type: ignore[attr-defined]
                lines = list(raw_conn.iterdump())
                return {
                    "db/analytics.sql": ("\n".join(lines) + "\n").encode("utf-8"),
                    "db/globals.sql": b"-- sqlite test mode\n",
                }
            except Exception as e:
                raise HTTPException(status_code=500, detail=f"sqlite_dump_failed: {e}")

        # 운영(Postgres) 덤프: pg_dump 16+ 권장(서버와 major 불일치 시 실패할 수 있음)
        db_url = str(os.getenv("ANALYTICS_DB_URL") or "").strip()
        if not db_url:
            raise HTTPException(status_code=500, detail="ANALYTICS_DB_URL not configured")
        u = urlparse(db_url)
        host = u.hostname or "localhost"
        port = int(u.port or 5432)
        user = u.username or "analytics"
        password = u.password or ""
        dbname = (u.path or "/analytics").lstrip("/") or "analytics"

        base_env = dict(os.environ)
        if password:
            base_env["PGPASSWORD"] = password

        def _run_dump(args: list[str], *, binary: bool) -> bytes:
            try:
                p = subprocess.run(
                    args,
                    env=base_env,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    check=False,
                )
            except FileNotFoundError:
                raise HTTPException(status_code=500, detail="pg_dump not available in api container")
            if p.returncode != 0:
                err = (p.stderr or b"").decode("utf-8", errors="replace")
                raise HTTPException(status_code=500, detail=f"db_dump_failed: {err[:8000]}")
            return bytes(p.stdout or b"") if binary else bytes(p.stdout or b"")

        common = ["-h", host, "-p", str(port), "-U", user]
        dump_fc = _run_dump(["pg_dump"] + common + ["-d", dbname, "-Fc"], binary=True)
        dump_sql = _run_dump(["pg_dump"] + common + ["-d", dbname, "--no-owner", "--no-privileges"], binary=True)
        globals_sql = _run_dump(["pg_dumpall"] + common + ["--globals-only"], binary=True)

        return {
            "db/analytics.dump": dump_fc,
            "db/analytics.sql": dump_sql,
            "db/globals.sql": globals_sql,
        }

    settings_dump = None
    if backup_type in ("ops_code", "full"):
        # settings dump (주의: api:* 키에는 시크릿이 포함될 수 있다. superadmin만 허용)
        rows = db.query(AppSetting).order_by(AppSetting.key.asc()).all()
        settings_dump = [
            {
                "key": str(r.key),
                "value": str(r.value or ""),
                "updated_at": (r.updated_at.isoformat() if getattr(r, "updated_at", None) else None),
            }
            for r in (rows or [])
        ]

    db_dump = None
    if backup_type in ("db", "full"):
        db_dump = _db_dump_bytes()

    # 3) zip 생성(in-memory)
    now_kst = datetime.now(ZoneInfo("Asia/Seoul"))
    ts = now_kst.strftime("%Y%m%d_%H%M%S")
    filename = f"analytics_backup_{backup_type}_{ts}_{version_label}.zip"

    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("meta/version_label.txt", version_label + "\n")
        zf.writestr("meta/api_version.json", json.dumps(api_meta, ensure_ascii=False, indent=2))
        zf.writestr("meta/backup_type.txt", backup_type + "\n")
        if settings_dump is not None:
            zf.writestr("settings/app_settings.json", json.dumps(settings_dump, ensure_ascii=False, indent=2))
        if db_dump:
            for name, data in db_dump.items():
                zf.writestr(name, data)
        zf.writestr(
            "README.txt",
            "\n".join(
                [
                    "Analytics backup bundle",
                    "",
                    f"- meta/backup_type.txt : 백업 타입({backup_type})",
                    "- meta/version_label.txt : 운영자가 저장한 표시용 버전 라벨",
                    "- meta/api_version.json  : /api/version 응답(배포 태그/빌드 시각 증거)",
                    "- settings/app_settings.json : AppSetting 전체 덤프(시크릿 포함 가능, ops_code/full에만 포함)",
                    "- db/* : DB 덤프(db/full에만 포함)",
                    "",
                    "주의: 이 백업은 호스트(docker save/볼륨 tar) 기반의 '전체 스택 백업'이 아닙니다.",
                    "      (전체 스택 백업은 운영 스크립트로 수행하세요.)",
                ]
            )
            + "\n",
        )
    buf.seek(0)

    headers = {"Content-Disposition": f'attachment; filename="{filename}"'}
    return StreamingResponse(buf, media_type="application/zip", headers=headers)


# ----------------------------
# Admin: 사용자 관리 (Firebase Auth 사용자/커스텀클레임 관리)
# - ERP와 동일한 roles/role(legacy) 스키마를 사용한다.
# - roles: superadmin | ops_admin | accounting | sales | marketing
# - legacy role: admin | accounting | sales | marketing
# - ops_admin 이상만 사용자 목록/비밀번호/비활성화/역할 변경 가능
# - superadmin만: superadmin 부여, 삭제
# ----------------------------


