def _review_qna_tag_cloud_display_parts(tag: str) -> tuple[str, str, str]:
    tag0 = str(tag or "").strip()
    mapped = REVIEW_QNA_TAG_CLOUD_TRANSLATIONS.get(tag0.lower()) or REVIEW_QNA_TAG_CLOUD_TRANSLATIONS.get(tag0)
    if mapped:
        ko, en = mapped
        return ko, en, f"{ko}({en})"
    if re.search(r"[가-힣]", tag0):
        return tag0, "", tag0
    return tag0, tag0, tag0


def _review_qna_tag_cloud_sentiment(text_value: object) -> str:
    text0 = re.sub(r"\s+", " ", str(text_value or "")).strip().lower()
    if not text0:
        return "neutral"
    positive = sum(1 for hint in REVIEW_QNA_TAG_CLOUD_POSITIVE_HINTS if hint in text0)
    negative = sum(1 for hint in REVIEW_QNA_TAG_CLOUD_NEGATIVE_HINTS if hint in text0)
    if positive > negative:
        return "positive"
    if negative > positive:
        return "negative"
    if positive > 0 and negative > 0:
        return "mixed"
    return "neutral"


def _review_qna_tag_cloud_sentiment_label(positive: int, negative: int, neutral: int, mixed: int) -> str:
    if negative > positive and negative >= max(1, neutral, mixed):
        return "negative"
    if positive > negative and positive >= max(1, neutral, mixed):
        return "positive"
    if mixed > 0 or (positive > 0 and negative > 0):
        return "mixed"
    return "neutral"


def _review_qna_tag_cloud_normalize_range(
    from_date: date | None,
    to_date: date | None,
) -> tuple[date, date]:
    today = _today_kst()
    if from_date is None and to_date is None:
        return today - timedelta(days=29), today
    if from_date is None and to_date is not None:
        return to_date - timedelta(days=29), to_date
    if from_date is not None and to_date is None:
        return from_date, from_date
    assert from_date is not None and to_date is not None
    return (to_date, from_date) if from_date > to_date else (from_date, to_date)


def _review_qna_tag_cloud_normalize_token(token: str) -> str:
    token0 = str(token or "").strip().lower()
    if len(token0) < 2 or token0.isdigit() or REVIEW_QNA_TAG_CLOUD_QUANTITY_RE.match(token0):
        return ""
    if token0 in REVIEW_QNA_TAG_CLOUD_STOPWORDS:
        return ""
    for suffix in REVIEW_QNA_TAG_CLOUD_SUFFIXES:
        if token0.endswith(suffix) and len(token0) - len(suffix) >= 2:
            token0 = token0[: -len(suffix)]
            break
    token0 = token0.strip()
    if token0 in REVIEW_QNA_TAG_CLOUD_BARE_PREDICATES:
        return ""
    for stem, normalized in REVIEW_QNA_TAG_CLOUD_PREDICATE_STEMS:
        if token0.endswith(stem) and len(token0) > len(stem):
            token0 = token0[: -len(stem)] + normalized
            break
    if (
        len(token0) < 2
        or token0.isdigit()
        or REVIEW_QNA_TAG_CLOUD_QUANTITY_RE.match(token0)
        or token0 in REVIEW_QNA_TAG_CLOUD_STOPWORDS
        or token0 in REVIEW_QNA_TAG_CLOUD_BARE_PREDICATES
    ):
        return ""
    return token0


def _review_qna_tag_cloud_predicate(token: str) -> str:
    token0 = re.sub(r"\s+", " ", str(token or "")).strip().lower()
    if not token0:
        return ""
    for stem, normalized in REVIEW_QNA_TAG_CLOUD_PREDICATE_STEMS:
        if token0.startswith(stem.replace(" ", "")) or token0.startswith(stem):
            return normalized
    return ""


def _review_qna_tag_cloud_can_be_subject(token: str) -> bool:
    token0 = str(token or "").strip()
    if not token0 or token0 in REVIEW_QNA_TAG_CLOUD_STOPWORDS or token0 in REVIEW_QNA_TAG_CLOUD_BARE_PREDICATES:
        return False
    if REVIEW_QNA_TAG_CLOUD_QUANTITY_RE.match(token0):
        return False
    return bool(re.search(r"[가-힣A-Za-z]", token0))


def _review_qna_tag_cloud_tokens(text_value: object) -> list[str]:
    text0 = re.sub(r"\s+", " ", str(text_value or "")).strip().lower()
    if not text0:
        return []
    tokens = re.findall(r"[가-힣A-Za-z0-9]{2,}", text0)
    out: list[str] = []
    last_subject = ""
    for token in tokens:
        predicate = _review_qna_tag_cloud_predicate(token)
        if predicate and last_subject:
            phrase = _review_qna_tag_cloud_normalize_token(f"{last_subject}{predicate}")
            if phrase:
                out.append(phrase)
        if predicate:
            continue
        token0 = _review_qna_tag_cloud_normalize_token(token)
        if not token0:
            continue
        out.append(token0)
        if _review_qna_tag_cloud_can_be_subject(token0):
            last_subject = token0
    return out


def _review_qna_tag_cloud_items(
    counter: dict[str, dict[str, int]],
    *,
    limit: int,
) -> list[dict]:
    max_count = max((int(item.get("total", 0) or 0) for item in counter.values()), default=0)
    items: list[dict] = []
    for tag, counts in counter.items():
        total = int(counts.get("total", 0) or 0)
        if total <= 0:
            continue
        tag_ko, tag_en, display_tag = _review_qna_tag_cloud_display_parts(tag)
        positive_count = int(counts.get("positive", 0) or 0)
        negative_count = int(counts.get("negative", 0) or 0)
        neutral_count = int(counts.get("neutral", 0) or 0)
        mixed_count = int(counts.get("mixed", 0) or 0)
        sentiment = _review_qna_tag_cloud_sentiment_label(positive_count, negative_count, neutral_count, mixed_count)
        items.append(
            {
                "tag": tag,
                "tag_ko": tag_ko,
                "tag_en": tag_en,
                "display_tag": display_tag,
                "count": total,
                "review_count": int(counts.get("review", 0) or 0),
                "qna_count": int(counts.get("qna", 0) or 0),
                "positive_count": positive_count,
                "negative_count": negative_count,
                "neutral_count": neutral_count,
                "mixed_count": mixed_count,
                "sentiment": sentiment,
                "sentiment_label": {
                    "positive": "긍정",
                    "negative": "부정",
                    "mixed": "혼합",
                    "neutral": "중립",
                }.get(sentiment, "중립"),
                "weight": round(total / max(1, max_count), 4),
            }
        )
    return sorted(items, key=lambda item: (-int(item["count"]), str(item["tag"])))[:limit]


def _review_qna_tag_cloud_increment(counter: dict[str, dict[str, int]], source: str, tokens: list[str], sentiment: str) -> None:
    for token in tokens:
        bucket = counter.setdefault(token, {"total": 0, "review": 0, "qna": 0, "positive": 0, "negative": 0, "neutral": 0, "mixed": 0})
        bucket["total"] += 1
        bucket[source] += 1
        if sentiment not in {"positive", "negative", "neutral", "mixed"}:
            sentiment = "neutral"
        bucket[sentiment] += 1


def _build_review_qna_tag_cloud(
    db: Session,
    *,
    from_date: date | None,
    to_date: date | None,
    sources: str,
    limit: int,
) -> dict:
    start_date, end_date = _review_qna_tag_cloud_normalize_range(from_date, to_date)
    source_tokens = {x.strip().lower() for x in str(sources or "all").split(",") if x.strip()}
    include_reviews = not source_tokens or "all" in source_tokens or "review" in source_tokens or "reviews" in source_tokens
    include_qna = not source_tokens or "all" in source_tokens or "qna" in source_tokens

    combined_counts: dict[str, dict[str, int]] = {}
    review_counts: dict[str, dict[str, int]] = {}
    qna_counts: dict[str, dict[str, int]] = {}
    source_info = {
        "review_rows": 0,
        "qna_rows": 0,
        "review_token_count": 0,
        "qna_token_count": 0,
    }

    if include_reviews:
        review_rows = (
            db.query(NaverReviewRaw)
            .filter(NaverReviewRaw.review_written_at >= start_date)
            .filter(NaverReviewRaw.review_written_at <= end_date)
            .order_by(NaverReviewRaw.review_written_at.desc(), NaverReviewRaw.review_key.asc())
            .limit(10000)
            .all()
        )
        source_info["review_rows"] = len(review_rows)
        for row in review_rows:
            text_blob = " ".join(
                [
                    str(getattr(row, "product_title", "") or ""),
                    str(getattr(row, "option_text", "") or ""),
                    str(getattr(row, "review_text", "") or ""),
                ]
            )
            tokens = _review_qna_tag_cloud_tokens(text_blob)
            sentiment = _review_qna_tag_cloud_sentiment(text_blob)
            source_info["review_token_count"] += len(tokens)
            _review_qna_tag_cloud_increment(combined_counts, "review", tokens, sentiment)
            _review_qna_tag_cloud_increment(review_counts, "review", tokens, sentiment)

    if include_qna:
        qna_rows = (
            db.query(CommerceQnaRaw)
            .filter(func.date(CommerceQnaRaw.inquiry_registered_at) >= start_date)
            .filter(func.date(CommerceQnaRaw.inquiry_registered_at) <= end_date)
            .order_by(CommerceQnaRaw.inquiry_registered_at.desc(), CommerceQnaRaw.qna_key.asc())
            .limit(10000)
            .all()
        )
        source_info["qna_rows"] = len(qna_rows)
        for row in qna_rows:
            text_blob = " ".join(
                [
                    str(getattr(row, "title", "") or ""),
                    str(getattr(row, "category", "") or ""),
                    str(getattr(row, "product_name", "") or ""),
                    str(getattr(row, "inquiry_text", "") or ""),
                ]
            )
            tokens = _review_qna_tag_cloud_tokens(text_blob)
            sentiment = _review_qna_tag_cloud_sentiment(text_blob)
            source_info["qna_token_count"] += len(tokens)
            _review_qna_tag_cloud_increment(combined_counts, "qna", tokens, sentiment)
            _review_qna_tag_cloud_increment(qna_counts, "qna", tokens, sentiment)

    return {
        "ok": True,
        "date_from": start_date.isoformat(),
        "date_to": end_date.isoformat(),
        "sources": {
            "review": include_reviews,
            "qna": include_qna,
        },
        "source_info": source_info,
        "combined": _review_qna_tag_cloud_items(combined_counts, limit=limit),
        "review": _review_qna_tag_cloud_items(review_counts, limit=limit),
        "qna": _review_qna_tag_cloud_items(qna_counts, limit=limit),
    }


