@app.post("/reviews/import-smartstore-file", response_model=ReviewImportSmartstoreResponse)
async def import_smartstore_review_file(
    file: UploadFile = File(...),
    db: Session = Depends(get_db),
):
    content = await file.read()
    if not content:
        raise HTTPException(status_code=400, detail="empty file")

    df = _read_smartstore_review_upload(content, getattr(file, "filename", None))
    items, errors = _normalize_smartstore_review_upload_df(df)
    if errors:
        raise HTTPException(status_code=400, detail="; ".join(errors))
    if not items:
        raise HTTPException(status_code=400, detail="리뷰 행을 찾지 못했습니다.")

    matched_product_keys: set[str] = set()
    unmatched_product_keys: set[str] = set()
    for item in items:
        fallback_url = str(item.get("product_url") or "").strip()
        resolved_url = _resolve_uploaded_review_product_url(
            db,
            product_id=_safe_int(item.get("product_id_catalog")),
            product_title=str(item.get("product_title") or "").strip() or None,
            fallback_url=fallback_url,
        )
        item["product_url"] = resolved_url
        product_key = str(item.get("product_id_catalog") or item.get("product_title") or resolved_url or "").strip()
        if resolved_url and resolved_url != fallback_url and resolved_url.startswith("https://smartstore.naver.com/"):
            matched_product_keys.add(product_key)
        else:
            unmatched_product_keys.add(product_key)

    grouped: dict[str, list[dict]] = {}
    for item in items:
        product_url = str(item.get("product_url") or "").strip()
        if not product_url:
            continue
        grouped.setdefault(product_url, []).append(item)

    saved_reviews = 0
    saved_replies = 0
    for product_url, group_items in grouped.items():
        result = _upsert_review_raw_items(db, product_url=product_url, items=group_items)
        saved_reviews += int(result.get("saved_reviews") or 0)
        saved_replies += int(result.get("saved_replies") or 0)

    reply_exists_rows = sum(1 for item in items if bool(item.get("reply_exists_flag")))
    reply_backfill_targets = sum(
        1 for item in items if bool(item.get("reply_exists_flag")) and not _collapse_ws_text(item.get("reply_text"))
    )
    imported_dates = sorted(
        {
            value
            for value in (item.get("review_written_at") for item in items)
            if isinstance(value, date)
        }
    )
    return ReviewImportSmartstoreResponse(
        ok=True,
        filename=str(getattr(file, "filename", None) or "upload"),
        processed_rows=len(items),
        saved_reviews=saved_reviews,
        saved_replies=saved_replies,
        reply_exists_rows=reply_exists_rows,
        reply_backfill_targets=reply_backfill_targets,
        matched_products=len(matched_product_keys),
        unmatched_products=len(unmatched_product_keys),
        imported_date_from=imported_dates[0] if imported_dates else None,
        imported_date_to=imported_dates[-1] if imported_dates else None,
        detail="상품번호가 추적 상품 URL과 일치하면 실제 스마트스토어 URL로 저장합니다. 답글여부=Y 이면서 본문이 없는 리뷰는 판매자센터 보강 대상으로 저장했습니다.",
    )


REVIEW_REPLY_BACKFILL_JOB_PREFIX = "review-reply-backfill"
REVIEW_REPLY_BACKFILL_BATCH_SIZE = 1
REVIEW_REPLY_BACKFILL_STALE_MINUTES = 20


def _count_reply_backfill_target_rows(db: Session) -> int:
    return len(_list_reply_backfill_target_rows(db, limit=1000000))


def _review_reply_backfill_job_name(job_id: str) -> str:
    return f"{REVIEW_REPLY_BACKFILL_JOB_PREFIX}:{str(job_id or '').strip()}"


def _get_review_reply_backfill_job_row(db: Session, *, job_id: str | None = None) -> AnalyticsJobRun | None:
    if str(job_id or "").strip():
        return (
            db.query(AnalyticsJobRun)
            .filter(AnalyticsJobRun.job_name == _review_reply_backfill_job_name(str(job_id or "").strip()))
            .one_or_none()
        )
    return (
        db.query(AnalyticsJobRun)
        .filter(AnalyticsJobRun.job_name.like(f"{REVIEW_REPLY_BACKFILL_JOB_PREFIX}:%"))
        .order_by(AnalyticsJobRun.started_at.desc(), AnalyticsJobRun.run_date.desc())
        .first()
    )


def _serialize_review_reply_backfill_job_response(
    row: AnalyticsJobRun | None,
    *,
    scheduled: bool = False,
    fallback_detail: str | None = None,
) -> ReviewReplyBackfillJobResponse:
    if row is None:
        return ReviewReplyBackfillJobResponse(
            ok=True,
            scheduled=scheduled,
            job_id=None,
            status="IDLE",
            detail=fallback_detail,
        )
    detail_payload: dict[str, object] = {}
    try:
        raw_detail = getattr(row, "detail", None)
        if raw_detail:
            parsed = json.loads(raw_detail)
            if isinstance(parsed, dict):
                detail_payload = parsed
    except Exception:
        detail_payload = {}
    job_name = str(getattr(row, "job_name", "") or "").strip()
    job_id_value = str(detail_payload.get("job_id") or "").strip()
    if not job_id_value and job_name.startswith(f"{REVIEW_REPLY_BACKFILL_JOB_PREFIX}:"):
        job_id_value = job_name.split(":", 1)[1].strip()
    detail_text = str(detail_payload.get("detail") or getattr(row, "detail", None) or fallback_detail or "").strip() or None
    return ReviewReplyBackfillJobResponse(
        ok=True,
        scheduled=scheduled,
        job_id=job_id_value or None,
        status=str(getattr(row, "status", "") or "IDLE"),
        pending_targets=int(detail_payload.get("pending_targets") or 0),
        processed=int(detail_payload.get("processed") or 0),
        collected=int(detail_payload.get("collected") or 0),
        failed=int(detail_payload.get("failed") or 0),
        skipped=int(detail_payload.get("skipped") or 0),
        detail=detail_text,
        started_at=getattr(row, "started_at", None),
        finished_at=getattr(row, "finished_at", None),
    )


def _save_review_reply_backfill_job_state(
    *,
    job_id: str,
    run_date: date,
    status: str,
    pending_targets: int,
    processed: int,
    collected: int,
    failed: int,
    skipped: int,
    detail: str,
    finished: bool = False,
) -> None:
    job_name = _review_reply_backfill_job_name(job_id)
    now = datetime.utcnow()
    payload = {
        "job_id": job_id,
        "pending_targets": int(pending_targets or 0),
        "processed": int(processed or 0),
        "collected": int(collected or 0),
        "failed": int(failed or 0),
        "skipped": int(skipped or 0),
        "detail": str(detail or "").strip(),
    }
    with SessionLocal() as db:
        row = (
            db.query(AnalyticsJobRun)
            .filter(
                AnalyticsJobRun.job_name == job_name,
                AnalyticsJobRun.run_date == run_date,
            )
            .one_or_none()
        )
        if row is None:
            row = AnalyticsJobRun(job_name=job_name, run_date=run_date)
            db.add(row)
        row.status = str(status or "").strip() or "STARTED"
        row.detail = json.dumps(payload, ensure_ascii=False)
        if str(row.status).upper() == "STARTED":
            row.started_at = now
            row.finished_at = None
        elif finished:
            row.finished_at = now
        db.commit()


def _process_review_reply_backfill_target_rows(
    db: Session,
    *,
    target_rows: list[NaverReviewRaw],
    max_pages: int,
    cdp_url_override: str | None = None,
) -> tuple[list[ReviewReplyBackfillItem], int, int, int]:
    target_review_ids = [
        str(getattr(row, "review_id_original", "") or "").strip()
        for row in target_rows
        if str(getattr(row, "review_id_original", "") or "").strip()
    ]
    candidates, timed_out_review_ids = _collect_smartstore_admin_reply_candidates_resilient(
        max_pages=max_pages,
        target_review_ids=target_review_ids,
        cdp_url_override=cdp_url_override,
    )
    candidate_map = {
        str(item.get("review_id_original") or "").strip(): item
        for item in candidates
        if str(item.get("review_id_original") or "").strip()
    }

    items: list[ReviewReplyBackfillItem] = []
    collected = 0
    failed = 0
    skipped = 0
    for review_row in target_rows:
        review_key = str(getattr(review_row, "review_key", "") or "").strip()
        review_id_original = str(getattr(review_row, "review_id_original", "") or "").strip() or None
        product_title = str(getattr(review_row, "product_title", "") or "").strip() or None
        recheck_only = not bool(getattr(review_row, "reply_exists_flag", False))
        if review_id_original and review_id_original in timed_out_review_ids:
            failed += 1
            review_row.reply_collect_status = "failed"
            items.append(
                ReviewReplyBackfillItem(
                    review_key=review_key,
                    review_id_original=review_id_original,
                    product_title=product_title,
                    status="failed",
                    detail="판매자센터 응답 지연으로 단건 보강 작업이 timeout 되었습니다. 다음 실행에서 다시 시도할 수 있습니다.",
                    reply_written_at=None,
                )
            )
            continue
        matched = candidate_map.get(review_id_original or "")
        if not matched:
            skipped += 1
            review_row.reply_collect_status = "verified_absent" if recheck_only else "not_found"
            items.append(
                ReviewReplyBackfillItem(
                    review_key=review_key,
                    review_id_original=review_id_original,
                    product_title=product_title,
                    status="verified_absent" if recheck_only else "not_found",
                    detail=(
                        "판매자센터 재검증 결과 현재 등록된 답글이 없는 것으로 확인했습니다."
                        if recheck_only
                        else "판매자센터 크롤링 결과에서 일치하는 답글 본문을 찾지 못했습니다."
                    ),
                    reply_written_at=None,
                )
            )
            continue

        reply_text = _collapse_ws_text(matched.get("reply_text"))
        if not reply_text:
            failed += 1
            review_row.reply_collect_status = "failed"
            items.append(
                ReviewReplyBackfillItem(
                    review_key=review_key,
                    review_id_original=review_id_original,
                    product_title=product_title,
                    status="failed",
                    detail="일치 항목은 찾았지만 답글 본문 파싱에 실패했습니다.",
                    reply_written_at=None,
                )
            )
            continue
        if not is_valid_reply_body(reply_text):
            failed += 1
            _hold_invalid_remote_reply_bodies(
                db,
                {review_id_original: {"text": reply_text, "reason": classify_reply_body(reply_text)}},
                source="smartstore_seller_center_crawl",
            )
            items.append(
                ReviewReplyBackfillItem(
                    review_key=review_key,
                    review_id_original=review_id_original,
                    product_title=product_title,
                    status="failed",
                    detail="답글 본문이 유효하지 않아(숫자/UI 문구) 저장하지 않고 보류했습니다.",
                    reply_written_at=None,
                )
            )
            continue

        reply_row: NaverReviewReplyRaw | None = (
            db.query(NaverReviewReplyRaw)
            .filter(NaverReviewReplyRaw.review_key == review_key)
            .one_or_none()
        )
        if reply_row is None:
            reply_row = NaverReviewReplyRaw(review_key=review_key)
            db.add(reply_row)
        else:
            _audit_replaced_invalid_reply_body(
                db,
                review_key=review_key,
                review_id_original=review_id_original,
                previous_text=reply_row.reply_text,
                replacement_text=reply_text,
                source="smartstore_seller_center_crawl",
            )
        reply_written_at = matched.get("reply_written_at")
        if isinstance(reply_written_at, str):
            reply_written_at = _parse_review_date_text(reply_written_at)
        if reply_written_at is not None and not isinstance(reply_written_at, date):
            reply_written_at = None
        reply_row.reply_text = reply_text
        reply_row.reply_written_at = reply_written_at
        reply_row.raw_payload_json = json.dumps(
            {
                "source": "smartstore_seller_center_crawl",
                "review_id_original": review_id_original,
                "reply_text": reply_text,
                "reply_written_at": reply_written_at.isoformat() if isinstance(reply_written_at, date) else None,
            },
            ensure_ascii=False,
        )
        review_row.reply_exists_flag = True
        review_row.reply_collect_status = "collected"
        collected += 1
        items.append(
            ReviewReplyBackfillItem(
                review_key=review_key,
                review_id_original=review_id_original,
                product_title=product_title,
                status="collected",
                detail="판매자센터에서 답글 본문을 보강했습니다.",
                reply_written_at=reply_written_at,
            )
        )
    db.commit()
    return items, collected, failed, skipped


def _run_review_reply_backfill_job(
    *,
    job_id: str,
    run_date: date,
    max_pages: int,
    total_limit: int | None,
    cdp_url_override: str | None = None,
) -> None:
    processed = 0
    collected = 0
    failed = 0
    skipped = 0
    attempted_review_keys: set[str] = set()
    try:
        while True:
            remaining_limit = None if total_limit is None else max(0, int(total_limit) - processed)
            if remaining_limit is not None and remaining_limit <= 0:
                break
            with SessionLocal() as db:
                pending_targets = _count_reply_backfill_target_rows(db)
                if pending_targets <= 0:
                    break
                batch_limit = REVIEW_REPLY_BACKFILL_BATCH_SIZE
                if remaining_limit is not None:
                    batch_limit = max(1, min(batch_limit, remaining_limit))
                target_rows = _list_reply_backfill_target_rows(
                    db,
                    limit=batch_limit,
                    exclude_review_keys=attempted_review_keys,
                )
                if not target_rows:
                    break
                attempted_review_keys.update(
                    str(getattr(row, "review_key", "") or "").strip()
                    for row in target_rows
                    if str(getattr(row, "review_key", "") or "").strip()
                )
                batch_items, batch_collected, batch_failed, batch_skipped = _process_review_reply_backfill_target_rows(
                    db,
                    target_rows=target_rows,
                    max_pages=max_pages,
                    cdp_url_override=cdp_url_override,
                )
                processed += len(batch_items)
                collected += batch_collected
                failed += batch_failed
                skipped += batch_skipped
                _save_review_reply_backfill_job_state(
                    job_id=job_id,
                    run_date=run_date,
                    status="STARTED",
                    pending_targets=max(0, _count_reply_backfill_target_rows(db)),
                    processed=processed,
                    collected=collected,
                    failed=failed,
                    skipped=skipped,
                    detail="답글 본문 보강 작업을 진행 중입니다.",
                )
        final_status = "SUCCESS"
        if failed > 0 and (collected > 0 or skipped > 0):
            final_status = "PARTIAL"
        elif failed > 0 and collected == 0 and skipped == 0:
            final_status = "FAILED"
        with SessionLocal() as db:
            _save_review_reply_backfill_job_state(
                job_id=job_id,
                run_date=run_date,
                status=final_status,
                pending_targets=_count_reply_backfill_target_rows(db),
                processed=processed,
                collected=collected,
                failed=failed,
                skipped=skipped,
                detail="답글 본문 보강 작업이 완료되었습니다.",
                finished=True,
            )
    except HTTPException as exc:
        with SessionLocal() as db:
            _save_review_reply_backfill_job_state(
                job_id=job_id,
                run_date=run_date,
                status="FAILED",
                pending_targets=_count_reply_backfill_target_rows(db),
                processed=processed,
                collected=collected,
                failed=failed + 1,
                skipped=skipped,
                detail=str(getattr(exc, "detail", "") or "reply_backfill_failed"),
                finished=True,
            )
    except Exception as exc:
        with SessionLocal() as db:
            _save_review_reply_backfill_job_state(
                job_id=job_id,
                run_date=run_date,
                status="FAILED",
                pending_targets=_count_reply_backfill_target_rows(db),
                processed=processed,
                collected=collected,
                failed=failed + 1,
                skipped=skipped,
                detail=str(exc or "reply_backfill_failed"),
                finished=True,
            )


@app.post("/reviews/reply-backfill/start", response_model=ReviewReplyBackfillJobResponse)
def start_review_reply_backfill(
    req: ReviewReplyBackfillRequest,
    request: Request,
    background_tasks: BackgroundTasks,
    db: Session = Depends(get_db),
):
    latest_job = _get_review_reply_backfill_job_row(db)
    if latest_job is not None and str(getattr(latest_job, "status", "") or "").upper() == "STARTED":
        started_at = getattr(latest_job, "started_at", None)
        if started_at is not None and started_at.replace(tzinfo=None) > (datetime.utcnow() - timedelta(minutes=REVIEW_REPLY_BACKFILL_STALE_MINUTES)):
            return _serialize_review_reply_backfill_job_response(
                latest_job,
                scheduled=False,
                fallback_detail="이미 답글 본문 보강 작업이 진행 중입니다.",
            )
    pending_targets = _count_reply_backfill_target_rows(db)
    if pending_targets <= 0:
        return ReviewReplyBackfillJobResponse(
            ok=True,
            scheduled=False,
            status="SUCCESS",
            pending_targets=0,
            detail="보강할 답글 대상이 없습니다.",
        )
    total_limit = int(req.limit or 0)
    if total_limit > 0:
        pending_targets = min(pending_targets, total_limit)
    max_pages = max(1, min(int(req.max_pages or 30), 50))
    cdp_url_override = _host_cdp_override_url_from_request(
        request,
        explicit_ip=(request.headers.get("x-erp2-client-ip") or getattr(req, "client_ip", None)),
    )
    run_date = _today_kst()
    job_id = hashlib.sha256(f"reply-backfill|{time.time()}|{random.random()}".encode("utf-8")).hexdigest()[:16]
    _save_review_reply_backfill_job_state(
        job_id=job_id,
        run_date=run_date,
        status="STARTED",
        pending_targets=pending_targets,
        processed=0,
        collected=0,
        failed=0,
        skipped=0,
        detail="답글 본문 보강 작업을 시작했습니다.",
    )
    background_tasks.add_task(
        _run_review_reply_backfill_job,
        job_id=job_id,
        run_date=run_date,
        max_pages=max_pages,
        total_limit=(total_limit if total_limit > 0 else None),
        cdp_url_override=cdp_url_override,
    )
    row = _get_review_reply_backfill_job_row(db, job_id=job_id)
    return _serialize_review_reply_backfill_job_response(
        row,
        scheduled=True,
        fallback_detail="답글 본문 보강 작업을 시작했습니다.",
    )


@app.get("/reviews/reply-backfill/status", response_model=ReviewReplyBackfillJobResponse)
def get_review_reply_backfill_status(
    job_id: str | None = Query(None, description="답글 본문 보강 작업 ID"),
    db: Session = Depends(get_db),
):
    row = _get_review_reply_backfill_job_row(db, job_id=job_id)
    if row is None:
        pending_targets = _count_reply_backfill_target_rows(db)
        if pending_targets <= 0:
            return ReviewReplyBackfillJobResponse(
                ok=True,
                scheduled=False,
                status="SUCCESS",
                pending_targets=0,
                detail="보강할 답글 대상이 없습니다.",
            )
        return ReviewReplyBackfillJobResponse(
            ok=True,
            scheduled=False,
            status="IDLE",
            pending_targets=pending_targets,
            detail="아직 시작된 답글 본문 보강 작업이 없습니다.",
        )
    return _serialize_review_reply_backfill_job_response(row, scheduled=False)


@app.post("/reviews/reply-backfill/enrich", response_model=ReviewReplyBackfillResponse)
def enrich_review_reply_backfill(
    req: ReviewReplyBackfillRequest,
    request: Request,
    db: Session = Depends(get_db),
):
    batch_size = max(1, min(int(req.limit or REVIEW_REPLY_BACKFILL_BATCH_SIZE), 100))
    page_limit = max(1, min(int(req.max_pages or 30), 50))
    attempted_review_keys: set[str] = set()
    items: list[ReviewReplyBackfillItem] = []
    collected = 0
    failed = 0
    skipped = 0
    while True:
        target_rows = _list_reply_backfill_target_rows(
            db,
            limit=batch_size,
            exclude_review_keys=attempted_review_keys,
        )
        if not target_rows:
            break
        attempted_review_keys.update(
            str(getattr(row, "review_key", "") or "").strip()
            for row in target_rows
            if str(getattr(row, "review_key", "") or "").strip()
        )
        batch_items, batch_collected, batch_failed, batch_skipped = _process_review_reply_backfill_target_rows(
            db,
            target_rows=target_rows,
            max_pages=page_limit,
            cdp_url_override=_host_cdp_override_url_from_request(
                request,
                explicit_ip=(request.headers.get("x-erp2-client-ip") or getattr(req, "client_ip", None)),
            ),
        )
        items.extend(batch_items)
        collected += batch_collected
        failed += batch_failed
        skipped += batch_skipped

    if not items:
        return ReviewReplyBackfillResponse(
            ok=True,
            requested=0,
            processed=0,
            collected=0,
            failed=0,
            skipped=0,
            items=[],
            detail="보강할 답글 대상이 없습니다.",
        )
    return ReviewReplyBackfillResponse(
        ok=True,
        requested=len(items),
        processed=len(items),
        collected=collected,
        failed=failed,
        skipped=skipped,
        items=items,
        detail="호스트 크롬의 스마트스토어 판매자센터 리뷰 화면 기준으로 답글 본문을 보강했습니다.",
    )


