@app.post("/reviews/reply-drafts/generate-batch", response_model=ReviewReplyDraftBatchGenerateResponse)
def generate_review_reply_draft_batch(
    req: ReviewReplyDraftBatchGenerateRequest,
    db: Session = Depends(get_db),
):
    max_items = max(1, min(int(req.max_items or 10), 100))
    product_url = str(req.product_url or "").strip()
    date_from = req.date_from
    date_to = req.date_to
    base_query = _apply_review_scope_filters(
        db.query(NaverReviewRaw),
        model_cls=NaverReviewRaw,
        product_url=(product_url or None),
        date_from=date_from,
        date_to=date_to,
        rating_filters=req.rating_filters,
        exclude_incomplete_product_page_stubs=True,
    )
    ordered_query = base_query.order_by(
        NaverReviewRaw.collected_at.desc(),
        NaverReviewRaw.review_written_at.desc(),
        NaverReviewRaw.review_key.desc(),
    )
    style_corpus_rows = _build_review_reply_style_corpus(db, product_url=(product_url or None), limit=1500)
    style_profiles = build_style_profiles(style_corpus_rows)

    out_items: list[ReviewReplyDraftResponse] = []
    processed = 0
    generated = 0
    reused = 0
    skipped_replied = 0
    skipped_existing = 0
    exhausted = True
    scan_chunk = max(50, int(REVIEW_REPLY_DRAFT_BATCH_SCAN_CHUNK or 500))
    scan_offset = 0
    requested_style_level = max(1, min(int(req.style_level or 3), 6))
    draft_status_priority = {
        "approved": 0,
        "generated": 1,
        "rejected": 2,
        "failed": 3,
        "superseded": 4,
    }

    while processed < max_items:
        page_rows_raw = ordered_query.offset(scan_offset).limit(scan_chunk + 1).all()
        if not page_rows_raw:
            exhausted = True
            break

        has_more_after_page = len(page_rows_raw) > scan_chunk
        page_rows = page_rows_raw[:scan_chunk]
        review_keys = [
            str(getattr(row, "review_key", "") or "").strip()
            for row in page_rows
            if str(getattr(row, "review_key", "") or "").strip()
        ]
        reply_map = {
            str(getattr(row, "review_key", "") or "").strip(): row
            for row in (
                db.query(NaverReviewReplyRaw)
                .filter(NaverReviewReplyRaw.review_key.in_(review_keys))
                .all()
                if review_keys
                else []
            )
        }
        latest_draft_rows = (
            db.query(ReviewReplyDraft)
            .filter(ReviewReplyDraft.review_key.in_(review_keys))
            .order_by(
                ReviewReplyDraft.generated_at.desc(),
                ReviewReplyDraft.updated_at.desc(),
                ReviewReplyDraft.draft_id.desc(),
            )
            .all()
            if review_keys
            else []
        )
        latest_draft_map: dict[str, ReviewReplyDraft] = {}
        for draft_row in latest_draft_rows:
            draft_review_key = str(getattr(draft_row, "review_key", "") or "").strip()
            if not draft_review_key:
                continue
            current = latest_draft_map.get(draft_review_key)
            if current is None:
                latest_draft_map[draft_review_key] = draft_row
                continue
            next_priority = draft_status_priority.get(str(getattr(draft_row, "status", "") or "").strip(), 9)
            current_priority = draft_status_priority.get(str(getattr(current, "status", "") or "").strip(), 9)
            if next_priority < current_priority:
                latest_draft_map[draft_review_key] = draft_row

        for idx, review_row in enumerate(page_rows):
            review_key = str(getattr(review_row, "review_key", "") or "").strip()
            if not review_key:
                continue

            reply_row = reply_map.get(review_key)
            reply_text = str(getattr(reply_row, "reply_text", "") or "").strip()
            if reply_text or bool(getattr(review_row, "reply_exists_flag", False)):
                skipped_replied += 1
                continue

            latest = latest_draft_map.get(review_key)
            has_existing_active_draft = bool(
                latest is not None
                and str(latest.status or "") in ("generated", "approved", "rejected")
                and str(latest.draft_text or "").strip()
            )
            if has_existing_active_draft and not bool(req.force_regenerate) and not bool(req.include_existing):
                skipped_existing += 1
                continue

            item = _generate_review_reply_draft_for_row(
                db,
                review_row=review_row,
                model=req.model,
                force_regenerate=bool(req.force_regenerate),
                style_level=requested_style_level,
                style_controls=req.style_controls,
                style_corpus_rows=style_corpus_rows,
                style_profiles=style_profiles,
            )
            out_items.append(item)
            processed += 1
            if item.generated_now:
                generated += 1
            else:
                reused += 1

            if processed >= max_items:
                exhausted = (idx >= len(page_rows) - 1) and (not has_more_after_page)
                break

        if processed >= max_items:
            break

        scan_offset += len(page_rows)
        if not has_more_after_page:
            exhausted = True
            break

    return ReviewReplyDraftBatchGenerateResponse(
        ok=True,
        requested=max_items,
        processed=processed,
        generated=generated,
        reused=reused,
        skipped_replied=skipped_replied,
        skipped_existing=skipped_existing,
        exhausted=exhausted,
        items=out_items,
    )


