@app.post("/reviews/reply-drafts/status", response_model=ReviewReplyDraftStatusUpdateResponse)
def update_review_reply_draft_status(
    req: ReviewReplyDraftStatusUpdateRequest,
    db: Session = Depends(get_db),
):
    draft_id = str(req.draft_id or "").strip()
    if not draft_id:
        raise HTTPException(status_code=400, detail="draft_id is required")
    row: ReviewReplyDraft | None = (
        db.query(ReviewReplyDraft).filter(ReviewReplyDraft.draft_id == draft_id).one_or_none()
    )
    if row is None:
        raise HTTPException(status_code=404, detail="draft not found")
    target_status = str(req.status or "").strip()
    rejection_comment = _collapse_ws_text(req.rejection_comment)
    rejection_analysis: dict = {}
    if target_status == "rejected":
        review_row: NaverReviewRaw | None = (
            db.query(NaverReviewRaw).filter(NaverReviewRaw.review_key == str(row.review_key or "")).one_or_none()
        )
        if review_row is None:
            raise HTTPException(status_code=404, detail="review not found")
        product_title = None
        meta_filters = _smartstore_product_url_filters(TrackedProductMeta, product_url=review_row.product_url)
        if meta_filters:
            meta_row: TrackedProductMeta | None = (
                db.query(TrackedProductMeta)
                .filter(or_(*meta_filters))
                .order_by(TrackedProductMeta.updated_at.desc(), TrackedProductMeta.id.desc())
                .limit(1)
                .one_or_none()
            )
            if meta_row is not None and str(getattr(meta_row, "title", "") or "").strip():
                product_title = str(meta_row.title).strip()
        target_meta = _lookup_review_target_meta(db, review_row.product_url)
        keyword = str((target_meta or {}).get("keyword") or "").strip() or None
        if bool(req.analyze_rejection):
            rejection_analysis = _analyze_review_reply_rejection_feedback(
                review_row=review_row,
                draft_row=row,
                rejection_comment=(rejection_comment or ""),
                product_title=product_title,
                keyword=keyword,
            )
        else:
            rejection_analysis = _fallback_review_reply_rejection_analysis(rejection_comment or "슈퍼관리자 일괄 반려")
    row = _apply_review_reply_draft_status_change(
        db,
        draft_id=draft_id,
        target_status=target_status,
        rejection_comment=rejection_comment,
        rejection_analysis=rejection_analysis,
    )
    if target_status == "rejected" and rejection_analysis:
        _save_review_reply_feedback_knowledge(
            db,
            source_draft_id=str(row.draft_id or ""),
            analysis=rejection_analysis,
        )
    db.commit()
    return ReviewReplyDraftStatusUpdateResponse(
        ok=True,
        draft_id=str(row.draft_id or ""),
        review_key=str(row.review_key or ""),
        status=str(row.status or ""),
        rejection_comment=(str(getattr(row, "rejection_comment", "") or "").strip() or None),
        rejection_problem_summary=_summarize_review_reply_rejection_problem(getattr(row, "rejection_analysis_json", None)),
        rejection_analysis=_parse_review_reply_rejection_analysis(getattr(row, "rejection_analysis_json", None)),
    )


