@app.post("/reviews/reply-drafts/submit", response_model=ReviewReplyDraftSubmitResponse)
def submit_review_reply_draft(
    req: ReviewReplyDraftSubmitRequest,
    db: Session = Depends(get_db),
):
    ctx = _build_review_reply_submit_context(db, draft_id=str(req.draft_id or "").strip())
    draft_row = ctx["draft_row"]
    review_row = ctx["review_row"]
    if not bool(ctx["can_submit"]):
        blockers = list(ctx["blockers"] or [])
        terminal_blockers = [one for one in blockers if one in REVIEW_REPLY_TERMINAL_BLOCKER_DETAILS]
        if terminal_blockers:
            blocker = str(terminal_blockers[0] or "").strip()
            return _persist_review_reply_terminal_state(
                db,
                draft_row=draft_row,
                review_row=review_row,
                blocker=blocker,
                detail=_describe_review_reply_submit_blocker(blocker),
            )
        raise HTTPException(status_code=409, detail=",".join(blockers) or "reply_submit_not_ready")
    return _submit_review_reply_and_sync(
        db,
        draft_row=draft_row,
        review_row=review_row,
    )


@app.post("/reviews/reply-drafts/manual-complete", response_model=ReviewReplyDraftSubmitResponse)
def manual_complete_review_reply_draft(
    req: ReviewReplyDraftManualCompleteRequest,
    request: Request,
    db: Session = Depends(get_db),
):
    require_role_level(request, minimum="ops_admin")
    draft_id = str(req.draft_id or "").strip()
    if not draft_id:
        raise HTTPException(status_code=400, detail="draft_id is required")
    draft_row: ReviewReplyDraft | None = (
        db.query(ReviewReplyDraft).filter(ReviewReplyDraft.draft_id == draft_id).one_or_none()
    )
    if draft_row is None:
        raise HTTPException(status_code=404, detail="draft not found")
    review_row: NaverReviewRaw | None = (
        db.query(NaverReviewRaw).filter(NaverReviewRaw.review_key == str(draft_row.review_key or "")).one_or_none()
    )
    if review_row is None:
        raise HTTPException(status_code=404, detail="review not found")
    reply_row: NaverReviewReplyRaw | None = (
        db.query(NaverReviewReplyRaw).filter(NaverReviewReplyRaw.review_key == str(review_row.review_key or "")).one_or_none()
    )
    existing_reply_known = bool(getattr(review_row, "reply_exists_flag", False)) or (
        reply_row is not None and str(getattr(reply_row, "reply_text", "") or "").strip()
    )
    if not existing_reply_known:
        raise HTTPException(status_code=409, detail="manual_complete_requires_existing_reply")
    if str(getattr(review_row, "reply_collect_status", "") or "").strip() == "manual_completed":
        return ReviewReplyDraftSubmitResponse(
            ok=True,
            draft_id=str(draft_row.draft_id or ""),
            review_key=str(review_row.review_key or ""),
            status="completed",
            result_type="manual_completed",
            detail="관리자가 기존 답글 존재를 확인해 완료 처리했습니다.",
            reply_written_at=(getattr(reply_row, "reply_written_at", None) if reply_row is not None else None),
        )
    return _persist_review_reply_manual_complete(
        db,
        draft_row=draft_row,
        review_row=review_row,
    )


REVIEW_REPLY_BULK_SUBMIT_JOB_PREFIX = "review-reply-bulk-submit"
REVIEW_REPLY_BULK_SUBMIT_BATCH_SIZE = 20
REVIEW_REPLY_BULK_SUBMIT_STALE_MINUTES = 20


def _check_review_reply_bulk_browser_ready(product_url: str | None) -> dict:
    if _pw_runtime_mode() != "host_cdp":
        return {"ready": False, "reason": "browser_host_cdp_not_enabled"}
    product_url0 = str(product_url or "").strip()
    if not product_url0:
        return {"ready": True, "reason": None}
    return _check_review_reply_browser_ready(product_url0)


def _review_reply_bulk_submit_base_query(db: Session):
    return (
        db.query(
            ReviewReplyDraft,
            NaverReviewRaw.review_id_original,
            NaverReviewRaw.product_url,
            NaverReviewRaw.reply_exists_flag,
            NaverReviewRaw.reply_collect_status,
            NaverReviewRaw.rating,
            NaverReviewRaw.review_text,
            NaverReviewRaw.review_written_at,
        )
        .join(NaverReviewRaw, NaverReviewRaw.review_key == ReviewReplyDraft.review_key)
        .outerjoin(NaverReviewReplyRaw, NaverReviewReplyRaw.review_key == ReviewReplyDraft.review_key)
        .filter(
            ReviewReplyDraft.status == "approved",
            or_(
                NaverReviewReplyRaw.review_key.is_(None),
                NaverReviewReplyRaw.reply_text.is_(None),
                func.trim(NaverReviewReplyRaw.reply_text) == "",
            ),
        )
    )


def _count_review_reply_bulk_submit_policy_excluded(db: Session) -> int:
    total = int(_review_reply_bulk_submit_base_query(db).count() or 0)
    in_scope = int(_review_reply_bulk_submit_policy_scope(_review_reply_bulk_submit_base_query(db)).count() or 0)
    return max(0, total - in_scope)


def _review_reply_bulk_submit_policy_scope(q):
    # SQL pre-filter only; review_reply_v3.evaluate_auto_post is the authoritative gate.
    return q.filter(
        ReviewReplyDraft.prompt_version == REVIEW_REPLY_PROMPT_VERSION,
        ReviewReplyDraft.generated_at
        >= datetime.now(ZoneInfo("UTC")) - timedelta(days=review_reply_v3.AUTO_POST_MAX_DRAFT_AGE_DAYS),
        ReviewReplyDraft.published_at.is_(None),
        NaverReviewRaw.rating >= review_reply_v3.AUTO_POST_MIN_RATING,
        NaverReviewRaw.review_written_at >= _today_kst() - timedelta(days=review_reply_v3.AUTO_POST_MAX_REVIEW_AGE_DAYS),
    )


def _review_reply_auto_post_gate(
    *,
    draft_row: ReviewReplyDraft,
    rating: float | None,
    review_text: str | None,
    review_written_at: object,
    reply_exists: bool,
) -> dict:
    return review_reply_v3.evaluate_auto_post(
        rating=rating,
        review_text=review_text,
        review_written_at=review_written_at,
        draft_status=getattr(draft_row, "status", None),
        prompt_version=getattr(draft_row, "prompt_version", None),
        draft_generated_at=getattr(draft_row, "generated_at", None),
        draft_text=getattr(draft_row, "draft_text", None),
        draft_published_at=getattr(draft_row, "published_at", None),
        reply_exists=reply_exists,
        today=_today_kst(),
        now_utc=datetime.utcnow(),
    )


def _list_review_reply_bulk_submit_candidate_rows(
    db: Session,
    *,
    exclude_draft_ids: set[str] | None = None,
) -> list[tuple[ReviewReplyDraft, str | None, str | None, bool, str | None, float | None, str | None, object]]:
    q = (
        _review_reply_bulk_submit_policy_scope(_review_reply_bulk_submit_base_query(db))
        .order_by(
            ReviewReplyDraft.generated_at.asc(),
            ReviewReplyDraft.updated_at.asc(),
            ReviewReplyDraft.draft_id.asc(),
        )
    )
    excluded = [str(one or "").strip() for one in (exclude_draft_ids or set()) if str(one or "").strip()]
    if excluded:
        q = q.filter(not_(ReviewReplyDraft.draft_id.in_(excluded)))
    return list(q.all())


def _evaluate_review_reply_bulk_submit_candidate(
    *,
    review_id_original: str | None,
    product_url: str | None,
    reply_exists_flag: bool,
    reply_collect_status: str | None,
    commerce_status: dict,
    browser_status_cache: dict[str, dict],
) -> dict[str, object]:
    blockers: list[str] = []
    existing_reply_detected = bool(reply_exists_flag)
    if not str(review_id_original or "").strip() and not existing_reply_detected:
        blockers.append("review_collection_required")
    terminal_blocker = _get_review_reply_terminal_blocker(reply_collect_status)
    if terminal_blocker:
        blockers.append(terminal_blocker)
    product_url0 = str(product_url or "").strip()
    browser_status = browser_status_cache.get(product_url0)
    if browser_status is None:
        browser_status = _check_review_reply_bulk_browser_ready(product_url0)
        browser_status_cache[product_url0] = browser_status
    if not existing_reply_detected and not bool(commerce_status.get("ready")) and not bool(browser_status.get("ready")):
        commerce_reason = str(commerce_status.get("reason") or "").strip()
        browser_reason = str(browser_status.get("reason") or "").strip()
        if commerce_reason:
            blockers.append(commerce_reason)
        if browser_reason:
            blockers.append(browser_reason)
    deduped_blockers: list[str] = []
    seen: set[str] = set()
    for blocker in blockers:
        blocker0 = str(blocker or "").strip()
        if not blocker0 or blocker0 in seen:
            continue
        seen.add(blocker0)
        deduped_blockers.append(blocker0)
    return {
        "can_submit": len(deduped_blockers) == 0,
        "blockers": deduped_blockers,
        "existing_reply_detected": existing_reply_detected,
    }


def _format_review_reply_bulk_submit_block_detail(blocker_counts: Counter[str]) -> str:
    if not blocker_counts:
        return "자동 게시할 승인 답글이 없습니다."
    ordered = blocker_counts.most_common()
    if len(ordered) == 1:
        reason, count = ordered[0]
        return f"자동 게시 가능 대상이 없습니다. 차단 사유: {_describe_review_reply_submit_blocker(reason)} ({count}건)"
    reason_text = ", ".join(f"{_describe_review_reply_submit_blocker(reason)} ({count}건)" for reason, count in ordered[:3])
    return f"자동 게시 가능 대상이 없습니다. 주요 차단 사유: {reason_text}"


def _scan_review_reply_bulk_submit_targets(
    db: Session,
    *,
    limit: int | None = None,
    exclude_draft_ids: set[str] | None = None,
) -> dict[str, object]:
    candidate_rows = _list_review_reply_bulk_submit_candidate_rows(db, exclude_draft_ids=exclude_draft_ids)
    policy_excluded = _count_review_reply_bulk_submit_policy_excluded(db)
    commerce_status = _check_review_reply_commerce_api_ready()
    browser_status_cache: dict[str, dict] = {}
    blocker_counts: Counter[str] = Counter()
    eligible_draft_rows: list[ReviewReplyDraft] = []
    for (
        draft_row,
        review_id_original,
        product_url,
        reply_exists_flag,
        reply_collect_status,
        rating,
        review_text,
        review_written_at,
    ) in candidate_rows:
        gate = _review_reply_auto_post_gate(
            draft_row=draft_row,
            rating=rating,
            review_text=review_text,
            review_written_at=review_written_at,
            reply_exists=bool(reply_exists_flag),
        )
        if not bool(gate.get("eligible")):
            for reason in list(gate.get("reasons") or []):
                blocker_counts[str(reason)] += 1
            continue
        eligibility = _evaluate_review_reply_bulk_submit_candidate(
            review_id_original=review_id_original,
            product_url=product_url,
            reply_exists_flag=bool(reply_exists_flag),
            reply_collect_status=reply_collect_status,
            commerce_status=commerce_status,
            browser_status_cache=browser_status_cache,
        )
        if bool(eligibility.get("can_submit")):
            eligible_draft_rows.append(draft_row)
            if limit is not None and len(eligible_draft_rows) >= max(1, int(limit)):
                break
            continue
        for blocker in list(eligibility.get("blockers") or []):
            blocker_counts[str(blocker)] += 1
    detail = _format_review_reply_bulk_submit_block_detail(blocker_counts)
    if policy_excluded > 0:
        detail = (
            f"{detail} 자동 게시 기준(최근 30일 리뷰·4~5점·최근 7일 v3 초안·미게시) 밖의 승인 초안 "
            f"{policy_excluded}건은 대상에서 제외했습니다."
        )
    return {
        "candidate_count": len(candidate_rows),
        "eligible_count": len(eligible_draft_rows),
        "eligible_draft_rows": eligible_draft_rows,
        "blocker_counts": blocker_counts,
        "policy_excluded_count": policy_excluded,
        "detail": detail,
    }


def _count_review_reply_bulk_submit_targets(db: Session) -> int:
    return int(_scan_review_reply_bulk_submit_targets(db).get("eligible_count") or 0)


def _is_review_reply_bulk_submit_cancel_requested(job_id: str, run_date: date) -> bool:
    with SessionLocal() as db:
        row = (
            db.query(AnalyticsJobRun)
            .filter(
                AnalyticsJobRun.job_name == _review_reply_bulk_submit_job_name(job_id),
                AnalyticsJobRun.run_date == run_date,
            )
            .one_or_none()
        )
    if row is None:
        return False
    try:
        detail_payload = json.loads(str(getattr(row, "detail", "") or "") or "{}")
    except Exception:
        detail_payload = {}
    return bool(detail_payload.get("cancel_requested"))


def _list_review_reply_bulk_submit_target_drafts(
    db: Session,
    *,
    limit: int,
    exclude_draft_ids: set[str] | None = None,
) -> list[ReviewReplyDraft]:
    snapshot = _scan_review_reply_bulk_submit_targets(
        db,
        limit=max(1, min(int(limit or REVIEW_REPLY_BULK_SUBMIT_BATCH_SIZE), 200)),
        exclude_draft_ids=exclude_draft_ids,
    )
    return list(snapshot.get("eligible_draft_rows") or [])


def _review_reply_bulk_submit_job_name(job_id: str) -> str:
    return f"{REVIEW_REPLY_BULK_SUBMIT_JOB_PREFIX}:{str(job_id or '').strip()}"


def _get_review_reply_bulk_submit_job_row(db: Session, *, job_id: str | None = None) -> AnalyticsJobRun | None:
    if str(job_id or "").strip():
        return (
            db.query(AnalyticsJobRun)
            .filter(AnalyticsJobRun.job_name == _review_reply_bulk_submit_job_name(str(job_id or "").strip()))
            .one_or_none()
        )
    return (
        db.query(AnalyticsJobRun)
        .filter(AnalyticsJobRun.job_name.like(f"{REVIEW_REPLY_BULK_SUBMIT_JOB_PREFIX}:%"))
        .order_by(AnalyticsJobRun.started_at.desc(), AnalyticsJobRun.run_date.desc())
        .first()
    )


def _serialize_review_reply_bulk_submit_job_response(
    row: AnalyticsJobRun | None,
    *,
    scheduled: bool = False,
    fallback_detail: str | None = None,
) -> ReviewReplyDraftBulkSubmitJobResponse:
    if row is None:
        return ReviewReplyDraftBulkSubmitJobResponse(
            ok=True,
            scheduled=scheduled,
            status="IDLE",
            detail=fallback_detail,
        )
    detail_payload: dict[str, object] = {}
    try:
        raw_detail = getattr(row, "detail", None)
        if raw_detail:
            parsed = json.loads(raw_detail)
            if isinstance(parsed, dict):
                detail_payload = parsed
    except Exception:
        detail_payload = {}
    job_name = str(getattr(row, "job_name", "") or "").strip()
    job_id_value = str(detail_payload.get("job_id") or "").strip()
    if not job_id_value and job_name.startswith(f"{REVIEW_REPLY_BULK_SUBMIT_JOB_PREFIX}:"):
        job_id_value = job_name.split(":", 1)[1].strip()
    return ReviewReplyDraftBulkSubmitJobResponse(
        ok=True,
        scheduled=scheduled,
        job_id=job_id_value or None,
        status=str(getattr(row, "status", "") or "IDLE"),
        pending_targets=int(detail_payload.get("pending_targets") or 0),
        processed=int(detail_payload.get("processed") or 0),
        succeeded=int(detail_payload.get("succeeded") or 0),
        failed=int(detail_payload.get("failed") or 0),
        skipped=int(detail_payload.get("skipped") or 0),
        existing_reply_completed=int(detail_payload.get("existing_reply_completed") or 0),
        existing_reply_enrichment=int(detail_payload.get("existing_reply_enrichment") or 0),
        cancel_requested=bool(detail_payload.get("cancel_requested")),
        detail=str(detail_payload.get("detail") or fallback_detail or "").strip() or None,
        started_at=getattr(row, "started_at", None),
        finished_at=getattr(row, "finished_at", None),
    )


def _save_review_reply_bulk_submit_job_state(
    *,
    job_id: str,
    run_date: date,
    status: str,
    pending_targets: int,
    processed: int,
    succeeded: int,
    failed: int,
    skipped: int,
    existing_reply_completed: int = 0,
    existing_reply_enrichment: int = 0,
    detail: str,
    cancel_requested: bool = False,
    finished: bool = False,
) -> None:
    job_name = _review_reply_bulk_submit_job_name(job_id)
    now = datetime.utcnow()
    payload = {
        "job_id": job_id,
        "pending_targets": int(pending_targets or 0),
        "processed": int(processed or 0),
        "succeeded": int(succeeded or 0),
        "failed": int(failed or 0),
        "skipped": int(skipped or 0),
        "existing_reply_completed": int(existing_reply_completed or 0),
        "existing_reply_enrichment": int(existing_reply_enrichment or 0),
        "cancel_requested": bool(cancel_requested),
        "detail": str(detail or "").strip(),
    }
    with SessionLocal() as db:
        row = (
            db.query(AnalyticsJobRun)
            .filter(
                AnalyticsJobRun.job_name == job_name,
                AnalyticsJobRun.run_date == run_date,
            )
            .one_or_none()
        )
        if row is None:
            row = AnalyticsJobRun(job_name=job_name, run_date=run_date)
            db.add(row)
        row.status = str(status or "").strip() or "STARTED"
        row.detail = json.dumps(payload, ensure_ascii=False)
        if str(row.status).upper() == "STARTED":
            row.started_at = now
            row.finished_at = None
        elif finished:
            row.finished_at = now
        db.commit()


def _format_review_reply_existing_sync_summary(
    *,
    existing_reply_completed: int,
    existing_reply_enrichment: int,
) -> str:
    parts: list[str] = []
    if int(existing_reply_completed or 0) > 0:
        parts.append(f"기존 답글 자동 완료 {int(existing_reply_completed)}건")
    if int(existing_reply_enrichment or 0) > 0:
        parts.append(f"기존 답글 보강 전이 {int(existing_reply_enrichment)}건")
    return ", ".join(parts)


def _run_review_reply_bulk_submit_job(*, job_id: str, run_date: date, total_limit: int | None) -> None:
    processed = 0
    succeeded = 0
    failed = 0
    skipped = 0
    existing_reply_completed = 0
    existing_reply_enrichment = 0
    attempted_draft_ids: set[str] = set()
    try:
        while True:
            if _is_review_reply_bulk_submit_cancel_requested(job_id, run_date):
                with SessionLocal() as db:
                    _save_review_reply_bulk_submit_job_state(
                        job_id=job_id,
                        run_date=run_date,
                        status="CANCELLED",
                        pending_targets=_count_review_reply_bulk_submit_targets(db),
                        processed=processed,
                        succeeded=succeeded,
                        failed=failed,
                        skipped=skipped,
                        existing_reply_completed=existing_reply_completed,
                        existing_reply_enrichment=existing_reply_enrichment,
                        detail="승인 답글 자동 게시 작업을 사용자 요청으로 중단했습니다.",
                        cancel_requested=True,
                        finished=True,
                    )
                return
            remaining_limit = None if total_limit is None else max(0, int(total_limit) - processed)
            if remaining_limit is not None and remaining_limit <= 0:
                break
            with SessionLocal() as db:
                pending_targets = _count_review_reply_bulk_submit_targets(db)
                if pending_targets <= 0:
                    break
                batch_limit = REVIEW_REPLY_BULK_SUBMIT_BATCH_SIZE
                if remaining_limit is not None:
                    batch_limit = max(1, min(batch_limit, remaining_limit))
                draft_rows = _list_review_reply_bulk_submit_target_drafts(
                    db,
                    limit=batch_limit,
                    exclude_draft_ids=attempted_draft_ids,
                )
                if not draft_rows:
                    break
                for draft_row in draft_rows:
                    draft_id = str(getattr(draft_row, "draft_id", "") or "").strip()
                    if not draft_id:
                        continue
                    attempted_draft_ids.add(draft_id)
                    processed += 1
                    try:
                        ctx = _build_review_reply_submit_context(db, draft_id=draft_id)
                        if not bool(ctx["can_submit"]):
                            skipped += 1
                            continue
                        review_row = ctx["review_row"]
                        submit_response = _submit_review_reply_and_sync(
                            db,
                            draft_row=draft_row,
                            review_row=review_row,
                        )
                        result_type = str(getattr(submit_response, "result_type", "") or "").strip()
                        if result_type == "existing_reply_completed":
                            existing_reply_completed += 1
                        elif result_type == "existing_reply_enrichment":
                            existing_reply_enrichment += 1
                        succeeded += 1
                    except Exception:
                        db.rollback()
                        failed += 1
                    if _is_review_reply_bulk_submit_cancel_requested(job_id, run_date):
                        _save_review_reply_bulk_submit_job_state(
                            job_id=job_id,
                            run_date=run_date,
                            status="CANCELLED",
                            pending_targets=_count_review_reply_bulk_submit_targets(db),
                            processed=processed,
                            succeeded=succeeded,
                            failed=failed,
                            skipped=skipped,
                            existing_reply_completed=existing_reply_completed,
                            existing_reply_enrichment=existing_reply_enrichment,
                            detail="승인 답글 자동 게시 작업을 사용자 요청으로 중단했습니다.",
                            cancel_requested=True,
                            finished=True,
                        )
                        return
                progress_detail = "승인 답글 자동 게시 작업을 진행 중입니다."
                existing_sync_summary = _format_review_reply_existing_sync_summary(
                    existing_reply_completed=existing_reply_completed,
                    existing_reply_enrichment=existing_reply_enrichment,
                )
                if existing_sync_summary:
                    progress_detail = f"{progress_detail} ({existing_sync_summary})"
                _save_review_reply_bulk_submit_job_state(
                    job_id=job_id,
                    run_date=run_date,
                    status="STARTED",
                    pending_targets=_count_review_reply_bulk_submit_targets(db),
                    processed=processed,
                    succeeded=succeeded,
                    failed=failed,
                    skipped=skipped,
                    existing_reply_completed=existing_reply_completed,
                    existing_reply_enrichment=existing_reply_enrichment,
                    detail=progress_detail,
                )
        final_status = "SUCCESS" if failed == 0 else ("PARTIAL" if succeeded > 0 else "FAILED")
        final_detail = "승인 답글 자동 게시 작업이 완료되었습니다."
        existing_sync_summary = _format_review_reply_existing_sync_summary(
            existing_reply_completed=existing_reply_completed,
            existing_reply_enrichment=existing_reply_enrichment,
        )
        if existing_sync_summary:
            final_detail = f"{final_detail} ({existing_sync_summary})"
        with SessionLocal() as db:
            _save_review_reply_bulk_submit_job_state(
                job_id=job_id,
                run_date=run_date,
                status=final_status,
                pending_targets=_count_review_reply_bulk_submit_targets(db),
                processed=processed,
                succeeded=succeeded,
                failed=failed,
                skipped=skipped,
                existing_reply_completed=existing_reply_completed,
                existing_reply_enrichment=existing_reply_enrichment,
                detail=final_detail,
                finished=True,
            )
    except Exception as exc:
        with SessionLocal() as db:
            _save_review_reply_bulk_submit_job_state(
                job_id=job_id,
                run_date=run_date,
                status="FAILED",
                pending_targets=_count_review_reply_bulk_submit_targets(db),
                processed=processed,
                succeeded=succeeded,
                failed=failed + 1,
                skipped=skipped,
                existing_reply_completed=existing_reply_completed,
                existing_reply_enrichment=existing_reply_enrichment,
                detail=str(exc or "reply_bulk_submit_failed"),
                finished=True,
            )


@app.post("/reviews/reply-drafts/bulk-submit/start", response_model=ReviewReplyDraftBulkSubmitJobResponse)
def start_review_reply_draft_bulk_submit(
    req: ReviewReplyDraftBulkSubmitRequest,
    background_tasks: BackgroundTasks,
    request: Request,
    db: Session = Depends(get_db),
):
    require_role_level(request, minimum="ops_admin")
    latest_job = _get_review_reply_bulk_submit_job_row(db)
    if latest_job is not None and str(getattr(latest_job, "status", "") or "").upper() == "STARTED":
        started_at = getattr(latest_job, "started_at", None)
        if started_at is not None and started_at.replace(tzinfo=None) > (
            datetime.utcnow() - timedelta(minutes=REVIEW_REPLY_BULK_SUBMIT_STALE_MINUTES)
        ):
            return _serialize_review_reply_bulk_submit_job_response(
                latest_job,
                scheduled=False,
                fallback_detail="이미 승인 답글 자동 게시 작업이 진행 중입니다.",
            )
    target_snapshot = _scan_review_reply_bulk_submit_targets(db)
    pending_targets = int(target_snapshot.get("eligible_count") or 0)
    candidate_count = int(target_snapshot.get("candidate_count") or 0)
    if pending_targets <= 0 and candidate_count <= 0:
        return ReviewReplyDraftBulkSubmitJobResponse(
            ok=True,
            scheduled=False,
            status="SUCCESS",
            pending_targets=0,
            detail="자동 게시할 승인 답글이 없습니다.",
        )
    if pending_targets <= 0:
        return ReviewReplyDraftBulkSubmitJobResponse(
            ok=True,
            scheduled=False,
            status="BLOCKED",
            pending_targets=0,
            detail=str(target_snapshot.get("detail") or "자동 게시 가능 대상이 없습니다."),
        )
    total_limit = int(req.limit or 0)
    if total_limit > 0:
        pending_targets = min(pending_targets, total_limit)
    run_date = _today_kst()
    job_id = hashlib.sha256(f"reply-bulk-submit|{time.time()}|{random.random()}".encode("utf-8")).hexdigest()[:16]
    _save_review_reply_bulk_submit_job_state(
        job_id=job_id,
        run_date=run_date,
        status="STARTED",
        pending_targets=pending_targets,
        processed=0,
        succeeded=0,
        failed=0,
        skipped=0,
        detail="승인 답글 자동 게시 작업을 시작했습니다.",
    )
    background_tasks.add_task(
        _run_review_reply_bulk_submit_job,
        job_id=job_id,
        run_date=run_date,
        total_limit=(total_limit if total_limit > 0 else None),
    )
    row = _get_review_reply_bulk_submit_job_row(db, job_id=job_id)
    return _serialize_review_reply_bulk_submit_job_response(
        row,
        scheduled=True,
        fallback_detail="승인 답글 자동 게시 작업을 시작했습니다.",
    )


@app.post("/reviews/reply-drafts/bulk-submit/stop", response_model=ReviewReplyDraftBulkSubmitJobResponse)
def stop_review_reply_draft_bulk_submit(
    req: ReviewReplyDraftBulkSubmitStopRequest,
    request: Request,
    db: Session = Depends(get_db),
):
    require_role_level(request, minimum="ops_admin")
    row = _get_review_reply_bulk_submit_job_row(db, job_id=req.job_id)
    if row is None:
        return ReviewReplyDraftBulkSubmitJobResponse(
            ok=True,
            scheduled=False,
            status="IDLE",
            pending_targets=_count_review_reply_bulk_submit_targets(db),
            detail="중지할 승인 답글 자동 게시 작업이 없습니다.",
        )
    current = _serialize_review_reply_bulk_submit_job_response(row, scheduled=False)
    if str(current.status or "").upper() != "STARTED":
        return current
    _save_review_reply_bulk_submit_job_state(
        job_id=str(current.job_id or "").strip(),
        run_date=getattr(row, "run_date"),
        status="CANCELLED",
        pending_targets=current.pending_targets,
        processed=current.processed,
        succeeded=current.succeeded,
        failed=current.failed,
        skipped=current.skipped,
        existing_reply_completed=current.existing_reply_completed,
        existing_reply_enrichment=current.existing_reply_enrichment,
        detail="승인 답글 자동 게시 중지 요청을 접수했습니다.",
        cancel_requested=True,
        finished=True,
    )
    db.expire_all()
    refreshed = _get_review_reply_bulk_submit_job_row(db, job_id=current.job_id)
    return _serialize_review_reply_bulk_submit_job_response(
        refreshed,
        scheduled=False,
        fallback_detail="승인 답글 자동 게시 중지 요청을 접수했습니다.",
    )


@app.get("/reviews/reply-drafts/bulk-submit/status", response_model=ReviewReplyDraftBulkSubmitJobResponse)
def get_review_reply_draft_bulk_submit_status(
    request: Request,
    job_id: str | None = Query(None, description="승인 답글 일괄 자동 게시 작업 ID"),
    db: Session = Depends(get_db),
):
    require_role_level(request, minimum="ops_admin")
    row = _get_review_reply_bulk_submit_job_row(db, job_id=job_id)
    if row is None:
        target_snapshot = _scan_review_reply_bulk_submit_targets(db)
        pending_targets = int(target_snapshot.get("eligible_count") or 0)
        candidate_count = int(target_snapshot.get("candidate_count") or 0)
        if pending_targets <= 0 and candidate_count <= 0:
            return ReviewReplyDraftBulkSubmitJobResponse(
                ok=True,
                scheduled=False,
                status="SUCCESS",
                pending_targets=0,
                detail="자동 게시할 승인 답글이 없습니다.",
            )
        if pending_targets <= 0:
            return ReviewReplyDraftBulkSubmitJobResponse(
                ok=True,
                scheduled=False,
                status="BLOCKED",
                pending_targets=0,
                detail=str(target_snapshot.get("detail") or "자동 게시 가능 대상이 없습니다."),
            )
        return ReviewReplyDraftBulkSubmitJobResponse(
            ok=True,
            scheduled=False,
            status="IDLE",
            pending_targets=pending_targets,
            detail="아직 시작된 승인 답글 자동 게시 작업이 없습니다.",
        )
    return _serialize_review_reply_bulk_submit_job_response(row, scheduled=False)


def _review_reply_bulk_stage_job_name(job_id: str) -> str:
    return f"{REVIEW_REPLY_BULK_STAGE_JOB_PREFIX}:{str(job_id or '').strip()}"


def _get_review_reply_bulk_stage_job_row(db: Session, *, job_id: str | None = None) -> AnalyticsJobRun | None:
    if str(job_id or "").strip():
        return (
            db.query(AnalyticsJobRun)
            .filter(AnalyticsJobRun.job_name == _review_reply_bulk_stage_job_name(str(job_id or "").strip()))
            .one_or_none()
        )
    return (
        db.query(AnalyticsJobRun)
        .filter(AnalyticsJobRun.job_name.like(f"{REVIEW_REPLY_BULK_STAGE_JOB_PREFIX}:%"))
        .order_by(AnalyticsJobRun.started_at.desc(), AnalyticsJobRun.run_date.desc())
        .first()
    )


def _serialize_review_reply_bulk_stage_job_response(
    row: AnalyticsJobRun | None,
    *,
    scheduled: bool = False,
    fallback_detail: str | None = None,
) -> ReviewReplyBulkStageJobResponse:
    if row is None:
        return ReviewReplyBulkStageJobResponse(ok=True, scheduled=scheduled, status="IDLE", detail=fallback_detail)
    detail_payload: dict[str, object] = {}
    try:
        raw_detail = getattr(row, "detail", None)
        if raw_detail:
            parsed = json.loads(raw_detail)
            if isinstance(parsed, dict):
                detail_payload = parsed
    except Exception:
        detail_payload = {}
    job_name = str(getattr(row, "job_name", "") or "").strip()
    job_id_value = str(detail_payload.get("job_id") or "").strip()
    if not job_id_value and job_name.startswith(f"{REVIEW_REPLY_BULK_STAGE_JOB_PREFIX}:"):
        job_id_value = job_name.split(":", 1)[1].strip()
    stage = str(detail_payload.get("stage") or "").strip() or None
    return ReviewReplyBulkStageJobResponse(
        ok=True,
        scheduled=scheduled,
        job_id=job_id_value or None,
        stage=stage,  # type: ignore[arg-type]
        stage_label=str(detail_payload.get("stage_label") or "").strip() or None,
        status=str(getattr(row, "status", "") or "IDLE"),
        filtered_total=int(detail_payload.get("filtered_total") or 0),
        pending_targets=int(detail_payload.get("pending_targets") or 0),
        processed=int(detail_payload.get("processed") or 0),
        succeeded=int(detail_payload.get("succeeded") or 0),
        failed=int(detail_payload.get("failed") or 0),
        skipped=int(detail_payload.get("skipped") or 0),
        existing_reply_completed=int(detail_payload.get("existing_reply_completed") or 0),
        existing_reply_enrichment=int(detail_payload.get("existing_reply_enrichment") or 0),
        cancel_requested=bool(detail_payload.get("cancel_requested")),
        detail=str(detail_payload.get("detail") or fallback_detail or "").strip() or None,
        started_at=getattr(row, "started_at", None),
        finished_at=getattr(row, "finished_at", None),
    )


def _save_review_reply_bulk_stage_job_state(
    *,
    job_id: str,
    run_date: date,
    stage: str,
    filtered_total: int,
    pending_targets: int,
    processed: int,
    succeeded: int,
    failed: int,
    skipped: int,
    existing_reply_completed: int = 0,
    existing_reply_enrichment: int = 0,
    detail: str,
    status: str = "STARTED",
    cancel_requested: bool = False,
    finished: bool = False,
) -> None:
    job_name = _review_reply_bulk_stage_job_name(job_id)
    now = datetime.utcnow()
    payload = {
        "job_id": job_id,
        "stage": stage,
        "stage_label": REVIEW_REPLY_BULK_STAGE_LABELS.get(stage, stage),
        "filtered_total": int(filtered_total or 0),
        "pending_targets": int(pending_targets or 0),
        "processed": int(processed or 0),
        "succeeded": int(succeeded or 0),
        "failed": int(failed or 0),
        "skipped": int(skipped or 0),
        "existing_reply_completed": int(existing_reply_completed or 0),
        "existing_reply_enrichment": int(existing_reply_enrichment or 0),
        "cancel_requested": bool(cancel_requested),
        "detail": str(detail or "").strip(),
    }
    with SessionLocal() as db:
        row = (
            db.query(AnalyticsJobRun)
            .filter(
                AnalyticsJobRun.job_name == job_name,
                AnalyticsJobRun.run_date == run_date,
            )
            .one_or_none()
        )
        if row is None:
            row = AnalyticsJobRun(job_name=job_name, run_date=run_date)
            db.add(row)
        row.status = str(status or "").strip() or "STARTED"
        row.detail = json.dumps(payload, ensure_ascii=False)
        if str(row.status).upper() == "STARTED":
            row.started_at = now
            row.finished_at = None
        elif finished:
            row.finished_at = now
        db.commit()


def _is_review_reply_bulk_stage_cancel_requested(job_id: str, run_date: date) -> bool:
    job_name = _review_reply_bulk_stage_job_name(job_id)
    with SessionLocal() as db:
        row = (
            db.query(AnalyticsJobRun)
            .filter(
                AnalyticsJobRun.job_name == job_name,
                AnalyticsJobRun.run_date == run_date,
            )
            .one_or_none()
        )
        if row is None:
            return False
        try:
            raw_detail = getattr(row, "detail", None)
            if raw_detail:
                parsed = json.loads(raw_detail)
                if isinstance(parsed, dict):
                    return bool(parsed.get("cancel_requested"))
        except Exception:
            return False
        return False


def _apply_review_reply_draft_status_change(
    db: Session,
    *,
    draft_id: str,
    target_status: str,
    rejection_comment: str | None = None,
    rejection_analysis: dict | None = None,
) -> ReviewReplyDraft:
    draft_id0 = str(draft_id or "").strip()
    target_status0 = str(target_status or "").strip()
    row: ReviewReplyDraft | None = (
        db.query(ReviewReplyDraft).filter(ReviewReplyDraft.draft_id == draft_id0).one_or_none()
    )
    if row is None:
        raise HTTPException(status_code=404, detail="draft not found")
    current_status = str(getattr(row, "status", "") or "").strip()
    if target_status0 in ("approved", "rejected") and current_status not in ("generated", target_status0):
        raise HTTPException(status_code=409, detail="draft_status_transition_not_allowed")
    if target_status0 == "rejected":
        rejection_comment0 = _collapse_ws_text(rejection_comment)
        if not rejection_comment0:
            raise HTTPException(status_code=400, detail="rejection_comment is required")
        row.rejection_comment = rejection_comment0
        analysis0 = _parse_review_reply_rejection_analysis(rejection_analysis)
        row.rejection_analysis_json = (
            json.dumps(analysis0, ensure_ascii=False, sort_keys=True)
            if analysis0
            else json.dumps(_fallback_review_reply_rejection_analysis(rejection_comment0), ensure_ascii=False, sort_keys=True)
        )
        row.rejection_analyzed_at = datetime.now(ZoneInfo("Asia/Seoul"))
    if target_status0 == "approved" and current_status != "approved":
        _record_review_reply_approval(db, row)
    row.status = target_status0 or row.status
    return row


def _run_review_reply_bulk_stage_job(
    *,
    job_id: str,
    run_date: date,
    stage: str,
    filtered_total: int,
    target_ids: list[str],
    product_url: str | None,
    model: str | None,
    style_level: int,
    style_controls: dict[str, int] | None,
    max_pages: int,
    cdp_url_override: str | None = None,
) -> None:
    processed = 0
    succeeded = 0
    failed = 0
    skipped = 0
    existing_reply_completed = 0
    existing_reply_enrichment = 0
    target_ids0 = [str(one or "").strip() for one in target_ids if str(one or "").strip()]
    try:
        if stage in ("approve", "reject"):
            with SessionLocal() as db:
                for draft_id in target_ids0:
                    if _is_review_reply_bulk_stage_cancel_requested(job_id, run_date):
                        _save_review_reply_bulk_stage_job_state(
                            job_id=job_id,
                            run_date=run_date,
                            stage=stage,
                            filtered_total=filtered_total,
                            pending_targets=max(len(target_ids0) - processed, 0),
                            processed=processed,
                            succeeded=succeeded,
                            failed=failed,
                            skipped=skipped,
                            detail="슈퍼관리자 일괄 단계 작업을 사용자 요청으로 중단했습니다.",
                            status="CANCELLED",
                            cancel_requested=True,
                            finished=True,
                        )
                        return
                    try:
                        _apply_review_reply_draft_status_change(
                            db,
                            draft_id=draft_id,
                            target_status=("approved" if stage == "approve" else "rejected"),
                            rejection_comment=("슈퍼관리자 일괄 반려" if stage == "reject" else None),
                            rejection_analysis=(
                                {
                                    "problem_types": ["bulk_rejected"],
                                    "root_cause": "슈퍼관리자 일괄 반려",
                                    "must_avoid": [],
                                    "rewrite_guidance": [],
                                    "global_rule_candidate": {},
                                }
                                if stage == "reject"
                                else None
                            ),
                        )
                        succeeded += 1
                    except HTTPException:
                        skipped += 1
                        db.rollback()
                    except Exception:
                        failed += 1
                        db.rollback()
                    processed += 1
                    if _is_review_reply_bulk_stage_cancel_requested(job_id, run_date):
                        _save_review_reply_bulk_stage_job_state(
                            job_id=job_id,
                            run_date=run_date,
                            stage=stage,
                            filtered_total=filtered_total,
                            pending_targets=max(len(target_ids0) - processed, 0),
                            processed=processed,
                            succeeded=succeeded,
                            failed=failed,
                            skipped=skipped,
                            detail="슈퍼관리자 일괄 단계 작업을 사용자 요청으로 중단했습니다.",
                            status="CANCELLED",
                            cancel_requested=True,
                            finished=True,
                        )
                        return
                    pending_targets = max(len(target_ids0) - processed, 0)
                    _save_review_reply_bulk_stage_job_state(
                        job_id=job_id,
                        run_date=run_date,
                        stage=stage,
                        filtered_total=filtered_total,
                        pending_targets=pending_targets,
                        processed=processed,
                        succeeded=succeeded,
                        failed=failed,
                        skipped=skipped,
                        detail=f"{REVIEW_REPLY_BULK_STAGE_LABELS.get(stage, stage)} 작업을 진행 중입니다.",
                    )
                db.commit()
        elif stage == "generate":
            with SessionLocal() as db:
                style_corpus_rows = _build_review_reply_style_corpus(db, product_url=(str(product_url or "").strip() or None), limit=1500)
                style_profiles = build_style_profiles(style_corpus_rows)
                for review_key in target_ids0:
                    if _is_review_reply_bulk_stage_cancel_requested(job_id, run_date):
                        _save_review_reply_bulk_stage_job_state(
                            job_id=job_id,
                            run_date=run_date,
                            stage=stage,
                            filtered_total=filtered_total,
                            pending_targets=max(len(target_ids0) - processed, 0),
                            processed=processed,
                            succeeded=succeeded,
                            failed=failed,
                            skipped=skipped,
                            detail="슈퍼관리자 일괄 단계 작업을 사용자 요청으로 중단했습니다.",
                            status="CANCELLED",
                            cancel_requested=True,
                            finished=True,
                        )
                        return
                    review_row = db.query(NaverReviewRaw).filter(NaverReviewRaw.review_key == review_key).one_or_none()
                    try:
                        if review_row is None:
                            skipped += 1
                        else:
                            generated = _generate_review_reply_draft_for_row(
                                db,
                                review_row=review_row,
                                model=model,
                                force_regenerate=False,
                                style_level=max(1, min(int(style_level or 3), 6)),
                                style_controls=style_controls,
                                style_corpus_rows=style_corpus_rows,
                                style_profiles=style_profiles,
                            )
                            if bool(getattr(generated, "generated_now", False)):
                                succeeded += 1
                            else:
                                skipped += 1
                    except HTTPException:
                        skipped += 1
                        db.rollback()
                    except Exception:
                        failed += 1
                        db.rollback()
                    processed += 1
                    if _is_review_reply_bulk_stage_cancel_requested(job_id, run_date):
                        _save_review_reply_bulk_stage_job_state(
                            job_id=job_id,
                            run_date=run_date,
                            stage=stage,
                            filtered_total=filtered_total,
                            pending_targets=max(len(target_ids0) - processed, 0),
                            processed=processed,
                            succeeded=succeeded,
                            failed=failed,
                            skipped=skipped,
                            detail="슈퍼관리자 일괄 단계 작업을 사용자 요청으로 중단했습니다.",
                            status="CANCELLED",
                            cancel_requested=True,
                            finished=True,
                        )
                        return
                    pending_targets = max(len(target_ids0) - processed, 0)
                    _save_review_reply_bulk_stage_job_state(
                        job_id=job_id,
                        run_date=run_date,
                        stage=stage,
                        filtered_total=filtered_total,
                        pending_targets=pending_targets,
                        processed=processed,
                        succeeded=succeeded,
                        failed=failed,
                        skipped=skipped,
                        detail="미작성 초안 생성 작업을 진행 중입니다.",
                    )
        elif stage == "submit":
            with SessionLocal() as db:
                for draft_id in target_ids0:
                    if _is_review_reply_bulk_stage_cancel_requested(job_id, run_date):
                        _save_review_reply_bulk_stage_job_state(
                            job_id=job_id,
                            run_date=run_date,
                            stage=stage,
                            filtered_total=filtered_total,
                            pending_targets=max(len(target_ids0) - processed, 0),
                            processed=processed,
                            succeeded=succeeded,
                            failed=failed,
                            skipped=skipped,
                            detail="슈퍼관리자 일괄 단계 작업을 사용자 요청으로 중단했습니다.",
                            status="CANCELLED",
                            cancel_requested=True,
                            finished=True,
                        )
                        return
                    try:
                        ctx = _build_review_reply_submit_context(db, draft_id=draft_id)
                        gate = _review_reply_auto_post_gate(
                            draft_row=ctx["draft_row"],
                            rating=getattr(ctx["review_row"], "rating", None),
                            review_text=getattr(ctx["review_row"], "review_text", None),
                            review_written_at=getattr(ctx["review_row"], "review_written_at", None),
                            reply_exists="review_already_replied" in list(ctx.get("blockers") or []),
                        )
                        if not bool(ctx["can_submit"]) or not bool(gate.get("eligible")):
                            skipped += 1
                        else:
                            draft_row = ctx["draft_row"]
                            review_row = ctx["review_row"]
                            submit_response = _submit_review_reply_and_sync(
                                db,
                                draft_row=draft_row,
                                review_row=review_row,
                            )
                            result_type = str(getattr(submit_response, "result_type", "") or "").strip()
                            if result_type == "existing_reply_completed":
                                existing_reply_completed += 1
                            elif result_type == "existing_reply_enrichment":
                                existing_reply_enrichment += 1
                            succeeded += 1
                    except HTTPException:
                        skipped += 1
                        db.rollback()
                    except Exception:
                        failed += 1
                        db.rollback()
                    processed += 1
                    if _is_review_reply_bulk_stage_cancel_requested(job_id, run_date):
                        _save_review_reply_bulk_stage_job_state(
                            job_id=job_id,
                            run_date=run_date,
                            stage=stage,
                            filtered_total=filtered_total,
                            pending_targets=max(len(target_ids0) - processed, 0),
                            processed=processed,
                            succeeded=succeeded,
                            failed=failed,
                            skipped=skipped,
                            detail="슈퍼관리자 일괄 단계 작업을 사용자 요청으로 중단했습니다.",
                            status="CANCELLED",
                            cancel_requested=True,
                            finished=True,
                        )
                        return
                    pending_targets = max(len(target_ids0) - processed, 0)
                    _save_review_reply_bulk_stage_job_state(
                        job_id=job_id,
                        run_date=run_date,
                        stage=stage,
                        filtered_total=filtered_total,
                        pending_targets=pending_targets,
                        processed=processed,
                        succeeded=succeeded,
                        failed=failed,
                        skipped=skipped,
                        existing_reply_completed=existing_reply_completed,
                        existing_reply_enrichment=existing_reply_enrichment,
                        detail=(
                            "승인 답글 자동 게시 작업을 진행 중입니다."
                            + (
                                f" ({_format_review_reply_existing_sync_summary(existing_reply_completed=existing_reply_completed, existing_reply_enrichment=existing_reply_enrichment)})"
                                if _format_review_reply_existing_sync_summary(
                                    existing_reply_completed=existing_reply_completed,
                                    existing_reply_enrichment=existing_reply_enrichment,
                                )
                                else ""
                            )
                        ),
                    )
        elif stage == "backfill":
            with SessionLocal() as db:
                target_rows = (
                    db.query(NaverReviewRaw)
                    .filter(NaverReviewRaw.review_key.in_(target_ids0))
                    .order_by(NaverReviewRaw.review_written_at.desc(), NaverReviewRaw.review_key.desc())
                    .all()
                )
                batch_size = REVIEW_REPLY_BACKFILL_BATCH_SIZE
                for start in range(0, len(target_rows), batch_size):
                    if _is_review_reply_bulk_stage_cancel_requested(job_id, run_date):
                        _save_review_reply_bulk_stage_job_state(
                            job_id=job_id,
                            run_date=run_date,
                            stage=stage,
                            filtered_total=filtered_total,
                            pending_targets=max(len(target_rows) - processed, 0),
                            processed=processed,
                            succeeded=succeeded,
                            failed=failed,
                            skipped=skipped,
                            detail="슈퍼관리자 일괄 단계 작업을 사용자 요청으로 중단했습니다.",
                            status="CANCELLED",
                            cancel_requested=True,
                            finished=True,
                        )
                        return
                    batch_rows = target_rows[start : start + batch_size]
                    _, collected_count, failed_count, skipped_count = _process_review_reply_backfill_target_rows(
                        db,
                        target_rows=batch_rows,
                        max_pages=max(1, int(max_pages or 30)),
                        cdp_url_override=cdp_url_override,
                    )
                    processed += len(batch_rows)
                    succeeded += collected_count
                    failed += failed_count
                    skipped += skipped_count
                    if _is_review_reply_bulk_stage_cancel_requested(job_id, run_date):
                        _save_review_reply_bulk_stage_job_state(
                            job_id=job_id,
                            run_date=run_date,
                            stage=stage,
                            filtered_total=filtered_total,
                            pending_targets=max(len(target_rows) - processed, 0),
                            processed=processed,
                            succeeded=succeeded,
                            failed=failed,
                            skipped=skipped,
                            detail="슈퍼관리자 일괄 단계 작업을 사용자 요청으로 중단했습니다.",
                            status="CANCELLED",
                            cancel_requested=True,
                            finished=True,
                        )
                        return
                    pending_targets = max(len(target_rows) - processed, 0)
                    _save_review_reply_bulk_stage_job_state(
                        job_id=job_id,
                        run_date=run_date,
                        stage=stage,
                        filtered_total=filtered_total,
                        pending_targets=pending_targets,
                        processed=processed,
                        succeeded=succeeded,
                        failed=failed,
                        skipped=skipped,
                        detail="답글 본문 보강 작업을 진행 중입니다.",
                    )
        final_status = "SUCCESS" if failed == 0 else ("PARTIAL" if succeeded > 0 else "FAILED")
        _save_review_reply_bulk_stage_job_state(
            job_id=job_id,
            run_date=run_date,
            stage=stage,
            filtered_total=filtered_total,
            pending_targets=max(len(target_ids0) - processed, 0),
            processed=processed,
            succeeded=succeeded,
            failed=failed,
            skipped=skipped,
            existing_reply_completed=existing_reply_completed,
            existing_reply_enrichment=existing_reply_enrichment,
            detail=(
                f"{REVIEW_REPLY_BULK_STAGE_LABELS.get(stage, stage)} 작업이 완료되었습니다."
                + (
                    f" ({_format_review_reply_existing_sync_summary(existing_reply_completed=existing_reply_completed, existing_reply_enrichment=existing_reply_enrichment)})"
                    if _format_review_reply_existing_sync_summary(
                        existing_reply_completed=existing_reply_completed,
                        existing_reply_enrichment=existing_reply_enrichment,
                    )
                    else ""
                )
            ),
            status=final_status,
            finished=True,
        )
    except Exception as exc:
        _save_review_reply_bulk_stage_job_state(
            job_id=job_id,
            run_date=run_date,
            stage=stage,
            filtered_total=filtered_total,
            pending_targets=max(len(target_ids0) - processed, 0),
            processed=processed,
            succeeded=succeeded,
            failed=failed + 1,
            skipped=skipped,
            existing_reply_completed=existing_reply_completed,
            existing_reply_enrichment=existing_reply_enrichment,
            detail=str(exc or "review_reply_bulk_stage_failed"),
            status="FAILED",
            finished=True,
        )


