@app.post("/reviews/reply-bulk-stage/start", response_model=ReviewReplyBulkStageJobResponse)
def start_review_reply_bulk_stage(
    req: ReviewReplyBulkStageStartRequest,
    background_tasks: BackgroundTasks,
    request: Request,
    db: Session = Depends(get_db),
):
    require_role_level(request, minimum="superadmin")
    latest_job = _get_review_reply_bulk_stage_job_row(db)
    if latest_job is not None and str(getattr(latest_job, "status", "") or "").upper() == "STARTED":
        started_at = getattr(latest_job, "started_at", None)
        if started_at is not None and started_at.replace(tzinfo=None) > (datetime.utcnow() - timedelta(minutes=REVIEW_REPLY_BULK_STAGE_STALE_MINUTES)):
            return _serialize_review_reply_bulk_stage_job_response(
                latest_job,
                scheduled=False,
                fallback_detail="이미 슈퍼관리자 일괄 단계 작업이 진행 중입니다.",
            )
    snapshot = _build_review_bulk_stage_snapshot(
        db,
        product_url=req.product_url,
        date_from=req.date_from,
        date_to=req.date_to,
        status_filter=req.status_filter,
        has_rejection_history_only=bool(req.has_rejection_history_only),
        rating_filters=req.rating_filters,
    )
    stage = str(req.stage or "").strip()
    stage_targets_map = {
        "generate": list(snapshot.get("generate_review_keys") or []),
        "approve": list(snapshot.get("approve_draft_ids") or []),
        "reject": list(snapshot.get("reject_draft_ids") or []),
        "submit": list(snapshot.get("submit_draft_ids") or []),
        "backfill": list(snapshot.get("backfill_review_keys") or []),
    }
    target_ids = [str(one or "").strip() for one in stage_targets_map.get(stage, []) if str(one or "").strip()]
    filtered_total = int(snapshot.get("filtered_total") or 0)
    stage_label = REVIEW_REPLY_BULK_STAGE_LABELS.get(stage, stage or "단계")
    if not target_ids:
        return ReviewReplyBulkStageJobResponse(
            ok=True,
            scheduled=False,
            stage=stage,  # type: ignore[arg-type]
            stage_label=stage_label,
            status="SUCCESS",
            filtered_total=filtered_total,
            pending_targets=0,
            detail=f"{stage_label} 대상이 없습니다.",
        )
    run_date = _today_kst()
    job_id = hashlib.sha256(f"reply-bulk-stage|{stage}|{time.time()}|{random.random()}".encode("utf-8")).hexdigest()[:16]
    _save_review_reply_bulk_stage_job_state(
        job_id=job_id,
        run_date=run_date,
        stage=stage,
        filtered_total=filtered_total,
        pending_targets=len(target_ids),
        processed=0,
        succeeded=0,
        failed=0,
        skipped=0,
        detail=f"{stage_label} 작업을 시작했습니다.",
    )
    background_tasks.add_task(
        _run_review_reply_bulk_stage_job,
        job_id=job_id,
        run_date=run_date,
        stage=stage,
        filtered_total=filtered_total,
        target_ids=target_ids,
        product_url=req.product_url,
        model=req.model,
        style_level=req.style_level,
        style_controls=dict(req.style_controls or {}),
        max_pages=int(req.max_pages or 30),
        cdp_url_override=(
            _host_cdp_override_url_from_request(request, explicit_ip=request.headers.get("x-erp2-client-ip"))
            if stage == "backfill"
            else None
        ),
    )
    row = _get_review_reply_bulk_stage_job_row(db, job_id=job_id)
    return _serialize_review_reply_bulk_stage_job_response(
        row,
        scheduled=True,
        fallback_detail=f"{stage_label} 작업을 시작했습니다.",
    )


@app.post("/reviews/reply-bulk-stage/stop", response_model=ReviewReplyBulkStageJobResponse)
def stop_review_reply_bulk_stage(
    req: ReviewReplyBulkStageStopRequest,
    request: Request,
    db: Session = Depends(get_db),
):
    require_role_level(request, minimum="superadmin")
    row = _get_review_reply_bulk_stage_job_row(db, job_id=req.job_id)
    if row is None:
        return ReviewReplyBulkStageJobResponse(
            ok=True,
            scheduled=False,
            status="IDLE",
            detail="중지할 슈퍼관리자 일괄 단계 작업이 없습니다.",
        )
    current = _serialize_review_reply_bulk_stage_job_response(row, scheduled=False)
    if str(current.status or "").upper() != "STARTED":
        return current
    _save_review_reply_bulk_stage_job_state(
        job_id=str(current.job_id or "").strip(),
        run_date=getattr(row, "run_date"),
        stage=str(current.stage or "").strip(),
        filtered_total=current.filtered_total,
        pending_targets=current.pending_targets,
        processed=current.processed,
        succeeded=current.succeeded,
        failed=current.failed,
        skipped=current.skipped,
        existing_reply_completed=current.existing_reply_completed,
        existing_reply_enrichment=current.existing_reply_enrichment,
        detail="슈퍼관리자 일괄 단계 작업 중지 요청을 접수했습니다.",
        status="CANCELLED",
        cancel_requested=True,
        finished=True,
    )
    db.expire_all()
    refreshed = _get_review_reply_bulk_stage_job_row(db, job_id=current.job_id)
    return _serialize_review_reply_bulk_stage_job_response(
        refreshed,
        scheduled=False,
        fallback_detail="슈퍼관리자 일괄 단계 작업 중지 요청을 접수했습니다.",
    )


