@app.post("/ai/chat", response_model=AiChatResponse)
def ai_chat(req: AiChatRequest):
    """
    간단 테스트용 ChatGPT 프록시.
    - 브라우저에 API 키를 노출하지 않기 위해 서버가 OPENAI_API_KEY를 읽어 호출한다.
    - 스트리밍/툴콜 등 고급기능은 제외(테스트 창 용도)
    """
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise HTTPException(status_code=400, detail="OPENAI_API_KEY not configured (설정 > API 세팅에서 등록)")

    msgs = []
    for m in (req.messages or []):
        role = str(getattr(m, "role", "") or "").strip().lower()
        content = str(getattr(m, "content", "") or "").strip()
        if role not in ("system", "user", "assistant"):
            raise HTTPException(status_code=400, detail=f"invalid role: {role}")
        if not content:
            continue
        msgs.append({"role": role, "content": content})
    if not msgs:
        raise HTTPException(status_code=400, detail="messages is empty")

    payload = {
        "model": (req.model or OPENAI_DEFAULT_MODEL),
        "messages": msgs,
    }
    if req.temperature is not None:
        try:
            payload["temperature"] = float(req.temperature)
        except Exception:
            pass
    if req.max_tokens is not None:
        try:
            payload["max_tokens"] = int(req.max_tokens)
        except Exception:
            pass

    try:
        resp = requests.post(
            "https://api.openai.com/v1/chat/completions",
            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
            json=payload,
            timeout=30,
        )
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"OpenAI 요청 실패: {e}")

    if int(resp.status_code) != 200:
        raise HTTPException(status_code=502, detail=f"OpenAI 실패({resp.status_code}) {_safe_err_text(resp)}".strip())

    try:
        j = resp.json() or {}
    except Exception:
        raise HTTPException(status_code=502, detail="OpenAI 응답 파싱 실패")

    msg = None
    try:
        choices = j.get("choices") or []
        if isinstance(choices, list) and choices:
            msg = (choices[0] or {}).get("message")
    except Exception:
        msg = None
    if not isinstance(msg, dict):
        raise HTTPException(status_code=502, detail="OpenAI 응답에 message가 없습니다.")

    out_msg = AiChatMessage(role=str(msg.get("role") or "assistant"), content=str(msg.get("content") or ""))
    return AiChatResponse(
        ok=True,
        model=str(j.get("model") or payload.get("model") or ""),
        message=out_msg,
        usage=j.get("usage") if isinstance(j.get("usage"), dict) else None,
    )


@app.get("/ai/models", response_model=AiModelsResponse)
def ai_models():
    """
    OpenAI 모델 목록(드롭다운 선택용).
    - 설정에 저장된 OPENAI_API_KEY로 /v1/models를 호출한다.
    - UI 용도로 gpt 계열만 간단히 필터링한다.
    """
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise HTTPException(status_code=400, detail="OPENAI_API_KEY not configured (설정 > API 세팅에서 등록)")

    try:
        resp = requests.get(
            "https://api.openai.com/v1/models",
            headers={"Authorization": f"Bearer {key}"},
            timeout=20,
        )
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"OpenAI 요청 실패: {e}")

    if int(resp.status_code) != 200:
        raise HTTPException(status_code=502, detail=f"OpenAI 실패({resp.status_code}) {_safe_err_text(resp)}".strip())

    try:
        j = resp.json() or {}
    except Exception:
        raise HTTPException(status_code=502, detail="OpenAI 응답 파싱 실패")

    data = j.get("data") or []
    out: list[dict] = []
    if isinstance(data, list):
        for m in data:
            if not isinstance(m, dict):
                continue
            mid = str(m.get("id") or "").strip()
            if not mid:
                continue
            low = mid.lower()
            # UI용: gpt 계열만
            if not low.startswith("gpt-"):
                continue
            out.append({"id": mid})

    out = sorted(out, key=lambda x: str(x.get("id") or ""))
    return AiModelsResponse(ok=True, models=out)


def _ai_ads_date_range(date_from: date, date_to: date | None) -> tuple[date, date]:
    to = date_to or date_from
    if to < date_from:
        raise HTTPException(status_code=400, detail="date_to must be >= date_from")
    # 안전장치: 무제한 기간을 LLM에 던지지 않는다(과금/응답지연/메모리 폭발 방지)
    days = (to - date_from).days + 1
    if days > 31:
        raise HTTPException(status_code=400, detail="date range too large (max 31 days)")
    return date_from, to


def _ai_ads_prev_range(date_from: date, date_to: date) -> tuple[date, date]:
    days = (date_to - date_from).days + 1
    prev_to = date_from - timedelta(days=1)
    prev_from = prev_to - timedelta(days=days - 1)
    return prev_from, prev_to


def _ai_num(x: object) -> float:
    try:
        return float(x)  # type: ignore[arg-type]
    except Exception:
        return 0.0


def _ai_agg_rows(rows: list[object], *, level: str) -> list[dict]:
    """
    list_campaign_daily / list_adgroup_daily 결과(일자별)를 키별(캠페인/광고그룹)로 합산한다.
    """
    out: dict[str, dict] = {}

    def getv(r: object, k: str) -> object:
        if isinstance(r, dict):
            return r.get(k)
        return getattr(r, k, None)

    for r in rows or []:
        if level == "campaign":
            cname = str(getv(r, "campaign_name") or "").strip()
            key = cname
            if not key:
                continue
            st = getv(r, "campaign_status")
        else:
            cname = str(getv(r, "campaign_name") or "").strip()
            gname = str(getv(r, "adgroup_name") or "").strip()
            key = f"{cname}||{gname}"
            if not cname or not gname:
                continue
            st = getv(r, "adgroup_status") or getv(r, "campaign_status")

        cur = out.get(key)
        if cur is None:
            cur = {
                "key": key,
                "campaign_name": cname,
                "adgroup_name": None if level == "campaign" else gname,
                "status": str(st or "").strip() or None,
                "impressions": 0.0,
                "clicks": 0.0,
                "cost": 0.0,
                "conversions": 0.0,
                "revenue": 0.0,
            }
            out[key] = cur

        cur["impressions"] += _ai_num(getv(r, "impressions"))
        cur["clicks"] += _ai_num(getv(r, "clicks"))
        cur["cost"] += _ai_num(getv(r, "cost"))
        cur["conversions"] += _ai_num(getv(r, "conversions"))
        cur["revenue"] += _ai_num(getv(r, "revenue"))

    # 파생지표 재계산
    res: list[dict] = []
    for v in out.values():
        imp = float(v["impressions"])
        clk = float(v["clicks"])
        cost = float(v["cost"])
        conv = float(v["conversions"])
        rev = float(v["revenue"])
        ctr = (clk / imp * 100.0) if imp > 0 else 0.0
        cpc = (cost / clk) if clk > 0 else 0.0
        cvr = (conv / clk * 100.0) if clk > 0 else 0.0
        roas = (rev / cost * 100.0) if cost > 0 else 0.0
        v["ctr"] = round(ctr, 4)
        v["cpc"] = round(cpc, 4)
        v["cvr"] = round(cvr, 4)
        v["roas"] = round(roas, 4)
        # 정수로 다루는 값들은 보기 좋게 정리
        v["impressions"] = int(round(imp))
        v["clicks"] = int(round(clk))
        v["cost"] = int(round(cost))
        v["conversions"] = int(round(conv))
        v["revenue"] = int(round(rev))
        res.append(v)

    # 기본 정렬: 비용 ↓, 노출 ↓
    res.sort(key=lambda x: (int(x.get("cost") or 0), int(x.get("impressions") or 0)), reverse=True)
    return res


def _json_loads_dict(raw: object) -> dict:
    if isinstance(raw, dict):
        return raw
    text0 = str(raw or "").strip()
    if not text0:
        return {}
    try:
        parsed = json.loads(text0)
    except Exception:
        return {}
    return parsed if isinstance(parsed, dict) else {}


def _json_loads_list(raw: object) -> list:
    if isinstance(raw, list):
        return raw
    text0 = str(raw or "").strip()
    if not text0:
        return []
    try:
        parsed = json.loads(text0)
    except Exception:
        return []
    return parsed if isinstance(parsed, list) else []


def _clamp_ai_ops_score(value: object) -> float:
    try:
        num = float(value or 0.0)
    except Exception:
        num = 0.0
    if num < 0:
        return 0.0
    if num > 100:
        return 100.0
    return round(num, 4)


def _ai_ops_normalize_name(text_value: object) -> str:
    return re.sub(r"\s+", " ", str(text_value or "").strip()).lower()


def _ai_ops_is_probable_product_url(text_value: object) -> bool:
    text0 = str(text_value or "").strip()
    if not text0:
        return False
    text1 = text0.lower()
    return (
        text1.startswith("http://")
        or text1.startswith("https://")
        or text1.startswith("smartstore.naver.com/")
        or ("/products/" in text1 and ("naver.com" in text1 or "smartstore" in text1))
    )


def _ai_ops_pick_display_product_name(*candidates: object) -> str | None:
    for candidate in candidates:
        text0 = str(candidate or "").strip()
        if not text0 or _ai_ops_is_probable_product_url(text0):
            continue
        return text0
    return None


def _ai_ops_state_strength_score(state_value: object) -> float:
    state0 = str(state_value or "").strip().upper()
    mapping = {
        "VERY_STABLE": 92.0,
        "STABLE_DEFENSE": 76.0,
        "GROWTH_NEEDED": 58.0,
        "RISK_RECOVERY": 36.0,
        "REFERENCE_ONLY": 24.0,
    }
    return float(mapping.get(state0, 50.0))


def _ai_ops_normalize_metric_map(metric_by_sku: dict[str, float]) -> dict[str, float]:
    if not metric_by_sku:
        return {}
    values = [float(v or 0.0) for v in metric_by_sku.values()]
    min_value = min(values)
    max_value = max(values)
    if max_value <= 0:
        return {sku_id: 0.0 for sku_id in metric_by_sku.keys()}
    if abs(max_value - min_value) < 1e-9:
        return {sku_id: (100.0 if float(value or 0.0) > 0 else 0.0) for sku_id, value in metric_by_sku.items()}
    out: dict[str, float] = {}
    for sku_id, value in metric_by_sku.items():
        out[sku_id] = _clamp_ai_ops_score(((float(value or 0.0) - min_value) / (max_value - min_value)) * 100.0)
    return out


def _ai_ops_choose_policy(
    *,
    qna_barrier_score: float,
    review_risk_score: float,
    organic_strength_score: float,
    sales_growth_score: float,
    qna_action_hint: str | None,
    thresholds: dict | None = None,
) -> tuple[str, str, str]:
    cfg = _merge_nested_dict(_ai_ops_default_thresholds(), thresholds if isinstance(thresholds, dict) else {})
    qna_threshold = float(cfg.get("qna_barrier_high") or 70.0)
    review_threshold = float(cfg.get("review_risk_high") or 65.0)
    growth = cfg.get("growth") if isinstance(cfg.get("growth"), dict) else {}
    defense = cfg.get("defense") if isinstance(cfg.get("defense"), dict) else {}
    growth_organic_min = float((growth or {}).get("organic_strength_min") or 80.0)
    growth_sales_min = float((growth or {}).get("sales_growth_min") or 60.0)
    growth_review_max = float((growth or {}).get("review_risk_max") or 45.0)
    growth_qna_max = float((growth or {}).get("qna_barrier_max") or 45.0)
    defense_organic_max = float((defense or {}).get("organic_strength_max") or 55.0)

    if qna_barrier_score >= qna_threshold:
        return (
            "FAQ_CONTENT_IMPROVEMENT",
            "구매 직전 문의와 상세 설명 부족 신호가 커서 FAQ/상세페이지 보강이 우선입니다.",
            str(qna_action_hint or "").strip() or "FAQ/상세페이지 보강",
        )
    if review_risk_score >= review_threshold:
        return (
            "VOC_IMPROVEMENT_PRIORITY",
            "리뷰 저평점과 부정 피드백 신호가 커서 광고 확대보다 VOC 개선이 우선입니다.",
            "리뷰/VOC 개선 우선",
        )
    if (
        organic_strength_score >= growth_organic_min
        and sales_growth_score >= growth_sales_min
        and review_risk_score < growth_review_max
        and qna_barrier_score < growth_qna_max
    ):
        return (
            "AD_GROWTH",
            "오가닉과 판매 신호가 안정적이어서 광고/SEO 확장 테스트를 검토할 수 있습니다.",
            "광고 확대 테스트",
        )
    if organic_strength_score < defense_organic_max:
        return (
            "AD_DEFENSE",
            "핵심 키워드 방어선이 약해져 광고/오가닉 방어 운영이 필요합니다.",
            "핵심 키워드 방어 광고",
        )
    return (
        "AD_DEFENSE",
        "확대보다 방어와 검증 중심의 운영이 적절합니다.",
        "방어 광고 3일 테스트",
    )


def _ai_ops_product_health_seed_targets(db: Session) -> list[dict[str, object]]:
    mapped_rows = db.query(A1SkuMap).order_by(A1SkuMap.sku_id.asc()).all()
    if mapped_rows:
        return [
            {
                "sku_id": str(getattr(row, "sku_id", "") or "").strip(),
                "product_url": str(getattr(row, "product_url", "") or "").strip() or None,
                "product_id_catalog": int(getattr(row, "product_id_catalog", 0) or 0) or None,
            }
            for row in mapped_rows
            if str(getattr(row, "sku_id", "") or "").strip()
        ]

    tracked_url_rows = (
        db.query(TrackedProductKeyword.product_url)
        .filter(TrackedProductKeyword.is_active.is_(True))
        .order_by(TrackedProductKeyword.product_url.asc())
        .distinct()
        .all()
    )
    tracked_urls = [
        _canonicalize_smartstore_base_url(row[0]) or str(row[0] or "").strip()
        for row in tracked_url_rows
        if str(row[0] or "").strip()
    ]
    tracked_urls = list(dict.fromkeys([url for url in tracked_urls if url]))
    if not tracked_urls:
        return []

    meta_rows = db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url.in_(tracked_urls)).all()
    meta_by_url: dict[str, TrackedProductMeta] = {}
    for row in meta_rows:
        key = _canonicalize_smartstore_base_url(getattr(row, "product_url", None)) or str(getattr(row, "product_url", "") or "").strip()
        if key and key not in meta_by_url:
            meta_by_url[key] = row

    seeds: list[dict[str, object]] = []
    for product_url in tracked_urls:
        meta_row = meta_by_url.get(product_url)
        try:
            product_id_catalog = int(getattr(meta_row, "product_id_catalog", 0) or 0) if meta_row is not None else 0
        except Exception:
            product_id_catalog = 0
        seeds.append(
            {
                "sku_id": product_url,
                "product_url": product_url,
                "product_id_catalog": product_id_catalog or None,
            }
        )
    return seeds


def _rebuild_ai_ops_product_health(target_date: date, db: Session) -> int:
    ai_settings = _get_ai_settings(db) or {}
    maps = _ai_ops_product_health_seed_targets(db)
    if not maps:
        db.query(DecisionProductHealthDaily).filter(DecisionProductHealthDaily.date == target_date).delete(synchronize_session=False)
        db.commit()
        return 0

    product_ids = [int(row.get("product_id_catalog") or 0) for row in maps if row.get("product_id_catalog")]
    product_ids = [pid for pid in product_ids if pid > 0]
    product_urls = [str(row.get("product_url") or "").strip() for row in maps if str(row.get("product_url") or "").strip()]

    meta_rows = []
    if product_urls:
        meta_rows = db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url.in_(product_urls)).all()
    meta_by_url: dict[str, TrackedProductMeta] = {}
    meta_by_product_id: dict[int, TrackedProductMeta] = {}
    for row in meta_rows:
        key = str(getattr(row, "product_url", "") or "").strip()
        if key and key not in meta_by_url:
            meta_by_url[key] = row
        try:
            product_id_catalog = int(getattr(row, "product_id_catalog", 0) or 0)
        except Exception:
            product_id_catalog = 0
        if product_id_catalog > 0 and product_id_catalog not in meta_by_product_id:
            meta_by_product_id[product_id_catalog] = row

    state_rows = (
        db.query(A1SkuStateDaily)
        .filter(A1SkuStateDaily.date == target_date, A1SkuStateDaily.sku_id.in_([str(getattr(row, "sku_id", "") or "") for row in maps]))
        .all()
    )
    surface_rank = {"mobile_integrated": 0, "organic_rank": 1}
    state_by_sku: dict[str, A1SkuStateDaily] = {}
    for row in state_rows:
        sku_id = str(getattr(row, "sku_id", "") or "").strip()
        if not sku_id:
            continue
        current = state_by_sku.get(sku_id)
        current_rank = surface_rank.get(str(getattr(current, "surface", "") or "").strip(), 99) if current is not None else 999
        next_rank = surface_rank.get(str(getattr(row, "surface", "") or "").strip(), 99)
        if current is None or next_rank < current_rank:
            state_by_sku[sku_id] = row

    sales_rows = []
    if product_ids:
        sales_rows = (
            db.query(NaverCommerceProductSalesDaily)
            .filter(
                NaverCommerceProductSalesDaily.product_id.in_(product_ids),
                NaverCommerceProductSalesDaily.source == "commerce_orders",
                NaverCommerceProductSalesDaily.date >= (target_date - timedelta(days=6)),
                NaverCommerceProductSalesDaily.date <= target_date,
            )
            .all()
        )
    sales_by_product_id: dict[int, list[NaverCommerceProductSalesDaily]] = {}
    for row in sales_rows:
        try:
            pid = int(getattr(row, "product_id", 0) or 0)
        except Exception:
            pid = 0
        if pid <= 0:
            continue
        sales_by_product_id.setdefault(pid, []).append(row)

    review_rows = []
    if product_ids:
        review_rows = (
            db.query(NaverProductReviewDaily)
            .filter(
                NaverProductReviewDaily.product_id.in_(product_ids),
                NaverProductReviewDaily.date >= (target_date - timedelta(days=30)),
                NaverProductReviewDaily.date <= target_date,
            )
            .all()
        )
    latest_review_by_product_id: dict[int, NaverProductReviewDaily] = {}
    for row in review_rows:
        try:
            pid = int(getattr(row, "product_id", 0) or 0)
        except Exception:
            pid = 0
        if pid <= 0:
            continue
        current = latest_review_by_product_id.get(pid)
        candidate_key = (
            getattr(row, "date", None) or date.min,
            int(getattr(row, "rating_count", 0) or 0),
            float(getattr(row, "rating_avg", 0.0) or 0.0),
        )
        current_key = (
            getattr(current, "date", None) or date.min,
            int(getattr(current, "rating_count", 0) or 0),
            float(getattr(current, "rating_avg", 0.0) or 0.0),
        ) if current is not None else (date.min, 0, 0.0)
        if current is None or candidate_key > current_key:
            latest_review_by_product_id[pid] = row

    qna_pairs = []
    window_from_dt = datetime.combine(target_date - timedelta(days=30), datetime.min.time())
    window_to_dt = datetime.combine(target_date + timedelta(days=1), datetime.min.time())
    try:
        qna_pairs = (
            db.query(CommerceQnaRaw, CommerceQnaAnalysis)
            .join(CommerceQnaAnalysis, CommerceQnaAnalysis.qna_key == CommerceQnaRaw.qna_key)
            .filter(
                or_(
                    and_(
                        CommerceQnaRaw.inquiry_registered_at.is_not(None),
                        CommerceQnaRaw.inquiry_registered_at >= window_from_dt,
                        CommerceQnaRaw.inquiry_registered_at < window_to_dt,
                    ),
                    and_(
                        CommerceQnaRaw.inquiry_registered_at.is_(None),
                        CommerceQnaAnalysis.updated_at >= window_from_dt,
                        CommerceQnaAnalysis.updated_at < window_to_dt,
                    ),
                )
            )
            .all()
        )
    except Exception:
        qna_pairs = []

    raw_sales_metric_by_sku: dict[str, float] = {}
    facts: list[dict] = []
    for map_row in maps:
        sku_id = str(map_row.get("sku_id") or "").strip()
        if not sku_id:
            continue
        product_url = str(map_row.get("product_url") or "").strip() or None
        try:
            product_id_catalog = int(map_row.get("product_id_catalog") or 0)
        except Exception:
            product_id_catalog = 0
        meta_row = meta_by_url.get(product_url or "")
        state_row = state_by_sku.get(sku_id)
        sales_for_product = sales_by_product_id.get(product_id_catalog, []) if product_id_catalog > 0 else []
        review_row = latest_review_by_product_id.get(product_id_catalog) if product_id_catalog > 0 else None

        sales_product_name = None
        latest_sales_date = date.min
        for sales_row in sales_for_product:
            sales_date = getattr(sales_row, "date", None) or date.min
            if sales_date >= latest_sales_date and str(getattr(sales_row, "product_name", "") or "").strip():
                latest_sales_date = sales_date
                sales_product_name = str(getattr(sales_row, "product_name", "") or "").strip()
        meta_title = str(getattr(meta_row, "title", "") or "").strip() if meta_row is not None else ""
        review_product_title = str(getattr(review_row, "product_title", "") or "").strip() if review_row is not None else ""
        mall_name = (
            str(getattr(meta_row, "mall_name", "") or "").strip()
            if meta_row is not None
            else str(_infer_smartstore_mall_name(product_url) or "").strip()
        ) or None
        product_name = _ai_ops_pick_display_product_name(meta_title, sales_product_name, review_product_title)

        candidate_names = {
            _ai_ops_normalize_name(product_name),
            _ai_ops_normalize_name(meta_title),
            _ai_ops_normalize_name(sales_product_name),
            _ai_ops_normalize_name(review_product_title),
        }
        candidate_names = {name for name in candidate_names if name}

        matched_qna_pairs: list[tuple[CommerceQnaRaw, CommerceQnaAnalysis]] = []
        for qna_raw_row, qna_analysis_row in qna_pairs:
            raw_product_no = str(getattr(qna_raw_row, "product_no", "") or "").strip()
            raw_product_name = _ai_ops_normalize_name(getattr(qna_raw_row, "product_name", None))
            pid_match = bool(product_id_catalog > 0 and raw_product_no and raw_product_no == str(product_id_catalog))
            name_match = bool(raw_product_name and raw_product_name in candidate_names)
            if pid_match or name_match:
                matched_qna_pairs.append((qna_raw_row, qna_analysis_row))

        qna_product_name = next(
            (
                str(getattr(qna_raw_row, "product_name", "") or "").strip()
                for qna_raw_row, _ in matched_qna_pairs
                if str(getattr(qna_raw_row, "product_name", "") or "").strip()
            ),
            None,
        )
        product_name = _ai_ops_pick_display_product_name(meta_title, sales_product_name, review_product_title, qna_product_name)

        sales_amount = sum(float(getattr(row, "amount", 0.0) or 0.0) for row in sales_for_product)
        sales_refund_amount = sum(float(getattr(row, "refund_amount", 0.0) or 0.0) for row in sales_for_product)
        sales_net_amount = max(0.0, sales_amount - sales_refund_amount)
        sales_order_count = sum(int(getattr(row, "order_count", 0) or 0) for row in sales_for_product)
        raw_sales_metric_by_sku[sku_id] = sales_net_amount

        review_risk_score = 0.0
        review_snapshot: dict[str, object] = {}
        if review_row is not None:
            rating_count = int(getattr(review_row, "rating_count", 0) or 0)
            low_rating_count = (
                int(getattr(review_row, "rating_1_cnt", 0) or 0)
                + int(getattr(review_row, "rating_2_cnt", 0) or 0)
                + int(getattr(review_row, "rating_3_cnt", 0) or 0)
            )
            low_ratio = (float(low_rating_count) / float(rating_count)) if rating_count > 0 else 0.0
            rating_avg = float(getattr(review_row, "rating_avg", 0.0) or 0.0)
            review_risk_score = _clamp_ai_ops_score((low_ratio * 100.0) + max(0.0, (4.3 - rating_avg) * 25.0))
            review_snapshot = {
                "rating_avg": rating_avg,
                "rating_count": rating_count,
                "low_rating_count": low_rating_count,
                "low_rating_ratio": round(low_ratio, 4),
            }

        qna_barrier_score = 0.0
        qna_action_hint = None
        qna_snapshot: dict[str, object] = {}
        if matched_qna_pairs:
            impact_scores = [float(getattr(analysis_row, "conversion_impact_score", 0.0) or 0.0) for _, analysis_row in matched_qna_pairs]
            avg_impact_score = (sum(impact_scores) / len(impact_scores)) if impact_scores else 0.0
            faq_count = sum(1 for _, analysis_row in matched_qna_pairs if bool(getattr(analysis_row, "faq_candidate_flag", False)))
            quality_count = sum(1 for _, analysis_row in matched_qna_pairs if bool(getattr(analysis_row, "quality_issue_flag", False)))
            complaint_count = sum(1 for _, analysis_row in matched_qna_pairs if bool(getattr(analysis_row, "complaint_flag", False)))
            qna_barrier_score = _clamp_ai_ops_score(max(avg_impact_score * 100.0, (faq_count * 20.0) + (quality_count * 25.0) + (complaint_count * 15.0)))
            qna_action_hint = next(
                (str(getattr(analysis_row, "recommended_action", "") or "").strip() for _, analysis_row in matched_qna_pairs if str(getattr(analysis_row, "recommended_action", "") or "").strip()),
                None,
            )
            qna_snapshot = {
                "count": len(matched_qna_pairs),
                "avg_conversion_impact_score": round(avg_impact_score, 4),
                "faq_candidate_count": faq_count,
                "quality_issue_count": quality_count,
                "complaint_count": complaint_count,
            }

        available_sources = 1  # sku map 자체는 항상 1개 소스로 본다.
        if state_row is not None:
            available_sources += 1
        if sales_for_product:
            available_sources += 1
        if review_row is not None:
            available_sources += 1
        if matched_qna_pairs:
            available_sources += 1
        data_quality_score = round(min(1.0, available_sources / 5.0), 4)

        organic_strength_score = _ai_ops_state_strength_score(getattr(state_row, "state", None) if state_row is not None else None)
        qna_confidence = (
            sum(float(getattr(analysis_row, "confidence_score", 0.0) or 0.0) for _, analysis_row in matched_qna_pairs) / len(matched_qna_pairs)
        ) if matched_qna_pairs else 0.45
        confidence_score = round(
            (
                (0.92 if state_row is not None else 0.45)
                + (0.95 if sales_for_product else 0.4)
                + (0.9 if review_row is not None else 0.45)
                + float(qna_confidence)
            )
            / 4.0,
            4,
        )

        facts.append(
            {
                "sku_id": sku_id,
                "product_url": product_url,
                "product_id_catalog": (product_id_catalog if product_id_catalog > 0 else None),
                "product_name": product_name,
                "mall_name": mall_name,
                "organic_strength_score": organic_strength_score,
                "sales_net_amount": sales_net_amount,
                "sales_amount": sales_amount,
                "sales_refund_amount": sales_refund_amount,
                "sales_order_count": sales_order_count,
                "review_risk_score": review_risk_score,
                "qna_barrier_score": qna_barrier_score,
                "qna_action_hint": qna_action_hint,
                "data_quality_score": data_quality_score,
                "confidence_score": confidence_score,
                "state": (str(getattr(state_row, "state", "") or "").strip() or None) if state_row is not None else None,
                "review_snapshot": review_snapshot,
                "qna_snapshot": qna_snapshot,
            }
        )

    sales_score_by_sku = _ai_ops_normalize_metric_map(raw_sales_metric_by_sku)
    ads_rollup_by_keyword = _ai_ops_ads_rollup_by_keyword(db, target_date=target_date)

    db.query(DecisionProductHealthDaily).filter(DecisionProductHealthDaily.date == target_date).delete(synchronize_session=False)

    saved = 0
    for fact in facts:
        sku_id = str(fact.get("sku_id") or "").strip()
        mall_name = str(fact.get("mall_name") or "").strip() or None
        ai_ops_rule_pack = _ai_ops_pick_rule_pack(ai_settings, mall_name=mall_name)
        ai_ops_thresholds = _merge_nested_dict(_ai_ops_default_thresholds(), (ai_ops_rule_pack.get("thresholds") if isinstance(ai_ops_rule_pack, dict) else None) or {})
        sales_growth_score = float(sales_score_by_sku.get(sku_id, 0.0))
        organic_strength_score = float(fact.get("organic_strength_score") or 0.0)
        review_risk_score = float(fact.get("review_risk_score") or 0.0)
        qna_barrier_score = float(fact.get("qna_barrier_score") or 0.0)
        ad_efficiency_score = _clamp_ai_ops_score((organic_strength_score * 0.45) + (sales_growth_score * 0.35) - (review_risk_score * 0.15) - (qna_barrier_score * 0.15) + 15.0)
        trend_momentum_score = sales_growth_score
        policy_type, top_issue, recommended_action_primary = _ai_ops_choose_policy(
            qna_barrier_score=qna_barrier_score,
            review_risk_score=review_risk_score,
            organic_strength_score=organic_strength_score,
            sales_growth_score=sales_growth_score,
            qna_action_hint=(fact.get("qna_action_hint") if isinstance(fact.get("qna_action_hint"), str) else None),
            thresholds=ai_ops_thresholds,
        )
        priority_score = _clamp_ai_ops_score(
            max(
                qna_barrier_score,
                review_risk_score,
                100.0 - organic_strength_score,
                sales_growth_score * (0.8 if organic_strength_score >= 70.0 else 0.5),
            )
        )
        evidence = {
            "target_date": target_date.isoformat(),
            "state": fact.get("state"),
            "policy_pack_id": str((ai_ops_rule_pack.get("rule_id") if isinstance(ai_ops_rule_pack, dict) else "") or "AI_OPS"),
            "mall_name": mall_name,
            "sales": {
                "amount": round(float(fact.get("sales_amount") or 0.0), 2),
                "refund_amount": round(float(fact.get("sales_refund_amount") or 0.0), 2),
                "net_amount": round(float(fact.get("sales_net_amount") or 0.0), 2),
                "order_count": int(fact.get("sales_order_count") or 0),
            },
            "review": fact.get("review_snapshot") or {},
            "qna": fact.get("qna_snapshot") or {},
        }
        product_id_catalog = int(fact.get("product_id_catalog") or 0) if fact.get("product_id_catalog") else 0
        overinvestment_candidate = _ai_ops_sales_overinvestment_candidate_from_metrics(
            snapshot_date=target_date,
            product_id=product_id_catalog,
            product_name=fact.get("product_name"),
            amount=float(fact.get("sales_amount") or 0.0),
            refund_amount=float(fact.get("sales_refund_amount") or 0.0),
            order_count=int(fact.get("sales_order_count") or 0),
            keyword=str(getattr(meta_by_product_id.get(product_id_catalog), "keyword", "") or "").strip(),
            ads_rollup=(
                ads_rollup_by_keyword.get(str(getattr(meta_by_product_id.get(product_id_catalog), "keyword", "") or "").strip(), {})
                if product_id_catalog > 0
                else {}
            ),
        ) if product_id_catalog > 0 else None
        if overinvestment_candidate is not None:
            evidence["sales"]["ad_overinvestment"] = {
                "keyword": overinvestment_candidate.get("keyword"),
                "ad_cost": overinvestment_candidate.get("ad_cost"),
                "ad_purchase_conversions": overinvestment_candidate.get("ad_purchase_conversions"),
                "ad_purchase_revenue": overinvestment_candidate.get("ad_purchase_revenue"),
                "ad_roas": overinvestment_candidate.get("ad_roas"),
                "ad_spend_ratio": overinvestment_candidate.get("ad_spend_ratio"),
            }
        db.add(
            DecisionProductHealthDaily(
                date=target_date,
                sku_id=sku_id,
                product_url=fact.get("product_url"),
                product_id_catalog=fact.get("product_id_catalog"),
                product_name=fact.get("product_name"),
                policy_type=policy_type,
                top_issue=top_issue,
                priority_score=priority_score,
                confidence_score=float(fact.get("confidence_score") or 0.0),
                data_quality_score=float(fact.get("data_quality_score") or 0.0),
                organic_strength_score=organic_strength_score,
                ad_efficiency_score=ad_efficiency_score,
                sales_growth_score=sales_growth_score,
                review_risk_score=review_risk_score,
                qna_barrier_score=qna_barrier_score,
                trend_momentum_score=trend_momentum_score,
                recommended_action_primary=recommended_action_primary,
                recommended_actions_json=json.dumps({"primary": recommended_action_primary}, ensure_ascii=False),
                evidence_json=json.dumps(evidence, ensure_ascii=False),
            )
        )
        rules_triggered = _ai_ops_rules_triggered(
            qna_barrier_score=qna_barrier_score,
            review_risk_score=review_risk_score,
            organic_strength_score=organic_strength_score,
            sales_growth_score=sales_growth_score,
            thresholds=ai_ops_thresholds,
            faq_candidate_count=int((((evidence.get("qna") or {}) if isinstance(evidence.get("qna"), dict) else {}).get("faq_candidate_count")) or 0),
        )
        if overinvestment_candidate is not None:
            rules_triggered.append("ad_overinvestment_detected")
            if str(recommended_action_primary or "").strip() != str(overinvestment_candidate.get("recommended_action") or "").strip():
                extra_action = str(overinvestment_candidate.get("recommended_action") or "").strip()
            else:
                extra_action = ""
        else:
            extra_action = ""
        inputs_snapshot = {
            "snapshot_date": target_date.isoformat(),
            "sku_id": sku_id,
            "mall_name": mall_name,
            "product_id_catalog": fact.get("product_id_catalog"),
            "product_name": fact.get("product_name"),
            "ai_ops_rule_pack": {
                "rule_id": str((ai_ops_rule_pack.get("rule_id") if isinstance(ai_ops_rule_pack, dict) else "") or "AI_OPS"),
                "title": str((ai_ops_rule_pack.get("title") if isinstance(ai_ops_rule_pack, dict) else "") or ""),
                "scope": (ai_ops_rule_pack.get("scope") if isinstance(ai_ops_rule_pack, dict) else {}) or {},
            },
            "scores": {
                "organic_strength_score": organic_strength_score,
                "ad_efficiency_score": ad_efficiency_score,
                "sales_growth_score": sales_growth_score,
                "review_risk_score": review_risk_score,
                "qna_barrier_score": qna_barrier_score,
                "trend_momentum_score": trend_momentum_score,
                "priority_score": priority_score,
                "data_quality_score": float(fact.get("data_quality_score") or 0.0),
            },
            "ai_ops_thresholds": ai_ops_thresholds,
            "evidence": evidence,
        }
        db.add(
            AiDecisionLog(
                log_id=str(uuid.uuid4()),
                analysis_type="AI_OPS_PRODUCT_HEALTH",
                entity_type="SKU",
                entity_id=sku_id,
                inputs_hash=_ai_hash_inputs(inputs_snapshot),
                inputs_json=_ai_json_dumps(inputs_snapshot),
                decision=policy_type,
                rules_triggered=_ai_json_dumps(rules_triggered),
                confidence=float(fact.get("confidence_score") or 0.0),
                recommended_actions=_ai_json_dumps(
                    [action for action in [recommended_action_primary, extra_action] if str(action or "").strip()]
                ),
                analysis_text=(
                    f"{top_issue} 광고 과투입도 함께 점검해야 합니다."
                    if overinvestment_candidate is not None
                    else top_issue
                ),
            )
        )
        saved += 1

    db.commit()
    return saved


def _serialize_action_queue_item(row: ActionQueueItem, db: Session | None = None) -> dict:
    payload = _json_loads_dict(getattr(row, "payload_json", None))
    return {
        "queue_id": str(getattr(row, "queue_id", "") or ""),
        "created_at": getattr(row, "created_at", None).isoformat() if getattr(row, "created_at", None) else None,
        "updated_at": getattr(row, "updated_at", None).isoformat() if getattr(row, "updated_at", None) else None,
        "source_scope": str(getattr(row, "source_scope", "") or ""),
        "entity_type": str(getattr(row, "entity_type", "") or ""),
        "entity_id": str(getattr(row, "entity_id", "") or ""),
        "action_type": str(getattr(row, "action_type", "") or ""),
        "priority": str(getattr(row, "priority", "") or ""),
        "status": str(getattr(row, "status", "") or ""),
        "reviewer": getattr(row, "reviewer", None),
        "review_note": getattr(row, "review_note", None),
        "payload": payload,
        "approval_recommendation": payload.get("approval_recommendation"),
        "approval_recommendation_reason": payload.get("approval_recommendation_reason"),
        "verification": _ai_ops_action_verification_summary(db, item=row) if db is not None else {},
    }


def _ai_ops_display_name_overrides(db: Session, rows: list[DecisionProductHealthDaily]) -> dict[str, str]:
    rows0 = list(rows or [])
    if not rows0:
        return {}

    product_urls = {
        str(getattr(row, "product_url", "") or "").strip()
        for row in rows0
        if str(getattr(row, "product_url", "") or "").strip()
    }
    product_ids: set[int] = set()
    sku_to_product_id: dict[str, int] = {}
    for row in rows0:
        sku_id = str(getattr(row, "sku_id", "") or "").strip()
        try:
            product_id = int(getattr(row, "product_id_catalog", 0) or 0)
        except Exception:
            product_id = 0
        if product_id > 0:
            product_ids.add(product_id)
            if sku_id:
                sku_to_product_id[sku_id] = product_id

    meta_by_url: dict[str, TrackedProductMeta] = {}
    meta_by_product_id: dict[int, TrackedProductMeta] = {}
    if product_urls or product_ids:
        meta_query = db.query(TrackedProductMeta)
        filters = []
        if product_urls:
            filters.append(TrackedProductMeta.product_url.in_(list(product_urls)))
        if product_ids:
            filters.append(TrackedProductMeta.product_id_catalog.in_(list(product_ids)))
        for meta_row in meta_query.filter(or_(*filters)).all():
            product_url = str(getattr(meta_row, "product_url", "") or "").strip()
            if product_url and product_url not in meta_by_url:
                meta_by_url[product_url] = meta_row
            try:
                product_id = int(getattr(meta_row, "product_id_catalog", 0) or 0)
            except Exception:
                product_id = 0
            if product_id > 0 and product_id not in meta_by_product_id:
                meta_by_product_id[product_id] = meta_row

    latest_review_by_product_id: dict[int, NaverProductReviewDaily] = {}
    if product_ids:
        for review_row in (
            db.query(NaverProductReviewDaily)
            .filter(NaverProductReviewDaily.product_id.in_(list(product_ids)))
            .order_by(NaverProductReviewDaily.date.desc(), NaverProductReviewDaily.rating_count.desc())
            .all()
        ):
            try:
                product_id = int(getattr(review_row, "product_id", 0) or 0)
            except Exception:
                product_id = 0
            if product_id > 0 and product_id not in latest_review_by_product_id:
                latest_review_by_product_id[product_id] = review_row

    overrides: dict[str, str] = {}
    for row in rows0:
        sku_id = str(getattr(row, "sku_id", "") or "").strip()
        if not sku_id:
            continue
        product_url = str(getattr(row, "product_url", "") or "").strip()
        product_id = sku_to_product_id.get(sku_id, 0)
        meta_title = str(getattr(meta_by_url.get(product_url), "title", "") or "").strip() if product_url in meta_by_url else ""
        if not meta_title and product_id > 0:
            meta_title = str(getattr(meta_by_product_id.get(product_id), "title", "") or "").strip()
        review_title = str(getattr(latest_review_by_product_id.get(product_id), "product_title", "") or "").strip() if product_id > 0 else ""
        display_name = _ai_ops_pick_display_product_name(
            getattr(row, "product_name", None),
            meta_title,
            review_title,
        )
        if display_name:
            overrides[sku_id] = display_name
    return overrides


def _serialize_ai_ops_log_item(
    *,
    db: Session,
    row: DecisionProductHealthDaily,
    decision_log: AiDecisionLog | None,
    latest_action: ActionQueueItem | None,
    display_product_name: str | None = None,
) -> dict:
    rules_triggered: list[str] = []
    recommended_actions: list[str] = []
    analysis_text = str(getattr(row, "top_issue", "") or "").strip()
    confidence_score = float(getattr(row, "confidence_score", 0.0) or 0.0)

    if decision_log is not None:
        try:
            parsed_rules = json.loads(str(getattr(decision_log, "rules_triggered", "") or "[]"))
            if isinstance(parsed_rules, list):
                rules_triggered = [str(x).strip() for x in parsed_rules if str(x).strip()]
        except Exception:
            rules_triggered = []
        try:
            parsed_actions = json.loads(str(getattr(decision_log, "recommended_actions", "") or "[]"))
            if isinstance(parsed_actions, list):
                recommended_actions = [str(x).strip() for x in parsed_actions if str(x).strip()]
        except Exception:
            recommended_actions = []
        analysis_text = str(getattr(decision_log, "analysis_text", "") or "").strip() or analysis_text
        if getattr(decision_log, "confidence", None) is not None:
            confidence_score = float(getattr(decision_log, "confidence", 0.0) or 0.0)

    if not recommended_actions:
        primary_action = str(getattr(row, "recommended_action_primary", "") or "").strip()
        if primary_action:
            recommended_actions = [primary_action]

    return {
        "date": getattr(row, "date", None).isoformat() if getattr(row, "date", None) else None,
        "sku_id": str(getattr(row, "sku_id", "") or ""),
        "product_name": display_product_name if display_product_name is not None else getattr(row, "product_name", None),
        "policy_type": getattr(row, "policy_type", None),
        "policy_pack_id": _ai_ops_policy_pack_id_from_row(row),
        "top_issue": getattr(row, "top_issue", None),
        "confidence_score": confidence_score,
        "latest_action_status": getattr(latest_action, "status", None) if latest_action is not None else None,
        "latest_action_note": getattr(latest_action, "review_note", None) if latest_action is not None else None,
        "latest_action_reviewer": getattr(latest_action, "reviewer", None) if latest_action is not None else None,
        "latest_action_type": getattr(latest_action, "action_type", None) if latest_action is not None else None,
        "latest_action_payload": _json_loads_dict(getattr(latest_action, "payload_json", None)) if latest_action is not None else {},
        "latest_action_verification": _ai_ops_action_verification_summary(db, item=latest_action) if latest_action is not None else {},
        "rules_triggered": rules_triggered,
        "recommended_actions": recommended_actions,
        "analysis_text": analysis_text,
        "evidence": _json_loads_dict(getattr(row, "evidence_json", None)),
    }


def _serialize_ai_ops_policy_item(rows: list[DecisionProductHealthDaily], *, display_name_by_sku: dict[str, str] | None = None) -> dict:
    if not rows:
        return {
            "policy_type": "UNCLASSIFIED",
            "sku_count": 0,
            "avg_priority_score": 0.0,
            "top_product_name": None,
            "top_priority_score": 0.0,
            "top_recommended_action": None,
            "top_policy_pack_id": None,
        }
    sorted_rows = sorted(
        rows,
        key=lambda row: (
            float(getattr(row, "priority_score", 0.0) or 0.0),
            float(getattr(row, "confidence_score", 0.0) or 0.0),
        ),
        reverse=True,
    )
    top_row = sorted_rows[0]
    avg_priority = round(
        sum(float(getattr(row, "priority_score", 0.0) or 0.0) for row in rows) / max(1, len(rows)),
        2,
    )
    return {
        "policy_type": str(getattr(top_row, "policy_type", "") or "UNCLASSIFIED"),
        "sku_count": len(rows),
        "avg_priority_score": avg_priority,
        "top_product_name": (
            (display_name_by_sku or {}).get(str(getattr(top_row, "sku_id", "") or "").strip())
            or getattr(top_row, "product_name", None)
        ),
        "top_priority_score": float(getattr(top_row, "priority_score", 0.0) or 0.0),
        "top_recommended_action": getattr(top_row, "recommended_action_primary", None),
        "top_policy_pack_id": (
            (_json_loads_dict(getattr(top_row, "evidence_json", None)).get("policy_pack_id"))
            if isinstance(_json_loads_dict(getattr(top_row, "evidence_json", None)), dict)
            else None
        ),
    }


def _ai_ops_policy_pack_id_from_row(row: DecisionProductHealthDaily | None) -> str | None:
    if row is None:
        return None
    evidence = _json_loads_dict(getattr(row, "evidence_json", None))
    if not isinstance(evidence, dict):
        return None
    value = str(evidence.get("policy_pack_id") or "").strip()
    return value or None


def _ai_ops_list_rule_packs(ai_settings: dict) -> list[dict]:
    fmt = str((ai_settings or {}).get("format_version") or "").strip().lower()
    packs = (ai_settings or {}).get("rule_packs") or []
    if fmt != "v2" or not isinstance(packs, list):
        return [
            {
                "rule_id": "AI_OPS",
                "title": "",
                "scope": _ai_ops_default_scope(),
                "thresholds": _ai_ops_default_thresholds(),
            }
        ]
    items: list[dict] = []
    seen_ids: set[str] = set()
    for pack in packs:
        if not isinstance(pack, dict) or not bool((pack or {}).get("enabled", True)):
            continue
        ai_ops = pack.get("ai_ops")
        if not isinstance(ai_ops, dict):
            continue
        rule_id = str((pack or {}).get("id") or "AI_OPS").strip() or "AI_OPS"
        if rule_id in seen_ids:
            continue
        seen_ids.add(rule_id)
        items.append(
            {
                "rule_id": rule_id,
                "title": str((pack or {}).get("title") or ""),
                "scope": _merge_nested_dict(
                    _ai_ops_default_scope(),
                    (ai_ops.get("scope") if isinstance(ai_ops, dict) else None) or {},
                ),
                "thresholds": _merge_nested_dict(
                    _ai_ops_default_thresholds(),
                    (ai_ops.get("thresholds") if isinstance(ai_ops, dict) else None) or {},
                ),
            }
        )
    if items:
        return items
    return [
        {
            "rule_id": "AI_OPS",
            "title": "",
            "scope": _ai_ops_default_scope(),
            "thresholds": _ai_ops_default_thresholds(),
        }
    ]


def _ai_ops_rules_triggered(
    *,
    qna_barrier_score: float,
    review_risk_score: float,
    organic_strength_score: float,
    sales_growth_score: float,
    thresholds: dict | None = None,
    faq_candidate_count: int = 0,
) -> list[str]:
    cfg = _merge_nested_dict(_ai_ops_default_thresholds(), thresholds if isinstance(thresholds, dict) else {})
    rules_triggered: list[str] = []
    if qna_barrier_score >= float(cfg.get("qna_barrier_high") or 70.0):
        rules_triggered.append("qna_barrier_high")
    if review_risk_score >= float(cfg.get("review_risk_high") or 65.0):
        rules_triggered.append("review_risk_high")
    defense = cfg.get("defense") if isinstance(cfg.get("defense"), dict) else {}
    growth = cfg.get("growth") if isinstance(cfg.get("growth"), dict) else {}
    if organic_strength_score < float((defense or {}).get("organic_strength_max") or 55.0):
        rules_triggered.append("organic_strength_low")
    if sales_growth_score >= float((growth or {}).get("sales_growth_min") or 60.0):
        rules_triggered.append("sales_growth_high")
    if int(faq_candidate_count or 0) > 0:
        rules_triggered.append("faq_candidate_detected")
    return rules_triggered


def _serialize_ai_ops_policy_compare_candidate(row: DecisionProductHealthDaily, *, display_product_name: str | None = None) -> dict:
    return {
        "sku_id": str(getattr(row, "sku_id", "") or ""),
        "product_name": display_product_name if display_product_name is not None else getattr(row, "product_name", None),
        "policy_type": getattr(row, "policy_type", None),
        "current_policy_pack_id": _ai_ops_policy_pack_id_from_row(row),
        "priority_score": float(getattr(row, "priority_score", 0.0) or 0.0),
    }


def _ai_ops_policy_compare_recommendation(
    *,
    current_policy_type: str | None,
    compare_item: dict,
    learning_item: dict | None = None,
    operation_learning_item: dict | None = None,
) -> tuple[float, str]:
    policy_type = str(compare_item.get("policy_type") or "").strip()
    matches_current_pack = bool(compare_item.get("matches_current_pack"))
    score = 0.0
    reasons: list[str] = []

    if not matches_current_pack and policy_type and policy_type != str(current_policy_type or "").strip():
        score += 18.0
        reasons.append(f"현재 정책과 다른 대안({policy_type})")
    if policy_type == "AD_GROWTH":
        score += 14.0
        reasons.append("확장형 정책")
    elif policy_type == "FAQ_CONTENT_IMPROVEMENT":
        score += 6.0
        reasons.append("FAQ 보강형 정책")
    elif policy_type == "VOC_IMPROVEMENT_PRIORITY":
        score += 5.0
        reasons.append("VOC 개선형 정책")

    if learning_item:
        improvement_rate = float(learning_item.get("improvement_rate") or 0.0)
        verified_count = int(learning_item.get("verified_count") or 0)
        avg_sales_growth_delta = float(learning_item.get("avg_sales_growth_delta") or 0.0)
        score += improvement_rate * 40.0
        score += min(verified_count, 10) * 2.0
        score += avg_sales_growth_delta * 0.6
        reasons.append(
            f"검증 개선율 {int(round(improvement_rate * 100))}% / 평균 매출성장 {avg_sales_growth_delta:+.0f}"
        )
    elif not matches_current_pack:
        reasons.append("학습 이력은 아직 없음")

    if operation_learning_item:
        operation_improvement_rate = float(operation_learning_item.get("improvement_rate") or 0.0)
        operation_verified_count = int(operation_learning_item.get("verified_count") or 0)
        operation_avg_purchase_conversions_delta = float(operation_learning_item.get("avg_purchase_conversions_delta") or 0.0)
        operation_avg_roas_delta = float(operation_learning_item.get("avg_roas_delta") or 0.0)
        score += operation_improvement_rate * 18.0
        score += min(operation_verified_count, 5) * 1.5
        score += max(0.0, operation_avg_purchase_conversions_delta) * 3.0
        score += max(0.0, operation_avg_roas_delta / 30.0)
        reasons.append(
            f"운영 학습 개선율 {int(round(operation_improvement_rate * 100))}% / 검증 {operation_verified_count}건"
        )

    if matches_current_pack:
        score -= 8.0
        reasons.append("현재 적용 정책팩")

    return round(score, 2), " / ".join(reasons[:4]) if reasons else "추천 근거 없음"


def _serialize_ai_ops_policy_compare_item(
    row: DecisionProductHealthDaily,
    *,
    rule_pack: dict,
    learning_item: dict | None = None,
    operation_learning_item: dict | None = None,
) -> dict:
    evidence = _json_loads_dict(getattr(row, "evidence_json", None))
    thresholds = (rule_pack.get("thresholds") if isinstance(rule_pack, dict) else None) or {}
    qna_action_hint = str((evidence or {}).get("qna_action_hint") or getattr(row, "recommended_action_primary", None) or "").strip()
    policy_type, top_issue, recommended_action_primary = _ai_ops_choose_policy(
        qna_barrier_score=float(getattr(row, "qna_barrier_score", 0.0) or 0.0),
        review_risk_score=float(getattr(row, "review_risk_score", 0.0) or 0.0),
        organic_strength_score=float(getattr(row, "organic_strength_score", 0.0) or 0.0),
        sales_growth_score=float(getattr(row, "sales_growth_score", 0.0) or 0.0),
        qna_action_hint=qna_action_hint or None,
        thresholds=thresholds,
    )
    qna_snapshot = (evidence.get("qna") if isinstance(evidence.get("qna"), dict) else {}) or {}
    item = {
        "policy_pack_id": str((rule_pack.get("rule_id") if isinstance(rule_pack, dict) else "") or "AI_OPS"),
        "policy_pack_title": str((rule_pack.get("title") if isinstance(rule_pack, dict) else "") or ""),
        "scope": (rule_pack.get("scope") if isinstance(rule_pack, dict) else {}) or {},
        "thresholds": thresholds,
        "policy_type": policy_type,
        "top_issue": top_issue,
        "recommended_action_primary": recommended_action_primary,
        "rules_triggered": _ai_ops_rules_triggered(
            qna_barrier_score=float(getattr(row, "qna_barrier_score", 0.0) or 0.0),
            review_risk_score=float(getattr(row, "review_risk_score", 0.0) or 0.0),
            organic_strength_score=float(getattr(row, "organic_strength_score", 0.0) or 0.0),
            sales_growth_score=float(getattr(row, "sales_growth_score", 0.0) or 0.0),
            thresholds=thresholds,
            faq_candidate_count=int((qna_snapshot.get("faq_candidate_count")) or 0),
        ),
        "matches_current_pack": _ai_ops_policy_pack_id_from_row(row)
        == str((rule_pack.get("rule_id") if isinstance(rule_pack, dict) else "") or "AI_OPS"),
    }
    recommendation_score, recommendation_reason = _ai_ops_policy_compare_recommendation(
        current_policy_type=getattr(row, "policy_type", None),
        compare_item=item,
        learning_item=learning_item,
        operation_learning_item=operation_learning_item,
    )
    item["recommendation_score"] = recommendation_score
    item["recommendation_reason"] = recommendation_reason
    item["learning_summary"] = learning_item or {}
    item["operation_learning_summary"] = operation_learning_item or {}
    item["recommended"] = False
    return item


def _ai_ops_compare_policy_type_for_rule_pack(row: DecisionProductHealthDaily, *, rule_pack: dict) -> str:
    evidence = _json_loads_dict(getattr(row, "evidence_json", None))
    thresholds = (rule_pack.get("thresholds") if isinstance(rule_pack, dict) else None) or {}
    qna_action_hint = str((evidence or {}).get("qna_action_hint") or getattr(row, "recommended_action_primary", None) or "").strip()
    policy_type, _top_issue, _recommended_action_primary = _ai_ops_choose_policy(
        qna_barrier_score=float(getattr(row, "qna_barrier_score", 0.0) or 0.0),
        review_risk_score=float(getattr(row, "review_risk_score", 0.0) or 0.0),
        organic_strength_score=float(getattr(row, "organic_strength_score", 0.0) or 0.0),
        sales_growth_score=float(getattr(row, "sales_growth_score", 0.0) or 0.0),
        qna_action_hint=qna_action_hint or None,
        thresholds=thresholds,
    )
    return str(policy_type or "").strip()


def _ai_ops_find_rule_pack(rule_packs: list[dict], *, rule_id: str | None) -> dict | None:
    target_rule_id = str(rule_id or "").strip()
    if not target_rule_id:
        return None
    for item in rule_packs:
        if str((item or {}).get("rule_id") or "").strip() == target_rule_id:
            return item
    return None


def _ai_ops_priority_from_score(priority_score: object) -> str:
    try:
        score = float(priority_score or 0.0)
    except Exception:
        score = 0.0
    if score >= 80.0:
        return "P1"
    if score >= 60.0:
        return "P2"
    return "P3"


def _ai_ops_compare_action_recommendation(
    *,
    recommendation_score: object,
    base_priority_score: object = 0.0,
    matches_current_pack: bool = False,
) -> tuple[str, str, str]:
    try:
        score = float(recommendation_score or 0.0)
    except Exception:
        score = 0.0
    try:
        base_score = float(base_priority_score or 0.0)
    except Exception:
        base_score = 0.0
    overall_score = max(score, base_score)
    if matches_current_pack:
        return (
            "P3",
            "HOLD",
            f"추천 점수 {round(score)}점이지만 현재 정책팩과 동일하므로 자동 승인은 보류합니다.",
        )
    if overall_score >= 80.0:
        return (
            "P1",
            "APPROVE",
            f"추천 점수 {round(score)}점 / SKU 긴급도 {round(base_score)}점으로 즉시 테스트 승인을 권장합니다.",
        )
    if overall_score >= 60.0:
        return (
            "P2",
            "REVIEW",
            f"추천 점수 {round(score)}점 / SKU 긴급도 {round(base_score)}점으로 운영자 검토 후 승인하는 것이 적절합니다.",
        )
    return (
        "P3",
        "HOLD",
        f"추천 점수 {round(score)}점 / SKU 긴급도 {round(base_score)}점으로 근거가 약해 우선 보류를 권장합니다.",
    )


