@app.get("/ai/ops/ads", response_model=dict)
def ai_ops_ads(
    limit: int = Query(default=30, ge=1, le=200),
    action_bucket: str | None = Query(default=None),
    db: Session = Depends(get_db),
):
    latest_date = _ai_ops_latest_ads_date(db)
    if latest_date is None:
        return {
            "ok": True,
            "summary": {"snapshot_date": None, "total_keywords": 0, "listed_count": 0, "action_buckets": []},
            "items": [],
        }

    rows = (
        db.query(NaverAdKeywordDaily)
        .filter(NaverAdKeywordDaily.date == latest_date)
        .order_by(NaverAdKeywordDaily.cost.desc(), NaverAdKeywordDaily.clicks.desc(), NaverAdKeywordDaily.keyword.asc())
        .all()
    )
    organic_rank_by_keyword = _ai_ops_latest_rank_by_keyword(db, target_date=latest_date)
    ad_action_learning_map = _ai_ops_ad_action_learning_map(db)
    overinvestment_learning_map = _ai_ops_overinvestment_learning_map(db)
    candidates = [item for item in (_ai_ops_ads_action_candidate(row) for row in rows) if item is not None]
    cannibalization_items = [
        item
        for item in (
            _ai_ops_apply_ad_action_learning(
                _ai_ops_ads_cannibalization_candidate(
                    row,
                    organic_rank=organic_rank_by_keyword.get(str(getattr(row, "keyword", "") or "").strip()),
                ),
                learning_item=ad_action_learning_map.get(
                    _ai_ops_ad_keyword_learning_key(
                        action_kind="CANNIBALIZATION_DECREASE",
                        keyword=str(getattr(row, "keyword", "") or "").strip(),
                    )
                ),
            )
            for row in rows
        )
        if item is not None
    ]
    budget_items: list[dict] = []
    for row in rows:
        candidate = _ai_ops_ads_budget_candidate(row)
        if candidate is None:
            continue
        keyword = str(candidate.get("keyword") or "").strip()
        action_kind = str(candidate.get("action_kind") or "").strip().upper()
        candidate = _ai_ops_apply_ad_action_learning(
            candidate,
            learning_item=ad_action_learning_map.get(
                _ai_ops_ad_keyword_learning_key(action_kind=action_kind, keyword=keyword)
            ),
        )
        if not ((candidate or {}).get("learning_summary") or {}).get("verified_count"):
            candidate = _ai_ops_apply_overinvestment_learning(
                candidate,
                learning_item=overinvestment_learning_map.get(keyword),
            )
        if candidate is not None:
            budget_items.append(candidate)
    action_bucket0 = str(action_bucket or "").strip().upper()
    if action_bucket0:
        candidates = [item for item in candidates if str(item.get("action_bucket") or "").upper() == action_bucket0]
    candidates = sorted(
        candidates,
        key=lambda item: (
            {"P1": 3, "P2": 2, "P3": 1}.get(str(item.get("priority") or "P3").upper(), 1),
            int(item.get("cost") or 0),
            int(item.get("clicks") or 0),
        ),
        reverse=True,
    )
    listed = candidates[: int(limit)]
    return {
        "ok": True,
        "summary": {
            "snapshot_date": latest_date.isoformat(),
            "total_keywords": len(rows),
            "listed_count": len(listed),
            "action_buckets": sorted({str(item.get("action_bucket") or "") for item in candidates if str(item.get("action_bucket") or "").strip()}),
            "cannibalization_count": len(cannibalization_items),
            "budget_count": len(budget_items),
            "selected_action_bucket": action_bucket0 or None,
        },
        "items": listed,
        "cannibalization_items": cannibalization_items,
        "budget_items": budget_items,
        "freshness": _ai_ops_freshness_payload(db),
    }


@app.post("/ai/ops/ads/actions", response_model=dict)
def ai_ops_ads_action_create(payload: AiOpsAdsActionCreateRequest, request: Request, db: Session = Depends(get_db)):
    latest_date = _ai_ops_latest_ads_date(db)
    if latest_date is None:
        raise HTTPException(status_code=404, detail="ad snapshot not found")
    row = (
        db.query(NaverAdKeywordDaily)
        .filter(
            NaverAdKeywordDaily.date == latest_date,
            NaverAdKeywordDaily.campaign_name == str(payload.campaign_name or "").strip(),
            NaverAdKeywordDaily.adgroup_name == str(payload.adgroup_name or "").strip(),
            NaverAdKeywordDaily.keyword == str(payload.keyword or "").strip(),
        )
        .first()
    )
    if row is None:
        raise HTTPException(status_code=404, detail="ad keyword not found in latest snapshot")
    candidate = _ai_ops_ads_action_candidate(row)
    if candidate is None:
        raise HTTPException(status_code=400, detail="ad keyword is not an action candidate")
    queue_payload = {
        "title": f"[광고 {str(candidate.get('action_bucket') or '')}] {str(candidate.get('keyword') or '')}",
        **candidate,
    }
    actor, actor_role = _ai_ops_reviewer_context(request)
    normalized_payload = _ai_ops_normalize_queue_payload(
        db=db,
        source_scope="ai-ops-ads",
        entity_type="ad_keyword",
        entity_id="::".join(
            [
                str(candidate.get("campaign_name") or ""),
                str(candidate.get("adgroup_name") or ""),
                str(candidate.get("keyword") or ""),
            ]
        ),
        action_type="QUEUE_AD_KEYWORD_ACTION",
        payload=queue_payload,
        actor=actor,
        actor_role=actor_role,
        event="QUEUED",
        status="PENDING",
    )
    item = ActionQueueItem(
        queue_id=str(uuid.uuid4()),
        source_scope="ai-ops-ads",
        entity_type="ad_keyword",
        entity_id=str((normalized_payload.get("target_identifier") or {}).get("entity_id") or normalized_payload.get("entity_id") or ""),
        action_type="QUEUE_AD_KEYWORD_ACTION",
        payload_json=json.dumps(normalized_payload, ensure_ascii=False),
        priority=str(candidate.get("priority") or "P3"),
        status="PENDING",
    )
    db.add(item)
    db.commit()
    db.refresh(item)
    return {"ok": True, "item": _serialize_action_queue_item(item, db=db)}


@app.post("/ai/ops/ads/budget-actions", response_model=dict)
def ai_ops_ads_budget_action_create(payload: AiOpsAdsBudgetActionCreateRequest, request: Request, db: Session = Depends(get_db)):
    latest_date = _ai_ops_latest_ads_date(db)
    if latest_date is None:
        raise HTTPException(status_code=404, detail="ad snapshot not found")
    row = (
        db.query(NaverAdKeywordDaily)
        .filter(
            NaverAdKeywordDaily.date == latest_date,
            NaverAdKeywordDaily.campaign_name == str(payload.campaign_name or "").strip(),
            NaverAdKeywordDaily.adgroup_name == str(payload.adgroup_name or "").strip(),
            NaverAdKeywordDaily.keyword == str(payload.keyword or "").strip(),
        )
        .first()
    )
    if row is None:
        raise HTTPException(status_code=404, detail="ad keyword not found in latest snapshot")
    action_kind = str(payload.action_kind or "").strip().upper()
    organic_rank_by_keyword = _ai_ops_latest_rank_by_keyword(db, target_date=latest_date)
    if action_kind == "CANNIBALIZATION_DECREASE":
        candidate = _ai_ops_ads_cannibalization_candidate(
            row,
            organic_rank=organic_rank_by_keyword.get(str(getattr(row, "keyword", "") or "").strip()),
        )
    else:
        candidate = _ai_ops_ads_budget_candidate(row)
    candidate = _ai_ops_apply_ad_action_learning(
        candidate,
        learning_item=_ai_ops_ad_action_learning_map(db).get(
            _ai_ops_ad_keyword_learning_key(action_kind=action_kind, keyword=str(getattr(row, "keyword", "") or "").strip())
        ),
    )
    if not ((candidate or {}).get("learning_summary") or {}).get("verified_count"):
        candidate = _ai_ops_apply_overinvestment_learning(
            candidate,
            learning_item=_ai_ops_overinvestment_learning_map(db).get(str(getattr(row, "keyword", "") or "").strip()),
        )
    if candidate is None or str(candidate.get("action_kind") or "").strip().upper() != action_kind:
        raise HTTPException(status_code=400, detail="ad keyword is not eligible for requested budget action")
    queue_payload = {
        "title": f"[광고 예산] {str(candidate.get('keyword') or '')}",
        **candidate,
    }
    actor, actor_role = _ai_ops_reviewer_context(request)
    normalized_payload = _ai_ops_normalize_queue_payload(
        db=db,
        source_scope="ai-ops-ads-budget",
        entity_type="ad_keyword",
        entity_id="::".join(
            [
                str(candidate.get("campaign_name") or ""),
                str(candidate.get("adgroup_name") or ""),
                str(candidate.get("keyword") or ""),
            ]
        ),
        action_type="QUEUE_AD_BUDGET_ACTION",
        payload=queue_payload,
        actor=actor,
        actor_role=actor_role,
        event="QUEUED",
        status="PENDING",
    )
    item = ActionQueueItem(
        queue_id=str(uuid.uuid4()),
        source_scope="ai-ops-ads-budget",
        entity_type="ad_keyword",
        entity_id=str((normalized_payload.get("target_identifier") or {}).get("entity_id") or normalized_payload.get("entity_id") or ""),
        action_type="QUEUE_AD_BUDGET_ACTION",
        payload_json=json.dumps(normalized_payload, ensure_ascii=False),
        priority=str(candidate.get("priority") or "P3"),
        status="PENDING",
    )
    db.add(item)
    db.commit()
    db.refresh(item)
    return {"ok": True, "item": _serialize_action_queue_item(item, db=db)}


@app.get("/ai/ops/sales", response_model=dict)
def ai_ops_sales(
    limit: int = Query(default=30, ge=1, le=200),
    action_bucket: str | None = Query(default=None),
    db: Session = Depends(get_db),
):
    latest_date = _ai_ops_latest_sales_date(db)
    if latest_date is None:
        return {
            "ok": True,
            "summary": {
                "snapshot_date": None,
                "total_products": 0,
                "listed_count": 0,
                "action_buckets": [],
                "focus_count": 0,
                "risk_hold_count": 0,
                "low_contribution_count": 0,
                "overinvestment_count": 0,
            },
            "items": [],
            "overinvestment_items": [],
        }

    rows = (
        db.query(NaverCommerceProductSalesDaily)
        .filter(
            NaverCommerceProductSalesDaily.date == latest_date,
            NaverCommerceProductSalesDaily.source == "commerce_orders",
        )
        .order_by(NaverCommerceProductSalesDaily.amount.desc(), NaverCommerceProductSalesDaily.product_id.asc())
        .all()
    )
    product_ids: list[int] = []
    for row in rows:
        try:
            product_id = int(getattr(row, "product_id", 0) or 0)
        except Exception:
            product_id = 0
        if product_id > 0:
            product_ids.append(product_id)
    meta_by_product_id = _ai_ops_sales_meta_by_product_id(db, product_ids=product_ids)
    ads_latest_date = _ai_ops_latest_ads_date(db)
    ads_rollup_by_keyword = _ai_ops_ads_rollup_by_keyword(db, target_date=ads_latest_date) if ads_latest_date is not None else {}
    overinvestment_learning_map = _ai_ops_overinvestment_learning_map(db)
    candidates = [item for item in (_ai_ops_sales_action_candidate(row) for row in rows) if item is not None]
    overinvestment_candidates = [
        item
        for item in (
            _ai_ops_apply_overinvestment_learning(
                _ai_ops_sales_overinvestment_candidate(
                    row,
                    meta_row=meta_by_product_id.get(int(getattr(row, "product_id", 0) or 0)),
                    ads_rollup_by_keyword=ads_rollup_by_keyword,
                ),
                learning_item=overinvestment_learning_map.get(
                    str(getattr(meta_by_product_id.get(int(getattr(row, "product_id", 0) or 0)), "keyword", "") or "").strip()
                ),
            )
            for row in rows
        )
        if item is not None
    ]
    action_bucket0 = str(action_bucket or "").strip().upper()
    filtered = [item for item in candidates if not action_bucket0 or str(item.get("action_bucket") or "").upper() == action_bucket0]
    overinvestment_filtered = [
        item for item in overinvestment_candidates if not action_bucket0 or str(item.get("action_bucket") or "").upper() == action_bucket0
    ]
    items = filtered[: int(limit)]
    overinvestment_items = overinvestment_filtered[: int(limit)]
    return {
        "ok": True,
        "summary": {
            "snapshot_date": latest_date.isoformat(),
            "total_products": len(rows),
            "listed_count": len(items),
            "action_buckets": sorted(
                {
                    str(item.get("action_bucket") or "")
                    for item in (candidates + overinvestment_candidates)
                    if item.get("action_bucket")
                }
            ),
            "focus_count": sum(1 for item in candidates if item.get("action_bucket") == "FOCUS"),
            "risk_hold_count": sum(1 for item in candidates if item.get("action_bucket") == "RISK_HOLD"),
            "low_contribution_count": sum(1 for item in candidates if item.get("action_bucket") == "LOW_CONTRIBUTION"),
            "overinvestment_count": sum(1 for item in overinvestment_candidates if item.get("action_bucket") == "AD_OVERINVESTMENT"),
        },
        "items": items,
        "overinvestment_items": overinvestment_items,
        "freshness": _ai_ops_freshness_payload(db),
    }


@app.post("/ai/ops/sales/actions", response_model=dict)
def ai_ops_sales_action_create(payload: AiOpsSalesActionCreateRequest, request: Request, db: Session = Depends(get_db)):
    latest_date = _ai_ops_latest_sales_date(db)
    if latest_date is None:
        raise HTTPException(status_code=404, detail="sales snapshot not found")
    row = (
        db.query(NaverCommerceProductSalesDaily)
        .filter(
            NaverCommerceProductSalesDaily.date == latest_date,
            NaverCommerceProductSalesDaily.source == "commerce_orders",
            NaverCommerceProductSalesDaily.product_id == int(payload.product_id),
        )
        .first()
    )
    if row is None:
        raise HTTPException(status_code=404, detail="product sales not found in latest snapshot")
    requested_bucket = str(payload.action_bucket or "").strip().upper()
    candidate = None
    if requested_bucket == "AD_OVERINVESTMENT":
        meta_by_product_id = _ai_ops_sales_meta_by_product_id(db, product_ids=[int(payload.product_id)])
        ads_latest_date = _ai_ops_latest_ads_date(db)
        ads_rollup_by_keyword = _ai_ops_ads_rollup_by_keyword(db, target_date=ads_latest_date) if ads_latest_date is not None else {}
        meta_row = meta_by_product_id.get(int(payload.product_id))
        candidate = _ai_ops_apply_overinvestment_learning(
            _ai_ops_sales_overinvestment_candidate(
                row,
                meta_row=meta_row,
                ads_rollup_by_keyword=ads_rollup_by_keyword,
            ),
            learning_item=_ai_ops_overinvestment_learning_map(db).get(str(getattr(meta_row, "keyword", "") or "").strip()),
        )
    else:
        candidate = _ai_ops_sales_action_candidate(row)
    if candidate is None or str(candidate.get("action_bucket") or "").strip().upper() != requested_bucket:
        raise HTTPException(status_code=400, detail="product is not eligible for requested sales action")
    queue_payload = {
        "title": f"[판매 {str(candidate.get('action_bucket') or '')}] {str(candidate.get('product_name') or payload.product_id)}",
        **candidate,
    }
    actor, actor_role = _ai_ops_reviewer_context(request)
    normalized_payload = _ai_ops_normalize_queue_payload(
        db=db,
        source_scope="ai-ops-sales",
        entity_type="product",
        entity_id=str(candidate.get("product_id") or payload.product_id),
        action_type="QUEUE_SALES_ACTION",
        payload=queue_payload,
        actor=actor,
        actor_role=actor_role,
        event="QUEUED",
        status="PENDING",
    )
    item = ActionQueueItem(
        queue_id=str(uuid.uuid4()),
        source_scope="ai-ops-sales",
        entity_type="product",
        entity_id=str(candidate.get("product_id") or payload.product_id),
        action_type="QUEUE_SALES_ACTION",
        payload_json=json.dumps(normalized_payload, ensure_ascii=False),
        priority=str(candidate.get("priority") or "P3"),
        status="PENDING",
    )
    db.add(item)
    db.commit()
    db.refresh(item)
    return {"ok": True, "item": _serialize_action_queue_item(item, db=db)}


