@app.post("/ai/ops/execution/run", response_model=dict)
def ai_ops_execution_run(payload: AiOpsExecutionRunRequest, request: Request, db: Session = Depends(get_db)):
    actor, actor_role = _ai_ops_reviewer_context(request, reviewer=payload.actor, reviewer_role=payload.actor_role)
    queue_ids = [str(queue_id or "").strip() for queue_id in (payload.queue_ids or []) if str(queue_id or "").strip()]
    query = db.query(ActionQueueItem)
    if queue_ids:
        query = query.filter(ActionQueueItem.queue_id.in_(queue_ids))
    else:
        query = query.filter(ActionQueueItem.status == "APPROVED")
    rows = query.order_by(ActionQueueItem.updated_at.asc(), ActionQueueItem.created_at.asc(), ActionQueueItem.queue_id.asc()).limit(int(payload.limit)).all()

    processed_items: list[dict] = []
    skipped_count = 0
    for item in rows:
        current_status = str(getattr(item, "status", "") or "").strip().upper()
        if current_status not in {"APPROVED", "DONE"}:
            skipped_count += 1
            continue
        queue_payload = _json_loads_dict(getattr(item, "payload_json", None))
        execution_block = queue_payload.get("execution") if isinstance(queue_payload.get("execution"), dict) else {}
        last_result = execution_block.get("last_result") if isinstance(execution_block.get("last_result"), dict) else {}
        execution_result = build_execution_result(
            queue_id=str(getattr(item, "queue_id", "") or ""),
            action_type=str(getattr(item, "action_type", "") or ""),
            payload=queue_payload,
            actor=actor,
            actor_role=actor_role,
            dry_run=bool(payload.dry_run),
        )
        if (
            str(last_result.get("execution_key") or "").strip()
            and str(last_result.get("execution_key") or "").strip() == str(execution_result.get("execution_key") or "").strip()
            and current_status == "DONE"
        ):
            skipped_count += 1
            continue
        history = execution_block.get("history") if isinstance(execution_block.get("history"), list) else []
        history = [entry for entry in history if isinstance(entry, dict)]
        history.append(execution_result)
        queue_payload["execution"] = {
            "adapter": execution_result.get("adapter"),
            "last_result": execution_result,
            "history": history[-20:],
        }
        queue_payload = _ai_ops_append_audit_entry(
            queue_payload,
            event="EXECUTED",
            actor=actor,
            actor_role=actor_role,
            note=str(execution_result.get("summary") or "").strip() or None,
            status=str(execution_result.get("status") or "DONE"),
        )
        item.payload_json = json.dumps(queue_payload, ensure_ascii=False)
        item.status = _normalize_ai_ops_action_status(execution_result.get("status"))
        item.reviewer = str(getattr(item, "reviewer", "") or "").strip() or actor
        item.updated_at = datetime.now(ZoneInfo("Asia/Seoul"))
        db.add(item)
        processed_items.append({"queue_id": str(getattr(item, "queue_id", "") or ""), "_item": item})
    db.commit()
    response_items = []
    for entry in processed_items:
        item = entry.get("_item")
        if item is None:
            continue
        db.refresh(item)
        response_items.append({"queue_id": entry.get("queue_id"), "item": _serialize_action_queue_item(item, db=db)})
    return {
        "ok": True,
        "summary": {
            "requested_count": len(queue_ids) if queue_ids else len(rows),
            "processed_count": len(response_items),
            "skipped_count": int(skipped_count or 0),
            "dry_run": bool(payload.dry_run),
        },
        "items": response_items,
    }


@app.get("/ai/ops/logs", response_model=dict)
def ai_ops_logs(
    limit: int = Query(default=50, ge=1, le=200),
    policy_pack_id: str | None = Query(default=None),
    db: Session = Depends(get_db),
):
    latest_date = _ai_ops_latest_health_date(db)
    if latest_date is None:
        return {"ok": True, "summary": {"snapshot_date": None, "total_items": 0, "policy_pack_ids": []}, "items": []}

    all_rows = (
        db.query(DecisionProductHealthDaily)
        .filter(DecisionProductHealthDaily.date == latest_date)
        .order_by(DecisionProductHealthDaily.priority_score.desc(), DecisionProductHealthDaily.sku_id.asc())
        .all()
    )
    policy_pack_ids = sorted({pack_id for pack_id in (_ai_ops_policy_pack_id_from_row(row) for row in all_rows) if pack_id})
    policy_pack_id0 = str(policy_pack_id or "").strip()
    rows = [
        row for row in all_rows if not policy_pack_id0 or _ai_ops_policy_pack_id_from_row(row) == policy_pack_id0
    ][: int(limit)]
    sku_ids = [str(getattr(row, "sku_id", "") or "").strip() for row in rows if str(getattr(row, "sku_id", "") or "").strip()]

    latest_logs: dict[str, AiDecisionLog] = {}
    if sku_ids:
        log_rows = (
            db.query(AiDecisionLog)
            .filter(
                AiDecisionLog.analysis_type == "AI_OPS_PRODUCT_HEALTH",
                AiDecisionLog.entity_id.in_(sku_ids),
            )
            .order_by(AiDecisionLog.created_at.desc())
            .all()
        )
        for log_row in log_rows:
            entity_id = str(getattr(log_row, "entity_id", "") or "").strip()
            if entity_id and entity_id not in latest_logs:
                latest_logs[entity_id] = log_row

    latest_actions: dict[str, ActionQueueItem] = {}
    if sku_ids:
        action_rows = (
            db.query(ActionQueueItem)
            .filter(ActionQueueItem.entity_type == "sku", ActionQueueItem.entity_id.in_(sku_ids))
            .order_by(ActionQueueItem.updated_at.desc(), ActionQueueItem.created_at.desc())
            .all()
        )
        for action_row in action_rows:
            entity_id = str(getattr(action_row, "entity_id", "") or "").strip()
            if entity_id and entity_id not in latest_actions:
                latest_actions[entity_id] = action_row

    display_name_by_sku = _ai_ops_display_name_overrides(db, rows)
    items = [
        _serialize_ai_ops_log_item(
            db=db,
            row=row,
            decision_log=latest_logs.get(str(getattr(row, "sku_id", "") or "").strip()),
            latest_action=latest_actions.get(str(getattr(row, "sku_id", "") or "").strip()),
            display_product_name=display_name_by_sku.get(str(getattr(row, "sku_id", "") or "").strip()),
        )
        for row in rows
    ]
    return {
        "ok": True,
        "summary": {
            "snapshot_date": latest_date.isoformat(),
            "total_items": len(items),
            "policy_pack_ids": policy_pack_ids,
            "selected_policy_pack_id": policy_pack_id0 or None,
        },
        "items": items,
    }


@app.get("/ai/ops/policies", response_model=dict)
def ai_ops_policies(
    db: Session = Depends(get_db),
):
    latest_date = _ai_ops_latest_health_date(db)
    ai_settings = _get_ai_settings(db) or {}
    if latest_date is None:
        return {
            "ok": True,
            "summary": {
                "snapshot_date": None,
                "total_skus": 0,
                "policy_count": 0,
                "rule_pack_count": len((ai_settings or {}).get("rule_packs") or []),
                "format_version": str((ai_settings or {}).get("format_version") or ""),
                "common_rules_len": len(str((ai_settings or {}).get("common_rules") or "")),
            },
            "learning_items": [],
            "items": [],
        }

    rows = (
        db.query(DecisionProductHealthDaily)
        .filter(DecisionProductHealthDaily.date == latest_date)
        .order_by(DecisionProductHealthDaily.priority_score.desc(), DecisionProductHealthDaily.sku_id.asc())
        .all()
    )
    display_name_by_sku = _ai_ops_display_name_overrides(db, rows)
    grouped: dict[str, list[DecisionProductHealthDaily]] = {}
    for row in rows:
        key = str(getattr(row, "policy_type", "") or "").strip() or "UNCLASSIFIED"
        grouped.setdefault(key, []).append(row)

    items = [
        _serialize_ai_ops_policy_item(policy_rows, display_name_by_sku=display_name_by_sku)
        for _, policy_rows in sorted(
            grouped.items(),
            key=lambda item: (
                len(item[1]),
                sum(float(getattr(row, "priority_score", 0.0) or 0.0) for row in item[1]),
            ),
            reverse=True,
        )
    ]
    learning_items = _ai_ops_policy_learning_items(db)
