@app.get("/ads/diagnose/creatives", response_model=dict)
def diagnose_creatives_missing(
    date_ymd: str = Query(..., description="YYYY-MM-DD"),
    campaign: str | None = Query(None, description="캠페인명(표시명)"),
    adgroup: str | None = Query(None, description="광고그룹명(표시명)"),
    limit: int = Query(5000, ge=1, le=20000),
    db: Session = Depends(get_db),
):
    """
    소재 누락 원인 단계별 진단(수집/저장/응답).

    - expected: /ncc/ads(광고그룹 전체 소재 목록)
    - stored: DB(naver_ad_creative_daily) 저장된 소재ID distinct 수
    - served: 현재 API 응답(limit 적용 가정)
    """
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", (date_ymd or "").strip()):
        raise HTTPException(status_code=400, detail="date_ymd must be YYYY-MM-DD")
    if not adgroup and not campaign:
        raise HTTPException(status_code=400, detail="campaign 또는 adgroup 중 하나는 필요합니다.")

    # 1) expected: 현재 메타 기준(이름->ID)로 adgroupId를 찾고 /ncc/ads로 소재ID 목록을 가져온다.
    try:
        (camp_map, grp_map, _kw, _cs, _gs) = _searchad_build_meta(include_keywords=False)
    except Exception:
        camp_map, grp_map = {}, {}

    # name -> gids
    gids: list[str] = []
    adgroup_name = str(adgroup or "").strip()
    if adgroup_name:
        for gid, nm in (grp_map or {}).items():
            if str(nm or "").strip() == adgroup_name:
                gids.append(str(gid))

    expected_ids: set[str] = set()
    if gids:
        try:
            meta = _searchad_build_ads_meta_by_adgroup(gids)
            if isinstance(meta, dict):
                expected_ids = {str(k).strip() for k in meta.keys() if str(k).strip()}
        except Exception:
            expected_ids = set()

    # 2) stored: DB에서 (date, campaign/adgroup) 필터로 distinct 소재ID 수를 센다.
    dt_obj = datetime.strptime(date_ymd, "%Y-%m-%d").date()
    q = db.query(NaverAdCreativeDaily.creative_id).filter(NaverAdCreativeDaily.date == dt_obj)
    if campaign:
        vs = _expand_campaign_names({str(campaign).strip()})
        q = q.filter(NaverAdCreativeDaily.campaign_name.in_(vs)) if vs else q
    if adgroup:
        q = q.filter(NaverAdCreativeDaily.adgroup_name == str(adgroup).strip())
    stored_ids = {str(x[0]).strip() for x in q.distinct().all() if x and str(x[0]).strip()}

    # 3) served: 현재 UI는 /creatives/daily를 limit으로 받으므로, served는 stored에서 limit만큼 나온다고 가정(정밀 진단은 추가로 확장 가능)
    served_cnt = min(len(stored_ids), int(limit))

    # diff
    missing_in_db = sorted(list(expected_ids - stored_ids)) if expected_ids else []
    stage = _diagnose_creatives_stage(
        expected_cnt=len(expected_ids),
        stored_cnt=len(stored_ids),
        served_cnt=served_cnt,
        limit=limit,
    )

    return {
        "date": date_ymd,
        "scope": {"campaign": str(campaign or "").strip() or None, "adgroup": adgroup_name or None},
        "expected": {"count": len(expected_ids), "sample_ids": missing_in_db[:20], "adgroup_ids": gids[:10]},
        "stored": {"count": len(stored_ids), "sample_ids": sorted(list(stored_ids))[:20]},
        "served": {"count": served_cnt, "limit": limit},
        "missing": {"missing_in_db_count": len(missing_in_db), "missing_in_db_sample": missing_in_db[:50]},
        "stage": stage,
        "note": "expected는 현재 시점의 /ncc/adgroups 이름 매핑을 사용합니다(과거 이름 변경 시 매칭이 어려울 수 있음).",
    }


class AdsCollectRequest(BaseModel):
    mode: str | None = "single"  # single | range
    date: str | None = None
    date_from: str | None = None
    date_to: str | None = None
    kinds: list[str] | None = None  # ["keyword","searchword","creative"]
    debug: bool | None = False
    # 선택 수집/검증용(소재 분석)
    campaigns: list[str] | None = None  # 캠페인명(표시명) 필터
    adgroups: list[str] | None = None  # 광고그룹명(표시명) 필터
    verify_missing: bool | None = True  # 소재 누락 검증/재시도(creative만)
    max_retries: int | None = 1  # 누락 시 재시도 횟수(creative만)
    # 강제 초기화(삭제 후 재수집)는 /ads/purge(삭제키)에서 수행한다.


@app.post("/ads/collect", response_model=dict)
def collect_ads(req: AdsCollectRequest):
    """
    실제 SearchAd API를 호출해 광고 성과(키워드/검색어)를 수집하고 DB에 적재한다.

    - mode=single: date (없으면 어제)
    - mode=range: date_from/date_to
    """
    mode = (req.mode or "single").strip().lower()
    # ads_daily의 대상 테이블은 키워드/검색어/소재 3종이다. 기본 수집에서도 소재를 누락하지 않는다.
    kinds = tuple((req.kinds or ["keyword", "searchword", "creative"]))
    if not kinds:
        kinds = ("keyword", "searchword", "creative")

    def _is_ymd(s: str) -> bool:
        return bool(re.match(r"^\d{4}-\d{2}-\d{2}$", (s or "").strip()))

    if mode == "single":
        d = (req.date or "").strip()
        if not d:
            d = (datetime.utcnow().date() - timedelta(days=1)).strftime("%Y-%m-%d")
        if not _is_ymd(d):
            raise HTTPException(status_code=400, detail="date must be YYYY-MM-DD")
        try:
            r = _collect_searchad_daily(
                d,
                kinds=kinds,  # type: ignore[arg-type]
                scope_campaigns=req.campaigns,
                scope_adgroups=req.adgroups,
                verify_missing=bool(req.verify_missing) if req.verify_missing is not None else False,
                max_retries=int(req.max_retries or 0),
            )
        except HTTPException as he:
            if he.status_code == 503 and "REPORT_NOT_READY" in str(he.detail or ""):
                # 5분 단위 백그라운드 재시도 큐에 등록
                try:
                    _REPORT_NOT_READY_SCHED.enqueue(
                        date=d,
                        kinds=kinds,  # type: ignore[arg-type]
                        scope_campaigns=req.campaigns,
                        scope_adgroups=req.adgroups,
                        verify_missing=bool(req.verify_missing) if req.verify_missing is not None else False,
                        max_retries=int(req.max_retries or 0),
                    )
                except Exception:
                    pass
                raise HTTPException(
                    status_code=503,
                    detail=f"{he.detail} (서버가 5분 간격으로 백그라운드에서 자동 재시도합니다)",
                )
            raise
        if req.debug:
            r["debug"] = {
                **(r.get("debug") or {}),
                "note": "debug is limited; use /ads/debug-report for raw samples",
                "timings": r.get("_timings"),
            }
        # debug가 아니면 내부 timings는 응답에서 제거(노이즈 최소화)
        else:
            try:
                r.pop("_timings", None)
            except Exception:
                pass
        return r

    if mode != "range":
        raise HTTPException(status_code=400, detail="mode must be single|range")

    df = (req.date_from or "").strip()
    dt = (req.date_to or "").strip()
    if not _is_ymd(df) or not _is_ymd(dt):
        raise HTTPException(status_code=400, detail="date_from/date_to must be YYYY-MM-DD")

    start = datetime.strptime(df, "%Y-%m-%d").date()
    end = datetime.strptime(dt, "%Y-%m-%d").date()
    if start > end:
        start, end = end, start

    days = (end - start).days + 1
    if days > 31:
        raise HTTPException(status_code=400, detail="date range too large (max 31 days)")

    processed: list[dict] = []
    ok = True
    errors: list[str] = []
    # range 성능/안전성:
    # - 캠페인/광고그룹 LIGHT 메타는 날짜별로 거의 변하지 않으므로 1회 생성 후 재사용한다.
    # - keyword meta(/ncc/keywords)도 광고그룹 단위로 누적 캐시해 재호출을 줄인다.
    # - 단, unknown ID 등장 시 _collect_searchad_daily 내부의 refresh 로직이 최신 상태로 보정할 수 있다.
    prebuilt_meta: dict = {}
    try:
        c_map, g_map, _kw_map, _cst, _gst = _searchad_build_meta(include_keywords=False)
        prebuilt_meta["campaign_name_map"] = c_map
        prebuilt_meta["adgroup_name_map"] = g_map
        prebuilt_meta["keyword_meta_map"] = {}
        prebuilt_meta["keyword_meta_built_gids"] = set()
    except Exception:
        # 메타가 실패해도 기존 로직(일자별 build_meta)로 수집은 가능해야 한다.
        prebuilt_meta = {}
    cur = start
    inserted_kw_total = 0
    inserted_sw_total = 0
    inserted_cr_total = 0
    while cur <= end:
        d = cur.strftime("%Y-%m-%d")
        try:
            r = _collect_searchad_daily(
                d,
                kinds=kinds,  # type: ignore[arg-type]
                scope_campaigns=req.campaigns,
                scope_adgroups=req.adgroups,
                verify_missing=bool(req.verify_missing) if req.verify_missing is not None else False,
                max_retries=int(req.max_retries or 0),
                prebuilt_meta=prebuilt_meta if prebuilt_meta else None,
            )
        except HTTPException as he:
            if he.status_code == 503 and "REPORT_NOT_READY" in str(he.detail or ""):
                # range 모드에서는 "다른 날짜는 계속 수집"하고, 준비중 날짜는 백그라운드로 넘긴다.
                try:
                    _REPORT_NOT_READY_SCHED.enqueue(
                        date=d,
                        kinds=kinds,  # type: ignore[arg-type]
                        scope_campaigns=req.campaigns,
                        scope_adgroups=req.adgroups,
                        verify_missing=bool(req.verify_missing) if req.verify_missing is not None else False,
                        max_retries=int(req.max_retries or 0),
                    )
                except Exception:
                    pass
                r = {"ok": False, "date": d, "insertedKeyword": 0, "insertedSearchword": 0, "insertedCreative": 0, "errors": [str(he.detail)]}
            else:
                raise
        processed.append(r)
        # range 응답도 debug 모드에서만 timings를 보이게 한다.
        if not req.debug:
            try:
                r.pop("_timings", None)
            except Exception:
                pass
        inserted_kw_total += int(r.get("insertedKeyword") or 0)
        inserted_sw_total += int(r.get("insertedSearchword") or 0)
        inserted_cr_total += int(r.get("insertedCreative") or 0)
        if not r.get("ok"):
            ok = False
            for e in r.get("errors") or []:
                errors.append(f"{d}: {e}")
        cur = cur + timedelta(days=1)

    out = {
        "ok": ok,
        "from": df,
        "to": dt,
        "insertedKeyword": inserted_kw_total,
        "insertedSearchword": inserted_sw_total,
        "insertedCreative": inserted_cr_total,
        "processed": processed,
        "errors": errors,
    }
    if req.debug:
        out["debug"] = {
            **(out.get("debug") or {}),
            "note": "debug is limited; use /ads/debug-report for raw samples",
            "timingsByDay": [{p.get("date"): p.get("_timings")} for p in (processed or [])],
        }
    return out


class GfaReportCdpRequest(BaseModel):
    ad_account_no: str
    date_from: date
    date_to: date
    created_by_device_id: str | None = None


class GfaCampaignInventoryCdpRequest(BaseModel):
    ad_account_no: str
    campaign_type: str = "website_conversion"
    created_by_device_id: str | None = None


class GfaAdgroupInventoryCdpRequest(BaseModel):
    ad_account_no: str
    campaign_type: str = "website_conversion"
    created_by_device_id: str | None = None


def _gfa_csv_key_signature(v: object) -> str:
    return re.sub(r"[^0-9a-z가-힣]+", "", str(v or "").lower())


GFA_REQUIRED_CONVERSION_HEADER_GROUPS = (
    ("구매완료 수", "구매완료수", "구매완료 전환수", "구매완료전환수", "구매 전환수", "구매전환수", "purchase_conv_count", "purchase_conversions"),
    ("구매완료 전환매출액", "구매완료전환매출액", "구매완료 매출액", "구매완료매출액", "구매 전환매출액", "구매전환매출액", "purchase_conv_sales_krw", "purchase_revenue"),
)


def _gfa_csv_has_header(headers: list[str], keys: tuple[str, ...]) -> bool:
    header_signatures = {_gfa_csv_key_signature(h) for h in headers if str(h or "").strip()}
    for key in keys:
        sig = _gfa_csv_key_signature(key)
        if not sig:
            continue
        if sig in header_signatures:
            return True
        if re.search(r"[가-힣]", str(key or "")) and any(sig in header or header in sig for header in header_signatures):
            return True
    return False


def _gfa_validate_conversion_headers(headers: list[str], filename: str) -> None:
    missing_groups = [
        group[0]
        for group in GFA_REQUIRED_CONVERSION_HEADER_GROUPS
        if not _gfa_csv_has_header(headers, group)
    ]
    if missing_groups:
        raise HTTPException(
            status_code=422,
            detail={
                "code": "gfa_conversion_columns_missing",
                "message": "GFA 성과보고서에 전환 열 맞춤 설정 컬럼이 없습니다. 열 맞춤 설정에서 '전환'을 선택한 뒤 다시 수집해야 합니다.",
                "filename": filename,
                "missing": missing_groups,
                "headers": headers,
            },
        )


def _gfa_csv_first(row: dict, keys: list[str]) -> str:
    normalized = {re.sub(r"\s+", "", str(k or "")).lower(): v for k, v in row.items()}
    signatures = {_gfa_csv_key_signature(k): v for k, v in row.items()}
    for key in keys:
        if key in row and row.get(key) not in (None, ""):
            return str(row.get(key) or "").strip()
        nk = re.sub(r"\s+", "", str(key or "")).lower()
        if nk in normalized and normalized.get(nk) not in (None, ""):
            return str(normalized.get(nk) or "").strip()
        sig = _gfa_csv_key_signature(key)
        if sig in signatures and signatures.get(sig) not in (None, ""):
            return str(signatures.get(sig) or "").strip()
        if re.search(r"[가-힣]", str(key or "")) and len(sig) >= 5:
            for header, value in signatures.items():
                if value not in (None, "") and (sig in header or header in sig):
                    return str(value or "").strip()
    return ""


def _gfa_csv_int(v: object) -> int:
    try:
        if v is None:
            return 0
        if isinstance(v, bool):
            return int(v)
        if isinstance(v, (int, float)):
            return int(v)
        s = str(v).strip().replace(",", "")
        if not s or s in {"-", "--"}:
            return 0
        s = re.sub(r"[^\d.\-]", "", s)
        return int(float(s)) if s else 0
    except Exception:
        return 0


def _gfa_csv_float(v: object) -> float:
    try:
        if v is None:
            return 0.0
        if isinstance(v, (int, float)):
            f = float(v)
        else:
            s = str(v).strip().replace(",", "")
            if not s or s in {"-", "--"}:
                return 0.0
            s = re.sub(r"[^\d.\-]", "", s)
            f = float(s) if s else 0.0
        return f if math.isfinite(f) else 0.0
    except Exception:
        return 0.0


def _gfa_csv_date(v: object) -> str:
    s = str(v or "").strip()
    if not s:
        return ""
    s = s.replace(".", "-").replace("/", "-")
    s = re.sub(r"-+$", "", s)
    parts = [p for p in s.split("-") if p]
    if len(parts) >= 3:
        try:
            return f"{int(parts[0]):04d}-{int(parts[1]):02d}-{int(parts[2]):02d}"
        except Exception:
            return ""
    return s if re.match(r"^\d{4}-\d{2}-\d{2}$", s) else ""


def _gfa_decode_csv_bytes(data: bytes) -> str:
    for enc in ("utf-8-sig", "cp949", "euc-kr", "utf-8"):
        try:
            return data.decode(enc)
        except Exception:
            continue
    return data.decode("utf-8", errors="replace")


def _gfa_extract_csv_files(filename: str, data: bytes) -> list[tuple[str, bytes]]:
    lower = (filename or "").lower()
    if lower.endswith(".zip"):
        out: list[tuple[str, bytes]] = []
        with zipfile.ZipFile(io.BytesIO(data)) as zf:
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                if name.lower().endswith(".csv"):
                    out.append((name, zf.read(info)))
        if not out:
            raise HTTPException(status_code=400, detail="zip 내부에 csv 파일이 없습니다.")
        return out
    if not lower.endswith(".csv"):
        raise HTTPException(status_code=400, detail="result.csv 또는 ReportDownload_*.zip 파일만 업로드할 수 있습니다.")
    return [(filename or "result.csv", data)]


def _gfa_parse_report_csv(data: bytes, *, filename: str = "result.csv", ad_unit: str = "CREATIVE") -> list[dict]:
    unit = str(ad_unit or "CREATIVE").strip().upper()
    text0 = _gfa_decode_csv_bytes(data)
    sample = text0[:4096]
    try:
        dialect = csv.Sniffer().sniff(sample)
    except Exception:
        dialect = csv.excel
    reader = csv.DictReader(io.StringIO(text0), dialect=dialect)
    _gfa_validate_conversion_headers([str(h or "").strip() for h in (reader.fieldnames or [])], filename)
    records: list[dict] = []
    for row in reader:
        target_date = _gfa_csv_date(
            _gfa_csv_first(row, ["일", "일별", "날짜", "기간", "date", "schedule", "일자"])
        )
        campaign_id = _gfa_csv_first(row, ["캠페인 ID", "캠페인ID", "campaign_id", "campaignId", "Campaign ID"])
        campaign_name = _gfa_csv_first(row, ["캠페인", "캠페인 이름", "캠페인명", "campaign_name", "Campaign"])
        adgroup_id = _gfa_csv_first(row, ["광고그룹 ID", "광고 그룹 ID", "광고그룹ID", "에셋 그룹 ID", "에셋그룹ID", "애셋 그룹 ID", "애셋그룹ID", "소재 그룹 ID", "소재그룹 ID", "소재그룹ID", "asset_group_id", "adgroup_id", "adSetNo", "Ad Group ID"])
        adgroup_name = _gfa_csv_first(row, ["광고그룹", "광고 그룹", "광고그룹 이름", "광고 그룹 이름", "에셋 그룹", "에셋그룹", "에셋 그룹 이름", "에셋그룹 이름", "애셋 그룹", "애셋그룹", "애셋 그룹 이름", "애셋그룹 이름", "소재 그룹", "소재그룹", "소재 그룹 이름", "소재그룹 이름", "소재 그룹명", "소재그룹명", "asset_group_name", "adgroup_name", "Ad Group"])
        creative_id = _gfa_csv_first(row, ["광고 소재 ID", "광고소재ID", "소재 ID", "소재ID", "creative_id", "creativeId", "Creative ID"])
        creative_name = _gfa_csv_first(row, ["광고 소재 이름", "광고소재이름", "소재", "소재 이름", "소재명", "creative_name", "Creative"])
        if unit == "CAMPAIGN" and not creative_id:
            creative_id = "__campaign__:" + (campaign_id or campaign_name or "unknown")
            creative_name = creative_name or campaign_name
        elif unit == "ASSET_GROUP" and not creative_id:
            creative_id = "__asset_group__:" + (adgroup_id or adgroup_name or campaign_id or campaign_name or "unknown")
            creative_name = creative_name or adgroup_name
        if not target_date or not creative_id:
            continue
        records.append(
            {
                "date": target_date,
                "raw_payload": {str(k or "").strip(): ("" if v is None else str(v)) for k, v in row.items()},
                "campaign_id": campaign_id,
                "campaign_name": campaign_name,
                "adgroup_id": adgroup_id,
                "adgroup_name": adgroup_name,
                "creative_id": creative_id,
                "creative_name": creative_name,
                "placement": _gfa_csv_first(row, ["게재위치", "게재 위치", "placement", "Placement"]) or "전체",
                "audience": _gfa_csv_first(row, ["연령/성별", "연령 및 성별", "타겟", "audience", "Age/Gender"]) or "전체",
                "result_type": _gfa_csv_first(row, ["결과 유형", "결과유형", "result_type"]),
                "cost_per_result_type": _gfa_csv_first(row, ["결과당 비용 유형", "cost_per_result_type"]),
                "started_on": _gfa_csv_date(_gfa_csv_first(row, ["시작일", "시작 일", "started_on"])),
                "ended_on": _gfa_csv_first(row, ["종료일", "종료 일", "ended_on"]),
                "results": _gfa_csv_int(_gfa_csv_first(row, ["결과", "result", "results"])),
                "cost_per_result": _gfa_csv_float(_gfa_csv_first(row, ["결과당 비용", "sales_per_result", "cost_per_result"])),
                "cost": _gfa_csv_int(_gfa_csv_first(row, ["총비용", "총 비용", "비용", "총비용(원)", "sales", "cost"])),
                "impressions": _gfa_csv_int(_gfa_csv_first(row, ["노출수", "노출", "imp_count", "impressions"])),
                "cpm": _gfa_csv_float(_gfa_csv_first(row, ["평균 CPM", "CPM", "cpm"])),
                "clicks": _gfa_csv_int(_gfa_csv_first(row, ["클릭수", "클릭", "click_count", "clicks"])),
                "cpc": _gfa_csv_float(_gfa_csv_first(row, ["평균 CPC", "CPC", "cpc"])),
                "ctr": _gfa_csv_float(_gfa_csv_first(row, ["클릭률(%)", "CTR", "클릭률", "ctr"])),
                "conversions": _gfa_csv_int(_gfa_csv_first(row, ["총 전환수", "총전환수", "전환수", "conv_count", "conversions"])),
                "purchase_conversions": _gfa_csv_int(_gfa_csv_first(row, ["구매완료 수", "구매완료수", "구매완료 전환수", "구매완료전환수", "구매 전환수", "구매전환수", "purchase_conv_count", "purchase_conversions"])),
                "cart_conversions": _gfa_csv_int(_gfa_csv_first(row, ["장바구니 담기 수", "장바구니담기수", "장바구니 전환수", "장바구니전환수", "cart_conv_count", "cart_conversions"])),
                "revenue": _gfa_csv_int(_gfa_csv_first(row, ["총 전환매출액", "총전환매출액", "전환매출액", "전환 매출액", "conv_sales_krw", "revenue"])),
                "purchase_revenue": _gfa_csv_int(_gfa_csv_first(row, ["구매완료 전환매출액", "구매완료전환매출액", "구매완료 매출액", "구매완료매출액", "구매 전환매출액", "구매전환매출액", "purchase_conv_sales_krw", "purchase_revenue"])),
                "cart_revenue": _gfa_csv_int(_gfa_csv_first(row, ["장바구니 전환매출액", "장바구니전환매출액", "장바구니 매출액", "장바구니매출액", "cart_conv_sales_krw", "cart_revenue"])),
                "cvr": _gfa_csv_float(_gfa_csv_first(row, ["총 전환율(%)", "CVR", "전환율", "cvr"])),
                "roas": _gfa_csv_float(_gfa_csv_first(row, ["총 광고수익률(%)", "총 ROAS", "ROAS", "roas"])),
                "purchase_roas": _gfa_csv_float(_gfa_csv_first(row, ["구매완료 광고수익률(%)", "구매완료 ROAS", "구매 ROAS", "purchase_roas"])),
            }
        )
        last = records[-1]
        result_type_compact = re.sub(r"\s+", "", str(last.get("result_type") or "")).lower()
        if ("구매" in result_type_compact or "purchase" in result_type_compact) and int(last.get("purchase_conversions") or 0) <= 0:
            last["purchase_conversions"] = int(last.get("results") or 0)
        if int(last.get("conversions") or 0) <= 0:
            last["conversions"] = int(last.get("purchase_conversions") or 0) + int(last.get("cart_conversions") or 0)
        if int(last.get("revenue") or 0) <= 0:
            last["revenue"] = int(last.get("purchase_revenue") or 0) + int(last.get("cart_revenue") or 0)
    return records


def _gfa_source_for_ad_unit(ad_unit: str | None, fallback: str = GFA_CONVERSION_COMPLETE_SOURCE) -> str:
    unit = str(ad_unit or "").strip().upper()
    if unit == "CREATIVE":
        return GFA_CONVERSION_COMPLETE_SOURCE_CREATIVE
    if unit == "CAMPAIGN":
        return GFA_CONVERSION_COMPLETE_SOURCE_CAMPAIGN
    if unit == "ASSET_GROUP":
        return GFA_CONVERSION_COMPLETE_SOURCE_ASSET_GROUP
    return fallback


def _gfa_ad_unit_from_url(url: str | None) -> str:
    try:
        parsed = urllib.parse.urlparse(str(url or ""))
        values = urllib.parse.parse_qs(parsed.query).get("adUnit") or []
        unit = str(values[0] if values else "").strip().upper()
        return unit if unit in {"CREATIVE", "CAMPAIGN", "ASSET_GROUP"} else "CREATIVE"
    except Exception:
        return "CREATIVE"


def _gfa_mark_no_data_dates(date_from: date, date_to: date, ad_unit: str) -> dict:
    if date_to < date_from:
        date_from, date_to = date_to, date_from
    unit = str(ad_unit or "CREATIVE").strip().upper()
    if unit not in {"CREATIVE", "CAMPAIGN", "ASSET_GROUP"}:
        unit = "CREATIVE"
    source = _gfa_source_for_ad_unit(unit, fallback=GFA_CONVERSION_COMPLETE_SOURCE)
    records: list[dict] = []
    cur = date_from
    while cur <= date_to:
        records.append(
            {
                "date": cur.isoformat(),
                "campaign_id": "__no_data__",
                "campaign_name": "",
                "adgroup_id": "",
                "adgroup_name": "",
                "creative_id": f"__no_data__:{unit.lower()}",
                "creative_name": "",
                "placement": "전체",
                "audience": "전체",
            }
        )
        cur = cur + timedelta(days=1)
    inserted_total = upsert_gfa_daily_records(records, source=source)
    processed_dates = [str(row["date"]) for row in records]
    return {
        "ok": True,
        "source": source,
        "ad_unit": unit,
        "no_data": True,
        "inserted_total": inserted_total,
        "inserted_by_date": {ymd: 1 for ymd in processed_dates},
        "processed_dates": processed_dates,
    }


def _gfa_fill_missing_report_dates(upload_response: dict, date_from: date, date_to: date, ad_unit: str) -> dict:
    if not isinstance(upload_response, dict):
        return upload_response
    if upload_response.get("no_data") is True:
        return upload_response
    if date_to < date_from:
        date_from, date_to = date_to, date_from
    processed_raw = upload_response.get("processed_dates")
    if isinstance(processed_raw, list):
        processed = {_collection_parse_date(x) for x in processed_raw}
    else:
        inserted = upload_response.get("inserted_by_date") or {}
        processed = {_collection_parse_date(x) for x in inserted.keys()} if isinstance(inserted, dict) else set()
    processed = {x for x in processed if x is not None}
    missing_dates: list[date] = []
    cur = date_from
    while cur <= date_to:
        if cur not in processed:
            missing_dates.append(cur)
        cur = cur + timedelta(days=1)
    if not missing_dates:
        return upload_response
    filled_details: list[dict] = []
    inserted_by_date = dict(upload_response.get("inserted_by_date") or {})
    processed_dates = sorted({str(x) for x in (upload_response.get("processed_dates") or []) if str(x or "").strip()})
    for seg_from, seg_to in _collection_contiguous_date_segments(missing_dates):
        filled = _gfa_mark_no_data_dates(seg_from, seg_to, ad_unit)
        filled_details.append(filled)
        for ymd, n in (filled.get("inserted_by_date") or {}).items():
            inserted_by_date[str(ymd)] = inserted_by_date.get(str(ymd), 0) + int(n or 0)
        for ymd in filled.get("processed_dates") or []:
            processed_dates.append(str(ymd))
    try:
        upload_response["inserted_total"] = int(upload_response.get("inserted_total") or 0) + sum(
            int((one.get("inserted_total") or 0)) for one in filled_details if isinstance(one, dict)
        )
    except Exception:
        pass
    upload_response["inserted_by_date"] = inserted_by_date
    upload_response["processed_dates"] = sorted(set(processed_dates))
    upload_response["no_data_filled_dates"] = [d.isoformat() for d in missing_dates]
    upload_response["no_data_fill_details"] = filled_details
    return upload_response


def _gfa_upload_report_bytes(filename: str, data: bytes, *, source: str = "gfa_report_upload", ad_unit: str = "CREATIVE") -> dict:
    files = _gfa_extract_csv_files(filename, data)
    all_records: list[dict] = []
    file_summaries: list[dict] = []
    for name, body in files:
        records = _gfa_parse_report_csv(body, filename=name, ad_unit=ad_unit)
        all_records.extend(records)
        file_summaries.append({"filename": name, "rows": len(records)})
    inserted_total = upsert_gfa_daily_records(all_records, source=source)
    by_date: dict[str, int] = {}
    for row in all_records:
        ymd = str(row.get("date") or "")
        if ymd:
            by_date[ymd] = by_date.get(ymd, 0) + 1
    return {
        "ok": True,
        "source": source,
        "ad_unit": ad_unit,
        "files": file_summaries,
        "parsed_rows": len(all_records),
        "inserted_total": inserted_total,
        "inserted_by_date": by_date,
        "processed_dates": sorted(by_date.keys()),
    }


def _gfa_report_cdp_url(ad_account_no: str, date_from: date, date_to: date, *, ad_unit: str = "CREATIVE") -> str:
    account = re.sub(r"[^\d]", "", str(ad_account_no or ""))
    if not account:
        raise HTTPException(status_code=400, detail="ad_account_no is required")
    unit = str(ad_unit or "CREATIVE").strip().upper()
    if unit not in {"CREATIVE", "CAMPAIGN", "ASSET_GROUP"}:
        unit = "CREATIVE"
    params = {
        "page": "1",
        "filterOptions": "[]",
        "showColList": "result,sales_per_result,sales,schedule,imp_count,cpm,click_count,cpc,ctr,conv_count,purchase_conv_count,cart_conv_count,conv_sales_krw,purchase_conv_sales_krw,cart_conv_sales_krw,cvr,roas,purchase_roas",
        "dateRange": f"{date_from.isoformat()},{date_to.isoformat()}",
        "adUnit": unit,
        "dateUnit": "DAY",
        "placeUnit": "PLACEMENT_GROUP",
        "audience": "AGE_GENDER",
        "period": "custom",
        "analyticsGfaDateFrom": date_from.isoformat(),
        "analyticsGfaDateTo": date_to.isoformat(),
    }
    return f"https://ads.naver.com/manage/ad-accounts/{account}/da/report/performance?{urllib.parse.urlencode(params)}"


GFA_CAMPAIGN_INVENTORY_MENU_TYPES: dict[str, dict[str, str]] = {
    "website_conversion": {"naver_type": "CONVERSION", "menu_label": "웹사이트 전환"},
}


def _gfa_campaign_inventory_cdp_url(ad_account_no: str, *, campaign_type: str = "website_conversion") -> str:
    account = re.sub(r"[^\d]", "", str(ad_account_no or ""))
    if not account:
        raise HTTPException(status_code=400, detail="ad_account_no is required")
    type_key = str(campaign_type or "website_conversion").strip().lower()
    meta = GFA_CAMPAIGN_INVENTORY_MENU_TYPES.get(type_key)
    if not meta:
        raise HTTPException(status_code=400, detail=f"unsupported campaign_type: {campaign_type}")
    ref_date = _today_kst() - timedelta(days=1)
    params = {
        "dateRange": f"{ref_date.isoformat()},{ref_date.isoformat()}",
        "period": "yesterday",
        "analyticsGfaInventoryType": type_key,
        "analyticsGfaInventoryMenuLabel": meta["menu_label"],
        "analyticsGfaAdAccountNo": account,
    }
    return f"https://ads.naver.com/manage/ad-accounts/{account}/da/campaigns-by/{meta['naver_type']}?{urllib.parse.urlencode(params)}"


