def _gfa_creative_detail_cdp_url(ad_account_no: str, *, campaign_id: str, adgroup_id: str, creative_id: str, creative_name: str = "") -> str:
    account = re.sub(r"[^\d]", "", str(ad_account_no or ""))
    campaign = re.sub(r"[^\d]", "", str(campaign_id or ""))
    adgroup = re.sub(r"[^\d]", "", str(adgroup_id or ""))
    creative = re.sub(r"[^\d]", "", str(creative_id or ""))
    if not account or not campaign or not adgroup or not creative:
        raise HTTPException(status_code=400, detail="gfa creative detail ids are required")
    params = {
        "campaignNo": campaign,
        "adSetNo": adgroup,
        "creativeNo": creative,
        "analyticsGfaAdAccountNo": account,
    }
    name = _collapse_ws_text(creative_name)
    if name:
        params["analyticsGfaCreativeName"] = name
    return f"https://ads.naver.com/manage/ad-accounts/{account}/da/ad/edit/creative?{urllib.parse.urlencode(params)}"


def _gfa_creative_detail_ids_from_url(url: object) -> dict[str, str]:
    out = {"ad_account_no": "", "campaign_id": "", "adgroup_id": "", "creative_id": ""}
    raw = str(url or "").strip()
    if not raw:
        return out
    try:
        parsed = urllib.parse.urlparse(raw)
        match = re.search(r"/ad-accounts/(\d+)", parsed.path or "")
        if match:
            out["ad_account_no"] = match.group(1)
        qs = urllib.parse.parse_qs(parsed.query or "")
        out["ad_account_no"] = re.sub(r"[^\d]", "", str((qs.get("analyticsGfaAdAccountNo") or [out["ad_account_no"]])[0] or ""))
        out["campaign_id"] = re.sub(r"[^\d]", "", str((qs.get("campaignNo") or qs.get("campaignId") or [""])[0] or ""))
        out["adgroup_id"] = re.sub(r"[^\d]", "", str((qs.get("adSetNo") or qs.get("adgroupNo") or qs.get("adGroupId") or [""])[0] or ""))
        out["creative_id"] = re.sub(r"[^\d]", "", str((qs.get("creativeNo") or qs.get("creativeId") or [""])[0] or ""))
    except Exception:
        pass
    return out


GFA_CREATIVE_DETAIL_COMPLETED_EMPTY_EDITOR = "gfa_creative_detail_completed_empty_editor"
GFA_CREATIVE_DETAIL_COMPLETED_REMOTE_ERROR_PAGE = "gfa_creative_detail_completed_remote_error_page"
GFA_CREATIVE_DETAIL_NON_FAILURE_CODES = {
    GFA_CREATIVE_DETAIL_COMPLETED_EMPTY_EDITOR,
    GFA_CREATIVE_DETAIL_COMPLETED_REMOTE_ERROR_PAGE,
}


def _gfa_creative_detail_name_from_url(url: object) -> str:
    raw = str(url or "").strip()
    if not raw:
        return ""
    try:
        parsed = urllib.parse.urlparse(raw)
        qs = urllib.parse.parse_qs(parsed.query or "")
        return _collapse_ws_text((qs.get("analyticsGfaCreativeName") or [""])[0])
    except Exception:
        return ""


def _gfa_creative_detail_is_non_failure_code(code: object) -> bool:
    return str(code or "").strip() in GFA_CREATIVE_DETAIL_NON_FAILURE_CODES


def _gfa_creative_detail_classify_result(*, metrics: dict, error: str | None = None) -> tuple[str | None, bool]:
    err = _collapse_ws_text(error or metrics.get("error")) or None
    via = str(metrics.get("via") or "").strip()
    meaningful_values = [
        _collapse_ws_text(metrics.get("primary_text")),
        _collapse_ws_text(metrics.get("headline")),
        _collapse_ws_text(metrics.get("description")),
        _collapse_ws_text(metrics.get("cta")),
        str(metrics.get("profile_image_url") or "").strip(),
        str(metrics.get("image_url") or "").strip(),
        str(metrics.get("landing_url") or "").strip(),
    ]
    meaningful = any(value and value.lower() not in {"on", "off", "true", "false"} for value in meaningful_values)
    body = _collapse_ws_text(metrics.get("body_sample")) or ""

    if via and via != "naver_gfa_creative_detail_cdp":
        return "unexpected_gfa_creative_detail_payload", True
    if meaningful and not err:
        return None, False

    if body:
        if "예기치 않은 오류가 발생했습니다" in body and "새로고침 후 다시 시도해 주세요" in body:
            return GFA_CREATIVE_DETAIL_COMPLETED_REMOTE_ERROR_PAGE, False
        if (
            "소재 미리보기를 표시할 수 없습니다" in body
            and "표기는 필수 입력 항목입니다" in body
            and "취소 저장" in body
        ):
            return GFA_CREATIVE_DETAIL_COMPLETED_EMPTY_EDITOR, False

    if err and err != "gfa_creative_detail_fields_not_found":
        return err, True
    if not meaningful:
        return "gfa_creative_detail_fields_not_found", True
    return err, bool(err)


def _gfa_creative_detail_targets(
    db: Session,
    *,
    ad_account_no: str,
    force: bool = False,
    limit: int = 200,
) -> list[dict]:
    lim = max(1, min(int(limit or 200), 1000))
    q = (
        db.query(
            NaverGfaDaily.campaign_id,
            NaverGfaDaily.campaign_name,
            NaverGfaDaily.adgroup_id,
            NaverGfaDaily.adgroup_name,
            NaverGfaDaily.creative_id,
            NaverGfaDaily.creative_name,
            func.max(NaverGfaDaily.date).label("last_seen_date"),
        )
        .filter(NaverGfaDaily.source.in_([GFA_CONVERSION_COMPLETE_SOURCE, GFA_CONVERSION_COMPLETE_SOURCE_CREATIVE]))
        .filter(NaverGfaDaily.campaign_id != "__no_data__")
        .filter(func.substr(NaverGfaDaily.creative_id, 1, 2) != "__")
        .filter(func.length(func.trim(NaverGfaDaily.campaign_id)) > 0)
        .filter(func.length(func.trim(NaverGfaDaily.adgroup_id)) > 0)
        .filter(func.length(func.trim(NaverGfaDaily.creative_id)) > 0)
        .group_by(
            NaverGfaDaily.campaign_id,
            NaverGfaDaily.campaign_name,
            NaverGfaDaily.adgroup_id,
            NaverGfaDaily.adgroup_name,
            NaverGfaDaily.creative_id,
            NaverGfaDaily.creative_name,
        )
        .order_by(func.max(NaverGfaDaily.date).desc(), NaverGfaDaily.campaign_name.asc(), NaverGfaDaily.adgroup_name.asc(), NaverGfaDaily.creative_name.asc())
    )
    rows = q.all()
    existing: set[tuple[str, str, str, str]] = set()
    if not force:
        detail_rows = (
            db.query(
                NaverGfaCreativeDetail.ad_account_no,
                NaverGfaCreativeDetail.campaign_id,
                NaverGfaCreativeDetail.adgroup_id,
                NaverGfaCreativeDetail.creative_id,
                NaverGfaCreativeDetail.last_error,
                NaverGfaCreativeDetail.content_hash,
                NaverGfaCreativeDetail.image_url,
                NaverGfaCreativeDetail.primary_text,
                NaverGfaCreativeDetail.headline,
                NaverGfaCreativeDetail.description,
                NaverGfaCreativeDetail.cta,
                NaverGfaCreativeDetail.landing_url,
            )
            .filter(NaverGfaCreativeDetail.ad_account_no == str(ad_account_no or "").strip())
            .all()
        )
        for detail in detail_rows:
            key0 = (str(detail.ad_account_no or ""), str(detail.campaign_id or ""), str(detail.adgroup_id or ""), str(detail.creative_id or ""))
            last_error = _collapse_ws_text(detail.last_error)
            has_success_payload = bool(
                detail.content_hash
                and not last_error
                and any(
                    [
                        str(detail.image_url or "").strip().lower().startswith("http"),
                        _collapse_ws_text(detail.primary_text),
                        _collapse_ws_text(detail.headline),
                        _collapse_ws_text(detail.description),
                        _collapse_ws_text(detail.cta),
                        str(detail.landing_url or "").strip().lower().startswith("http"),
                    ]
                )
            )
            if has_success_payload or last_error or detail.content_hash:
                existing.add(key0)
    targets: list[dict] = []
    account = re.sub(r"[^\d]", "", str(ad_account_no or ""))
    for row in rows:
        campaign_id = re.sub(r"[^\d]", "", str(row.campaign_id or ""))
        adgroup_id = re.sub(r"[^\d]", "", str(row.adgroup_id or ""))
        creative_id = re.sub(r"[^\d]", "", str(row.creative_id or ""))
        if not campaign_id or not adgroup_id or not creative_id:
            continue
        key = (account, campaign_id, adgroup_id, creative_id)
        if key in existing:
            continue
        targets.append(
            {
                "ad_account_no": account,
                "campaign_id": campaign_id,
                "campaign_name": row.campaign_name or "",
                "adgroup_id": adgroup_id,
                "adgroup_name": row.adgroup_name or "",
                "creative_id": creative_id,
                "creative_name": row.creative_name or "",
                "last_seen_date": row.last_seen_date.isoformat() if getattr(row, "last_seen_date", None) else None,
                "url": _gfa_creative_detail_cdp_url(
                    account,
                    campaign_id=campaign_id,
                    adgroup_id=adgroup_id,
                    creative_id=creative_id,
                    creative_name=row.creative_name or "",
                ),
            }
        )
        if len(targets) >= lim:
            break
    return targets


