    if (req.date_to - req.date_from).days + 1 > 31:
        raise HTTPException(status_code=400, detail="date range too large (max 31 days)")
    collector_job = create_page_metrics_collector_job(
        PageMetricsCollectorJobCreate(
            urls=[_gfa_report_cdp_url(req.ad_account_no, req.date_from, req.date_to)],
            mode="gfa_performance_report_cdp",
            target_date=req.date_to.isoformat(),
            date_from=req.date_from.isoformat(),
            date_to=req.date_to.isoformat(),
            created_by_device_id=req.created_by_device_id,
        )
    )
    return {
        "ok": True,
        "collector_job": collector_job,
        "message": "Host Agent background worker will download and upload the Naver GFA performance report.",
    }


