def _gfa_tag_hits(text: str, rules: list[tuple[str, list[str]]]) -> list[str]:
    hay = str(text or "").lower()
    out: list[str] = []
    for label, words in rules:
        if any(str(w).lower() in hay for w in words):
            out.append(label)
    return list(dict.fromkeys(out))


def _gfa_score_to_stars(value: object) -> int:
    try:
        score = float(value or 0.0)
    except Exception:
        score = 0.0
    if score <= 0:
        return 0
    return max(1, min(5, int(round(score * 5))))


def _gfa_top_score_key(scores: object, *, default: str = "unclassified") -> str:
    if not isinstance(scores, dict):
        return default
    positives = []
    for key, value in scores.items():
        try:
            score = float(value or 0.0)
        except Exception:
            score = 0.0
        if score > 0:
            positives.append((str(key), score))
    return max(positives, key=lambda x: x[1])[0] if positives else default


def _gfa_cta_strength_score(cta_text: object, cta_action_type: object = "") -> int:
    text0 = _collapse_ws_text(cta_text)
    action = _collapse_ws_text(cta_action_type)
    source = f"{text0} {action}"
    if any(x in source for x in ["구매", "주문", "buy"]):
        base = 91
    elif any(x in source for x in ["특가", "할인", "이벤트", "혜택", "event"]):
        base = 78
    elif any(x in source for x in ["확인", "보러", "지금", "확인하기"]):
        base = 56
    elif any(x in source for x in ["더보기", "자세히", "알아", "learn"]):
        base = 32
    elif any(x in source for x in ["상담", "문의", "consult"]):
        base = 24
    else:
        base = 12 if text0 else 0
    if any(x in source for x in ["지금", "오늘", "바로"]):
        base += 6
    if len(text0) > 12:
        base -= 8
    return max(0, min(100, int(base)))


def _gfa_success_dna_from_scores(success_factors: object, trust_score: object = 0.0, cta_strength: object = 0) -> dict:
    factors = success_factors if isinstance(success_factors, dict) else {}

    def score(*keys: str, fallback: float = 0.0) -> float:
        vals: list[float] = []
        for key in keys:
            raw = factors.get(key)
            if isinstance(raw, dict):
                raw = raw.get("score")
            try:
                vals.append(float(raw or 0.0))
            except Exception:
                pass
        return round(max(vals) if vals else fallback, 2)

    try:
        trust = float(trust_score or 0.0)
    except Exception:
        trust = 0.0
    try:
        cta = max(0.0, min(1.0, float(cta_strength or 0) / 100.0))
    except Exception:
        cta = 0.0
    raw_scores = {
        "hook": score("problem_hook"),
        "emotion": score("empathy", "family_emotion"),
        "problem": score("problem_hook"),
        "usp": score("natural_usp"),
        "trust": round(max(trust, score("evidence") * 0.8), 2),
        "urgency": round(max(score("urgency"), cta * 0.55), 2),
    }
    return {key: {"score": value, "stars": _gfa_score_to_stars(value)} for key, value in raw_scores.items()}


def _gfa_copy_differentiation(text: object, usp_categories: object = None, evidence_types: object = None) -> dict:
    text0 = _collapse_ws_text(text)
    usps = [str(x) for x in _json_list(usp_categories) if str(x or "").strip() and str(x) not in {"unclassified", "미분류"}]
    evidence = [str(x) for x in _json_list(evidence_types) if str(x or "").strip() and str(x) not in {"none", "미분류"}]
    common = _gfa_tag_hits(
        text0,
        [
            ("새치", ["새치", "흰머리"]),
            ("천연", ["천연", "자연", "식물"]),
            ("헤나", ["헤나"]),
            ("두피", ["두피", "자극", "순한"]),
            ("염색", ["염색", "컬러"]),
        ],
    )
    unique = _gfa_tag_hits(
        text0,
        [
            ("USDA", ["USDA", "인증"]),
            ("비건", ["비건", "vegan"]),
            ("유기농", ["유기농", "organic"]),
            ("인도 전통", ["인도", "전통"]),
            ("가족 케어", ["엄마", "가족", "부모"]),
            ("원료 증거", ["성분", "원료", "식물성"]),
        ],
    )
    if "organic" in usps and "유기농" not in unique:
        unique.append("유기농")
    if "vegan" in usps and "비건" not in unique:
        unique.append("비건")
    if "certification" in evidence and "USDA" not in unique:
        unique.append("인증")
    return {
        "common_claims": list(dict.fromkeys(common))[:6],
        "unique_claims": list(dict.fromkeys(unique))[:6],
        "differentiation_score": max(0, min(100, 35 + len(set(unique)) * 14 - max(0, len(set(common)) - 3) * 4)),
    }


def _gfa_visual_strategy_from_image_payload(payload: object, cv_metrics: object = None) -> dict:
    data = payload if isinstance(payload, dict) else {}
    cv = cv_metrics if isinstance(cv_metrics, dict) else data.get("cv_metrics") if isinstance(data.get("cv_metrics"), dict) else {}
    visual_subjects = " ".join(_json_list(data.get("visual_subjects")))
    scene_tags = " ".join(_json_list(data.get("scene_tags")))
    composition_tags = " ".join(_json_list(data.get("composition_tags")))
    color_tags = _json_list(data.get("color_mood_tags")) + _json_list(data.get("color_detail_tags"))
    product_visibility = _collapse_ws_text(data.get("product_visibility"))

    def f(key: str) -> float:
        try:
            return float(cv.get(key) or 0.0)
        except Exception:
            return 0.0

    face_ratio = f("face_area_ratio")
    text_ratio = f("estimated_text_area_ratio")
    product_visible = "제품" in product_visibility or "제품" in visual_subjects or "패키지" in visual_subjects or "제품" in scene_tags
    face_weight = min(45, int(round(face_ratio * 400))) if face_ratio > 0 else (34 if any(x in visual_subjects for x in ["얼굴", "여성", "모델", "인물"]) else 0)
    product_weight = 18 if product_visible else 0
    text_weight = max(0, min(38, int(round(text_ratio * 260)))) if text_ratio > 0 else (24 if any(x in composition_tags for x in ["텍스트", "리뷰", "사용법"]) else 12)
    negative_weight = max(8, min(35, int(round(f("white_tone_ratio") * 100)))) if cv else 13
    used = face_weight + product_weight + text_weight + negative_weight
    if used > 100:
        scale = 100.0 / used
        face_weight = int(round(face_weight * scale))
        product_weight = int(round(product_weight * scale))
        text_weight = int(round(text_weight * scale))
        negative_weight = int(round(negative_weight * scale))
    background_weight = max(0, 100 - face_weight - product_weight - text_weight - negative_weight)

    path: list[str] = []
    if face_weight >= max(product_weight, text_weight):
        path.append("face")
    elif product_weight > 0:
        path.append("product")
    else:
        path.append("headline")
    if "headline" not in path:
        path.append("headline")
    path.append("benefit")
    if product_weight > 0 and "product" not in path:
        path.append("product")
    path.append("cta")

    color_text = " ".join(str(x) for x in color_tags)
    color_psychology = []
    if any(x in color_text for x in ["초록", "그린", "연두", "green", "자연"]):
        color_psychology.append({"color": "green", "signals": ["safety", "natural", "health"]})
    if any(x in color_text for x in ["노랑", "옐로", "yellow", "밝"]):
        color_psychology.append({"color": "yellow", "signals": ["energy", "friendly", "warmth"]})
    if any(x in color_text for x in ["검정", "블랙", "black", "프리미엄", "고급"]):
        color_psychology.append({"color": "black", "signals": ["premium", "professional", "authority"]})
    if any(x in color_text for x in ["화이트", "흰", "깨끗", "white"]):
        color_psychology.append({"color": "white", "signals": ["clean", "simple", "clarity"]})
    if not color_psychology:
        color_psychology.append({"color": "neutral", "signals": ["clarity"]})

    guide_layout_metrics = {
        "layout_model": "guide_two_zone_copy_column",
        "copy_zone_ratio": {"left": 0.4, "right_visual": 0.6},
        "copy_zone_distribution": {
            "top_hook": {"x": "5-42%", "y": "9-28%"},
            "middle_benefit_proof": {"x": "5-42%", "y": "34-58%"},
            "bottom_cta": {"x": "5-42%", "y": "78-90%"},
        },
        "visual_zone_distribution": {
            "hero_object": {"x": "50-78%", "y": "16-82%"},
            "product_or_ingredient": {"x": "70-92%", "y": "52-86%"},
        },
        "layout_targets": {
            "left_middle_empty_ratio_max": 0.35,
            "object_right_edge_bias_max": 0.78,
            "visual_balance_score_target": 85,
            "guide_layout_match_target": 90,
        },
        "derived_from_guide": [
            "Stop/Relevance/Clarity/Desire/Action",
            "문제/자극 -> 해결/혜택 -> 증거 -> CTA",
            "Hook 좌상단, Message 중앙, CTA 하단",
            "메시지 1개, 혜택 1개, CTA 1개",
        ],
    }
    return {
        "visual_hierarchy_path": path,
        "visual_weight": {
            "face": face_weight,
            "product": product_weight,
            "text": text_weight,
            "negative_space": negative_weight,
            "background": background_weight,
        },
        "color_psychology": color_psychology,
        "cta_destination": "cta" in path,
        "visual_priority": path[0] if path else "headline",
        "guide_layout_metrics": guide_layout_metrics,
    }


def _gfa_creative_dna_from_copy(
    *,
    design_plan: object,
    weighted_feature_layer: object,
    cta_action_type: object,
    visual_strategy: object | None = None,
) -> dict:
    design = design_plan if isinstance(design_plan, dict) else {}
    weights = weighted_feature_layer if isinstance(weighted_feature_layer, dict) else {}
    psychology = weights.get("psychology") if isinstance(weights.get("psychology"), dict) else {}
    benefits = weights.get("benefits") if isinstance(weights.get("benefits"), dict) else {}
    evidence = weights.get("evidence") if isinstance(weights.get("evidence"), dict) else {}
    usp = weights.get("usp") if isinstance(weights.get("usp"), dict) else {}
    visual = visual_strategy if isinstance(visual_strategy, dict) else {}
    color_psych = visual.get("color_psychology") if isinstance(visual.get("color_psychology"), list) else []
    visual_trigger = "green_natural" if any("green" == str((x or {}).get("color")) for x in color_psych if isinstance(x, dict)) else _collapse_ws_text(design.get("image_focus")) or "copy_support"
    return {
        "emotion_driver": _gfa_top_score_key(psychology, default=_collapse_ws_text(design.get("primary_emotion")) or "unclassified"),
        "decision_trigger": _gfa_top_score_key(benefits, default=_collapse_ws_text(design.get("primary_benefit")) or "unclassified"),
        "purchase_trigger": _gfa_top_score_key(usp, default=_collapse_ws_text(design.get("usp")) or "unclassified"),
        "trust_trigger": _gfa_top_score_key(evidence, default=_collapse_ws_text(design.get("evidence")) or "none"),
        "action_trigger": _collapse_ws_text(cta_action_type) or _collapse_ws_text(design.get("cta")) or "none",
        "visual_trigger": visual_trigger,
    }


def _gfa_generation_prompt_vector(
    *,
    design_plan: object,
    creative_dna: object,
    visual_strategy: object | None = None,
    cta_strength: object = 0,
    differentiation: object | None = None,
) -> dict:
    design = design_plan if isinstance(design_plan, dict) else {}
    dna = creative_dna if isinstance(creative_dna, dict) else {}
    visual = visual_strategy if isinstance(visual_strategy, dict) else {}
    diff = differentiation if isinstance(differentiation, dict) else {}
    unique = diff.get("unique_claims") if isinstance(diff.get("unique_claims"), list) else []
    return {
        "audience": _collapse_ws_text(design.get("expected_audience")) or "performance_matched_audience",
        "hook_style": _collapse_ws_text(design.get("primary_hook")) or "problem_hook",
        "primary_emotion": _collapse_ws_text(dna.get("emotion_driver")) or "unclassified",
        "secondary_emotion": _collapse_ws_text(design.get("secondary_emotion")) or "unclassified",
        "primary_benefit": _collapse_ws_text(design.get("primary_benefit")) or "unclassified",
        "primary_usp": _collapse_ws_text(dna.get("purchase_trigger")) or "unclassified",
        "evidence": _collapse_ws_text(dna.get("trust_trigger")) or "none",
        "cta_strength_target": int(cta_strength or 0),
        "visual_direction": " -> ".join(str(x) for x in (visual.get("visual_hierarchy_path") or ["headline", "benefit", "cta"])),
        "visual_trigger": _collapse_ws_text(dna.get("visual_trigger")) or "copy_support",
        "unique_claim_to_emphasize": ", ".join(str(x) for x in unique[:3]) or "none",
        "text_rule": "headline_under_15_chars",
        "message_density": _collapse_ws_text(design.get("copy_density")) or "low",
    }


def _gfa_copy_image_alignment_score(copy_payload: object, image_payload: object, visual_strategy: object | None = None) -> dict:
    cp = copy_payload if isinstance(copy_payload, dict) else {}
    img = image_payload if isinstance(image_payload, dict) else {}
    visual = visual_strategy if isinstance(visual_strategy, dict) else _gfa_visual_strategy_from_image_payload(img)
    copy_terms = " ".join(
        str(x)
        for x in (
            _json_list(cp.get("benefits"))
            + _json_list(cp.get("usp_categories"))
            + _json_list(cp.get("evidence_types"))
            + [_collapse_ws_text(cp.get("image_support_needed")), _collapse_ws_text(cp.get("consumer_benefit"))]
        )
    ).lower()
    image_terms = " ".join(
        str(x)
        for x in (
            _json_list(img.get("visual_subjects"))
            + _json_list(img.get("hair_condition_tags"))
            + _json_list(img.get("scene_tags"))
            + _json_list(img.get("color_mood_tags"))
            + _json_list(img.get("fine_visual_details"))
            + _json_list(img.get("ingredient_visual_cues"))
        )
    ).lower()
    matches = 0
    reasons: list[str] = []
    checks = [
        ("gray_hair", ["gray_hair", "새치", "흰머리"], ["새치", "흰머리", "모발", "헤어"]),
        ("natural", ["natural", "천연", "헤나", "식물", "유기농"], ["천연", "헤나", "초록", "식물", "원료", "자연"]),
        ("family", ["family", "엄마", "가족"], ["중년", "여성", "엄마", "인물", "모델"]),
        ("shine", ["shine", "윤기", "찰랑"], ["윤기", "광채", "찰랑", "정돈"]),
        ("scalp", ["scalp", "두피", "자극", "순한"], ["두피", "도포", "순한", "원료"]),
    ]
    for label, copy_keys, image_keys in checks:
        if any(x in copy_terms for x in copy_keys) and any(x in image_terms for x in image_keys):
            matches += 1
            reasons.append(label)
    score = 55 + matches * 9
    if visual.get("cta_destination"):
        score += 5
    if "화학" in image_terms and any(x in copy_terms for x in ["천연", "순한", "natural"]):
        score -= 20
        reasons.append("chemical_visual_conflict")
    return {
        "score": max(0, min(100, int(score))),
        "matched_signals": reasons,
        "target": 90,
        "risk": "low" if score >= 85 else "medium" if score >= 70 else "high",
    }


def _gfa_creative_score_evaluation(
    *,
    brief: object,
    copy_result: object,
    combination: object,
) -> dict:
    b = brief if isinstance(brief, dict) else {}
    copy0 = copy_result if isinstance(copy_result, dict) else {}
    dna = b.get("creative_dna") if isinstance(b.get("creative_dna"), dict) else {}
    success = b.get("success_dna") if isinstance(b.get("success_dna"), dict) else {}
    alignment = b.get("copy_image_alignment") if isinstance(b.get("copy_image_alignment"), dict) else {}
    prompt_vec = b.get("creative_prompt") if isinstance(b.get("creative_prompt"), dict) else {}
    diff = b.get("differentiation") if isinstance(b.get("differentiation"), dict) else {}
    cta_strength = int(b.get("cta_strength_score") or prompt_vec.get("cta_strength_target") or _gfa_cta_strength_score(copy0.get("cta"), dna.get("action_trigger")))
    headline = _collapse_ws_text(copy0.get("headline"))
    subcopy = _collapse_ws_text(copy0.get("subcopy"))
    proof = _collapse_ws_text(copy0.get("proof_line"))

    def factor(key: str) -> float:
        raw = success.get(key)
        if isinstance(raw, dict):
            raw = raw.get("score")
        try:
            return max(0.0, min(1.0, float(raw or 0.0)))
        except Exception:
            return 0.0

    hook_score = max(factor("hook"), 0.78 if headline and len(headline) <= 18 else 0.45 if headline else 0.0)
    emotion_score = factor("emotion")
    usp_score = max(factor("usp"), min(1.0, float(diff.get("differentiation_score") or 0) / 100.0))
    trust_score = max(factor("trust"), 0.58 if proof and proof != "증거 필요" else 0.2)
    alignment_score = max(0.0, min(1.0, float(alignment.get("score") or 70) / 100.0))
    cta_score = max(0.0, min(1.0, cta_strength / 100.0))
    novelty_score = max(0.0, min(1.0, float(b.get("novelty_score") or 70) / 100.0))
    total = (
        hook_score * 0.20
        + emotion_score * 0.17
        + usp_score * 0.13
        + trust_score * 0.12
        + alignment_score * 0.18
        + cta_score * 0.12
        + novelty_score * 0.08
    )
    strengths = []
    weaknesses = []
    improvements = []
    if hook_score >= 0.8:
        strengths.append("Hook 강함")
    else:
        weaknesses.append("Hook 선명도 부족")
        improvements.append("메인 카피를 12~16자 문제/혜택 직격형으로 재작성")
    if emotion_score >= 0.75:
        strengths.append("심리 자극 우수")
    else:
        weaknesses.append("감정 동인 약함")
        improvements.append("불안/안심/가족 케어 중 1개 감정을 더 선명하게 반영")
    if alignment_score >= 0.85:
        strengths.append("이미지와 카피 일치")
    else:
        weaknesses.append("이미지-카피 정합성 보강 필요")
        improvements.append("이미지 오브젝트를 카피의 Benefit/USP와 직접 연결")
    if usp_score < 0.7:
        weaknesses.append("USP가 경쟁 소재와 유사")
        improvements.append("USDA/비건/인도 전통/원료 증거 중 실제 근거가 있는 차별점 추가")
    if trust_score < 0.55:
        weaknesses.append("신뢰 요소 부족")
        improvements.append("근거 없는 숫자 대신 원료/성분/후기/인증 중 확인 가능한 Evidence 보강")
    if cta_score < 0.75:
        improvements.append("CTA를 '확인' 계열보다 구매/혜택 이유가 있는 행동형으로 강화")
    return {
        "creative_score": round(total * 100, 1),
        "targets": {
            "hook": 90,
            "emotion": 85,
            "usp": 80,
            "alignment": 90,
            "cta": 85,
            "differentiation": 70,
            "predicted_ctr_fit": 88,
        },
        "candidate_scores": {
            "hook": round(hook_score * 100, 1),
            "emotion": round(emotion_score * 100, 1),
            "usp": round(usp_score * 100, 1),
            "alignment": round(alignment_score * 100, 1),
            "cta": round(cta_score * 100, 1),
            "differentiation": round(float(diff.get("differentiation_score") or 0), 1),
            "novelty": round(novelty_score * 100, 1),
            "predicted_ctr_fit": round((hook_score * 0.45 + alignment_score * 0.25 + emotion_score * 0.2 + novelty_score * 0.1) * 100, 1),
        },
        "strengths": strengths[:5],
        "weaknesses": weaknesses[:5],
        "improvement_suggestions": list(dict.fromkeys(improvements))[:5],
    }


def _gfa_analyze_image_rule_based(detail: NaverGfaCreativeDetail | None, meta: NaverGfaCreativeMeta | None) -> dict:
    text = " ".join(
        [
            str(getattr(detail, "creative_name", "") or ""),
            str(getattr(detail, "creative_type", "") or ""),
            str(getattr(detail, "primary_text", "") or ""),
            str(getattr(detail, "headline", "") or ""),
            str(getattr(detail, "description", "") or ""),
            str(getattr(meta, "notes", "") or ""),
        ]
    )
    image_type = str(getattr(meta, "image_type", "") or "")
    text2 = f"{text} {image_type}"
    visual_subjects = _gfa_tag_hits(
        text2,
        [
            ("여성 모델", ["여성", "여자", "모델", "woman"]),
            ("20대 여성", ["20대", "20 대"]),
            ("중년 여성", ["중년", "40대", "50대", "새치"]),
            ("헤어 클로즈업", ["머리", "모발", "헤어", "두피", "염색", "새치"]),
            ("제품 패키지", ["제품", "패키지", "박스", "용기"]),
        ],
    )
    hair_condition_tags = _gfa_tag_hits(
        text2,
        [
            ("손상모", ["손상", "푸석", "갈라짐", "상한"]),
            ("새치 고민", ["새치", "흰머리", "백모"]),
            ("염색모", ["염색", "컬러", "헤나"]),
            ("윤기", ["윤기", "광채", "찰랑"]),
            ("두피 민감", ["두피", "자극", "민감"]),
        ],
    )
    scene_tags = _gfa_tag_hits(
        text2,
        [
            ("헤나 사용 장면", ["헤나", "바른", "도포"]),
            ("비포애프터", ["before", "after", "전후", "비포", "애프터"]),
            ("사용 후 결과", ["결과", "완성", "after", "애프터"]),
            ("제품 중심", ["제품", "패키지", "구성"]),
            ("고민 제시", ["고민", "문제", "걱정"]),
        ],
    )
    emotion_tags = _gfa_tag_hits(
        text2,
        [
            ("환한 미소", ["미소", "웃", "환한"]),
            ("고민", ["고민", "걱정", "스트레스"]),
            ("자신감", ["자신감", "당당", "만족"]),
        ],
    )
    composition_tags = _gfa_tag_hits(
        text2,
        [
            ("클로즈업", ["클로즈업", "close", "확대"]),
            ("전후 비교", ["전후", "비포", "애프터", "before", "after"]),
            ("사용법 설명", ["사용법", "방법", "단계"]),
            ("리뷰형", ["후기", "리뷰", "만족"]),
        ],
    )
    color_mood_tags = _gfa_tag_hits(
        text2,
        [
            ("자연", ["자연", "천연", "내추럴"]),
            ("밝음", ["밝", "화이트", "환한"]),
            ("깨끗함", ["깨끗", "클린"]),
            ("프리미엄", ["프리미엄", "고급"]),
            ("따뜻한 느낌", ["따뜻", "편안"]),
        ],
    )
    product_visibility = "제품 노출" if any(x in text2 for x in ["제품", "패키지", "박스", "용기"]) else "미확인"
    confidence = 0.35 + min(0.45, 0.05 * sum(bool(x) for x in [visual_subjects, hair_condition_tags, scene_tags, emotion_tags, composition_tags, color_mood_tags]))
    payload = {
        "visual_subjects": visual_subjects or ["미분류"],
        "hair_condition_tags": hair_condition_tags or ["미분류"],
        "scene_tags": scene_tags or ["미분류"],
        "emotion_tags": emotion_tags or ["미분류"],
        "composition_tags": composition_tags or ["미분류"],
        "color_mood_tags": color_mood_tags or ["미분류"],
        "product_visibility": product_visibility,
        "confidence": round(confidence, 2),
        "model_name": "rule_based_v1",
    }
    payload["visual_strategy"] = _gfa_visual_strategy_from_image_payload(payload)
    return payload


def _gfa_normalize_image_analysis_payload(raw: object) -> dict:
    data = raw if isinstance(raw, dict) else {}

    def tags(*keys: str) -> list[str]:
        vals: list[str] = []
        for key in keys:
            vals.extend(_json_list(data.get(key)))
        return list(dict.fromkeys([x for x in vals if x and x != "미분류"])) or ["미분류"]

    def optional_tags(*keys: str) -> list[str]:
        vals: list[str] = []
        for key in keys:
            vals.extend(_json_list(data.get(key)))
        return list(dict.fromkeys([x for x in vals if x and x != "미분류"]))

    def merge_tags(*groups: list[str], fallback: str = "미분류", limit: int = 10) -> list[str]:
        vals: list[str] = []
        for group in groups:
            vals.extend([_collapse_ws_text(x) for x in group if _collapse_ws_text(x) and _collapse_ws_text(x) != "미분류"])
        return list(dict.fromkeys(vals))[:limit] or [fallback]

    fine_visual_details = optional_tags("fine_visual_details", "visual_details", "distinctive_visual_cues")
    ingredient_visual_cues = optional_tags("ingredient_visual_cues", "natural_ingredient_cues", "material_cues")
    unusual_visual_hooks = optional_tags("unusual_visual_hooks", "curiosity_hooks", "attention_hooks")
    color_detail_tags = optional_tags("color_detail_tags", "specific_color_tags", "hair_color_tags", "color_details")
    performance_hypotheses = optional_tags("performance_hypotheses", "performance_hypothesis", "why_it_may_work")
    product_visibility = _collapse_ws_text(data.get("product_visibility") or data.get("productVisibility")) or "미확인"
    try:
        confidence = float(data.get("confidence") or data.get("confidence_score") or 0.0)
    except Exception:
        confidence = 0.0
    if confidence <= 0:
        confidence = 0.75
    if confidence > 1:
        confidence = confidence / 100.0 if confidence <= 100 else 1.0
    visual_subjects = tags("visual_subjects", "visual_subject", "model_subjects")
    hair_condition_tags = tags("hair_condition_tags", "hair_condition")
    scene_tags = tags("scene_tags", "scene")
    color_mood_tags = tags("color_mood_tags", "color_mood", "mood_tags", "tone_tags")
    payload = {
        "visual_subjects": merge_tags(fine_visual_details, ingredient_visual_cues, visual_subjects, limit=8),
        "hair_condition_tags": merge_tags(color_detail_tags, hair_condition_tags, limit=8),
        "scene_tags": merge_tags(ingredient_visual_cues, unusual_visual_hooks, scene_tags, limit=8),
        "emotion_tags": tags("emotion_tags", "emotion"),
        "composition_tags": tags("composition_tags", "composition"),
        "color_mood_tags": merge_tags(color_detail_tags, color_mood_tags, limit=8),
        "fine_visual_details": fine_visual_details,
        "ingredient_visual_cues": ingredient_visual_cues,
        "unusual_visual_hooks": unusual_visual_hooks,
        "color_detail_tags": color_detail_tags,
        "performance_hypotheses": performance_hypotheses,
        "product_visibility": product_visibility,
        "confidence": round(max(0.0, min(1.0, confidence)), 2),
        "model_name": _collapse_ws_text(data.get("model_name")) or "openai_vision",
    }
    payload["visual_strategy"] = _gfa_visual_strategy_from_image_payload(payload, data.get("cv_metrics") if isinstance(data.get("cv_metrics"), dict) else None)
    return payload


def _gfa_is_public_image_url(raw: str) -> bool:
    try:
        parsed = urllib.parse.urlparse(str(raw or "").strip())
        if parsed.scheme not in ("http", "https"):
            return False
        host = str(parsed.hostname or "").strip()
        if not host:
            return False
        for info in socket.getaddrinfo(host, None):
            ip = ipaddress.ip_address(info[4][0])
            if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified:
                return False
        return True
    except Exception:
        return False


def _gfa_dominant_hex_colors(cv2_mod, image, *, k: int = 3) -> list[str]:
    try:
        small = cv2_mod.resize(image, (80, 80), interpolation=cv2_mod.INTER_AREA)
        pixels = small.reshape((-1, 3)).astype("float32")
        criteria = (cv2_mod.TERM_CRITERIA_EPS + cv2_mod.TERM_CRITERIA_MAX_ITER, 20, 1.0)
        _, labels, centers = cv2_mod.kmeans(pixels, int(k), None, criteria, 3, cv2_mod.KMEANS_PP_CENTERS)
        counts = Counter(int(x) for x in labels.flatten().tolist())
        ordered = sorted(range(len(centers)), key=lambda idx: counts.get(idx, 0), reverse=True)
        out: list[str] = []
        for idx in ordered:
            b, g, r = [int(max(0, min(255, round(v)))) for v in centers[idx]]
            out.append(f"#{r:02X}{g:02X}{b:02X}")
        return out
    except Exception:
        return []


def _gfa_extract_image_cv_metrics(detail: NaverGfaCreativeDetail | None, meta: NaverGfaCreativeMeta | None) -> dict | None:
    image_url = str(getattr(detail, "image_url", "") or "").strip()
    if not image_url or not _gfa_is_public_image_url(image_url):
        return None
    try:
        import cv2  # type: ignore
        import numpy as np  # type: ignore
    except Exception:
        return None
    try:
        resp = requests.get(
            image_url,
            headers={"User-Agent": "Mozilla/5.0 (ERP2 Analytics Image Analyzer)"},
            timeout=12,
            stream=True,
        )
        if int(resp.status_code) != 200:
            return None
        content_type = str(resp.headers.get("content-type") or "").lower()
        if content_type and not content_type.startswith("image/"):
            return None
        chunks: list[bytes] = []
        total = 0
        max_bytes = 6 * 1024 * 1024
        for chunk in resp.iter_content(chunk_size=65536):
            if not chunk:
                continue
            chunks.append(chunk)
            total += len(chunk)
            if total > max_bytes:
                return None
        arr = np.frombuffer(b"".join(chunks), dtype=np.uint8)
        image = cv2.imdecode(arr, cv2.IMREAD_COLOR)
        if image is None:
            return None
        h, w = image.shape[:2]
        if h <= 0 or w <= 0:
            return None
        hsv = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)
        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        brightness = float(np.mean(hsv[:, :, 2]) / 255.0)
        saturation = float(np.mean(hsv[:, :, 1]) / 255.0)
        contrast = float(min(1.0, np.std(gray) / 128.0))
        sharpness_raw = float(cv2.Laplacian(gray, cv2.CV_64F).var())
        sharpness = float(min(1.0, math.log1p(max(0.0, sharpness_raw)) / 8.0))
        edges = cv2.Canny(gray, 80, 160)
        edge_density = float(np.count_nonzero(edges) / max(1, edges.size))
        white_mask = (hsv[:, :, 1] < 35) & (hsv[:, :, 2] > 190)
        white_ratio = float(np.count_nonzero(white_mask) / max(1, white_mask.size))
        hue = hsv[:, :, 0]
        warm_mask = ((hue < 25) | (hue > 165)) & (hsv[:, :, 1] > 45) & (hsv[:, :, 2] > 80)
        warm_ratio = float(np.count_nonzero(warm_mask) / max(1, warm_mask.size))
        left = image[:, : max(1, w // 2)]
        right = image[:, min(w - 1, w // 2) :]
        left_mean = np.mean(left.reshape((-1, 3)), axis=0)
        right_mean = np.mean(right.reshape((-1, 3)), axis=0)
        side_color_delta = float(np.linalg.norm(left_mean - right_mean) / 441.67)
        center_band = edges[:, max(0, w // 2 - max(2, w // 80)) : min(w, w // 2 + max(2, w // 80))]
        center_edge_density = float(np.count_nonzero(center_band) / max(1, center_band.size))
        split_layout_score = float(max(0.0, min(1.0, (side_color_delta * 0.65) + (center_edge_density * 1.8))))
        text_like = cv2.morphologyEx(edges, cv2.MORPH_CLOSE, np.ones((3, 9), np.uint8))
        contours, _ = cv2.findContours(text_like, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        text_area = 0
        for contour in contours:
            x, y, cw, ch = cv2.boundingRect(contour)
            area = cw * ch
            if 12 <= cw <= w * 0.95 and 6 <= ch <= h * 0.25 and area <= w * h * 0.15:
                text_area += area
        estimated_text_area_ratio = float(min(1.0, text_area / max(1, w * h)))
        face_count = 0
        face_area_ratio = 0.0
        try:
            cascade_path = os.path.join(cv2.data.haarcascades, "haarcascade_frontalface_default.xml")
            classifier = cv2.CascadeClassifier(cascade_path)
            faces = classifier.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(24, 24))
            face_count = int(len(faces))
            face_area_ratio = float(sum(int(fw) * int(fh) for _, _, fw, fh in faces) / max(1, w * h))
        except Exception:
            face_count = 0
            face_area_ratio = 0.0
        return {
            "image_width": int(w),
            "image_height": int(h),
            "aspect_ratio": round(float(w / h), 3),
            "brightness_score": round(brightness, 4),
            "saturation_score": round(saturation, 4),
            "contrast_score": round(contrast, 4),
            "sharpness_score": round(sharpness, 4),
            "edge_density": round(edge_density, 4),
            "white_tone_ratio": round(white_ratio, 4),
            "warm_tone_ratio": round(warm_ratio, 4),
            "split_layout_score": round(split_layout_score, 4),
            "estimated_text_area_ratio": round(estimated_text_area_ratio, 4),
            "face_count": face_count,
            "face_area_ratio": round(face_area_ratio, 4),
            "dominant_colors": _gfa_dominant_hex_colors(cv2, image),
        }
    except Exception:
        return None


def _gfa_banner_extract_uploaded_cv_metrics(data: bytes) -> dict | None:
    try:
        import cv2  # type: ignore
        import numpy as np  # type: ignore
    except Exception:
        return None
    try:
        arr = np.frombuffer(data, dtype=np.uint8)
        image = cv2.imdecode(arr, cv2.IMREAD_COLOR)
        if image is None:
            return None
        h, w = image.shape[:2]
        if h <= 0 or w <= 0:
            return None
        hsv = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)
        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        brightness = float(np.mean(hsv[:, :, 2]) / 255.0)
        saturation = float(np.mean(hsv[:, :, 1]) / 255.0)
        contrast = float(min(1.0, np.std(gray) / 128.0))
        sharpness_raw = float(cv2.Laplacian(gray, cv2.CV_64F).var())
        sharpness = float(min(1.0, math.log1p(max(0.0, sharpness_raw)) / 8.0))
        edges = cv2.Canny(gray, 80, 160)
        edge_density = float(np.count_nonzero(edges) / max(1, edges.size))
        text_like = cv2.morphologyEx(edges, cv2.MORPH_CLOSE, np.ones((3, 9), np.uint8))
        contours, _ = cv2.findContours(text_like, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        text_area = 0
        text_boxes = 0
        text_box_rows: list[dict] = []
        for contour in contours:
            x, y, cw, ch = cv2.boundingRect(contour)
            area = cw * ch
            if 12 <= cw <= w * 0.95 and 6 <= ch <= h * 0.25 and area <= w * h * 0.15:
                text_area += area
                text_boxes += 1
                x_pct = float(x / max(1, w))
                y_pct = float(y / max(1, h))
                w_pct = float(cw / max(1, w))
                h_pct = float(ch / max(1, h))
                if y_pct < 0.33:
                    vertical_zone = "top"
                elif y_pct < 0.66:
                    vertical_zone = "middle"
                else:
                    vertical_zone = "bottom"
                if x_pct + w_pct / 2 < 0.33:
                    horizontal_zone = "left"
                elif x_pct + w_pct / 2 < 0.66:
                    horizontal_zone = "center"
                else:
                    horizontal_zone = "right"
                text_box_rows.append(
                    {
                        "x_pct": round(x_pct, 4),
                        "y_pct": round(y_pct, 4),
                        "w_pct": round(w_pct, 4),
                        "h_pct": round(h_pct, 4),
                        "area_pct": round(float(area / max(1, w * h)), 4),
                        "vertical_zone": vertical_zone,
                        "horizontal_zone": horizontal_zone,
                        "size_bucket": "small" if h_pct < 0.035 else "medium" if h_pct < 0.075 else "large",
                    }
                )
        estimated_text_area_ratio = float(min(1.0, text_area / max(1, w * h)))
        text_box_rows.sort(key=lambda row: row.get("area_pct", 0), reverse=True)
        small_text_box_count = sum(1 for row in text_box_rows if row.get("size_bucket") == "small")
        bottom_text_box_count = sum(1 for row in text_box_rows if row.get("vertical_zone") == "bottom")
        top_text_box_count = sum(1 for row in text_box_rows if row.get("vertical_zone") == "top")
        lower_band = edges[int(h * 0.65) :, :]
        lower_edge_density = float(np.count_nonzero(lower_band) / max(1, lower_band.size))
        center_band = edges[:, int(w * 0.33) : int(w * 0.67)]
        center_edge_density = float(np.count_nonzero(center_band) / max(1, center_band.size))
        border = max(1, min(h, w) // 20)
        border_pixels = np.concatenate(
            [
                image[:border, :, :].reshape(-1, 3),
                image[-border:, :, :].reshape(-1, 3),
                image[:, :border, :].reshape(-1, 3),
                image[:, -border:, :].reshape(-1, 3),
            ],
            axis=0,
        )
        bg_color = np.median(border_pixels, axis=0)
        bg_delta = np.linalg.norm(image.astype(np.float32) - bg_color.astype(np.float32), axis=2)
        _, bg_diff_mask = cv2.threshold(np.clip(bg_delta, 0, 255).astype(np.uint8), 28, 255, cv2.THRESH_BINARY)
        _, saturated_mask = cv2.threshold(hsv[:, :, 1], 45, 255, cv2.THRESH_BINARY)
        edge_mask = cv2.dilate(edges, np.ones((5, 5), np.uint8), iterations=1)
        object_mask = cv2.bitwise_and(cv2.bitwise_or(bg_diff_mask, saturated_mask), edge_mask)
        object_mask = cv2.morphologyEx(object_mask, cv2.MORPH_CLOSE, np.ones((15, 15), np.uint8), iterations=2)
        object_contours, _ = cv2.findContours(object_mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        object_regions: list[dict] = []
        for contour in object_contours:
            x, y, cw, ch = cv2.boundingRect(contour)
            area = cw * ch
            area_pct = float(area / max(1, w * h))
            if area_pct < 0.012 or area_pct > 0.75:
                continue
            if cw < w * 0.04 or ch < h * 0.04:
                continue
            x_pct = float(x / max(1, w))
            y_pct = float(y / max(1, h))
            w_pct = float(cw / max(1, w))
            h_pct = float(ch / max(1, h))
            center_x = x_pct + w_pct / 2
            center_y = y_pct + h_pct / 2
            vertical_zone = "top" if center_y < 0.33 else "middle" if center_y < 0.66 else "bottom"
            horizontal_zone = "left" if center_x < 0.33 else "center" if center_x < 0.66 else "right"
            object_regions.append(
                {
                    "x_pct": round(x_pct, 4),
                    "y_pct": round(y_pct, 4),
                    "w_pct": round(w_pct, 4),
                    "h_pct": round(h_pct, 4),
                    "area_pct": round(area_pct, 4),
                    "vertical_zone": vertical_zone,
                    "horizontal_zone": horizontal_zone,
                }
            )
        object_regions.sort(key=lambda row: row.get("area_pct", 0), reverse=True)
        largest_object_area_ratio = float(object_regions[0]["area_pct"]) if object_regions else 0.0
        largest_object_zone = (
            f"{object_regions[0].get('vertical_zone')}/{object_regions[0].get('horizontal_zone')}"
            if object_regions
            else "unknown"
        )
        return {
            "image_width": int(w),
            "image_height": int(h),
            "aspect_ratio": round(float(w / h), 3),
            "brightness_score": round(brightness, 4),
            "saturation_score": round(saturation, 4),
            "contrast_score": round(contrast, 4),
            "sharpness_score": round(sharpness, 4),
            "edge_density": round(edge_density, 4),
            "lower_edge_density": round(lower_edge_density, 4),
            "center_edge_density": round(center_edge_density, 4),
            "estimated_text_area_ratio": round(estimated_text_area_ratio, 4),
            "estimated_text_box_count": int(text_boxes),
            "estimated_text_boxes": text_box_rows[:30],
            "small_text_box_count": int(small_text_box_count),
            "top_text_box_count": int(top_text_box_count),
            "bottom_text_box_count": int(bottom_text_box_count),
            "estimated_object_regions": object_regions[:12],
            "estimated_object_region_count": int(len(object_regions)),
            "largest_object_area_ratio": round(largest_object_area_ratio, 4),
            "largest_object_zone": largest_object_zone,
            "dominant_colors": _gfa_dominant_hex_colors(cv2, image),
        }
    except Exception:
        return None


def _gfa_landing_product_id(raw_url: object) -> int | None:
    raw = str(raw_url or "").strip()
    if not raw:
        return None
    match = re.search(r"products/([0-9]{5,12})", raw)
    if not match:
        return None
    try:
        return int(match.group(1))
    except Exception:
        return None


def _gfa_clean_context_keyword(raw: object) -> str:
    text0 = _collapse_ws_text(raw)
    if not text0:
        return ""
    low = text0.lower()
    if low in {"undefined", "null", "none", "nan"}:
        return ""
    if text0 in {"(유입상세없음)", "유입상세없음", "(not set)", "-"}:
        return ""
    if re.fullmatch(r"[0-9]{5,}", text0):
        return ""
    return text0


def _gfa_product_intelligence_context(
    db: Session,
    detail: NaverGfaCreativeDetail | None,
    *,
    date_from: date | None = None,
    date_to: date | None = None,
    limit: int = 12,
) -> dict:
    product_id = _gfa_landing_product_id(getattr(detail, "landing_url", None))
    if product_id is None:
        return {"matched": False, "match_rule": "landing_product_id_missing"}
    dt = date_to or _today_kst()
    df = date_from or (dt - timedelta(days=180))

    def _float(v: object) -> float:
        try:
            return float(v or 0)
        except Exception:
            return 0.0

    def _int(v: object) -> int:
        try:
            return int(float(v or 0))
        except Exception:
            return 0

    purchase_rows = db.execute(
        text(
            """
            select keyword, sum(payments)::float as payments, sum(amount)::float as amount
            from naver_smartstore_purchase_keyword_daily
            where product_id = :product_id and date between :df and :dt
            group by keyword
            order by sum(amount) desc nulls last, sum(payments) desc nulls last
            limit 80
            """
        ),
        {"product_id": product_id, "df": df, "dt": dt},
    ).mappings().all()
    purchase_keywords: list[dict] = []
    for row in purchase_rows:
        kw = _gfa_clean_context_keyword(row.get("keyword"))
        if not kw:
            continue
        purchase_keywords.append(
            {
                "keyword": kw,
                "payments": round(_float(row.get("payments")), 2),
                "amount": int(round(_float(row.get("amount")))),
            }
        )
        if len(purchase_keywords) >= limit:
            break

    product_row = db.execute(
        text(
            """
            select product_name, sum(payments)::float as payments, sum(amount)::float as amount, count(*)::int as rows
            from naver_smartstore_purchase_keyword_daily
            where product_id = :product_id and date between :df and :dt
            group by product_name
            order by sum(amount) desc nulls last
            limit 1
            """
        ),
        {"product_id": product_id, "df": df, "dt": dt},
    ).mappings().first()
    product_name = _collapse_ws_text(product_row.get("product_name") if product_row else "") if product_row else ""

    organic_rows = db.execute(
        text(
            """
            select keyword, count(*)::int as rows, avg(nullif(rank, 0))::float as avg_rank, min(nullif(rank, 0))::int as best_rank
            from tracked_product_rank_daily
            where product_url like :pid_like and date between :df and :dt
            group by keyword
            having count(*) >= 7
            order by avg(nullif(rank, 0)) asc nulls last, count(*) desc
            limit :limit
            """
        ),
        {"pid_like": f"%products/{product_id}%", "df": df, "dt": dt, "limit": int(limit)},
    ).mappings().all()
    organic_keywords = [
        {
            "keyword": _gfa_clean_context_keyword(row.get("keyword")),
            "avg_rank": round(_float(row.get("avg_rank")), 2) if row.get("avg_rank") is not None else None,
            "best_rank": _int(row.get("best_rank")) if row.get("best_rank") is not None else None,
        }
        for row in organic_rows
        if _gfa_clean_context_keyword(row.get("keyword"))
    ]

    qna_issue_rows = db.execute(
        text(
            """
            select t.issue_tag, count(*)::int as cnt, max(t.severity) as severity
            from commerce_qna_analysis_issue_tag t
            join commerce_qna_raw q on q.qna_key = t.qna_key
            where q.product_no = :product_no
            group by t.issue_tag
            order by count(*) desc, t.issue_tag asc
            limit :limit
            """
        ),
        {"product_no": str(product_id), "limit": int(limit)},
    ).mappings().all()
    qna_issues = [
        {"issue_tag": _collapse_ws_text(row.get("issue_tag")), "count": _int(row.get("cnt")), "severity": _collapse_ws_text(row.get("severity"))}
        for row in qna_issue_rows
        if _collapse_ws_text(row.get("issue_tag"))
    ]

    review_rows = db.execute(
        text(
            """
            select review_text
            from naver_review_raw
            where product_id_catalog = :product_id and review_text is not null and review_text <> ''
            order by review_written_at desc nulls last
            limit 300
            """
        ),
        {"product_id": product_id},
    ).scalars().all()
    review_text = " ".join(_collapse_ws_text(x) for x in review_rows if _collapse_ws_text(x))
    review_signals = []
    for label, words in [
        ("두피 가려움/자극 없음", ["가렵지", "가려움", "자극", "순하"]),
        ("천연/안심 사용", ["천연", "안심", "헤나"]),
        ("발색/색상 만족", ["발색", "색상", "색으로", "진해", "브라운", "검정"]),
        ("모발 손상/머릿결 관리", ["모발", "머릿결", "손상", "가늘어"]),
        ("사용 시간/번거로움", ["시간", "3시간", "번거롭"]),
    ]:
        cnt = sum(review_text.count(w) for w in words)
        if cnt > 0:
            review_signals.append({"signal": label, "mentions": int(cnt)})

    source_text = " ".join(
        [product_name]
        + [x["keyword"] for x in purchase_keywords[:8]]
        + [x["keyword"] for x in organic_keywords[:8]]
        + [x["signal"] for x in review_signals[:6]]
        + [x["issue_tag"] for x in qna_issues[:6]]
    )
    inferred_product_traits = []
    for label, words in [
        ("헤나 염색약", ["헤나", "henna"]),
        ("천연/유기농/비건 원료 소구", ["천연", "유기농", "비건", "자연"]),
        ("새치/흰머리 커버 니즈", ["새치", "흰머리"]),
        ("두피 자극 회피 니즈", ["두피", "자극", "가려움", "순하"]),
        ("색상/발색 불안 해소 필요", ["색상", "발색", "브라운", "블랙", "COLOR_DIFF"]),
    ]:
        if any(w.lower() in source_text.lower() for w in words):
            inferred_product_traits.append(label)
    creative_hints = []
    if "헤나 염색약" in inferred_product_traits:
        creative_hints.append("헤나 반죽/도포 장면은 일반 염색약과 다른 시각적 차별점이므로 원료감과 호기심 후킹으로 해석한다.")
    if "천연/유기농/비건 원료 소구" in inferred_product_traits:
        creative_hints.append("초록/연두/식물성 질감은 천연 원료 신뢰를 강화하는 색·재료 단서로 우선 해석한다.")
    if "두피 자극 회피 니즈" in inferred_product_traits:
        creative_hints.append("두피에 닿는 도포 장면은 자극 걱정 해소와 순한 사용감의 증거 후보로 본다.")
    if "색상/발색 불안 해소 필요" in inferred_product_traits:
        creative_hints.append("색상 결과와 도포 과정은 발색 불안을 낮추는 비교/설명 소재로 확장한다.")

    return {
        "matched": True,
        "match_rule": "gfa_landing_url_product_id",
        "product_id": product_id,
        "product_name": product_name,
        "date_from": df.isoformat(),
        "date_to": dt.isoformat(),
        "purchase_keywords": purchase_keywords,
        "organic_keywords": organic_keywords,
        "review_signals": review_signals[:8],
        "qna_issues": qna_issues,
        "inferred_product_traits": inferred_product_traits,
        "creative_interpretation_hints": creative_hints,
        "coverage": {
            "purchase_keyword_rows": _int(product_row.get("rows") if product_row else 0),
            "reviews_sampled": len(review_rows),
            "qna_issue_tags": len(qna_issues),
        },
    }


def _gfa_analyze_image_with_openai(
    detail: NaverGfaCreativeDetail | None,
    meta: NaverGfaCreativeMeta | None,
    cv_metrics: dict | None = None,
    product_context: dict | None = None,
) -> dict | None:
    image_url = str(getattr(detail, "image_url", "") or "").strip()
    if not image_url.lower().startswith(("http://", "https://")):
        return None
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        return None
    model_name = str(os.getenv("GFA_CREATIVE_VISION_MODEL") or "gpt-5.5-2026-04-23").strip()
    copy_context = {
        "creative_name": str(getattr(detail, "creative_name", "") or ""),
        "creative_type": str(getattr(detail, "creative_type", "") or ""),
        "primary_text": str(getattr(detail, "primary_text", "") or ""),
        "headline": str(getattr(detail, "headline", "") or ""),
        "description": str(getattr(detail, "description", "") or ""),
        "cta": str(getattr(detail, "cta", "") or ""),
        "manual_image_type": str(getattr(meta, "image_type", "") or ""),
        "manual_notes": str(getattr(meta, "notes", "") or ""),
    }
    cv_context = cv_metrics if isinstance(cv_metrics, dict) else {}
    product_context = product_context if isinstance(product_context, dict) else {}
    system = (
        "너는 GFA 광고 소재 이미지를 분석하는 퍼포먼스 마케팅 크리에이티브 전문가다. "
        "이미지 자체에서 실제로 보이는 장면/인물/표정/구도/분위기를 먼저 태깅하고, "
        "카피 문맥은 보조 근거로만 사용한다. 최종 출력은 JSON 객체만 반환한다. "
        "보이지 않는 요소는 추정하지 말고, 근거가 약하면 '미분류'를 사용한다."
    )
    instruction = (
        "아래 광고 이미지를 광고 크리에이티브 성과 분석용 태그로 분류해라. "
        "반드시 JSON 객체만 반환하고, 키는 visual_subjects, hair_condition_tags, scene_tags, "
        "emotion_tags, composition_tags, color_mood_tags, fine_visual_details, ingredient_visual_cues, "
        "unusual_visual_hooks, color_detail_tags, performance_hypotheses, visual_hierarchy_path, visual_weight, "
        "color_psychology, product_visibility, confidence 로 제한한다. "
        "각 배열은 1~8개 태그로 작성한다.\n"
        "- visual_subjects: 모델/인물/대상. 예: 중년 여성, 40~60대 여성, 얼굴 중심, 상반신, 손 등장, 남성, 뒷모습, 제품 패키지.\n"
        "- hair_condition_tags: 헤어 상태/결과. 예: 새치, 염색모, 손상모, 푸석함, 윤기, 볼륨 부족, 볼륨감, 정돈된 모발, 자연스러운 컬, 머릿결개선.\n"
        "- scene_tags: 제품/사용/결과 장면. 예: BeforeAfter, 결과비교, 동일인물 비교, 염색 완료 상태, 사용 과정, 제품 미노출, 제품 노출.\n"
        "- emotion_tags: 표정/감정. 예: 고민, 무표정, 신경 쓰임, 만족, 자신감, 편안함, 자연스러운 미소, 환한 미소.\n"
        "- composition_tags: 화면 구성. 예: 전후 비교, 좌우 비교, 정면 클로즈업, 얼굴 클로즈업, 동일 배경, 동일 의상, 리뷰형, 사용법 설명.\n"
        "- color_mood_tags: 색감/분위기. 예: 자연, 화이트톤, 깨끗함, 밝음, 프리미엄, 따뜻한 느낌, 생활감, 전문가 느낌.\n"
        "- fine_visual_details: 이미지에서 실제 보이는 디테일. 예: 헤나 반죽 도포, 연두색 모발, 젖은 모발, 두피에 바른 질감, 식물성 가루 질감.\n"
        "- ingredient_visual_cues: 천연/원료/성분을 암시하는 시각 단서. 예: 헤나 반죽, 초록빛 원료감, 가루/팩 제형, 식물성 질감.\n"
        "- unusual_visual_hooks: 일반 염색약 광고와 달라 호기심을 만드는 장치. 예: 초록 반죽 머리, 도포 과정 클로즈업, 낯선 원료 질감.\n"
        "- color_detail_tags: 구체 색상. 예: 연두색, 그린톤, 짙은 브라운, 블랙, 적갈색, 흑백톤.\n"
        "- performance_hypotheses: 상품/구매/리뷰/Q&A 컨텍스트와 이미지를 결합한 성과 가설. 예: 천연 원료감을 직접 보여줘 헤나/천연염색약 구매 키워드와 일치.\n"
        "- visual_hierarchy_path: 시선 이동 순서. 예: [\"face\",\"headline\",\"benefit\",\"cta\"], [\"product\",\"headline\",\"cta\"].\n"
        "- visual_weight: 얼굴/제품/텍스트/여백/배경 비중을 합산 100에 가깝게 작성. 예: {\"face\":42,\"product\":18,\"text\":27,\"negative_space\":13,\"background\":0}.\n"
        "- color_psychology: 주요 색과 광고 심리. 예: [{\"color\":\"green\",\"signals\":[\"safety\",\"natural\",\"health\"]}].\n"
        "- product_visibility: '제품 노출', '제품 미노출', '부분 노출', '미확인' 중 하나에 가깝게 작성한다.\n"
        "소재 성과에서 카피의 설득 구조를 80%, 오브젝트/배경 이미지를 20% 보조 요소로 본다. "
        "이미지는 카피의 문제의식, 감정, 구매 이유를 설명하고 증명해야 하며 카피와 의미가 충돌하면 큰 실패 요소로 기록한다. "
        "예: 카피가 '엄마 새치 걱정'인데 이미지가 일반 화학 염색약처럼 보이면, 엄마 건강/순한 관리 걱정과 충돌하므로 부정 가설로 적는다. "
        "성과 분석에 쓰기 쉽도록 태그는 짧은 명사형 한국어로 정규화하고, 같은 의미는 중복하지 않는다. "
        "상품 컨텍스트에는 구매 키워드, 검색 순위, 리뷰, Q&A 이슈가 포함된다. "
        "이미지에 보이는 요소가 상품 컨텍스트와 맞물려 의미가 생기면 performance_hypotheses에 반드시 적는다. "
        "예를 들어 상품 컨텍스트가 헤나/천연염색약이고 이미지에 초록 반죽이 머리에 발려 있으면, 이를 '헤나 반죽 도포', '천연 원료 시각 증거', '호기심 후킹'으로 해석한다. "
        "OpenCV 수치 지표는 이미지의 밝기/색감/구도/얼굴비중을 객관적으로 계산한 참고값이다. "
        "수치 지표와 실제 이미지가 충돌하면 실제 이미지를 우선하되, 색감/구도 판단에는 수치를 보조 근거로 사용한다. "
        "예시 출력: {\"visual_subjects\":[\"중년 여성\",\"얼굴 중심\",\"상반신\"],"
        "\"hair_condition_tags\":[\"새치\",\"푸석함\",\"윤기\",\"염색모\"],"
        "\"scene_tags\":[\"BeforeAfter\",\"결과비교\",\"동일인물 비교\"],"
        "\"emotion_tags\":[\"고민\",\"만족\",\"자신감\"],"
        "\"composition_tags\":[\"좌우 비교\",\"정면 클로즈업\"],"
        "\"color_mood_tags\":[\"자연\",\"화이트톤\",\"깨끗함\",\"프리미엄\"],"
        "\"fine_visual_details\":[\"헤나 반죽 도포\",\"연두색 모발\"],"
        "\"ingredient_visual_cues\":[\"초록빛 원료감\",\"식물성 질감\"],"
        "\"unusual_visual_hooks\":[\"일반 염색약과 다른 도포 비주얼\"],"
        "\"color_detail_tags\":[\"연두색\",\"그린톤\"],"
        "\"performance_hypotheses\":[\"헤나/천연염색약 구매 키워드와 초록 반죽 도포 이미지가 일치해 원료 신뢰와 호기심을 만든다\"],"
        "\"visual_hierarchy_path\":[\"hair\",\"headline\",\"benefit\",\"cta\"],"
        "\"visual_weight\":{\"face\":0,\"product\":0,\"text\":28,\"negative_space\":20,\"background\":52},"
        "\"color_psychology\":[{\"color\":\"green\",\"signals\":[\"safety\",\"natural\",\"health\"]}],"
        "\"product_visibility\":\"제품 미노출\",\"confidence\":0.88}. "
        f"카피 문맥 참고: {json.dumps(copy_context, ensure_ascii=False)}\n"
        f"상품/구매/소비자 반응 컨텍스트 참고: {json.dumps(product_context, ensure_ascii=False, default=str)}\n"
        f"OpenCV 수치 지표 참고: {json.dumps(cv_context, ensure_ascii=False)}"
    )
    payload = _build_openai_chat_payload(
        model_name=model_name,
        messages=[
            {"role": "system", "content": system},
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": instruction},
                    {"type": "image_url", "image_url": {"url": image_url, "detail": "high"}},
                ],
            },
        ],
        temperature=0.1,
        max_output_tokens=1100,
    )
    try:
        resp = _post_openai_chat_completion_compatible(api_key=key, payload=payload, timeout=45)
        if int(resp.status_code) != 200:
            try:
                body0 = resp.json() or {}
            except Exception:
                body0 = {}
            err0 = body0.get("error") if isinstance(body0, dict) else {}
            if not isinstance(err0, dict):
                err0 = {}
            code0 = str(err0.get("code") or err0.get("type") or f"http_{resp.status_code}").strip()
            msg0 = _collapse_ws_text(err0.get("message")) or _collapse_ws_text(getattr(resp, "text", "")) or "OpenAI vision request failed"
            raise RuntimeError(f"openai_vision_error:{code0}:{msg0[:500]}")
        body = resp.json() or {}
        choices = body.get("choices") or []
        msg = (choices[0] or {}).get("message") if isinstance(choices, list) and choices else {}
        content = _strip_json_fence(str((msg or {}).get("content") or "").strip())
        parsed = json.loads(content)
        if not isinstance(parsed, dict):
            raise RuntimeError("openai_vision_error:invalid_json:OpenAI response was not a JSON object")
        out = _gfa_normalize_image_analysis_payload(parsed)
        out["model_name"] = str(body.get("model") or model_name or "openai_vision")
        return out
    except RuntimeError:
        raise
    except Exception as exc:
        raise RuntimeError(f"openai_vision_error:request_failed:{str(exc)[:500]}")


def _gfa_analyze_copy_rule_based(detail: NaverGfaCreativeDetail | None) -> dict:
    primary_text = _collapse_ws_text(getattr(detail, "primary_text", "") if detail else "")
    headline0 = _collapse_ws_text(getattr(detail, "headline", "") if detail else "")
    description0 = _collapse_ws_text(getattr(detail, "description", "") if detail else "")
    cta0 = _collapse_ws_text(getattr(detail, "cta", "") if detail else "")
    text = " ".join(
        [
            primary_text,
            headline0,
            description0,
            cta0,
        ]
    )
    core_keywords = _gfa_tag_hits(
        text,
        [
            ("헤나", ["헤나"]),
            ("새치", ["새치", "흰머리"]),
            ("손상모", ["손상", "푸석", "상한"]),
            ("염색", ["염색", "컬러"]),
            ("윤기", ["윤기", "찰랑", "광채"]),
            ("자극", ["자극", "순한", "두피"]),
            ("천연/성분", ["천연", "성분", "식물", "자연"]),
        ],
    )
    pain_points = _gfa_tag_hits(
        text,
        [
            ("새치 고민", ["새치", "흰머리"]),
            ("손상모 고민", ["손상", "푸석", "상한"]),
            ("두피 자극 고민", ["두피", "자극", "민감"]),
            ("염색 지속 고민", ["지속", "유지", "금방"]),
        ],
    )
    appeal_types = _gfa_tag_hits(
        text,
        [
            ("공감형", ["고민", "걱정", "혹시", "나만"]),
            ("문제 제시형", ["문제", "손상", "새치", "자극"]),
            ("혜택 제시형", ["혜택", "할인", "무료", "증정", "특가"]),
            ("결과 강조형", ["완성", "결과", "변화", "윤기", "커버"]),
            ("신뢰형", ["인증", "성분", "전문", "후기", "리뷰"]),
            ("행동 유도형", ["지금", "확인", "구매", "보기", "받기"]),
        ],
    )
    if any(x in text for x in ["?", "혹시", "고민"]):
        message_tone = "고민 공감형"
    elif any(x in text for x in ["특가", "할인", "증정", "무료"]):
        message_tone = "혜택 강조형"
    elif any(x in text for x in ["인증", "성분", "전문", "후기"]):
        message_tone = "신뢰 설득형"
    else:
        message_tone = "정보 전달형"
    cta = str(getattr(detail, "cta", "") or "")
