@app.get("/gfa/creatives/analysis/readiness", response_model=dict)
def get_gfa_creative_analysis_readiness(db: Session = Depends(get_db)):
    analyzed_ids = select(NaverGfaCreativeImageAnalysis.creative_id)
    detail_q = db.query(NaverGfaCreativeDetail.creative_id).filter(NaverGfaCreativeDetail.creative_id != "")
    image_q = detail_q.filter(
        NaverGfaCreativeDetail.image_url != "",
        NaverGfaCreativeDetail.image_url.isnot(None),
        or_(
            NaverGfaCreativeDetail.image_url.like("http://%"),
            NaverGfaCreativeDetail.image_url.like("https://%"),
        ),
    )
    missing_image_q = image_q.filter(~NaverGfaCreativeDetail.creative_id.in_(analyzed_ids))
    openai_configured = bool(_get_api_setting("OPENAI_API_KEY"))
    blockers: list[str] = []
    if not openai_configured:
        blockers.append("openai_api_key_missing")
    if image_q.distinct().count() <= 0:
        blockers.append("gfa_creative_image_url_missing")
    return {
        "ok": True,
        "openai_configured": openai_configured,
        "vision_model": str(os.getenv("GFA_CREATIVE_VISION_MODEL") or "gpt-5.5-2026-04-23"),
        "total_detail_creatives": detail_q.distinct().count(),
        "image_url_creatives": image_q.distinct().count(),
        "missing_image_analysis": missing_image_q.distinct().count(),
        "blockers": blockers,
    }


