@app.post("/gfa/creatives/analysis/run", response_model=dict)
def run_gfa_creative_analysis_batch(payload: GfaCreativeAnalyzePayload, db: Session = Depends(get_db)):
    ids = [str(x or "").strip() for x in (payload.creative_ids or []) if str(x or "").strip()]
    if not ids:
        limit = int(payload.limit or 100)
        q = db.query(NaverGfaCreativeDetail.creative_id).filter(
            NaverGfaCreativeDetail.creative_id != "",
            NaverGfaCreativeDetail.image_url != "",
            NaverGfaCreativeDetail.image_url.isnot(None),
            or_(
                NaverGfaCreativeDetail.image_url.like("http://%"),
                NaverGfaCreativeDetail.image_url.like("https://%"),
            ),
        )
        if not payload.force:
            analyzed_ids = select(NaverGfaCreativeImageAnalysis.creative_id).filter(
                ~NaverGfaCreativeImageAnalysis.status.in_(["", "missing", "failed"])
            )
            fresh_copy_ids = select(NaverGfaCreativeCopyAnalysis.creative_id).filter(
                NaverGfaCreativeCopyAnalysis.model_name == "rule_based_v2",
                NaverGfaCreativeCopyAnalysis.analysis_json.like('%"weighted_feature_layer"%'),
                NaverGfaCreativeCopyAnalysis.analysis_json.like('%"design_plan"%'),
                NaverGfaCreativeCopyAnalysis.analysis_json.like('%"feature_importance"%'),
                NaverGfaCreativeCopyAnalysis.analysis_json.like('%"creative_dna"%'),
                NaverGfaCreativeCopyAnalysis.analysis_json.like('%"success_dna"%'),
                NaverGfaCreativeCopyAnalysis.analysis_json.like('%"creative_prompt"%'),
            )
            q = q.filter(
                or_(
                    ~NaverGfaCreativeDetail.creative_id.in_(analyzed_ids),
                    ~NaverGfaCreativeDetail.creative_id.in_(fresh_copy_ids),
                )
            )
        seen_ids: set[str] = set()
        for row in q.order_by(NaverGfaCreativeDetail.updated_at.desc()).all():
            cid = str(row[0] or "").strip()
            if not cid or cid in seen_ids:
                continue
            seen_ids.add(cid)
            ids.append(cid)
            if len(ids) >= limit:
                break
    results = []
    for cid in ids:
        try:
            results.append(_upsert_gfa_creative_analysis(db, cid, force=bool(payload.force), allow_fallback=bool(payload.allow_fallback)))
        except Exception as e:
            results.append({"creative_id": cid, "error": str(e)})
    return {"ok": True, "count": len(results), "results": results}


