    def _metric_value(row: dict, goal: str) -> float:
        metric = str(goal_specs.get(goal, {}).get("metric") or "ctr")
        return float(row.get(metric) or 0.0)

    def _grade_for_rank(rank: int, row: dict, goal: str) -> str:
        if int(row.get("cost") or 0) <= 0 or int(row.get("clicks") or 0) <= 0:
            return "D"
        value = _metric_value(row, goal)
        sample = _sample_status(row, goal)
        if not sample["sample_sufficient"] and value > 0:
            return "B"
        if rank <= 1 and value > 0:
            return "S"
        if rank <= 3 and value > 0:
            return "A"
        if rank <= 5 and value > 0:
            return "B"
        if value > 0:
            return "C"
        return "D"

    def _parse_audience_parts(label: str | None) -> dict:
        raw = _collapse_ws_text(label) or "전체"
        gender = "전체"
        age = "전체"
        has_female = bool(re.search(r"(여성|여자|female|woman|F\b)", raw, flags=re.I))
        has_male = bool(re.search(r"(남성|남자|male|man|M\b)", raw, flags=re.I))
        if "전체" in raw or (has_female and has_male):
            gender = "전체"
        elif has_female:
            gender = "여성"
        elif has_male:
            gender = "남성"
        age_match = re.search(r"(\d{2})\s*세?\s*(?:~|-)\s*(\d{2})\s*세?", raw)
        if age_match:
            age = f"{age_match.group(1)}-{age_match.group(2)}세"
        else:
            decade_match = re.search(r"(\d{2})\s*대", raw)
            if decade_match:
                age = f"{decade_match.group(1)}대"
        return {"audience": raw, "gender": gender, "age": age}

    def _analysis_tags(row: dict, key: str, limit: int = 3) -> str:
        val = row.get(key)
        vals = val if isinstance(val, list) else [val]
        clean = [_collapse_ws_text(x) for x in vals if _collapse_ws_text(x) and _collapse_ws_text(x) != "미분류"]
        return ", ".join(clean[:limit]) if clean else "분석 필요"

    def _product_context_summary(row: dict, *, limit: int = 3) -> str:
        ctx = row.get("product_context") if isinstance(row.get("product_context"), dict) else {}
        if not ctx or not ctx.get("matched"):
            return ""

        def _kw(items: object, key: str = "keyword", n: int = limit) -> str:
            vals = []
            for item in items if isinstance(items, list) else []:
                if isinstance(item, dict):
                    text0 = _collapse_ws_text(item.get(key))
                else:
                    text0 = _collapse_ws_text(item)
                if text0:
                    vals.append(text0)
            return ", ".join(list(dict.fromkeys(vals))[:n])

        traits = ", ".join([_collapse_ws_text(x) for x in (ctx.get("inferred_product_traits") or []) if _collapse_ws_text(x)][:limit])
        purchase = _kw(ctx.get("purchase_keywords"), n=limit)
        organic = _kw(ctx.get("organic_keywords"), n=limit)
        qna = _kw(ctx.get("qna_issues"), key="issue_tag", n=limit)
        hints = " / ".join([_collapse_ws_text(x) for x in (ctx.get("creative_interpretation_hints") or []) if _collapse_ws_text(x)][:2])
        parts = []
        if traits:
            parts.append(f"상품특성: {traits}")
        if purchase:
            parts.append(f"구매키워드: {purchase}")
        if organic:
            parts.append(f"검색우위: {organic}")
        if qna:
            parts.append(f"구매장벽: {qna}")
        if hints:
            parts.append(f"해석: {hints}")
        return "\n".join(parts)

