    def _baseline_row(level: str, items: list[dict], goal: str) -> dict:
        candidates = [x for x in _top_rows(items, goal, limit=1) if int(x.get("cost") or 0) > 0]
        best = candidates[0] if candidates else {}
        return {
            "level": level,
            "goal": goal,
            "goal_label": goal_specs[goal]["label"],
            "name": best.get("name") or best.get("campaign_name") or best.get("adgroup_name") or best.get("creative_name") or "데이터 부족",
            "metric_label": goal_specs[goal]["metric_label"],
            "metric_value": _metric_value(best, goal) if best else 0.0,
            "cost": int(best.get("cost") or 0) if best else 0,
            "ctr": float(best.get("ctr") or 0.0) if best else 0.0,
            "total_cvr": float(best.get("total_cvr") or best.get("cvr") or 0.0) if best else 0.0,
            "purchase_cvr": float(best.get("purchase_cvr") or 0.0) if best else 0.0,
            "purchase_roas": float(best.get("purchase_roas") or 0.0) if best else 0.0,
        }

    high_performance_baselines = {
        "campaigns": [_baseline_row("campaign", campaign_rows, goal) for goal in ("click", "conversion", "purchase")],
        "adgroups": [_baseline_row("adgroup", adgroup_rows, goal) for goal in ("click", "conversion", "purchase")],
        "creatives": [_baseline_row("creative", material_creative_rows, goal) for goal in ("click", "conversion", "purchase")],
    }

    def _condition_gap_rows(source_rows: list[tuple[str, dict]], *, limit: int = 80) -> list[dict]:
        out: list[dict] = []
        for level, row in sorted(source_rows, key=lambda z: int(z[1].get("cost") or 0), reverse=True)[:limit]:
            best_goal = _best_goal_for_item(row)
            sample = _sample_status(row, best_goal)
            baseline = next((x for x in high_performance_baselines.get(f"{level}s", []) if x.get("goal") == best_goal), {})
            metric = goal_specs[best_goal]["metric"]
            current_value = _metric_value(row, best_goal)
            baseline_value = float(baseline.get("metric_value") or 0.0)
            gap = current_value - baseline_value
            issues: list[str] = []
            if not sample["sample_sufficient"]:
                issues.append("표본 부족")
            if int(row.get("cost") or 0) > 0 and int(row.get("clicks") or 0) <= 0:
                issues.append("클릭 미발생")
            if float(row.get("ctr") or 0.0) < max(0.1, float(baseline.get("ctr") or 0.0) * 0.6):
                issues.append("CTR 기준선 미달")
            if float(row.get("total_cvr") or row.get("cvr") or 0.0) < max(0.1, float(baseline.get("total_cvr") or 0.0) * 0.6):
                issues.append("총전환CVR 기준선 미달")
            if float(row.get("purchase_cvr") or 0.0) < max(0.1, float(baseline.get("purchase_cvr") or 0.0) * 0.6):
                issues.append("구매CVR 기준선 미달")
            if int(row.get("cost") or 0) >= 50000 and int(row.get("purchase_conversions") or 0) <= 0:
                issues.append("비용 대비 구매 없음")
            grade = "S" if gap >= 0 and current_value > 0 else "A" if current_value >= baseline_value * 0.8 and current_value > 0 else "B" if current_value > 0 else "D"
            if not sample["sample_sufficient"] and grade in {"S", "A"}:
                grade = "B"
            if "비용 대비 구매 없음" in issues:
                grade = "D"
            purpose_fit = _purpose_fit(row, best_goal)
            action = "우수 기준선과 유사하므로 예산 유지 또는 확장 후보입니다."
            if issues:
                action = f"{', '.join(issues[:2])} 문제를 우선 개선하고, 우수 기준선({baseline.get('name') or '상위 성과'})의 타겟/지면/소재 조건으로 재조정합니다."
            if purpose_fit.get("purpose_fit") == "점검 필요":
                action = f"{purpose_fit.get('purpose_fit_reason')} {action}"
            display_name = (
                row.get("campaign_name")
                if level == "campaign"
                else row.get("adgroup_name")
                if level == "adgroup"
                else row.get("creative_name")
                if level == "creative"
                else None
            )
            out.append(
                {
                    **row,
                    "level": level,
                    "level_label": "캠페인" if level == "campaign" else "광고그룹" if level == "adgroup" else "소재",
                    "name": display_name or row.get("name") or "미상",
                    "best_goal": best_goal,
                    "best_goal_label": goal_specs[best_goal]["label"],
                    "baseline_name": baseline.get("name") or "데이터 부족",
                    "baseline_metric_label": goal_specs[best_goal]["metric_label"],
                    "baseline_metric_value": round(baseline_value, 4),
                    "current_metric_value": round(current_value, 4),
                    "metric_gap": round(gap, 4),
                    "gap_summary": f"{goal_specs[best_goal]['metric_label']} 현재 {current_value:.2f}% / 우수 기준 {baseline_value:.2f}%",
                    "problem_cause": ", ".join(issues) if issues else "우수 기준선과 유사",
                    "grade": grade,
                    "recommendation": action,
                    "metric_key": metric,
                    **sample,
                    **purpose_fit,
                }
            )
        return out

    campaign_condition_rows = _condition_gap_rows([("campaign", x) for x in campaign_rows], limit=500)
    adgroup_condition_rows = _condition_gap_rows([("adgroup", x) for x in adgroup_rows], limit=1000)
    creative_condition_rows = _condition_gap_rows([("creative", x) for x in material_creative_rows], limit=2000)
    condition_gap_rows = (campaign_condition_rows + adgroup_condition_rows + creative_condition_rows)[:80]
    condition_hierarchy = {
        "campaigns": campaign_condition_rows,
        "adgroups": adgroup_condition_rows,
        "creatives": creative_condition_rows,
    }

    def _operation_rows() -> list[dict]:
        out: list[dict] = []
        axes = [
            ("audience", "성별/연령", audience_rows),
            ("media", "매체", media_rows),
            ("placement", "게재위치", placement_rows),
            ("audience_media_placement", "성별/연령 x 매체 x 게재위치", audience_media_placement_rows),
        ]
        for axis_key, axis_label, items in axes:
            for goal in ("click", "conversion", "purchase"):
                for idx, row in enumerate(_top_rows(items, goal, limit=5), start=1):
                    audience_info = _parse_audience_parts(row.get("audience") or row.get("name"))
                    media = row.get("media") or ("전체" if axis_key != "media" else row.get("name"))
                    placement = row.get("placement") or ("전체" if axis_key != "placement" else row.get("name"))
                    grade = _grade_for_rank(idx, row, goal)
                    out.append(
                        {
                            **row,
                            "rank": idx,
                            "axis": axis_key,
                            "axis_label": axis_label,
                            "goal": goal,
                            "goal_label": goal_specs[goal]["label"],
                            "metric_label": goal_specs[goal]["metric_label"],
                            "metric_value": round(_metric_value(row, goal), 4),
                            "gender": audience_info["gender"],
                            "age": audience_info["age"],
                            "audience": audience_info["audience"],
                            "media": media or "전체",
                            "placement": placement or "전체",
                            "grade": grade,
                            "judgment": f"{axis_label} {idx}위 조건입니다.",
                            "operation_suggestion": f"{goal_specs[goal]['label']} 목적에서 {audience_info['audience']} / {media or '전체'} / {placement or '전체'} 조건을 우선 테스트 또는 확장합니다.",
                        }
                    )
        return out

    operation_compare_rows = _operation_rows()

    top_rank_maps = {
        "click": {str(x.get("creative_id") or x.get("name")): idx for idx, x in enumerate(creative_factor_analysis["top_ctr"], start=1)},
        "conversion": {str(x.get("creative_id") or x.get("name")): idx for idx, x in enumerate(creative_factor_analysis["top_total_cvr"], start=1)},
        "purchase": {str(x.get("creative_id") or x.get("name")): idx for idx, x in enumerate(creative_factor_analysis["top_purchase_cvr"], start=1)},
    }

    def _creative_purpose(row: dict) -> str:
        data_goal = _best_goal_for_item(row)
        if _sample_status(row, data_goal)["sample_sufficient"]:
            return data_goal
        cid = str(row.get("creative_id") or row.get("name"))
        ranks = {goal: top_rank_maps[goal].get(cid, 999) for goal in ("click", "conversion", "purchase")}
        goal = min(ranks, key=lambda g: ranks[g])
        if ranks[goal] == 999:
            goal = data_goal
        return goal

    def _creative_direction(row: dict, goal: str) -> str:
        def _ready_bits(values: list[str]) -> list[str]:
            return [x for x in values if x not in {"미분류", "분석 필요"}]

        image_bits = [
            _analysis_tags(row, "visual_subjects", 2),
            _analysis_tags(row, "scene_tags", 2),
            _analysis_tags(row, "hair_condition_tags", 2),
            _analysis_tags(row, "color_mood_tags", 2),
        ]
        copy_bits = [
            _analysis_tags(row, "core_keywords", 2),
            _analysis_tags(row, "copy_appeal_types", 2),
            _collapse_ws_text(row.get("message_tone")) or "미분류",
        ]
        product_context = _product_context_summary(row, limit=2)
        product_sentence = f" 상품/구매/소비자 반응 근거({product_context.replace(chr(10), ' / ')})를 함께 반영합니다." if product_context else ""
        return (
            f"{goal_specs[goal]['label']} 목적은 이미지({', '.join(_ready_bits(image_bits)[:3]) or '분석 필요'})와 "
            f"카피({', '.join(_ready_bits(copy_bits)[:3]) or '분석 필요'}) 조합을 우선 제작/테스트합니다."
            f"{product_sentence}"
        )

    def _creative_rows() -> list[dict]:
        out: list[dict] = []
        candidates: dict[str, dict] = {}
        for row in material_creative_rows:
            key = str(row.get("creative_id") or row.get("name") or "")
            if key and not key.startswith("__"):
                candidates[key] = row
        picked_keys = set()
        ordered: list[dict] = []
        for goal, rows_for_goal in (
            ("click", creative_factor_analysis["top_ctr"]),
            ("conversion", creative_factor_analysis["top_total_cvr"]),
            ("purchase", creative_factor_analysis["top_purchase_cvr"]),
        ):
            for row in rows_for_goal:
                key = str(row.get("creative_id") or row.get("name") or "")
                if key and not key.startswith("__") and key not in picked_keys:
                    ordered.append(candidates.get(key) or row)
                    picked_keys.add(key)
        for row in ordered[:30]:
            cid = str(row.get("creative_id") or row.get("name"))
            goal = _creative_purpose(row)
            rank = top_rank_maps[goal].get(cid, 999)
            grade = _grade_for_rank(rank if rank != 999 else 10, row, goal)
            image_summary = " / ".join(
                [
                    _analysis_tags(row, "visual_subjects", 2),
                    _analysis_tags(row, "scene_tags", 2),
                    _analysis_tags(row, "composition_tags", 2),
                    _analysis_tags(row, "color_mood_tags", 2),
                ]
            )
            product_context_summary = _product_context_summary(row, limit=3)
            if product_context_summary:
                image_summary = f"{image_summary}\n{product_context_summary}"
            copy_summary = _copy_detail_summary(row)
            opencv_summary = " / ".join(
                [
                    _collapse_ws_text(row.get("cv_brightness_level")) or "분석 필요",
                    _collapse_ws_text(row.get("cv_text_area_level")) or "분석 필요",
                    _collapse_ws_text(row.get("cv_face_area_level")) or "분석 필요",
                    _collapse_ws_text(row.get("cv_split_layout_level")) or "분석 필요",
                ]
            )
            image_ready = str(row.get("image_analysis_status") or "") not in {"", "missing", "failed"}
            copy_ready = str(row.get("copy_analysis_status") or "") not in {"", "missing", "failed"}
            purpose_fit = _purpose_fit(row, goal)
            out.append(
                {
                    **row,
                    "recommended_goal": goal,
                    "recommended_goal_label": goal_specs[goal]["label"],
                    "grade": grade,
                    "ctr_rank": top_rank_maps["click"].get(cid),
                    "total_cvr_rank": top_rank_maps["conversion"].get(cid),
                    "purchase_cvr_rank": top_rank_maps["purchase"].get(cid),
                    "image_summary": image_summary if image_ready else "이미지 분석 필요",
                    "copy_summary": copy_summary if copy_ready else "카피 분석 필요",
                    "opencv_summary": opencv_summary if image_ready else "이미지 수치 분석 필요",
                    "creative_direction": _creative_direction(row, goal),
                    **purpose_fit,
                }
            )
        return out

    creative_compare_rows = _creative_rows()

    def _is_advoost_exposure(row: dict) -> bool:
        label = " ".join(
            [
                _collapse_ws_text(row.get("media")),
                _collapse_ws_text(row.get("placement")),
                _collapse_ws_text(row.get("name")),
            ]
        ).lower()
        return "advoost" in label

    def _operation_blueprint_rows() -> list[dict]:
        rows_out: list[dict] = []
        for goal in ("click", "conversion", "purchase"):
            exposure = next((x for x in operation_compare_rows if x.get("goal") == goal and x.get("axis") == "audience_media_placement"), {})
            exposure_is_advoost = _is_advoost_exposure(exposure)
            audience = exposure.get("audience") or "데이터 부족"
            media = exposure.get("media") or "데이터 부족"
            placement = exposure.get("placement") or "데이터 부족"
            rows_out.append(
                {
                    "goal": goal,
                    "goal_label": goal_specs[goal]["label"],
                    "decision_metric": goal_specs[goal]["metric_label"],
                    "recommended_gender": exposure.get("gender") or "전체",
                    "recommended_age": exposure.get("age") or "전체",
                    "recommended_audience": audience,
                    "recommended_media": media,
                    "recommended_placement": placement,
                    "recommended_creative": "운영 공식 전용",
                    "ad_product_type": "ADVoost 쇼핑" if exposure_is_advoost else "전체 캠페인 운영",
                    "ad_product_purpose": "쇼핑 노출/상품 탐색" if exposure_is_advoost else "광고형태 전체의 노출 조건 최적화",
                    "purpose_fit": "운영 분석",
                    "purpose_fit_reason": "소재 유무와 무관하게 전체 캠페인의 타겟/매체/게재위치 성과를 기준으로 판단합니다.",
                    "recommended_image_elements": "운영 공식 전용",
                    "recommended_copy_elements": "운영 공식 전용",
                    "creative_direction": "운영 공식 전용: 소재 제작 판단은 별도 소재 제작 공식과 전략 매트릭스에서 봅니다.",
                    "operation_action": exposure.get("operation_suggestion") or "운영 데이터 보강 후 판단",
                    "grade": exposure.get("grade") or "D",
                    "metric_value": exposure.get("metric_value") or 0,
                    "has_creative_material": False,
                    "strategic_role": "목적별 노출 운영 최적 조건",
                    "exposure_formula": f"{audience}에게 {media} / {placement} 중심으로 노출",
                    "creative_formula": "소재 제작 공식은 별도 표에서 판단",
                    "success_formula": "광고형태와 무관하게 목적 지표가 높은 타겟/매체/게재위치 조합에 예산을 우선 배분",
                    "avoid_formula": "소재 없는 광고형태까지 소재 제작 대상으로 해석하는 운영",
                    "decision_rule": f"{goal_specs[goal]['metric_label']}를 1차 기준으로 보고 비용·클릭수·구매ROAS로 확장 여부를 보정",
                    "next_test": f"{goal_specs[goal]['label']} 목적의 다음 테스트는 {audience} / {placement} 조건에서 노출 운영 조건을 조정해 검증",
                }
            )
        return rows_out

    def _creative_goal_matrix_rows() -> list[dict]:
        rows_out: list[dict] = []
        for goal in ("click", "conversion", "purchase"):
            creative = next((x for x in creative_compare_rows if x.get("recommended_goal") == goal), {})
            rows_out.append(
                {
                    "goal": goal,
                    "goal_label": goal_specs[goal]["label"],
                    "decision_metric": goal_specs[goal]["metric_label"],
                    "recommended_gender": "소재 분석 기준",
                    "recommended_age": "소재 분석 기준",
                    "recommended_audience": "소재 분석 기준",
                    "recommended_media": "소재 분석 기준",
                    "recommended_placement": "소재 분석 기준",
                    "recommended_creative": creative.get("creative_name") or creative.get("name") or "데이터 부족",
                    "ad_product_type": creative.get("ad_product_type") or "광고형태 미확인",
                    "ad_product_purpose": creative.get("ad_product_purpose") or "분류 필요",
                    "purpose_fit": creative.get("purpose_fit") or "판정 보류",
                    "purpose_fit_reason": creative.get("purpose_fit_reason") or "소재 후보 기준으로 판정할 데이터가 부족합니다.",
                    "recommended_image_elements": creative.get("image_summary") or "분류 필요",
                    "recommended_copy_elements": creative.get("copy_summary") or "분류 필요",
                    "creative_direction": creative.get("creative_direction") or "소재 분석 데이터 보강 후 판단",
                    "operation_action": "소재 제작 공식 전용",
                    "grade": creative.get("grade") or "D",
                    "metric_value": creative.get(goal_specs[goal]["metric"]) or 0,
                    "has_creative_material": True,
                }
            )
        return rows_out

    def _creative_blueprint_rows(source_rows: list[dict]) -> list[dict]:
        rows_out: list[dict] = []
        for row in source_rows:
            goal = str(row.get("goal") or "")
            goal_label = str(row.get("goal_label") or "")
            metric_label = str(row.get("decision_metric") or "")
            image_elements = str(row.get("recommended_image_elements") or "분류 필요")
            copy_elements = str(row.get("recommended_copy_elements") or "분류 필요")
            if goal == "click":
                strategic_role = "낮은 진입장벽으로 클릭을 만드는 유입형 소재"
                success_formula = "공감/호기심 카피를 1차 성공요소로 두고, 이미지는 그 카피를 즉시 이해하게 돕는 단일 오브젝트로 보조"
                avoid_formula = "카피 의미는 약하고 이미지 장식만 강하거나, 구매 설득 정보가 과도해 첫 클릭 장벽을 높이는 구성"
            elif goal == "conversion":
                strategic_role = "관심 고객을 장바구니 또는 구매 전 단계로 이동시키는 가망고객 확보 소재"
                success_formula = "문제 인식과 구매 후 이득을 카피로 먼저 설득하고, 이미지는 그 혜택/근거를 충돌 없이 설명"
                avoid_formula = "클릭은 만들지만 카피의 구매 이유가 약하거나 이미지가 카피의 감정/혜택과 충돌하는 구성"
            else:
                strategic_role = "구매 의사결정을 밀어주는 매출 확보형 소재"
                success_formula = "구매 이유/신뢰/장벽 해소를 카피로 명확히 말하고, 이미지는 그 약속을 증명하는 보조 증거로 배치"
                avoid_formula = "감성 이미지만 있거나 카피와 이미지가 상반되어 구매 목적과 신뢰를 흐리는 구성"
            rows_out.append(
                {
                    **row,
                    "strategic_role": strategic_role,
                    "exposure_formula": "운영 공식은 별도 표에서 판단",
                    "creative_formula": f"카피(80%): {copy_elements} / 이미지 보조(20%): {image_elements}",
                    "success_formula": success_formula,
                    "avoid_formula": avoid_formula,
                    "decision_rule": f"{metric_label}를 1차 기준으로 보고, 비용·클릭수·구매ROAS로 확장 여부를 보정",
                    "next_test": f"{goal_label} 목적의 다음 테스트는 소재가 있는 캠페인에서 {image_elements} + {copy_elements} 후보를 제작해 검증",
                }
            )
        return rows_out

    operation_blueprints = _operation_blueprint_rows()
    goal_matrix = _creative_goal_matrix_rows()
    creative_blueprints = _creative_blueprint_rows(goal_matrix)
    strategy_blueprints = operation_blueprints + creative_blueprints

    def _summary_rows() -> list[str]:
        out: list[str] = []
        for row in operation_blueprints:
            out.append(f"{row['goal_label']} 운영: {row['exposure_formula']}합니다.")
        for row in creative_blueprints:
            out.append(f"{row['goal_label']} 소재: {row['creative_formula']} 공식으로 소재를 제작합니다.")
        weak = next((x for x in condition_gap_rows if x.get("grade") == "D"), None)
        if weak:
            out.append(f"우선 개선: {weak.get('name')}은 {weak.get('problem_cause')} 때문에 {weak.get('recommendation')}")
        return out[:5]

    executive_summary = _summary_rows()

    action_rows = []
    for row in condition_gap_rows[:20]:
        action_rows.append(
            {
                "name": row.get("name"),
                "level_label": row.get("level_label"),
                "action_type": "확대" if row.get("grade") in {"S", "A"} else "개선" if row.get("grade") == "B" else "중단/교체 검토",
                "grade": row.get("grade"),
                "reason": row.get("problem_cause"),
                "recommendation": row.get("recommendation"),
                "cost": row.get("cost"),
                "ctr": row.get("ctr"),
                "total_cvr": row.get("total_cvr") or row.get("cvr"),
                "purchase_cvr": row.get("purchase_cvr"),
                "purchase_roas": row.get("purchase_roas"),
            }
        )

    def _recommendation(goal: str) -> dict:
        axis = operating_factor_analysis["audience_media_placement"][goal]["top"]
        creative_top = (
            creative_factor_analysis["top_ctr"]
            if goal == "click"
            else creative_factor_analysis["top_total_cvr"]
            if goal == "conversion"
            else creative_factor_analysis["top_purchase_cvr"]
        )
        pattern_key = "image_type_by_ctr" if goal == "click" else "appeal_point_by_total_cvr" if goal == "conversion" else "message_type_by_purchase_cvr"
        patterns = creative_factor_analysis["patterns"].get(pattern_key) or []
        best_axis = axis[0] if axis else {}
        best_creative = creative_top[0] if creative_top else {}
        best_pattern = patterns[0] if patterns else {}
        if goal == "click":
            summary = "CTR이 높은 타겟/게재위치와 이미지 유형을 우선 확장해 유입량을 키웁니다."
            primary_metric = "CTR"
        elif goal == "conversion":
            summary = "총전환 CVR이 높은 소재/조합을 가망고객 확보용으로 분리 운영합니다."
            primary_metric = "총전환 CVR"
        else:
            summary = "구매완료 CVR/구매 ROAS가 높은 조합에 예산을 집중합니다."
            primary_metric = "구매완료 CVR"
        return {
            "goal": goal,
            "label": _goal_label(goal),
            "summary": summary,
            "primary_metric": primary_metric,
            "recommended_audience": best_axis.get("audience") or best_axis.get("name") or "데이터 부족",
            "recommended_media": best_axis.get("media") or "데이터 부족",
            "recommended_placement": best_axis.get("placement") or best_axis.get("name") or "데이터 부족",
            "recommended_creative_type": best_creative.get("image_type") or best_creative.get("creative_type") or "미분류",
            "recommended_appeal_or_message": best_creative.get("appeal_point") or best_creative.get("message_type") or best_pattern.get("name") or "미분류",
            "test_candidates": creative_top[:5],
            "operating_candidates": axis[:5],
        }

    goal_recommendations = {
        "click": _recommendation("click"),
        "conversion": _recommendation("conversion"),
        "purchase": _recommendation("purchase"),
    }

    strong = sorted(
        [x for x in finalized if int(x["cost"] or 0) > 0],
        key=lambda x: (float(x.get("purchase_revenue") or 0) / max(1, int(x.get("cost") or 0)), int(x.get("purchase_conversions") or 0), int(x.get("cost") or 0)),
        reverse=True,
    )[:10]
    weak_rows = sorted(
        [x for x in (_gfa_finalize_metrics(v) for v in weak.values()) if int(x["cost"] or 0) > 0 and int(x.get("purchase_conversions") or 0) == 0],
        key=lambda x: int(x.get("cost") or 0),
        reverse=True,
    )[:10]
    suggestions = []
    if strong:
        top = strong[0]
        suggestions.append(
            f"{top['appeal_point']} 소구 / {top['image_type']} 이미지 / {top['placement']} / {top['audience']} 조합을 우선 확장 후보로 봅니다."
        )
    if weak_rows:
        w = weak_rows[0]
        suggestions.append(
            f"{w['creative_name']} 소재는 {w['placement']} / {w['audience']}에서 비용 대비 구매완료가 없어 축소 또는 교체 후보입니다."
        )
    result = {
        "ok": True,
        "date_from": df.isoformat(),
        "date_to": dt.isoformat(),
        "metric_definitions": {
            "total": {
                "label": "총전환",
                "cvr": "총전환수 / 클릭수",
                "revenue": "전체 전환매출액",
                "roas": "전체 전환매출액 / 비용",
            },
            "purchase": {
                "label": "구매완료",
                "cvr": "구매완료 전환수 / 클릭수",
                "revenue": "구매완료 전환매출액",
                "roas": "구매완료 전환매출액 / 비용",
            },
            "cart": {
                "label": "장바구니",
                "cvr": "장바구니 전환수 / 클릭수",
                "revenue": "장바구니 전환매출액",
                "roas": "장바구니 전환매출액 / 비용",
            },
        },
        "executive_summary": executive_summary,
        "goal_matrix": goal_matrix,
        "operation_blueprints": operation_blueprints,
        "creative_blueprints": creative_blueprints,
        "strategy_blueprints": strategy_blueprints,
        "high_performance_baselines": high_performance_baselines,
        "condition_hierarchy": condition_hierarchy,
        "condition_gap_rows": condition_gap_rows,
        "operation_compare_rows": operation_compare_rows,
        "creative_compare_rows": creative_compare_rows,
        "action_rows": action_rows,
        "campaign_condition": campaign_diagnosis,
        "operating_factor_analysis": operating_factor_analysis,
        "creative_factor_analysis": creative_factor_analysis,
        "goal_recommendations": goal_recommendations,
        "strong_combinations": strong,
        "weak_combinations": weak_rows,
        "suggestions": suggestions,
    }
    result["_analysis_storage"] = {
        "hit": False,
        "analysis_type": "strategy",
        "analysis_version": GFA_STRATEGY_ANALYSIS_VERSION,
        "source_fingerprint": source_fingerprint,
    }
    if storage_enabled:
        _gfa_store_analysis_result(
            db,
            analysis_type="strategy",
            version=GFA_STRATEGY_ANALYSIS_VERSION,
            date_from=df,
            date_to=dt,
            params=analysis_params,
            fingerprint=source_fingerprint,
            result=result,
        )
    return result


