def _gfa_generator_extract_reference_text(filename: str, data: bytes, content_type: str | None = None) -> str:
    name = str(filename or "reference").strip() or "reference"
    lower = name.lower()
    text = ""
    try:
        if lower.endswith(".docx"):
            with zipfile.ZipFile(io.BytesIO(data)) as zf:
                raw = zf.read("word/document.xml").decode("utf-8", errors="ignore")
            text = unescape(re.sub(r"<[^>]+>", "\n", raw))
        elif lower.endswith((".txt", ".md", ".csv", ".json", ".html", ".htm")) or str(content_type or "").startswith("text/"):
            try:
                text = data.decode("utf-8")
            except Exception:
                text = data.decode("cp949", errors="ignore")
        else:
            return ""
    except Exception:
        return ""
    lines = [_collapse_ws_text(x) for x in str(text or "").splitlines() if _collapse_ws_text(x)]
    return f"[첨부 텍스트: {name}]\n" + "\n".join(lines[:120])


def _gfa_generator_fetch_reference_image_from_url(url: str, *, filename: str = "source_creative") -> dict | None:
    raw_url = str(url or "").strip()
    if not raw_url.lower().startswith(("http://", "https://")):
        return None
    try:
        resp = requests.get(
            raw_url,
            headers={"User-Agent": "Mozilla/5.0 (ERP2 Analytics Creative Generator)"},
            timeout=20,
            stream=True,
        )
        if int(resp.status_code) != 200:
            return None
        mime = str(resp.headers.get("content-type") or "image/jpeg").split(";")[0].strip() or "image/jpeg"
        if not mime.startswith("image/"):
            return None
        chunks: list[bytes] = []
        total = 0
        max_bytes = 6_000_000
        for chunk in resp.iter_content(chunk_size=65536):
            if not chunk:
                continue
            chunks.append(chunk)
            total += len(chunk)
            if total > max_bytes:
                return None
        data = b"".join(chunks)
        if not data:
            return None
        return {
            "filename": filename,
            "mime_type": mime,
            "source": "selected_creative_image",
            "url": raw_url,
            "size": len(data),
            "data_base64": base64.b64encode(data).decode("ascii"),
        }
    except Exception:
        return None


def _gfa_generator_product_image_reference(db: Session, selected: dict) -> dict | None:
    product_context = selected.get("product_context") if isinstance(selected.get("product_context"), dict) else {}
    product_id = str(product_context.get("product_id") or "").strip()
    if not product_id:
        return None
    try:
        rows = (
            db.query(TrackedProductMeta)
            .filter(
                TrackedProductMeta.image_url.isnot(None),
                TrackedProductMeta.image_url != "",
                or_(
                    TrackedProductMeta.product_url == f"https://smartstore.naver.com/thesujata/products/{product_id}",
                    TrackedProductMeta.product_url.like(f"%/products/{product_id}"),
                    TrackedProductMeta.product_url.like(f"%/products/{product_id}?%"),
                ),
            )
            .order_by(TrackedProductMeta.updated_at.desc(), TrackedProductMeta.id.desc())
            .limit(1)
            .one_or_none()
        )
    except Exception:
        rows = None
    if rows is None:
        return None
    ref = _gfa_generator_fetch_reference_image_from_url(
        str(getattr(rows, "image_url", "") or ""),
        filename=f"product_{product_id}",
    )
    if ref:
        ref["source"] = "tracked_product_image"
        ref["product_url"] = getattr(rows, "product_url", None)
        ref["product_title"] = getattr(rows, "title", None)
    return ref


def _gfa_attach_product_authority(db: Session, *, sku: str, explanation: dict, resolve_mode: str = "GENERATION") -> dict:
    from gfa_product_authority import (
        PRODUCT_AUTHORITY_AVAILABLE,
        public_authority_record,
        resolve_product_authority,
    )

    explanation = explanation if isinstance(explanation, dict) else {}
    persisted = explanation.get("productAuthority") if isinstance(explanation.get("productAuthority"), dict) else {}
    record = resolve_product_authority(db, sku, persisted=persisted, resolve_mode=resolve_mode)
    data = record.get("bytes") if isinstance(record.get("bytes"), (bytes, bytearray)) else b""
    if str(record.get("status") or "") == PRODUCT_AUTHORITY_AVAILABLE and data:
        source_path = str(record.get("sourcePath") or "").strip()
        if not source_path or not os.path.exists(source_path):
            record["sourcePath"] = _gfa_generator_write_image_file(
                bytes(data),
                str(record.get("sourceMime") or "image/png"),
                prefix="gfa_product_source",
            )
        foreground_path = str(record.get("foregroundPath") or "").strip()
        if not foreground_path or not os.path.exists(foreground_path):
            try:
                foreground = _gfa_generator_prepare_reference_product_foreground(
                    bytes(data),
                    reference_mime=str(record.get("sourceMime") or "image/png"),
                )
                record["foregroundPath"] = _gfa_generator_write_image_file(
                    foreground["foregroundPng"],
                    "image/png",
                    prefix="gfa_product_foreground",
                )
                record["foregroundSummary"] = foreground.get("summary") if isinstance(foreground.get("summary"), dict) else {}
            except Exception as exc:
                record["foregroundError"] = str(exc)[:300]
    public = public_authority_record(record)
    explanation["productAuthority"] = public
    return public


async def _gfa_generator_request_from_http(request: Request) -> tuple[GfaCreativeGeneratorRunRequest, dict]:
    content_type = str(request.headers.get("content-type") or "").lower()
    references: dict[str, object] = {"text_blocks": [], "files": [], "images": []}
    if "multipart/form-data" not in content_type:
        body = await request.json()
        return GfaCreativeGeneratorRunRequest(**(body or {})), references

    form = await request.form()
    def _form_str(key: str, default: str | None = None) -> str | None:
        val = form.get(key)
        if val is None:
            return default
        s = str(val).strip()
        return s or default

    payload = {
        "goal": _form_str("goal", "click"),
        "template_type": _form_str("template_type", "problem_direct"),
        "source_creative_id": _form_str("source_creative_id"),
        "date_from": _form_str("date_from"),
        "date_to": _form_str("date_to"),
        "candidate_count": int(_form_str("candidate_count", "3") or 3),
        "openai_model": _form_str("openai_model"),
        "gemini_model": _form_str("gemini_model"),
        "additional_reference_text": _form_str("additional_reference_text"),
    }
    text_blocks: list[str] = []
    direct_text = _collapse_ws_text(payload.get("additional_reference_text"))
    if direct_text:
        text_blocks.append(f"[직접 입력 참고자료]\n{direct_text[:6000]}")

    files = [v for k, v in form.multi_items() if k == "reference_files" and hasattr(v, "filename") and hasattr(v, "read")]
    for file in files[:8]:
        data = await file.read()
        if not data:
            continue
        filename = str(file.filename or "reference").strip() or "reference"
        content_type0 = str(file.content_type or "")
        file_meta = {"filename": filename, "content_type": content_type0, "size": len(data)}
        references["files"].append(file_meta)
        if content_type0.startswith("image/"):
            references["images"].append(
                {
                    "filename": filename,
                    "mime_type": content_type0 or "image/png",
                    "data_base64": base64.b64encode(data[:6_000_000]).decode("ascii"),
                }
            )
            continue
        extracted = _gfa_generator_extract_reference_text(filename, data[:1_000_000], content_type0)
        if extracted:
            text_blocks.append(extracted[:6000])
    references["text_blocks"] = text_blocks
    return GfaCreativeGeneratorRunRequest(**payload), references


def _gfa_generator_public_brief(brief: dict) -> dict:
    out = copy.deepcopy(brief if isinstance(brief, dict) else {})
    refs = out.get("additional_references")
    if isinstance(refs, dict):
        images = refs.get("images")
        if isinstance(images, list):
            refs["images"] = [
                {k: v for k, v in img.items() if k != "data_base64"}
                for img in images
                if isinstance(img, dict)
            ]
    return out


def _gfa_generator_creative_copy_brief(*, source: dict, guide: dict | None = None) -> dict:
    source = source if isinstance(source, dict) else {}
    guide = guide if isinstance(guide, dict) else {}
    source_copy = source.get("source_copy") if isinstance(source.get("source_copy"), dict) else _gfa_generator_source_copy_context(source)
    feature = source.get("copy_feature_layer") if isinstance(source.get("copy_feature_layer"), dict) else {}
    weighted = source.get("copy_weighted_feature_layer") if isinstance(source.get("copy_weighted_feature_layer"), dict) else {}
    design = source.get("copy_design_plan") if isinstance(source.get("copy_design_plan"), dict) else {}
    dna = source.get("copy_creative_dna") if isinstance(source.get("copy_creative_dna"), dict) else {}
    success = source.get("copy_success_dna") if isinstance(source.get("copy_success_dna"), dict) else {}
    diff = source.get("copy_differentiation") if isinstance(source.get("copy_differentiation"), dict) else {}
    product_context = source.get("product_context") if isinstance(source.get("product_context"), dict) else {}
    source_row = source.get("source_row") if isinstance(source.get("source_row"), dict) else {}

    def list_text(v: object) -> str:
        if isinstance(v, list):
            return " ".join(str(x.get("keyword") if isinstance(x, dict) else x) for x in v if x)
        if isinstance(v, dict):
            return " ".join(str(x) for x in v.values())
        return str(v or "")

    raw_text = " ".join(
        str(x or "")
        for x in [
            source_copy.get("live_copy"),
            source_copy.get("copy_summary"),
            source.get("copy_summary"),
            source.get("image_summary"),
            source.get("creative_direction"),
            source_row.get("copy_summary"),
            source_row.get("creative_direction"),
            list_text(product_context.get("purchase_keywords")),
            list_text(product_context.get("inferred_product_traits")),
            list_text(diff.get("unique_claims")),
        ]
    )
    has_mom = "엄마" in raw_text
    has_gray = any(x in raw_text for x in ["새치", "흰머리", "백발"])
    has_worry = any(x in raw_text for x in ["걱정", "고민", "어떡", "미루"])
    has_henna = any(x in raw_text for x in ["헤나", "천연", "식물", "유기농", "비건", "무암모니아"])
    is_self_talk = any(x in str(source_copy.get("expression_style") or "") for x in ["독백형", "속마음"])

    unique_claims = [str(x).strip() for x in (diff.get("unique_claims") if isinstance(diff.get("unique_claims"), list) else []) if str(x).strip()]
    usp_candidates: list[str] = []
    for token, label in [
        ("유기농", "유기농 원료"),
        ("100%", "100% 천연"),
        ("천연", "천연/식물성 원료"),
        ("식물", "식물성 원료"),
        ("비건", "비건"),
        ("무암모니아", "무암모니아"),
        ("헤나", "헤나 기반"),
        ("집에서", "집에서 가능"),
    ]:
        if token in raw_text and label not in usp_candidates:
            usp_candidates.append(label)
    for claim in unique_claims:
        if claim and "family" not in claim.lower() and "care" not in claim.lower() and claim not in usp_candidates:
            usp_candidates.append(claim)

    emotion_primary = "family_care" if has_mom else (_collapse_ws_text(dna.get("emotion_driver")) or "problem_awareness")
    emotion_secondary = "anxiety" if has_worry else (_collapse_ws_text(design.get("secondary_emotion")) or "")
    function_primary = "gray_hair_cover" if has_gray else (_collapse_ws_text(dna.get("decision_trigger")) or "problem_solution")
    benefit_primary = "집에서 순하게 새치 걱정을 덜 수 있음" if has_gray and has_henna else "구매 후 고민을 더 쉽게 해결할 수 있음"
    emotional_payoff = "엄마 걱정을 미루지 않았다는 안심" if has_mom and has_gray else "지금 필요한 관리를 시작했다는 안심"
    usp_primary = usp_candidates[0] if usp_candidates else ("천연/식물성 원료" if has_henna else "제품 차별점 1개")
    evidence_primary = "유기농/식물성 원료 신뢰" if any(x in raw_text for x in ["유기농", "식물", "천연"]) else "근거 없는 숫자 대신 제품 맥락 1개"

    return {
        "purpose": {
            "goal": "purchase",
            "flow": ["scroll_stop", "empathy", "trust", "purchase_reason", "cta"],
            "one_sentence_strategy": "엄마 새치 걱정을 공감시키고, 집에서 순하게 관리할 수 있다는 안심을 구매 이유로 만든다."
            if has_mom and has_gray
            else "문제 공감 후 구매 후 이득 1개와 신뢰 근거 1개로 행동을 유도한다.",
        },
        "audience": {
            "target": "엄마 새치를 걱정하는 자녀 또는 45~60 여성" if has_mom else "새치/모발 고민 소비자",
            "viewpoint": "소비자 1인칭/가족 걱정 관점" if has_mom and is_self_talk else "소비자 문제 해결 관점",
        },
        "message_decisions": {
            "primary_emotion": emotion_primary,
            "secondary_emotion": emotion_secondary,
            "forbidden_emotions": ["aging_fear", "shame", "appearance_blame"] if has_mom else ["excessive_fear", "medical_anxiety"],
            "primary_function": function_primary,
            "primary_benefit": benefit_primary,
            "emotional_payoff": emotional_payoff,
            "primary_usp": usp_primary,
            "evidence": evidence_primary,
            "forbidden_claims": ["근거 없는 수치", "의학적 효능", "엄마 외모 지적", "family_care를 USP처럼 반복"],
        },
        "copy_rules": {
            "headline": {
                "objective": "스크롤 정지와 자기 관련성 형성",
                "style": "소비자 독백형 질문" if is_self_talk else "문제 제기형 질문",
                "target_chars": "12~16자",
                "hard_max_chars": 16,
                "must_include": ["엄마", "새치"] if has_mom and has_gray else ["새치"] if has_gray else [],
                "must_not_include": ["구매", "브랜드명", "또 보여", "늙어", "노화"],
            },
            "subcopy": {
                "objective": "구매 후 이득 1개 전달",
                "target_chars": "20~28자",
                "hard_max_chars": 28,
                "must_express": [benefit_primary],
                "must_not_do": ["키워드 나열", "혜택 2개 이상", "미완성 문장"],
            },
            "proof_line": {
                "objective": "신뢰 근거 1개만 보조",
                "target_chars": "6~18자",
                "hard_max_chars": 24,
                "use_only_one": evidence_primary,
            },
            "cta": {
                "objective": "짧은 구매 행동 유도",
                "target_chars": "4~8자",
                "hard_max_chars": 8,
                "action": "buy",
                "reason": "엄마 새치 걱정을 오늘부터 줄이기" if has_mom and has_gray else "지금 필요한 관리를 시작하기",
                "examples": ["순하게 시작하기", "엄마 새치 케어", "지금 케어하기"] if has_mom else ["지금 시작하기", "관리 시작하기"],
                "must_not_do": ["문장형 CTA", "혜택+상품+행동을 모두 붙인 긴 CTA", "자세히 보기"],
            },
        },
        "source_signals_for_audit": {
            "feature_layer": feature,
            "weighted_feature_layer": weighted,
            "design_plan": design,
            "creative_dna": dna,
            "success_dna": success,
            "differentiation": diff,
            "guide_copywriting": guide.get("copywriting") if isinstance(guide.get("copywriting"), dict) else {},
        },
    }


def _gfa_generator_combination_strategy(*, brief: dict, candidate_index: int, candidate_count: int) -> dict:
    image_elements = str(brief.get("image_elements") or "")
    copy_elements = str(brief.get("copy_elements") or "")
    opencv_elements = str(brief.get("opencv_elements") or "")
    creative_dna = brief.get("creative_dna") if isinstance(brief.get("creative_dna"), dict) else {}
    visual_strategy = brief.get("visual_strategy") if isinstance(brief.get("visual_strategy"), dict) else {}
    creative_prompt = brief.get("creative_prompt") if isinstance(brief.get("creative_prompt"), dict) else {}
    template_type = str(brief.get("template_type") or "problem_direct")
    template_label = str(brief.get("template_label") or "")
    palette = ["주황 CTA + 자연 초록 보조색", "고대비 베이지/브라운 + 빨강 CTA", "밝은 배경 + 진한 네이비 텍스트 + 주황 CTA"]
    template_plan = {
        "problem_direct": {
            "subjects": ["새치 고민이 드러나는 인물 헤어 클로즈업", "거울 앞에서 새치를 확인하는 장면", "두피/모발 고민을 표현하는 자연스러운 인물"],
            "compositions": [
                "좌측 38~42%는 상단 Hook, 중단 Benefit/Proof, 하단 CTA가 들어갈 3단 카피 컬럼으로 비워두고, 우측 50~92% 안에 새치 고민 인물/모발 장면과 제품 또는 원료 컷 1개를 중앙-우측 균형으로 배치",
                "좌측 38~42%는 상단 문제 Hook, 중단 안심 Benefit, 하단 CTA가 자연스럽게 이어지는 카피 컬럼으로 비워두고, 우측 50~92% 안에 거울 앞 새치 확인 장면과 작은 제품 패키지 컷을 끝에 몰리지 않게 배치",
                "좌측 38~42%는 빈 박스가 아니라 카피 흐름을 받을 깨끗한 3단 컬럼으로 두고, 우측 50~92% 안에는 감정이 보이는 인물 헤어 장면과 헤나 원료감을 중앙-우측에 안정적으로 배치",
            ],
            "appeals": ["문제 직격과 손실 회피", "고민 공감과 해결 기대", "지금 관리해야 하는 이유"],
            "must_follow": "문제 직격형 구조를 반드시 따른다. before/after 비교판이나 후기/증거 카드 중심 구도로 바꾸지 않는다.",
        },
        "before_after": {
            "subjects": ["새치 많은 모발과 자연스럽게 커버된 모발의 비교", "사용 전/사용 후 헤어 상태 비교", "동일 인물 또는 유사 각도의 헤어 변화 비교"],
            "compositions": [
                "좌측 38~42%는 Hook/Benefit/CTA 3단 카피 컬럼으로 비워두고, 우측 50~92% 안에서만 사용 전/후 모발 대비를 단순하게 표현",
                "좌측 38~42%는 중간이 비지 않도록 Benefit/Proof 텍스트 자리까지 고려한 카피 컬럼으로 두고, 우측 50~92%는 두 컷 이하 전후 비교를 과하지 않게 배치",
                "좌측 38~42%는 상중하 카피 흐름을 받을 깨끗한 배경으로 두고, 우측 50~92%는 변화 대비가 보이는 헤어 결과 장면 1개를 중앙-우측에 배치",
            ],
            "appeals": ["변화 대비와 결과 기대", "사용 전후 차이의 즉시 이해", "집에서 관리 가능한 변화"],
            "must_follow": "비포/애프터 비교형 구조를 반드시 따른다. 단일 인물 문제 제기형이나 후기 카드형으로 바꾸지 않는다.",
        },
        "proof_review": {
            "subjects": ["천연 헤나 염색약 제품 패키지와 관리 후 모발", "제품 신뢰감을 주는 패키지 중심 장면", "모발 결과와 제품을 함께 보여주는 구매 설득 장면"],
            "compositions": [
                "좌측 38~42%는 신뢰 메시지/Benefit/CTA 3단 카피 컬럼으로 비워두고, 우측 50~92%는 제품 패키지와 모발 결과만 단순 배치",
                "좌측 38~42%는 중간 공백이 생기지 않게 Proof 텍스트 자리까지 고려한 카피 컬럼으로 두고, 우측 50~92%는 제품 패키지 중심 장면과 헤나 원료 컷 1개",
                "좌측 38~42%는 큰 Hook과 중단 증거선, 하단 CTA를 받을 배경으로 두고, 우측 50~92%는 제품/모발 결과를 한 장면처럼 중앙-우측에 구성",
            ],
            "appeals": ["신뢰 근거와 구매 장벽 해소", "제품 효익과 안전한 성분 이미지", "후기/증거를 통한 구매 확신"],
            "must_follow": "후기/데이터 증거형 구조를 반드시 따른다. 문제만 크게 제기하는 단일 이미지나 before/after 2분할 중심으로 바꾸지 않는다.",
        },
    }
    plan = template_plan.get(template_type, template_plan["problem_direct"])
    idx = max(0, (candidate_index - 1) % 3)
    return {
        "candidate_index": candidate_index,
        "candidate_count": candidate_count,
        "template_type": template_type,
        "template": template_label,
        "selected_template_must_follow": plan["must_follow"],
        "selected_template_structure": brief.get("template_structure") or [],
        "source_analysis_used": {
            "image": image_elements,
            "copy": copy_elements,
            "opencv": opencv_elements,
            "creative_dna": creative_dna,
            "creative_prompt": creative_prompt,
        },
        "visual_combination": {
            "color": palette[idx],
            "person_or_object": plan["subjects"][idx],
            "composition": plan["compositions"][idx],
            "opencv_guidance": opencv_elements,
            "visual_hierarchy_path": visual_strategy.get("visual_hierarchy_path") if isinstance(visual_strategy.get("visual_hierarchy_path"), list) else ["headline", "benefit", "cta"],
            "visual_weight_target": visual_strategy.get("visual_weight") if isinstance(visual_strategy.get("visual_weight"), dict) else {},
            "visual_trigger": creative_dna.get("visual_trigger") or creative_prompt.get("visual_trigger") or "copy_support",
        },
        "copy_combination": {
            "appeal": plan["appeals"][idx],
            "copy_source": copy_elements,
            "emotion_driver": creative_dna.get("emotion_driver") or creative_prompt.get("primary_emotion") or "",
            "decision_trigger": creative_dna.get("decision_trigger") or creative_prompt.get("primary_benefit") or "",
            "purchase_trigger": creative_dna.get("purchase_trigger") or creative_prompt.get("primary_usp") or "",
            "cta_rule": "행동 + 이유가 있는 CTA 1개만 사용",
        },
        "generation_intent": f"{template_label} 구조를 반드시 유지하면서 {plan['appeals'][idx]}를 강조하는 {candidate_index}/{candidate_count}번 후보입니다.",
    }


def _gfa_generator_explanation(*, brief: dict, combination: dict, copy_result: dict) -> dict:
    visual = combination.get("visual_combination") if isinstance(combination.get("visual_combination"), dict) else {}
    copy_combo = combination.get("copy_combination") if isinstance(combination.get("copy_combination"), dict) else {}
    return {
        "summary": combination.get("generation_intent") or "",
        "why_image": [
            f"이미지 분석 요소({brief.get('image_elements') or '분석 필요'})를 시각 주제로 사용했습니다.",
            f"OpenCV/구도 수치({brief.get('opencv_elements') or '분석 필요'})를 참고해 {visual.get('composition') or '명확한 단일 구도'}로 설계했습니다.",
            f"색상은 {visual.get('color') or 'CTA 대비 중심'}로 지정해 배너 제작 가이드의 강한 대비 원칙을 반영했습니다.",
        ],
        "why_copy": [
            f"카피 분석 요소({brief.get('copy_elements') or '분석 필요'})에서 핵심 키워드/고민/소구를 가져왔습니다.",
            f"소구 방식은 {copy_combo.get('appeal') or '문제-해결'} 중심으로 잡았습니다.",
            f"CTA '{copy_result.get('cta') or 'CTA 없음'}'는 행동 이유가 보이도록 생성했습니다.",
        ],
        "guide_checklist": [
            "메시지 1개",
            "혜택 1개",
            "CTA 1개",
            "문제/혜택/증거/CTA 구조",
            "근거 없는 숫자/효능 클레임 금지",
        ],
        "feedback_hint": "실제 광고 집행 후 후보별 CTR, 총전환CVR, 구매CVR, 구매ROAS를 다시 연결해 어떤 조합이 성과를 냈는지 학습합니다.",
    }


def _gfa_copywriting_guide_v2() -> dict:
    return {
        "version": "commercial-banner-copywriting-typography-v2",
        "source_file": "온라인 광고 배너 제작 가이드 카피작성 가이드.pdf",
        "core_principle": "카피는 문학적 문장이 아니라 0.8~1.5초 안에 Hook-Value-Action을 전달하는 시각 신호다.",
        "copy_rules": {
            "headline": {
                "chars_with_spaces": [8, 16],
                "max_lines": 2,
                "role": "Hook: 감정 자극, 도발적 질문, 구체 혜택으로 스크롤 정지",
                "syntax": ["명사형 종결 허용", "구체 명사/동작 동사 우선", "모호한 형용사 배제", "의미 단위 줄바꿈"],
            },
            "subcopy": {
                "chars_with_spaces": [18, 28],
                "max_lines": 2,
                "role": "Proof/Bridge: 메인 카피의 의구심 해소, 구체 근거, 구매 장벽 제거",
                "syntax": ["메인 카피를 반복하지 않음", "키워드 나열 금지", "상세페이지/참고소재 근거 기반"],
            },
            "cta": {
                "chars_with_spaces": [4, 8],
                "role": "Action: 클릭 후 얻을 가치를 암시",
                "ban": ["확인", "자세히 보기", "구매하기"],
            },
        },
        "proven_patterns": [
            "Pain Killer: 문제/고통 훅 -> 해결 근거 -> 가치 CTA",
            "Social Proof: 검증 수치/후기 근거가 있을 때만 사용",
            "Urgency Offer: 실제 기간/쿠폰 근거가 있을 때만 사용",
            "Curiosity Gap: 결론 일부를 숨기되 과장 효능 금지",
        ],
        "typography_rules": {
            "headline_to_subcopy_size_ratio": [1.8, 2.5],
            "headline_font_weight": [800, 900],
            "subcopy_font_weight": [400, 500],
            "headline_line_height": [1.10, 1.25],
            "subcopy_line_height": [1.40, 1.60],
            "word_break": "keep-all; semantic line breaks only",
            "accent": "핵심 단어 1개만 고채도 포인트 컬러 또는 하이라이트",
            "alignment": "좌측 정렬 기본; 중앙 정렬은 1~2줄 임팩트 카피에만 제한",
        },
    }


def _gfa_generator_copy_prompt(brief: dict) -> str:
    expert_copy_guide = _gfa_copywriting_guide_v2()
    return (
        "너는 최고 수준의 상업 광고 카피라이터다. GFA 성과 분석으로 도출된 근거만 사용해 배너용 카피와 CTA를 만든다.\n"
        "반드시 JSON 객체만 반환한다. 마크다운 금지.\n"
        "JSON 스키마: {\"headline\":\"\", \"subcopy\":\"\", \"proof_line\":\"\", \"cta\":\"\", "
        "\"variants\":[{\"headline\":\"\", \"cta\":\"\", \"angle\":\"\"}], \"landing_message\":\"\", \"risk_notes\":[\"\"]}\n"
        "최우선 규칙: creative_copy_brief가 실제 생성 설계도다. Hook/Emotion/Benefit/USP 같은 Feature 목록을 그대로 나열하지 말고, creative_copy_brief의 message_decisions와 copy_rules에 맞춰 문장을 만든다.\n"
        "Feature는 속성 설명이고 Creative Brief는 결정이다. 충돌하면 Creative Brief를 우선한다.\n"
        "Emotion, Function, Benefit, USP, Evidence를 섞지 마라. family_care는 Emotion이지 USP가 아니다. gray_hair_cover는 Function이지 최종 Benefit이 아니다.\n"
        "Primary Emotion 1개, Primary Benefit 1개, USP 1개, Evidence 1개, CTA 1개만 사용한다. 여러 개를 동시에 넣지 않는다.\n"
        "SMP 원칙을 지킨다. 한 배너에는 가장 강한 핵심 USP 1개만 남기고 가격/후기/사은품/스펙을 동시에 나열하지 않는다.\n"
        "목적에 맞춰 PAS, BAB, FAB 중 하나의 흐름을 선택하되 네이버 GFA에서 전후 비교/과장 효능으로 읽히는 표현은 만들지 않는다.\n"
        "creative_copy_brief.copy_rules의 target_chars와 hard_max_chars를 지킨다. 헤드라인은 공백 포함 12~16자, 서브카피는 20~28자, CTA는 4~8자여야 한다.\n"
        "최우선 참고: source_copy_verbatim의 원문 카피가 기준 소재의 의미다. 원문에 엄마/가족 감성, 새치 걱정, 구매 유도가 있으면 반드시 새 카피의 중심 의미로 유지한다.\n"
        "generation_focus가 source_image_focus이면 source_copy_verbatim.live_copy의 핵심 약속/결과/색상/상황을 필수 보존한다. 예: 원문이 '생기 있는 자연스러운 브라운 컬러'라면 이를 '새치 걱정', '순한 관리' 같은 일반 문제 문구로 대체하지 않는다.\n"
        "소재 성공 요소의 80%는 카피다. 이미지/오브젝트/배경은 카피를 보조하고 설명하는 역할이라는 전제로 카피를 만든다.\n"
        "제품 특성(천연, 헤나, 초록 반죽 등)은 보조 근거일 뿐이다. 메인 카피가 제품 속성 설명으로 끝나면 실패다.\n"
        "메인 카피는 강해야 한다. '누구의 어떤 걱정을 왜 지금 해결해야 하는지'를 사람 마음이 움직이게 말한다. 단순히 좋으니까 구매하라는 표현은 금지한다.\n"
        "표현 방식은 source_copy_verbatim.expression_style을 따른다. 기준 소재가 독백형이면 독백형으로, 증거형이면 증거형으로, 혜택형이면 혜택형으로 재작성한다. 모든 소재를 한 가지 말투로 고정하지 않는다.\n"
        "판매자 명령형 금지는 기준 소재가 소비자 속마음/독백형일 때만 적용한다. 독백형에서는 '또 보여?'처럼 엄마의 외모를 지적하는 문장을 쓰지 않는다.\n"
        "서브카피는 구매 후 얻는 혜택/이득을 명확하게 말한다. 예: 걱정을 덜 수 있다, 순하게 관리할 수 있다, 집에서 시작할 수 있다.\n"
        "규칙: 메시지 1개, 혜택 1개, CTA 1개. CTA는 행동+이유를 포함한다. 근거 없는 숫자/후기/효능은 만들지 않는다.\n"
        "headline은 creative_copy_brief의 글자수 규칙을 따르고, 기준 소재의 소구점과 표현 방식을 보존하면서 더 선명하게 직격한다.\n"
        "subcopy는 완성 문장 또는 명확한 명사구로 끝낸다. 조사나 목적어만 남긴 미완성 문장, 키워드 나열형 문구는 금지한다.\n"
        "최종 출력되는 headline/subcopy/proof_line/cta에는 내부 작업어를 절대 쓰지 않는다. 금지어: 가이드, 분석, 반영, 소재, 키워드, 텍스트, 프롬프트, 브리프, 레이아웃, 오버레이, 생성, 신호, 원료감.\n"
        "최종 출력 카피에는 근거 없는 수치/성분/인증 claim을 쓰지 않는다. 특히 0%, 100%, 무첨가, 무자극, 화학 성분, 인증, 1위, 치료/완치/탈모 관련 표현은 원문 증빙이 있어도 배너 오버레이에서는 제외한다.\n"
        "CTA는 '새치 케어 보기', '헤나 케어 보기', '관리 시작하기'처럼 자연스러운 행동형으로만 쓴다. '순해 보러가기', '자세히 보기', '구매하기' 같은 어색하거나 약한 CTA는 금지한다.\n"
        "가이드는 문장을 판단하는 기준일 뿐이며, 소비자가 배너에서 실제로 읽을 자연스러운 한국어 광고 문장만 출력한다.\n"
        "product_context가 있으면 구매 키워드/검색 우위/리뷰 신호/Q&A 구매장벽을 제품 정체성과 소구 근거로 반드시 반영한다.\n"
        "AI 콘텐츠 센터의 상세페이지 분석, 제품 이미지 분석, 관련 이미지/영상 분석에서 확인된 제품 맥락과 구매 장벽을 카피의 근거로 사용한다. 확인되지 않은 수치/인증/효능은 만들지 않는다.\n"
        "전문 카피 작성 가이드 v2를 엄격히 따른다. headline은 12~16자, subcopy는 20~28자, CTA는 4~8자다. 의미 단위 줄바꿈을 넣고, 조사/어미만 따로 떨어지지 않게 한다.\n"
        f"전문 카피 작성 가이드 v2 JSON:\n{_gfa_generator_json_dumps(expert_copy_guide)}\n"
        f"제작 브리프:\n{_gfa_generator_json_dumps(brief)}"
    )


def _gfa_generator_image_prompt_brief(brief: dict) -> dict:
    b = brief if isinstance(brief, dict) else {}
    copy_brief = b.get("creative_copy_brief") if isinstance(b.get("creative_copy_brief"), dict) else {}
    product_context = b.get("product_context") if isinstance(b.get("product_context"), dict) else {}
    refs = b.get("additional_references") if isinstance(b.get("additional_references"), dict) else {}
    return {
        "goal": b.get("goal"),
        "generation_focus": b.get("generation_focus"),
        "generation_focus_label": b.get("generation_focus_label"),
        "template_type": b.get("template_type"),
        "template_label": b.get("template_label"),
        "source_creative_id": b.get("source_creative_id"),
        "source_creative_name": b.get("source_creative_name"),
        "image_elements": b.get("image_elements"),
        "opencv_elements": b.get("opencv_elements"),
        "visual_strategy": b.get("visual_strategy"),
        "guide_layout_metrics": b.get("guide_layout_metrics"),
        "layout_rule": b.get("layout_rule"),
        "layout_metric_rule": b.get("layout_metric_rule"),
        "ad_media_spec": b.get("ad_media_spec") if isinstance(b.get("ad_media_spec"), dict) else {},
        "creative_copy_brief": {
            "purpose": copy_brief.get("purpose") if isinstance(copy_brief.get("purpose"), dict) else {},
            "audience": copy_brief.get("audience") if isinstance(copy_brief.get("audience"), dict) else {},
            "message_decisions": copy_brief.get("message_decisions") if isinstance(copy_brief.get("message_decisions"), dict) else {},
        },
        "product_context": {
            "purchase_keywords": product_context.get("purchase_keywords") if isinstance(product_context.get("purchase_keywords"), list) else [],
            "inferred_product_traits": product_context.get("inferred_product_traits") if isinstance(product_context.get("inferred_product_traits"), list) else [],
            "product_title": product_context.get("product_title"),
        },
        "additional_references": {
            "text": str(refs.get("text") or "")[:1200],
            "files": refs.get("files") if isinstance(refs.get("files"), list) else [],
            "image_count": len(refs.get("images") if isinstance(refs.get("images"), list) else []),
            "usage_rule": refs.get("usage_rule"),
        },
        "claim_policy": b.get("claim_policy"),
    }


def _gfa_generator_image_prompt(
    brief: dict,
    copy_result: dict | None = None,
    combination: dict | None = None,
    product_slot_context: dict | None = None,
) -> str:
    copy_result = copy_result if isinstance(copy_result, dict) else {}
    combination = combination if isinstance(combination, dict) else {}
    refs = brief.get("additional_references") if isinstance(brief.get("additional_references"), dict) else {}
    image_refs = refs.get("images") if isinstance(refs.get("images"), list) else []
    first_ref_source = str((image_refs[0] or {}).get("source") or "") if image_refs and isinstance(image_refs[0], dict) else ""
    edit_source_banner = first_ref_source == "banner_analysis_upload"
    ad_media_spec = brief.get("ad_media_spec") if isinstance(brief.get("ad_media_spec"), dict) else {}
    generation_focus = str(brief.get("generation_focus") or "source_image_focus")
    image_brief = _gfa_generator_image_prompt_brief(brief)
    source_focus_layout_rule = (
        "SOURCE-FOCUSED LAYOUT RULE: keep the analyzed banner's recognizable composition and persuasion structure as the base. "
        "Improve readability, contrast, product salience, CTA clarity, and safe-zone placement without forcing a new left-column template. "
        "If the source uses top-centered headline, central hair/person visual, and bottom CTA/product band, keep that structure and polish it instead of moving everything into a new two-zone layout.\n"
    )
    similar_focus_layout_rule = (
        "Use a BALANCED TWO-ZONE layout: left 38-42% is a vertical copy column for three later overlay stops (top headline, middle benefit/proof, bottom CTA), and right 50-92% contains one clear visual subject plus optional product/ingredient image. "
        "Do not leave the entire middle-left area visually dead; it must be clean but suitable for benefit/proof overlay. Do not push all objects to the far-right edge. Keep the hero hair/person around the center-right and product/ingredient around lower-right or lower-center-right with breathing room.\n"
    )
    source_focus_visual_rule = (
        "SOURCE-FOCUSED VISUAL RULE: preserve the source banner's key person/hair result and emotional promise. "
        "If the source promise is a lively natural brown color result, show healthy natural brown hair as the visual anchor. "
        "Do not turn the scene into a green paste application process unless the original analyzed image already shows paste on hair. "
        "For henna/natural dye products, ingredient powder/paste can appear as small supporting props only, not as the main hair state.\n"
    )
    similar_focus_visual_rule = (
        "For henna/natural dye products, show the applied result realistically: green henna paste visibly coating the hair, moist herbal texture, smooth application direction, and plant-based powder/paste cues. This should look like a real product applied to hair, not generic green paint.\n"
    )
    deterministic_product = product_slot_context if isinstance(product_slot_context, dict) else {}
    product_reference_rule = (
        "DETERMINISTIC PRODUCT LAYER CONTRACT: the product/package body will be composited later by the server from the authoritative product source. "
        "Do not draw, preserve, invent, duplicate, label, relabel, or render any final product package/body in the OpenAI base scene. "
        f"Leave the designated {str(deterministic_product.get('placementIntent') or 'LOWER_RIGHT')} product area clean and visually plausible for a later packshot composite. "
        "The reserved area may contain simple background, surface, lighting, and natural negative space, but must not contain package silhouettes, label-like artifacts, ghost products, product cards, bottles, boxes, pouches, or product text. "
        "Use product_context only for category mood, usage context, material cues, and compatible scene styling; product pixels and product placement authority belong to the deterministic server layer.\n"
        if deterministic_product
        else (
            "Use `product_context.content_center_generation_context` as a hard contract. The uploaded product/package reference must remain the product identity source. Do not invent a different package, label, bottle, box, pouch, or brand visual. "
            "If a content_center_product_image is provided, the product/package must keep its original aspect ratio and proportions. Never stretch, squash, widen, narrow, rotate, or perspective-warp the product package. Treat the uploaded product image as the product identity reference, not as an extra pasted card. Show only one product/package representation in the final scene. Do not duplicate the product, do not insert a separate white-background product card, and do not place both a generated package and a pasted package together. "
            "Outside the product/package itself, refine the source banner with only minimal supporting visual improvements from detail-page and reference-media analysis: cleaner product usage cue, safer result atmosphere, powder or ingredient texture, paste/formula color, and natural props. Do not replace the original banner's scene with a reference-media scene.\n"
        )
    )
    return (
        ("Improve the first provided source banner image for Naver GFA. Do not create a totally different banner.\n" if edit_source_banner else "Create a high-converting Korean display ad banner image for Naver GFA.\n")
        + ("Keep the source banner's core product/person/usage scene and overall category recognition, but do not copy it pixel-for-pixel. The output must be a visibly improved revision of the analyzed banner: fix the design, layout, visual hierarchy, readability, policy-risk composition, product salience, clutter, lighting, and commercial polish according to analysis_regeneration_contract.priority_changes. Do not replace it with an unrelated model, unrelated background, different product, or different ad concept.\n" if edit_source_banner else "")
        + f"Generation focus selected by user: {generation_focus}. "
        + ("Prioritize the analyzed source banner as the visual base. Similar creatives and reference media are secondary hints only.\n" if generation_focus == "source_image_focus" else "Prioritize similar/reference creative direction more strongly for scene, props, texture, and composition variation, while still obeying the analysis correction contract and product/copy identity.\n")
        + "Use the provided performance-derived creative brief only. Make it commercially polished, realistic, and conversion-focused.\n"
        + f"Selected ad placement: {ad_media_spec.get('media_label') or 'Naver GFA'} / {ad_media_spec.get('placement_label') or 'Feed'}. "
        f"Required image format: {ad_media_spec.get('display_size') or '1:1 square'}, aspect ratio {ad_media_spec.get('aspect_ratio') or '1:1'}. "
        "The composition, safe zone, object scale, and text overlay area must fit this exact placement.\n"
        "Copy is the primary success driver: treat the headline/subcopy as 80% of the creative strategy. The image, objects, and background are supporting evidence for that copy, not the main message.\n"
        "Every object must help explain the copy's emotional problem and purchase reason. Do not use visuals that contradict the copy. If the copy is about a daughter's/mother's gray-hair worry and gentle care, avoid generic chemical hair-dye imagery and instead support gentle/natural henna care, gray hair concern, family care, and plant-based ingredient trust.\n"
        + ("Layout must follow the analyzed source banner structure first; template rules are secondary correction aids.\n" if generation_focus == "source_image_focus" else "Layout must follow the selected template as the highest-priority constraint. Do not switch to another structure.\n")
        + (source_focus_layout_rule if generation_focus == "source_image_focus" else similar_focus_layout_rule)
        + "Apply the supplemental banner guide for Naver GFA only: one banner must communicate one SMP/core USP, the final server-side copy must fit headline 12-16 Korean chars, subcopy 20-28 Korean chars, and CTA 4-8 Korean chars. "
        "The image composition must support the funnel stage: awareness favors stronger visual hook and lighter text space, consideration balances visual proof and text space, conversion reserves clearer benefit/CTA zones. "
        "The first 1.5 seconds must read as Visual Anchor -> Primary Hook safe area -> CTA safe area -> Brand Trust. Keep all important objects inside a 5-8% outer safe zone and reserve clean contrast for WCAG-like readable overlays.\n"
        "Avoid collage, multi-panel layouts, diagonal split screens, multiple frames, dense decorations, or divided sections. The message must not compete with the image, but the composition must feel balanced across the full canvas.\n"
        + ("Use banner guide layout metrics only to repair readability and safe zones; do not override the source banner's core composition.\n" if generation_focus == "source_image_focus" else "The banner guide layout metrics are mandatory: top-left is Hook, middle-left is Message/Benefit/Proof, bottom-left is CTA. The middle-left must not become a large unused blank rectangle.\nRespect object position ratios from guide_layout_metrics: hero object should live around x=50-78%, product/ingredient around x=70-92%, and no object should be clipped or pushed against the far-right edge.\n")
        + "Follow visual_strategy and creative_prompt as the compact commercial generation plan. The intended gaze path, visual weight, color psychology, CTA destination, and copy-image alignment target are mandatory.\n"
        "If visual_hierarchy_path says face -> headline -> benefit -> CTA, make the face/hero hair scene the first visual stop while preserving the left text column for server-side typography.\n"
        "If color_psychology contains green/natural/safety, use a natural green support palette; if premium/black, use restrained premium contrast. Do not choose colors that conflict with the copy's trust trigger.\n"
        + (source_focus_visual_rule if generation_focus == "source_image_focus" else similar_focus_visual_rule)
        + "Keep every important object fully inside the canvas safe area. The main hair/head subject must fit within the right zone with visible margins; do not crop off the head, hair, bowl, product pack, or CTA-safe bottom area. "
        "Use medium shot/product-ad framing, not extreme close-up. Leave at least 6% outer padding around the right-side subject and keep the left copy column clean but not treated as one large empty box.\n"
        "Create only the photographic/product background and natural empty areas for later server-side typography.\n"
        "Do not invent unsupported numerical claims, certifications, medical claims, or review counts.\n"
        "IMPORTANT HARD BAN: Do not render Korean text, English text, letters, labels, UI words, fake typography, icons, checklists, leaf bullet lists, frames, speech bubbles, text boxes, CTA buttons, button shapes, or app-like UI elements. "
        "Do not preserve or recreate any text/button areas from reference images. Leave those areas as simple clean background only; final Korean copy and the only CTA button will be overlaid by the server after image generation.\n"
        "Apply the candidate-specific combination strategy exactly so each candidate is visually distinct.\n"
        "The fields `selected_template_must_follow`, `selected_template_structure`, and `visual_combination.composition` are mandatory layout constraints.\n"
        "If `product_context.reference_media_context` exists, use it only as secondary text context for material cues, props, texture, and safe product usage ideas. In source-banner revision mode, never use reference media or similar historical creatives as the new visual layout, model, scene, package arrangement, or copy target. If they conflict with the source banner or analysis_regeneration_contract.priority_changes, ignore them.\n"
        + product_reference_rule
        + ("Use `product_context` to preserve product-specific visual meaning. For henna/natural dye products, natural brown hair result, herbal powder props, and plant-based trust cues are important. Keep green paste as a small ingredient cue only when it already fits the source banner's promise.\n" if generation_focus == "source_image_focus" else "Use `product_context` to preserve product-specific visual meaning. For henna/natural dye products, green paste, herbal powder texture, and application scenes are important ingredient trust and curiosity cues.\n")
        + f"Reference image count: {len(image_refs)}. Follow additional_references.usage_rule exactly. "
        "If the first reference image is the analyzed source banner, treat it as the visual base to revise, not as a loose mood board and not as an exact copy target. Preserve its product/person/usage context while visibly correcting the specific design, layout, readability, product-placement, and policy problems found by the analysis. The correction list is stronger than any similar-creative or reference-media cue. "
        "If a content_center_product_image is provided after the source banner, preserve the product/package identity from that image and do not invent a new product package. "
        "Use all reference images only for product/brand/style cues, not for unsupported claims.\n"
        f"Headline text for later overlay only, DO NOT render it in the image: {copy_result.get('headline') or ''}\n"
        f"CTA text for later overlay only, DO NOT render it in the image: {copy_result.get('cta') or ''}\n"
        f"Candidate combination strategy JSON:\n{_gfa_generator_json_dumps(combination)}\n"
        f"Compact visual brief JSON:\n{_gfa_generator_json_dumps(image_brief)}"
    )


def _gfa_generator_parse_openai_json(resp_json: dict) -> dict:
    content = ""
    try:
        choices = resp_json.get("choices") or []
        if choices:
            message = (choices[0] or {}).get("message") or {}
            raw_content = message.get("content")
            if isinstance(raw_content, list):
                parts = []
                for part in raw_content:
                    if isinstance(part, dict):
                        parts.append(str(part.get("text") or part.get("content") or ""))
                    else:
                        parts.append(str(part or ""))
                content = "\n".join(x for x in parts if x)
            else:
                content = str(raw_content or "")
        if not content and isinstance(resp_json.get("output_text"), str):
            content = str(resp_json.get("output_text") or "")
        if not content and isinstance(resp_json.get("content"), str):
            content = str(resp_json.get("content") or "")
        if not content and isinstance(resp_json.get("message"), dict):
            content = str((resp_json.get("message") or {}).get("content") or "")
        if not content and isinstance(resp_json.get("output"), list):
            parts = []
            for item in resp_json.get("output") or []:
                if not isinstance(item, dict):
                    continue
                for part in item.get("content") or []:
                    if isinstance(part, dict):
                        parts.append(str(part.get("text") or part.get("content") or ""))
            content = "\n".join(x for x in parts if x)
    except Exception:
        content = ""
    content = content.strip()
    if content.startswith("```"):
        content = re.sub(r"^```(?:json)?\s*", "", content)
        content = re.sub(r"\s*```$", "", content)
    if "{" in content and "}" in content:
        content = content[content.find("{") : content.rfind("}") + 1]
    try:
        obj = json.loads(content)
        return obj if isinstance(obj, dict) else {"raw": content}
    except Exception:
        return {"headline": content[:80], "subcopy": content, "proof_line": "증거 필요", "cta": "자세히 보기", "variants": [], "landing_message": "", "risk_notes": ["json_parse_failed"]}


def _gfa_generator_fallback_copy_result(brief: dict, parsed: dict | None = None) -> dict:
    parsed = parsed if isinstance(parsed, dict) else {}
    image_elements = str(brief.get("image_elements") or "")
    copy_elements = str(brief.get("copy_elements") or "")
    source_copy = brief.get("source_copy_verbatim") if isinstance(brief.get("source_copy_verbatim"), dict) else {}
    product_context = brief.get("product_context") if isinstance(brief.get("product_context"), dict) else {}
    traits = product_context.get("inferred_product_traits") if isinstance(product_context.get("inferred_product_traits"), list) else []
    keywords = product_context.get("purchase_keywords") if isinstance(product_context.get("purchase_keywords"), list) else []
    keyword_text = " ".join(str(x.get("keyword") or x) for x in keywords[:3] if x)
    source_live_copy = str(source_copy.get("live_copy") or "")
    source_text = " ".join([image_elements, copy_elements, source_live_copy, " ".join(str(x) for x in traits), keyword_text])
    generation_focus = str(brief.get("generation_focus") or "source_image_focus")
    parsed_risk_notes = parsed.get("risk_notes") if isinstance(parsed.get("risk_notes"), list) else []
    ignore_parsed_copy = "json_parse_failed" in parsed_risk_notes

    is_henna = any(token in source_text for token in ["헤나", "천연", "유기농", "비건", "초록", "반죽"])
    has_gray = any(token in source_text for token in ["새치", "흰머리", "백발"])
    has_mom = "엄마" in source_text
    source_focus = generation_focus == "source_image_focus"
    has_brown_color_promise = source_focus and any(token in source_text for token in ["브라운", "갈색", "자연스러운 컬러", "생기 있는", "새카만"])
    expression_style = str(source_copy.get("expression_style") or "")
    is_self_talk_source = "독백형" in expression_style or "속마음" in expression_style
    headline = "" if ignore_parsed_copy else _collapse_ws_text(parsed.get("headline"))
    subcopy = "" if ignore_parsed_copy else _collapse_ws_text(parsed.get("subcopy"))
    proof_line = "" if ignore_parsed_copy else _collapse_ws_text(parsed.get("proof_line"))
    cta = "" if ignore_parsed_copy else _collapse_ws_text(parsed.get("cta"))

    if not headline:
        if has_brown_color_promise:
            headline = "새카만 새치 말고\n브라운 컬러"
        elif has_mom and has_gray and is_self_talk_source:
            headline = "엄마 새치, 집에서 순하게"
        elif has_mom and has_gray:
            headline = "엄마 새치, 집에서 순하게"
        elif is_henna and has_gray:
            headline = "새치 걱정, 집에서 순하게"
        elif has_gray:
            headline = "새치 고민, 오늘 덜기"
        elif is_henna:
            headline = "헤나 관리, 집에서 쉽게"
        else:
            headline = "오늘 필요한 관리 시작"
    command_markers = ["하세요", "마세요", "구매하세요", "시작하세요", "보세요", "줄이세요", "덜어내세요"]
    if has_mom and has_gray and is_self_talk_source and (
        not ("엄마" in headline and any(x in headline for x in ["새치", "흰머리", "걱정", "어떡"]))
        or any(x in headline for x in command_markers)
    ):
        headline = "엄마 새치, 집에서 순하게"
    if has_brown_color_promise and not any(x in headline for x in ["브라운", "컬러", "새카만", "생기"]):
        headline = "새카만 새치 말고\n브라운 컬러"
    if not subcopy:
        if has_brown_color_promise:
            subcopy = "생기 있는 브라운 컬러로 자연스럽게"
        elif has_mom and is_henna:
            subcopy = "식물성 헤나로 집에서 부담 없이 새치 걱정 덜어요"
        elif is_henna:
            subcopy = "식물성 헤나로 집에서 부담 없이 새치 걱정 덜어요"
        else:
            subcopy = "필요한 순간 집에서 부담 없이 쉽게 시작해요"
    weak_subcopy_markers = ["원료감으로", "첫인상을", "확인하세요", "자세히"]
    if has_mom and has_gray and (
        not any(x in subcopy for x in ["걱정", "부담", "순한", "관리", "덜"])
        or any(x in subcopy for x in [*weak_subcopy_markers, *command_markers])
    ):
        subcopy = "식물성 헤나로 집에서 부담 없이 새치 걱정 덜어요"
    if has_brown_color_promise and not any(x in subcopy for x in ["브라운", "컬러", "생기", "자연"]):
        subcopy = "생기 있는 브라운 컬러로 자연스럽게"
    if not proof_line or proof_line in {"증거 필요", "근거 필요"}:
        if has_brown_color_promise:
            proof_line = "자연스러운 브라운"
        elif is_henna:
            proof_line = "식물성 헤나 원료"
        else:
            proof_line = "부담 낮춘 선택"
    weak_ctas = {"자세히 보기", "확인하기", "보러가기", "더 알아보기", "구매하기"}
    if not cta or cta in weak_ctas:
        if has_brown_color_promise:
            cta = "브라운 보기"
        elif has_mom and has_gray:
            cta = "새치 케어 보기"
        elif is_henna and has_gray:
            cta = "새치 케어 보기"
        elif has_gray:
            cta = "새치 케어 보기"
        elif is_henna:
            cta = "헤나 케어 보기"
        else:
            cta = "관리 시작하기"
    if has_mom and has_gray and not any(x in cta for x in ["엄마", "새치", "케어", "걱정"]):
        cta = "새치 케어 보기"

    risk_notes = parsed_risk_notes
    if parsed.get("risk_notes") and "fallback_copy_used" not in risk_notes:
        risk_notes = [*risk_notes, "fallback_copy_used"]
    elif not parsed.get("risk_notes"):
        risk_notes = []
    return {
        **parsed,
        "headline": headline,
        "subcopy": subcopy,
        "proof_line": proof_line,
        "cta": cta,
        "variants": parsed.get("variants") if isinstance(parsed.get("variants"), list) else [],
        "landing_message": _collapse_ws_text(parsed.get("landing_message")),
        "risk_notes": risk_notes,
    }


def _gfa_manual_copy_text(value: object, *, max_lines: int = 2) -> str:
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    lines = [_collapse_ws_text(line) for line in text.split("\n")]
    lines = [line for line in lines if line]
    return "\n".join(lines[:max_lines])


def _gfa_generator_validate_copy_against_brief(brief: dict, copy_result: dict) -> tuple[dict, dict]:
    out = copy.deepcopy(copy_result if isinstance(copy_result, dict) else {})
    cb = brief.get("creative_copy_brief") if isinstance(brief.get("creative_copy_brief"), dict) else {}
    decisions = cb.get("message_decisions") if isinstance(cb.get("message_decisions"), dict) else {}
    rules = cb.get("copy_rules") if isinstance(cb.get("copy_rules"), dict) else {}
    headline_rule = rules.get("headline") if isinstance(rules.get("headline"), dict) else {}
    subcopy_rule = rules.get("subcopy") if isinstance(rules.get("subcopy"), dict) else {}
    proof_rule = rules.get("proof_line") if isinstance(rules.get("proof_line"), dict) else {}
    cta_rule = rules.get("cta") if isinstance(rules.get("cta"), dict) else {}

    headline = _collapse_ws_text(out.get("headline"))
    subcopy = _collapse_ws_text(out.get("subcopy"))
    proof_line = _collapse_ws_text(out.get("proof_line"))
    cta = _collapse_ws_text(out.get("cta"))
    issues: list[str] = []
    rewrites: list[str] = []

    def compact_len(text: str) -> int:
        return len(re.sub(r"\s+", "", str(text or "")))

    def display_len(text: str) -> int:
        return len(_collapse_ws_text(text).replace("\n", ""))

    must_include = [str(x) for x in (headline_rule.get("must_include") if isinstance(headline_rule.get("must_include"), list) else []) if str(x).strip()]
    must_not_include = [str(x) for x in (headline_rule.get("must_not_include") if isinstance(headline_rule.get("must_not_include"), list) else []) if str(x).strip()]
    forbidden_claims = [str(x) for x in (decisions.get("forbidden_claims") if isinstance(decisions.get("forbidden_claims"), list) else []) if str(x).strip()]
    primary_benefit = _collapse_ws_text(decisions.get("primary_benefit"))
    primary_usp = _collapse_ws_text(decisions.get("primary_usp"))
    evidence = _collapse_ws_text(decisions.get("evidence"))
    is_mom_gray = "엄마" in must_include and "새치" in must_include
    brief_text = _gfa_generator_json_dumps(brief)
    generation_focus = str(brief.get("generation_focus") or "source_image_focus")
    source_focus = generation_focus == "source_image_focus"
    source_copy = brief.get("source_copy_verbatim") if isinstance(brief.get("source_copy_verbatim"), dict) else {}
    source_live_copy = str(source_copy.get("live_copy") or "")
    has_brown_color_promise = source_focus and any(token in f"{brief_text} {source_live_copy}" for token in ["브라운", "갈색", "자연스러운 컬러", "생기 있는", "새카만"])
    is_henna_context = any(token in brief_text for token in ["헤나", "천연", "식물", "초록", "반죽", "유기농", "비건"])
    has_gray_context = "새치" in brief_text or "흰머리" in brief_text
    has_mom_context = "엄마" in brief_text or "어머니" in brief_text

    def customer_copy_replacement(field: str) -> str:
        if field == "headline":
            if has_brown_color_promise:
                return "새카만 새치 말고\n브라운 컬러"
            if is_mom_gray or (has_mom_context and has_gray_context):
                return "엄마 새치, 집에서 순하게"
            if has_gray_context:
                return "새치 걱정, 집에서 순하게"
            if is_henna_context:
                return "헤나 관리, 집에서 쉽게"
            return "오늘 필요한 관리 시작"
        if field == "subcopy":
            if has_brown_color_promise:
                return "생기 있는 브라운 컬러로 자연스럽게"
            if is_mom_gray or is_henna_context or has_gray_context:
                return "식물성 헤나로 집에서 부담 없이 새치 걱정 덜어요"
            return "필요한 순간 집에서 부담 없이 쉽게 시작해요"
        if field == "proof_line":
            if has_brown_color_promise:
                return "자연스러운 브라운"
            if is_henna_context:
                return "원료부터 순하게"
            return "부담 낮춘 선택"
        if field == "cta":
            if has_brown_color_promise:
                return "브라운 보기"
            if is_mom_gray:
                return "새치 케어 보기"
            if has_gray_context:
                return "새치 케어 보기"
            if is_henna_context:
                return "헤나 케어 보기"
            return "관리 시작하기"
        return ""

    def is_internal_or_bad_customer_copy(text: str) -> bool:
        if not text:
            return True
        internal_markers = [
            "가이드", "프롬프트", "브리프", "contract", "reference", "OpenCV", "AI ", "분석", "반영",
            "소재", "키워드", "신호", "텍스트", "레이아웃", "오버레이", "생성", "후보", "원료감",
        ]
        if any(marker in text for marker in internal_markers):
            return True
        if "�" in text or "i??" in text or "e??" in text:
            return True
        if text.count("·") >= 2 or text.count("/") >= 2:
            return True
        return False

    def has_unsupported_overlay_claim(text: str) -> bool:
        if not text:
            return False
        claim_markers = [
            "%", "0%", "100%", "무첨가", "무자극", "저자극", "화학 성분", "화학성분",
            "인증", "1위", "최고", "완치", "치료", "탈모", "염증", "부작용 없음",
        ]
        if any(marker in text for marker in claim_markers):
            return True
        return bool(re.search(r"\d+\s*(?:%|배|명|건|위|일|시간)", text))

    def is_bad_cta_text(text: str) -> bool:
        compact = re.sub(r"\s+", "", str(text or ""))
        if not compact:
            return True
        bad_cta_markers = ["보러가기", "구매하기", "자세히", "확인", "순해", "반영", "분석", "가이드"]
        if any(marker in text or marker in compact for marker in bad_cta_markers):
            return True
        return not any(compact.endswith(suffix) for suffix in ["보기", "시작하기", "받기", "상담하기"])

    def semantic_line_break(text: str, *, max_lines: int, min_chars: int) -> str:
        raw = _collapse_ws_text(text)
        if "\n" in str(text or "") or compact_len(raw) < min_chars or " " not in raw:
            return raw
        words = raw.split()
        if len(words) < 2:
            return raw
        target = len(raw) / 2
        best_idx = min(range(1, len(words)), key=lambda i: abs(len(" ".join(words[:i])) - target))
        lines = [" ".join(words[:best_idx]), " ".join(words[best_idx:])]
        lines = [line for line in lines if line][:max_lines]
        return "\n".join(lines) if len(lines) > 1 else raw

    if any(x and x not in headline for x in must_include) or any(x and x in headline for x in must_not_include) or has_unsupported_overlay_claim(headline):
        issues.append("headline_not_aligned_with_brief")
        if is_mom_gray:
            headline = "우리 엄마 새치 어떡하지?"
        elif "새치" in must_include:
            headline = "순한 새치 케어"
        else:
            headline = customer_copy_replacement("headline")
        rewrites.append("headline")
    hard_headline = int(headline_rule.get("hard_max_chars") or 16)
    headline_too_short_or_label = display_len(headline) < 12 or bool(re.fullmatch(r".{0,8}(케어|관리|헤나|새치)\s*", headline))
    visual_headline_too_long = display_len(headline) > hard_headline or (headline.count(" ") >= 3 and display_len(headline) > 16)
    if visual_headline_too_long or headline_too_short_or_label:
        issues.append("headline_not_hook_or_bad_length")
        headline = customer_copy_replacement("headline")
        rewrites.append("headline")

    weak_or_bad_subcopy = (
        not subcopy
        or any(x in subcopy for x in ["키워드", "검색 우위", "기반", "구매 키워드"])
        or any(x in subcopy for x in ["·", "/", ","]) and compact_len(subcopy) > 18
        or has_unsupported_overlay_claim(subcopy)
        or not re.search(r"(요|다|니다|세요)$", subcopy)
    )
    hard_subcopy = int(subcopy_rule.get("hard_max_chars") or 28)
    if weak_or_bad_subcopy or display_len(subcopy) < 20 or display_len(subcopy) > hard_subcopy:
        issues.append("subcopy_not_benefit_or_too_long")
        if is_mom_gray:
            subcopy = "식물성 헤나로 집에서 부담 없이 새치 걱정 덜어요"
        elif primary_benefit and 20 <= display_len(primary_benefit) <= hard_subcopy and re.search(r"(요|다|니다|세요)$", primary_benefit) and not is_internal_or_bad_customer_copy(primary_benefit):
            subcopy = primary_benefit[:hard_subcopy]
        else:
            subcopy = customer_copy_replacement("subcopy")
        rewrites.append("subcopy")

    hard_proof = int(proof_rule.get("hard_max_chars") or 24)
    if not proof_line or compact_len(proof_line) > hard_proof or "성과 분석" in proof_line or has_unsupported_overlay_claim(proof_line):
        issues.append("proof_line_not_customer_facing")
        if evidence and not evidence.startswith("근거 없는") and not has_unsupported_overlay_claim(evidence):
            proof_line = evidence[:hard_proof]
        elif primary_usp and primary_usp != "제품 차별점 1개" and not has_unsupported_overlay_claim(primary_usp):
            proof_line = primary_usp[:hard_proof]
        else:
            proof_line = customer_copy_replacement("proof_line")
        rewrites.append("proof_line")

    hard_cta = int(cta_rule.get("hard_max_chars") or 8)
    weak_ctas = {"자세히 보기", "확인하기", "보러가기", "더 알아보기", "구매하기", "지금 구매하기"}
    if not cta or cta in weak_ctas or compact_len(cta) > hard_cta or is_bad_cta_text(cta):
        issues.append("cta_not_short_action")
        cta = customer_copy_replacement("cta")
        rewrites.append("cta")

    field_values = {
        "headline": headline,
        "subcopy": subcopy,
        "proof_line": proof_line,
        "cta": cta,
    }
    if has_brown_color_promise and not any(token in " ".join(field_values.values()) for token in ["브라운", "컬러", "생기", "새카만"]):
        issues.append("source_color_promise_missing")
        headline = customer_copy_replacement("headline")
        subcopy = customer_copy_replacement("subcopy")
        proof_line = customer_copy_replacement("proof_line")
        cta = customer_copy_replacement("cta")
        rewrites.extend(["headline", "subcopy", "proof_line", "cta"])
        field_values = {
            "headline": headline,
            "subcopy": subcopy,
            "proof_line": proof_line,
            "cta": cta,
        }
    for field, value in list(field_values.items()):
        if is_internal_or_bad_customer_copy(value) or has_unsupported_overlay_claim(value) or (field == "cta" and is_bad_cta_text(value)):
            issues.append(f"{field}_not_customer_copy")
            replacement = customer_copy_replacement(field)
            if field == "headline":
                headline = replacement
            elif field == "subcopy":
                subcopy = replacement
            elif field == "proof_line":
                proof_line = replacement
            elif field == "cta":
                cta = replacement
            rewrites.append(field)

    for bad in [*must_not_include, *forbidden_claims]:
        if bad and any(bad in text for text in [headline, subcopy, proof_line, cta]):
            issues.append(f"forbidden_phrase:{bad}")

    headline = semantic_line_break(headline, max_lines=2, min_chars=9)
    subcopy = semantic_line_break(subcopy, max_lines=2, min_chars=16)

    out["headline"] = headline
    out["subcopy"] = subcopy
    out["proof_line"] = proof_line
    out["cta"] = cta
    risk_notes = out.get("risk_notes") if isinstance(out.get("risk_notes"), list) else []
    if issues and "copy_validation_rewrite_used" not in risk_notes:
        risk_notes = [*risk_notes, "copy_validation_rewrite_used"]
    out["risk_notes"] = risk_notes
    validation = {
        "status": "pass" if not issues else "rewritten",
        "issues": issues,
        "rewritten_fields": sorted(set(rewrites)),
        "checked_against": {
            "primary_emotion": decisions.get("primary_emotion"),
            "primary_benefit": decisions.get("primary_benefit"),
            "primary_usp": decisions.get("primary_usp"),
            "evidence": decisions.get("evidence"),
            "headline_rule": headline_rule,
            "subcopy_rule": subcopy_rule,
            "cta_rule": cta_rule,
        },
    }
    out["copy_validation"] = validation
    return out, validation


def _gfa_generator_generate_copy(*, brief: dict, model: str | None = None) -> tuple[dict, str, str]:
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise RuntimeError("OPENAI_API_KEY not configured")
    model_name = str(model or os.getenv("GFA_CREATIVE_COPY_MODEL") or GFA_CREATIVE_COPY_DEFAULT_MODEL).strip()
    prompt = _gfa_generator_copy_prompt(brief)
    payload = _build_openai_chat_payload(
        model_name=model_name,
        messages=[
            {"role": "system", "content": "Return only valid JSON. You write Korean performance marketing banner copy."},
            {"role": "user", "content": prompt},
        ],
        temperature=0.2,
        max_output_tokens=900,
    )
    payload["response_format"] = {"type": "json_object"}
    resp = _post_openai_chat_completion_compatible(api_key=key, payload=payload, timeout=45)
    if resp.status_code != 200:
        raise RuntimeError(f"openai_copy_error:{resp.status_code}:{_safe_err_text(resp, 800)}")
    parsed = _gfa_generator_parse_openai_json(resp.json() or {})
    copy_result = _gfa_generator_fallback_copy_result(brief, parsed)
    copy_result, _validation = _gfa_generator_validate_copy_against_brief(brief, copy_result)
    overlay_layout, overlay_plan = _gfa_generator_guided_overlay_layout(brief, copy_result)
    copy_result["overlay_layout"] = overlay_layout
    copy_result["overlay_design_plan"] = overlay_plan
    return copy_result, prompt, model_name


def _gfa_generator_user_error(exc: Exception) -> str:
    raw = str(exc or "").strip()
    low = raw.lower()
    if "openai_api_key not configured" in low:
        return "OpenAI API 키가 설정되지 않았습니다. 설정 > API 세팅에서 OpenAI 키를 저장한 뒤 다시 생성하세요."
    if "gemini_api_key not configured" in low:
        return "Gemini API 키가 설정되지 않았습니다. 설정 > API 세팅에서 Gemini 키를 저장한 뒤 다시 생성하세요."
    if "openai_copy_error" in low:
        model_match = re.search(r"model\s+['\"]?([A-Za-z0-9_.:-]+)['\"]?", raw)
        model_hint = f" (모델: {model_match.group(1)})" if model_match else ""
        if "model_not_found" in low or "does not have access to model" in low:
            return f"OpenAI 카피 생성 모델 접근 권한이 없습니다{model_hint}. OpenAI 프로젝트의 모델 권한을 확인하거나 GFA_CREATIVE_COPY_MODEL을 접근 가능한 모델로 지정하세요."
        if "insufficient_quota" in low or "quota" in low:
            return "OpenAI API 할당량 또는 결제 한도 문제로 카피 생성에 실패했습니다. OpenAI 계정의 quota/billing 상태를 확인하세요."
        return "OpenAI 카피 생성 요청에 실패했습니다. API 키, 모델 권한, 계정 할당량을 확인하세요."
    if "openai_image_error" in low:
        if "duplicate parameter" in low or "duplicate_parameter" in low:
            return "OpenAI 이미지 생성 요청 형식이 잘못되었습니다. 참조 이미지 전달 방식을 확인하세요."
        if "model_not_found" in low or "does not have access to model" in low:
            return "OpenAI 이미지 생성 모델 접근 권한이 없습니다. OpenAI 프로젝트의 GPT 이미지 모델 권한을 확인하세요."
        if "insufficient_quota" in low or "quota" in low:
            return "OpenAI API 할당량 또는 결제 한도 문제로 이미지 생성에 실패했습니다. OpenAI 계정의 quota/billing 상태를 확인하세요."
        if "invalid" in low:
            return "OpenAI 이미지 생성 요청 형식이 올바르지 않습니다. 이미지 크기, 참조 이미지, 프롬프트 파라미터를 확인하세요."
        return "OpenAI 이미지 생성 요청에 실패했습니다. API 키, 이미지 모델 권한, 계정 할당량을 확인하세요."
    if "product_authority_unavailable" in low:
        return "제품 원본 이미지를 찾을 수 없어 선택한 제품을 키우거나 옮길 수 없습니다."
    if "image_overlay_error" in low:
        return "이미지는 생성됐지만 한글 문구 합성에 실패했습니다. 서버의 Pillow/한글 폰트 설정을 확인하세요."
    if "base_image_missing_for_locked_copy_overlay" in low:
        return "이미지 고정에 사용할 원본 배경 이미지가 없습니다. 이 옵션은 원본/텍스트 레이어 분리 저장 이후 생성된 시안에서 사용할 수 있습니다. 먼저 이미지 고정 해제 상태로 한 번 재생성한 뒤 다시 카피만 수정하세요."
    if "gemini_image_error" in low:
        if "permission" in low or "not found" in low or "access" in low or "invalid" in low:
            return "Gemini 이미지 생성 모델 접근 권한이 없습니다. Gemini API 키와 이미지 생성 모델 권한을 확인하세요."
        return "Gemini 이미지 생성 요청에 실패했습니다. API 키, 모델 권한, 계정 할당량을 확인하세요."
    return raw[:500] or "소재 생성에 실패했습니다."


def _gfa_generated_image_dir() -> str:
    base = os.getenv("GFA_GENERATED_IMAGE_DIR") or "/data/gfa_generated_creatives"
    os.makedirs(base, exist_ok=True)
    return base


def _gfa_generator_extract_gemini_image(body: dict) -> tuple[bytes, str]:
    def walk(v):
        if isinstance(v, dict):
            data = v.get("data")
            mime = v.get("mimeType") or v.get("mime_type") or v.get("mime")
            if data and mime and str(mime).startswith("image/"):
                return str(data), str(mime)
            for key in ("inlineData", "inline_data", "blob"):
                if isinstance(v.get(key), dict):
                    found = walk(v.get(key))
                    if found:
                        return found
            for x in v.values():
                found = walk(x)
                if found:
                    return found
        if isinstance(v, list):
            for x in v:
                found = walk(x)
                if found:
                    return found
        return None

    found = walk(body)
    if not found:
        raise RuntimeError("gemini_image_error:no_image_data")
    data_b64, mime = found
    return base64.b64decode(data_b64), mime


def _gfa_generator_extract_openai_image(body: dict) -> tuple[bytes, str]:
    data = body.get("data") if isinstance(body, dict) else None
    if not isinstance(data, list) or not data:
        raise RuntimeError("openai_image_error:no_image_data")
    first = data[0] if isinstance(data[0], dict) else {}
    b64 = str(first.get("b64_json") or first.get("b64") or "")
    if b64:
        return base64.b64decode(b64), "image/png"
    url = str(first.get("url") or "")
    if url:
        resp = requests.get(url, timeout=45)
        if int(resp.status_code) != 200:
            raise RuntimeError(f"openai_image_error:download_failed:{resp.status_code}:{_safe_err_text(resp, 500)}")
        mime = str(resp.headers.get("content-type") or "image/png").split(";")[0].strip() or "image/png"
        return resp.content, mime
    raise RuntimeError("openai_image_error:no_image_data")


def _gfa_generator_font_dirs() -> list[str]:
    raw_dirs = [
        os.getenv("GFA_WINDOWS_FONT_DIR") or "",
        "/host_windows_fonts",
        "C:/Windows/Fonts",
        "C:\\Windows\\Fonts",
        "/usr/share/fonts/opentype/noto",
        "/usr/share/fonts/truetype/noto",
        "/usr/share/fonts/truetype/dejavu",
    ]
    out: list[str] = []
    for raw in raw_dirs:
        path = str(raw or "").strip()
        if path and path not in out and os.path.isdir(path):
            out.append(path)
    return out


def _gfa_generator_font_catalog(limit: int = 300) -> list[dict]:
    fonts: list[dict] = []
    seen: set[str] = set()

    def font_names(path: str, fallback: str) -> tuple[str, str]:
        try:
            from PIL import ImageFont
            font = ImageFont.truetype(path, size=20)
            family, style = font.getname()
            family = str(family or "").strip()
            style = str(style or "").strip()
            return family or fallback, style
        except Exception:
            return fallback, ""

    for root_dir in _gfa_generator_font_dirs():
        for root, _dirs, files in os.walk(root_dir):
            for name in files:
                low = name.lower()
                if not low.endswith((".ttf", ".ttc", ".otf")):
                    continue
                key = name.lower()
                if key in seen:
                    continue
                seen.add(key)
                path = os.path.join(root, name)
                stem = os.path.splitext(name)[0]
                family, style = font_names(path, stem)
                label = family if not style or style.lower() in {"regular", "normal"} else f"{family} {style}"
                fonts.append({
                    "id": f"winfont:{name}" if root_dir in {"/host_windows_fonts", "C:/Windows/Fonts", "C:\\Windows\\Fonts"} else f"fontfile:{name}",
                    "label": label,
                    "filename": name,
                    "family": family,
                    "style": style,
                    "source": "windows" if root_dir in {"/host_windows_fonts", "C:/Windows/Fonts", "C:\\Windows\\Fonts"} else "container",
                })
                if len(fonts) >= limit:
                    return sorted(fonts, key=lambda x: (x.get("source") != "windows", str(x.get("label") or "").lower()))
    return sorted(fonts, key=lambda x: (x.get("source") != "windows", str(x.get("label") or "").lower()))


def _gfa_generator_font_by_id(font_id: str) -> str | None:
    raw = str(font_id or "").strip()
    if not raw.startswith(("winfont:", "fontfile:")):
        return None
    filename = os.path.basename(raw.split(":", 1)[1])
    if not filename.lower().endswith((".ttf", ".ttc", ".otf")):
        return None
    for root_dir in _gfa_generator_font_dirs():
        path = os.path.join(root_dir, filename)
        if os.path.exists(path):
            return path
    return None


def _gfa_generator_font_path(family: str | None = None, weight: str | None = None) -> str | None:
    env_path = str(os.getenv("GFA_CREATIVE_KOREAN_FONT") or "").strip()
    fam = str(family or "noto_sans").strip().lower()
    wt = str(weight or "bold").strip().lower()
    bold = wt != "regular"
    if fam.startswith(("winfont:", "fontfile:")):
        found = _gfa_generator_font_by_id(fam)
        if found:
            return found
    candidates = [env_path]
    if fam == "noto_serif":
        candidates.extend(
            [
                f"/usr/share/fonts/opentype/noto/NotoSerifCJK-{'Bold' if bold else 'Regular'}.ttc",
                f"/usr/share/fonts/truetype/noto/NotoSerifCJK-{'Bold' if bold else 'Regular'}.ttc",
            ]
        )
    candidates.extend(
        [
            f"/usr/share/fonts/opentype/noto/NotoSansCJK-{'Bold' if bold else 'Regular'}.ttc",
            f"/usr/share/fonts/truetype/noto/NotoSansCJK-{'Bold' if bold else 'Regular'}.ttc",
            "/usr/share/fonts/opentype/noto/NotoSansCJK-Bold.ttc",
            "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        ]
    )
    for path in candidates:
        if path and os.path.exists(path):
            return path
    return None


def _gfa_overlay_float(value: object, default: float, low: float, high: float) -> float:
    try:
        out = float(value)
    except Exception:
        out = default
    return max(low, min(high, out))


def _gfa_overlay_text_style(copy_result: dict, key: str, defaults: dict) -> dict:
    layout = copy_result.get("overlay_layout") if isinstance(copy_result.get("overlay_layout"), dict) else {}
    raw = layout.get(key) if isinstance(layout.get(key), dict) else {}
    align = str(raw.get("align") or defaults.get("align") or "left").lower()
    if align not in {"left", "center", "right"}:
        align = "left"
    return {
        "x": _gfa_overlay_float(raw.get("x"), defaults["x"], 0.0, 0.95),
        "y": _gfa_overlay_float(raw.get("y"), defaults["y"], 0.0, 0.95),
        "w": _gfa_overlay_float(raw.get("w"), defaults.get("w", 0.38), 0.15, 0.9),
        "font_scale": _gfa_overlay_float(raw.get("font_scale"), defaults.get("font_scale", 1.0), 0.55, 1.8),
        "font_family": str(raw.get("font_family") or defaults.get("font_family") or "noto_sans"),
        "font_weight": str(raw.get("font_weight") or defaults.get("font_weight") or "bold"),
        "color": str(raw.get("color") or defaults.get("color") or "#1e2b1c"),
        "align": align,
        "opacity": _gfa_overlay_float(raw.get("opacity"), defaults.get("opacity", 1.0), 0.15, 1.0),
        "bg_color": str(raw.get("bg_color") or defaults.get("bg_color") or "#ffffff"),
        "bg_opacity": _gfa_overlay_float(raw.get("bg_opacity"), defaults.get("bg_opacity", 0.0), 0.0, 1.0),
        "line_height": _gfa_overlay_float(raw.get("line_height"), defaults.get("line_height", 1.18), 0.9, 1.8),
        "shadow": bool(raw.get("shadow", defaults.get("shadow", True))),
    }


def _gfa_generator_guided_overlay_layout(brief: dict, copy_result: dict) -> tuple[dict, dict]:
    brief = brief if isinstance(brief, dict) else {}
    copy_result = copy_result if isinstance(copy_result, dict) else {}
    goal = str(brief.get("goal") or "click").strip()
    context_text = _gfa_generator_json_dumps(
        {
            "product_context": brief.get("product_context") if isinstance(brief.get("product_context"), dict) else {},
            "copy": {k: copy_result.get(k) for k in ("headline", "subcopy", "proof_line", "cta")},
        }
    )
    natural = any(token in context_text for token in ["헤나", "천연", "식물", "그린", "초록", "유기농", "비건", "natural", "green"])
    premium = any(token in context_text for token in ["프리미엄", "고급", "premium", "black"])
    conversion = goal in {"purchase", "conversion"}

    palette = {
        "headline": "#142313" if natural else "#111827",
        "subcopy": "#2f3f28" if natural else "#374151",
        "proof": "#5d4b31" if natural else "#4b5563",
        "cta_bg": "#f5700d" if conversion else "#16a34a" if natural else "#2563eb",
        "cta_text": "#ffffff",
    }
    if premium:
        palette.update({"headline": "#111827", "subcopy": "#374151", "proof": "#4b5563", "cta_bg": "#111827"})

    layout = {
        "headline": {"x": 0.055, "y": 0.105, "w": 0.42, "font_scale": 1.04 if conversion else 1.0, "font_family": "noto_sans", "font_weight": "bold", "color": palette["headline"], "align": "left", "opacity": 1.0, "bg_color": "#ffffff", "bg_opacity": 0.0, "line_height": 1.12, "shadow": True},
        "subcopy": {"x": 0.055, "y": 0.335, "w": 0.42, "font_scale": 0.88, "font_family": "noto_sans", "font_weight": "medium", "color": palette["subcopy"], "align": "left", "opacity": 1.0, "bg_color": "#ffffff", "bg_opacity": 0.0, "line_height": 1.45, "shadow": True},
        "proof": {"x": 0.055, "y": 0.505, "w": 0.40, "font_scale": 0.80, "font_family": "noto_sans", "font_weight": "regular", "color": palette["proof"], "align": "left", "opacity": 0.95, "bg_color": "#ffffff", "bg_opacity": 0.0, "line_height": 1.45, "shadow": True},
        "cta": {"x": 0.055, "y": 0.77 if conversion else 0.785, "w": 0.34 if conversion else 0.31, "font_scale": 1.10 if conversion else 1.0, "font_family": "noto_sans", "font_weight": "bold", "color": palette["cta_text"], "align": "center", "opacity": 1.0, "bg_color": palette["cta_bg"], "bg_opacity": 1.0, "line_height": 1.12, "shadow": False},
    }
    plan = {
        "version": "guided-overlay-layout-v1",
        "source": "supplemental_banner_guide + analysis_regeneration_contract",
        "principles": [
            "좌측 38~42% 카피 안전영역",
            "Visual Anchor -> Primary Hook -> CTA -> Brand Trust 1.5초 위계",
            "헤드라인 12~16자, 서브카피 20~28자, CTA 4~8자",
            "헤드라인은 서브카피보다 1.8~2.5배 강하게, 행간은 110~125%로 압축",
            "서브카피는 140~160% 행간으로 읽기 쉽게, CTA는 버튼 배경으로 분리",
            "제품/사용 장면은 우측 시각 영역에 두고 카피와 충돌하지 않게 배치",
            "외곽 5~8% Safe Zone 확보",
        ],
        "goal": goal,
        "palette": palette,
        "manual_edit_supported": ["x", "y", "w", "font_scale", "font_family", "font_weight", "color", "align", "opacity", "bg_color", "bg_opacity", "line_height", "shadow"],
    }
    return layout, plan


def _gfa_overlay_hex_color(value: str, fallback: tuple[int, int, int, int]) -> tuple[int, int, int, int]:
    raw = str(value or "").strip().lstrip("#")
    if len(raw) == 3:
        raw = "".join(ch * 2 for ch in raw)
    if len(raw) != 6:
        return fallback
    try:
        return (int(raw[0:2], 16), int(raw[2:4], 16), int(raw[4:6], 16), 255)
    except Exception:
        return fallback


def _gfa_generator_wrap_text(draw, text: str, font, max_width: int, max_lines: int) -> list[str]:
    raw = str(text or "").replace("\r\n", "\n").replace("\r", "\n")
    if not raw:
        return []
    lines: list[str] = []
    for raw_line in raw.split("\n"):
        if len(lines) >= max_lines:
            break
        paragraph = _collapse_ws_text(raw_line)
        if not paragraph:
            continue
        current = ""
        words = paragraph.split()
        if not words:
            words = [paragraph]
        for word in words:
            candidate = f"{current} {word}".strip() if current else word
            try:
                width = draw.textbbox((0, 0), candidate, font=font)[2]
            except Exception:
                width = len(candidate) * 18
            if width <= max_width or not current:
                current = candidate
                continue
            lines.append(current.strip())
            current = word
            if len(lines) >= max_lines:
                break
        if current and len(lines) < max_lines:
            lines.append(current.strip())
    return lines


def _gfa_generator_overlay_copy_on_image(img_bytes: bytes, *, copy_result: dict, combination: dict | None = None) -> tuple[bytes, str]:
    try:
        from PIL import Image, ImageDraw, ImageFont
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_overlay_error:pillow_missing:{exc}")

    image = Image.open(BytesIO(img_bytes)).convert("RGBA")
    width, height = image.size
    overlay = Image.new("RGBA", image.size, (255, 255, 255, 0))
    draw = ImageDraw.Draw(overlay)

    def load_font(size: int, style: dict):
        font_path = _gfa_generator_font_path(style.get("font_family"), style.get("font_weight"))
        if font_path:
            try:
                return ImageFont.truetype(font_path, size=size)
            except Exception:
                pass
        return ImageFont.load_default()

    headline = _gfa_manual_copy_text(copy_result.get("headline"), max_lines=2) or "새치 고민, 자연스럽게 관리"
    subcopy = _gfa_manual_copy_text(copy_result.get("subcopy"), max_lines=2) or _gfa_manual_copy_text(copy_result.get("landing_message"), max_lines=2)
    proof = _gfa_manual_copy_text(copy_result.get("proof_line"), max_lines=2)
    if proof in {"증거 필요", "근거 필요"}:
        proof = ""
    cta_enabled = bool(copy_result.get("cta_enabled", True))
    cta = _collapse_ws_text(copy_result.get("cta")) or ("자세히 보기" if cta_enabled else "")

    line_gap = max(10, int(height * 0.012))

    def draw_text_block(key: str, text: str, base_size: float, defaults: dict, max_lines: int, fallback_fill: tuple[int, int, int, int], shadow_alpha: int) -> None:
        if not text:
            return
        style = _gfa_overlay_text_style(copy_result, key, defaults)
        font = load_font(max(12, int(width * base_size * style["font_scale"])), style)
        block_w = int(width * style["w"])
        lines = _gfa_generator_wrap_text(draw, text, font, block_w, max_lines)
        x = int(width * style["x"])
        y = int(height * style["y"])
        fill_raw = _gfa_overlay_hex_color(style.get("color", ""), fallback_fill)
        fill = (fill_raw[0], fill_raw[1], fill_raw[2], int(255 * style["opacity"]))
        line_gap_px = max(2, int(line_gap * style["line_height"]))
        bg_fill_raw = _gfa_overlay_hex_color(style.get("bg_color", ""), (255, 255, 255, 255))
        for line in lines:
            try:
                bbox = draw.textbbox((0, 0), line, font=font)
                line_w = bbox[2] - bbox[0]
                line_h = bbox[3] - bbox[1]
            except Exception:
                line_w = min(block_w, len(line) * int(width * base_size * 0.6))
                line_h = int(width * base_size)
            text_x = x
            if style["align"] == "center":
                text_x = x + max(0, (block_w - line_w) // 2)
            elif style["align"] == "right":
                text_x = x + max(0, block_w - line_w)
            if style["bg_opacity"] > 0:
                pad_x = max(6, int(width * 0.008))
                pad_y = max(4, int(height * 0.006))
                draw.rounded_rectangle(
                    (x - pad_x, y - pad_y, x + block_w + pad_x, y + line_h + pad_y),
                    radius=max(4, int(height * 0.008)),
                    fill=(bg_fill_raw[0], bg_fill_raw[1], bg_fill_raw[2], int(255 * style["bg_opacity"])),
                )
            if style.get("shadow"):
                shadow = max(1, int(width * 0.0025))
                draw.text((text_x + shadow, y + shadow), line, font=font, fill=(255, 255, 255, shadow_alpha))
            draw.text((text_x, y), line, font=font, fill=fill)
            y += line_h + line_gap_px

    draw_text_block("headline", headline, 0.062, {"x": 0.055, "y": 0.10, "w": 0.38, "font_scale": 1.0, "font_weight": "bold", "color": "#1e2b1c", "align": "left", "opacity": 1.0, "bg_opacity": 0.0, "line_height": 1.18, "shadow": True}, 2, (30, 43, 28, 255), 220)
    draw_text_block("subcopy", subcopy, 0.031, {"x": 0.055, "y": 0.36, "w": 0.38, "font_scale": 1.0, "font_weight": "regular", "color": "#303d26", "align": "left", "opacity": 1.0, "bg_opacity": 0.0, "line_height": 1.25, "shadow": True}, 2, (48, 61, 38, 255), 210)
    draw_text_block("proof", proof, 0.026, {"x": 0.055, "y": 0.51, "w": 0.38, "font_scale": 1.0, "font_weight": "regular", "color": "#634b34", "align": "left", "opacity": 1.0, "bg_opacity": 0.0, "line_height": 1.25, "shadow": True}, 2, (99, 75, 52, 255), 200)

    if cta_enabled and cta:
        cta_style = _gfa_overlay_text_style(copy_result, "cta", {"x": 0.055, "y": 0.79, "w": 0.34, "font_scale": 1.0, "font_weight": "bold", "color": "#ffffff", "align": "center", "opacity": 1.0, "bg_color": "#f5700d", "bg_opacity": 1.0, "line_height": 1.15, "shadow": False})
        cta_w = int(width * cta_style["w"])
        cta_h = max(58, int(height * 0.078 * cta_style["font_scale"]))
        cta_x = int(width * cta_style["x"])
        cta_y = int(height * cta_style["y"])
        cta_y = min(cta_y, int(height - cta_h - max(34, height * 0.045)))
        cta_font = load_font(max(18, int(width * 0.034 * cta_style["font_scale"])), cta_style)
        draw.rounded_rectangle(
            (cta_x, cta_y, cta_x + cta_w, cta_y + cta_h),
            radius=int(cta_h * 0.28),
            fill=tuple(list(_gfa_overlay_hex_color(cta_style.get("bg_color", ""), (245, 112, 13, 255)))[:3] + [int(255 * cta_style["bg_opacity"])]),
            outline=(255, 255, 255, 245),
            width=max(4, int(width * 0.006)),
        )
        try:
            cta_bbox = draw.textbbox((0, 0), cta, font=cta_font)
            cta_text_w = cta_bbox[2] - cta_bbox[0]
            cta_text_h = cta_bbox[3] - cta_bbox[1]
        except Exception:
            cta_text_w = len(cta) * 24
            cta_text_h = 32
        draw.text(
            (cta_x + (cta_w - cta_text_w) / 2, cta_y + (cta_h - cta_text_h) / 2 - 3),
            cta,
            font=cta_font,
            fill=tuple(list(_gfa_overlay_hex_color(cta_style.get("color", ""), (255, 255, 255, 255)))[:3] + [int(255 * cta_style["opacity"])]),
        )

    composed = Image.alpha_composite(image, overlay).convert("RGB")
    out = BytesIO()
    composed.save(out, format="PNG", optimize=True)
    return out.getvalue(), "image/png"


def _gfa_generator_image_ext(mime: str) -> str:
    low = str(mime or "").lower()
    if "png" in low:
        return ".png"
    if "jpeg" in low or "jpg" in low:
        return ".jpg"
    if "webp" in low:
        return ".webp"
    return ".png"


def _gfa_generator_write_image_file(img_bytes: bytes, mime: str, *, prefix: str) -> str:
    path = os.path.join(_gfa_generated_image_dir(), f"{prefix}_{uuid.uuid4().hex}{_gfa_generator_image_ext(mime)}")
    with open(path, "wb") as f:
        f.write(img_bytes)
    return path


def _gfa_local_edit_debug_dir(debug_id: str) -> str:
    path = os.path.join(_gfa_generated_image_dir(), "edit-debug", str(debug_id or uuid.uuid4().hex))
    os.makedirs(path, exist_ok=True)
    return path


def _gfa_local_edit_debug_write(debug_dir: str, name: str, data: bytes) -> str:
    path = os.path.join(debug_dir, name)
    with open(path, "wb") as f:
        f.write(data)
    return path


def _gfa_local_edit_debug_write_json(debug_dir: str, name: str, data: dict) -> str:
    path = os.path.join(debug_dir, name)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data if isinstance(data, dict) else {}, f, ensure_ascii=False, indent=2, sort_keys=True)
    return path


def _gfa_api_mask_stats(mask_bytes: bytes) -> dict:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_mask_stats_error:pillow_missing:{exc}")
    try:
        mask = Image.open(BytesIO(mask_bytes)).convert("RGBA")
    except Exception as exc:
        raise RuntimeError(f"image_mask_stats_error:{exc}")
    alpha = mask.getchannel("A")
    values = list(alpha.getdata())
    total = max(1, len(values))
    editable = sum(1 for value in values if value < 250)
    ratio = editable / float(total)
    return {
        "width": mask.size[0],
        "height": mask.size[1],
        "has_alpha": True,
        "editable_pixels": editable,
        "editable_ratio": round(ratio, 6),
    }


def _gfa_semantic_mask_input_stats(mask_bytes: bytes, *, target_size: tuple[int, int]) -> dict:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_mask_stats_error:pillow_missing:{exc}")
    if not mask_bytes:
        raise RuntimeError("image_edit_mask_missing")
    try:
        with Image.open(BytesIO(mask_bytes)) as opened:
            mode = str(opened.mode or "")
            width, height = opened.size
            has_alpha = mode in {"RGBA", "LA"} or (mode == "P" and "transparency" in opened.info)
            if (width, height) != target_size:
                raise RuntimeError(
                    f"image_edit_mask_size_mismatch:source={target_size[0]}x{target_size[1]},mask={width}x{height}"
                )
            if not has_alpha:
                raise RuntimeError("image_edit_mask_alpha_missing")
            mask = opened.convert("RGBA")
    except RuntimeError:
        raise
    except Exception as exc:
        raise RuntimeError(f"image_edit_mask_invalid:{exc}")
    pixels = mask.load()
    painted = 0
    total = max(1, width * height)
    for y in range(height):
        for x in range(width):
            r, g, b, a = pixels[x, y]
            if a > 10 and (r > 10 or g > 10 or b > 10):
                painted += 1
    ratio = painted / float(total)
    if ratio <= 0.001:
        raise RuntimeError("image_edit_mask_empty")
    if ratio >= 0.9:
        raise RuntimeError(f"image_edit_mask_invalid_editable_ratio:{ratio:.4f}")
    return {
        "width": width,
        "height": height,
        "has_alpha": has_alpha,
        "editable_pixels": painted,
        "editable_ratio": round(ratio, 6),
    }


def _gfa_local_edit_debug_write_diff_evidence(debug_dir: str, source_bytes: bytes, raw_bytes: bytes, final_bytes: bytes, api_mask_bytes: bytes) -> dict:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_diff_error:pillow_missing:{exc}")
    try:
        source = Image.open(BytesIO(source_bytes)).convert("RGBA")
        raw = Image.open(BytesIO(raw_bytes)).convert("RGBA").resize(source.size)
        final = Image.open(BytesIO(final_bytes)).convert("RGBA").resize(source.size)
        api_mask = Image.open(BytesIO(api_mask_bytes)).convert("RGBA").resize(source.size)
    except Exception as exc:
        raise RuntimeError(f"image_diff_error:{exc}")
    width, height = source.size
    total = max(1, width * height)
    src_px = source.load()
    raw_px = raw.load()
    final_px = final.load()
    mask_px = api_mask.load()
    diff_all = Image.new("RGBA", source.size, (0, 0, 0, 255))
    diff_outside = Image.new("RGBA", source.size, (0, 0, 0, 255))
    diff_all_px = diff_all.load()
    diff_outside_px = diff_outside.load()
    raw_changed = raw_outside_changed = final_changed = final_outside_changed = 0
    for y in range(height):
        for x in range(width):
            sr, sg, sb, _sa = src_px[x, y]
            rr, rg, rb, _ra = raw_px[x, y]
            fr, fg, fb, _fa = final_px[x, y]
            _mr, _mg, _mb, ma = mask_px[x, y]
            outside_mask = ma >= 250
            raw_delta = max(abs(sr - rr), abs(sg - rg), abs(sb - rb))
            final_delta = max(abs(sr - fr), abs(sg - fg), abs(sb - fb))
            if raw_delta > 8:
                raw_changed += 1
                if outside_mask:
                    raw_outside_changed += 1
            if final_delta > 8:
                final_changed += 1
                intensity = min(255, final_delta * 4)
                diff_all_px[x, y] = (intensity, 0, 0, 255)
                if outside_mask:
                    final_outside_changed += 1
                    diff_outside_px[x, y] = (intensity, 0, 0, 255)
    diff_all_path = os.path.join(debug_dir, "diff-all.png")
    diff_outside_path = os.path.join(debug_dir, "diff-mask-outside.png")
    diff_all.save(diff_all_path, format="PNG")
    diff_outside.save(diff_outside_path, format="PNG")
    return {
        "rawChangedRatio": round(raw_changed / float(total), 6),
        "rawOutsideMaskChangedRatio": round(raw_outside_changed / float(total), 6),
        "finalChangedRatio": round(final_changed / float(total), 6),
        "finalOutsideMaskChangedRatio": round(final_outside_changed / float(total), 6),
        "diffAllPath": diff_all_path,
        "diffMaskOutsidePath": diff_outside_path,
    }


def _gfa_local_edit_mask_expansion_path_stats(mask_bytes: bytes, *, target_size: tuple[int, int], expand_px: int, blur_px: int, api_mask_bytes: bytes) -> dict:
    try:
        from PIL import Image
        from PIL import ImageFilter
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_mask_expansion_stats_error:pillow_missing:{exc}")
    try:
        mask = Image.open(BytesIO(mask_bytes)).convert("RGBA")
        original_size = mask.size
        resized = mask.resize(target_size) if mask.size != target_size else mask
        selection = Image.new("L", target_size, 0)
        in_px = resized.load()
        out_px = selection.load()
    except Exception as exc:
        raise RuntimeError(f"image_mask_expansion_stats_error:{exc}")
    width, height = target_size
    total = max(1, width * height)
    for y in range(height):
        for x in range(width):
            r, g, b, a = in_px[x, y]
            if a > 10 and (r > 10 or g > 10 or b > 10):
                out_px[x, y] = 255
    semantic_pixels = sum(1 for value in selection.getdata() if value > 10)
    dilated = selection
    if expand_px > 1:
        dilated = dilated.filter(ImageFilter.MaxFilter(max(3, int(expand_px) | 1)))
    dilated_pixels = sum(1 for value in dilated.getdata() if value > 10)
    blurred = dilated
    if blur_px > 0:
        blurred = blurred.filter(ImageFilter.GaussianBlur(float(blur_px)))
    blurred_pixels = sum(1 for value in blurred.getdata() if value > 10)
    api_stats = _gfa_api_mask_stats(api_mask_bytes)
    return {
        "semanticInput": round(semantic_pixels / float(total), 6),
        "resize": round(semantic_pixels / float(total), 6),
        "dilation": round(dilated_pixels / float(total), 6),
        "blurFeather": round(blurred_pixels / float(total), 6),
        "alphaConversion": api_stats.get("editable_ratio"),
        "finalApiMask": api_stats.get("editable_ratio"),
        "sourceMaskSize": {"width": original_size[0], "height": original_size[1]},
        "targetSize": {"width": width, "height": height},
        "expandPx": int(expand_px),
        "blurPx": int(blur_px),
    }


def _gfa_local_edit_debug_write_boundary_evidence(
    debug_dir: str,
    source_bytes: bytes,
    final_bytes: bytes,
    semantic_mask_bytes: bytes,
    api_mask_bytes: bytes,
) -> dict:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_boundary_diff_error:pillow_missing:{exc}")
    try:
        source = Image.open(BytesIO(source_bytes)).convert("RGBA")
        final = Image.open(BytesIO(final_bytes)).convert("RGBA").resize(source.size)
        semantic_mask = Image.open(BytesIO(semantic_mask_bytes)).convert("RGBA").resize(source.size)
        api_mask = Image.open(BytesIO(api_mask_bytes)).convert("RGBA").resize(source.size)
    except Exception as exc:
        raise RuntimeError(f"image_boundary_diff_error:{exc}")
    width, height = source.size
    total = max(1, width * height)
    src_px = source.load()
    final_px = final.load()
    sem_px = semantic_mask.load()
    api_px = api_mask.load()
    diff_semantic_outside = Image.new("RGBA", source.size, (0, 0, 0, 255))
    expansion_zone = Image.new("RGBA", source.size, (0, 0, 0, 255))
    diff_sem_px = diff_semantic_outside.load()
    zone_px = expansion_zone.load()
    zone_counts = {"semantic": 0, "apiExpansion": 0, "outsideApi": 0}
    changed_counts = {"semantic": 0, "apiExpansion": 0, "outsideApi": 0}
    final_outside_semantic_changed = 0
    final_outside_api_changed = 0
    for y in range(height):
        for x in range(width):
            sr, sg, sb, _sa = src_px[x, y]
            fr, fg, fb, _fa = final_px[x, y]
            sem_r, sem_g, sem_b, sem_a = sem_px[x, y]
            _api_r, _api_g, _api_b, api_a = api_px[x, y]
            in_semantic = sem_a > 10 and (sem_r > 10 or sem_g > 10 or sem_b > 10)
            in_api = api_a < 250
            if in_semantic:
                zone = "semantic"
                zone_px[x, y] = (0, 180, 255, 255)
            elif in_api:
                zone = "apiExpansion"
                zone_px[x, y] = (255, 160, 0, 255)
            else:
                zone = "outsideApi"
                zone_px[x, y] = (32, 32, 32, 255)
            zone_counts[zone] += 1
            final_delta = max(abs(sr - fr), abs(sg - fg), abs(sb - fb))
            if final_delta > 8:
                changed_counts[zone] += 1
                intensity = min(255, final_delta * 4)
                if not in_semantic:
                    final_outside_semantic_changed += 1
                    diff_sem_px[x, y] = (intensity, 0, 0, 255)
                if not in_api:
                    final_outside_api_changed += 1
    semantic_outside_path = os.path.join(debug_dir, "diff-semantic-mask-outside.png")
    expansion_zone_path = os.path.join(debug_dir, "mask-expansion-zone.png")
    diff_semantic_outside.save(semantic_outside_path, format="PNG")
    expansion_zone.save(expansion_zone_path, format="PNG")

    def zone_summary(name: str) -> dict:
        zone_total = max(1, zone_counts.get(name, 0))
        return {
            "areaRatio": round(zone_counts.get(name, 0) / float(total), 6),
            "changedPixelRatio": round(changed_counts.get(name, 0) / float(zone_total), 6),
            "changedImageRatio": round(changed_counts.get(name, 0) / float(total), 6),
            "changedPixels": changed_counts.get(name, 0),
            "totalPixels": zone_counts.get(name, 0),
        }

    return {
        "finalOutsideSemanticMaskChangedRatio": round(final_outside_semantic_changed / float(total), 6),
        "finalOutsideApiMaskChangedRatio": round(final_outside_api_changed / float(total), 6),
        "zones": {
            "semantic": zone_summary("semantic"),
            "apiExpansion": zone_summary("apiExpansion"),
            "outsideApi": zone_summary("outsideApi"),
        },
        "diffSemanticMaskOutsidePath": semantic_outside_path,
        "maskExpansionZonePath": expansion_zone_path,
    }


def _gfa_local_edit_debug_write_dual_mask_evidence(
    debug_dir: str,
    source_bytes: bytes,
    raw_bytes: bytes,
    final_bytes: bytes,
    semantic_mask_bytes: bytes,
    generation_mask_bytes: bytes,
    commit_mask_bytes: bytes,
) -> dict:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_dual_mask_diff_error:pillow_missing:{exc}")
    try:
        source = Image.open(BytesIO(source_bytes)).convert("RGBA")
        raw = Image.open(BytesIO(raw_bytes)).convert("RGBA").resize(source.size)
        final = Image.open(BytesIO(final_bytes)).convert("RGBA").resize(source.size)
        semantic = Image.open(BytesIO(semantic_mask_bytes)).convert("RGBA").resize(source.size)
        generation = Image.open(BytesIO(generation_mask_bytes)).convert("L")
        commit = Image.open(BytesIO(commit_mask_bytes)).convert("L")
    except Exception as exc:
        raise RuntimeError(f"image_dual_mask_diff_error:{exc}")
    if generation.size != source.size or commit.size != source.size:
        raise RuntimeError("image_dual_mask_diff_error:mask_size_mismatch")
    width, height = source.size
    total = max(1, width * height)
    source_px = source.load()
    raw_px = raw.load()
    final_px = final.load()
    semantic_px = semantic.load()
    generation_px = generation.load()
    commit_px = commit.load()
    zone_counts = {"semantic": 0, "commitBand": 0, "generationOnly": 0, "outsideGeneration": 0}
    raw_changed = {key: 0 for key in zone_counts}
    final_changed = {key: 0 for key in zone_counts}
    raw_outside_semantic = final_outside_semantic = 0
    final_outside_generation = final_outside_commit = 0
    diff_commit_outside = Image.new("RGBA", source.size, (0, 0, 0, 255))
    diff_commit_px = diff_commit_outside.load()
    for y in range(height):
        for x in range(width):
            sr, sg, sb, _sa = source_px[x, y]
            rr, rg, rb, _ra = raw_px[x, y]
            fr, fg, fb, _fa = final_px[x, y]
            sem_r, sem_g, sem_b, sem_a = semantic_px[x, y]
            in_semantic = sem_a > 10 and (sem_r > 10 or sem_g > 10 or sem_b > 10)
            in_commit = commit_px[x, y] > 0
            in_generation = generation_px[x, y] > 0
            if in_semantic:
                zone = "semantic"
            elif in_commit:
                zone = "commitBand"
            elif in_generation:
                zone = "generationOnly"
            else:
                zone = "outsideGeneration"
            zone_counts[zone] += 1
            raw_delta = max(abs(sr - rr), abs(sg - rg), abs(sb - rb))
            final_delta = max(abs(sr - fr), abs(sg - fg), abs(sb - fb))
            if raw_delta > 8:
                raw_changed[zone] += 1
                if not in_semantic:
                    raw_outside_semantic += 1
            if final_delta > 8:
                final_changed[zone] += 1
                if not in_semantic:
                    final_outside_semantic += 1
                if not in_generation:
                    final_outside_generation += 1
                if not in_commit:
                    final_outside_commit += 1
                    diff_commit_px[x, y] = (min(255, final_delta * 4), 0, 0, 255)
    diff_commit_path = os.path.join(debug_dir, "diff-commit-mask-outside.png")
    diff_commit_outside.save(diff_commit_path, format="PNG")

    def summarize(zone: str) -> dict:
        count = zone_counts[zone]
        denominator = max(1, count)
        return {
            "areaRatio": round(count / float(total), 6),
            "rawChangedPixelRatio": round(raw_changed[zone] / float(denominator), 6),
            "rawChangedImageRatio": round(raw_changed[zone] / float(total), 6),
            "finalChangedPixelRatio": round(final_changed[zone] / float(denominator), 6),
            "finalChangedImageRatio": round(final_changed[zone] / float(total), 6),
            "totalPixels": count,
        }

    return {
        "rawOutsideSemanticMaskChangedRatio": round(raw_outside_semantic / float(total), 6),
        "finalOutsideSemanticMaskChangedRatio": round(final_outside_semantic / float(total), 6),
        "finalOutsideGenerationMaskChangedRatio": round(final_outside_generation / float(total), 6),
        "finalOutsideCommitMaskChangedRatio": round(final_outside_commit / float(total), 6),
        "zones": {
            "zoneA_semantic": summarize("semantic"),
            "zoneB_commitBand": summarize("commitBand"),
            "zoneC_generationOnly": summarize("generationOnly"),
            "zoneD_outsideGeneration": summarize("outsideGeneration"),
        },
        "diffCommitMaskOutsidePath": diff_commit_path,
    }


def _gfa_local_edit_debug_write_product_target_overlay(
    debug_dir: str,
    source_bytes: bytes,
    *,
    product_target_geometry: dict,
    commit_bbox: dict | None,
) -> str:
    try:
        from PIL import Image
        from PIL import ImageDraw
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_product_target_overlay_error:pillow_missing:{exc}")
    try:
        image = Image.open(BytesIO(source_bytes)).convert("RGBA")
    except Exception as exc:
        raise RuntimeError(f"image_product_target_overlay_error:{exc}")
    draw = ImageDraw.Draw(image, "RGBA")
    boxes = [
        ("semantic", product_target_geometry.get("semanticBBox"), (0, 180, 255, 255)),
        ("clear", product_target_geometry.get("clearBBox"), (34, 197, 94, 255)),
        ("productTarget", product_target_geometry.get("targetBBox"), (255, 214, 10, 255)),
        ("commit", commit_bbox, (255, 160, 0, 255)),
        ("generation", product_target_geometry.get("generationBBox"), (168, 85, 247, 255)),
    ]
    for label, box, color in boxes:
        if not isinstance(box, dict):
            continue
        x0, y0, x1, y1 = int(box["xMin"]), int(box["yMin"]), int(box["xMax"]), int(box["yMax"])
        draw.rectangle((x0, y0, x1, y1), outline=color, width=5)
        draw.text((x0 + 4, max(0, y0 - 18)), label, fill=color)
    path = os.path.join(debug_dir, "product-target-geometry-overlay.png")
    image.save(path, format="PNG")
    return path


def _gfa_generator_overlay_copy_on_base_image(*, base_image_path: str, copy_result: dict, combination: dict | None = None) -> tuple[str, str]:
    if not base_image_path or not os.path.exists(base_image_path):
        raise RuntimeError("base_image_missing_for_locked_copy_overlay")
    with open(base_image_path, "rb") as f:
        base_bytes = f.read()
    img_bytes, mime = _gfa_generator_overlay_copy_on_image(base_bytes, copy_result=copy_result, combination=combination)
    return _gfa_generator_write_image_file(img_bytes, mime, prefix="gfa_overlay"), mime


GFA_HAIR_NATIVE_EDIT_MODE = "hair_native_transform"
GFA_HAIR_NATIVE_MASK_TYPE = "ROUGH_HAIR_NATIVE_V2"
GFA_HAIR_NATIVE_MASK_EXPAND_PX = 9
GFA_HAIR_NATIVE_MASK_BLUR_PX = 2
GFA_PRODUCT_LOCKED_LAYER_VERSION = "GFA_PRODUCT_LOCKED_LAYER_V1"
GFA_PRODUCT_LOCKED_LAYER_AVAILABLE = "AVAILABLE"
GFA_PRODUCT_LOCKED_LAYER_FLATTENED = "SCENE_LOCKED_FLATTENED_UNRESTORABLE"
GFA_PRODUCT_LOCKED_LAYER_NOT_APPLICABLE = "NOT_APPLICABLE"
GFA_PRODUCT_PLACEMENT_AUTHORITY = "CANONICAL_PRODUCT_SLOT_GEOMETRY"
GFA_PRODUCT_SLOT_CONTRACT_VERSION = "GFA_CANONICAL_PRODUCT_SLOT_GEOMETRY_V1"
GFA_PRODUCT_SLOT_CONTRACT_RELATIVE_PATH = os.path.join(
    "calibration",
    "review",
    "gfa-generation-product-placement-geometry-authority-v1",
    "product-slot-contract.json",
)
GFA_AUTHORITATIVE_PRODUCT_REFERENCE_SOURCES = {"content_center_product_image", "tracked_product_image"}


def _sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data or b"").hexdigest()


def _sha256_file(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def _gfa_generator_product_slot_contract_path() -> str:
    explicit = str(os.getenv("GFA_PRODUCT_SLOT_CONTRACT_PATH") or "").strip()
    if explicit:
        return explicit
    candidates = [
        os.path.abspath(os.path.join(os.path.dirname(__file__), "..", GFA_PRODUCT_SLOT_CONTRACT_RELATIVE_PATH)),
        os.path.abspath(os.path.join(os.getcwd(), GFA_PRODUCT_SLOT_CONTRACT_RELATIVE_PATH)),
        os.path.abspath(os.path.join(os.sep, GFA_PRODUCT_SLOT_CONTRACT_RELATIVE_PATH)),
    ]
    for path in candidates:
        if os.path.exists(path):
            return path
    return candidates[0]


def _gfa_generator_product_slot_contract() -> dict:
    path = _gfa_generator_product_slot_contract_path()
    with open(path, "r", encoding="utf-8-sig") as f:
        contract = json.load(f)
    if str(contract.get("version") or "") != GFA_PRODUCT_SLOT_CONTRACT_VERSION:
        raise RuntimeError("product_slot_contract_version_mismatch")
    if str(contract.get("authority") or "") != GFA_PRODUCT_PLACEMENT_AUTHORITY:
        raise RuntimeError("product_slot_contract_authority_mismatch")
    slots = contract.get("slots") if isinstance(contract.get("slots"), dict) else {}
    for key in ("LOWER_RIGHT", "LOWER_CENTER_RIGHT"):
        if key not in slots:
            raise RuntimeError(f"product_slot_contract_missing:{key}")
    contract["_contractPath"] = path
    return contract


def _gfa_generator_normalize_product_placement_intent(brief: dict, combination: dict | None) -> str:
    combo = combination if isinstance(combination, dict) else {}
    visual = combo.get("visual_combination") if isinstance(combo.get("visual_combination"), dict) else {}
    text = " ".join(
        str(value or "")
        for value in (
            visual.get("composition"),
            combo.get("generation_intent"),
            (brief or {}).get("layout_rule"),
            (brief or {}).get("layout_metric_rule"),
        )
    ).lower()
    raw = text.replace("_", "-")
    if "lower-center-right" in raw or "중앙-우측" in text or "중앙 우측" in text:
        return "LOWER_CENTER_RIGHT"
    if "lower-right" in raw or "오른쪽 아래" in text or "우측 하단" in text or "하단 우측" in text:
        return "LOWER_RIGHT"
    return "LOWER_RIGHT"


def _gfa_generator_product_reference_payload(brief: dict) -> dict:
    refs = (brief or {}).get("additional_references") if isinstance((brief or {}).get("additional_references"), dict) else {}
    images = refs.get("images") if isinstance(refs.get("images"), list) else []
    for ref in images:
        if not isinstance(ref, dict):
            continue
        source = str(ref.get("source") or "").strip()
        if source not in GFA_AUTHORITATIVE_PRODUCT_REFERENCE_SOURCES:
            continue
        data_b64 = str(ref.get("data_base64") or "")
        if not data_b64:
            continue
        try:
            raw = base64.b64decode(data_b64)
        except Exception:
            continue
        return {
            "ref": ref,
            "bytes": raw,
            "mimeType": str(ref.get("mime_type") or "image/png").strip() or "image/png",
            "filename": str(ref.get("filename") or "product-reference.png").strip() or "product-reference.png",
            "sha256": _sha256_bytes(raw),
        }
    return {}


def _gfa_generator_product_reference_lineage(brief: dict) -> dict:
    refs = (brief or {}).get("additional_references") if isinstance((brief or {}).get("additional_references"), dict) else {}
    images = refs.get("images") if isinstance(refs.get("images"), list) else []
    for ref in images:
        if not isinstance(ref, dict):
            continue
        source = str(ref.get("source") or "").strip()
        if source not in GFA_AUTHORITATIVE_PRODUCT_REFERENCE_SOURCES:
            continue
        data_b64 = str(ref.get("data_base64") or "")
        sha = ""
        size = 0
        if data_b64:
            try:
                raw = base64.b64decode(data_b64)
                sha = _sha256_bytes(raw)
                size = len(raw)
            except Exception:
                sha = ""
        return {
            "sourceType": "PRODUCT_ASSET",
            "assetId": str(ref.get("asset_id") or "").strip(),
            "source": source,
            "sourceUrl": str(ref.get("url") or ref.get("product_url") or "").strip(),
            "sourcePath": str(ref.get("path") or "").strip(),
            "sha256": sha,
            "mimeType": str(ref.get("mime_type") or "image/png").strip() or "image/png",
            "size": size,
        }
    return {}


def _gfa_generator_product_locked_layer_metadata(*, brief: dict, base_image_path: str, canvas_size: tuple[int, int] | None = None) -> dict:
    lineage = _gfa_generator_product_reference_lineage(brief)
    canvas_w, canvas_h = (canvas_size or (0, 0))
    if not lineage:
        return {
            "version": GFA_PRODUCT_LOCKED_LAYER_VERSION,
            "status": GFA_PRODUCT_LOCKED_LAYER_NOT_APPLICABLE,
            "reason": "product_reference_not_present",
        }
    return {
        "version": GFA_PRODUCT_LOCKED_LAYER_VERSION,
        "status": GFA_PRODUCT_LOCKED_LAYER_FLATTENED,
        "reason": "product_rendered_by_image_model_into_flattened_base_raster",
        "source": {
            "assetId": lineage.get("assetId") or "",
            "sourceType": lineage.get("sourceType") or "",
            "sourceUrl": lineage.get("sourceUrl") or "",
            "sourcePath": lineage.get("sourcePath") or "",
            "sha256": lineage.get("sha256") or "",
            "mimeType": lineage.get("mimeType") or "",
        },
        "geometry": {
            "canvasWidth": int(canvas_w or 0),
            "canvasHeight": int(canvas_h or 0),
            "x": None,
            "y": None,
            "width": None,
            "height": None,
            "anchor": "",
            "scaleX": None,
            "scaleY": None,
        },
        "render": {
            "alphaAvailable": False,
            "zOrder": None,
        },
        "baseImagePath": base_image_path,
        "restoreCapability": "exact_restore_unavailable_without_authoritative_product_layer_geometry",
    }


def _gfa_generator_available_product_locked_layer_metadata(
    *,
    brief: dict,
    base_image_path: str,
    deterministic_product: dict,
) -> dict:
    lineage = _gfa_generator_product_reference_lineage(brief)
    geometry = deterministic_product.get("geometry") if isinstance(deterministic_product.get("geometry"), dict) else {}
    slot = deterministic_product.get("slot") if isinstance(deterministic_product.get("slot"), dict) else {}
    source = deterministic_product.get("source") if isinstance(deterministic_product.get("source"), dict) else {}
    layer = deterministic_product.get("layer") if isinstance(deterministic_product.get("layer"), dict) else {}
    canvas = deterministic_product.get("canvas") if isinstance(deterministic_product.get("canvas"), dict) else {}
    if not lineage or not geometry or not slot or not layer.get("path") or not source.get("sha256"):
        return _gfa_generator_product_locked_layer_metadata(
            brief=brief,
            base_image_path=base_image_path,
            canvas_size=(int(canvas.get("width") or 0), int(canvas.get("height") or 0)),
        )
    return {
        "version": GFA_PRODUCT_LOCKED_LAYER_VERSION,
        "status": GFA_PRODUCT_LOCKED_LAYER_AVAILABLE,
        "reason": "product_layer_rendered_deterministically_from_canonical_slot_contract",
        "placementIntent": deterministic_product.get("placementIntent"),
        "geometryAuthority": GFA_PRODUCT_PLACEMENT_AUTHORITY,
        "slotContractVersion": deterministic_product.get("slotContractVersion"),
        "slotContractPath": deterministic_product.get("slotContractPath"),
        "source": {
            "assetId": lineage.get("assetId") or "",
            "sourceType": lineage.get("sourceType") or "",
            "sourceUrl": lineage.get("sourceUrl") or "",
            "sourcePath": source.get("path") or lineage.get("sourcePath") or "",
            "sha256": source.get("sha256") or lineage.get("sha256") or "",
            "mimeType": lineage.get("mimeType") or "",
        },
        "slot": slot,
        "geometry": {
            "canvasWidth": int(canvas.get("width") or 0),
            "canvasHeight": int(canvas.get("height") or 0),
            "x": int(geometry.get("x") or 0),
            "y": int(geometry.get("y") or 0),
            "width": int(geometry.get("width") or geometry.get("w") or 0),
            "height": int(geometry.get("height") or geometry.get("h") or 0),
            "xMin": int(geometry.get("xMin") or geometry.get("x") or 0),
            "yMin": int(geometry.get("yMin") or geometry.get("y") or 0),
            "xMax": int(geometry.get("xMax") or 0),
            "yMax": int(geometry.get("yMax") or 0),
            "anchor": deterministic_product.get("anchor") or "BOTTOM_CENTER",
            "scaleX": deterministic_product.get("scaleFactor"),
            "scaleY": deterministic_product.get("scaleFactor"),
        },
        "render": {
            "alphaAvailable": True,
            "zOrder": "above_base_below_text_overlay",
            "fitPolicy": "FIT_INSIDE_PRODUCT_SLOT",
            "aspect": "PRESERVE_PRODUCT_FOREGROUND_ASPECT_RATIO",
            "productLayerPath": layer.get("path") or "",
            "productLayerSha256": layer.get("sha256") or "",
            "foregroundPath": deterministic_product.get("foregroundPath") or "",
            "debugDir": deterministic_product.get("debugDir") or "",
        },
        "productLayerPath": layer.get("path") or "",
        "baseImagePath": base_image_path,
        "restoreCapability": "RESTORE_EXACT_FROM_DETERMINISTIC_PRODUCT_LAYER",
    }


def _gfa_generator_image_size_from_file(path: str) -> tuple[int, int]:
    if not path or not os.path.exists(path):
        return (0, 0)
    try:
        from PIL import Image
        with Image.open(path) as opened:
            return opened.size
    except Exception:
        return (0, 0)


def _gfa_generator_product_locked_layer_status(source_explanation: dict) -> tuple[dict, str]:
    explanation = source_explanation if isinstance(source_explanation, dict) else {}
    layer = explanation.get("productLockedLayer") if isinstance(explanation.get("productLockedLayer"), dict) else None
    if not layer:
        return (
            {
                "version": GFA_PRODUCT_LOCKED_LAYER_VERSION,
                "status": GFA_PRODUCT_LOCKED_LAYER_FLATTENED,
                "reason": "product_layer_metadata_missing",
            },
            "SKIPPED_SCENE_LOCKED_FLATTENED_UNRESTORABLE",
        )
    status = str(layer.get("status") or "").strip() or GFA_PRODUCT_LOCKED_LAYER_FLATTENED
    if status == GFA_PRODUCT_LOCKED_LAYER_AVAILABLE:
        return layer, "RESTORE_CANDIDATE_AVAILABLE"
    if status == GFA_PRODUCT_LOCKED_LAYER_NOT_APPLICABLE:
        return layer, "NOT_APPLICABLE"
    return layer, "SKIPPED_SCENE_LOCKED_FLATTENED_UNRESTORABLE"


def _gfa_generator_has_locked_text_assets(copy_result: dict) -> dict:
    copy = copy_result if isinstance(copy_result, dict) else {}
    return {
        "headline": bool(_collapse_ws_text(copy.get("headline"))),
        "subcopy": bool(_collapse_ws_text(copy.get("subcopy"))),
        "proof": bool(_collapse_ws_text(copy.get("proof_line"))),
        "cta": bool(copy.get("cta_enabled", True) and _collapse_ws_text(copy.get("cta"))),
    }


def _gfa_generator_find_product_layer_path(payload: object) -> str:
    keys = {
        "product_layer_path",
        "productLayerPath",
        "placed_product_layer_path",
        "placedProductLayerPath",
        "deterministic_product_layer_path",
        "deterministicProductLayerPath",
    }
    stack = [payload]
    seen = 0
    while stack and seen < 800:
        seen += 1
        item = stack.pop()
        if isinstance(item, dict):
            for key, value in item.items():
                if key in keys and isinstance(value, str):
                    path = value.strip()
                    if path and os.path.exists(path):
                        return path
                if isinstance(value, (dict, list)):
                    stack.append(value)
        elif isinstance(item, list):
            stack.extend(value for value in item if isinstance(value, (dict, list)))
    return ""


def _gfa_local_edit_debug_write_changed_mask(debug_dir: str, before_bytes: bytes, after_bytes: bytes, name: str) -> str:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_changed_mask_error:pillow_missing:{exc}")
    before = Image.open(BytesIO(before_bytes)).convert("RGBA")
    after = Image.open(BytesIO(after_bytes)).convert("RGBA").resize(before.size)
    out = Image.new("RGBA", before.size, (0, 0, 0, 0))
    bp = before.load()
    ap = after.load()
    op = out.load()
    width, height = before.size
    for y in range(height):
        for x in range(width):
            br, bg, bb, _ba = bp[x, y]
            ar, ag, ab, _aa = ap[x, y]
            delta = max(abs(br - ar), abs(bg - ag), abs(bb - ab))
            if delta > 8:
                op[x, y] = (255, 255, 255, 255)
    path = os.path.join(debug_dir, name)
    out.save(path, format="PNG")
    return path


def _gfa_generator_hair_native_restore_locked_assets(
    *,
    native_raw_bytes: bytes,
    copy_result: dict,
    combination: dict | None,
    source_explanation: dict,
    overlay_after_edit: bool,
    debug_dir: str,
) -> tuple[bytes, bytes, str, dict]:
    locked_text = _gfa_generator_has_locked_text_assets(copy_result)
    locked_assets = {
        "product": False,
        "logo": False,
        "text": bool(any(locked_text.get(key) for key in ("headline", "subcopy", "proof")) and overlay_after_edit),
        "cta": bool(locked_text.get("cta") and overlay_after_edit),
    }
    summary: dict = {
        "lockedAssets": locked_assets,
        "lockedTextAssets": locked_text,
        "productLockedLayer": {},
        "productRestoreStatus": "",
        "restoreSource": {
            "product": "none",
            "text": "server_copy_overlay" if overlay_after_edit else "unavailable_no_clean_base",
            "cta": "server_copy_overlay" if overlay_after_edit else "unavailable_no_clean_base",
        },
        "restoreMethod": {
            "product": "none",
            "text": "deterministic_server_overlay" if overlay_after_edit else "none",
            "cta": "deterministic_server_overlay" if overlay_after_edit else "none",
        },
        "productRestoreSkippedReason": "",
    }
    restored_base_bytes = native_raw_bytes
    product_layer, product_restore_status = _gfa_generator_product_locked_layer_status(source_explanation)
    summary["productLockedLayer"] = product_layer
    summary["productRestoreStatus"] = product_restore_status
    product_layer_path = ""
    if product_restore_status == "RESTORE_CANDIDATE_AVAILABLE":
        source = product_layer.get("source") if isinstance(product_layer.get("source"), dict) else {}
        render = product_layer.get("render") if isinstance(product_layer.get("render"), dict) else {}
        product_layer_path = str(
            product_layer.get("productLayerPath")
            or product_layer.get("product_layer_path")
            or render.get("productLayerPath")
            or source.get("sourcePath")
            or ""
        ).strip()
        if product_layer_path and not os.path.exists(product_layer_path):
            summary["productRestoreStatus"] = "PRODUCT_LOCKED_LAYER_SOURCE_MISMATCH"
            summary["productRestoreSkippedReason"] = "product_locked_layer_source_missing"
            product_layer_path = ""
        expected_sha = str(render.get("productLayerSha256") or "").strip() if product_layer_path and product_layer_path == str(render.get("productLayerPath") or "").strip() else str(source.get("sha256") or "").strip()
        if product_layer_path and expected_sha:
            try:
                actual_sha = _sha256_file(product_layer_path)
                summary["productSourceSha256"] = actual_sha
                if actual_sha != expected_sha:
                    summary["productRestoreStatus"] = "PRODUCT_LOCKED_LAYER_SOURCE_MISMATCH"
                    summary["productRestoreSkippedReason"] = "product_locked_layer_source_sha_mismatch"
                    product_layer_path = ""
            except Exception as exc:
                summary["productSourceSha256Error"] = str(exc)[:500]
                product_layer_path = ""
    else:
        summary["productRestoreSkippedReason"] = str(product_layer.get("reason") or "").strip() or "product_locked_layer_not_available"

    if product_layer_path:
        with open(product_layer_path, "rb") as f:
            product_layer_bytes = f.read()
        restored_base_bytes = _gfa_generator_reoverlay_product_layer(restored_base_bytes, product_layer_bytes)
        locked_assets["product"] = True
        summary["productRestoreStatus"] = "RESTORED_EXACT"
        summary["restoreSource"]["product"] = product_layer_path
        summary["restoreMethod"]["product"] = "exact_product_layer_reoverlay"
        try:
            summary["productIdentity"] = _gfa_generator_product_identity_evidence(restored_base_bytes, product_layer_bytes, debug_dir=debug_dir)
        except Exception as exc:
            summary["productIdentityError"] = str(exc)[:500]
    elif not summary.get("productRestoreSkippedReason"):
        summary["productRestoreSkippedReason"] = "product_layer_metadata_missing"

    if overlay_after_edit:
        final_bytes, final_mime = _gfa_generator_overlay_copy_on_image(restored_base_bytes, copy_result=copy_result, combination=combination)
    else:
        final_bytes, final_mime = restored_base_bytes, "image/png"
    try:
        summary["lockedAssetMaskPath"] = _gfa_local_edit_debug_write_changed_mask(debug_dir, restored_base_bytes, final_bytes, "locked-asset-mask.png")
        summary["lockedAssetOverlayPath"] = _gfa_local_edit_debug_write(debug_dir, "locked-asset-overlay.png", final_bytes)
    except Exception as exc:
        summary["lockedAssetArtifactError"] = str(exc)[:500]
    return restored_base_bytes, final_bytes, final_mime, summary


def _gfa_generator_edit_image_hair_native_locked_restore(
    *,
    source_image_path: str,
    source_mime: str,
    edit_prompt: str,
    copy_result: dict,
    combination: dict | None = None,
    model: str | None = None,
    mask_bytes: bytes | None = None,
    source_explanation: dict | None = None,
    overlay_after_edit: bool = True,
) -> tuple[str, str, str, str, str, str, dict]:
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise RuntimeError("OPENAI_API_KEY not configured")
    if not source_image_path or not os.path.exists(source_image_path):
        raise RuntimeError("source_image_missing")
    user_prompt = _collapse_ws_text(edit_prompt)
    if not user_prompt:
        raise RuntimeError("image_edit_prompt_missing")
    flags = _gfa_generator_mask_edit_flags(user_prompt, reference_count=0)
    if not flags.get("hair"):
        raise RuntimeError("hair_native_prompt_not_hair")
    if not mask_bytes:
        raise RuntimeError("image_edit_mask_missing")

    uploaded_mask_bytes = mask_bytes
    mask_bytes, mask_sanitize_stats = _gfa_generator_sanitize_semantic_mask_png(uploaded_mask_bytes)

    model_name = str(model or os.getenv("GFA_CREATIVE_IMAGE_MODEL") or "gpt-image-2").strip()
    debug_id = uuid.uuid4().hex
    debug_dir = _gfa_local_edit_debug_dir(debug_id)
    with open(source_image_path, "rb") as f:
        source_bytes = f.read()
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_edit_error:pillow_missing:{exc}")
    with Image.open(BytesIO(source_bytes)) as opened:
        target_size = opened.size
    image_size = str(os.getenv("GFA_CREATIVE_IMAGE_SIZE") or f"{target_size[0]}x{target_size[1]}").strip() or "1024x1024"
    semantic_mask_stats = _gfa_semantic_mask_input_stats(mask_bytes, target_size=target_size)
    native_mask_bytes, native_mask_coverage = _gfa_generator_prepare_openai_edit_mask(
        mask_bytes,
        target_size=target_size,
        expand_px=GFA_HAIR_NATIVE_MASK_EXPAND_PX,
        blur_px=GFA_HAIR_NATIVE_MASK_BLUR_PX,
    )
    native_mask_stats = _gfa_api_mask_stats(native_mask_bytes)
    generation_mask_bytes = _gfa_generator_api_mask_to_selection_bytes(native_mask_bytes)
    _gfa_local_edit_debug_write(debug_dir, "source.png", source_bytes)
    _gfa_local_edit_debug_write(debug_dir, "semantic-mask-uploaded.png", uploaded_mask_bytes)
    _gfa_local_edit_debug_write(debug_dir, "semantic-mask-input.png", mask_bytes)
    _gfa_local_edit_debug_write(debug_dir, "actual-api-image-input.png", source_bytes)
    _gfa_local_edit_debug_write(debug_dir, "native-mask.png", native_mask_bytes)
    _gfa_local_edit_debug_write(debug_dir, "rough-hair-selection-mask.png", generation_mask_bytes)

    resp = requests.post(
        "https://api.openai.com/v1/images/edits",
        headers={"Authorization": f"Bearer {key}"},
        data={"model": model_name, "prompt": user_prompt, "size": image_size, "n": "1"},
        files=[
            ("image", ("source.png", source_bytes, source_mime or "image/png")),
            ("mask", ("native-mask.png", native_mask_bytes, "image/png")),
        ],
        timeout=180,
    )
    if resp.status_code != 200:
        raise RuntimeError(f"openai_image_error:{resp.status_code}:{_safe_err_text(resp, 1200)}")
    native_raw_bytes, native_raw_mime = _gfa_generator_extract_openai_image(resp.json() or {})
    _gfa_local_edit_debug_write(debug_dir, "native-raw-result.png", native_raw_bytes)
    restored_base_bytes, final_bytes, final_mime, locked_restore = _gfa_generator_hair_native_restore_locked_assets(
        native_raw_bytes=native_raw_bytes,
        copy_result=copy_result,
        combination=combination,
        source_explanation=source_explanation if isinstance(source_explanation, dict) else {},
        overlay_after_edit=overlay_after_edit,
        debug_dir=debug_dir,
    )
    _gfa_local_edit_debug_write(debug_dir, "base-after-locked-restore.png", restored_base_bytes)
    _gfa_local_edit_debug_write(debug_dir, "final-after-locked-restore.png", final_bytes)
    try:
        diff = _gfa_local_edit_debug_write_diff_evidence(debug_dir, source_bytes, native_raw_bytes, final_bytes, native_mask_bytes)
    except Exception as exc:
        diff = {"error": str(exc)[:500]}

    base_path = _gfa_generator_write_image_file(restored_base_bytes, "image/png", prefix="gfa_base_edit")
    final_path = _gfa_generator_write_image_file(final_bytes, final_mime, prefix="gfa_image_edit")
    debug_summary = {
        "operation": "HAIR_NATIVE_EDIT_WITH_LOCKED_ASSET_RESTORE",
        "debugId": debug_id,
        "debugDir": debug_dir,
        "hairNativeTransform": {
            "enabled": True,
            "maskType": GFA_HAIR_NATIVE_MASK_TYPE,
            "nativeApiExecuted": True,
            "lockedAssetRestoreApplied": True,
            "commitPixelLockApplied": False,
            "lockedAssets": locked_restore.get("lockedAssets"),
            "nativeQuality": {
                "structuralChange": "PENDING_RUNTIME_QA",
                "naturalness": "PENDING_RUNTIME_QA",
            },
        },
        "semanticMask": semantic_mask_stats,
        "nativeMask": native_mask_stats,
        "nativeMaskPolicy": {
            "expandPx": GFA_HAIR_NATIVE_MASK_EXPAND_PX,
            "blurPx": GFA_HAIR_NATIVE_MASK_BLUR_PX,
            "coverage": round(float(native_mask_coverage or 0), 6),
        },
        "lockedAssetRestore": locked_restore,
        "diff": diff,
        "source": {"path": source_image_path, "mime": source_mime, "width": target_size[0], "height": target_size[1]},
        "annotationIsolation": _gfa_annotation_isolation_evidence(
            source_bytes=source_bytes,
            uploaded_mask_bytes=uploaded_mask_bytes,
            semantic_mask_bytes=mask_bytes,
            sanitize_stats=mask_sanitize_stats,
            api_image_bytes=source_bytes,
            api_mask_bytes=native_mask_bytes,
            raw_ai_bytes=native_raw_bytes,
            final_bytes=final_bytes,
            composite_base_bytes=source_bytes,
            intentional_source_clear=False,
            stale_overlay_after_result=False,
        ),
    }
    _gfa_local_edit_debug_write_json(debug_dir, "debug-summary.json", debug_summary)
    prompt = f"HAIR_NATIVE_EDIT_DEBUG_ID:{debug_id}\nHAIR_NATIVE_EDIT_DEBUG_DIR:{debug_dir}\n{user_prompt}"
    return final_path, final_mime, prompt, f"openai:{model_name}", base_path, "image/png", debug_summary


def _gfa_generator_generate_image(*, brief: dict, copy_result: dict, combination: dict | None = None, model: str | None = None) -> tuple[str, str, str, str, str, str, dict]:
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise RuntimeError("OPENAI_API_KEY not configured")
    model_name = str(model or os.getenv("GFA_CREATIVE_IMAGE_MODEL") or "gpt-image-2").strip()
    ad_media_spec = brief.get("ad_media_spec") if isinstance(brief.get("ad_media_spec"), dict) else {}
    image_size = str(ad_media_spec.get("openai_size") or os.getenv("GFA_CREATIVE_IMAGE_SIZE") or "1024x1024").strip() or "1024x1024"
    product_reference = _gfa_generator_product_reference_payload(brief)
    product_slot_context: dict = {}
    if product_reference:
        contract = _gfa_generator_product_slot_contract()
        placement_intent = _gfa_generator_normalize_product_placement_intent(brief, combination)
        contract_slot = (contract.get("slots") or {}).get(placement_intent)
        if not isinstance(contract_slot, dict):
            raise RuntimeError(f"product_slot_contract_missing:{placement_intent}")
        slot = contract_slot.get("slot") if isinstance(contract_slot.get("slot"), dict) else {}
        product_slot_context = {
            "placementIntent": placement_intent,
            "slot": slot,
            "anchor": str(contract_slot.get("anchor") or "BOTTOM_CENTER"),
            "slotContractVersion": str(contract.get("version") or ""),
            "slotContractPath": str(contract.get("_contractPath") or ""),
            "geometryAuthority": GFA_PRODUCT_PLACEMENT_AUTHORITY,
        }
    prompt = _gfa_generator_image_prompt(_gfa_generator_public_brief(brief), copy_result, combination, product_slot_context=product_slot_context)
    refs = brief.get("additional_references") if isinstance(brief.get("additional_references"), dict) else {}
    image_refs = refs.get("images") if isinstance(refs.get("images"), list) else []

    files: list[tuple[str, tuple[str, bytes, str]]] = []
    for idx, ref in enumerate(image_refs[:4], start=1):
        if not isinstance(ref, dict):
            continue
        if product_slot_context and str(ref.get("source") or "").strip() in GFA_AUTHORITATIVE_PRODUCT_REFERENCE_SOURCES:
            continue
        data_b64 = str(ref.get("data_base64") or "")
        if not data_b64:
            continue
        mime = str(ref.get("mime_type") or "image/png").strip() or "image/png"
        filename = str(ref.get("filename") or f"reference_{idx}.png")
        try:
            files.append(("image", (filename, base64.b64decode(data_b64), mime)))
        except Exception:
            continue

    headers = {"Authorization": f"Bearer {key}"}
    if files:
        if len(files) > 1:
            files = [("image[]", value) for _name, value in files]
        resp = requests.post(
            "https://api.openai.com/v1/images/edits",
            headers=headers,
            data={
                "model": model_name,
                "prompt": prompt,
                "size": image_size,
                "n": "1",
            },
            files=files,
            timeout=180,
        )
    else:
        resp = requests.post(
            "https://api.openai.com/v1/images/generations",
            headers={**headers, "Content-Type": "application/json"},
            json={
                "model": model_name,
                "prompt": prompt,
                "size": image_size,
                "n": 1,
            },
            timeout=180,
        )
    if resp.status_code != 200:
        raise RuntimeError(f"openai_image_error:{resp.status_code}:{_safe_err_text(resp, 1200)}")
    base_bytes, base_mime = _gfa_generator_extract_openai_image(resp.json() or {})
    base_path = _gfa_generator_write_image_file(base_bytes, base_mime, prefix="gfa_base")
    generation_product_layer: dict = {}
    product_composite_bytes = base_bytes
    if product_slot_context and product_reference:
        generation_product_layer = _gfa_generator_compose_generation_product_layer(
            base_bytes,
            product_reference=product_reference,
            slot_context=product_slot_context,
        )
        product_composite_bytes = generation_product_layer["finalCompositePng"]
    img_bytes, mime = _gfa_generator_overlay_copy_on_image(product_composite_bytes, copy_result=copy_result, combination=combination)
    path = _gfa_generator_write_image_file(img_bytes, mime, prefix="gfa_generated")
    if generation_product_layer:
        debug_dir = str(generation_product_layer.get("debugDir") or "")
        if debug_dir:
            _gfa_local_edit_debug_write(debug_dir, "final-generated-banner-with-copy.png", img_bytes)
            _gfa_local_edit_debug_write_json(
                debug_dir,
                "product-layer-metadata.json",
                _gfa_generator_available_product_locked_layer_metadata(
                    brief=brief,
                    base_image_path=base_path,
                    deterministic_product=generation_product_layer,
                ),
            )
    generation_debug = {
        "productLayer": generation_product_layer,
        "productSlotContext": product_slot_context,
        "baseGeneration": {
            "productReferenceRemovedFromOpenAIInput": bool(product_slot_context),
            "reservedProductSlotRequired": bool(product_slot_context),
            "productFreeBase": bool(product_slot_context),
            "ghostProduct": "UNKNOWN_RUNTIME_VISUAL_QA_REQUIRED" if product_slot_context else "NOT_APPLICABLE",
        },
    }
    return path, mime, prompt, f"openai:{model_name}", base_path, base_mime, generation_debug


def _gfa_generator_mask_edit_envelope(prompt: str) -> tuple[int, int]:
    text = str(prompt or "").lower()
    if any(token in text or token in str(prompt or "") for token in ["길이", "길게", "연장", "어깨", "extend", "longer", "length"]):
        return 111, 9
    if any(token in text or token in str(prompt or "") for token in ["교체", "변경", "바꿔", "replace", "change"]):
        return 121, 10
    if any(token in text or token in str(prompt or "") for token in ["삭제", "제거", "지워", "없애", "remove", "delete", "erase"]):
        return 111, 9
    return 71, 6


def _gfa_generator_split_edit_clauses(prompt: str) -> list[str]:
    raw = str(prompt or "")
    for sep in ["\r", "\n", ".", "。", "!", "?", "!", "?", ";", "；"]:
        raw = raw.replace(sep, "|")
    for sep in [" 그리고 ", " and ", " but ", " however ", " 단, ", " 다만 ", " 그리고", "하고 "]:
        raw = raw.replace(sep, "|")
    return [_collapse_ws_text(part) for part in raw.split("|") if _collapse_ws_text(part)]


def _gfa_generator_is_preservation_or_negative_clause(clause: str) -> bool:
    raw = str(clause or "")
    text = raw.lower()
    markers = [
        "변경하지",
        "바꾸지",
        "수정하지",
        "건드리지",
        "그대로",
        "유지",
        "보존",
        "제외",
        "do not change",
        "don't change",
        "do not modify",
        "keep",
        "preserve",
        "leave unchanged",
        "except",
    ]
    return any(marker in raw or marker in text for marker in markers)


def _gfa_generator_mask_edit_flags(prompt: str, reference_count: int = 0) -> dict:
    raw = str(prompt or "")
    clauses = _gfa_generator_split_edit_clauses(raw)
    positive_clauses = [clause for clause in clauses if not _gfa_generator_is_preservation_or_negative_clause(clause)]
    positive_raw = " ".join(positive_clauses)
    positive_text = positive_raw.lower()
    hair_terms = ["머리", "머리카락", "헤어", "hair", "bang", "length", "longer", "웨이브", "윤기"]
    product_terms = ["제품", "상품", "패키지", "파우치", "pack", "package", "pouch", "product"]
    removal_terms = ["삭제", "제거", "지워", "없애", "remove", "delete", "erase"]
    replace_terms = ["교체", "바꿔", "replace", "change", "첨부", "reference"]
    product = any(token in positive_raw or token in positive_text for token in product_terms)
    replace = bool(product and int(reference_count or 0) > 0 and any(token in positive_raw or token in positive_text for token in replace_terms))
    return {
        "hair": any(token in positive_raw or token in positive_text for token in hair_terms),
        "product": product,
        "remove": any(token in positive_raw or token in positive_text for token in removal_terms),
        "replace": replace,
    }


def _gfa_generator_should_clear_masked_region(prompt: str, reference_count: int = 0, flags: dict | None = None) -> bool:
    flags = flags if isinstance(flags, dict) else _gfa_generator_mask_edit_flags(prompt, reference_count=reference_count)
    # Clearing helps object removal/replacement, but for hair/person edits it
    # often erases identity and causes full person regeneration.
    return bool(flags.get("remove") or (flags.get("replace") and int(reference_count or 0) > 0))


def _gfa_generator_sanitize_semantic_mask_png(mask_bytes: bytes) -> tuple[bytes, dict]:
    from gfa_mask_annotation_isolation import sanitize_semantic_mask_png

    return sanitize_semantic_mask_png(mask_bytes)


def _gfa_annotation_isolation_evidence(**kwargs) -> dict:
    from gfa_mask_annotation_isolation import build_annotation_isolation_evidence

    return build_annotation_isolation_evidence(**kwargs)


def _gfa_request_image_bytes(files: list) -> bytes:
    try:
        payload = files[0][1]
        if isinstance(payload, tuple) and len(payload) >= 2 and isinstance(payload[1], (bytes, bytearray)):
            return bytes(payload[1])
    except Exception:
        return b""
    return b""


def _gfa_generator_prepare_openai_edit_mask(mask_bytes: bytes, *, target_size: tuple[int, int], expand_px: int = 91, blur_px: int = 8) -> tuple[bytes, float]:
    try:
        from PIL import Image
        from PIL import ImageFilter
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_mask_error:pillow_missing:{exc}")

    selection, coverage = _gfa_generator_selection_from_mask(mask_bytes, target_size=target_size, expand_px=expand_px, blur_px=blur_px)
    out = Image.new("RGBA", target_size, (255, 255, 255, 255))
    out_pixels = out.load()
    sel_pixels = selection.load()
    width, height = selection.size
    for y in range(height):
        for x in range(width):
            if sel_pixels[x, y] > 10:
                out_pixels[x, y] = (255, 255, 255, 0)
    buf = BytesIO()
    out.save(buf, format="PNG")
    return buf.getvalue(), coverage


def _gfa_generator_selection_from_mask(mask_bytes: bytes, *, target_size: tuple[int, int], expand_px: int = 21, blur_px: int = 3):
    try:
        from PIL import Image
        from PIL import ImageFilter
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_mask_error:pillow_missing:{exc}")

    if not mask_bytes:
        raise RuntimeError("image_edit_mask_missing")
    try:
        mask = Image.open(BytesIO(mask_bytes)).convert("RGBA")
    except Exception as exc:
        raise RuntimeError(f"image_edit_mask_invalid:{exc}")
    if mask.size != target_size:
        mask = mask.resize(target_size)
    pixels = mask.load()
    width, height = mask.size
    painted = 0
    out = Image.new("L", mask.size, 0)
    out_pixels = out.load()
    for y in range(height):
        for x in range(width):
            r, g, b, a = pixels[x, y]
            is_painted = a > 10 and (r > 10 or g > 10 or b > 10)
            if is_painted:
                painted += 1
                out_pixels[x, y] = 255
    coverage = painted / float(max(1, width * height))
    if coverage <= 0.001:
        raise RuntimeError("image_edit_mask_empty")
    if expand_px > 1:
        size = max(3, int(expand_px) | 1)
        out = out.filter(ImageFilter.MaxFilter(size))
    if blur_px > 0:
        out = out.filter(ImageFilter.GaussianBlur(float(blur_px)))
    return out, coverage


def _gfa_generator_selection_mask_bytes(selection, *, threshold_floor: int = 10, binary: bool = False) -> bytes:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_selection_mask_error:pillow_missing:{exc}")
    mask = selection.convert("L")
    floor = max(0, min(254, int(threshold_floor)))
    if binary:
        mask = mask.point(lambda value: 255 if value > floor else 0)
    elif floor > 0:
        mask = mask.point(lambda value: value if value > floor else 0)
    buf = BytesIO()
    mask.save(buf, format="PNG")
    return buf.getvalue()


def _gfa_generator_api_mask_to_selection_bytes(api_mask_bytes: bytes) -> bytes:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_generation_mask_error:pillow_missing:{exc}")
    try:
        api_mask = Image.open(BytesIO(api_mask_bytes)).convert("RGBA")
    except Exception as exc:
        raise RuntimeError(f"image_generation_mask_error:{exc}")
    selection = api_mask.getchannel("A").point(lambda value: 255 - value)
    return _gfa_generator_selection_mask_bytes(selection, threshold_floor=0, binary=True)


def _gfa_generator_selection_mask_stats(mask_bytes: bytes) -> dict:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_selection_mask_stats_error:pillow_missing:{exc}")
    try:
        mask = Image.open(BytesIO(mask_bytes)).convert("L")
    except Exception as exc:
        raise RuntimeError(f"image_selection_mask_stats_error:{exc}")
    values = list(mask.getdata())
    editable = sum(1 for value in values if value > 0)
    total = max(1, len(values))
    return {
        "width": mask.size[0],
        "height": mask.size[1],
        "editable_pixels": editable,
        "editable_ratio": round(editable / float(total), 6),
    }


GFA_PRODUCT_TARGET_PADDING_PX = 56
GFA_PRODUCT_TARGET_COMMIT_FEATHER_PX = 3


def _gfa_generator_mask_bbox(mask_bytes: bytes, *, rgba_semantic: bool = False) -> dict | None:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_mask_bbox_error:pillow_missing:{exc}")
    try:
        image = Image.open(BytesIO(mask_bytes))
        if rgba_semantic:
            mask = image.convert("RGBA")
        else:
            mask = image.convert("L")
    except Exception as exc:
        raise RuntimeError(f"image_mask_bbox_error:{exc}")
    width, height = mask.size
    pixels = mask.load()
    xs: list[int] = []
    ys: list[int] = []
    for y in range(height):
        for x in range(width):
            if rgba_semantic:
                r, g, b, a = pixels[x, y]
                selected = a > 10 and (r > 10 or g > 10 or b > 10)
            else:
                selected = pixels[x, y] > 0
            if selected:
                xs.append(x)
                ys.append(y)
    if not xs:
        return None
    x_min = min(xs)
    x_max = max(xs)
    y_min = min(ys)
    y_max = max(ys)
    return {
        "x": x_min,
        "y": y_min,
        "w": x_max - x_min + 1,
        "h": y_max - y_min + 1,
        "xMin": x_min,
        "yMin": y_min,
        "xMax": x_max,
        "yMax": y_max,
    }


def _gfa_generator_bbox_union(*boxes: dict | None) -> dict | None:
    valid = [box for box in boxes if isinstance(box, dict)]
    if not valid:
        return None
    x_min = min(int(box["xMin"]) for box in valid)
    y_min = min(int(box["yMin"]) for box in valid)
    x_max = max(int(box["xMax"]) for box in valid)
    y_max = max(int(box["yMax"]) for box in valid)
    return {"x": x_min, "y": y_min, "w": x_max - x_min + 1, "h": y_max - y_min + 1, "xMin": x_min, "yMin": y_min, "xMax": x_max, "yMax": y_max}


def _gfa_generator_bbox_pad_and_clamp(box: dict, *, padding_px: int, bounds: dict, target_size: tuple[int, int]) -> dict:
    width, height = target_size
    x_min = max(0, int(box["xMin"]) - int(padding_px))
    y_min = max(0, int(box["yMin"]) - int(padding_px))
    x_max = min(width - 1, int(box["xMax"]) + int(padding_px))
    y_max = min(height - 1, int(box["yMax"]) + int(padding_px))
    if isinstance(bounds, dict):
        x_min = max(x_min, int(bounds["xMin"]))
        y_min = max(y_min, int(bounds["yMin"]))
        x_max = min(x_max, int(bounds["xMax"]))
        y_max = min(y_max, int(bounds["yMax"]))
    if x_max < x_min or y_max < y_min:
        x_min, y_min, x_max, y_max = int(box["xMin"]), int(box["yMin"]), int(box["xMax"]), int(box["yMax"])
    return {"x": x_min, "y": y_min, "w": x_max - x_min + 1, "h": y_max - y_min + 1, "xMin": x_min, "yMin": y_min, "xMax": x_max, "yMax": y_max}


def _gfa_generator_mask_outside_count(inner_mask_bytes: bytes, outer_mask_bytes: bytes, *, rgba_inner: bool = False) -> int:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_mask_containment_error:pillow_missing:{exc}")
    try:
        inner_img = Image.open(BytesIO(inner_mask_bytes))
        outer = Image.open(BytesIO(outer_mask_bytes)).convert("L")
        inner = inner_img.convert("RGBA") if rgba_inner else inner_img.convert("L")
    except Exception as exc:
        raise RuntimeError(f"image_mask_containment_error:{exc}")
    if inner.size != outer.size:
        raise RuntimeError("image_mask_containment_error:size_mismatch")
    inner_px = inner.load()
    outer_px = outer.load()
    width, height = inner.size
    count = 0
    for y in range(height):
        for x in range(width):
            if rgba_inner:
                r, g, b, a = inner_px[x, y]
                selected = a > 10 and (r > 10 or g > 10 or b > 10)
            else:
                selected = inner_px[x, y] > 0
            if selected and outer_px[x, y] <= 0:
                count += 1
    return count


def _gfa_generator_commit_mask_policy(edit_flags: dict) -> dict:
    if bool((edit_flags or {}).get("product")):
        return {"intent": "product", "expand_px": 7, "feather_px": 2}
    if bool((edit_flags or {}).get("hair")):
        return {"intent": "hair", "expand_px": 13, "feather_px": 3}
    return {"intent": "local", "expand_px": 9, "feather_px": 2}


def _gfa_generator_prepare_commit_mask(mask_bytes: bytes, *, target_size: tuple[int, int], edit_flags: dict) -> tuple[bytes, dict]:
    policy = _gfa_generator_commit_mask_policy(edit_flags)
    selection, _coverage = _gfa_generator_selection_from_mask(
        mask_bytes,
        target_size=target_size,
        expand_px=int(policy["expand_px"]),
        blur_px=int(policy["feather_px"]),
    )
    return _gfa_generator_selection_mask_bytes(selection, threshold_floor=10, binary=False), policy


def _gfa_generator_prepare_product_target_geometry(
    semantic_mask_bytes: bytes,
    *,
    clear_mask_bytes: bytes,
    generation_mask_bytes: bytes,
    target_size: tuple[int, int],
) -> tuple[bytes, dict]:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_product_target_geometry_error:pillow_missing:{exc}")
    semantic_bbox = _gfa_generator_mask_bbox(semantic_mask_bytes, rgba_semantic=True)
    clear_bbox = _gfa_generator_mask_bbox(clear_mask_bytes)
    generation_bbox = _gfa_generator_mask_bbox(generation_mask_bytes)
    base_bbox = _gfa_generator_bbox_union(semantic_bbox, clear_bbox)
    if not base_bbox or not generation_bbox:
        raise RuntimeError("image_product_target_geometry_error:missing_bbox")
    padding_px = int(os.getenv("GFA_PRODUCT_TARGET_PADDING_PX") or GFA_PRODUCT_TARGET_PADDING_PX)
    target_bbox = _gfa_generator_bbox_pad_and_clamp(base_bbox, padding_px=padding_px, bounds=generation_bbox, target_size=target_size)
    try:
        generation = Image.open(BytesIO(generation_mask_bytes)).convert("L")
    except Exception as exc:
        raise RuntimeError(f"image_product_target_geometry_error:generation_mask:{exc}")
    target = Image.new("L", target_size, 0)
    target_px = target.load()
    generation_px = generation.load()
    for y in range(int(target_bbox["yMin"]), int(target_bbox["yMax"]) + 1):
        for x in range(int(target_bbox["xMin"]), int(target_bbox["xMax"]) + 1):
            if generation_px[x, y] > 0:
                target_px[x, y] = 255
    target_bytes = _gfa_generator_selection_mask_bytes(target, threshold_floor=0, binary=True)
    target_stats = _gfa_generator_selection_mask_stats(target_bytes)
    summary = {
        "enabled": True,
        "semanticBBox": semantic_bbox,
        "clearBBox": clear_bbox,
        "baseBBox": base_bbox,
        "targetBBox": _gfa_generator_mask_bbox(target_bytes),
        "generationBBox": generation_bbox,
        "paddingPx": padding_px,
        "targetEditableRatio": target_stats.get("editable_ratio"),
        "semanticOutsideTargetPixels": _gfa_generator_mask_outside_count(semantic_mask_bytes, target_bytes, rgba_inner=True),
        "clearOutsideTargetPixels": _gfa_generator_mask_outside_count(clear_mask_bytes, target_bytes),
        "targetOutsideGenerationPixels": _gfa_generator_mask_outside_count(target_bytes, generation_mask_bytes),
    }
    summary["invariants"] = {
        "semanticInsideTarget": summary["semanticOutsideTargetPixels"] == 0,
        "clearInsideTarget": summary["clearOutsideTargetPixels"] == 0,
        "targetInsideGeneration": summary["targetOutsideGenerationPixels"] == 0,
    }
    return target_bytes, summary


def _gfa_generator_prepare_product_commit_mask(product_target_mask_bytes: bytes, *, generation_mask_bytes: bytes) -> tuple[bytes, dict]:
    try:
        from PIL import Image
        from PIL import ImageFilter
        from PIL import ImageChops
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_product_commit_mask_error:pillow_missing:{exc}")
    try:
        target = Image.open(BytesIO(product_target_mask_bytes)).convert("L")
        generation = Image.open(BytesIO(generation_mask_bytes)).convert("L")
    except Exception as exc:
        raise RuntimeError(f"image_product_commit_mask_error:{exc}")
    if target.size != generation.size:
        raise RuntimeError("image_product_commit_mask_error:size_mismatch")
    feather_px = int(os.getenv("GFA_PRODUCT_TARGET_COMMIT_FEATHER_PX") or GFA_PRODUCT_TARGET_COMMIT_FEATHER_PX)
    commit = target.filter(ImageFilter.GaussianBlur(float(max(0, feather_px)))) if feather_px > 0 else target
    commit = commit.point(lambda value: value if value > 10 else 0)
    commit = ImageChops.multiply(commit, generation.point(lambda value: 255 if value > 0 else 0))
    policy = {
        "intent": "product_target_geometry",
        "target_padding_px": int(os.getenv("GFA_PRODUCT_TARGET_PADDING_PX") or GFA_PRODUCT_TARGET_PADDING_PX),
        "commit_feather_px": feather_px,
    }
    return _gfa_generator_selection_mask_bytes(commit, threshold_floor=10, binary=False), policy


def _gfa_generator_openai_mask_from_selection(selection_mask_bytes: bytes, *, target_size: tuple[int, int]) -> bytes:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_harmonization_mask_error:pillow_missing:{exc}")
    try:
        selection = Image.open(BytesIO(selection_mask_bytes)).convert("L")
    except Exception as exc:
        raise RuntimeError(f"image_harmonization_mask_error:{exc}")
    if selection.size != target_size:
        raise RuntimeError("image_harmonization_mask_error:size_mismatch")
    out = Image.new("RGBA", target_size, (255, 255, 255, 255))
    out_px = out.load()
    sel_px = selection.load()
    width, height = target_size
    for y in range(height):
        for x in range(width):
            if sel_px[x, y] > 0:
                out_px[x, y] = (255, 255, 255, 0)
    buf = BytesIO()
    out.save(buf, format="PNG")
    return buf.getvalue()


def _gfa_generator_prepare_reference_product_foreground(reference_bytes: bytes, *, reference_mime: str | None = None) -> dict:
    try:
        from PIL import Image
        from PIL import ImageFilter
        from io import BytesIO
        from collections import deque
    except Exception as exc:
        raise RuntimeError(f"image_edit_product_reference_foreground_invalid:pillow_missing:{exc}")
    try:
        original = Image.open(BytesIO(reference_bytes)).convert("RGBA")
    except Exception as exc:
        raise RuntimeError(f"image_edit_product_reference_background_unsupported:{exc}")
    width, height = original.size
    if width < 16 or height < 16:
        raise RuntimeError("image_edit_product_reference_foreground_invalid:size_too_small")
    alpha = original.getchannel("A")
    alpha_values = list(alpha.getdata())
    has_alpha = any(value < 250 for value in alpha_values)
    background = Image.new("L", original.size, 0)
    if has_alpha:
        background = alpha.point(lambda value: 0 if value > 10 else 255)
        method = "alpha"
    else:
        rgb = original.convert("RGB")
        pix = rgb.load()
        border_points = []
        for x in range(width):
            border_points.append(pix[x, 0])
            border_points.append(pix[x, height - 1])
        for y in range(height):
            border_points.append(pix[0, y])
            border_points.append(pix[width - 1, y])
        bg = tuple(int(sum(point[i] for point in border_points) / max(1, len(border_points))) for i in range(3))

        def is_background_pixel(x: int, y: int) -> bool:
            r, g, b = pix[x, y]
            light = min(r, g, b) >= 205 and (max(r, g, b) - min(r, g, b)) <= 52
            dist = abs(r - bg[0]) + abs(g - bg[1]) + abs(b - bg[2])
            return light or (dist <= 78 and min(r, g, b) >= 185)

        bg_px = background.load()
        seen = set()
        q = deque()
        for x in range(width):
            for y in (0, height - 1):
                if is_background_pixel(x, y):
                    q.append((x, y))
                    seen.add((x, y))
        for y in range(height):
            for x in (0, width - 1):
                if (x, y) not in seen and is_background_pixel(x, y):
                    q.append((x, y))
                    seen.add((x, y))
        while q:
            x, y = q.popleft()
            bg_px[x, y] = 255
            for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                if nx < 0 or ny < 0 or nx >= width or ny >= height or (nx, ny) in seen:
                    continue
                if is_background_pixel(nx, ny):
                    seen.add((nx, ny))
                    q.append((nx, ny))
        method = "border_connected_light_background"
    fg_binary = background.point(lambda value: 0 if value > 0 else 255)
    fg_px = fg_binary.load()
    visited = set()
    components = []
    for y in range(height):
        for x in range(width):
            if fg_px[x, y] <= 0 or (x, y) in visited:
                continue
            q = deque([(x, y)])
            visited.add((x, y))
            xs: list[int] = []
            ys: list[int] = []
            while q:
                cx, cy = q.popleft()
                xs.append(cx)
                ys.append(cy)
                for nx, ny in ((cx - 1, cy), (cx + 1, cy), (cx, cy - 1), (cx, cy + 1)):
                    if nx < 0 or ny < 0 or nx >= width or ny >= height or (nx, ny) in visited:
                        continue
                    if fg_px[nx, ny] > 0:
                        visited.add((nx, ny))
                        q.append((nx, ny))
            if xs:
                components.append((len(xs), min(xs), min(ys), max(xs), max(ys)))
    if not components:
        raise RuntimeError("image_edit_product_reference_foreground_empty")
    components.sort(reverse=True)
    _area, x0, y0, x1, y1 = components[0]
    bbox = {"x": x0, "y": y0, "w": x1 - x0 + 1, "h": y1 - y0 + 1, "xMin": x0, "yMin": y0, "xMax": x1, "yMax": y1}
    foreground_ratio = round(_area / float(max(1, width * height)), 6)
    if foreground_ratio <= 0.02 or foreground_ratio >= 0.85:
        raise RuntimeError(f"image_edit_product_reference_foreground_invalid:ratio={foreground_ratio:.4f}")
    if not has_alpha and (bbox["xMin"] <= 1 or bbox["yMin"] <= 1 or bbox["xMax"] >= width - 2 or bbox["yMax"] >= height - 2):
        raise RuntimeError("image_edit_product_reference_foreground_invalid:border_connected_foreground")
    component_mask = Image.new("L", original.size, 0)
    cmp_px = component_mask.load()
    for y in range(y0, y1 + 1):
        for x in range(x0, x1 + 1):
            if fg_px[x, y] > 0:
                cmp_px[x, y] = 255
    soft_mask = component_mask.filter(ImageFilter.GaussianBlur(0.6)).point(lambda value: value if value > 8 else 0)
    foreground = original.copy()
    foreground.putalpha(soft_mask)
    tight = foreground.crop((x0, y0, x1 + 1, y1 + 1))
    tight_mask = soft_mask.crop((x0, y0, x1 + 1, y1 + 1))

    def png_bytes(image) -> bytes:
        buf = BytesIO()
        image.save(buf, format="PNG")
        return buf.getvalue()

    return {
        "image": foreground,
        "mask": soft_mask,
        "tight": tight,
        "tightMask": tight_mask,
        "referenceOriginalPng": png_bytes(original),
        "backgroundMaskPng": png_bytes(background),
        "foregroundMaskPng": png_bytes(soft_mask),
        "foregroundPng": png_bytes(foreground),
        "tightCropPng": png_bytes(tight),
        "summary": {
            "status": "PASS",
            "method": method,
            "referenceWidth": width,
            "referenceHeight": height,
            "referenceMime": reference_mime,
            "hasAlpha": bool(has_alpha),
            "backgroundType": "transparent_alpha" if has_alpha else "simple_white_light",
            "foregroundBBox": bbox,
            "foregroundRatio": foreground_ratio,
            "foregroundAspectRatio": round(float(bbox["w"]) / float(max(1, bbox["h"])), 6),
            "tightCrop": {"width": tight.size[0], "height": tight.size[1]},
        },
    }


def _gfa_generator_prepare_deterministic_product_placement(
    source_cleared_bytes: bytes,
    *,
    reference_bytes: bytes,
    reference_mime: str | None,
    clear_mask_bytes: bytes,
    target_size: tuple[int, int],
    placement_bbox: dict | None = None,
    include_clear_in_harmonization: bool = True,
) -> dict:
    try:
        from PIL import Image
        from PIL import ImageFilter
        from PIL import ImageChops
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_edit_product_deterministic_placement_error:pillow_missing:{exc}")
    foreground = _gfa_generator_prepare_reference_product_foreground(reference_bytes, reference_mime=reference_mime)
    try:
        source_cleared = Image.open(BytesIO(source_cleared_bytes)).convert("RGBA")
        clear_mask = Image.open(BytesIO(clear_mask_bytes)).convert("L")
    except Exception as exc:
        raise RuntimeError(f"image_edit_product_deterministic_placement_error:{exc}")
    if source_cleared.size != target_size or clear_mask.size != target_size:
        raise RuntimeError("image_edit_product_deterministic_placement_error:size_mismatch")
    placement_bbox = placement_bbox if isinstance(placement_bbox, dict) else _gfa_generator_mask_bbox(clear_mask_bytes)
    if not placement_bbox:
        raise RuntimeError("image_edit_product_deterministic_placement_error:missing_clear_bbox")
    tight = foreground["tight"]
    tight_mask = foreground["tightMask"]
    scale = min(float(placement_bbox["w"]) / float(max(1, tight.size[0])), float(placement_bbox["h"]) / float(max(1, tight.size[1])))
    placed_w = max(1, int(round(tight.size[0] * scale)))
    placed_h = max(1, int(round(tight.size[1] * scale)))
    center_x = float(placement_bbox["xMin"] + placement_bbox["xMax"] + 1) / 2.0
    bottom_y = float(placement_bbox["yMax"])
    left = int(round(center_x - (placed_w / 2.0)))
    top = int(round(bottom_y - placed_h + 1))
    right = left + placed_w - 1
    bottom = top + placed_h - 1
    if left < 0 or top < 0 or right >= target_size[0] or bottom >= target_size[1]:
        raise RuntimeError("image_edit_product_deterministic_placement_error:placement_out_of_bounds")
    placed = tight.resize((placed_w, placed_h), Image.Resampling.LANCZOS)
    placed_mask = tight_mask.resize((placed_w, placed_h), Image.Resampling.LANCZOS).point(lambda value: value if value > 8 else 0)
    placed.putalpha(placed_mask)
    layer = Image.new("RGBA", target_size, (255, 255, 255, 0))
    layer.alpha_composite(placed, (left, top))
    mask_layer = Image.new("L", target_size, 0)
    mask_layer.paste(placed_mask, (left, top))
    temp = source_cleared.copy()
    temp.alpha_composite(layer)
    ring_px = max(10, min(24, int(round(min(placed_w, placed_h) * 0.06))))
    grounding_px = max(14, min(40, int(round(placed_h * 0.09))))
    binary_product = mask_layer.point(lambda value: 255 if value > 10 else 0)
    clear_binary = clear_mask.point(lambda value: 255 if value > 0 else 0)
    outer = binary_product.filter(ImageFilter.MaxFilter(max(3, (ring_px * 2 + 1) | 1)))
    ring = ImageChops.subtract(outer, binary_product)
    ground = Image.new("L", target_size, 0)
    ground_px = ground.load()
    gx0 = max(0, left - ring_px)
    gx1 = min(target_size[0] - 1, right + ring_px)
    gy0 = max(0, bottom - max(4, grounding_px // 3))
    gy1 = min(target_size[1] - 1, bottom + grounding_px)
    for y in range(gy0, gy1 + 1):
        for x in range(gx0, gx1 + 1):
            ground_px[x, y] = 255
    if include_clear_in_harmonization:
        harmonization_generation = ImageChops.lighter(ImageChops.lighter(ring, ground), clear_binary)
    else:
        harmonization_generation = ImageChops.lighter(ring, ground)
    harmonization_generation = ImageChops.subtract(harmonization_generation, binary_product)
    harmonization_commit = harmonization_generation.filter(ImageFilter.GaussianBlur(2.0)).point(lambda value: value if value > 10 else 0)
    harmonization_commit = ImageChops.subtract(harmonization_commit, binary_product)
    api_mask = _gfa_generator_openai_mask_from_selection(_gfa_generator_selection_mask_bytes(harmonization_generation, threshold_floor=10, binary=True), target_size=target_size)

    def png_bytes(image) -> bytes:
        buf = BytesIO()
        image.save(buf, format="PNG")
        return buf.getvalue()

    placed_bbox = {"x": left, "y": top, "w": placed_w, "h": placed_h, "xMin": left, "yMin": top, "xMax": right, "yMax": bottom}
    fg_summary = foreground["summary"]
    aspect = round(float(placed_w) / float(max(1, placed_h)), 6)
    target_center = round(center_x, 3)
    placed_center = round(float(left + right + 1) / 2.0, 3)
    summary = {
        "enabled": True,
        "foregroundExtraction": fg_summary,
        "reference": {
            "width": fg_summary.get("referenceWidth"),
            "height": fg_summary.get("referenceHeight"),
            "foregroundBBox": fg_summary.get("foregroundBBox"),
            "foregroundAspectRatio": fg_summary.get("foregroundAspectRatio"),
        },
        "target": {
            "bbox": placement_bbox,
            "centerX": target_center,
            "bottomY": int(placement_bbox["yMax"]),
        },
        "placement": {
            "targetBBox": placement_bbox,
            "placedBBox": placed_bbox,
            "scaleFactor": round(scale, 6),
            "width": placed_w,
            "height": placed_h,
            "left": left,
            "top": top,
            "right": right,
            "bottom": bottom,
            "aspectRatio": aspect,
            "bottomCenterAligned": abs(placed_center - target_center) <= 0.5 and bottom == int(placement_bbox["yMax"]),
            "aspectPreserved": abs(aspect - float(fg_summary.get("foregroundAspectRatio") or aspect)) <= 0.01,
        },
        "authority": {
            "scale": "DETERMINISTIC",
            "position": "DETERMINISTIC",
            "aspect": "REFERENCE_FOREGROUND",
            "productPixels": "REFERENCE",
        },
        "harmonization": {
            "ringPx": ring_px,
            "groundingPx": grounding_px,
            "clearRemainderIncluded": True,
            "generationMaskRatio": _gfa_generator_selection_mask_stats(png_bytes(harmonization_generation)).get("editable_ratio"),
            "commitMaskRatio": _gfa_generator_selection_mask_stats(png_bytes(harmonization_commit)).get("editable_ratio"),
        },
    }
    return {
        "summary": summary,
        "referenceOriginalPng": foreground["referenceOriginalPng"],
        "backgroundMaskPng": foreground["backgroundMaskPng"],
        "foregroundMaskPng": foreground["foregroundMaskPng"],
        "foregroundPng": foreground["foregroundPng"],
        "tightCropPng": foreground["tightCropPng"],
        "placedProductLayerPng": png_bytes(layer),
        "placedProductMaskPng": png_bytes(mask_layer),
        "temporaryProductCompositePng": png_bytes(temp),
        "harmonizationGenerationMaskPng": png_bytes(harmonization_generation),
        "harmonizationCommitMaskPng": png_bytes(harmonization_commit),
        "harmonizationApiMaskPng": api_mask,
    }


def _gfa_generator_compose_generation_product_layer(
    base_bytes: bytes,
    *,
    product_reference: dict,
    slot_context: dict,
) -> dict:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"gfa_generation_product_layer_error:pillow_missing:{exc}")
    try:
        base = Image.open(BytesIO(base_bytes)).convert("RGBA")
    except Exception as exc:
        raise RuntimeError(f"gfa_generation_product_layer_error:base_invalid:{exc}")
    target_size = base.size
    ref_bytes = product_reference.get("bytes") if isinstance(product_reference.get("bytes"), (bytes, bytearray)) else b""
    if not ref_bytes:
        raise RuntimeError("gfa_generation_product_layer_error:product_reference_missing")
    foreground = _gfa_generator_prepare_reference_product_foreground(
        bytes(ref_bytes),
        reference_mime=str(product_reference.get("mimeType") or "image/png"),
    )
    slot = slot_context.get("slot") if isinstance(slot_context.get("slot"), dict) else {}
    anchor = str(slot_context.get("anchor") or "BOTTOM_CENTER").strip() or "BOTTOM_CENTER"
    if anchor != "BOTTOM_CENTER":
        raise RuntimeError(f"gfa_generation_product_layer_error:unsupported_anchor:{anchor}")
    canvas_w, canvas_h = target_size
    slot_x = int(round(float(slot.get("xRatio")) * canvas_w))
    slot_y = int(round(float(slot.get("yRatio")) * canvas_h))
    slot_w = int(round(float(slot.get("widthRatio")) * canvas_w))
    slot_h = int(round(float(slot.get("heightRatio")) * canvas_h))
    if slot_w <= 0 or slot_h <= 0:
        raise RuntimeError("gfa_generation_product_layer_error:invalid_slot")
    slot_x = max(0, min(canvas_w - 1, slot_x))
    slot_y = max(0, min(canvas_h - 1, slot_y))
    slot_w = max(1, min(canvas_w - slot_x, slot_w))
    slot_h = max(1, min(canvas_h - slot_y, slot_h))
    slot_bbox = {
        "x": slot_x,
        "y": slot_y,
        "w": slot_w,
        "h": slot_h,
        "width": slot_w,
        "height": slot_h,
        "xMin": slot_x,
        "yMin": slot_y,
        "xMax": slot_x + slot_w - 1,
        "yMax": slot_y + slot_h - 1,
    }
    tight = foreground["tight"]
    tight_mask = foreground["tightMask"]
    scale = min(float(slot_w) / float(max(1, tight.size[0])), float(slot_h) / float(max(1, tight.size[1])))
    placed_w = max(1, int(round(tight.size[0] * scale)))
    placed_h = max(1, int(round(tight.size[1] * scale)))
    center_x = float(slot_bbox["xMin"] + slot_bbox["xMax"] + 1) / 2.0
    bottom_y = float(slot_bbox["yMax"])
    left = int(round(center_x - (placed_w / 2.0)))
    top = int(round(bottom_y - placed_h + 1))
    right = left + placed_w - 1
    bottom = top + placed_h - 1
    if left < 0 or top < 0 or right >= canvas_w or bottom >= canvas_h:
        raise RuntimeError("gfa_generation_product_layer_error:placement_out_of_bounds")
    placed = tight.resize((placed_w, placed_h), Image.Resampling.LANCZOS)
    placed_mask = tight_mask.resize((placed_w, placed_h), Image.Resampling.LANCZOS).point(lambda value: value if value > 8 else 0)
    placed.putalpha(placed_mask)
    layer = Image.new("RGBA", target_size, (255, 255, 255, 0))
    layer.alpha_composite(placed, (left, top))
    final = base.copy()
    final.alpha_composite(layer)

    def png_bytes(image) -> bytes:
        buf = BytesIO()
        image.save(buf, format="PNG")
        return buf.getvalue()

    layer_bytes = png_bytes(layer)
    foreground_bytes = foreground["foregroundPng"]
    final_bytes = png_bytes(final)
    source_path = _gfa_generator_write_image_file(bytes(ref_bytes), str(product_reference.get("mimeType") or "image/png"), prefix="gfa_product_source")
    layer_path = _gfa_generator_write_image_file(layer_bytes, "image/png", prefix="gfa_product_layer")
    foreground_path = _gfa_generator_write_image_file(foreground_bytes, "image/png", prefix="gfa_product_foreground")
    debug_id = uuid.uuid4().hex
    debug_dir = os.path.join(_gfa_generated_image_dir(), "generation-product-debug", debug_id)
    os.makedirs(debug_dir, exist_ok=True)
    _gfa_local_edit_debug_write(debug_dir, "base-product-free.png", base_bytes)
    _gfa_local_edit_debug_write(debug_dir, "product-authoritative-source.png", bytes(ref_bytes))
    _gfa_local_edit_debug_write(debug_dir, "product-foreground.png", foreground_bytes)
    _gfa_local_edit_debug_write(debug_dir, "product-render-layer.png", layer_bytes)
    _gfa_local_edit_debug_write(debug_dir, "final-generated-banner.png", final_bytes)
    placed_bbox = {"x": left, "y": top, "w": placed_w, "h": placed_h, "width": placed_w, "height": placed_h, "xMin": left, "yMin": top, "xMax": right, "yMax": bottom}
    aspect = round(float(placed_w) / float(max(1, placed_h)), 6)
    fg_aspect = float((foreground.get("summary") or {}).get("foregroundAspectRatio") or aspect)
    summary = {
        "productGeneration": {
            "placementIntent": slot_context.get("placementIntent"),
            "geometryAuthority": GFA_PRODUCT_PLACEMENT_AUTHORITY,
            "slotContractVersion": slot_context.get("slotContractVersion"),
            "anchor": anchor,
            "fitPolicy": "FIT_INSIDE_PRODUCT_SLOT",
            "productFreeBase": True,
            "ghostProduct": "UNKNOWN_RUNTIME_VISUAL_QA_REQUIRED",
        },
        "slot": slot_bbox,
        "placement": {
            "targetBBox": slot_bbox,
            "placedBBox": placed_bbox,
            "scaleFactor": round(scale, 6),
            "bottomCenterAligned": abs(round(float(left + right + 1) / 2.0, 3) - round(center_x, 3)) <= 0.5 and bottom == int(slot_bbox["yMax"]),
            "aspectPreserved": abs(aspect - fg_aspect) <= 0.01,
            "aspectRatio": aspect,
        },
        "foregroundExtraction": foreground["summary"],
        "paths": {
            "sourcePath": source_path,
            "layerPath": layer_path,
            "foregroundPath": foreground_path,
            "debugDir": debug_dir,
        },
    }
    _gfa_local_edit_debug_write_json(debug_dir, "debug-summary.json", summary)
    return {
        "finalCompositePng": final_bytes,
        "productLayerPng": layer_bytes,
        "foregroundPng": foreground_bytes,
        "summary": summary,
        "placementIntent": slot_context.get("placementIntent"),
        "slotContractVersion": slot_context.get("slotContractVersion"),
        "slotContractPath": slot_context.get("slotContractPath"),
        "anchor": anchor,
        "slot": {
            **slot,
            "bbox": slot_bbox,
        },
        "canvas": {"width": canvas_w, "height": canvas_h},
        "geometry": placed_bbox,
        "scaleFactor": round(scale, 6),
        "source": {"path": source_path, "sha256": str(product_reference.get("sha256") or ""), "mimeType": str(product_reference.get("mimeType") or "image/png")},
        "layer": {"path": layer_path, "sha256": _sha256_bytes(layer_bytes), "mimeType": "image/png"},
        "foregroundPath": foreground_path,
        "debugDir": debug_dir,
    }


def _gfa_generator_reoverlay_product_layer(base_bytes: bytes, product_layer_bytes: bytes) -> bytes:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_product_reoverlay_error:pillow_missing:{exc}")
    try:
        base = Image.open(BytesIO(base_bytes)).convert("RGBA")
        layer = Image.open(BytesIO(product_layer_bytes)).convert("RGBA")
    except Exception as exc:
        raise RuntimeError(f"image_product_reoverlay_error:{exc}")
    if base.size != layer.size:
        raise RuntimeError("image_product_reoverlay_error:size_mismatch")
    base.alpha_composite(layer)
    buf = BytesIO()
    base.save(buf, format="PNG")
    return buf.getvalue()


def _gfa_generator_product_identity_evidence(final_bytes: bytes, product_layer_bytes: bytes, *, debug_dir: str) -> dict:
    try:
        from PIL import Image
        from PIL import ImageFilter
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_product_identity_error:pillow_missing:{exc}")
    final = Image.open(BytesIO(final_bytes)).convert("RGBA")
    layer = Image.open(BytesIO(product_layer_bytes)).convert("RGBA")
    if final.size != layer.size:
        raise RuntimeError("image_product_identity_error:size_mismatch")
    final_px = final.load()
    layer_px = layer.load()
    core_mask = layer.getchannel("A").point(lambda value: 255 if value >= 250 else 0).filter(ImageFilter.MinFilter(5))
    core_px = core_mask.load()
    diff = Image.new("RGBA", final.size, (0, 0, 0, 255))
    diff_px = diff.load()
    core = changed = 0
    edge_alpha = 0
    for y in range(final.size[1]):
        for x in range(final.size[0]):
            lr, lg, lb, la = layer_px[x, y]
            if la > 0 and core_px[x, y] <= 0:
                edge_alpha += 1
            if core_px[x, y] > 0:
                core += 1
                fr, fg, fb, _fa = final_px[x, y]
                if (fr, fg, fb) != (lr, lg, lb):
                    changed += 1
                    diff_px[x, y] = (255, 0, 0, 255)
                else:
                    diff_px[x, y] = (0, 0, 0, 255)
    path = os.path.join(debug_dir, "product-identity-diff.png")
    diff.save(path, format="PNG")
    return {
        "authority": "REFERENCE_PIXELS",
        "finalReoverlayApplied": True,
        "productBodyCorePixels": core,
        "productBodyCoreChangedPixels": changed,
        "productBodyCoreChangedPixelRatio": round(changed / float(max(1, core)), 6),
        "edgeAlphaPixels": edge_alpha,
        "productIdentityDiffPath": path,
    }


def _gfa_generator_write_product_edge_review(final_bytes: bytes, product_layer_bytes: bytes, *, placed_bbox: dict, debug_dir: str) -> str:
    try:
        from PIL import Image
        from PIL import ImageDraw
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_product_edge_review_error:pillow_missing:{exc}")
    final = Image.open(BytesIO(final_bytes)).convert("RGBA")
    layer = Image.open(BytesIO(product_layer_bytes)).convert("RGBA")
    if final.size != layer.size:
        raise RuntimeError("image_product_edge_review_error:size_mismatch")
    pad = 28
    x0 = max(0, int(placed_bbox["xMin"]) - pad)
    y0 = max(0, int(placed_bbox["yMin"]) - pad)
    x1 = min(final.size[0] - 1, int(placed_bbox["xMax"]) + pad)
    y1 = min(final.size[1] - 1, int(placed_bbox["yMax"]) + pad)
    crop = final.crop((x0, y0, x1 + 1, y1 + 1))
    draw = ImageDraw.Draw(crop, "RGBA")
    draw.rectangle((pad, pad, pad + int(placed_bbox["w"]) - 1, pad + int(placed_bbox["h"]) - 1), outline=(255, 214, 10, 255), width=4)
    path = os.path.join(debug_dir, "product-edge-review.png")
    crop.save(path, format="PNG")
    return path


def _gfa_generator_prepare_clear_mask(mask_bytes: bytes, *, target_size: tuple[int, int], edit_flags: dict) -> tuple[bytes, dict]:
    policy = {
        "intent": "product_replace_or_remove" if bool((edit_flags or {}).get("product")) else "object_remove",
        "expand_px": 21,
        "feather_px": 3,
    }
    selection, _coverage = _gfa_generator_selection_from_mask(
        mask_bytes,
        target_size=target_size,
        expand_px=int(policy["expand_px"]),
        blur_px=int(policy["feather_px"]),
    )
    return _gfa_generator_selection_mask_bytes(selection, threshold_floor=10, binary=True), policy


def _gfa_generator_apply_masked_edit_region(source_bytes: bytes, edited_bytes: bytes, commit_mask_bytes: bytes) -> tuple[bytes, str]:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_mask_composite_error:pillow_missing:{exc}")

    try:
        source = Image.open(BytesIO(source_bytes)).convert("RGBA")
        edited = Image.open(BytesIO(edited_bytes)).convert("RGBA")
    except Exception as exc:
        raise RuntimeError(f"image_mask_composite_error:{exc}")
    if edited.size != source.size:
        edited = edited.resize(source.size)
    try:
        commit_mask = Image.open(BytesIO(commit_mask_bytes)).convert("L")
    except Exception as exc:
        raise RuntimeError(f"image_mask_composite_error:commit_mask:{exc}")
    if commit_mask.size != source.size:
        raise RuntimeError(
            f"image_mask_composite_error:commit_mask_size_mismatch:source={source.size[0]}x{source.size[1]},mask={commit_mask.size[0]}x{commit_mask.size[1]}"
        )
    composited = Image.composite(edited, source, commit_mask)
    buf = BytesIO()
    composited.save(buf, format="PNG")
    return buf.getvalue(), "image/png"


def _gfa_generator_clear_masked_region_for_edit(source_bytes: bytes, clear_mask_bytes: bytes, *, target_size: tuple[int, int]) -> bytes:
    try:
        from PIL import Image
        from io import BytesIO
    except Exception as exc:
        raise RuntimeError(f"image_mask_clear_error:pillow_missing:{exc}")

    try:
        source = Image.open(BytesIO(source_bytes)).convert("RGBA")
    except Exception as exc:
        raise RuntimeError(f"image_mask_clear_error:{exc}")
    if source.size != target_size:
        source = source.resize(target_size)
    try:
        selection = Image.open(BytesIO(clear_mask_bytes)).convert("L")
    except Exception as exc:
        raise RuntimeError(f"image_mask_clear_error:clear_mask:{exc}")
    if selection.size != target_size:
        raise RuntimeError(
            f"image_mask_clear_error:clear_mask_size_mismatch:source={target_size[0]}x{target_size[1]},mask={selection.size[0]}x{selection.size[1]}"
        )
    src_pixels = source.load()
    sel_pixels = selection.load()
    width, height = source.size
    for y in range(height):
        for x in range(width):
            if sel_pixels[x, y] > 10:
                r, g, b, _a = src_pixels[x, y]
                src_pixels[x, y] = (r, g, b, 0)
    buf = BytesIO()
    source.save(buf, format="PNG")
    return buf.getvalue()


def _gfa_generator_mask_edit_instruction(user_prompt: str, *, has_reference_images: bool = False) -> str:
    prompt = _collapse_ws_text(user_prompt)
    low = prompt.lower()
    remove_markers = ["삭제", "제거", "지워", "없애", "remove", "delete", "erase"]
    cleanup_markers = ["정리", "깨끗", "자연스럽게", "보정", "cleanup", "clean up"]
    add_markers = ["추가", "넣어", "바꿔", "변경", "replace", "add"]

    intent = "localized retouch"
    if any(x in low or x in prompt for x in remove_markers):
        intent = "object removal / clean fill"
    elif any(x in low or x in prompt for x in add_markers):
        intent = "localized replacement / addition"
    elif any(x in low or x in prompt for x in cleanup_markers):
        intent = "natural cleanup / retouch"

    reference_rule = (
        "When reference images are attached, use them as concrete source material only inside the selected area. "
        if has_reference_images
        else "Do not invent new product packages, labels, text, logos, medical claims, or extra CTA elements. "
    )
    return (
        f"User requested intent: {intent}. "
        "Rewrite the selected masked region only. The final result must look like a natural photo edit, not a newly generated banner. "
        "The green brush/mask color is only an editing focus guide, not the hard boundary or final shape of the generated change. Use the mask as the correction point/anchor and extend the corrected visual naturally inside the expanded edit context when needed. "
        "Never render the mask color, brush stroke, border, outline, black smear, or selection artifact into the final image. "
        "For removal requests, remove the selected object and fill the area with matching background, lighting, texture, edges, shadows, and depth. "
        "For replacement or addition requests, blend the new visual element into the existing scene with realistic perspective, scale, color temperature, and shadows. "
        "For object removal or replacement, do not keep a ghost, remnant, silhouette, shadow patch, duplicated edge, or cropped fragment of the previous object inside the edit area. Reconstruct that region cleanly from surrounding context or the requested replacement. "
        "For hair edits, keep the same person's identity, age impression, face, head angle, neck, shoulder line, clothing, and camera perspective. Do not replace the person with a new model or front-facing portrait unless explicitly requested. "
        "For product edits, replace the product content/style only inside the selected product area while preserving the original position, scale, perspective, grounding, and shadows unless relocation is explicitly requested. "
        "Preserve all unselected pixels exactly. Preserve the person, hair shape, face, product packages, bowls, tools, ingredient props, package count, and labels unless the masked area covers that exact subject and the user explicitly asks to change it. "
        "If the user explicitly asks to change hair length, hair shape, hair color, product size, object position, or background from the masked point, apply that request visibly and let the modified element occupy the natural size/length/space required by the request rather than being clipped to the brush stroke. "
        "Never add readable ad copy, UI boxes, CTA buttons, watermarks, random Korean text, or extra products. "
        f"{reference_rule}"
        f"Original user request: {prompt}"
    )


def _gfa_product_authority_source_bytes(authority: dict) -> tuple[bytes, str]:
    data = authority.get("bytes") if isinstance(authority, dict) else None
    if isinstance(data, (bytes, bytearray)) and data:
        return bytes(data), str(authority.get("sourceMime") or "image/png")
    path = str((authority or {}).get("sourcePath") or "").strip()
    if path and os.path.exists(path):
        with open(path, "rb") as handle:
            return handle.read(), str(authority.get("sourceMime") or "image/png")
    raise RuntimeError("PRODUCT_AUTHORITY_UNAVAILABLE")


def _gfa_generator_edit_image_marked_product_authority(
    *,
    source_image_path: str,
    source_mime: str,
    edit_prompt: str,
    copy_result: dict,
    combination: dict | None = None,
    model: str | None = None,
    mask_bytes: bytes | None = None,
    authority: dict | None = None,
    intent: dict | None = None,
    overlay_after_edit: bool = True,
) -> tuple[str, str, str, str, str, str, dict]:
    from gfa_product_authority import (
        PRODUCT_AUTHORITY_AVAILABLE,
        SCENE_REPAIR_PROMPT,
        l_mask_from_bbox,
        object_workspace_from_user_mark,
        placement_bbox_from_workspace,
    )

    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise RuntimeError("OPENAI_API_KEY not configured")
    if not source_image_path or not os.path.exists(source_image_path):
        raise RuntimeError("base_image_missing_for_image_edit")
    authority = authority if isinstance(authority, dict) else {}
    intent = intent if isinstance(intent, dict) else {}
    if str(authority.get("status") or "") != PRODUCT_AUTHORITY_AVAILABLE:
        raise RuntimeError("PRODUCT_AUTHORITY_UNAVAILABLE")
    reference_bytes, reference_mime = _gfa_product_authority_source_bytes(authority)
    model_name = str(model or os.getenv("GFA_CREATIVE_IMAGE_MODEL") or "gpt-image-2").strip()
    image_size = str(os.getenv("GFA_CREATIVE_IMAGE_SIZE") or "1024x1024").strip() or "1024x1024"
    with open(source_image_path, "rb") as handle:
        source_bytes = handle.read()
    uploaded_mask_bytes = mask_bytes or b""
    mask_bytes, mask_sanitize_stats = _gfa_generator_sanitize_semantic_mask_png(uploaded_mask_bytes)
    try:
        from PIL import Image
        from io import BytesIO

        with Image.open(BytesIO(source_bytes)) as src_img:
            target_size = src_img.size
    except Exception:
        target_size = (1024, 1024)
    workspace = object_workspace_from_user_mark(mask_bytes, target_size=target_size)
    workspace_mask = workspace["maskPng"]
    placement_bbox = placement_bbox_from_workspace(
        workspace["bbox"],
        op=str(intent.get("op") or ""),
        factor=float(intent.get("factor") or 1.22),
        canvas=target_size,
        move_dx_ratio=float(intent.get("moveDxRatio") or 0.0),
        move_dy_ratio=float(intent.get("moveDyRatio") or 0.0),
        contact=str(intent.get("contact") or "BOTTOM_GROUND_CONTACT"),
    )
    placement_mask = l_mask_from_bbox(placement_bbox, target_size)
    debug_id = uuid.uuid4().hex
    debug_dir = _gfa_local_edit_debug_dir(debug_id)
    summary: dict = {
        "debugId": debug_id,
        "operation": "MARKED_PRODUCT_ASSET_EDIT",
        "intent": intent,
        "productAuthority": {k: v for k, v in authority.items() if k != "bytes"},
        "workspace": {k: v for k, v in workspace.items() if k != "maskPng"},
        "placementBBox": placement_bbox,
        "productInstanceCount": 1,
        "apiCallExecuted": False,
    }
    _gfa_local_edit_debug_write(debug_dir, "source.png", source_bytes)
    _gfa_local_edit_debug_write(debug_dir, "semantic-mask-uploaded.png", uploaded_mask_bytes)
    _gfa_local_edit_debug_write(debug_dir, "semantic-mask-input.png", mask_bytes)
    _gfa_local_edit_debug_write(debug_dir, "object-workspace.png", workspace_mask)
    _gfa_local_edit_debug_write(debug_dir, "placement-bbox.png", placement_mask)
    _gfa_local_edit_debug_write(debug_dir, "product-authoritative-source.png", reference_bytes)
    cleared_source_bytes = _gfa_generator_clear_masked_region_for_edit(source_bytes, workspace_mask, target_size=target_size)
    _gfa_local_edit_debug_write(debug_dir, "source-cleared-workspace.png", cleared_source_bytes)
    repair_api_mask = _gfa_generator_openai_mask_from_selection(workspace_mask, target_size=target_size)
    repair_prompt = (
        "Edit this Korean ad banner image conservatively. "
        f"{SCENE_REPAIR_PROMPT} "
        f"Original local edit request for context only: {_collapse_ws_text(edit_prompt)}"
    )
    summary["apiCallExecuted"] = True
    repair_resp = requests.post(
        "https://api.openai.com/v1/images/edits",
        headers={"Authorization": f"Bearer {key}"},
        data={"model": model_name, "prompt": repair_prompt, "size": image_size, "n": "1"},
        files=[
            ("image", ("source.png", cleared_source_bytes, "image/png")),
            ("mask", ("mask.png", repair_api_mask, "image/png")),
        ],
        timeout=180,
    )
    if repair_resp.status_code != 200:
        _gfa_local_edit_debug_write_json(debug_dir, "debug-summary.json", {**summary, "error": "scene_repair_failed"})
        raise RuntimeError(f"openai_image_error:{repair_resp.status_code}:{_safe_err_text(repair_resp, 1200)}")
    repaired_raw, repaired_mime = _gfa_generator_extract_openai_image(repair_resp.json() or {})
    _gfa_local_edit_debug_write(debug_dir, "raw-scene-repair.png", repaired_raw)
    repaired_bytes, _repaired_mime = _gfa_generator_apply_masked_edit_region(source_bytes, repaired_raw, workspace_mask)
    _gfa_local_edit_debug_write(debug_dir, "scene-repaired.png", repaired_bytes)
    deterministic_product = _gfa_generator_prepare_deterministic_product_placement(
        repaired_bytes,
        reference_bytes=reference_bytes,
        reference_mime=reference_mime,
        clear_mask_bytes=workspace_mask,
        target_size=target_size,
        placement_bbox=placement_bbox,
        include_clear_in_harmonization=False,
    )
    product_layer = deterministic_product["placedProductLayerPng"]
    temp_composite = deterministic_product["temporaryProductCompositePng"]
    harmonization_api_mask = deterministic_product["harmonizationApiMaskPng"]
    harmonization_commit = deterministic_product["harmonizationCommitMaskPng"]
    _gfa_local_edit_debug_write(debug_dir, "placed-product-layer.png", product_layer)
    _gfa_local_edit_debug_write(debug_dir, "temporary-product-composite.png", temp_composite)
    _gfa_local_edit_debug_write(debug_dir, "harmonization-api-mask.png", harmonization_api_mask)
    summary["deterministicProductPlacement"] = deterministic_product.get("summary") if isinstance(deterministic_product.get("summary"), dict) else {}
    harmonize_prompt = (
        "Product placement and product pixels are already fixed in the input image. "
        "Preserve the placed product exactly. Do not redraw, resize, reposition, relabel, recolor, redesign, replace, or simplify the product/package. "
        "Only harmonize the immediately surrounding masked area for contact shadow, grounding, local lighting transition, and edge integration. "
        "Preserve all unrelated background, person, hair, table, bowl, and product body pixels. "
        "Place the packshot once only; do not clone extra pouches or packages. "
        f"Original local edit request for context only: {_collapse_ws_text(edit_prompt)}"
    )
    harm_resp = requests.post(
        "https://api.openai.com/v1/images/edits",
        headers={"Authorization": f"Bearer {key}"},
        data={"model": model_name, "prompt": harmonize_prompt, "size": image_size, "n": "1"},
        files=[
            ("image", ("temporary-product-composite.png", temp_composite, "image/png")),
            ("mask", ("mask.png", harmonization_api_mask, "image/png")),
        ],
        timeout=180,
    )
    if harm_resp.status_code != 200:
        _gfa_local_edit_debug_write_json(debug_dir, "debug-summary.json", {**summary, "error": "harmonization_failed"})
        raise RuntimeError(f"openai_image_error:{harm_resp.status_code}:{_safe_err_text(harm_resp, 1200)}")
    harm_raw, _harm_mime = _gfa_generator_extract_openai_image(harm_resp.json() or {})
    _gfa_local_edit_debug_write(debug_dir, "raw-harmonized-result.png", harm_raw)
    base_bytes, base_mime = _gfa_generator_apply_masked_edit_region(temp_composite, harm_raw, harmonization_commit)
    base_bytes = _gfa_generator_reoverlay_product_layer(base_bytes, product_layer)
    base_mime = "image/png"
    _gfa_local_edit_debug_write(debug_dir, "final-composite.png", base_bytes)
    summary["annotationIsolation"] = _gfa_annotation_isolation_evidence(
        source_bytes=source_bytes,
        uploaded_mask_bytes=uploaded_mask_bytes,
        semantic_mask_bytes=mask_bytes,
        sanitize_stats=mask_sanitize_stats,
        api_image_bytes=cleared_source_bytes,
        api_mask_bytes=repair_api_mask,
        raw_ai_bytes=repaired_raw,
        final_bytes=base_bytes,
        composite_base_bytes=source_bytes,
        intentional_source_clear=True,
        stale_overlay_after_result=False,
    )
    try:
        summary["deterministicProductPlacement"]["identity"] = _gfa_generator_product_identity_evidence(
            base_bytes,
            product_layer,
            debug_dir=debug_dir,
        )
    except Exception as exc:
        summary["identityError"] = str(exc)[:300]
    prompt = f"LOCAL_EDIT_DEBUG_ID:{debug_id}\nMARKED_PRODUCT_ASSET_EDIT\n{repair_prompt}"
    _gfa_local_edit_debug_write_json(debug_dir, "debug-summary.json", summary)
    if overlay_after_edit:
        base_path = _gfa_generator_write_image_file(base_bytes, base_mime, prefix="gfa_base_edit")
        img_bytes, mime = _gfa_generator_overlay_copy_on_image(base_bytes, copy_result=copy_result, combination=combination)
        path = _gfa_generator_write_image_file(img_bytes, mime, prefix="gfa_image_edit")
    else:
        path = _gfa_generator_write_image_file(base_bytes, base_mime, prefix="gfa_image_edit")
        mime = base_mime
        base_path = ""
    return path, mime, prompt, f"openai:{model_name}", base_path, base_mime, summary


def _gfa_generator_edit_image_only(*, source_image_path: str, source_mime: str, edit_prompt: str, copy_result: dict, combination: dict | None = None, model: str | None = None, mask_bytes: bytes | None = None, mask_mime: str | None = None, reference_images: list[tuple[str, bytes, str]] | None = None, overlay_after_edit: bool = True) -> tuple[str, str, str, str, str, str]:
    key = _get_api_setting("OPENAI_API_KEY")
    if not key:
        raise RuntimeError("OPENAI_API_KEY not configured")
    if not source_image_path or not os.path.exists(source_image_path):
        raise RuntimeError("base_image_missing_for_image_edit")
    model_name = str(model or os.getenv("GFA_CREATIVE_IMAGE_MODEL") or "gpt-image-2").strip()
    image_size = str(os.getenv("GFA_CREATIVE_IMAGE_SIZE") or "1024x1024").strip() or "1024x1024"
    user_prompt = _collapse_ws_text(edit_prompt)
    if not user_prompt:
        raise RuntimeError("image_edit_prompt_missing")
    envelope_expand_px, envelope_blur_px = _gfa_generator_mask_edit_envelope(user_prompt)
    refs = reference_images if isinstance(reference_images, list) else []
    reference_count = len([ref for ref in refs[:4] if ref and ref[1]])
    edit_flags = _gfa_generator_mask_edit_flags(user_prompt, reference_count=reference_count)
    clear_masked_region = _gfa_generator_should_clear_masked_region(user_prompt, reference_count=reference_count, flags=edit_flags)
    scoped_user_prompt = _gfa_generator_mask_edit_instruction(user_prompt, has_reference_images=bool(refs)) if mask_bytes else user_prompt
    prompt = (
        "Edit this Korean ad banner image conservatively. "
        "CRITICAL PRESERVATION RULES: preserve all existing foreground product/package objects exactly, including pouches, bottles, boxes, bowls, tools, leaves, hair/person, product count, package shapes, label-like marks, relative sizes, and positions unless the user's request explicitly says to change that specific object. "
        "Never remove product packages. Never replace product packages with generic props. Never simplify packages into plain background. "
        "If the user asks to change background, lighting, mood, color, or texture, change only those photographic background areas while keeping products/packages intact. "
        "Do not create ad overlay copy, Korean text, English ad text, CTA buttons, button shapes, or text boxes. Existing visual details that belong to product packaging must be preserved as image details. "
        "Preserve a clean left text-safe area for later server-side overlay without deleting products/packages. Keep the composition commercial and realistic. "
        "Apply this image-only edit request: "
        f"{scoped_user_prompt}"
    )
    with open(source_image_path, "rb") as f:
        source_bytes = f.read()
    uploaded_mask_bytes = mask_bytes or b""
    mask_sanitize_stats: dict | None = None
    if uploaded_mask_bytes:
        mask_bytes, mask_sanitize_stats = _gfa_generator_sanitize_semantic_mask_png(uploaded_mask_bytes)
    debug_id = uuid.uuid4().hex if mask_bytes else ""
    debug_dir = _gfa_local_edit_debug_dir(debug_id) if debug_id else ""
    debug_summary: dict = {
        "debugId": debug_id,
        "operation": "LOCAL_EDIT" if mask_bytes else "IMAGE_EDIT",
        "intent": edit_flags,
        "referenceCount": reference_count,
        "clearMaskedRegion": clear_masked_region,
        "pixelLockEnabled": bool(mask_bytes),
        "apiCallExecuted": False,
        "compositeApplied": False,
    }

    def write_debug_summary(extra: dict | None = None) -> None:
        if not debug_dir:
            return
        if isinstance(extra, dict):
            debug_summary.update(extra)
        _gfa_local_edit_debug_write_json(debug_dir, "debug-summary.json", debug_summary)

    if debug_dir:
        _gfa_local_edit_debug_write(debug_dir, "source.png", source_bytes)
        if uploaded_mask_bytes:
            _gfa_local_edit_debug_write(debug_dir, "semantic-mask-uploaded.png", uploaded_mask_bytes)
        _gfa_local_edit_debug_write(debug_dir, "semantic-mask-input.png", mask_bytes or b"")
    image_field_name = "image[]" if refs else "image"
    files = [(image_field_name, ("source.png", source_bytes, source_mime or "image/png"))]
    if refs:
        ref_names = ", ".join(str(ref[0] or f"reference_{idx + 1}.png") for idx, ref in enumerate(refs[:4]))
        prompt = (
            "The first image[] file is the target banner to edit. All following image[] files are user-uploaded visual reference images for the masked area. "
            f"Reference image files: {ref_names}. "
            "You must visibly apply the relevant subject, material, texture, color, shape, or style from those reference images inside the transparent mask area, according to the user's request. "
            "Do not treat the reference images as a weak mood board; use them as concrete visual source material for the masked region. "
            "Preserve all unmasked target-banner pixels. Do not replace the main product/package identity unless the mask covers that part and the user explicitly requests it. "
            + prompt
        )
        for idx, ref in enumerate(refs[:4], start=1):
            name, data, mime = ref
            if data:
                files.append(("image[]", (name or f"reference_{idx}.png", data, mime or "image/png")))
    if mask_bytes:
        try:
            from PIL import Image
            from io import BytesIO
            with Image.open(BytesIO(source_bytes)) as src_img:
                target_size = src_img.size
        except Exception:
            target_size = (1024, 1024)
        debug_summary["source"] = {"width": target_size[0], "height": target_size[1]}
        try:
            semantic_mask_stats = _gfa_semantic_mask_input_stats(mask_bytes, target_size=target_size)
            debug_summary["semanticMask"] = semantic_mask_stats
            debug_summary["semanticEditableRatio"] = semantic_mask_stats.get("editable_ratio")
        except Exception as exc:
            write_debug_summary({"error": str(exc), "apiCallExecuted": False, "compositeApplied": False})
            raise
        prepared_mask, mask_coverage = _gfa_generator_prepare_openai_edit_mask(mask_bytes, target_size=target_size, expand_px=envelope_expand_px, blur_px=envelope_blur_px)
        generation_mask_bytes = _gfa_generator_api_mask_to_selection_bytes(prepared_mask)
        mask_stats = _gfa_api_mask_stats(prepared_mask)
        generation_mask_stats = _gfa_generator_selection_mask_stats(generation_mask_bytes)
        debug_summary["apiMask"] = mask_stats
        debug_summary["apiMaskEditableRatio"] = mask_stats.get("editable_ratio")
        try:
            debug_summary["editableRatioExpansion"] = round(float(mask_stats.get("editable_ratio") or 0) - float(debug_summary.get("semanticEditableRatio") or 0), 6)
            if float(debug_summary.get("semanticEditableRatio") or 0) > 0:
                debug_summary["editableRatioExpansionMultiplier"] = round(float(mask_stats.get("editable_ratio") or 0) / float(debug_summary.get("semanticEditableRatio") or 1), 6)
        except Exception:
            pass
        if mask_stats["width"] != target_size[0] or mask_stats["height"] != target_size[1]:
            write_debug_summary({"error": "image_edit_mask_dimension_mismatch"})
            raise RuntimeError("image_edit_mask_dimension_mismatch")
        editable_ratio = float(mask_stats.get("editable_ratio") or 0)
        if editable_ratio <= 0.001 or editable_ratio >= 0.9:
            write_debug_summary({"error": f"image_edit_mask_invalid_editable_ratio:{editable_ratio:.4f}"})
            raise RuntimeError(f"image_edit_mask_invalid_editable_ratio:{editable_ratio:.4f}")
        clear_mask_bytes: bytes | None = None
        clear_mask_stats: dict | None = None
        clear_mask_policy: dict | None = None
        deterministic_product: dict | None = None
        deterministic_product_layer_bytes: bytes | None = None
        deterministic_temp_source_bytes: bytes | None = None
        if clear_masked_region:
            clear_mask_bytes, clear_mask_policy = _gfa_generator_prepare_clear_mask(
                mask_bytes,
                target_size=target_size,
                edit_flags=edit_flags,
            )
            clear_mask_stats = _gfa_generator_selection_mask_stats(clear_mask_bytes)
            cleared_source_bytes = _gfa_generator_clear_masked_region_for_edit(
                source_bytes,
                clear_mask_bytes,
                target_size=target_size,
            )
            files[0] = (image_field_name, ("source.png", cleared_source_bytes, "image/png"))
            if debug_dir:
                _gfa_local_edit_debug_write(debug_dir, "clear-mask.png", clear_mask_bytes)
                _gfa_local_edit_debug_write(debug_dir, "source-cleared.png", cleared_source_bytes)
        product_target_mask_bytes: bytes | None = None
        product_target_geometry: dict | None = None
        use_deterministic_product = bool(edit_flags.get("product")) and bool(edit_flags.get("replace")) and bool(clear_mask_bytes) and bool(refs)
        if use_deterministic_product and clear_mask_bytes:
            ref_name, ref_bytes, ref_mime = refs[0]
            deterministic_product = _gfa_generator_prepare_deterministic_product_placement(
                cleared_source_bytes,
                reference_bytes=ref_bytes,
                reference_mime=ref_mime,
                clear_mask_bytes=clear_mask_bytes,
                target_size=target_size,
            )
            deterministic_product_layer_bytes = deterministic_product["placedProductLayerPng"]
            deterministic_temp_source_bytes = deterministic_product["temporaryProductCompositePng"]
            prepared_mask = deterministic_product["harmonizationApiMaskPng"]
            generation_mask_bytes = deterministic_product["harmonizationGenerationMaskPng"]
            commit_mask_bytes = deterministic_product["harmonizationCommitMaskPng"]
            commit_mask_policy = {
                "intent": "deterministic_product_harmonization",
                "product_body_editable": False,
                "commit_basis": "harmonizationCommitMask",
            }
            mask_stats = _gfa_api_mask_stats(prepared_mask)
            generation_mask_stats = _gfa_generator_selection_mask_stats(generation_mask_bytes)
            debug_summary["apiMask"] = mask_stats
            debug_summary["apiMaskEditableRatio"] = mask_stats.get("editable_ratio")
            debug_summary["deterministicProductPlacement"] = deterministic_product["summary"]
            files = [("image", ("temporary-product-composite.png", deterministic_temp_source_bytes, "image/png"))]
            prompt = (
                "Product placement and product pixels are already fixed in the input image. "
                "Preserve the placed product exactly. Do not redraw, resize, reposition, relabel, recolor, redesign, replace, or simplify the product/package. "
                "Only harmonize the immediately surrounding masked area for contact shadow, grounding, local lighting transition, and edge integration. "
                "Preserve all unrelated background, person, hair, table, bowl, props, and product body pixels. "
                f"Original local edit request for context only: {user_prompt}"
            )
        elif bool(edit_flags.get("product")) and bool(edit_flags.get("replace")) and clear_mask_bytes:
            product_target_mask_bytes, product_target_geometry = _gfa_generator_prepare_product_target_geometry(
                mask_bytes,
                clear_mask_bytes=clear_mask_bytes,
                generation_mask_bytes=generation_mask_bytes,
                target_size=target_size,
            )
            commit_mask_bytes, commit_mask_policy = _gfa_generator_prepare_product_commit_mask(
                product_target_mask_bytes,
                generation_mask_bytes=generation_mask_bytes,
            )
        else:
            commit_mask_bytes, commit_mask_policy = _gfa_generator_prepare_commit_mask(
                mask_bytes,
                target_size=target_size,
                edit_flags=edit_flags,
            )
        commit_mask_stats = _gfa_generator_selection_mask_stats(commit_mask_bytes)
        if product_target_geometry is not None:
            product_target_geometry["commitBBox"] = _gfa_generator_mask_bbox(commit_mask_bytes)
            product_target_geometry["commitEditableRatio"] = commit_mask_stats.get("editable_ratio")
        if debug_dir:
            _gfa_local_edit_debug_write(debug_dir, "api-mask.png", prepared_mask)
            _gfa_local_edit_debug_write(debug_dir, "generation-mask.png", generation_mask_bytes)
            if product_target_mask_bytes:
                _gfa_local_edit_debug_write(debug_dir, "product-target-geometry.png", product_target_mask_bytes)
            if deterministic_product is not None:
                _gfa_local_edit_debug_write(debug_dir, "reference-original.png", deterministic_product["referenceOriginalPng"])
                _gfa_local_edit_debug_write(debug_dir, "reference-background-mask.png", deterministic_product["backgroundMaskPng"])
                _gfa_local_edit_debug_write(debug_dir, "reference-product-foreground-mask.png", deterministic_product["foregroundMaskPng"])
                _gfa_local_edit_debug_write(debug_dir, "reference-product-foreground.png", deterministic_product["foregroundPng"])
                _gfa_local_edit_debug_write(debug_dir, "reference-product-tight-crop.png", deterministic_product["tightCropPng"])
                _gfa_local_edit_debug_write(debug_dir, "placed-product-layer.png", deterministic_product["placedProductLayerPng"])
                _gfa_local_edit_debug_write(debug_dir, "placed-product-mask.png", deterministic_product["placedProductMaskPng"])
                _gfa_local_edit_debug_write(debug_dir, "temporary-product-composite.png", deterministic_product["temporaryProductCompositePng"])
                _gfa_local_edit_debug_write(debug_dir, "harmonization-generation-mask.png", deterministic_product["harmonizationGenerationMaskPng"])
                _gfa_local_edit_debug_write(debug_dir, "harmonization-commit-mask.png", deterministic_product["harmonizationCommitMaskPng"])
            _gfa_local_edit_debug_write(debug_dir, "commit-mask.png", commit_mask_bytes)
        semantic_ratio = float(debug_summary.get("semanticEditableRatio") or 0)
        generation_ratio = float(generation_mask_stats.get("editable_ratio") or 0)
        commit_ratio = float(commit_mask_stats.get("editable_ratio") or 0)
        debug_summary["maskContract"] = {
            "semanticEditableRatio": round(semantic_ratio, 6),
            "generationEditableRatio": round(generation_ratio, 6),
            "commitEditableRatio": round(commit_ratio, 6),
            "clearEditableRatio": clear_mask_stats.get("editable_ratio") if clear_mask_stats else None,
            "productTargetEditableRatio": (product_target_geometry or {}).get("targetEditableRatio") if product_target_geometry else None,
        }
        if product_target_geometry is not None:
            debug_summary["productTargetGeometry"] = product_target_geometry
        debug_summary["maskPolicy"] = {
            "generationMaskUsedForApi": True,
            "commitMaskUsedForComposite": True,
            "clearMaskUsedForSourceClear": bool(clear_mask_bytes),
            "productTargetGeometryUsedForProductCommit": bool(product_target_mask_bytes),
            "deterministicProductPlacementUsed": bool(deterministic_product),
            "pixelLockBasis": "commitMask",
            "generation": {"expand_px": envelope_expand_px, "blur_px": envelope_blur_px},
            "commit": commit_mask_policy,
            "clear": clear_mask_policy,
        }
        if deterministic_product is None:
            prompt = (
                "The transparent mask area is an expanded edit context around the user's correction point. Treat the user's painted mask as the edit anchor, not as a clipping boundary for the new visual element. "
                "Preserve every clearly unrelated unmasked pixel and composition as much as possible, but allow the requested element to extend naturally within the expanded mask context. "
                + ("The target image sent to the editor has the expanded edit area cleared to transparency so the old object should not be preserved there. Recreate the cleared area cleanly according to the user's request. " if clear_masked_region else "The target image is not cleared because the request touches hair/person identity; keep the same person, pose, head angle, age impression, and body silhouette while changing only the requested local attribute. ")
                + ("When replacing a product/package, keep the original product position, scale, perspective, and contact shadows unless the user explicitly requests relocation. " if edit_flags["product"] else "")
                + f"Mask coverage is about {mask_coverage:.1%}; API editable ratio is {editable_ratio:.1%}; derived edit envelope expand={envelope_expand_px}px blur={envelope_blur_px}px. "
                + prompt
            )
        files.append(("mask", ("mask.png", prepared_mask, "image/png")))
        write_debug_summary()
    api_image_bytes = _gfa_request_image_bytes(files) or source_bytes
    if debug_dir:
        _gfa_local_edit_debug_write(debug_dir, "actual-api-image-input.png", api_image_bytes)
        if mask_bytes:
            _gfa_local_edit_debug_write(debug_dir, "api-mask.png", prepared_mask)
            debug_summary["annotationIsolation"] = _gfa_annotation_isolation_evidence(
                source_bytes=source_bytes,
                uploaded_mask_bytes=uploaded_mask_bytes,
                semantic_mask_bytes=mask_bytes,
                sanitize_stats=mask_sanitize_stats,
                api_image_bytes=api_image_bytes,
                api_mask_bytes=prepared_mask,
                intentional_source_clear=bool(clear_masked_region),
                stale_overlay_after_result=False,
            )
            write_debug_summary()
    debug_summary["apiCallExecuted"] = True
    resp = requests.post(
        "https://api.openai.com/v1/images/edits",
        headers={"Authorization": f"Bearer {key}"},
        data={"model": model_name, "prompt": prompt, "size": image_size, "n": "1"},
        files=files,
        timeout=180,
    )
    if resp.status_code != 200:
        write_debug_summary({"error": f"openai_image_error:{resp.status_code}"})
        raise RuntimeError(f"openai_image_error:{resp.status_code}:{_safe_err_text(resp, 1200)}")
    base_bytes, base_mime = _gfa_generator_extract_openai_image(resp.json() or {})
    if debug_dir:
        _gfa_local_edit_debug_write(debug_dir, "raw-ai-result.png", base_bytes)
        if deterministic_product is not None:
            _gfa_local_edit_debug_write(debug_dir, "raw-harmonized-result.png", base_bytes)
    if mask_bytes:
        raw_bytes = base_bytes
        composite_source_bytes = deterministic_temp_source_bytes if deterministic_temp_source_bytes else source_bytes
        base_bytes, base_mime = _gfa_generator_apply_masked_edit_region(composite_source_bytes, base_bytes, commit_mask_bytes)
        harmonized_stage_bytes = base_bytes
        if deterministic_product_layer_bytes:
            base_bytes = _gfa_generator_reoverlay_product_layer(base_bytes, deterministic_product_layer_bytes)
            base_mime = "image/png"
        debug_summary["compositeApplied"] = True
        if debug_dir:
            _gfa_local_edit_debug_write(debug_dir, "final-composite.png", base_bytes)
            debug_summary["annotationIsolation"] = _gfa_annotation_isolation_evidence(
                source_bytes=source_bytes,
                uploaded_mask_bytes=uploaded_mask_bytes,
                semantic_mask_bytes=mask_bytes,
                sanitize_stats=mask_sanitize_stats,
                api_image_bytes=api_image_bytes,
                api_mask_bytes=prepared_mask,
                raw_ai_bytes=raw_bytes,
                final_bytes=base_bytes,
                composite_base_bytes=composite_source_bytes,
                intentional_source_clear=bool(clear_masked_region),
                stale_overlay_after_result=False,
            )
            if deterministic_product_layer_bytes:
                identity = _gfa_generator_product_identity_evidence(base_bytes, deterministic_product_layer_bytes, debug_dir=debug_dir)
                debug_summary.setdefault("deterministicProductPlacement", {})
                debug_summary["deterministicProductPlacement"]["identity"] = identity
                try:
                    placed_bbox = ((debug_summary.get("deterministicProductPlacement") or {}).get("placement") or {}).get("placedBBox")
                    if isinstance(placed_bbox, dict):
                        debug_summary["deterministicProductPlacement"]["edgeReviewPath"] = _gfa_generator_write_product_edge_review(
                            base_bytes,
                            deterministic_product_layer_bytes,
                            placed_bbox=placed_bbox,
                            debug_dir=debug_dir,
                        )
                except Exception as edge_exc:
                    debug_summary["deterministicProductPlacement"]["edgeReviewError"] = str(edge_exc)[:500]
            try:
                debug_summary["diff"] = _gfa_local_edit_debug_write_diff_evidence(debug_dir, composite_source_bytes, raw_bytes, base_bytes, prepared_mask)
            except Exception as exc:
                debug_summary["diffError"] = str(exc)[:500]
            try:
                boundary = _gfa_local_edit_debug_write_boundary_evidence(debug_dir, composite_source_bytes, base_bytes, mask_bytes, prepared_mask)
                debug_summary["maskBoundaryIntegrity"] = {
                    "semanticEditableRatio": debug_summary.get("semanticEditableRatio"),
                    "apiMaskEditableRatio": debug_summary.get("apiMaskEditableRatio"),
                    "editableRatioExpansion": debug_summary.get("editableRatioExpansion"),
                    "editableRatioExpansionFactor": debug_summary.get("editableRatioExpansionMultiplier"),
                    "finalOutsideSemanticMaskChangedRatio": boundary.get("finalOutsideSemanticMaskChangedRatio"),
                    "finalOutsideApiMaskChangedRatio": boundary.get("finalOutsideApiMaskChangedRatio"),
                    "zones": boundary.get("zones"),
                    "diffSemanticMaskOutsidePath": boundary.get("diffSemanticMaskOutsidePath"),
                    "maskExpansionZonePath": boundary.get("maskExpansionZonePath"),
                }
                dual_boundary = _gfa_local_edit_debug_write_dual_mask_evidence(
                    debug_dir,
                    composite_source_bytes,
                    raw_bytes,
                    harmonized_stage_bytes if deterministic_product is not None else base_bytes,
                    mask_bytes,
                    generation_mask_bytes,
                    commit_mask_bytes,
                )
                if deterministic_product is not None:
                    debug_summary.setdefault("deterministicProductPlacement", {})
                    debug_summary["deterministicProductPlacement"].setdefault("harmonization", {}).update(
                        {
                            "outsideCommitChangedRatio": dual_boundary.get("finalOutsideCommitMaskChangedRatio"),
                            "finalOutsideHarmonizationCommitChangedRatio": dual_boundary.get("finalOutsideCommitMaskChangedRatio"),
                            "productBodyEditable": False,
                        }
                    )
                debug_summary["maskBoundaryIntegrity"].update(
                    {
                        "semanticToGenerationExpansion": round(
                            float(generation_mask_stats.get("editable_ratio") or 0)
                            - float(debug_summary.get("semanticEditableRatio") or 0),
                            6,
                        ),
                        "semanticToCommitExpansion": round(
                            float(commit_mask_stats.get("editable_ratio") or 0)
                            - float(debug_summary.get("semanticEditableRatio") or 0),
                            6,
                        ),
                        "rawOutsideSemanticMaskChangedRatio": dual_boundary.get("rawOutsideSemanticMaskChangedRatio"),
                        "finalOutsideSemanticMaskChangedRatio": dual_boundary.get("finalOutsideSemanticMaskChangedRatio"),
                        "finalOutsideGenerationMaskChangedRatio": dual_boundary.get("finalOutsideGenerationMaskChangedRatio"),
                        "finalOutsideCommitMaskChangedRatio": dual_boundary.get("finalOutsideCommitMaskChangedRatio"),
                        "dualMaskZones": dual_boundary.get("zones"),
                        "diffCommitMaskOutsidePath": dual_boundary.get("diffCommitMaskOutsidePath"),
                    }
                )
                if product_target_geometry is not None:
                    dual_zones = dual_boundary.get("zones") if isinstance(dual_boundary.get("zones"), dict) else {}
                    debug_summary["productTargetZones"] = {
                        "zoneP_A_semantic": dual_zones.get("zoneA_semantic"),
                        "zoneP_B_clearTargetOutsideSemantic": dual_zones.get("zoneB_commitBand"),
                        "zoneP_C_generationOutsideProductCommit": dual_zones.get("zoneC_generationOnly"),
                        "zoneP_D_outsideGeneration": dual_zones.get("zoneD_outsideGeneration"),
                    }
                    try:
                        debug_summary["productTargetGeometry"]["overlayPath"] = _gfa_local_edit_debug_write_product_target_overlay(
                            debug_dir,
                            source_bytes,
                            product_target_geometry=product_target_geometry,
                            commit_bbox=_gfa_generator_mask_bbox(commit_mask_bytes),
                        )
                    except Exception as overlay_exc:
                        debug_summary["productTargetGeometry"]["overlayError"] = str(overlay_exc)[:500]
                debug_summary["maskExpansionPath"] = _gfa_local_edit_mask_expansion_path_stats(
                    mask_bytes,
                    target_size=target_size,
                    expand_px=envelope_expand_px,
                    blur_px=envelope_blur_px,
                    api_mask_bytes=prepared_mask,
                )
            except Exception as exc:
                debug_summary["maskBoundaryIntegrityError"] = str(exc)[:500]
            write_debug_summary()
            prompt = f"LOCAL_EDIT_DEBUG_ID:{debug_id}\nLOCAL_EDIT_DEBUG_DIR:{debug_dir}\n" + prompt
    if overlay_after_edit:
        base_path = _gfa_generator_write_image_file(base_bytes, base_mime, prefix="gfa_base_edit")
        img_bytes, mime = _gfa_generator_overlay_copy_on_image(base_bytes, copy_result=copy_result, combination=combination)
        path = _gfa_generator_write_image_file(img_bytes, mime, prefix="gfa_image_edit")
    else:
        path = _gfa_generator_write_image_file(base_bytes, base_mime, prefix="gfa_image_edit")
        mime = base_mime
        base_path = ""
    return path, mime, prompt, f"openai:{model_name}", base_path, base_mime


def _gfa_banner_generation_alignment_audit(
    *,
    contract: dict,
    brief: dict,
    copy_result: dict,
    image_prompt: str,
    image_path: str | None = None,
) -> dict:
    contract = contract if isinstance(contract, dict) else {}
    brief = brief if isinstance(brief, dict) else {}
    copy_result = copy_result if isinstance(copy_result, dict) else {}
    prompt_text = str(image_prompt or "")
    prompt_l = prompt_text.lower()

    def display_len(value: object) -> int:
        return len(_collapse_ws_text(value).replace("\n", ""))

    def score_status(score: float) -> str:
        return "PASS" if score >= 85 else "PARTIAL" if score >= 65 else "NEEDS_REVIEW"

    priority_rows = [x for x in (contract.get("priority_changes") or []) if isinstance(x, dict)]
    represented = 0
    missing_priority: list[dict] = []
    for row in priority_rows:
        key = str(row.get("key") or "").strip().lower()
        label = str(row.get("label") or "").strip()
        action = str(row.get("action") or "").strip()
        tokens = [x for x in [key, label[:18], action[:28]] if x]
        hit = any(str(token).lower() in prompt_l for token in tokens)
        if hit:
            represented += 1
        else:
            missing_priority.append({"key": row.get("key") or "", "label": row.get("label") or "", "action": action})
    priority_score = 100.0 if not priority_rows else round((represented / max(1, len(priority_rows))) * 100.0, 1)

    headline_len = display_len(copy_result.get("headline"))
    subcopy_len = display_len(copy_result.get("subcopy"))
    cta_len = display_len(copy_result.get("cta"))
    proof_len = display_len(copy_result.get("proof_line"))
    copy_checks = [
        {"key": "headline_length", "label": "헤드라인 12~16자", "passed": 12 <= headline_len <= 16, "value": headline_len, "target": "12~16"},
        {"key": "subcopy_length", "label": "서브카피 20~28자", "passed": 20 <= subcopy_len <= 28, "value": subcopy_len, "target": "20~28"},
        {"key": "cta_length", "label": "CTA 4~8자", "passed": 4 <= cta_len <= 8, "value": cta_len, "target": "4~8"},
        {"key": "proof_length", "label": "증거/보조문구 28자 이내", "passed": proof_len <= 28, "value": proof_len, "target": 28},
    ]
    copy_score = round((sum(1 for x in copy_checks if x["passed"]) / len(copy_checks)) * 100.0, 1)
    overlay = copy_result.get("overlay_layout") if isinstance(copy_result.get("overlay_layout"), dict) else {}
    headline_overlay = overlay.get("headline") if isinstance(overlay.get("headline"), dict) else {}
    cta_overlay = overlay.get("cta") if isinstance(overlay.get("cta"), dict) else {}
    overlay_checks = [
        {"key": "overlay_layout_exists", "label": "카피 위치/스타일 자동 생성", "passed": bool(overlay)},
        {"key": "headline_left_safe_zone", "label": "헤드라인 좌측 안전영역 배치", "passed": 0.04 <= _gfa_banner_program_num(headline_overlay.get("x")) <= 0.10 and 0.25 <= _gfa_banner_program_num(headline_overlay.get("w")) <= 0.45},
        {"key": "headline_emphasis", "label": "헤드라인 굵기/크기 강조", "passed": str(headline_overlay.get("font_weight") or "").lower() == "bold" and _gfa_banner_program_num(headline_overlay.get("font_scale")) >= 1.0},
        {"key": "cta_button_emphasis", "label": "CTA 버튼 색상/배경 강조", "passed": _gfa_banner_program_num(cta_overlay.get("bg_opacity")) >= 0.85 and bool(cta_overlay.get("bg_color"))},
        {"key": "cta_bottom_safe_zone", "label": "CTA 하단 안전영역 배치", "passed": 0.68 <= _gfa_banner_program_num(cta_overlay.get("y")) <= 0.86},
    ]
    overlay_score = round((sum(1 for x in overlay_checks if x["passed"]) / len(overlay_checks)) * 100.0, 1)

    supplemental = contract.get("supplemental_banner_guide_targets") if isinstance(contract.get("supplemental_banner_guide_targets"), dict) else {}
    guide_presence_checks = [
        {"key": "supplemental_guide", "label": "추가 배너 제작 가이드 contract 포함", "passed": bool(supplemental)},
        {"key": "smp_rule", "label": "SMP 단일 메시지 규칙 포함", "passed": "smp" in prompt_l or "core usp" in prompt_l or "single" in prompt_l},
        {"key": "visual_hierarchy", "label": "1.5초 시각 위계 포함", "passed": "visual anchor" in prompt_l and "primary hook" in prompt_l and "brand trust" in prompt_l},
        {"key": "safe_zone", "label": "5~8% Safe Zone 포함", "passed": "safe zone" in prompt_l or "5-8%" in prompt_l or "5~8%" in prompt_l},
        {"key": "copy_limits", "label": "카피 길이 제한 포함", "passed": ("12-16" in prompt_l or "12~16" in prompt_l) and ("20-28" in prompt_l or "20~28" in prompt_l) and ("4-8" in prompt_l or "4~8" in prompt_l)},
    ]
    guide_score = round((sum(1 for x in guide_presence_checks if x["passed"]) / len(guide_presence_checks)) * 100.0, 1)

    refs = brief.get("additional_references") if isinstance(brief.get("additional_references"), dict) else {}
    images = refs.get("images") if isinstance(refs.get("images"), list) else []
    content_context = brief.get("product_context") if isinstance(brief.get("product_context"), dict) else {}
    content_generation_context = content_context.get("content_center_generation_context") if isinstance(content_context.get("content_center_generation_context"), dict) else {}
    anti_random_checks = [
        {"key": "has_reference_images", "label": "참조 이미지 사용", "passed": len(images) > 0, "value": len(images)},
        {"key": "product_preserve_contract", "label": "제품/패키지 임의 생성 금지", "passed": "do_not_invent_new_product_or_package" in json.dumps(content_generation_context, ensure_ascii=False) or "do not invent a new product package" in prompt_l},
        {"key": "text_not_in_image_model", "label": "텍스트/CTA는 서버 오버레이 처리", "passed": "do not render" in prompt_l and "server-side" in prompt_l},
        {"key": "reference_media_variation", "label": "참고 소재로 장면/질감 다양화", "passed": "reference_media" in json.dumps(content_generation_context, ensure_ascii=False) or "reference media" in prompt_l},
    ]
    anti_random_score = round((sum(1 for x in anti_random_checks if x["passed"]) / len(anti_random_checks)) * 100.0, 1)

    post_cv_metrics = None
    post_cv_checks: list[dict] = []
    if image_path and os.path.exists(image_path):
        try:
            with open(image_path, "rb") as f:
                post_cv_metrics = _gfa_banner_extract_uploaded_cv_metrics(f.read()) or {}
            text_ratio = _gfa_banner_program_num((post_cv_metrics or {}).get("estimated_text_area_ratio"))
            post_cv_checks.append({"key": "final_text_area", "label": "최종 텍스트 면적 18% 이하", "passed": text_ratio <= 0.18, "value": round(text_ratio * 100.0, 1), "target": "18%"})
        except Exception:
            post_cv_metrics = None
    post_cv_score = round((sum(1 for x in post_cv_checks if x["passed"]) / len(post_cv_checks)) * 100.0, 1) if post_cv_checks else None

    score_parts = [priority_score, copy_score, guide_score, overlay_score, anti_random_score]
    if post_cv_score is not None:
        score_parts.append(post_cv_score)
    overall = round(sum(score_parts) / max(1, len(score_parts)), 1)
    return {
        "version": "generation-alignment-audit-v1",
        "overall_score": overall,
        "status": score_status(overall),
        "analysis_reflection": {
            "score": priority_score,
            "status": score_status(priority_score),
            "priority_total": len(priority_rows),
            "represented_in_prompt": represented,
            "missing_or_weak_items": missing_priority[:6],
        },
        "guide_compliance": {
            "score": round((copy_score + guide_score) / 2.0, 1),
            "status": score_status((copy_score + guide_score) / 2.0),
            "copy_score": copy_score,
            "guide_presence_score": guide_score,
            "overlay_style_score": overlay_score,
            "copy_checks": copy_checks,
            "overlay_checks": overlay_checks,
            "guide_checks": guide_presence_checks,
        },
        "anti_randomness": {
            "score": anti_random_score,
            "status": score_status(anti_random_score),
            "checks": anti_random_checks,
        },
        "post_generation_cv": {
            "score": post_cv_score,
            "status": score_status(post_cv_score) if post_cv_score is not None else "NOT_CHECKED",
            "checks": post_cv_checks,
            "metrics": post_cv_metrics or {},
        },
        "limits": [
            "제품 패키지 보존, 사용 장면 적합성, 참고 소재 반영 여부는 현재 프롬프트/참조/수치 기반 감사입니다.",
            "생성 이미지를 다시 AI Vision으로 분석하는 후검증 게이트를 추가하면 실제 시각 반영률을 더 정확히 판정할 수 있습니다.",
        ],
    }


def _gfa_generation_event_to_dict(row: NaverGfaCreativeGenerationEvent) -> dict:
    payload = {}
    if row.payload_json:
        try:
            obj = json.loads(row.payload_json)
            payload = obj if isinstance(obj, dict) else {}
        except Exception:
            payload = {}
    return {
        "event_id": row.event_id,
        "run_id": row.run_id,
        "batch_id": row.batch_id,
        "event_type": row.event_type,
        "actor": row.actor or "",
        "note": row.note or "",
        "payload": payload,
        "created_at": row.created_at.isoformat() if row.created_at else None,
    }


def _gfa_generation_add_event(
    db: Session,
    run: NaverGfaCreativeGenerationRun,
    *,
    event_type: str,
    note: str | None = None,
    payload: dict | None = None,
    actor: str | None = None,
) -> NaverGfaCreativeGenerationEvent:
    ev = NaverGfaCreativeGenerationEvent(
        event_id=uuid.uuid4().hex,
        run_id=run.id,
        batch_id=run.batch_id,
        event_type=str(event_type or "").strip(),
        actor=str(actor or "").strip() or None,
        note=str(note or "").strip() or None,
        payload_json=_gfa_generator_json_dumps(payload or {}),
        created_at=datetime.now(ZoneInfo("Asia/Seoul")),
    )
    db.add(ev)
    return ev


def _gfa_generation_run_to_dict(row: NaverGfaCreativeGenerationRun, db: Session | None = None) -> dict:
    def loads(s: str | None, default):
        if not s:
            return default
        try:
            obj = json.loads(s)
            return obj if obj is not None else default
        except Exception:
            return default

    generation_explanation = loads(row.generation_explanation_json, {})
    source_snapshot = loads(row.source_snapshot_json, {})
    source_creative_id = str(row.source_creative_id or "")
    linked_history_id = ""
    if source_creative_id.startswith("banner-analysis:"):
        linked_history_id = source_creative_id.split(":", 1)[1].strip()
        if linked_history_id == "current":
            linked_history_id = ""
    if not linked_history_id and isinstance(source_snapshot, dict):
        linked_history_id = str(source_snapshot.get("history_id") or "").strip()
    layering = generation_explanation.get("image_layering") if isinstance(generation_explanation.get("image_layering"), dict) else {}
    base_image_path = str(generation_explanation.get("base_image_path") or layering.get("base_image_path") or "").strip()
    can_lock_image = bool(base_image_path and os.path.exists(base_image_path))
    return {
        "id": row.id,
        "batch_id": row.batch_id,
        "candidate_index": row.candidate_index,
        "candidate_count": row.candidate_count,
        "goal": row.goal,
        "goal_label": row.goal_label,
        "template_type": row.template_type,
        "template_label": row.template_label,
        "source_creative_id": row.source_creative_id,
        "history_id": linked_history_id,
        "source_creative_name": row.source_creative_name,
        "generation_source": getattr(row, "generation_source", None) or "existing",
        "appeal_point_id": getattr(row, "appeal_point_id", None),
        "source_snapshot": source_snapshot,
        "guide_rules": loads(row.guide_rules_json, {}),
        "brief": loads(row.brief_json, {}),
        "combination_strategy": loads(row.combination_strategy_json, {}),
        "generation_explanation": generation_explanation,
        "copy_prompt": row.copy_prompt or "",
        "image_prompt": row.image_prompt or "",
        "copy_result": loads(row.copy_result_json, {}),
        "base_image_url": f"/gfa/creative-generator/runs/{row.id}/image/base" if can_lock_image else "",
        "image_url": f"/gfa/creative-generator/runs/{row.id}/image" if row.image_path and os.path.exists(row.image_path) else "",
        "image_mime_type": row.image_mime_type or "",
        "can_lock_image": can_lock_image,
        "openai_model": row.openai_model or "",
        "gemini_model": row.gemini_model or "",
        "status": row.status,
        "error": row.error or "",
        "reviewer_status": row.reviewer_status,
        "reviewer_note": row.reviewer_note or "",
        "usage_status": row.usage_status,
        "used_campaign_name": row.used_campaign_name or "",
        "used_adgroup_name": row.used_adgroup_name or "",
        "used_creative_name": row.used_creative_name or "",
        "used_at": row.used_at.isoformat() if row.used_at else None,
        "feedback_summary": row.feedback_summary or "",
        "events": [
            _gfa_generation_event_to_dict(ev)
            for ev in (
                db.query(NaverGfaCreativeGenerationEvent)
                .filter(NaverGfaCreativeGenerationEvent.run_id == row.id)
                .order_by(NaverGfaCreativeGenerationEvent.created_at.asc())
                .all()
                if db is not None
                else []
            )
        ],
        "created_at": row.created_at.isoformat() if row.created_at else None,
        "updated_at": row.updated_at.isoformat() if row.updated_at else None,
    }


