def _gfa_banner_parse_json(content: str) -> dict:
    text0 = _strip_json_fence(str(content or "").strip())
    if "{" in text0 and "}" in text0:
        text0 = text0[text0.find("{") : text0.rfind("}") + 1]
    try:
        parsed = json.loads(text0)
        return parsed if isinstance(parsed, dict) else {"raw": parsed}
    except Exception:
        return {"verdict": text0}


def _gfa_banner_openai_content(resp_json: dict) -> str:
    try:
        choices = resp_json.get("choices") or []
        if not choices:
            return ""
        message = (choices[0] or {}).get("message") or {}
        raw_content = message.get("content")
        if isinstance(raw_content, list):
            return "\n".join(str((part or {}).get("text") or (part or {}).get("content") or "") for part in raw_content if isinstance(part, dict))
        return str(raw_content or "")
    except Exception:
        return ""


def _gfa_banner_factor_key(raw: object) -> str:
    text = str(raw or "").strip().lower()
    compact = re.sub(r"[\s/_\-·]+", "", text)
    aliases = {
        "hook": ["hook", "첫인상", "후킹", "훅"],
        "emotion": ["emotion", "감정", "심리", "공감"],
        "usp": ["usp", "구매이유", "혜택", "차별혜택"],
        "trust": ["trust", "evidence", "신뢰", "근거", "증빙"],
        "alignment": ["alignment", "카피이미지", "정합성", "일치"],
        "message_structure": ["messagestructure", "메시지구조", "문제해결흐름", "전달구조"],
        "cta": ["cta", "행동유도", "버튼", "클릭유도"],
        "design_layout": ["designlayout", "디자인", "레이아웃", "구도"],
        "copy_hierarchy": ["copyhierarchy", "카피위계", "정보구조", "문구위계"],
        "text_readability": ["textreadability", "가독성", "텍스트크기", "문구가독"],
        "object_product": ["objectproduct", "오브젝트", "제품노출", "상품노출"],
        "visual_salience": ["visualsalience", "시선집중", "주목도", "눈에띄는정도"],
        "audience_fit": ["audiencefit", "타깃", "타겟", "고객적합"],
        "offer_clarity": ["offerclarity", "오퍼", "혜택명확", "제안명확"],
        "image_fit": ["imagefit", "이미지적합", "이미지연관", "시각적합"],
        "naver_review_fit": ["naverreviewfit", "네이버", "심사", "가이드", "광고정합"],
        "differentiation": ["differentiation", "차별", "새로움", "독창"],
        "click_motivation_fit": ["clickmotivationfit", "클릭동기", "클릭유도적합", "클릭률", "성과적합"],
    }
    for key, needles in aliases.items():
        if key == text or key == compact or any(needle in compact for needle in needles):
            return key
    return text


def _gfa_banner_score_value(raw: object, default: float = 60.0) -> float:
    if isinstance(raw, (int, float)):
        return max(0.0, min(100.0, float(raw)))
    match = re.search(r"-?\d+(?:\.\d+)?", str(raw or ""))
    if not match:
        return default
    try:
        return max(0.0, min(100.0, float(match.group(0))))
    except Exception:
        return default


def _gfa_banner_factor_rows(body: dict) -> list[dict]:
    rows: list[dict] = []
    direct = (
        body.get("factor_scores")
        or body.get("factorScores")
        or body.get("factors")
        or body.get("evaluations")
        or body.get("evaluation")
        or body.get("score_details")
        or body.get("scoreDetails")
    )
    if isinstance(direct, list):
        rows.extend([x for x in direct if isinstance(x, dict)])
    for key_name in ("scores", "candidate_scores", "element_scores", "score_map", "점수"):
        score_map = body.get(key_name)
        if isinstance(score_map, dict):
            for key0, value0 in score_map.items():
                if isinstance(value0, dict):
                    rows.append({"key": key0, **value0})
                else:
                    rows.append({"key": key0, "score": value0})
    normalized: list[dict] = []
    for row in rows:
        label0 = row.get("key") or row.get("label") or row.get("name") or row.get("item") or row.get("criterion") or row.get("항목") or row.get("평가항목")
        key = _gfa_banner_factor_key(label0)
        if not key:
            continue
        normalized.append({**row, "key": key})
    return normalized


def _gfa_banner_analysis_missing_keys(parsed: dict) -> list[str]:
    body = parsed if isinstance(parsed, dict) else {}
    factor_rows = _gfa_banner_factor_rows(body)
    present = set()
    for item in factor_rows:
        if isinstance(item, dict) and str(item.get("key") or "").strip():
            present.add(str(item.get("key") or "").strip())
    required = [key for key, _label, _target in GFA_BANNER_ANALYSIS_FACTORS]
    return [key for key in required if key not in present]


def _gfa_banner_normalize_analysis(raw: dict, *, filename: str, model: str) -> dict:
    body = raw if isinstance(raw, dict) else {}
    by_key = {}
    for item in _gfa_banner_factor_rows(body):
        if isinstance(item, dict):
            by_key[str(item.get("key") or "").strip()] = item
    factors = []
    for key, label, target in GFA_BANNER_ANALYSIS_FACTORS:
        item = by_key.get(key, {})
        score = _gfa_banner_score_value(
            item.get("score", item.get("점수", item.get("rating", body.get(f"{key}_score", 60)))),
            60.0,
        )
        good = item.get("good") or item.get("strength") or item.get("strengths") or item.get("good_points") or item.get("잘된점") or item.get("강점")
        weak = item.get("weak") or item.get("weakness") or item.get("weaknesses") or item.get("weak_points") or item.get("미흡한점") or item.get("약점")
        improvement = item.get("improvement") or item.get("recommendation") or item.get("recommendations") or item.get("개선안") or item.get("개선점")
        if isinstance(good, list):
            good = " · ".join(str(x) for x in good[:3])
        if isinstance(weak, list):
            weak = " · ".join(str(x) for x in weak[:3])
        if isinstance(improvement, list):
            improvement = " · ".join(str(x) for x in improvement[:3])
        factors.append(
            {
                "key": key,
                "label": str(item.get("label") or label),
                "target": target,
                "score": round(score, 1),
                "good": str(good or "해당 요소의 강점 설명이 누락되었습니다."),
                "weak": str(weak or "해당 요소의 미흡점 설명이 누락되었습니다."),
                "improvement": str(improvement or "기존 GFA 분석 기준에 맞춰 이 요소의 보완안을 다시 점검하세요."),
            }
        )
    try:
        overall = float(body.get("overall_score"))
    except Exception:
        overall = sum(float(item["score"]) for item in factors) / max(1, len(factors))
    overall = round(max(0.0, min(100.0, overall)), 1)
    grade = str(body.get("grade") or ("A" if overall >= 85 else "B" if overall >= 70 else "C" if overall >= 55 else "D"))
    element_analysis = _gfa_banner_normalize_element_analysis(body, factors)
    expert_analysis_v2 = _gfa_banner_normalize_expert_analysis_v2(body, factors, element_analysis)
    return {
        "ok": True,
        "filename": filename,
        "model": model,
        "criteria": _gfa_banner_analysis_rubric(),
        "overall_score": overall,
        "grade": grade,
        "verdict": str(body.get("verdict") or body.get("summary") or "기존 GFA 분석 기준으로 업로드 배너를 평가했습니다."),
        "factor_scores": factors,
        "element_analysis": element_analysis,
        "expert_analysis_v2": expert_analysis_v2,
        "visual_observation_v1": body.get("visual_observation_v1") if isinstance(body.get("visual_observation_v1"), dict) else {},
        "opencv_metrics_v1": body.get("_opencv_metrics_v1") if isinstance(body.get("_opencv_metrics_v1"), dict) else {},
        "vision_tags": body.get("vision_tags") if isinstance(body.get("vision_tags"), dict) else {},
        "policy_observations": body.get("policy_observations") if isinstance(body.get("policy_observations"), dict) else {},
        "strengths": [str(x) for x in (body.get("strengths") or []) if str(x).strip()][:6],
        "weaknesses": [str(x) for x in (body.get("weaknesses") or []) if str(x).strip()][:6],
        "recommendations": [str(x) for x in (body.get("recommendations") or body.get("improvement_suggestions") or []) if str(x).strip()][:8],
    }


def _gfa_banner_normalize_element_analysis(body: dict, factors: list[dict]) -> list[dict]:
    raw = body.get("element_analysis") or body.get("detailed_element_analysis") or body.get("creative_element_analysis")
    rows: list[dict] = []
    if isinstance(raw, list):
        for idx, item in enumerate(raw):
            if not isinstance(item, dict):
                continue
            title = str(item.get("title") or item.get("label") or item.get("name") or f"분석 요소 {idx + 1}").strip()
            observation = item.get("observation") or item.get("observations") or item.get("visual_observation") or item.get("관찰")
            strategic = item.get("strategic_meaning") or item.get("interpretation") or item.get("analysis") or item.get("광고적해석")
            strength = item.get("strength") or item.get("good") or item.get("good_point") or item.get("잘된점")
            weakness = item.get("weakness") or item.get("weak") or item.get("risk") or item.get("부족한점")
            improvement = item.get("improvement") or item.get("recommendation") or item.get("action") or item.get("수정방향")
            rows.append(
                {
                    "key": str(item.get("key") or item.get("type") or idx).strip(),
                    "title": title,
                    "observation": _gfa_banner_compact_list_text(observation),
                    "strategic_meaning": _gfa_banner_compact_list_text(strategic),
                    "strength": _gfa_banner_compact_list_text(strength),
                    "weakness": _gfa_banner_compact_list_text(weakness),
                    "improvement": _gfa_banner_compact_list_text(improvement),
                }
            )
    factor_by_key = {str(item.get("key") or ""): item for item in factors if isinstance(item, dict)}
    fallback_specs = [
        ("person_target", "인물/타깃", "audience_fit"),
        ("problem_scene", "문제상황/사용 맥락", "message_structure"),
        ("product_object", "제품/오브젝트", "object_product"),
        ("copy_message", "문구/카피", "copy_hierarchy"),
        ("layout_flow", "레이아웃/시선흐름", "visual_salience"),
        ("cta_action", "CTA/행동 유도", "cta"),
        ("policy_risk", "광고 정책 리스크", "naver_review_fit"),
    ]
    existing_keys = {str(row.get("key") or "").strip() for row in rows}
    existing_titles = {str(row.get("title") or "").strip() for row in rows}
    for key, title, factor_key in fallback_specs:
        if len(rows) >= 7:
            break
        if key in existing_keys or title in existing_titles:
            continue
        f = factor_by_key.get(factor_key) or {}
        rows.append(
            {
                "key": key,
                "title": title,
                "observation": str(f.get("good") or "관찰 근거가 충분하지 않습니다."),
                "strategic_meaning": str(f.get("weak") or "광고적 해석을 위해 재분석이 필요합니다."),
                "strength": str(f.get("good") or ""),
                "weakness": str(f.get("weak") or ""),
                "improvement": str(f.get("improvement") or ""),
            }
        )
    return rows


def _gfa_banner_compact_list_text(value: object) -> str:
    if isinstance(value, list):
        return " · ".join(str(x).strip() for x in value if str(x).strip())[:600]
    return str(value or "").strip()[:600]


def _gfa_banner_normalize_expert_analysis_v2(body: dict, factors: list[dict], element_analysis: list[dict]) -> dict:
    raw = body.get("expert_analysis_v2") if isinstance(body.get("expert_analysis_v2"), dict) else {}
    raw_dimensions = raw.get("dimensions") if isinstance(raw.get("dimensions"), list) else []
    if raw_dimensions:
        dimensions = []
        for idx, raw_dimension in enumerate(raw_dimensions[:10]):
            if not isinstance(raw_dimension, dict):
                continue
            raw_criteria = raw_dimension.get("criteria") if isinstance(raw_dimension.get("criteria"), list) else []
            criteria = []
            for cidx, criterion in enumerate(raw_criteria[:8]):
                if not isinstance(criterion, dict):
                    continue
                criteria.append(
                    {
                        "key": str(criterion.get("key") or cidx),
                        "label": str(criterion.get("label") or criterion.get("title") or "분석 기준"),
                        "score": _gfa_banner_score_value(criterion.get("score"), 60.0),
                        "observation": _gfa_banner_compact_list_text(criterion.get("observation")),
                        "interpretation": _gfa_banner_compact_list_text(criterion.get("interpretation") or criterion.get("analysis")),
                        "risk": _gfa_banner_compact_list_text(criterion.get("risk")),
                        "improvement": _gfa_banner_compact_list_text(criterion.get("improvement") or criterion.get("recommendation")),
                    }
                )
            dimensions.append(
                {
                    "key": str(raw_dimension.get("key") or idx),
                    "title": str(raw_dimension.get("title") or raw_dimension.get("label") or "전문가 분석"),
                    "score": _gfa_banner_score_value(raw_dimension.get("score"), 60.0),
                    "summary": _gfa_banner_compact_list_text(raw_dimension.get("summary") or raw_dimension.get("interpretation")),
                    "criteria": criteria,
                    "score_anchors": raw_dimension.get("score_anchors") if isinstance(raw_dimension.get("score_anchors"), dict) else {},
                }
            )
        if dimensions:
            return {
                "taxonomy_version": COMMERCIAL_BANNER_CREATIVE_ANALYSIS_TAXONOMY_V2["version"],
                "report_rubric_version": COMMERCIAL_BANNER_GUIDE_REPORT_RUBRIC_V1["version"],
                "dimensions": dimensions,
                "priority_actions": _gfa_banner_unique_texts(raw.get("priority_actions") if isinstance(raw.get("priority_actions"), list) else [], limit=8),
                "policy_conflict_guard": {
                    "enabled": True,
                    "principle": COMMERCIAL_BANNER_CREATIVE_ANALYSIS_TAXONOMY_V2["policy_conflict_principle"],
                },
            }
    by_key = {str(item.get("key") or "").strip(): item for item in raw_dimensions if isinstance(item, dict)}
    factor_by_key = {str(item.get("key") or "").strip(): item for item in factors if isinstance(item, dict)}

    factor_map = {
        "advertising_strategy": ["hook", "usp", "message_structure", "cta", "offer_clarity"],
        "psychology_trigger": ["emotion", "trust", "audience_fit", "click_motivation_fit"],
        "creative_technique": ["hook", "differentiation", "alignment", "object_product"],
        "design_system": ["design_layout", "copy_hierarchy", "text_readability", "visual_salience", "image_fit"],
        "platform_compliance": ["naver_review_fit", "text_readability", "image_fit"],
        "performance_learning": ["click_motivation_fit", "differentiation", "offer_clarity"],
    }

    dimensions: list[dict] = []
    for spec in COMMERCIAL_BANNER_CREATIVE_ANALYSIS_TAXONOMY_V2["dimensions"]:
        key = str(spec["key"])
        raw_dimension = by_key.get(key) if isinstance(by_key.get(key), dict) else {}
        related = [factor_by_key[x] for x in factor_map.get(key, []) if x in factor_by_key]
        fallback_score = round(sum(float(x.get("score") or 0) for x in related) / max(1, len(related)), 1) if related else 60.0
        criteria = raw_dimension.get("criteria") if isinstance(raw_dimension.get("criteria"), list) else []
        normalized_criteria = []
        for idx, criterion in enumerate(criteria[:6]):
            if not isinstance(criterion, dict):
                continue
            normalized_criteria.append(
                {
                    "key": str(criterion.get("key") or idx),
                    "label": str(criterion.get("label") or criterion.get("title") or "분석 기준"),
                    "score": _gfa_banner_score_value(criterion.get("score"), fallback_score),
                    "observation": _gfa_banner_compact_list_text(criterion.get("observation")),
                    "interpretation": _gfa_banner_compact_list_text(criterion.get("interpretation") or criterion.get("analysis")),
                    "risk": _gfa_banner_compact_list_text(criterion.get("risk")),
                    "improvement": _gfa_banner_compact_list_text(criterion.get("improvement") or criterion.get("recommendation")),
                }
            )
        if not normalized_criteria:
            for factor in related[:4]:
                normalized_criteria.append(
                    {
                        "key": str(factor.get("key") or ""),
                        "label": str(factor.get("label") or "분석 기준"),
                        "score": _gfa_banner_score_value(factor.get("score"), fallback_score),
                        "observation": _gfa_banner_compact_list_text(factor.get("good")),
                        "interpretation": _gfa_banner_compact_list_text(factor.get("weak")),
                        "risk": "",
                        "improvement": _gfa_banner_compact_list_text(factor.get("improvement")),
                    }
                )
        dimensions.append(
            {
                "key": key,
                "title": str(raw_dimension.get("title") or spec["title"]),
                "score": _gfa_banner_score_value(raw_dimension.get("score"), fallback_score),
                "summary": _gfa_banner_compact_list_text(raw_dimension.get("summary") or raw_dimension.get("interpretation") or (element_analysis[0].get("strategic_meaning") if element_analysis else "")),
                "criteria": normalized_criteria[:6],
                "score_anchors": spec.get("score_anchors", {}),
            }
        )

    priority_actions = _gfa_banner_unique_texts(raw.get("priority_actions") if isinstance(raw.get("priority_actions"), list) else [], limit=6)
    return {
        "taxonomy_version": COMMERCIAL_BANNER_CREATIVE_ANALYSIS_TAXONOMY_V2["version"],
        "dimensions": dimensions,
        "priority_actions": priority_actions,
        "policy_conflict_guard": {
            "enabled": True,
            "principle": COMMERCIAL_BANNER_CREATIVE_ANALYSIS_TAXONOMY_V2["policy_conflict_principle"],
        },
    }


def _gfa_banner_text_blob(*values: object) -> str:
    parts: list[str] = []
    for value in values:
        try:
            parts.append(json.dumps(value, ensure_ascii=False, default=str) if isinstance(value, (dict, list)) else str(value or ""))
        except Exception:
            parts.append(str(value or ""))
    return " ".join(parts).lower()


def _gfa_banner_has_any(text: str, needles: list[str]) -> bool:
    return any(str(needle or "").lower() in text for needle in needles)


