@app.post("/gfa/creative-generator/runs", response_model=dict)
async def create_gfa_creative_generator_run(request: Request, db: Session = Depends(get_db)):
    req, additional_references = await _gfa_generator_request_from_http(request)
    goal = str(req.goal or "click").strip()
    if goal not in {"click", "conversion", "purchase"}:
        raise HTTPException(status_code=400, detail="goal must be click|conversion|purchase")
    template = _gfa_generator_template(req.template_type)
    strategy_payload = {}
    if req.date_from:
        strategy_payload["date_from"] = req.date_from
    if req.date_to:
        strategy_payload["date_to"] = req.date_to
    strategy_payload["include_product_context"] = True
    sources = _gfa_generator_sources_from_strategy(analyze_gfa_strategy(strategy_payload, db), limit=60)
    candidates = [x for x in sources.get("candidates", []) if isinstance(x, dict)]
    selected = None
    if req.source_creative_id:
        selected = next((x for x in candidates if str(x.get("creative_id") or "") == str(req.source_creative_id)), None)
    if selected is None:
        selected = next((x for x in candidates if str(x.get("recommended_goal") or "") == goal), None)
    if selected is None and candidates:
        selected = candidates[0]
    if selected is None:
        raise HTTPException(status_code=400, detail="생성 가능한 소재 제작 최적값 후보가 없습니다.")

    guide = sources.get("guide") if isinstance(sources.get("guide"), dict) else _gfa_banner_make_guide()
    brief = _gfa_generator_build_brief(goal=goal, template=template, source=selected, guide=guide)
    generation_source = str(req.generation_source or "existing").strip() or "existing"
    if generation_source not in {"existing", "appeal", "hybrid"}:
        generation_source = "existing"
    appeal_point_id = str(req.appeal_point_id or "").strip() or None
    if generation_source in {"appeal", "hybrid"} and appeal_point_id:
        from content_center_engine import apply_appeal_to_gfa_brief, get_appeal

        appeal = get_appeal(db, appeal_point_id)
        if appeal is None:
            raise HTTPException(status_code=404, detail="appeal_not_found")
        brief = apply_appeal_to_gfa_brief(brief, appeal)
    elif generation_source == "appeal" and not appeal_point_id:
        raise HTTPException(status_code=400, detail="appeal_point_id is required when generation_source=appeal")
    text_blocks = additional_references.get("text_blocks") if isinstance(additional_references.get("text_blocks"), list) else []
    image_refs = additional_references.get("images") if isinstance(additional_references.get("images"), list) else []
    file_refs = additional_references.get("files") if isinstance(additional_references.get("files"), list) else []
    source_image_ref = _gfa_generator_fetch_reference_image_from_url(
        str(selected.get("image_url") or ""),
        filename=f"selected_creative_{selected.get('creative_id') or 'source'}",
    )
    if source_image_ref:
        image_refs = [source_image_ref, *image_refs]
        file_refs = [
            {
                "filename": source_image_ref.get("filename"),
                "content_type": source_image_ref.get("mime_type"),
                "size": source_image_ref.get("size"),
                "source": source_image_ref.get("source"),
                "url": source_image_ref.get("url"),
            },
            *file_refs,
        ]
        text_blocks = [
            (
                "[선택 기준 소재 이미지]\n"
                f"creative_id={selected.get('creative_id') or ''}, name={selected.get('creative_name') or ''}\n"
                "첫 번째 참조 이미지는 사용자가 선택한 기준 소재입니다. 새 이미지는 이 기준 소재의 핵심 인물/제품/구도/문제 상황을 우선 반영해야 합니다."
            ),
            *text_blocks,
        ]
    product_image_ref = _gfa_generator_product_image_reference(db, selected)
    if product_image_ref:
        image_refs = [*image_refs, product_image_ref]
        file_refs = [
            *file_refs,
            {
                "filename": product_image_ref.get("filename"),
                "content_type": product_image_ref.get("mime_type"),
                "size": product_image_ref.get("size"),
                "source": product_image_ref.get("source"),
                "url": product_image_ref.get("url"),
                "product_url": product_image_ref.get("product_url"),
                "product_title": product_image_ref.get("product_title"),
            },
        ]
        text_blocks = [
            *text_blocks,
            (
                "[상품 대표 이미지]\n"
                f"product_title={product_image_ref.get('product_title') or ''}\n"
                "상품 대표 이미지는 필요 시 우측 제품/원료 영역에 작고 명확하게 활용한다. 텍스트 영역을 침범하지 않는다."
            ),
        ]
    if text_blocks or image_refs or file_refs:
        brief["additional_references"] = {
            "text": "\n\n".join(str(x) for x in text_blocks if str(x).strip())[:12000],
            "files": file_refs,
            "images": image_refs,
            "usage_rule": "첫 번째 이미지는 선택한 기준 소재이므로 이미지 생성의 최우선 시각 참고자료로 사용한다. 추가 참고자료는 보조 근거로만 사용하고, 성과 분석과 충돌하면 성과 분석을 우선한다.",
        }
    batch_id = uuid.uuid4().hex
    candidate_count = max(1, min(5, int(req.candidate_count or 3)))
    runs: list[NaverGfaCreativeGenerationRun] = []
    for idx in range(1, candidate_count + 1):
        combination = _gfa_generator_combination_strategy(brief=brief, candidate_index=idx, candidate_count=candidate_count)
        candidate_brief = {**brief, "combination_strategy": combination}
        candidate_brief_public = _gfa_generator_public_brief(candidate_brief)
        run = NaverGfaCreativeGenerationRun(
            id=uuid.uuid4().hex,
            batch_id=batch_id,
            candidate_index=idx,
            candidate_count=candidate_count,
            goal=goal,
            goal_label=_gfa_generator_goal_label(goal),
            template_type=str(template.get("type") or ""),
            template_label=str(template.get("label") or ""),
            source_creative_id=str(selected.get("creative_id") or "") or None,
            source_creative_name=str(selected.get("creative_name") or "") or None,
            generation_source=generation_source,
            appeal_point_id=appeal_point_id,
            source_snapshot_json=_gfa_generator_json_dumps(selected),
            guide_rules_json=_gfa_generator_json_dumps(guide),
            brief_json=_gfa_generator_json_dumps(candidate_brief_public),
            combination_strategy_json=_gfa_generator_json_dumps(combination),
            status="running",
            reviewer_status="pending",
            created_at=datetime.now(ZoneInfo("Asia/Seoul")),
            updated_at=datetime.now(ZoneInfo("Asia/Seoul")),
        )
        db.add(run)
        db.commit()

        try:
            copy_result, copy_prompt, openai_model = _gfa_generator_generate_copy(brief=candidate_brief_public, model=req.openai_model)
            candidate_evaluation = _gfa_creative_score_evaluation(
                brief=candidate_brief_public,
                copy_result=copy_result,
                combination=combination,
            )
            copy_result["creative_score"] = candidate_evaluation.get("creative_score")
            copy_result["creative_score_detail"] = candidate_evaluation
            explanation = _gfa_generator_explanation(brief=candidate_brief_public, combination=combination, copy_result=copy_result)
            explanation["creative_score"] = candidate_evaluation
            explanation["copy_validation"] = copy_result.get("copy_validation") if isinstance(copy_result.get("copy_validation"), dict) else {}
            run.copy_prompt = copy_prompt
            run.copy_result_json = _gfa_generator_json_dumps(copy_result)
            run.generation_explanation_json = _gfa_generator_json_dumps(explanation)
            run.openai_model = openai_model
            run.updated_at = datetime.now(ZoneInfo("Asia/Seoul"))
            db.add(run)
            db.commit()
            image_path, image_mime, image_prompt, gemini_model, base_image_path, base_image_mime, generation_debug = _gfa_generator_generate_image(
                brief=candidate_brief,
                copy_result=copy_result,
                combination=combination,
                model=req.gemini_model,
            )
            explanation["base_image_path"] = base_image_path
            explanation["base_image_mime_type"] = base_image_mime
            deterministic_product = generation_debug.get("productLayer") if isinstance(generation_debug.get("productLayer"), dict) else {}
            explanation["productLockedLayer"] = (
                _gfa_generator_available_product_locked_layer_metadata(
                    brief=candidate_brief,
                    base_image_path=base_image_path,
                    deterministic_product=deterministic_product,
                )
                if deterministic_product
                else _gfa_generator_product_locked_layer_metadata(
                    brief=candidate_brief,
                    base_image_path=base_image_path,
                    canvas_size=_gfa_generator_image_size_from_file(base_image_path),
                )
            )
            explanation["image_layering"] = {
                "mode": "product_free_base_plus_deterministic_product_layer_plus_server_text_overlay" if deterministic_product else "base_image_plus_server_text_overlay",
                "base_image_path": base_image_path,
                "final_image_path": image_path,
                "deterministic_product": generation_debug,
            }
            try:
                product_context = selected.get("product_context") if isinstance(selected.get("product_context"), dict) else {}
                _gfa_attach_product_authority(
                    db,
                    sku=str(product_context.get("product_id") or ""),
                    explanation=explanation,
                    resolve_mode="GENERATION",
                )
            except Exception as auth_exc:
                explanation["productAuthority"] = {
                    "status": "UNAVAILABLE",
                    "reason": str(auth_exc)[:300],
                    "productLockedLayerIsNotAuthority": True,
                    "version": "GFA_PRODUCT_AUTHORITY_V1",
                }
            run.image_prompt = image_prompt
            run.combination_strategy_json = _gfa_generator_json_dumps(combination)
            run.generation_explanation_json = _gfa_generator_json_dumps(explanation)
            run.image_path = image_path
            run.image_mime_type = image_mime
            run.gemini_model = gemini_model
            run.status = "generated"
            run.error = None
            _gfa_generation_add_event(
                db,
                run,
                event_type="generated",
                note=f"{idx}/{candidate_count}번 후보 생성 완료",
                payload={"combination_strategy": combination, "explanation": explanation, "creative_score": candidate_evaluation},
            )
        except Exception as exc:
            user_error = _gfa_generator_user_error(exc)
            run.status = "failed"
            run.error = user_error[:2000]
            failed_explanation = {
                "summary": f"{idx}/{candidate_count}번 후보 생성 실패",
                "error": user_error[:1000],
                "raw_error": str(exc)[:1000],
                "combination_strategy": combination,
            }
            run.generation_explanation_json = _gfa_generator_json_dumps(failed_explanation)
            _gfa_generation_add_event(
                db,
                run,
                event_type="generation_failed",
                note=f"{idx}/{candidate_count}번 후보 생성 실패",
                payload=failed_explanation,
            )
        run.updated_at = datetime.now(ZoneInfo("Asia/Seoul"))
        db.add(run)
        db.commit()
        db.refresh(run)
        runs.append(run)

    out = [_gfa_generation_run_to_dict(x, db) for x in runs]
    return {"ok": any(x.get("status") == "generated" for x in out), "run": out[0] if out else None, "runs": out, "batch_id": batch_id}


@app.get("/gfa/creative-generator/runs/{run_id}/image")
def get_gfa_creative_generator_run_image(run_id: str, db: Session = Depends(get_db)):
    row = db.get(NaverGfaCreativeGenerationRun, str(run_id or "").strip())
    if row is None or not row.image_path or not os.path.exists(row.image_path):
        raise HTTPException(status_code=404, detail="generated_image_not_found")
    return FileResponse(row.image_path, media_type=row.image_mime_type or "image/png")


@app.get("/gfa/creative-generator/runs/{run_id}/image/base")
def get_gfa_creative_generator_run_base_image(run_id: str, db: Session = Depends(get_db)):
    row = db.get(NaverGfaCreativeGenerationRun, str(run_id or "").strip())
    if row is None:
        raise HTTPException(status_code=404, detail="generation_run_not_found")
    try:
        explanation = json.loads(row.generation_explanation_json or "{}")
        if not isinstance(explanation, dict):
            explanation = {}
    except Exception:
        explanation = {}
    layering = explanation.get("image_layering") if isinstance(explanation.get("image_layering"), dict) else {}
    base_image_path = str(explanation.get("base_image_path") or layering.get("base_image_path") or "").strip()
    if not base_image_path or not os.path.exists(base_image_path):
        raise HTTPException(status_code=404, detail="base_image_not_found")
    return FileResponse(base_image_path, media_type=str(explanation.get("base_image_mime_type") or "image/png"))


def _gfa_replacement_compose_copy_overlay(img_bytes: bytes, copy_result: dict, combination: dict | None) -> tuple[bytes, str]:
    return _gfa_generator_overlay_copy_on_image(img_bytes, copy_result=copy_result, combination=combination)


def _gfa_replacement_persist_result(db: Session, row: NaverGfaCreativeGenerationRun, result: dict) -> dict:
    row.generation_explanation_json = _gfa_generator_json_dumps(result.get("explanation") or {})
    if result.get("image_path"):
        row.image_path = str(result["image_path"])
        row.image_mime_type = str(result.get("image_mime") or row.image_mime_type or "image/png")
        row.status = "generated"
        row.error = None
    row.updated_at = datetime.now(ZoneInfo("Asia/Seoul"))
    _gfa_generation_add_event(
        db,
        row,
        event_type=str(result.get("event_type") or "image_replacement"),
        note=str(result.get("event_note") or ""),
        payload=result.get("event_payload") if isinstance(result.get("event_payload"), dict) else {},
    )
    db.add(row)
    db.commit()
    db.refresh(row)
    return {"ok": True, "run": _gfa_generation_run_to_dict(row, db), "current_unchanged": bool(result.get("current_unchanged", True))}


