def download_gfa_creative_generator_run_image_base_artifact(run_id: str, db: Session = Depends(get_db)):
    from gfa_creative_image_replacement import GfaCreativeImageReplacementError, download_current_base

    row = db.get(NaverGfaCreativeGenerationRun, str(run_id or "").strip())
