@app.get("/search-rank/page-metrics/client-ip", response_model=dict)
def page_metrics_client_ip(req: Request):
    """
    브라우저(사용자 PC)에서 "내 사설 IP"를 자동 감지하기 어렵거나,
    NAS 도커/NAT 환경에서 서버가 client host를 172.*로 오인하는 경우를 진단/보조하기 위한 endpoint.
    """
    try:
        xf = (req.headers.get("x-forwarded-for") or "").strip()
        xr = (req.headers.get("x-real-ip") or "").strip()
        xe = (req.headers.get("x-erp2-client-ip") or "").strip()
    except Exception:
        xf = ""
        xr = ""
        xe = ""
    try:
        chost = str(getattr(req.client, "host", "") or "").strip()
    except Exception:
        chost = ""
    picked = None
    try:
        picked = _pick_client_ip_from_request(req)
    except Exception:
        picked = None
    return {
        "client_ip": picked,
        "client_host": chost or None,
        "x_forwarded_for": xf or None,
        "x_real_ip": xr or None,
        "x_erp2_client_ip": xe or None,
    }


async def _probe_cdp_json_version(*, host: str, port: int, timeout_sec: float = 0.25) -> bool:
    """
    CDP(Chrome remote debugging) 포트에 /json/version 이 살아있는지 가볍게 확인한다.
    - 별도 의존성 없이 raw HTTP로 확인한다.
    - 너무 오래 걸리면 UI 자동 입력이 느려지므로 timeout을 짧게 둔다.
    """
    h = str(host or "").strip()
    if not h:
        return False
    p = int(port or 0)
    if p <= 0:
        return False
    try:
        reader, writer = await asyncio.wait_for(asyncio.open_connection(h, p), timeout=timeout_sec)
        req = f"GET /json/version HTTP/1.1\r\nHost: {h}\r\nConnection: close\r\n\r\n"
        writer.write(req.encode("ascii", errors="ignore"))
        await writer.drain()
        data = await asyncio.wait_for(reader.read(4096), timeout=timeout_sec)
        try:
            writer.close()
            await writer.wait_closed()
        except Exception:
            pass
        txt = data.decode("utf-8", errors="ignore")
        # 응답 헤더 + 일부 본문에 'webSocketDebuggerUrl' 또는 'Browser'가 있으면 CDP로 간주
        try:
            first = (txt.splitlines()[0] if txt else "").strip()
            if first and (" 200 " not in (" " + first + " ")):
                return False
        except Exception:
            # 헤더 파싱 실패 시에도 아래 본문 기준으로 best-effort 판단한다.
            pass
        if "webSocketDebuggerUrl" in txt or "\"webSocketDebuggerUrl\"" in txt:
            return True
        if "\"Browser\"" in txt or "Chrome/" in txt:
            return True
        return False
    except Exception:
        return False


@app.get("/search-rank/page-metrics/discover-host-cdp", response_model=dict)
async def page_metrics_discover_host_cdp(
    request: Request,
    cidr: str | None = Query(None, description="(옵션) 스캔할 사설망 CIDR (예: 192.168.0.0/24)"),
):
    """
    NAS 도커/NAT 환경에서 request.client.host/x-forwarded-for가 172.*로 오염되어
    사용자 PC IP를 알 수 없는 경우가 있다.

    해결:
    - UI가 NAS 주소(예: 192.168.0.50)로부터 /24 CIDR을 추정해 넘기면,
      서버가 해당 대역에서 CDP(9223)의 /json/version 응답을 스캔하여
      "CDP가 떠있는 PC IP"를 찾아 반환한다.
    """
    def _safe_private_ipv4(s: str | None) -> str | None:
        ss = (s or "").strip()
        if not ss:
            return None
        try:
            ip = ipaddress.ip_address(ss)
        except Exception:
            return None
        if ip.version != 4:
            return None
        if ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified:
            return None
        if not ip.is_private:
            return None
        return str(ip)

    def _pick_forwarded_for(req: Request) -> str | None:
        xf = (req.headers.get("x-forwarded-for") or "").strip()
        if not xf:
            return None
        # "client, proxy1, proxy2" 형태에서 client만 사용
        first = (xf.split(",")[0] or "").strip()
        return _safe_private_ipv4(first)

    def _pick_real_ip(req: Request) -> str | None:
        xr = (req.headers.get("x-real-ip") or "").strip()
        if not xr:
            return None
        return _safe_private_ipv4(xr)

    def _pick_request_host_ip(req: Request) -> str | None:
        raw = (req.headers.get("host") or "").strip()
        if not raw:
            return None
        host_only = raw
        if raw.startswith("[") and "]" in raw:
            host_only = raw[1 : raw.index("]")]
        elif ":" in raw:
            host_only = raw.split(":", 1)[0].strip()
        return _safe_private_ipv4(host_only)

    def _same_cidr24(ip_a: str | None, ip_b: str | None) -> bool:
        if not ip_a or not ip_b:
            return False
        aa = ip_a.split(".")
        bb = ip_b.split(".")
        return len(aa) == 4 and len(bb) == 4 and aa[:3] == bb[:3]

    def _cidr24_from_ip(ip_s: str) -> str:
        parts = ip_s.split(".")
        return f"{parts[0]}.{parts[1]}.{parts[2]}.0/24"

    # 포트는 PW_CDP_URL에서 읽되 기본 9223
    port = 9223
    try:
        u = urlparse((os.getenv("PW_CDP_URL", "") or "").strip() or "http://127.0.0.1:9223")
        port = int(u.port or 9223)
    except Exception:
        port = 9223

    # 1) CIDR 스캔 전에 "가장 그럴듯한 후보 IP"를 먼저 시도한다.
    # - NAS 환경에서 request.client.host, x-forwarded-for, x-real-ip 가 172.* 브리지로 오염될 수 있다.
    # - 따라서 NAS Web의 Host 헤더(예: 192.168.0.50:6188)에서 LAN 대역을 얻고,
    #   같은 /24 대역 후보만 자동 선택 대상으로 신뢰한다.
    hdr_ip = _safe_private_ipv4(request.headers.get("x-erp2-client-ip"))
    fwd_ip = _pick_forwarded_for(request)
    real_ip = _pick_real_ip(request)
    req_ip = _safe_private_ipv4(getattr(getattr(request, "client", None), "host", None))
    req_host_ip = _pick_request_host_ip(request)
    candidates: list[str] = []
    for ip in (hdr_ip, fwd_ip, real_ip, req_ip):
        if ip and ip not in candidates:
            candidates.append(ip)

    trusted_candidates = [ip for ip in candidates if not _looks_like_docker_bridge_ipv4(ip)]
    if req_host_ip:
        trusted_candidates = [
            ip
            for ip in candidates
            if _same_cidr24(ip, req_host_ip) and not _looks_like_docker_bridge_ipv4(ip)
        ]

    scanned = 0
    for ip in trusted_candidates:
        scanned += 1
        ok = await _probe_cdp_json_version(host=ip, port=port, timeout_sec=0.8)
        if ok:
            return {
                "found": True,
                "ip": ip,
                "port": port,
                "cidr": None,
                "scanned": scanned,
                "method": "candidate_probe",
                "candidates": trusted_candidates,
            }

    # 모달 오픈 시점에는 아직 Host Chrome/CDP가 열리기 전일 수 있다.
    # 이 경우에도 nginx가 전달한 "요청을 보낸 PC IP"를 먼저 고정하면,
    # 사용자가 수동 입력을 잊어 발생하는 오류를 줄일 수 있다.
    hint_ip = next((ip for ip in trusted_candidates if ip != req_host_ip), None)
    if hint_ip:
        return {
            "found": True,
            "ip": hint_ip,
            "port": port,
            "cidr": None,
            "scanned": scanned,
            "method": "candidate_hint",
            "verified": False,
            "candidates": trusted_candidates,
        }

    # 2) CIDR 준비: (a) UI가 준 cidr (b) 후보 IP에서 /24 유도
    cidr_s = str(cidr or "").strip()
    if not cidr_s and req_host_ip:
        cidr_s = _cidr24_from_ip(req_host_ip)
    if not cidr_s and trusted_candidates:
        cidr_s = _cidr24_from_ip(trusted_candidates[0])
    if not cidr_s:
        raise HTTPException(
            status_code=400,
            detail="cidr_required",
        )

    try:
        net = ipaddress.ip_network(cidr_s, strict=False)
    except Exception:
        raise HTTPException(status_code=400, detail="cidr_invalid")
    if net.version != 4:
        raise HTTPException(status_code=400, detail="cidr_ipv4_only")
    if not net.is_private:
        raise HTTPException(status_code=400, detail="cidr_private_only")
    # 안전장치: 너무 넓은 스캔 금지(최대 /24)
    if int(net.prefixlen) < 24:
        raise HTTPException(status_code=400, detail="cidr_too_wide")

    sem = asyncio.Semaphore(48)
    found: str | None = None

    async def _one(ip: str) -> str | None:
        nonlocal scanned
        async with sem:
            scanned += 1
            ok = await _probe_cdp_json_version(host=ip, port=port, timeout_sec=0.55)
            return ip if ok else None

    # 전체를 한 번에 gather하면 메모리가 커질 수 있어, 배치로 끊어서 스캔한다.
    ips = [str(h) for h in net.hosts()]
    for i in range(0, len(ips), 96):
        if found:
            break
        batch = ips[i : i + 96]
        tasks = [asyncio.create_task(_one(ip)) for ip in batch]
        try:
            for t in asyncio.as_completed(tasks, timeout=10.0):
                try:
                    r = await t
                except Exception:
                    r = None
                if r:
                    found = r
                    break
        except Exception:
            pass
        finally:
            for t in tasks:
                try:
                    t.cancel()
                except Exception:
                    pass

    return {
        "found": bool(found),
        "ip": found,
        "port": port,
        "cidr": cidr_s,
        "scanned": scanned,
        "method": "cidr_scan",
        "candidates": candidates,
    }


@app.get("/search-rank/page-metrics/status", response_model=dict)
def page_metrics_status(db: Session = Depends(get_db)):
    """
    페이지 메트릭(HTML 기반) 동기화 작업의 오늘 상태를 반환한다.
    - UI에서 "자동 실행됨/실패(429)/다음 재시도 가능 시각" 등을 표시하기 위함.
    """
    today = _today_kst()
    row: AnalyticsJobRun | None = (
        db.query(AnalyticsJobRun)
        .filter(AnalyticsJobRun.job_name == PAGE_METRICS_JOB_NAME, AnalyticsJobRun.run_date == today)
        .one_or_none()
    )
    if not row:
        return {"status": "IDLE", "detail": None, "started_at": None, "finished_at": None, "next_retry_at": None}

    started_at = row.started_at.isoformat() if row.started_at else None
    finished_at = row.finished_at.isoformat() if row.finished_at else None
    next_retry_at = None
    if (row.status or "").upper() == "FAILED" and "rate_limited" in (row.detail or "") and row.finished_at:
        try:
            # 20분 쿨다운 정책과 동일
            next_retry_at = (row.finished_at + timedelta(minutes=20)).isoformat()
        except Exception:
            next_retry_at = None
    return {
        "status": row.status,
        "detail": row.detail,
        "started_at": started_at,
        "finished_at": finished_at,
        "next_retry_at": next_retry_at,
    }


@app.post("/search-rank/page-metrics/batch", response_model=List[ProductPageMetrics])
def get_page_metrics_batch(
    payload: ProductPageMetricsBatchRequest,
    db: Session = Depends(get_db),
):
    """
    여러 URL에 대해 '가장 최신(최대 date)' 페이지 메트릭을 반환한다.
    """
    urls = [(u or "").strip() for u in (payload.urls or []) if (u or "").strip()]
    if not urls:
        return []
    out: list[ProductPageMetrics] = []
    for u in urls:
        rows: List[TrackedProductPageDaily] = (
            db.query(TrackedProductPageDaily)
            .filter(TrackedProductPageDaily.product_url == u)
            .order_by(TrackedProductPageDaily.date.desc())
            .limit(2)
            .all()
        )
        if not rows:
            continue
        latest = rows[0]
        prev = rows[1] if len(rows) >= 2 else None

        # 정책:
        # - 최신 행이 "오늘"이지만, 판매정보(최근 1주 구매/최근 3개월 재구매)가 비어있으면
        #   직전 데이터로 보완해 UI에 노출한다(요청: 오늘 못 받으면 과거 데이터 노출).
        try:
            if prev is not None and latest.date == _today_kst():
                if getattr(latest, "recent_purchase_7d_count", None) is None and getattr(prev, "recent_purchase_7d_count", None) is not None:
                    latest.recent_purchase_7d_count = prev.recent_purchase_7d_count  # type: ignore[attr-defined]
                if getattr(latest, "recent_repurchase_3m_count", None) is None and getattr(prev, "recent_repurchase_3m_count", None) is not None:
                    latest.recent_repurchase_3m_count = prev.recent_repurchase_3m_count  # type: ignore[attr-defined]
                # 텍스트도 없으면 과거 것을 보완(선택)
                if not str(getattr(latest, "recent_badge_text", "") or "").strip() and str(getattr(prev, "recent_badge_text", "") or "").strip():
                    latest.recent_badge_text = prev.recent_badge_text  # type: ignore[attr-defined]
                # 찜/등록일은 정적 또는 변동 폭이 작아, 오늘 수집이 비었으면 과거 값을 보완한다.
                if getattr(latest, "wish_count", None) is None and getattr(prev, "wish_count", None) is not None:
                    latest.wish_count = prev.wish_count  # type: ignore[attr-defined]
                if getattr(latest, "registered_date", None) is None and getattr(prev, "registered_date", None) is not None:
                    latest.registered_date = prev.registered_date  # type: ignore[attr-defined]
        except Exception:
            pass

        try:
            if latest.date == _today_kst():
                seed_metrics = _apply_page_metrics_seed_fallback(
                    db,
                    u,
                    {
                        "wish_count": getattr(latest, "wish_count", None),
                        "registered_date": getattr(latest, "registered_date", None),
                    },
                )
                if getattr(latest, "wish_count", None) is None and seed_metrics.get("wish_count") is not None:
                    latest.wish_count = seed_metrics.get("wish_count")  # type: ignore[attr-defined]
                if getattr(latest, "registered_date", None) is None and seed_metrics.get("registered_date") is not None:
                    latest.registered_date = seed_metrics.get("registered_date")  # type: ignore[attr-defined]
        except Exception:
            pass

        out.append(latest)  # pydantic from_attributes
    return out


@app.get("/search-rank/page-metrics/compare", response_model=ProductPageMetricsCompare)
def get_page_metrics_compare(
    product_url: str = Query(..., description="비교할 상품 URL"),
    db: Session = Depends(get_db),
):
    """
    한 URL에 대해 '가장 최신 1건'과 '그 이전 1건'을 반환한다.
    - 상세 화면 상단의 전일 대비(가격/리뷰/평점) 표시에 사용
    """
    u = (product_url or "").strip()
    if not u:
        raise HTTPException(status_code=400, detail="product_url is required")
    rows: List[TrackedProductPageDaily] = (
        db.query(TrackedProductPageDaily)
        .filter(TrackedProductPageDaily.product_url == u)
        .order_by(TrackedProductPageDaily.date.desc())
        .limit(2)
        .all()
    )
    latest = rows[0] if len(rows) >= 1 else None
    prev = rows[1] if len(rows) >= 2 else None
    # 정책: 최신이 오늘이지만 판매정보를 못 받으면 과거 값을 노출
    try:
        if latest is not None and prev is not None and latest.date == _today_kst():
            if getattr(latest, "recent_purchase_7d_count", None) is None and getattr(prev, "recent_purchase_7d_count", None) is not None:
                latest.recent_purchase_7d_count = prev.recent_purchase_7d_count  # type: ignore[attr-defined]
            if getattr(latest, "recent_repurchase_3m_count", None) is None and getattr(prev, "recent_repurchase_3m_count", None) is not None:
                latest.recent_repurchase_3m_count = prev.recent_repurchase_3m_count  # type: ignore[attr-defined]
            if not str(getattr(latest, "recent_badge_text", "") or "").strip() and str(getattr(prev, "recent_badge_text", "") or "").strip():
                latest.recent_badge_text = prev.recent_badge_text  # type: ignore[attr-defined]
            if getattr(latest, "wish_count", None) is None and getattr(prev, "wish_count", None) is not None:
                latest.wish_count = prev.wish_count  # type: ignore[attr-defined]
            if getattr(latest, "registered_date", None) is None and getattr(prev, "registered_date", None) is not None:
                latest.registered_date = prev.registered_date  # type: ignore[attr-defined]
    except Exception:
        pass
    latest_out = (
        ProductPageMetrics.model_validate(latest, from_attributes=True) if latest else None
    )
    prev_out = (
        ProductPageMetrics.model_validate(prev, from_attributes=True) if prev else None
    )
    return ProductPageMetricsCompare(product_url=u, latest=latest_out, prev=prev_out)


@app.get("/search-rank/product-sales-manual", response_model=ProductSalesManual)
def get_product_sales_manual(
    product_url: str = Query(..., description="상품 URL(정규화된 base URL 권장)"),
    db: Session = Depends(get_db),
):
    u = (product_url or "").strip()
    if not u:
        raise HTTPException(status_code=400, detail="product_url is required")
    row: TrackedProductSalesManual | None = (
        db.query(TrackedProductSalesManual)
        .filter(TrackedProductSalesManual.product_url == u)
        .one_or_none()
    )
    if row is None:
        # 미존재 시 빈 값으로 반환(프론트에서 '수기 입력 없음' 처리)
        return ProductSalesManual(product_url=u)
    return row  # pydantic from_attributes


@app.put("/search-rank/product-sales-manual", response_model=ProductSalesManual)
def put_product_sales_manual(
    payload: ProductSalesManualUpsert,
    db: Session = Depends(get_db),
):
    u = (payload.product_url or "").strip()
    if not u:
        raise HTTPException(status_code=400, detail="product_url is required")
    try:
        row = upsert_tracked_product_sales_manual(
            db,
            product_url=u,
            expected_sales_7d=payload.expected_sales_7d,
            expected_revenue_7d_manwon=payload.expected_revenue_7d_manwon,
            recent_purchase_1w_count=payload.recent_purchase_1w_count,
            recent_repurchase_3m_count=payload.recent_repurchase_3m_count,
        )
        # (요청) 수기 입력을 하면 "판매정보 수집 완료"로도 갱신되게 한다.
        # - UI의 완료 판정은 tracked_product_page_daily의 recent_purchase_status 기반이므로,
        #   오늘 날짜 row에 판매정보를 보강(upsert)한다.
        try:
            today = _today_kst().isoformat()
            purchase_7d = (
                payload.recent_purchase_1w_count
                if payload.recent_purchase_1w_count is not None
                else payload.expected_sales_7d
            )
            repurchase_3m = payload.recent_repurchase_3m_count
            # base 메트릭(제목/가격/리뷰/평점)이 없으면 UI에서 "미수집"으로 남을 수 있어,
            # 가능한 경우 기존 수집 데이터/메타에서 값을 보강해 준다.
            base_title = None
            base_price = None
            base_review = None
            base_rating = None
            base_delivery = None
            base_buy = None
            try:
                last: TrackedProductPageDaily | None = (
                    db.query(TrackedProductPageDaily)
                    .filter(TrackedProductPageDaily.product_url == u)
                    .order_by(TrackedProductPageDaily.date.desc())
                    .limit(1)
                    .one_or_none()
                )
                if last is not None:
                    base_title = last.title
                    base_price = last.price
                    base_review = last.review_count
                    base_rating = last.rating
                    base_delivery = last.delivery
                    base_buy = last.buy_count
            except Exception:
                pass
            if base_title is None or base_price is None:
                try:
                    meta: TrackedProductMeta | None = (
                        db.query(TrackedProductMeta)
                        .filter(TrackedProductMeta.product_url == u)
                        .one_or_none()
                    )
                    if meta is not None:
                        if base_title is None:
                            base_title = meta.title
                        if base_price is None:
                            base_price = meta.price
                except Exception:
                    pass
            upsert_tracked_product_page_daily(
                target_date=today,
                product_url=u,
                title=base_title,
                price=base_price,
                review_count=base_review,
                rating=base_rating,
                delivery=base_delivery,
                buy_count=base_buy,
                recent_purchase_status=("collected" if purchase_7d is not None else None),
                # 호환/표시용: 7d 고정값을 메인으로 채운다.
                recent_purchase_7d_count=int(purchase_7d) if purchase_7d is not None else None,
                recent_purchase_count=int(purchase_7d) if purchase_7d is not None else None,
                recent_purchase_window=("7d" if purchase_7d is not None else None),
                recent_repurchase_3m_count=int(repurchase_3m) if repurchase_3m is not None else None,
                recent_repurchase_count=int(repurchase_3m) if repurchase_3m is not None else None,
                recent_repurchase_window=("3m" if repurchase_3m is not None else None),
                http_status=200,
                error=None,
            )
        except Exception:
            # 수기 입력 저장은 성공시켜야 하므로, 보조 갱신 실패는 무시
            pass
        return row
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))


# -----------------------------
# 상품지수(점수화) - 내 상품 추적 기반
# -----------------------------


def _clamp_int(x: object, *, lo: int = 0, hi: int = 100) -> int:
    try:
        n = int(float(x)) if x is not None else 0
    except Exception:
        n = 0
    if n < lo:
        return lo
    if n > hi:
        return hi
    return n


def _safe_ratio(num: float, den: float, *, default: float = 1.0) -> float:
    try:
        n = float(num)
        d = float(den)
    except Exception:
        return float(default)
    if not math.isfinite(n) or not math.isfinite(d):
        return float(default)
    if d <= 0:
        return float(default)
    return float(n / d)


def _score_click_proxy(*, C: int, V: int, CTR: float, CTR_cat_avg: float) -> int:
    """
    요청 공식(패널티 없음 전제):
    Proxy_Click_Score = min( 100,
      log(C+1)*40 + log(V+1)*40 + (CTR/CTR_cat_avg)*20
    )

    - C: 최근 7일 광고 클릭수
    - V: 최근 7일 광고 전환수
    - CTR: 최근 7일 광고 CTR (clicks/impressions, 0~1)
    - CTR_cat_avg: 동일 카테고리 평균 CTR(0~1)
    """
    c = max(0, int(C or 0))
    v = max(0, int(V or 0))
    ctr = float(CTR or 0.0)
    if not math.isfinite(ctr) or ctr < 0:
        ctr = 0.0
    ctr_avg = float(CTR_cat_avg or 0.0)
    if not math.isfinite(ctr_avg) or ctr_avg <= 0:
        # 카테고리 평균이 없으면 ratio=1로 두어 과대/과소를 막는다.
        ctr_avg = ctr if ctr > 0 else 1.0
    ratio = _safe_ratio(ctr, ctr_avg, default=1.0)
    raw = (math.log(c + 1.0) * 40.0) + (math.log(v + 1.0) * 40.0) + (ratio * 20.0)
    # score는 0~100 정수로 clamp
    return _clamp_int(round(raw), lo=0, hi=100)


def _score_review(*, rating: float, review_count: int) -> int:
    r = float(rating or 0.0)
    if not math.isfinite(r):
        r = 0.0
    r = max(0.0, min(5.0, r))
    cnt = int(review_count or 0)
    if cnt < 0:
        cnt = 0
    raw = r * 20.0
    if cnt > 0:
        raw += math.log(cnt) * 2.0
    if r < 3.0:
        raw *= 0.5
    return _clamp_int(raw, lo=0, hi=100)


def _score_recency(*, days_since_reg: int) -> int:
    d = int(days_since_reg or 0)
    if d < 0:
        d = 0
    if d <= 30:
        return 100
    if d <= 90:
        return 70
    if d <= 180:
        return 40
    return 0


def _score_sales(*, sales_7d: int, sales_30d: int) -> int:
    """
    판매 점수는 원본 로직에서는 상한이 없으나,
    UI/비교(Δ) 요구사항을 위해 0~100 정규화 점수로 변환한다.

    정규화(구조적 안정성):
    - raw = sales_7d*5 + sales_30d*1
    - log1p 스케일로 완만하게 증가시키고 0~100으로 clamp
    """
    s7 = max(0, int(sales_7d or 0))
    s30 = max(0, int(sales_30d or 0))
    raw = float(s7 * 5 + s30)
    # 기준값(튜닝 가능): raw=5000이면 대략 100점 근처
    denom = math.log1p(5000.0)
    score = 0.0 if raw <= 0 else (math.log1p(raw) / denom * 100.0)
    return _clamp_int(score, lo=0, hi=100)


def _score_penalty(*, delay_count: int, sold_out_days: int) -> int:
    # 원본 패널티: (delay*5) + (sold_out_days*2)
    d = max(0, int(delay_count or 0))
    s = max(0, int(sold_out_days or 0))
    raw = d * 5 + s * 2
    return _clamp_int(raw, lo=0, hi=100)


def _sum_ads_metrics_7d_for_product(
    db: Session,
    *,
    product_url: str,
    title: str | None,
    date_to: date,
) -> dict:
    """
    상품 URL 기준으로 최근 7일 광고 지표(C,V,I)를 합산한다.
    - 우선: creative_organic_rank_daily_derived.matched_product_url 로 안전 매칭
    - fallback: NaverAdCreativeDaily.product_title 포함 매칭(정확도 낮음, 마지막 수단)
    """
    dt = date_to
    d7 = dt - timedelta(days=6)
    base = _canonicalize_smartstore_base_url(product_url) or str(product_url or "").strip()
    if not base:
        return {"impressions": 0, "clicks": 0, "conversions": 0, "ctr": 0.0, "source": "none"}

    # 1) derived join (정확)
    try:
        q = (
            db.query(
                func.count(NaverAdCreativeDaily.creative_id),
                func.sum(NaverAdCreativeDaily.impressions),
                func.sum(NaverAdCreativeDaily.clicks),
                func.sum(NaverAdCreativeDaily.conversions),
            )
            .join(
                CreativeOrganicDerived,
                and_(
                    NaverAdCreativeDaily.date == CreativeOrganicDerived.date,
                    NaverAdCreativeDaily.campaign_name == CreativeOrganicDerived.campaign_name,
                    NaverAdCreativeDaily.adgroup_name == CreativeOrganicDerived.adgroup_name,
                    NaverAdCreativeDaily.creative_id == CreativeOrganicDerived.creative_id,
                    NaverAdCreativeDaily.device == CreativeOrganicDerived.device,
                ),
            )
            .filter(
                CreativeOrganicDerived.matched_product_url == base,
                NaverAdCreativeDaily.date >= d7,
                NaverAdCreativeDaily.date <= dt,
            )
        )
        row_cnt, s_impr, s_clk, s_conv = q.one()
        if int(row_cnt or 0) > 0:
            impr = int(s_impr or 0)
            clk = int(s_clk or 0)
            conv = int(s_conv or 0)
            ctr = float(clk / impr) if impr > 0 else 0.0
            return {"impressions": impr, "clicks": clk, "conversions": conv, "ctr": ctr, "source": "creative_derived", "rows": int(row_cnt or 0)}
        # matched rows가 없으면 원천 creative product_title fallback으로 실제 0/수집 누락을 다시 판단한다.
        # 기존에는 합계 0도 creative_derived로 확정해 클릭 점수가 오경고로 떨어질 수 있었다.
        pass
    except Exception:
        pass

    # 2) title fallback (정확도 낮음)
    # SmartStore 메타는 환경/수집 경로에 따라 "상품명 : 스토어명" suffix가 붙을 수 있다.
    # 광고 리포트의 product_title은 suffix가 없는 경우가 많으므로 같은 정규화 규칙을 적용한다.
    t = _normalize_product_title(title, mall_name=_infer_smartstore_mall_name(base)) or str(title or "").strip()
    if len(t) >= 4:
        try:
            q = (
                db.query(
                    func.count(NaverAdCreativeDaily.creative_id),
                    func.sum(NaverAdCreativeDaily.impressions),
                    func.sum(NaverAdCreativeDaily.clicks),
                    func.sum(NaverAdCreativeDaily.conversions),
                )
                .filter(
                    NaverAdCreativeDaily.product_title.isnot(None),
                    NaverAdCreativeDaily.product_title.ilike(f"%{t}%"),
                    NaverAdCreativeDaily.date >= d7,
                    NaverAdCreativeDaily.date <= dt,
                )
            )
            row_cnt, s_impr, s_clk, s_conv = q.one()
            if int(row_cnt or 0) > 0:
                impr = int(s_impr or 0)
                clk = int(s_clk or 0)
                conv = int(s_conv or 0)
                ctr = float(clk / impr) if impr > 0 else 0.0
                return {"impressions": impr, "clicks": clk, "conversions": conv, "ctr": ctr, "source": "creative_title", "rows": int(row_cnt or 0)}
        except Exception:
            pass

    return {"impressions": 0, "clicks": 0, "conversions": 0, "ctr": 0.0, "source": "none", "rows": 0}


def _ctr_cat_avg_7d(
    db: Session,
    *,
    category_key: str | None,
    date_to: date,
) -> dict:
    """
    동일 카테고리 평균 CTR(최근 7일).
    - category_key가 없거나 데이터가 없으면 ctr_cat_avg=0으로 반환(상위에서 ratio=1 처리).
    """
    key = str(category_key or "").strip()
    if not key:
        return {"ctr_cat_avg": 0.0, "source": "none"}
    dt = date_to
    d7 = dt - timedelta(days=6)
    try:
        # category3 우선, 없으면 category2/1로 내려갈 수 있으나 key 자체에 이미 반영해서 호출한다.
        rows = (
            db.query(TrackedProductMeta.product_url)
            .filter(
                or_(
                    TrackedProductMeta.category3 == key,
                    TrackedProductMeta.category2 == key,
                    TrackedProductMeta.category1 == key,
                )
            )
            .limit(400)
            .all()
        )
        urls = []
        seen = set()
        for (u0,) in rows or []:
            u = _canonicalize_smartstore_base_url(str(u0 or "").strip()) or str(u0 or "").strip()
            if not u:
                continue
            if u in seen:
                continue
            seen.add(u)
            urls.append(u)
        urls = urls[:200]
        if not urls:
            return {"ctr_cat_avg": 0.0, "source": "none"}

        q = (
            db.query(
                func.sum(NaverAdCreativeDaily.impressions),
                func.sum(NaverAdCreativeDaily.clicks),
            )
            .join(
                CreativeOrganicDerived,
                and_(
                    NaverAdCreativeDaily.date == CreativeOrganicDerived.date,
                    NaverAdCreativeDaily.campaign_name == CreativeOrganicDerived.campaign_name,
                    NaverAdCreativeDaily.adgroup_name == CreativeOrganicDerived.adgroup_name,
                    NaverAdCreativeDaily.creative_id == CreativeOrganicDerived.creative_id,
                    NaverAdCreativeDaily.device == CreativeOrganicDerived.device,
                ),
            )
            .filter(
                CreativeOrganicDerived.matched_product_url.in_(urls),
                NaverAdCreativeDaily.date >= d7,
                NaverAdCreativeDaily.date <= dt,
            )
        )
        s_impr, s_clk = q.one()
        impr = int(s_impr or 0)
        clk = int(s_clk or 0)
        ctr = float(clk / impr) if impr > 0 else 0.0
        return {"ctr_cat_avg": ctr, "source": "category_meta"}
    except Exception:
        return {"ctr_cat_avg": 0.0, "source": "none"}

def _calc_product_index_scores(*, inputs: dict) -> dict:
    click = _score_click_proxy(
        C=int(inputs.get("ad_clicks_7d") or 0),
        V=int(inputs.get("ad_conversions_7d") or 0),
        CTR=float(inputs.get("ctr_7d") or 0.0),
        CTR_cat_avg=float(inputs.get("ctr_cat_avg_7d") or 0.0),
    )
    sales = _score_sales(
        sales_7d=int(inputs.get("sales_7d") or 0),
        sales_30d=int(inputs.get("sales_30d") or 0),
    )
    review = _score_review(
        rating=float(inputs.get("rating") or 0.0),
        review_count=int(inputs.get("review_count") or 0),
    )
    recency = _score_recency(days_since_reg=int(inputs.get("days_since_reg") or 0))
    # (요청) 패널티는 현재 점수 계산에서 사용하지 않는다.
    penalty = 0

    # 가중치(요청 문서 기준): 클릭20/판매35/리뷰25/최신성10
    final_raw = click * 0.2 + sales * 0.35 + review * 0.25 + recency * 0.1
    final = _clamp_int(round(final_raw), lo=0, hi=100)

    return {
        "click": int(click),
        "sales": int(sales),
        "review": int(review),
        "recency": int(recency),
        "penalty": int(penalty),
        "final": int(final),
    }


def _calc_product_index_explain(*, inputs: dict) -> dict:
    """
    상품지수 점수 산출 근거를 화면에 표시하기 위한 설명 객체를 만든다.
    - 프론트가 계산식을 중복 구현하지 않도록 서버에서 단일 소스로 제공한다.
    """
    v = int(inputs.get("weekly_views_7d") or 0)
    w = int(inputs.get("wishes") or 0)
    c = int(inputs.get("ad_clicks_7d") or 0)
    conv = int(inputs.get("ad_conversions_7d") or 0)
    impr = int(inputs.get("ad_impressions_7d") or 0)
    ctr = float(inputs.get("ctr_7d") or 0.0)
    ctr_cat = float(inputs.get("ctr_cat_avg_7d") or 0.0)
    s7 = int(inputs.get("sales_7d") or 0)
    s30 = int(inputs.get("sales_30d") or 0)
    rating = float(inputs.get("rating") or 0.0)
    review_count = int(inputs.get("review_count") or 0)
    days_since_reg = int(inputs.get("days_since_reg") or 0)

    # click (Proxy_Click_Score)
    ctr_ratio = _safe_ratio(ctr, (ctr_cat if ctr_cat > 0 else (ctr if ctr > 0 else 1.0)), default=1.0)
    term_c = math.log(max(0, c) + 1.0) * 40.0
    term_v = math.log(max(0, conv) + 1.0) * 40.0
    term_ctr = ctr_ratio * 20.0
    click_raw = term_c + term_v + term_ctr
    click_score = _score_click_proxy(C=c, V=conv, CTR=ctr, CTR_cat_avg=ctr_cat)

    # sales
    sales_raw = float(max(0, s7) * 5 + max(0, s30))
    denom = math.log1p(5000.0)
    sales_score = _score_sales(sales_7d=s7, sales_30d=s30)
    sales_scaled = 0.0 if sales_raw <= 0 else (math.log1p(sales_raw) / denom * 100.0)

    # review
    r = float(rating or 0.0)
    if not math.isfinite(r):
        r = 0.0
    r = max(0.0, min(5.0, r))
    cnt = max(0, int(review_count or 0))
    review_raw = r * 20.0 + (math.log(cnt) * 2.0 if cnt > 0 else 0.0)
    review_adjusted = review_raw * (0.5 if r < 3.0 else 1.0)
    review_score = _score_review(rating=r, review_count=cnt)

    # recency
    recency_score = _score_recency(days_since_reg=days_since_reg)
    bucket = "over_180"
    if days_since_reg <= 30:
        bucket = "0_30"
    elif days_since_reg <= 90:
        bucket = "31_90"
    elif days_since_reg <= 180:
        bucket = "91_180"

    # final
    weights = {"click": 0.2, "sales": 0.35, "review": 0.25, "recency": 0.1, "penalty": 0.0}
    final_raw = click_score * weights["click"] + sales_score * weights["sales"] + review_score * weights["review"] + recency_score * weights["recency"]
    final_score = _clamp_int(round(final_raw), lo=0, hi=100)

    return {
        "weights": weights,
        "click": {
            "inputs": {"C": c, "V": conv, "I": impr, "CTR": ctr, "CTR_cat_avg": ctr_cat},
            "formula": "min(100, log(C+1)*40 + log(V+1)*40 + (CTR/CTR_cat_avg)*20)",
            "raw": click_raw,
            "terms": {"logC*40": term_c, "logV*40": term_v, "ctr_ratio*20": term_ctr, "ctr_ratio": ctr_ratio},
            "score": click_score,
        },
        "sales": {
            "inputs": {"sales_7d": s7, "sales_30d": s30},
            "formula": "min(100, log1p(sales_7d*5 + sales_30d) / log1p(5000) * 100)",
            "raw": sales_raw,
            "scaled": sales_scaled,
            "score": sales_score,
        },
        "review": {
            "inputs": {"rating": r, "review_count": cnt},
            "formula": "min(100, (rating*20 + log(review_count)*2) * (0.5 if rating<3 else 1))",
            "raw": review_raw,
            "adjusted": review_adjusted,
            "score": review_score,
        },
        "recency": {
            "inputs": {"days_since_reg": days_since_reg},
            "rule": "≤30:100, ≤90:70, ≤180:40, else:0",
            "bucket": bucket,
            "score": recency_score,
        },
        "penalty": {"enabled": False, "score": 0},
        "final": {
            "formula": "round(click*0.2 + sales*0.35 + review*0.25 + recency*0.1)",
            "raw": final_raw,
            "score": final_score,
        },
    }


PRODUCT_INDEX_DAILY_JOB_NAME = "product-index-daily"


@app.get("/search-rank/product-index-manual", response_model=ProductIndexManual)
def get_product_index_manual(
    product_url: str = Query(..., description="상품 URL(정규화된 base URL 권장)"),
    db: Session = Depends(get_db),
):
    u_raw = (product_url or "").strip()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    u_base = _canonicalize_smartstore_base_url(u_raw) or u_raw

    filters = _smartstore_product_url_filters(TrackedProductIndexManual, product_url=u_raw)
    row: TrackedProductIndexManual | None = None
    if filters:
        row = db.query(TrackedProductIndexManual).filter(or_(*filters)).limit(1).one_or_none()
    else:
        row = (
            db.query(TrackedProductIndexManual)
            .filter(TrackedProductIndexManual.product_url == u_base)
            .one_or_none()
        )
    if row is None:
        return ProductIndexManual(product_url=u_base)
    # 정규화된 base URL로 응답(프론트 state/키 통일)
    try:
        row.product_url = u_base  # type: ignore[assignment]
    except Exception:
        pass
    return row  # pydantic from_attributes


@app.put("/search-rank/product-index-manual", response_model=ProductIndexManual)
def put_product_index_manual(
    payload: ProductIndexManualUpsert,
    db: Session = Depends(get_db),
):
    u_raw = (payload.product_url or "").strip()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    u_base = _canonicalize_smartstore_base_url(u_raw) or u_raw

    filters = _smartstore_product_url_filters(TrackedProductIndexManual, product_url=u_raw)
    rows: list[TrackedProductIndexManual] = []
    if filters:
        rows = db.query(TrackedProductIndexManual).filter(or_(*filters)).all()
    else:
        rows = db.query(TrackedProductIndexManual).filter(TrackedProductIndexManual.product_url == u_base).all()

    target: TrackedProductIndexManual | None = None
    for r in rows:
        if str(getattr(r, "product_url", "") or "") == u_base:
            target = r
            break
    if target is None and rows:
        target = rows[0]
    if target is None:
        target = TrackedProductIndexManual(product_url=u_base)
        db.add(target)
    else:
        # PK 정규화(가능한 범위에서 canonical base로 통일)
        if str(getattr(target, "product_url", "") or "") != u_base:
            exists_base = (
                db.query(TrackedProductIndexManual)
                .filter(TrackedProductIndexManual.product_url == u_base)
                .one_or_none()
            )
            if exists_base is None:
                try:
                    target.product_url = u_base  # type: ignore[assignment]
                except Exception:
                    pass
            elif exists_base is not target:
                # base row가 따로 있으면 merge 후 target 삭제
                target = exists_base
                for r in rows:
                    if r is target:
                        continue
                    try:
                        db.delete(r)
                    except Exception:
                        pass

    target.weekly_views_7d = payload.weekly_views_7d
    target.wishes = payload.wishes
    target.sales_7d_override = payload.sales_7d_override
    target.sales_30d = payload.sales_30d
    target.days_since_reg = payload.days_since_reg
    try:
        target.updated_at = datetime.utcnow()
    except Exception:
        pass
    db.commit()
    db.refresh(target)
    return target


@app.post("/search-rank/product-index/analyze", response_model=ProductIndexAnalyzeResponse)
def analyze_product_index(
    payload: ProductIndexAnalyzeRequest,
    db: Session = Depends(get_db),
):
    u_raw = (payload.product_url or "").strip()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    u = _canonicalize_smartstore_base_url(u_raw) or u_raw

    target_date = payload.target_date or _today_kst()

    # 메타(표시용)
    meta_filters = _smartstore_product_url_filters(TrackedProductMeta, product_url=u_raw)
    meta: TrackedProductMeta | None = None
    if meta_filters:
        meta = db.query(TrackedProductMeta).filter(or_(*meta_filters)).limit(1).one_or_none()
    else:
        meta = db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url == u).one_or_none()
    title = meta.title if meta is not None else None
    image_url = meta.image_url if meta is not None else None
    # 카테고리 키(CTR_cat_avg 계산용): category3 우선 → category2 → category1
    category_key = None
    try:
        if meta is not None:
            category_key = (
                str(getattr(meta, "category3", None) or "").strip()
                or str(getattr(meta, "category2", None) or "").strip()
                or str(getattr(meta, "category1", None) or "").strip()
            )
    except Exception:
        category_key = None

    # 수기 입력
    manual_filters = _smartstore_product_url_filters(TrackedProductIndexManual, product_url=u_raw)
    manual: TrackedProductIndexManual | None = None
    if manual_filters:
        manual = db.query(TrackedProductIndexManual).filter(or_(*manual_filters)).limit(1).one_or_none()
    else:
        manual = db.query(TrackedProductIndexManual).filter(TrackedProductIndexManual.product_url == u).one_or_none()

    # 판매 수기(기존 기능) + 페이지 메트릭(리뷰/평점/최근 구매 배지)
    sales_filters = _smartstore_product_url_filters(TrackedProductSalesManual, product_url=u_raw)
    sales_manual: TrackedProductSalesManual | None = None
    if sales_filters:
        sales_manual = db.query(TrackedProductSalesManual).filter(or_(*sales_filters)).limit(1).one_or_none()
    else:
        sales_manual = db.query(TrackedProductSalesManual).filter(TrackedProductSalesManual.product_url == u).one_or_none()

    # NOTE: 일부 날짜의 page-metrics 행이 "부분 NULL"인 케이스가 많아,
    #       단일 최신 1건이 아닌, 최근 N일 중 "가장 최신의 유효값(Non-Null)"을 사용한다.
    def _load_recent_page_rows(*, dt: date, limit: int = 30) -> list[TrackedProductPageDaily]:
        page_filters = _smartstore_product_url_filters(TrackedProductPageDaily, product_url=u_raw)
        q = db.query(TrackedProductPageDaily)
        if page_filters:
            q = q.filter(or_(*page_filters))
        else:
            q = q.filter(TrackedProductPageDaily.product_url == u)
        return (
            q.filter(TrackedProductPageDaily.date <= dt)
            .order_by(TrackedProductPageDaily.date.desc())
            .limit(limit)
            .all()
            or []
        )

    def _pick_latest_non_null(rows: list[TrackedProductPageDaily], attr: str):
        for r0 in rows:
            try:
                v0 = getattr(r0, attr, None)
            except Exception:
                v0 = None
            if v0 is not None:
                return v0
        return None

    page_rows = _load_recent_page_rows(dt=target_date, limit=30)
    page_latest: TrackedProductPageDaily | None = page_rows[0] if page_rows else None

    # 광고 지표 기반 클릭 점수 입력값(최근 7일)
    # - weekly_views_7d(Proxy)도 같은 소스를 사용해 자동 보강한다(수기 미입력 시).
    title_for_ads = title or (str(_pick_latest_non_null(page_rows, "title") or "").strip() or None)
    ads = _sum_ads_metrics_7d_for_product(db, product_url=u, title=title_for_ads, date_to=target_date)
    ctr_cat = _ctr_cat_avg_7d(db, category_key=category_key, date_to=target_date)

    weekly_views_7d_manual = getattr(manual, "weekly_views_7d", None) if manual is not None else None
    weekly_views_7d_auto = None
    try:
        imp7 = int(ads.get("impressions") or 0)
        weekly_views_7d_auto = imp7 if int(ads.get("rows") or 0) > 0 else None
    except Exception:
        weekly_views_7d_auto = None
    weekly_views_7d = weekly_views_7d_manual if weekly_views_7d_manual is not None else weekly_views_7d_auto

    # wishes/days_since_reg는 "내 상품 추적(페이지 메트릭)"의 최신 유효값을 우선 사용하고,
    # 수기 입력은 override로 취급한다.
    wishes_manual = getattr(manual, "wishes", None) if manual is not None else None
    wishes_auto = _pick_latest_non_null(page_rows, "wish_count")
    wishes = wishes_manual if wishes_manual is not None else wishes_auto
    sales_7d_override = int(getattr(manual, "sales_7d_override", None) or 0) if (manual is not None and getattr(manual, "sales_7d_override", None) is not None) else None
    sales_30d_manual = getattr(manual, "sales_30d", None) if manual is not None else None
    days_since_reg_manual = getattr(manual, "days_since_reg", None) if manual is not None else None
    days_since_reg_auto = None
    try:
        reg_date = _pick_latest_non_null(page_rows, "registered_date")
        if reg_date is not None:
            days_since_reg_auto = max(0, int((target_date - reg_date).days))
    except Exception:
        days_since_reg_auto = None
    days_since_reg = days_since_reg_manual if days_since_reg_manual is not None else days_since_reg_auto

    rating = _pick_latest_non_null(page_rows, "rating")
    review_count = _pick_latest_non_null(page_rows, "review_count")
    review_source = "page_metrics" if (page_latest is not None and (rating is not None or review_count is not None)) else "none"
    if rating is None or review_count is None:
        # 리뷰 원문 수집은 naver_review_raw에 저장된다. 상품 페이지 DOM 변경으로
        # page_metrics의 rating/review_count가 비어도, 이미 수집된 리뷰 원문에서 상품지수 입력값을 보강한다.
        try:
            review_filters = _smartstore_product_url_filters(NaverReviewRaw, product_url=u_raw)
            review_clauses = list(review_filters or [])
            pid_for_review = getattr(meta, "product_id_catalog", None) if meta is not None else None
            try:
                if pid_for_review is not None:
                    review_clauses.append(NaverReviewRaw.product_id_catalog == int(pid_for_review))
            except Exception:
                pass
            if review_clauses:
                review_row = (
                    db.query(func.avg(NaverReviewRaw.rating), func.count(NaverReviewRaw.review_key))
                    .filter(or_(*review_clauses))
                    .filter(NaverReviewRaw.rating.is_not(None))
                    .filter(or_(NaverReviewRaw.review_written_at.is_(None), NaverReviewRaw.review_written_at <= target_date))
                    .one()
                )
                avg_rating = review_row[0] if review_row is not None else None
                raw_review_count = int(review_row[1] or 0) if review_row is not None else 0
                if raw_review_count > 0:
                    if rating is None and avg_rating is not None:
                        rating = round(float(avg_rating), 2)
                    if review_count is None:
                        review_count = raw_review_count
                    review_source = f"review_raw(rows={raw_review_count})"
        except Exception:
            pass

    sales_7d_auto = None
    rp7 = None
    try:
        rp7 = _pick_latest_non_null(page_rows, "recent_purchase_7d_count")
        if rp7 is not None:
            sales_7d_auto = int(rp7)
    except Exception:
        sales_7d_auto = None
        rp7 = None
    if sales_7d_auto is None and sales_manual is not None and getattr(sales_manual, "expected_sales_7d", None) is not None:
        try:
            sales_7d_auto = int(sales_manual.expected_sales_7d)  # type: ignore[attr-defined]
        except Exception:
            sales_7d_auto = None
    sales_7d = sales_7d_override if sales_7d_override is not None else sales_7d_auto

    # 30일 판매량(자동 보강: 구매키워드 업로드 payments 합)
    d30 = target_date - timedelta(days=29)
    sales_30d_auto = None
    sales_30d_src = "none"
    try:
        pid = getattr(meta, "product_id_catalog", None) if meta is not None else None
        t0 = str(getattr(meta, "title", "") or "").strip() if meta is not None else ""
        if not t0:
            t0 = str(title_for_ads or "").strip()
        if pid is not None:
            row_cnt = (
                db.query(func.count(NaverSmartstorePurchaseKeywordDaily.date))
                .filter(
                    NaverSmartstorePurchaseKeywordDaily.product_id == int(pid),
                    NaverSmartstorePurchaseKeywordDaily.date >= d30,
                    NaverSmartstorePurchaseKeywordDaily.date <= target_date,
                )
                .scalar()
                or 0
            )
            if int(row_cnt) > 0:
                total = (
                    db.query(func.sum(NaverSmartstorePurchaseKeywordDaily.payments))
                    .filter(
                        NaverSmartstorePurchaseKeywordDaily.product_id == int(pid),
                        NaverSmartstorePurchaseKeywordDaily.date >= d30,
                        NaverSmartstorePurchaseKeywordDaily.date <= target_date,
                    )
                    .scalar()
                    or 0
                )
                sales_30d_auto = int(total)
                sales_30d_src = f"purchase_upload(pid,rows={int(row_cnt)})"
            else:
                sales_30d_auto = None
                sales_30d_src = "purchase_upload(pid,no_rows)"
        elif t0:
            row_cnt = (
                db.query(func.count(NaverSmartstorePurchaseKeywordDaily.date))
                .filter(
                    NaverSmartstorePurchaseKeywordDaily.product_name == t0,
                    NaverSmartstorePurchaseKeywordDaily.date >= d30,
                    NaverSmartstorePurchaseKeywordDaily.date <= target_date,
                )
                .scalar()
                or 0
            )
            if int(row_cnt) > 0:
                total = (
                    db.query(func.sum(NaverSmartstorePurchaseKeywordDaily.payments))
                    .filter(
                        NaverSmartstorePurchaseKeywordDaily.product_name == t0,
                        NaverSmartstorePurchaseKeywordDaily.date >= d30,
                        NaverSmartstorePurchaseKeywordDaily.date <= target_date,
                    )
                    .scalar()
                    or 0
                )
                sales_30d_auto = int(total)
                sales_30d_src = f"purchase_upload(title,rows={int(row_cnt)})"
            else:
                sales_30d_auto = None
                sales_30d_src = "purchase_upload(title,no_rows)"
        else:
            sales_30d_auto = None
            sales_30d_src = "purchase_upload(no_meta_pid_title)"
    except Exception:
        sales_30d_auto = None
        sales_30d_src = "none"

    # fallback: 구매키워드 업로드가 없으면, 최근 7일 판매량을 30일로 환산해 채운다.
    # - 예: sales_7d=98 => round(98*30/7)
    if sales_30d_auto is None and sales_7d is not None:
        try:
            est30 = int(round(float(sales_7d) * (30.0 / 7.0)))
            sales_30d_auto = max(0, est30)
            sales_30d_src = "derived_from_sales_7d"
        except Exception:
            pass

    sales_30d = sales_30d_manual if sales_30d_manual is not None else sales_30d_auto

    inputs = {
        "weekly_views_7d": (int(weekly_views_7d) if weekly_views_7d is not None else None),
        "wishes": (int(wishes) if wishes is not None else None),
        "sales_7d": (int(sales_7d) if sales_7d is not None else None),
        "sales_30d": (int(sales_30d) if sales_30d is not None else None),
        "rating": (float(rating) if rating is not None else None),
        "review_count": (int(review_count) if review_count is not None else None),
        "days_since_reg": (int(days_since_reg) if days_since_reg is not None else None),
        "ad_impressions_7d": int(ads.get("impressions") or 0),
        "ad_clicks_7d": int(ads.get("clicks") or 0),
        "ad_conversions_7d": int(ads.get("conversions") or 0),
        "ad_rows_7d": int(ads.get("rows") or 0),
        "ctr_7d": float(ads.get("ctr") or 0.0),
        "ctr_cat_avg_7d": float(ctr_cat.get("ctr_cat_avg") or 0.0),
        "sources": {
            "weekly_views_7d": ("manual_override" if weekly_views_7d_manual is not None else (f"ads_7d({ads.get('source')})" if weekly_views_7d_auto is not None else "none")),
            "sales_7d": ("manual_override" if sales_7d_override is not None else ("page_metrics" if sales_7d_auto is not None and rp7 is not None else ("sales_manual" if sales_manual is not None else "none"))),
            "sales_30d": ("manual_override" if sales_30d_manual is not None else sales_30d_src),
            "review": review_source,
            "wishes": ("manual_override" if wishes_manual is not None else ("page_metrics" if wishes_auto is not None and page_latest is not None else "none")),
            "days_since_reg": ("manual_override" if days_since_reg_manual is not None else ("page_metrics" if days_since_reg_auto is not None and page_latest is not None else "none")),
            "ads_7d": str(ads.get("source") or "none"),
            "ctr_cat_avg_7d": str(ctr_cat.get("source") or "none"),
        },
    }

    scores = _calc_product_index_scores(inputs=inputs)
    explain = _calc_product_index_explain(inputs=inputs)

    # 오늘(또는 지정일) 스냅샷 저장(upsert)
    score_filters = _smartstore_product_url_filters(TrackedProductIndexScoreDaily, product_url=u_raw)
    same_day_rows: list[TrackedProductIndexScoreDaily] = []
    if score_filters:
        same_day_rows = (
            db.query(TrackedProductIndexScoreDaily)
            .filter(or_(*score_filters), TrackedProductIndexScoreDaily.date == target_date)
            .all()
        )
    else:
        same_day_rows = (
            db.query(TrackedProductIndexScoreDaily)
            .filter(TrackedProductIndexScoreDaily.product_url == u, TrackedProductIndexScoreDaily.date == target_date)
            .all()
        )
    row: TrackedProductIndexScoreDaily | None = None
    for r in same_day_rows:
        if str(getattr(r, "product_url", "") or "") == u:
            row = r
            break
    if row is None and same_day_rows:
        row = same_day_rows[0]
    if row is None:
        row = TrackedProductIndexScoreDaily(date=target_date, product_url=u)
        db.add(row)
    # 변형 URL로 저장되어 있던 케이스를 base URL로 통일(동일 date 중복 방지)
    try:
        row.product_url = u  # type: ignore[assignment]
    except Exception:
        pass
    for r in same_day_rows:
        if r is row:
            continue
        try:
            db.delete(r)
        except Exception:
            pass

    row.click_score = int(scores["click"])
    row.sales_score = int(scores["sales"])
    row.review_score = int(scores["review"])
    row.recency_score = int(scores["recency"])
    row.penalty_score = int(scores["penalty"])
    row.final_score = int(scores["final"])
    try:
        row.inputs_json = json.dumps(inputs, ensure_ascii=False)
    except Exception:
        row.inputs_json = None
    db.commit()

    if score_filters:
        prev = (
            db.query(TrackedProductIndexScoreDaily)
            .filter(or_(*score_filters), TrackedProductIndexScoreDaily.date < target_date)
            .order_by(TrackedProductIndexScoreDaily.date.desc())
            .limit(1)
            .one_or_none()
        )
    else:
        prev = (
            db.query(TrackedProductIndexScoreDaily)
            .filter(TrackedProductIndexScoreDaily.product_url == u, TrackedProductIndexScoreDaily.date < target_date)
            .order_by(TrackedProductIndexScoreDaily.date.desc())
            .limit(1)
            .one_or_none()
        )

    def dlt(cur: int, prev_v: int | None) -> int | None:
        if prev_v is None:
            return None
        try:
            return int(cur) - int(prev_v)
        except Exception:
            return None

    deltas = {
        "click": dlt(scores["click"], getattr(prev, "click_score", None) if prev is not None else None),
        "sales": dlt(scores["sales"], getattr(prev, "sales_score", None) if prev is not None else None),
        "review": dlt(scores["review"], getattr(prev, "review_score", None) if prev is not None else None),
        "recency": dlt(scores["recency"], getattr(prev, "recency_score", None) if prev is not None else None),
        "penalty": dlt(scores["penalty"], getattr(prev, "penalty_score", None) if prev is not None else None),
        "final": dlt(scores["final"], getattr(prev, "final_score", None) if prev is not None else None),
    }

    return {
        "product_url": u,
        "date": target_date,
        "title": title,
        "image_url": image_url,
        "scores": scores,
        "deltas": deltas,
        "inputs": inputs,
        "explain": explain,
    }


@app.get("/search-rank/product-index/latest", response_model=ProductIndexAnalyzeResponse)
def get_product_index_latest(
    product_url: str = Query(..., description="상품 URL"),
    db: Session = Depends(get_db),
):
    """
    저장된 상품지수 스냅샷 중 '가장 최근' 1개를 반환한다.
    - 목적: 상품을 클릭했을 때 마지막 분석 데이터를 즉시 표시(UI)
    - URL 정규화/변형(query/hash) 차이도 안전 필터로 흡수한다.
    """
    u_raw = (product_url or "").strip()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    u = _canonicalize_smartstore_base_url(u_raw) or u_raw

    score_filters = _smartstore_product_url_filters(TrackedProductIndexScoreDaily, product_url=u_raw)
    q = db.query(TrackedProductIndexScoreDaily)
    if score_filters:
        q = q.filter(or_(*score_filters))
    else:
        q = q.filter(TrackedProductIndexScoreDaily.product_url == u)
    row = q.order_by(TrackedProductIndexScoreDaily.date.desc()).limit(1).one_or_none()
    if row is None:
        raise HTTPException(status_code=404, detail="no saved analysis")

    # prev (delta 계산용)
    q2 = db.query(TrackedProductIndexScoreDaily)
    if score_filters:
        q2 = q2.filter(or_(*score_filters), TrackedProductIndexScoreDaily.date < row.date)
    else:
        q2 = q2.filter(TrackedProductIndexScoreDaily.product_url == u, TrackedProductIndexScoreDaily.date < row.date)
    prev = q2.order_by(TrackedProductIndexScoreDaily.date.desc()).limit(1).one_or_none()

    def dlt(cur: int, prev_v: int | None) -> int | None:
        if prev_v is None:
            return None
        try:
            return int(cur) - int(prev_v)
        except Exception:
            return None

    scores = {
        "click": int(getattr(row, "click_score", 0) or 0),
        "sales": int(getattr(row, "sales_score", 0) or 0),
        "review": int(getattr(row, "review_score", 0) or 0),
        "recency": int(getattr(row, "recency_score", 0) or 0),
        "penalty": int(getattr(row, "penalty_score", 0) or 0),
        "final": int(getattr(row, "final_score", 0) or 0),
    }
    deltas = {
        "click": dlt(scores["click"], getattr(prev, "click_score", None) if prev is not None else None),
        "sales": dlt(scores["sales"], getattr(prev, "sales_score", None) if prev is not None else None),
        "review": dlt(scores["review"], getattr(prev, "review_score", None) if prev is not None else None),
        "recency": dlt(scores["recency"], getattr(prev, "recency_score", None) if prev is not None else None),
        "penalty": dlt(scores["penalty"], getattr(prev, "penalty_score", None) if prev is not None else None),
        "final": dlt(scores["final"], getattr(prev, "final_score", None) if prev is not None else None),
    }

    # inputs snapshot
    inputs: dict = {}
    try:
        raw = getattr(row, "inputs_json", None)
        if raw:
            inputs = json.loads(raw)
    except Exception:
        inputs = {}

    explain = _calc_product_index_explain(inputs=inputs) if isinstance(inputs, dict) else None

    # meta(best-effort)
    meta_filters = _smartstore_product_url_filters(TrackedProductMeta, product_url=u_raw)
    meta: TrackedProductMeta | None = None
    if meta_filters:
        meta = db.query(TrackedProductMeta).filter(or_(*meta_filters)).limit(1).one_or_none()
    else:
        meta = db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url == u).one_or_none()

    return {
        "product_url": u,
        "date": row.date,
        "title": meta.title if meta is not None else None,
        "image_url": meta.image_url if meta is not None else None,
        "scores": scores,
        "deltas": deltas,
        "inputs": (inputs if isinstance(inputs, dict) else {}),
        "explain": explain,
    }


def _product_index_inputs_from_row(row: TrackedProductIndexScoreDaily | None) -> dict:
    if row is None:
        return {}
    raw = getattr(row, "inputs_json", None)
    if not raw:
        return {}
    try:
        parsed = json.loads(str(raw))
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def _product_index_score_row_data_complete(row: TrackedProductIndexScoreDaily | None) -> bool:
    """
    상품지수 신호는 '실제 0'과 '수집/매칭 누락으로 인한 0'을 구분한 뒤에만 계산한다.
    필수 입력 중 하나라도 출처가 없으면 UNKNOWN(데이터부족)으로 내려 보낸다.
    """
    inputs = _product_index_inputs_from_row(row)
    if not inputs:
        return False
    sources = inputs.get("sources") if isinstance(inputs.get("sources"), dict) else {}

    def src(name: str) -> str:
        return str((sources or {}).get(name) or "").strip()

    def has_value(name: str) -> bool:
        return inputs.get(name) is not None

    def good_source(name: str) -> bool:
        s = src(name)
        if not s or s == "none":
            return False
        if "no_rows" in s or "no_meta" in s:
            return False
        return True

    try:
        ad_rows = int(inputs.get("ad_rows_7d") or 0)
    except Exception:
        ad_rows = 0
    try:
        ad_metric_sum = (
            int(inputs.get("ad_impressions_7d") or 0)
            + int(inputs.get("ad_clicks_7d") or 0)
            + int(inputs.get("ad_conversions_7d") or 0)
        )
    except Exception:
        ad_metric_sum = 0
    # 새 스냅샷은 ad_rows_7d로 실제 0을 판별한다. 구 스냅샷은 광고 지표가 하나라도
    # 양수면 수집된 것으로 간주하되, 전부 0이면 매칭/수집 누락 가능성이 있어 데이터부족으로 본다.
    if not good_source("ads_7d") or (ad_rows <= 0 and ad_metric_sum <= 0):
        return False
    # 카테고리 평균 CTR은 클릭 점수 보정 기준이다. 실제 광고 rows가 있으면 점수 계산은
    # CTR 자체를 기준으로 보수적으로 fallback하므로, 평균 CTR source 누락만으로 UNKNOWN 처리하지 않는다.
    if not (has_value("sales_7d") and good_source("sales_7d")):
        return False
    if not (has_value("sales_30d") and good_source("sales_30d")):
        return False
    if not (has_value("rating") and has_value("review_count") and good_source("review")):
        return False
    if not (has_value("days_since_reg") and good_source("days_since_reg")):
        return False
    return True


@app.post("/search-rank/product-index/latest/batch", response_model=list[ProductIndexLatestBatchItem])
def get_product_index_latest_batch(
    req: ProductIndexLatestBatchRequest,
    db: Session = Depends(get_db),
):
    """
    상품 목록에서 "현재 상태"를 빠르게 표시하기 위해, 최신 상품지수 스냅샷을 배치로 조회한다.
    - N번 API 호출 방지
    """
    urls = [str(u or "").strip() for u in (req.urls or [])]
    urls = [u for u in urls if u]
    if not urls:
        return []

    out: list[dict] = []
    for u_raw in urls:
        u = _canonicalize_smartstore_base_url(u_raw) or u_raw
        score_filters = _smartstore_product_url_filters(TrackedProductIndexScoreDaily, product_url=u_raw)
        q = db.query(TrackedProductIndexScoreDaily).order_by(TrackedProductIndexScoreDaily.date.desc())
        if score_filters:
            q = q.filter(or_(*score_filters))
        else:
            q = q.filter(TrackedProductIndexScoreDaily.product_url == u)
        row = q.limit(1).one_or_none()
        if row is None:
            out.append({"requested_url": u_raw, "product_url": u, "date": None, "scores": None, "deltas": None, "signal": None})
            continue

        # ---- strict previous-day delta + signal (same as rank-prediction) ----
        as_of = getattr(row, "date", None)
        prev_day = (as_of - timedelta(days=1)) if as_of is not None else None

        # 1일 Δ 판정용: 오늘/전일 중 하루라도 없거나 입력 품질이 부족하면 UNKNOWN(데이터부족).
        rows_w: list[TrackedProductIndexScoreDaily] = []
        if as_of is not None and prev_day is not None:
            qw = db.query(TrackedProductIndexScoreDaily)
            if score_filters:
                qw = qw.filter(or_(*score_filters))
            else:
                qw = qw.filter(TrackedProductIndexScoreDaily.product_url == u)
            qw = qw.filter(TrackedProductIndexScoreDaily.date >= prev_day, TrackedProductIndexScoreDaily.date <= as_of)
            rows_w = qw.all() or []

        by_date: dict[date, TrackedProductIndexScoreDaily] = {}
        for r0 in rows_w:
            d0 = getattr(r0, "date", None)
            if d0 is None:
                continue
            if d0 not in by_date:
                by_date[d0] = r0
            else:
                # canonical URL row 우선
                try:
                    if str(getattr(r0, "product_url", "") or "") == u:
                        by_date[d0] = r0
                except Exception:
                    pass

        prev = by_date.get(prev_day) if prev_day is not None else None

        def dlt(cur: int, prev_v: int | None) -> int | None:
            if prev_v is None:
                return None
            try:
                return int(cur) - int(prev_v)
            except Exception:
                return None

        scores = {
            "click": int(getattr(row, "click_score", 0) or 0),
            "sales": int(getattr(row, "sales_score", 0) or 0),
            "review": int(getattr(row, "review_score", 0) or 0),
            "recency": int(getattr(row, "recency_score", 0) or 0),
            "penalty": int(getattr(row, "penalty_score", 0) or 0),
            "final": int(getattr(row, "final_score", 0) or 0),
        }
        deltas = {
            "click": dlt(scores["click"], getattr(prev, "click_score", None) if prev is not None else None),
            "sales": dlt(scores["sales"], getattr(prev, "sales_score", None) if prev is not None else None),
            "review": dlt(scores["review"], getattr(prev, "review_score", None) if prev is not None else None),
            "recency": dlt(scores["recency"], getattr(prev, "recency_score", None) if prev is not None else None),
            "penalty": dlt(scores["penalty"], getattr(prev, "penalty_score", None) if prev is not None else None),
            "final": dlt(scores["final"], getattr(prev, "final_score", None) if prev is not None else None),
        }

        sig = "UNKNOWN"
        if (
            deltas["final"] is not None
            and _product_index_score_row_data_complete(row)
            and _product_index_score_row_data_complete(prev)
        ):
            d_final = int(deltas["final"] or 0)
            if d_final > 0:
                sig = "GOLDEN"
            elif d_final < 0:
                sig = "DEAD"
            else:
                sig = "TRAP"

        out.append({"requested_url": u_raw, "product_url": u, "date": row.date, "scores": scores, "deltas": deltas, "signal": sig})

    return out


@app.get("/search-rank/product-index/history", response_model=ProductIndexHistoryResponse)
def get_product_index_history(
    product_url: str = Query(..., description="상품 URL"),
    days: int = Query(30, ge=1, le=365),
    db: Session = Depends(get_db),
):
    u_raw = (product_url or "").strip()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    u = _canonicalize_smartstore_base_url(u_raw) or u_raw

    score_filters = _smartstore_product_url_filters(TrackedProductIndexScoreDaily, product_url=u_raw)
    q = db.query(TrackedProductIndexScoreDaily)
    if score_filters:
        q = q.filter(or_(*score_filters))
    else:
        q = q.filter(TrackedProductIndexScoreDaily.product_url == u)
    rows: list[TrackedProductIndexScoreDaily] = q.order_by(TrackedProductIndexScoreDaily.date.desc()).limit(int(days)).all()

    # 동일 날짜에 URL variant row가 섞인 경우를 방어적으로 병합(기본: canonical 우선)
    by_date: dict[date, TrackedProductIndexScoreDaily] = {}
    for r in (rows or []):
        dt = getattr(r, "date", None)
        if dt is None:
            continue
        if dt not in by_date:
            by_date[dt] = r
        else:
            try:
                if str(getattr(r, "product_url", "") or "") == u:
                    by_date[dt] = r
            except Exception:
                pass
    merged = list(by_date.values())
    merged.sort(key=lambda r: r.date)  # 오래된 순으로
    items = []
    for r in merged:
        items.append(
            {
                "date": r.date,
                "scores": {
                    "click": int(r.click_score or 0),
                    "sales": int(r.sales_score or 0),
                    "review": int(r.review_score or 0),
                    "recency": int(r.recency_score or 0),
                    "penalty": int(r.penalty_score or 0),
                    "final": int(r.final_score or 0),
                },
            }
        )
    return {"product_url": u, "items": items}


@app.get("/search-rank/product-index/history-detailed", response_model=ProductIndexHistoryDetailedResponse)
def get_product_index_history_detailed(
    product_url: str = Query(..., description="상품 URL"),
    days: int = Query(30, ge=1, le=365),
    db: Session = Depends(get_db),
):
    """
    상품지수 스냅샷을 '입력값(inputs_json)'까지 포함해 반환한다.
    - 목적: 일자별 수기입력(및 자동값) 변화와 점수 변화를 UI에서 검증/추적
    """
    u_raw = (product_url or "").strip()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    u = _canonicalize_smartstore_base_url(u_raw) or u_raw

    score_filters = _smartstore_product_url_filters(TrackedProductIndexScoreDaily, product_url=u_raw)
    q = db.query(TrackedProductIndexScoreDaily)
    if score_filters:
        q = q.filter(or_(*score_filters))
    else:
        q = q.filter(TrackedProductIndexScoreDaily.product_url == u)
    rows: list[TrackedProductIndexScoreDaily] = q.order_by(TrackedProductIndexScoreDaily.date.desc()).limit(int(days)).all()

    # 날짜 중복(variant URL) 방어 병합
    by_date: dict[date, TrackedProductIndexScoreDaily] = {}
    for r in (rows or []):
        dt = getattr(r, "date", None)
        if dt is None:
            continue
        if dt not in by_date:
            by_date[dt] = r
        else:
            try:
                if str(getattr(r, "product_url", "") or "") == u:
                    by_date[dt] = r
            except Exception:
                pass
    merged = list(by_date.values())
    merged.sort(key=lambda r: r.date)

    items = []
    for r in merged:
        inputs: dict = {}
        try:
            raw = getattr(r, "inputs_json", None)
            if raw:
                inputs = json.loads(raw)
        except Exception:
            inputs = {}
        items.append(
            {
                "date": r.date,
                "scores": {
                    "click": int(r.click_score or 0),
                    "sales": int(r.sales_score or 0),
                    "review": int(r.review_score or 0),
                    "recency": int(r.recency_score or 0),
                    "penalty": int(r.penalty_score or 0),
                    "final": int(r.final_score or 0),
                },
                "inputs": (inputs if isinstance(inputs, dict) else {}),
            }
        )
    return {"product_url": u, "items": items}


@app.get("/search-rank/product-index/coverage", response_model=ProductIndexCoverageResponse)
def get_product_index_coverage(
    product_url: str = Query(..., description="상품 URL"),
    days: int = Query(14, ge=1, le=365),
    date_to: date | None = Query(None, description="기준일(미입력 시 오늘 KST)"),
    db: Session = Depends(get_db),
):
    """
    "DB에 저장되어 있는데 왜 못 가져오나?"를 구조적으로 진단하기 위한 커버리지 API.
    - score: tracked_product_index_score_daily (점수 스냅샷)
    - page: tracked_product_page_daily (내 상품 추적 수집)
    """
    u_raw = (product_url or "").strip()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    u = _canonicalize_smartstore_base_url(u_raw) or u_raw

    dt = date_to or _today_kst()
    days_i = max(1, min(365, int(days)))
    date_from = dt - timedelta(days=days_i - 1)

    axis = [date_from + timedelta(days=i) for i in range(days_i)]
    axis_set = set(axis)

    score_filters = _smartstore_product_url_filters(TrackedProductIndexScoreDaily, product_url=u_raw)
    qs = db.query(TrackedProductIndexScoreDaily.date)
    if score_filters:
        qs = qs.filter(or_(*score_filters))
    else:
        qs = qs.filter(TrackedProductIndexScoreDaily.product_url == u)
    score_dates = {d for (d,) in (qs.filter(TrackedProductIndexScoreDaily.date >= date_from, TrackedProductIndexScoreDaily.date <= dt).all() or []) if d in axis_set}

    page_filters = _smartstore_product_url_filters(TrackedProductPageDaily, product_url=u_raw)
    qp = db.query(TrackedProductPageDaily.date)
    if page_filters:
        qp = qp.filter(or_(*page_filters))
    else:
        qp = qp.filter(TrackedProductPageDaily.product_url == u)
    page_dates = {d for (d,) in (qp.filter(TrackedProductPageDaily.date >= date_from, TrackedProductPageDaily.date <= dt).all() or []) if d in axis_set}

    missing_score = [d for d in axis if d not in score_dates]
    missing_page = [d for d in axis if d not in page_dates]

    return {
        "product_url": u,
        "date_from": date_from,
        "date_to": dt,
        "score_days_count": int(len(score_dates)),
        "page_days_count": int(len(page_dates)),
        "missing_score_days": missing_score,
        "missing_page_days": missing_page,
    }


@app.get("/search-rank/product-index/suggested-inputs", response_model=ProductIndexSuggestedInputs)
def get_product_index_suggested_inputs(
    product_url: str = Query(..., description="상품 URL"),
    date_to: date | None = Query(None, description="기준일(미입력 시 오늘 KST)"),
    db: Session = Depends(get_db),
):
    """
    '내 상품 추적(4-2)'에 저장된 데이터를 기반으로 상품지수 입력값을 자동 제안한다.
    - 수기 입력을 강제 저장하지 않고, UI에서 참고/자동 채움 용도로 사용한다.
    """
    u_raw = (product_url or "").strip()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    dt = date_to or _today_kst()
    d7 = dt - timedelta(days=6)
    d30 = dt - timedelta(days=29)

    u = _canonicalize_smartstore_base_url(u_raw) or u_raw

    page_filters = _smartstore_product_url_filters(TrackedProductPageDaily, product_url=u_raw)
    qpage = db.query(TrackedProductPageDaily)
    if page_filters:
        qpage = qpage.filter(or_(*page_filters))
    else:
        qpage = qpage.filter(TrackedProductPageDaily.product_url == u)
    page_rows: list[TrackedProductPageDaily] = (
        qpage.filter(TrackedProductPageDaily.date <= dt)
        .order_by(TrackedProductPageDaily.date.desc())
        .limit(30)
        .all()
        or []
    )
    page_latest: TrackedProductPageDaily | None = page_rows[0] if page_rows else None

    def _pick_latest_non_null(rows: list[TrackedProductPageDaily], attr: str):
        for r0 in rows:
            try:
                v0 = getattr(r0, attr, None)
            except Exception:
                v0 = None
            if v0 is not None:
                return v0
        return None

    sales_filters = _smartstore_product_url_filters(TrackedProductSalesManual, product_url=u_raw)
    if sales_filters:
        sales_manual: TrackedProductSalesManual | None = db.query(TrackedProductSalesManual).filter(or_(*sales_filters)).limit(1).one_or_none()
    else:
        sales_manual = db.query(TrackedProductSalesManual).filter(TrackedProductSalesManual.product_url == u).one_or_none()

    wishes = _pick_latest_non_null(page_rows, "wish_count")
    # "최근 7일 조회수"는 페이지뷰가 항상 수집되지 않아, Proxy로 광고 노출수(I)를 사용한다.
    # - 클릭 점수 공식이 광고 지표 기반이므로, UI에서도 동일 맥락의 입력값을 제공하는 것이 일관적이다.
    weekly_views_7d = None
    sales_7d = None
    rp7 = None
    try:
        rp7 = _pick_latest_non_null(page_rows, "recent_purchase_7d_count")
        if rp7 is not None:
            sales_7d = int(rp7)
    except Exception:
        sales_7d = None
        rp7 = None
    if sales_7d is None and sales_manual is not None and getattr(sales_manual, "expected_sales_7d", None) is not None:
        try:
            sales_7d = int(sales_manual.expected_sales_7d)  # type: ignore[attr-defined]
        except Exception:
            sales_7d = None

    # 등록 후 경과일(등록일이 있는 경우만)
    days_since_reg = None
    try:
        reg_date = _pick_latest_non_null(page_rows, "registered_date")
        if reg_date is not None:
            days_since_reg = max(0, int((dt - reg_date).days))
    except Exception:
        days_since_reg = None

    # 30일 판매량은 내 상품 추적에 일관된 자동 소스가 없어(추정치 오염 위험),
    # 구매키워드 업로드가 있다면(결제수 합) 이를 참고치로 제안한다.
    sales_30d = None
    sales_30d_src = "none"
    try:
        meta_filters = _smartstore_product_url_filters(TrackedProductMeta, product_url=u_raw)
        meta = db.query(TrackedProductMeta).filter(or_(*meta_filters)).limit(1).one_or_none() if meta_filters else db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url == u).one_or_none()
        pid = getattr(meta, "product_id_catalog", None) if meta is not None else None
        title = str(getattr(meta, "title", "") or "").strip() if meta is not None else ""
        if pid is not None:
            row_cnt = (
                db.query(func.count(NaverSmartstorePurchaseKeywordDaily.date))
                .filter(
                    NaverSmartstorePurchaseKeywordDaily.product_id == int(pid),
                    NaverSmartstorePurchaseKeywordDaily.date >= d30,
                    NaverSmartstorePurchaseKeywordDaily.date <= dt,
                )
                .scalar()
                or 0
            )
            if int(row_cnt) > 0:
                total = (
                    db.query(func.sum(NaverSmartstorePurchaseKeywordDaily.payments))
                    .filter(
                        NaverSmartstorePurchaseKeywordDaily.product_id == int(pid),
                        NaverSmartstorePurchaseKeywordDaily.date >= d30,
                        NaverSmartstorePurchaseKeywordDaily.date <= dt,
                    )
                    .scalar()
                    or 0
                )
                sales_30d = int(total)
                sales_30d_src = f"purchase_upload(pid,rows={int(row_cnt)})"
            else:
                sales_30d = None
                sales_30d_src = "purchase_upload(pid,no_rows)"
        elif title:
            row_cnt = (
                db.query(func.count(NaverSmartstorePurchaseKeywordDaily.date))
                .filter(
                    NaverSmartstorePurchaseKeywordDaily.product_name == title,
                    NaverSmartstorePurchaseKeywordDaily.date >= d30,
                    NaverSmartstorePurchaseKeywordDaily.date <= dt,
                )
                .scalar()
                or 0
            )
            if int(row_cnt) > 0:
                total = (
                    db.query(func.sum(NaverSmartstorePurchaseKeywordDaily.payments))
                    .filter(
                        NaverSmartstorePurchaseKeywordDaily.product_name == title,
                        NaverSmartstorePurchaseKeywordDaily.date >= d30,
                        NaverSmartstorePurchaseKeywordDaily.date <= dt,
                    )
                    .scalar()
                    or 0
                )
                sales_30d = int(total)
                sales_30d_src = f"purchase_upload(title,rows={int(row_cnt)})"
            else:
                sales_30d = None
                sales_30d_src = "purchase_upload(title,no_rows)"
        else:
            sales_30d = None
            sales_30d_src = "purchase_upload(no_meta_pid_title)"
    except Exception:
        sales_30d = None
        sales_30d_src = "none"

    # fallback: 구매키워드 업로드가 없으면 최근 7일 판매량을 30일로 환산해 제안한다.
    if sales_30d is None and sales_7d is not None:
        try:
            est30 = int(round(float(sales_7d) * (30.0 / 7.0)))
            sales_30d = max(0, est30)
            sales_30d_src = "derived_from_sales_7d"
        except Exception:
            pass

    matched_rows_30d = 0
    try:
        matched_rows_30d = int(
            db.query(func.count(TrackedProductPageDaily.date))
            .filter(or_(*page_filters), TrackedProductPageDaily.date >= d30, TrackedProductPageDaily.date <= dt)
            .scalar()
            or 0
        )
    except Exception:
        matched_rows_30d = 0

    # 광고(최근 7일) 기반 proxy 조회수 제안
    title_for_ads = str(_pick_latest_non_null(page_rows, "title") or "").strip() if page_latest is not None else ""
    ads = _sum_ads_metrics_7d_for_product(db, product_url=u, title=(title_for_ads or None), date_to=dt)
    try:
        imp7 = int(ads.get("impressions") or 0)
    except Exception:
        imp7 = 0
    weekly_views_7d = imp7 if imp7 > 0 else None

    sources = {
        "weekly_views_7d": (f"ads_7d({ads.get('source')})" if weekly_views_7d is not None else "none"),
        "wishes": ("page_metrics" if wishes is not None and page_latest is not None else "none"),
        "days_since_reg": ("page_metrics" if days_since_reg is not None and page_latest is not None else "none"),
        "sales_7d": ("page_metrics" if sales_7d is not None and rp7 is not None else ("sales_manual" if sales_manual is not None else "none")),
        "sales_30d": sales_30d_src,
    }

    return {
        "product_url": u,
        "date_to": dt,
        "date_from_7d": d7,
        "date_from_30d": d30,
        "weekly_views_7d": weekly_views_7d,
        "wishes": wishes,
        "days_since_reg": days_since_reg,
        "sales_7d": sales_7d,
        "sales_30d": sales_30d,
        "matched_rows_30d": matched_rows_30d,
        "source": "tracked_product" if (page_latest is not None or sales_manual is not None or sales_30d is not None) else "none",
        "sources": sources,
    }


@app.get("/search-rank/product-index/rank-prediction", response_model=ProductIndexRankPredictionResponse)
def get_product_index_rank_prediction(
    product_url: str = Query(..., description="상품 URL"),
    days: int = Query(30, ge=3, le=365),
    benchmark_product_url: str | None = Query(None, description="벤치마크(경쟁사) 상품 URL"),
    db: Session = Depends(get_db),
):
    """
    목표: 상품별 "점수 Δ(가속도)"를 기록하여 오가닉 순위 변동을 예측한다.

    - score: tracked_product_index_score_daily.final_score (없으면 None)
    - rank: tracked_product_rank_daily에서 날짜별 "최고 순위(min rank)" (없으면 None)
    - signal(간단 규칙):
      - GOLDEN: 전일 대비 score Δ > 0
      - DEAD: 전일 대비 score Δ < 0
      - TRAP: 전일 대비 score Δ == 0
      - UNKNOWN: 오늘/전일 중 하나라도 스냅샷 또는 필수 입력 데이터 부족
    """
    u_raw = (product_url or "").strip()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    u = _canonicalize_smartstore_base_url(u_raw) or u_raw
    bench_u_raw = (benchmark_product_url or "").strip() or None
    bench_u = _canonicalize_smartstore_base_url(bench_u_raw) if bench_u_raw else None

    dt = _today_kst()
    date_from = dt - timedelta(days=int(days) - 1)

    # 1) score series (date -> final_score)
    score_filters = _smartstore_product_url_filters(TrackedProductIndexScoreDaily, product_url=u_raw)
    q = db.query(TrackedProductIndexScoreDaily)
    if score_filters:
        q = q.filter(or_(*score_filters))
    else:
        q = q.filter(TrackedProductIndexScoreDaily.product_url == u)
    q = q.filter(TrackedProductIndexScoreDaily.date >= date_from, TrackedProductIndexScoreDaily.date <= dt)
    score_rows = q.all() or []
    score_by_date: dict[date, int] = {}
    score_row_by_date: dict[date, TrackedProductIndexScoreDaily] = {}
    for score_row in score_rows:
        try:
            d0 = getattr(score_row, "date", None)
            if d0 is None:
                continue
            if d0 not in score_row_by_date:
                score_row_by_date[d0] = score_row
            elif str(getattr(score_row, "product_url", "") or "") == u:
                score_row_by_date[d0] = score_row
            score_by_date[d0] = int(getattr(score_row_by_date[d0], "final_score", 0) or 0)
        except Exception:
            continue

    # 2) rank series (date -> best_rank)
    def _keyword_weight_map_for_product(u0_raw: str, u0: str) -> dict[str, int]:
        """
        대표 키워드 가중치 맵(월검색량 기반).
        우선순위: 수기 키워드 메타(tracked_product_manual_keyword) > 내 상품 추적 키워드(tracked_product_keyword)
        """
        out: dict[str, int] = {}
        # 1) manual keyword meta
        try:
            mk_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=u0_raw)
            mq = db.query(TrackedProductManualKeyword.keyword, TrackedProductManualKeyword.monthly_search_volume)
            if mk_filters:
                mq = mq.filter(or_(*mk_filters))
            else:
                mq = mq.filter(TrackedProductManualKeyword.product_url == u0)
            mq = mq.filter(TrackedProductManualKeyword.is_active == True)  # noqa: E712
            for kw, vol in (mq.all() or []):
                k = str(kw or "").strip()
                if not k:
                    continue
                try:
                    v = int(vol) if vol is not None else 0
                except Exception:
                    v = 0
                out[k] = max(1, v)
        except Exception:
            pass

        # 2) tracked keywords (fallback)
        try:
            tk_filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=u0_raw)
            tq = db.query(TrackedProductKeyword.keyword, TrackedProductKeyword.monthly_search_volume)
            if tk_filters:
                tq = tq.filter(or_(*tk_filters))
            else:
                tq = tq.filter(TrackedProductKeyword.product_url == u0)
            tq = tq.filter(TrackedProductKeyword.is_active == True)  # noqa: E712
            for kw, vol in (tq.all() or []):
                k = str(kw or "").strip()
                if not k or k in out:
                    continue
                try:
                    v = int(vol) if vol is not None else 0
                except Exception:
                    v = 0
                out[k] = max(1, v)
        except Exception:
            pass

        return out

    def _rank_stats_series_for_product_url(u0_raw: str, u0: str) -> dict[date, dict]:
        """
        날짜별:
        - best_rank: min rank
        - weighted_rank: Σ(rank*weight)/Σ(weight), weight=월검색량(없으면 1)
        """
        weights = _keyword_weight_map_for_product(u0_raw, u0)
        filters0 = _smartstore_product_url_filters(TrackedProductRankDaily, product_url=u0_raw)
        rq0 = db.query(TrackedProductRankDaily.date, TrackedProductRankDaily.keyword, TrackedProductRankDaily.rank)
        if filters0:
            rq0 = rq0.filter(or_(*filters0))
        else:
            rq0 = rq0.filter(TrackedProductRankDaily.product_url == u0)
        rq0 = rq0.filter(TrackedProductRankDaily.date >= date_from, TrackedProductRankDaily.date <= dt)
        rows0 = rq0.all() or []

        best_by_date: dict[date, int] = {}
        sum_w_by_date: dict[date, float] = {}
        sum_wr_by_date: dict[date, float] = {}
        for d0, kw0, r0 in rows0:
            if d0 is None:
                continue
            k = str(kw0 or "").strip()
            try:
                rk = int(r0 or 0)
            except Exception:
                continue
            if rk <= 0 or rk >= 999:
                continue

            cur_best = best_by_date.get(d0)
            if cur_best is None or rk < cur_best:
                best_by_date[d0] = rk

            w = float(max(1, int(weights.get(k) or 1)))
            sum_w_by_date[d0] = float(sum_w_by_date.get(d0) or 0.0) + w
            sum_wr_by_date[d0] = float(sum_wr_by_date.get(d0) or 0.0) + (float(rk) * w)

        out: dict[date, dict] = {}
        for d0 in set(list(best_by_date.keys()) + list(sum_w_by_date.keys())):
            wsum = float(sum_w_by_date.get(d0) or 0.0)
            wrsum = float(sum_wr_by_date.get(d0) or 0.0)
            out[d0] = {
                "best_rank": best_by_date.get(d0),
                "weighted_rank": (wrsum / wsum if wsum > 0 else None),
            }
        return out

    rank_stats_by_date = _rank_stats_series_for_product_url(u_raw, u)
    rank_stats_bench_by_date: dict[date, dict] = {}
    if bench_u_raw and bench_u:
        rank_stats_bench_by_date = _rank_stats_series_for_product_url(bench_u_raw, bench_u)
    # 3) build full date axis
    axis: list[date] = []
    for i in range(int(days)):
        axis.append(date_from + timedelta(days=i))

    # 4) compute deltas + signals
    items: list[dict] = []
    prev_day_delta_score: int | None = None
    for d0 in axis:
        score = score_by_date.get(d0)
        prev_day = d0 - timedelta(days=1)
        prev_day_score = score_by_date.get(prev_day)

        rank = (rank_stats_by_date.get(d0) or {}).get("best_rank")
        prev_day_rank = (rank_stats_by_date.get(prev_day) or {}).get("best_rank")
        weighted_rank = (rank_stats_by_date.get(d0) or {}).get("weighted_rank")
        prev_day_weighted_rank = (rank_stats_by_date.get(prev_day) or {}).get("weighted_rank")

        bench_rank = (rank_stats_bench_by_date.get(d0) or {}).get("best_rank") if rank_stats_bench_by_date else None
        bench_weighted_rank = (rank_stats_bench_by_date.get(d0) or {}).get("weighted_rank") if rank_stats_bench_by_date else None
        gap_rank = None
        if rank is not None and bench_rank is not None:
            try:
                gap_rank = int(rank) - int(bench_rank)
            except Exception:
                gap_rank = None
        gap_weighted_rank = None
        if weighted_rank is not None and bench_weighted_rank is not None:
            try:
                gap_weighted_rank = float(weighted_rank) - float(bench_weighted_rank)
            except Exception:
                gap_weighted_rank = None

        # Δ는 "전날" 기준으로만 계산(연속일이 아니면 None)
        d_score = None
        if score is not None and prev_day_score is not None:
            d_score = int(score) - int(prev_day_score)

        d_rank = None
        if rank is not None and prev_day_rank is not None:
            d_rank = int(rank) - int(prev_day_rank)

        d_wrank = None
        if weighted_rank is not None and prev_day_weighted_rank is not None:
            try:
                d_wrank = float(weighted_rank) - float(prev_day_weighted_rank)
            except Exception:
                d_wrank = None

        accel = None
        if d_score is not None and prev_day_delta_score is not None:
            accel = int(d_score) - int(prev_day_delta_score)

        sig = "UNKNOWN"
        if (
            d_score is not None
            and _product_index_score_row_data_complete(score_row_by_date.get(d0))
            and _product_index_score_row_data_complete(score_row_by_date.get(prev_day))
        ):
            if int(d_score) > 0:
                sig = "GOLDEN"
            elif int(d_score) == 0:
                sig = "TRAP"
            else:
                sig = "DEAD"

        items.append(
            {
                "date": d0,
                "score_final": score,
                "delta_score_final": d_score,
                "best_rank": rank,
                "delta_best_rank": d_rank,
                "benchmark_best_rank": bench_rank,
                "gap_best_rank": gap_rank,
                "weighted_rank": weighted_rank,
                "delta_weighted_rank": d_wrank,
                "benchmark_weighted_rank": bench_weighted_rank,
                "gap_weighted_rank": gap_weighted_rank,
                "signal": sig,
                "accel": accel,
            }
        )

        prev_day_delta_score = d_score

    return {
        "product_url": u,
        "days": int(days),
        "benchmark_product_url": (bench_u if bench_u else None),
        "items": items,
    }


@app.post("/search-rank/product-index/analyze-today-batch", response_model=ProductIndexBatchRunResponse)
def analyze_product_index_today_batch(
    db: Session = Depends(get_db),
):
    """
    내 상품 추적(tracked_product_keyword)에 등록된 상품들에 대해
    오늘(KST) 상품지수 분석을 '하루 1회' 일괄 실행하고 결과를 저장한다.

    - UI에서 "오늘 분석 저장" 버튼으로 수동 실행 가능
    - 배치/스케줄러에서 호출해도 중복 실행이 DB 레벨에서 방지됨(analytics_job_run 사용)
    """
    today = _today_kst()
    acquired = False
    try:
        acquired = acquire_daily_job_run(db, job_name=PRODUCT_INDEX_DAILY_JOB_NAME, run_date=today)
    except Exception:
        acquired = False
    if not acquired:
        return {
            "date": today,
            "status": "SKIPPED",
            "total_targets": 0,
            "analyzed": 0,
            "failed": 0,
            "detail": "already_ran_today",
        }

    analyzed = 0
    failed = 0

    # 대상 URL 수집
    try:
        rows: list[TrackedProductKeyword] = (
            db.query(TrackedProductKeyword)
            .filter(TrackedProductKeyword.is_active.is_(True))
            .all()
        )
    except Exception:
        rows = []
    urls = sorted({str(getattr(r, "product_url", "") or "").strip() for r in (rows or []) if str(getattr(r, "product_url", "") or "").strip()})

    for u in urls:
        try:
            # 기존 분석 로직을 그대로 재사용(저장/Δ 계산 포함)
            analyze_product_index(ProductIndexAnalyzeRequest(product_url=u, target_date=today), db=db)  # type: ignore[arg-type]
            analyzed += 1
        except Exception:
            failed += 1
            continue

    try:
        finish_daily_job_run(
            db,
            job_name=PRODUCT_INDEX_DAILY_JOB_NAME,
            run_date=today,
            status=("SUCCESS" if failed == 0 else "PARTIAL"),
            detail=f"analyzed={analyzed},failed={failed},targets={len(urls)}",
        )
    except Exception:
        pass

    return {
        "date": today,
        "status": ("SUCCESS" if failed == 0 else "FAILED"),
        "total_targets": int(len(urls)),
        "analyzed": int(analyzed),
        "failed": int(failed),
        "detail": None,
    }


@app.post("/search-rank/product-index/backfill-batch", response_model=ProductIndexBackfillResponse)
def product_index_backfill_batch(
    req: ProductIndexBackfillRequest,
    db: Session = Depends(get_db),
):
    """
    과거 N일(기본 14일) 동안 DB에 저장된 지표를 기반으로 상품지수 스냅샷을 채운다.

    - 목적: "연속 Δ/신호" 계산이 가능하도록, 누락된 일자 스냅샷을 빠르게 보강
    - 주의: 수기 입력(tracked_product_index_manual)은 '현재 값'을 사용한다(과거 버전 관리 없음).
    """
    days = int(req.days or 14)
    days = max(1, min(365, days))
    date_to = req.date_to or _today_kst()
    date_from = date_to - timedelta(days=days - 1)

    # 대상 URL 수집
    urls: list[str] = []
    if req.product_url:
        urls = [str(req.product_url).strip()]
    else:
        try:
            rows: list[TrackedProductKeyword] = (
                db.query(TrackedProductKeyword)
                .filter(TrackedProductKeyword.is_active.is_(True))
                .all()
            )
        except Exception:
            rows = []
        urls = sorted({str(getattr(r, "product_url", "") or "").strip() for r in (rows or []) if str(getattr(r, "product_url", "") or "").strip()})

    analyzed = 0
    failed = 0
    # 날짜 오름차순으로 채워야 UI 트렌드/Δ 확인이 직관적
    for i in range(days):
        d = date_from + timedelta(days=i)
        for u in urls:
            try:
                analyze_product_index(ProductIndexAnalyzeRequest(product_url=u, target_date=d), db=db)  # type: ignore[arg-type]
                analyzed += 1
            except Exception:
                failed += 1
                continue

    return {
        "date_from": date_from,
        "date_to": date_to,
        "days": days,
        "total_targets": int(len(urls)),
        "analyzed": int(analyzed),
        "failed": int(failed),
        "detail": None,
    }


@app.post("/search-rank/normalize-product-urls", response_model=dict)
def normalize_product_urls(db: Session = Depends(get_db)):
    """
    (복구/정리용) 과거에 query/hash 등이 섞인 smartstore URL이 저장된 경우,
    base URL(scheme://host/path)로 정규화해 데이터 혼용/누락(이미지 사라짐 등)을 복구한다.
    """
    updated_keywords = 0
    merged_meta = 0
    merged_page_daily = 0
    deleted_meta = 0
    deleted_page_daily = 0

    # 1) tracked_product_keyword 정규화
    try:
        rows: List[TrackedProductKeyword] = (
            db.query(TrackedProductKeyword).filter(TrackedProductKeyword.is_active.is_(True)).all()
        )
        for r in rows:
            url0 = (r.product_url or "").strip()
            if not url0:
                continue
            url = _canonicalize_smartstore_base_url(url0)
            if url and url != url0:
                r.product_url = url
                updated_keywords += 1
        db.commit()
    except Exception:
        db.rollback()

    # 2) tracked_product_meta 정규화/머지
    try:
        metas: List[TrackedProductMeta] = db.query(TrackedProductMeta).all()
        for m in metas:
            u0 = (m.product_url or "").strip()
            if not u0:
                continue
            u = _canonicalize_smartstore_base_url(u0)
            if not u or u == u0:
                continue
            target: TrackedProductMeta | None = (
                db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url == u).one_or_none()
            )
            if target is None:
                m.product_url = u
                merged_meta += 1
            else:
                # merge: target가 비어있으면 source 값을 채운다.
                for k in (
                    "keyword",
                    "title",
                    "mall_name",
                    "image_url",
                    "price",
                    "product_id_catalog",
                    "category1",
                    "category2",
                    "category3",
                    "category4",
                ):
                    tv = getattr(target, k, None)
                    sv = getattr(m, k, None)
                    if (tv is None or (isinstance(tv, str) and not tv.strip())) and sv is not None:
                        setattr(target, k, sv)
                try:
                    target.updated_at = max(target.updated_at, m.updated_at)  # type: ignore[arg-type]
                except Exception:
                    pass
                db.delete(m)
                deleted_meta += 1
                merged_meta += 1
        db.commit()
    except Exception:
        db.rollback()

    # 3) tracked_product_page_daily 정규화/머지
    try:
        rows: List[TrackedProductPageDaily] = db.query(TrackedProductPageDaily).all()
        for r in rows:
            u0 = (r.product_url or "").strip()
            if not u0:
                continue
            u = _canonicalize_smartstore_base_url(u0)
            if not u or u == u0:
                continue
            target: TrackedProductPageDaily | None = (
                db.query(TrackedProductPageDaily)
                .filter(TrackedProductPageDaily.product_url == u, TrackedProductPageDaily.date == r.date)
                .one_or_none()
            )
            if target is None:
                r.product_url = u
                merged_page_daily += 1
            else:
                # merge: null은 채우되, 기존 유효값을 덮지 않음
                for k in (
                    "title",
                    "price",
                    "review_count",
                    "rating",
                    "delivery",
                    "buy_count",
                    "recent_purchase_status",
                    "recent_purchase_count",
                    "recent_purchase_window",
                    "recent_purchase_7d_count",
                    "recent_repurchase_count",
                    "recent_repurchase_window",
                    "recent_repurchase_3m_count",
                    "recent_badge_text",
                    "http_status",
                    "error",
                ):
                    tv = getattr(target, k, None)
                    sv = getattr(r, k, None)
                    if tv is None and sv is not None:
                        setattr(target, k, sv)
                db.delete(r)
                deleted_page_daily += 1
                merged_page_daily += 1
        db.commit()
    except Exception:
        db.rollback()

    return {
        "updated_keywords": updated_keywords,
        "merged_meta": merged_meta,
        "deleted_meta": deleted_meta,
        "merged_page_daily": merged_page_daily,
        "deleted_page_daily": deleted_page_daily,
    }


@app.post("/search-rank/page-metrics/repair-poisoned", response_model=dict)
def repair_poisoned_page_metrics(
    days: int = Query(2, ge=1, le=30, description="최근 N일(오늘 포함) 범위에서 오염된 row를 탐지/복구"),
    db: Session = Depends(get_db),
):
    """
    (복구/정리용) 과거 수집 과정에서 다른 상품 페이지의 값이 잘못 저장(오염)된 경우를
    최근 N일 범위에서 탐지하고, 가능한 경우 '직전 정상 데이터'로 복구한다.
    """
    today = _today_kst()
    date_from = today - timedelta(days=days - 1)

    # active urls(최대 10개 UI 정책과 동일) 기준으로만 빠르게 수행
    try:
        kw_rows: List[TrackedProductKeyword] = (
            db.query(TrackedProductKeyword)
            .filter(TrackedProductKeyword.is_active.is_(True))
            .all()
        )
    except Exception:
        kw_rows = []
    urls = []
    seen = set()
    for r in kw_rows:
        u0 = (r.product_url or "").strip()
        if not u0:
            continue
        u = _canonicalize_smartstore_base_url(u0)
        if not u or u in seen:
            continue
        seen.add(u)
        urls.append(u)
        if len(urls) >= 10:
            break

    repaired: list[dict] = []
    scanned = 0
    updated = 0

    for u in urls:
        meta: TrackedProductMeta | None = None
        try:
            meta = db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url == u).one_or_none()
        except Exception:
            meta = None
        meta_price = getattr(meta, "price", None)

        rows: List[TrackedProductPageDaily] = []
        try:
            rows = (
                db.query(TrackedProductPageDaily)
                .filter(
                    TrackedProductPageDaily.product_url == u,
                    TrackedProductPageDaily.date >= date_from,
                    TrackedProductPageDaily.date <= today,
                )
                .order_by(TrackedProductPageDaily.date.desc())
                .all()
            )
        except Exception:
            rows = []
        if not rows:
            continue

        # 직전 정상 row(더 과거 포함)를 찾기 위해 30일치까지 확장
        try:
            history: List[TrackedProductPageDaily] = (
                db.query(TrackedProductPageDaily)
                .filter(
                    TrackedProductPageDaily.product_url == u,
                    TrackedProductPageDaily.date <= today,
                )
                .order_by(TrackedProductPageDaily.date.desc())
                .limit(60)
                .all()
            )
        except Exception:
            history = rows

        def _row_ok(r0: TrackedProductPageDaily) -> bool:
            if getattr(r0, "error", None):
                return False
            hs0 = getattr(r0, "http_status", None)
            if isinstance(hs0, int) and hs0 != 200:
                return False
            return True

        def _ratio_outlier(v: int, base: int, *, hi: float = 2.5, lo: float = 0.4) -> bool:
            if base <= 0 or v <= 0:
                return False
            try:
                r = v / base
            except Exception:
                return False
            return r > hi or r < lo

        def _neighbor_good(*, target_date: date, direction: str) -> TrackedProductPageDaily | None:
            # history는 date desc
            if direction == "newer":
                # target_date보다 "큰" 날짜 중 가장 가까운 것
                for h in history:
                    if h.date <= target_date:
                        continue
                    if not _row_ok(h):
                        continue
                    return h
                return None
            # older
            for h in history:
                if h.date >= target_date:
                    continue
                if not _row_ok(h):
                    continue
                return h

        def looks_poisoned(row: TrackedProductPageDaily) -> bool:
            # 정상(200, error 없음)인데 (가격/리뷰/평점)이 전후 일자 또는 메타 대비 비정상적으로 튀면 오염으로 본다.
            if not _row_ok(row):
                return False

            p = getattr(row, "price", None)
            rc = getattr(row, "review_count", None)
            rt = getattr(row, "rating", None)

            # 1) 가격 outlier(기존 로직)
            try:
                if meta_price is not None and p is not None:
                    if _ratio_outlier(int(p), int(meta_price), hi=2.5, lo=0.4):
                        return True
            except Exception:
                pass

            # 2) 리뷰 급변(outlier): 전후 이웃과 비교해 둘 다와 크게 다르면 오염 가능성 높음
            try:
                if rc is not None:
                    prev_ok = _neighbor_good(target_date=row.date, direction="older")
                    next_ok = _neighbor_good(target_date=row.date, direction="newer")
                    prev_rc = getattr(prev_ok, "review_count", None) if prev_ok is not None else None
                    next_rc = getattr(next_ok, "review_count", None) if next_ok is not None else None
                    if isinstance(prev_rc, int) and isinstance(next_rc, int) and prev_rc > 0 and next_rc > 0:
                        cur = int(rc)
                        # 둘 다 대비 3배 이상 또는 1/3 이하 + 절대차 5000 이상이면 오염으로 간주
                        out_prev = _ratio_outlier(cur, int(prev_rc), hi=3.0, lo=(1 / 3))
                        out_next = _ratio_outlier(cur, int(next_rc), hi=3.0, lo=(1 / 3))
                        if out_prev and out_next and (abs(cur - int(prev_rc)) >= 5000 or abs(cur - int(next_rc)) >= 5000):
                            return True
                    # 이웃 하나만 있어도 "메타 가격 정상 + 리뷰만 급증"이면 오염일 수 있으므로 보조 판단
                    if isinstance(prev_rc, int) and prev_rc > 0:
                        cur = int(rc)
                        if _ratio_outlier(cur, int(prev_rc), hi=8.0, lo=0.1) and abs(cur - int(prev_rc)) >= 5000:
                            return True
            except Exception:
                pass

            # 3) 평점 급변(outlier): 0.3 이상 튀면 오염 가능(보조)
            try:
                if rt is not None:
                    prev_ok = _neighbor_good(target_date=row.date, direction="older")
                    next_ok = _neighbor_good(target_date=row.date, direction="newer")
                    prev_rt = getattr(prev_ok, "rating", None) if prev_ok is not None else None
                    next_rt = getattr(next_ok, "rating", None) if next_ok is not None else None
                    cur = float(rt)
                    if isinstance(prev_rt, (int, float)) and isinstance(next_rt, (int, float)):
                        if abs(cur - float(prev_rt)) >= 0.3 and abs(cur - float(next_rt)) >= 0.3:
                            return True
            except Exception:
                pass

            return False

        def find_prev_good(before_date: date) -> TrackedProductPageDaily | None:
            for h in history:
                if h.date >= before_date:
                    continue
                if getattr(h, "error", None):
                    continue
                hs = getattr(h, "http_status", None)
                if isinstance(hs, int) and hs != 200:
                    continue
                if meta_price is not None and getattr(h, "price", None) is not None:
                    try:
                        mp = int(meta_price)
                        pp = int(getattr(h, "price"))
                        if mp > 0 and pp > 0:
                            ratio = pp / mp
                            if ratio > 2.5 or ratio < 0.4:
                                continue
                    except Exception:
                        pass
                return h
            return None

        for row in rows:
            scanned += 1
            if not looks_poisoned(row):
                continue
            prev = find_prev_good(row.date)
            # prev가 없으면 meta로라도 최소 복구
            try:
                if prev is not None:
                    row.title = prev.title
                    row.price = prev.price
                    row.review_count = prev.review_count
                    row.rating = prev.rating
                    row.delivery = prev.delivery
                    row.buy_count = prev.buy_count
                else:
                    if meta is not None:
                        if row.title is None:
                            row.title = meta.title
                        if row.price is None:
                            row.price = meta.price
                # base 복구 후에도 성공으로 남겨 UI가 흔들리지 않게 한다.
                row.http_status = 200
                row.error = None
                updated += 1
                repaired.append(
                    {
                        "product_url": u,
                        "date": row.date.isoformat(),
                        "from_prev": bool(prev is not None),
                    }
                )
            except Exception:
                pass

    try:
        db.commit()
    except Exception:
        db.rollback()

    return {
        "days": days,
        "scanned": scanned,
        "updated": updated,
        "repaired": repaired[:50],  # 너무 길어지지 않게 제한
    }


@app.get("/search-rank/page-metrics/scrape-once", response_model=dict)
def page_metrics_scrape_once(
    product_url: str = Query(..., description="단건 수집 대상 URL"),
    db: Session = Depends(get_db),
):
    """
    디버그/진단용: 특정 URL에 대해 현재 설정(Playwright/캡차 세션 재사용 포함)으로
    실제로 어떤 결과가 나오는지 1회 실행해 반환한다.
    - UI에서 '캡차는 풀었는데도 계속 captcha_detected' 같은 이슈의 원인을 확인하기 위함
    """
    u = (product_url or "").strip()
    if not u:
        raise HTTPException(status_code=400, detail="product_url is required")

    # 검색 fallback에 도움되는 힌트(대표상품명/카탈로그 id)를 최대한 DB에서 가져온다.
    search_title = None
    search_catalog_id = None
    try:
        meta: TrackedProductMeta | None = (
            db.query(TrackedProductMeta)
            .filter(TrackedProductMeta.product_url == u)
            .one_or_none()
        )
        search_title = (meta.title or "").strip() if meta else None
        try:
            search_catalog_id = str(meta.product_id_catalog) if (meta and meta.product_id_catalog) else None
        except Exception:
            search_catalog_id = None
    except Exception:
        search_title = None
        search_catalog_id = None

    result = _scrape_product_page_metrics(
        u,
        search_title=search_title or None,
        search_catalog_id=search_catalog_id or None,
    )
    # 진단 시 유용하도록 입력 힌트도 함께 반환
    return {
        "product_url": u,
        "search_title": search_title,
        "search_catalog_id": search_catalog_id,
        **(result or {}),
    }

@app.post("/search-rank/refresh-product-metadata", response_model=dict)
def refresh_tracked_product_metadata(
    db: Session = Depends(get_db),
):
    """
    등록된 내 상품(TrackedProductKeyword)의 URL 들을 기준으로
    shop.json 을 호출해 상품 메타데이터를 갱신한다.

    - 대표 키워드는 각 product_url 별로 가장 먼저 등록된 키워드를 사용한다.
    - 동일 키워드를 공유하는 여러 상품은 한 번의 shop.json 호출 결과를 재사용한다.
    """

    # (통일) API 세팅(DB 저장값) 우선 사용
    client_id = _first_nonempty(["NAVER_SEARCH_CLIENT_ID", "NAVER_KEY", "NAVER_CLIENT_ID"])
    client_secret = _first_nonempty(["NAVER_SEARCH_CLIENT_SECRET", "NAVER_SECRET", "NAVER_CLIENT_SECRET"])
    has_shop_api = bool(client_id and client_secret)

    # 1) 활성화된 추적 상품 URL 목록 + 대표 키워드 추출
    rows: List[TrackedProductKeyword] = (
        db.query(TrackedProductKeyword)
        .filter(TrackedProductKeyword.is_active.is_(True))
        .all()
    )

    by_url: dict[str, list[TrackedProductKeyword]] = {}
    # tracked_product_keyword 자체를 smartstore base URL로 정규화해 이후 매칭/저장 혼선을 줄인다.
    dirty_kw_rows: list[TrackedProductKeyword] = []
    for r in rows:
        url0 = (r.product_url or "").strip()
        if not url0:
            continue
        url = _canonicalize_smartstore_base_url(url0)
        if url0 != url:
            try:
                r.product_url = url
                dirty_kw_rows.append(r)
            except Exception:
                pass
        by_url.setdefault(url, []).append(r)

    if dirty_kw_rows:
        try:
            db.commit()
        except Exception:
            db.rollback()

    if not by_url:
        return {"updated": 0, "total_products": 0}

    # URL → (대표 키워드, SmartStore productId) 매핑 구성
    url_info: dict[str, tuple[str, Optional[str]]] = {}
    for url, kws in by_url.items():
        # 가장 먼저 등록된 키워드를 대표 키워드로 사용
        rep = sorted(kws, key=lambda x: x.id)[0]
        rep_kw = rep.keyword.strip()
        smart_id = _extract_product_id_path_only(url)
        if not rep_kw:
            continue
        url_info[url] = (rep_kw, smart_id)

    # 2) 대표 키워드 단위로 shop.json 호출 후, URL 별로 필터링
    updated = 0
    # keyword -> [(url, smart_id)]
    by_keyword: dict[str, list[tuple[str, Optional[str]]]] = {}
    for url, (kw, smart_id) in url_info.items():
        by_keyword.setdefault(kw, []).append((url, smart_id))

    for kw, targets in by_keyword.items():
        # 0) URL 직접 호출(og:title/og:image)로 우선 업데이트
        for url, _smart_id in targets:
            og = _fetch_product_og_metadata(url)
            if not og:
                try:
                    html_text, dbg = _fetch_html_best_effort(url=url, use_browser=True)
                except Exception:
                    html_text, dbg = (None, {})
                if html_text and not _is_shopping_block_html(html_text):
                    title, image = _extract_og_metadata_from_html(html_text=html_text)
                    html_site_name = _extract_og_site_name_from_html(html_text=html_text)
                    expected_mall = _infer_smartstore_mall_name(url)
                    normalized_site_name = html_site_name or expected_mall
                    title = _normalize_product_title(title, mall_name=normalized_site_name)
                    if title or image:
                        og = ProductMetadata(
                            title=title,
                            image_url=image,
                            site_name=normalized_site_name,
                            price=None,
                            product_id=None,
                        )
            if not og:
                continue
            try:
                url_norm = _canonicalize_smartstore_base_url(url)
                existing: TrackedProductMeta | None = (
                    db.query(TrackedProductMeta)
                    .filter(TrackedProductMeta.product_url == url_norm)
                    .one_or_none()
                )
                if existing is None:
                    existing = TrackedProductMeta(
                        product_url=url_norm,
                        keyword=kw,
                        title=og.title,
                        mall_name=og.site_name,
                        image_url=og.image_url,
                        price=None,
                        product_id_catalog=None,
                    )
                    db.add(existing)
                else:
                    # 중요: og 기반 값이 비어 있으면 기존 값을 덮어쓰지 않는다.
                    existing.keyword = kw
                    if og.title:
                        existing.title = og.title
                    if og.site_name:
                        existing.mall_name = og.site_name
                    if og.image_url:
                        existing.image_url = og.image_url
                    existing.updated_at = datetime.utcnow()
                db.commit()
                updated += 1
            except Exception as e:  # pragma: no cover
                db.rollback()
                print("[refresh-product-metadata] upsert(og) TrackedProductMeta failed:", e)

        # 1) OpenAPI(shop.json) 기반 보조 업데이트 (자격증명이 있을 때만)
        if not has_shop_api:
            continue
        try:
            resp = requests.get(
                NAVER_SHOP_ENDPOINT,
                params={"query": kw, "display": 50},
                headers={
                    "X-Naver-Client-Id": client_id,
                    "X-Naver-Client-Secret": client_secret,
                },
                timeout=5,
            )
        except Exception as e:  # pragma: no cover - 외부 네트워크 예외
            print(
                f"[refresh-product-metadata] Naver shop API request error keyword={kw} err={e}"
            )
            continue

        if resp.status_code >= 400:
            print(
                f"[refresh-product-metadata] Naver shop API status={resp.status_code} keyword={kw}"
            )
            continue

        data = resp.json()
        items = data.get("items") or []
        if not items:
            continue

        # 각 URL마다 SmartStore productId 기준으로 "정확 매칭"만 허용
        # (매칭 실패 시 items[0]로 덮어쓰면 다른 상품 메타로 오염된다)
        for url, smart_id in targets:
            chosen = None
            if smart_id:
                for item in items:
                    link = item.get("link") or ""
                    item_smart_id = _extract_product_id_path_only(link)
                    if item_smart_id == smart_id:
                        chosen = item
                        break
            if chosen is None:
                # 매칭 실패: 업데이트 스킵
                continue

            title = _strip_html_tags(chosen.get("title"))
            image_url = chosen.get("image")
            mall_name = chosen.get("mallName")
            title = _normalize_product_title(title, mall_name=mall_name or _infer_smartstore_mall_name(url))
            category1 = chosen.get("category1")
            category2 = chosen.get("category2")
            category3 = chosen.get("category3")
            category4 = chosen.get("category4")
            price_raw = chosen.get("lprice") or chosen.get("hprice") or 0
            try:
                price = int(price_raw)
            except (TypeError, ValueError):
                price = 0
            pid_raw = chosen.get("productId")
            try:
                pid_int = int(pid_raw) if pid_raw is not None else None
            except (TypeError, ValueError):
                pid_int = None

            try:
                url_norm = _canonicalize_smartstore_base_url(url)
                existing: TrackedProductMeta | None = (
                    db.query(TrackedProductMeta)
                    .filter(TrackedProductMeta.product_url == url_norm)
                    .one_or_none()
                )
                if existing is None:
                    existing = TrackedProductMeta(
                        product_url=url_norm,
                        keyword=kw,
                        title=title,
                        mall_name=mall_name,
                        image_url=image_url,
                        price=price,
                        product_id_catalog=pid_int,
                        category1=str(category1).strip() if category1 else None,
                        category2=str(category2).strip() if category2 else None,
                        category3=str(category3).strip() if category3 else None,
                        category4=str(category4).strip() if category4 else None,
                    )
                    db.add(existing)
                else:
                    existing.keyword = kw
                    existing.title = title
                    existing.mall_name = mall_name
                    existing.image_url = image_url
                    existing.price = price
                    existing.product_id_catalog = pid_int
                    # 카테고리는 비어 있으면 기존 값을 덮어쓰지 않는다.
                    if category1:
                        existing.category1 = str(category1).strip()
                    if category2:
                        existing.category2 = str(category2).strip()
                    if category3:
                        existing.category3 = str(category3).strip()
                    if category4:
                        existing.category4 = str(category4).strip()
                    existing.updated_at = datetime.utcnow()
                db.commit()
                updated += 1
            except Exception as e:  # pragma: no cover - 메타 upsert 실패는 치명적이지 않음
                db.rollback()
                print("[refresh-product-metadata] upsert TrackedProductMeta failed:", e)

    return {
        "updated": updated,
        "total_products": len(url_info),
        "skipped": False,
    }


@app.post("/search-rank/product-metadata/batch", response_model=Dict[str, Optional[ProductMetadata]])
def get_product_metadata_batch(
    req: ProductMetadataBatchRequest = Body(...),
    db: Session = Depends(get_db),
):
    """
    내 상품 추적(리스트) 진입 성능 개선을 위한 배치 조회(FAST/CACHED).

    주의:
    - 기존 /search-rank/product-metadata 는 "정확 매칭"을 위해 HTML/Shop API 호출까지 수행할 수 있어
      리스트 진입 시(상품 수만큼 호출) 매우 느려질 수 있다.
    - 이 엔드포인트는 **DB에 저장된 TrackedProductMeta**만 사용해 빠르게 응답한다.
      (오염 방지 차원에서 smartstore URL은 mall_name이 일치할 때만 title/image/price를 노출)
    """
    out: Dict[str, Optional[ProductMetadata]] = {}

    for it in (req.items or []):
        try:
            pid = str(getattr(it, "id", "") or "").strip()
            kw = str(getattr(it, "keyword", "") or "").strip()
            url_raw = str(getattr(it, "product_url", "") or "").strip()
            if not pid:
                continue
            if not kw or not url_raw or url_raw == "N/A":
                out[pid] = None
                continue

            normalized_url = _canonicalize_smartstore_base_url(url_raw)
            expected_mall = _infer_smartstore_mall_name(normalized_url) if normalized_url else None
            is_smartstore = False
            if normalized_url:
                try:
                    host = (urlparse(normalized_url).netloc or "").lower()
                    is_smartstore = host.endswith("smartstore.naver.com")
                except Exception:
                    is_smartstore = False

            if not normalized_url:
                out[pid] = None
                continue

            row: TrackedProductMeta | None = (
                db.query(TrackedProductMeta)
                .filter(TrackedProductMeta.product_url == normalized_url)
                .one_or_none()
            )
            if row is None:
                # DB에 없으면 최소 정보만(몰명 추정) 반환해 UI가 깨지지 않게 한다.
                out[pid] = ProductMetadata(
                    title=None,
                    image_url=None,
                    site_name=expected_mall,
                    price=None,
                    product_id=None,
                )
                continue

            if not is_smartstore:
                out[pid] = ProductMetadata(
                    title=_normalize_product_title(row.title, mall_name=row.mall_name),
                    image_url=row.image_url,
                    site_name=row.mall_name,
                    price=row.price,
                    product_id=row.product_id_catalog,
                )
                continue

            # smartstore: 오염 방지 + "정상인데도 숨김" 방지(구조적 수정)
            # - tracked_product_meta.mall_name 은 OpenAPI mallName(한글 상호)로 저장되는 케이스가 많다.
            # - 하지만 smartstore URL의 <mall> 세그먼트는 '몰ID(thesujata)'이므로, 단순 mall_name 비교는 자주 불일치한다.
            # - 리스트/배치 조회에서는 "요청 URL과 동일한 row"를 조회하므로,
            #   동일성 판정은 row.mall_name 대신 URL에서 추출한 mallId를 기준으로 한다.
            row_url_for_mall = None
            try:
                row_url_for_mall = getattr(row, "product_url", None)
            except Exception:
                row_url_for_mall = None
            db_mall = str((_infer_smartstore_mall_name(row_url_for_mall or normalized_url) or row.mall_name or "")).strip().lower()
            exp_mall = str(expected_mall or "").strip().lower()
            url_pid = _extract_product_id_path_only(normalized_url)
            db_pid = None
            try:
                db_pid = str(row.product_id_catalog) if row.product_id_catalog is not None else None
            except Exception:
                db_pid = None
            pid_matches = bool(url_pid and db_pid and str(url_pid) == str(db_pid))
            mall_matches = bool(exp_mall and db_mall == exp_mall)
            has_meta = bool((row.title or "").strip() or (row.image_url or "").strip())

            if has_meta and (mall_matches or pid_matches):
                out[pid] = ProductMetadata(
                    title=_normalize_product_title(row.title, mall_name=row.mall_name or expected_mall),
                    image_url=row.image_url,
                    # smartstore는 URL의 mallId(=expected_mall)가 더 안정적이므로 우선 노출한다.
                    site_name=expected_mall or row.mall_name,
                    price=row.price,
                    product_id=row.product_id_catalog,
                )
            else:
                out[pid] = ProductMetadata(
                    title=None,
                    image_url=None,
                    site_name=expected_mall or row.mall_name,
                    price=None,
                    product_id=row.product_id_catalog,
                )
        except Exception:
            try:
                if getattr(it, "id", None):
                    out[str(getattr(it, "id"))] = None
            except Exception:
                pass

    return out


@app.get("/search-rank/tracking-mode", response_model=ProductTrackingModeRead)
def get_product_tracking_mode(
    product_url: str = Query(..., description="상품 상세 URL(스마트스토어 등)"),
    db: Session = Depends(get_db),
):
    """
    상품별 '추적 키워드 운영 모드'(initial | focus)를 반환한다.
    - 기존 UI는 localStorage 단일 키로 저장되어 전 상품에 공유되는 문제가 있었으므로,
      DB(tracked_product_meta.tracking_mode)에 저장해 상품별로 분리한다.
    """
    u_raw = str(product_url or "").strip()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    u = _canonicalize_smartstore_base_url(u_raw)

    filters = _smartstore_product_url_filters(TrackedProductMeta, product_url=u)
    row: TrackedProductMeta | None = (
        db.query(TrackedProductMeta).filter(or_(*filters)).limit(1).one_or_none()
        if filters
        else db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url == u).one_or_none()
    )
    mode = str(getattr(row, "tracking_mode", "") or "").strip().lower()
    if mode not in ("initial", "focus"):
        mode = "focus"
    return ProductTrackingModeRead(product_url=u, tracking_mode=mode)


@app.put("/search-rank/tracking-mode", response_model=ProductTrackingModeRead)
def set_product_tracking_mode(
    payload: ProductTrackingModeWrite,
    db: Session = Depends(get_db),
):
    """
    상품별 '추적 키워드 운영 모드'(initial | focus)를 저장한다.
    """
    u_raw = str(payload.product_url or "").strip()
    mode = str(payload.tracking_mode or "").strip().lower()
    if not u_raw:
        raise HTTPException(status_code=400, detail="product_url is required")
    if mode not in ("initial", "focus"):
        raise HTTPException(status_code=400, detail="tracking_mode must be 'initial' or 'focus'")

    u = _canonicalize_smartstore_base_url(u_raw)
    now = datetime.utcnow()

    filters = _smartstore_product_url_filters(TrackedProductMeta, product_url=u)
    row: TrackedProductMeta | None = (
        db.query(TrackedProductMeta).filter(or_(*filters)).limit(1).one_or_none()
        if filters
        else db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url == u).one_or_none()
    )
    if row is None:
        row = TrackedProductMeta(product_url=u, tracking_mode=mode, updated_at=now)
        db.add(row)
    else:
        row.tracking_mode = mode
        row.updated_at = now
    db.commit()

    return ProductTrackingModeRead(product_url=u, tracking_mode=mode)


@app.get("/search-rank/product-metadata", response_model=ProductMetadata)
def get_product_metadata(
    keyword: str = Query(..., description="상품을 대표하는 검색 키워드"),
    product_url: Optional[str] = Query(
        None, description="스마트스토어 등 상품 상세 URL (productId 매칭용)"
    ),
    use_browser: bool = Query(False, description="차단 시 Playwright(캡차 세션)로 HTML을 가져와 메타를 추출"),
    db: Session = Depends(get_db),
):
    """
    네이버 쇼핑 검색 OpenAPI 를 사용해 상품 메타 정보를 조회한다.

    - 입력: 키워드(필수) + 상품 URL(선택, 있으면 productId 매칭에 사용)
    - 출력: title(태그 제거), image_url, site_name(mallName)
    - 네이버 OpenAPI 일일 호출 한도를 고려해 메모리 캐시를 사용한다.
    """

    now = datetime.utcnow()
    cache_key = f"{keyword}|{product_url or ''}"

    # smartstore는 query/hash가 달라도 동일 상품이므로 base URL로 통일한다.
    normalized_url = _canonicalize_smartstore_base_url((product_url or "").strip())
    expected_mall = _infer_smartstore_mall_name(normalized_url) if normalized_url else None
    is_smartstore = False
    if normalized_url:
        try:
            host = (urlparse(normalized_url).netloc or "").lower()
            is_smartstore = host.endswith("smartstore.naver.com")
        except Exception:
            is_smartstore = False

    # 0) DB 에 저장된 메타데이터가 있으면 우선 사용 (shop.json 호출 회피)
    if normalized_url:
        row: TrackedProductMeta | None = (
            db.query(TrackedProductMeta)
            .filter(TrackedProductMeta.product_url == normalized_url)
            .one_or_none()
        )
        if row:
            # IMPORTANT:
            # smartstore URL은 서버에서 direct requests가 429/캡차로 자주 막힌다.
            # 과거 fallback으로 DB에 다른 상품 메타가 저장되었을 가능성이 있어,
            # "검증 없이 DB 값을 즉시 반환"하면 UI가 '다른 상품'으로 오염될 수 있다.
            #
            # 따라서 smartstore URL은:
            # - use_browser=true 로 HTML(Playwright)에서 og 메타를 뽑아 성공한 경우에만 저장/반환
            # - 그 외에는 shop.json의 "정확 매칭"이 성공한 경우만 반환
            # - DB에 값이 있더라도 단독으로는 신뢰하지 않고(오염 방지), 아래 흐름으로 계속 진행한다.
            if not is_smartstore:
                return ProductMetadata(
                    title=_normalize_product_title(row.title, mall_name=row.mall_name),
                    image_url=row.image_url,
                    site_name=row.mall_name,
                    price=row.price,
                    product_id=row.product_id_catalog,
                )
            # smartstore 인 경우:
            # - 과거 fallback으로 오염된 메타가 저장되었을 수 있으므로 무조건 신뢰하면 안 된다.
            # - 다만 "URL에서 유추한 mall_name"과 DB mall_name이 일치하고, title/image가 존재한다면
            #   같은 몰의 동일 상품으로 볼 수 있어(오염 가능성 낮음) DB 값을 우선 반환해 UI(이미지/가격)를 안정화한다.
            if expected_mall and str(row.mall_name or "").strip().lower() == str(expected_mall).strip().lower():
                if (row.title or "").strip() or (row.image_url or "").strip():
                    return ProductMetadata(
                        title=_normalize_product_title(row.title, mall_name=row.mall_name or expected_mall),
                        image_url=row.image_url,
                        site_name=row.mall_name,
                        price=row.price,
                        product_id=row.product_id_catalog,
                    )
            # 그 외에는 아래 흐름(HTML/Shop API)으로 계속 진행.

    # 0.4) URL이 있으면 HTML에서 og 메타를 우선 추출한다.
    # - requests는 429/403으로 막힐 수 있어, use_browser=true면 Playwright로 우회한다.
    if normalized_url:
        html_text, dbg = _fetch_html_best_effort(url=normalized_url, use_browser=bool(use_browser))
        if html_text and not _is_shopping_block_html(html_text):
            title, image = _extract_og_metadata_from_html(html_text=html_text)
            title = _normalize_product_title(title, mall_name=expected_mall)
            if title or image:
                meta0 = ProductMetadata(
                    title=title,
                    image_url=image,
                    site_name=expected_mall,
                    price=None,
                    product_id=None,
                )
                PRODUCT_METADATA_CACHE[cache_key] = (now, meta0)
                try:
                    existing: TrackedProductMeta | None = (
                        db.query(TrackedProductMeta)
                        .filter(TrackedProductMeta.product_url == normalized_url)
                        .one_or_none()
                    )
                    if existing is None:
                        existing = TrackedProductMeta(
                            product_url=normalized_url,
                            keyword=keyword,
                            title=title,
                            mall_name=expected_mall,
                            image_url=image,
                            price=None,
                            product_id_catalog=None,
                        )
                        db.add(existing)
                    else:
                        existing.keyword = keyword
                        if title:
                            existing.title = title
                        if expected_mall:
                            existing.mall_name = expected_mall
                        if image:
                            existing.image_url = image
                        existing.updated_at = datetime.utcnow()
                    db.commit()
                except Exception as e:  # pragma: no cover
                    db.rollback()
                    print("[product-metadata] upsert(url-html) TrackedProductMeta failed:", e, dbg)
                return meta0

    # 0.5) URL 직접 호출(og:title/og:image) 기반 메타데이터 우선 시도
    # - 키워드 검색 결과 기반(shop.json)은 '다른 상품'으로 오염될 수 있어,
    #   URL이 주어진 경우엔 URL 기반 추출을 먼저 사용한다.
    if normalized_url:
        og = _fetch_product_og_metadata(normalized_url)
        if og:
            PRODUCT_METADATA_CACHE[cache_key] = (now, og)
            try:
                existing: TrackedProductMeta | None = (
                    db.query(TrackedProductMeta)
                    .filter(TrackedProductMeta.product_url == normalized_url)
                    .one_or_none()
                )
                if existing is None:
                    existing = TrackedProductMeta(
                        product_url=normalized_url,
                        keyword=keyword,
                        title=og.title,
                        mall_name=og.site_name,
                        image_url=og.image_url,
                        price=None,
                        product_id_catalog=None,
                    )
                    db.add(existing)
                else:
                    existing.keyword = keyword
                    if og.title:
                        existing.title = og.title
                    if og.site_name:
                        existing.mall_name = og.site_name
                    if og.image_url:
                        existing.image_url = og.image_url
                    existing.updated_at = datetime.utcnow()
                db.commit()
            except Exception as e:  # pragma: no cover
                db.rollback()
                print("[product-metadata] upsert(og) TrackedProductMeta failed:", e)
            return og

    # 1) 메모리 캐시된 값이 있고 TTL 이내면 그대로 사용
    cached = PRODUCT_METADATA_CACHE.get(cache_key)
    if cached:
        cached_at, meta = cached
        if now - cached_at < timedelta(hours=METADATA_CACHE_TTL_HOURS):
            return meta

    # (통일) API 세팅(DB 저장값) 우선 사용
    client_id = _first_nonempty(["NAVER_SEARCH_CLIENT_ID", "NAVER_KEY", "NAVER_CLIENT_ID"])
    client_secret = _first_nonempty(["NAVER_SEARCH_CLIENT_SECRET", "NAVER_SECRET", "NAVER_CLIENT_SECRET"])
    if not client_id or not client_secret:
        # 키가 없으면 UI 를 깨지 않도록 빈 메타데이터 반환
        print("[product-metadata] NAVER_SEARCH_CLIENT_ID/SECRET not configured")
        if cached:
            return cached[1]
        return ProductMetadata(title=None, image_url=None, site_name=expected_mall, price=None, product_id=None)

    # IMPORTANT: product_url querystring 안에 다른 URL(originUrl=...)이 포함될 수 있어
    # 전체 문자열에서 /products/<id>를 찾으면 "다른 상품"을 잘못 매칭할 수 있다.
    # 따라서 productId 추출은 path 기준으로만 수행한다.
    product_id = _extract_product_id_path_only(product_url)

    try:
        resp = requests.get(
            NAVER_SHOP_ENDPOINT,
            # 검색어는 항상 keyword 기준으로 사용하고,
            # product_id 는 나중에 결과 필터링에만 사용한다.
            # (productId 단독 검색은 응답이 비어 있는 경우가 있어 안정성이 떨어짐)
            params={"query": keyword, "display": 50},
            headers={
                "X-Naver-Client-Id": client_id,
                "X-Naver-Client-Secret": client_secret,
            },
            timeout=5,
        )
    except Exception as e:  # pragma: no cover - 외부 네트워크 예외
        print(f"[product-metadata] Naver shop API request error keyword={keyword} err={e}")
        if cached:
            return cached[1]
        return ProductMetadata(title=None, image_url=None, site_name=None, price=None, product_id=None)

    if resp.status_code >= 400:
        print(
            f"[product-metadata] Naver shop API status={resp.status_code} keyword={keyword}"
        )
        if cached:
            return cached[1]
        return ProductMetadata(title=None, image_url=None, site_name=expected_mall, price=None, product_id=None)

    data = resp.json()
    items = data.get("items") or []
    if not items:
        if cached:
            return cached[1]
        return ProductMetadata(title=None, image_url=None, site_name=expected_mall, price=None, product_id=None)

    # product_url 이 있으면 SmartStore productId 기준으로 '정확 매칭'만 허용한다.
    # (매칭 실패 시 items[0]로 떨어지면 다른 상품 메타로 오염될 수 있다)
    # product_url 이 없을 때만 items[0]을 사용한다.
    chosen = None
    if product_id:
        for item in items:
            # shop.json 의 productId 는 catalog ID 이므로,
            # SmartStore URL 의 productId 와 직접 매칭하지 않고
            # item.link 에서 SmartStore productId 를 추출해 비교한다.
            link = item.get("link") or ""
            item_smart_id = _extract_product_id_path_only(link)
            if item_smart_id == product_id:
                chosen = item
                break
    if chosen is None:
        if normalized_url:
            # URL이 있는데도 매칭 실패면 '다른 상품' 오염을 막기 위해 빈 메타를 반환한다.
            if cached:
                return cached[1]
            return ProductMetadata(title=None, image_url=None, site_name=expected_mall, price=None, product_id=None)
        chosen = items[0]

    title = _strip_html_tags(chosen.get("title"))
    image_url = chosen.get("image")
    site_name = chosen.get("mallName")
    title = _normalize_product_title(title, mall_name=site_name or expected_mall)
    price_raw = chosen.get("lprice") or chosen.get("hprice") or 0
    try:
        price = int(price_raw)
    except (TypeError, ValueError):
        price = 0
    pid_raw = chosen.get("productId")
    try:
        pid_int = int(pid_raw) if pid_raw is not None else None
    except (TypeError, ValueError):
        pid_int = None

    meta = ProductMetadata(
        title=title,
        image_url=image_url,
        site_name=site_name,
        price=price,
        product_id=pid_int,
    )
    # 디버깅: 어떤 상품 정보가 선택되었는지 로그로 남긴다.
    print(
        "[product-metadata] chosen",
        {
            "keyword": keyword,
            "product_url": product_url,
            "product_id": pid_int,
            "title": title,
            "price": price,
            "site_name": site_name,
        },
    )
    PRODUCT_METADATA_CACHE[cache_key] = (now, meta)

    # 3) DB 메타 테이블에 upsert (URL 가 있는 경우에만)
    if normalized_url:
        try:
            existing: TrackedProductMeta | None = (
                db.query(TrackedProductMeta)
                .filter(TrackedProductMeta.product_url == normalized_url)
                .one_or_none()
            )
            if existing is None:
                existing = TrackedProductMeta(
                    product_url=normalized_url,
                    keyword=keyword,
                    title=title,
                    mall_name=site_name,
                    image_url=image_url,
                    price=price,
                    product_id_catalog=pid_int,
                )
                db.add(existing)
            else:
                existing.keyword = keyword
                existing.title = title
                existing.mall_name = site_name
                existing.image_url = image_url
                existing.price = price
                existing.product_id_catalog = pid_int
                existing.updated_at = datetime.utcnow()
            db.commit()
        except Exception as e:  # pragma: no cover - 메타 upsert 실패는 치명적이지 않음
            db.rollback()
            print("[product-metadata] upsert TrackedProductMeta failed:", e)

    return meta


@app.get("/search-rank/product-analytics", response_model=ProductAnalytics)
def get_product_analytics(
    keyword: str = Query(..., description="상품을 대표하는 검색 키워드"),
    days: int = Query(7, ge=1, le=365),
    db: Session = Depends(get_db),
):
    """
    내 상품 분석(전일 기준)에서 사용할 요약 지표를 반환한다.

    현재는 `naver_product_rank_daily` 의 purchase_cnt 를 기반으로
    최근 N일간 예상 판매량만 계산하며, 리뷰/평점 관련 지표는
    추후 별도 수집 파이프라인 구축 시 채워질 수 있다.
    """

    today = _today_kst()
    date_from = today - timedelta(days=days - 1)

    # 1) 최근 N일간 예상 판매량 (랭킹 스냅샷의 purchase_cnt 합계)
    rank_rows = (
        db.query(NaverProductRankDaily)
        .filter(
            NaverProductRankDaily.keyword == keyword,
            NaverProductRankDaily.date >= date_from,
            NaverProductRankDaily.date <= today,
        )
        .all()
    )
    if not rank_rows:
        rank_rows = (
            db.query(NaverProductRankDaily)
            .filter(NaverProductRankDaily.keyword == keyword)
            .all()
        )
    expected_sales = sum(int(r.purchase_cnt or 0) for r in rank_rows) if rank_rows else 0

    # 2) 리뷰/평점 스냅샷 (naver_product_review_daily 기준, 전일 대비)
    yesterday = today - timedelta(days=1)
    latest: Optional[NaverProductReviewDaily] = (
        db.query(NaverProductReviewDaily)
        .filter(
            NaverProductReviewDaily.keyword == keyword,
            NaverProductReviewDaily.date <= yesterday,
        )
        .order_by(
            NaverProductReviewDaily.date.desc(),
            NaverProductReviewDaily.rating_count.desc(),
        )
        .limit(1)
        .one_or_none()
    )

    prev: Optional[NaverProductReviewDaily] = None
    if latest is not None:
        prev = (
            db.query(NaverProductReviewDaily)
            .filter(
                NaverProductReviewDaily.keyword == keyword,
                NaverProductReviewDaily.date < latest.date,
            )
            .order_by(NaverProductReviewDaily.date.desc())
            .limit(1)
            .one_or_none()
        )

    rating = latest.rating_avg if latest is not None else None
    total_reviews = latest.rating_count if latest is not None else None
    if latest is not None:
        prev_count = prev.rating_count if prev is not None else 0
        review_delta = latest.rating_count - prev_count
        rating_buckets = [
            RatingBucket(score=1, count=latest.rating_1_cnt),
            RatingBucket(score=2, count=latest.rating_2_cnt),
            RatingBucket(score=3, count=latest.rating_3_cnt),
            RatingBucket(score=4, count=latest.rating_4_cnt),
            RatingBucket(score=5, count=latest.rating_5_cnt),
        ]
    else:
        review_delta = None
        rating_buckets = []

    return ProductAnalytics(
        expectedSales7d=expected_sales,
        rating=rating,
        totalReviews=total_reviews,
        reviewDelta=review_delta,
        ratingBuckets=rating_buckets,
    )


@app.post("/search-rank/fetch-today")
def fetch_today_ranks_from_naver_shop(
    keywords: Optional[list[str]] = None,
    db: Session = Depends(get_db),
):
    """
    네이버 쇼핑 검색 OpenAPI를 사용해 **당일 기준** 랭킹 스냅샷을 수집한다.

    - 입력 keywords 가 없으면: 활성화된 tracked_product_keyword 의 keyword 목록을 사용
    - 각 키워드별로 최대 50개 상품을 가져와 `naver_product_rank_daily` 에 upsert
    - rank 는 OpenAPI 응답 순서(1,2,3,...)를 그대로 사용한다.
    """

    # (통일) API 세팅(DB 저장값) 우선 사용
    client_id = _first_nonempty(["NAVER_SEARCH_CLIENT_ID", "NAVER_KEY", "NAVER_CLIENT_ID"])
    client_secret = _first_nonempty(["NAVER_SEARCH_CLIENT_SECRET", "NAVER_SECRET", "NAVER_CLIENT_SECRET"])
    if not client_id or not client_secret:
        # 키가 없으면 외부 호출을 생략하고, 빈 결과를 200 으로 반환한다.
        # 프론트는 기존 DB 데이터만으로 화면을 그리게 된다.
        today_str = _today_kst().strftime("%Y-%m-%d")
        print("[fetch-today] NAVER_SEARCH_CLIENT_ID/SECRET not configured, skipping sync")
        return {
            "date": today_str,
            "keywords": keywords or [],
            "total_products": 0,
            "per_keyword": {},
            "skipped": "NAVER_SEARCH_CLIENT_ID/SECRET not configured",
        }

    # 키워드 목록이 주어지지 않으면 tracked_product_keyword 테이블에서 조회
    if not keywords:
        keywords = (
            db.query(TrackedProductKeyword.keyword)
            .filter(TrackedProductKeyword.is_active.is_(True))
            .distinct()
            .order_by(TrackedProductKeyword.keyword.asc())
            .all()
        )
        keywords = [k[0] for k in keywords]

    today_str = _today_kst().strftime("%Y-%m-%d")
    total_products = 0
    results: dict[str, int] = {}

    for kw in keywords:
        try:
            resp = requests.get(
                NAVER_SHOP_ENDPOINT,
                params={
                    "query": kw,
                    "display": 50,
                    "start": 1,
                    "sort": "sim",  # 정확도순
                },
                headers={
                    "X-Naver-Client-Id": client_id,
                    "X-Naver-Client-Secret": client_secret,
                },
                timeout=5,
            )
        except Exception as e:  # pragma: no cover - 외부 네트워크 예외
            print(f"[fetch-today] request error keyword={kw} err={e}")
            results[kw] = 0
            continue

        if resp.status_code >= 400:
            print(
                f"[fetch-today] Naver shop API status={resp.status_code} keyword={kw}"
            )
            results[kw] = 0
            continue

        data = resp.json()
        items = data.get("items") or []
        products: list[dict] = []
        for idx, item in enumerate(items):
            try:
                rank = idx + 1
                title = _strip_html_tags(item.get("title"))
                mall_name = (item.get("mallName") or "").strip()
                price = int(item.get("lprice") or 0)

                # shop.json 의 productId 는 카탈로그 ID 이므로,
                # 랭킹 테이블의 product_id 는 SmartStore 상품 ID(링크 기준)로 저장한다.
                link = item.get("link") or ""
                smart_id_str = _extract_product_id_from_url(link)
                product_id = int(smart_id_str) if smart_id_str is not None else None

                image_url = item.get("image")
                category1 = item.get("category1")
                category2 = item.get("category2")
                category3 = item.get("category3")
                category4 = item.get("category4")
                brand = item.get("brand")
                maker = item.get("maker")
            except Exception:
                continue

            if not title:
                continue

            products.append(
                {
                    "rank": rank,
                    "product_title": title,
                    "mall_name": mall_name,
                    "price": price,
                    "purchase_cnt": 0,
                    "product_id": product_id,
                    "image_url": image_url,
                    "category1": category1,
                    "category2": category2,
                    "category3": category3,
                    "category4": category4,
                    "brand": brand,
                    "maker": maker,
                    "is_our_brand": False,
                }
            )

        if not products:
            results[kw] = 0
            continue

        count = upsert_product_ranks_for_keyword(
            keyword=kw,
            target_date=today_str,
            products=products,
        )
        results[kw] = count
        total_products += count

    return {
        "date": today_str,
        "keywords": keywords,
        "total_products": total_products,
        "per_keyword": results,
    }


def _shopping_api_fetch_page_via_context_request(
    ctx,
    *,
    keyword: str,
    paging_index: int,
    paging_size: int,
    cat_id: str | None,
) -> tuple[int | None, str]:
    """
    Playwright BrowserContext의 request API로 쇼핑 내부 API(/api/search/all)를 호출한다.
    - pagingIndex/pagingSize로 페이지를 넘기며 TOP120(40*3) 같은 범위를 조회할 때 사용한다.
    - catId를 주면 카테고리 필터를 걸어 "카테고리 내 TOPN"을 조회한다.
    """
    q = (keyword or "").strip()
    if not q:
        return (None, "")
    pi = int(paging_index or 1)
    ps = int(paging_size or 40)
    if pi < 1:
        pi = 1
    if ps < 1:
        ps = 40
    params: dict[str, str] = {
        "query": q,
        "pagingIndex": str(pi),
        "pagingSize": str(ps),
        "viewType": "list",
        "sort": "rel",
    }
    cid = str(cat_id or "").strip()
    if cid and cid.isdigit():
        params["catId"] = cid
    api_url = "https://search.shopping.naver.com/api/search/all?" + urllib.parse.urlencode(params)
    try:
        referer = "https://search.shopping.naver.com/search/all?" + urllib.parse.urlencode({"query": q})
        resp = ctx.request.get(
            api_url,
            headers={
                "Accept": "*/*",
                "Accept-Language": "ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7",
                "Referer": referer,
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
            },
            timeout=15000,
        )
        try:
            status = int(getattr(resp, "status", None) or 0) or None
        except Exception:
            status = None
        try:
            text0 = resp.text() if hasattr(resp, "text") else ""
        except Exception:
            text0 = ""
        return (status, str(text0 or ""))
    except Exception:
        return (None, "")


def _shopping_api_fetch_page_via_page_fetch(
    page,
    *,
    keyword: str,
    paging_index: int,
    paging_size: int,
    cat_id: str | None,
) -> tuple[int | None, str]:
    """
    브라우저 '페이지'에서 fetch를 실행해 /api/search/all을 호출한다.
    - context.request 기반 호출이 418/access_limited로 차단될 때의 폴백으로 사용.
    - 실제 탭/세션/JS 환경(호스트 크롬 CDP)을 최대한 그대로 사용한다.
    """
    q = (keyword or "").strip()
    if not q:
        return (None, "")
    pi = int(paging_index or 1)
    ps = int(paging_size or 40)
    if pi < 1:
        pi = 1
    if ps < 1:
        ps = 40

    cid = str(cat_id or "").strip()
    try:
        payload = page.evaluate(
            """async ({ kw, pi, ps, cid }) => {
              const u = new URL('https://search.shopping.naver.com/api/search/all');
              u.searchParams.set('query', String(kw || ''));
              u.searchParams.set('pagingIndex', String(pi || 1));
              u.searchParams.set('pagingSize', String(ps || 40));
              u.searchParams.set('viewType', 'list');
              u.searchParams.set('sort', 'rel');
              if (cid && /^[0-9]+$/.test(String(cid))) u.searchParams.set('catId', String(cid));
              const res = await fetch(u.toString(), { credentials: 'include' });
              const text = await res.text();
              return { status: res.status, text };
            }""",
            {"kw": q, "pi": pi, "ps": ps, "cid": cid},
        )
    except Exception:
        payload = None

    if not isinstance(payload, dict):
        return (None, "")
    status = None
    try:
        status = int(payload.get("status") or 0) or None
    except Exception:
        status = None
    try:
        text0 = str(payload.get("text") or "")
    except Exception:
        text0 = ""
    return (status, text0)


def _shopping_search_page_collect_links(
    page,
    *,
    keyword: str,
    paging_index: int,
    paging_size: int,
    cat_id: str | None,
) -> list[str]:
    """
    쇼핑 검색 "페이지 HTML"(__NEXT_DATA__)에서 상품 링크를 추출한다.
    - /api/search/all 이 418(access_limited)로 막히는 환경에서의 구조적 우회 경로.
    - catId(카테고리 필터)가 있으면 URL에 그대로 포함한다.
    """
    q = (keyword or "").strip()
    if not q:
        return []
    pi = int(paging_index or 1)
    ps = int(paging_size or 40)
    if pi < 1:
        pi = 1
    if ps < 1:
        ps = 40
    params: dict[str, str] = {"query": q, "pagingIndex": str(pi), "pagingSize": str(ps), "sort": "rel"}
    cid = str(cat_id or "").strip()
    if cid and cid.isdigit():
        params["catId"] = cid
    url = "https://search.shopping.naver.com/search/all?" + urllib.parse.urlencode(params)
    try:
        page.goto(url, wait_until="domcontentloaded", timeout=60000)
    except Exception:
        pass
    try:
        # __NEXT_DATA__가 핵심 신호라 약간 기다린다.
        page.wait_for_selector("script#__NEXT_DATA__", timeout=8000)
    except Exception:
        pass
    html_text = ""
    try:
        html_text = page.content() or ""
    except Exception:
        html_text = ""
    rows = _extract_products_with_tags_from_shopping_search_html(html_text=html_text)
    links: list[str] = []
    for r in rows:
        try:
            u = str((r or {}).get("link") or "").strip()
        except Exception:
            u = ""
        if u.startswith("http"):
            links.append(u)
    # dedupe keep order
    uniq: list[str] = []
    seen: set[str] = set()
    for u in links:
        if u in seen:
            continue
        seen.add(u)
        uniq.append(u)
    return uniq


def _extract_ranked_links_from_shopping_api_response(data: object) -> list[str]:
    """
    /api/search/all 응답(JSON)에서 '검색 결과 상품 링크'를 랭킹 순서대로 추출한다.
    - 내부 구조가 자주 바뀌므로, '상품 같은 dict'가 많이 들어있는 list를 찾아 그 list 순서를 랭킹으로 사용한다.
    - 반환: link(url) 리스트 (중복/None 제외, 순서 유지)
    """
    def looks_like_product(d: dict) -> bool:
        title_ok = False
        for k in ("productTitle", "productName", "mallProductTitle", "title", "name"):
            v = d.get(k)
            if isinstance(v, str) and v.strip():
                title_ok = True
                break
        if not title_ok:
            return False
        id_ok = bool(d.get("productId") or d.get("mallProductId"))
        url_ok = False
        for k in ("mallProductUrl", "productUrl", "link", "url"):
            v = d.get(k)
            if isinstance(v, str) and v.strip().startswith("http"):
                url_ok = True
                break
        it = d.get("item")
        if (not url_ok) and isinstance(it, dict):
            for k in ("mallProductUrl", "productUrl", "link", "url"):
                v = it.get(k)
                if isinstance(v, str) and v.strip().startswith("http"):
                    url_ok = True
                    break
        return bool(id_ok or url_ok)

    def pick_link(d: dict) -> str | None:
        for k in ("mallProductUrl", "productUrl", "link", "url"):
            v = d.get(k)
            if isinstance(v, str) and v.strip().startswith("http"):
                return v.strip()
        it = d.get("item")
        if isinstance(it, dict):
            for k in ("mallProductUrl", "productUrl", "link", "url"):
                v = it.get(k)
                if isinstance(v, str) and v.strip().startswith("http"):
                    return v.strip()
        return None

    # 가장 '상품 리스트'로 보이는 list를 찾는다(상품-like dict 비율이 높은 리스트)
    best_list: list[dict] | None = None
    best_score = 0

    def walk(obj: object) -> None:
        nonlocal best_list, best_score
        if obj is None:
            return
        if isinstance(obj, list):
            # product-like count를 보고 후보로 채택
            prod_like = 0
            sample = obj[:120]
            for it in sample:
                if isinstance(it, dict) and looks_like_product(it):
                    prod_like += 1
            # 점수: product-like 개수
            if prod_like > best_score:
                best_score = prod_like
                best_list = [it for it in obj if isinstance(it, dict)]
            for it in obj:
                walk(it)
            return
        if isinstance(obj, dict):
            for _k, v in obj.items():
                walk(v)

    walk(data)

    rows = best_list or []
    out: list[str] = []
    seen: set[str] = set()
    for d in rows:
        if not looks_like_product(d):
            continue
        link = pick_link(d)
        if not link:
            continue
        if link in seen:
            continue
        seen.add(link)
        out.append(link)
    return out


def _category_key_from_meta(meta: TrackedProductMeta | None) -> str | None:
    if meta is None:
        return None
    parts = []
    for k in ("category1", "category2", "category3", "category4"):
        v = getattr(meta, k, None)
        s = str(v or "").strip()
        if s:
            parts.append(s)
    if not parts:
        return None
    return " > ".join(parts)


def _resolve_category_product_urls(
    db: Session,
    *,
    seed_product_url: str,
    max_products: int,
) -> tuple[list[str], str | None]:
    """
    seed 상품의 tracked_product_meta.category1~4를 기준으로 같은 카테고리 상품 URL 목록을 구성한다.
    반환: (product_urls, category_path)
    """
    seed = (seed_product_url or "").strip()
    meta: TrackedProductMeta | None = (
        db.query(TrackedProductMeta).filter(TrackedProductMeta.product_url == seed).one_or_none()
    )
    cat_path = _category_key_from_meta(meta)
    if not cat_path:
        return ([seed], None)

    # 동일 카테고리로 저장된 meta를 가진 상품들
    q = db.query(TrackedProductMeta.product_url).filter(
        TrackedProductMeta.category1 == getattr(meta, "category1", None),
        TrackedProductMeta.category2 == getattr(meta, "category2", None),
        TrackedProductMeta.category3 == getattr(meta, "category3", None),
        TrackedProductMeta.category4 == getattr(meta, "category4", None),
    )
    urls = [str(x[0] or "").strip() for x in q.all() if x and str(x[0] or "").strip()]
    # 실제로 '내 상품 추적'에 등록된 상품만 대상으로 제한(TrackedProductKeyword 활성 기준)
    active_urls = {
        str(x[0] or "").strip()
        for x in (
            db.query(TrackedProductKeyword.product_url)
            .filter(TrackedProductKeyword.is_active.is_(True))
            .distinct()
            .all()
        )
        if x and str(x[0] or "").strip()
    }
    urls = [u for u in urls if u in active_urls]
    # seed 우선 + 최대 max_products
    seen: set[str] = set()
    out: list[str] = []
    for u in [seed] + urls:
        if not u or u in seen:
            continue
        seen.add(u)
        out.append(u)
        if len(out) >= int(max_products or 10):
            break
    return (out or [seed], cat_path)


def _resolve_keywords_for_seed(db: Session, *, seed_product_url: str, payload_keywords: list[str] | None) -> list[str]:
    if payload_keywords:
        ks = [str(k or "").strip() for k in payload_keywords if str(k or "").strip()]
        return sorted(list(dict.fromkeys(ks)))
    # 기본: "등록된 키워드" 목록
    # - 수기 키워드(월검색량) + tracked 키워드(핵심/그룹) 모두 포함
    # - URL 정규화 차이를 고려해 안전 필터를 사용한다.
    u = str(seed_product_url or "").strip()
    if not u:
        return []
    mk_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=u)
    tk_filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=u)

    manual_rows = (
        db.query(TrackedProductManualKeyword.keyword)
        .filter(or_(*mk_filters), TrackedProductManualKeyword.is_active.is_(True))
        .order_by(TrackedProductManualKeyword.keyword.asc())
        .all()
    )
    tracked_rows = (
        db.query(TrackedProductKeyword.keyword)
        .filter(or_(*tk_filters), TrackedProductKeyword.is_active.is_(True))
        .order_by(TrackedProductKeyword.keyword.asc())
        .all()
    )
    ks = [
        *[str(x[0] or "").strip() for x in (manual_rows or []) if x and str(x[0] or "").strip()],
        *[str(x[0] or "").strip() for x in (tracked_rows or []) if x and str(x[0] or "").strip()],
    ]
    return sorted(list(dict.fromkeys(ks)))


def _run_category_crawl_job(
    *,
    job_id: str,
    job_name: str,
    seed_product_url: str,
    product_urls: list[str],
    keywords: list[str],
    category_path: str | None,
    category_id: str | None,
    target_date: date,
    limit: int,
) -> None:
    """
    BackgroundTasks에서 실행되는 실제 크롤링/저장 작업.
    """
    # 0) job run row STARTED
    with SessionLocal() as s:
        try:
            s.execute(
                text(
                    "INSERT INTO analytics_job_run(job_name, run_date, status) "
                    "VALUES (:job_name, :run_date, :status) "
                    "ON CONFLICT (job_name, run_date) DO UPDATE SET status = EXCLUDED.status, finished_at = NULL, detail = NULL"
                ),
                {"job_name": job_name, "run_date": target_date, "status": "STARTED"},
            )
            s.commit()
        except Exception:
            try:
                s.rollback()
            except Exception:
                pass

    # 1) 카테고리 ID 추론(없으면)
    cid = str(category_id or "").strip() or None
    if (not cid) and category_path:
        try:
            # 첫 키워드로 카테고리 ID를 추론(캐시됨)
            inferred = _pw_call(lambda: _infer_category_id_from_shopping_search(keyword=keywords[0], desired_path=category_path), timeout=120.0)
            if isinstance(inferred, tuple) and inferred and inferred[0]:
                cid = str(inferred[0]).strip() or None
        except Exception:
            cid = None

    # 2) target productId set
    targets: dict[str, str] = {}
    for u in product_urls:
        pid = _canonical_product_id(u)
        if pid:
            targets[u] = pid

    page_size = 40
    pages = int(math.ceil(float(max(1, int(limit))) / float(page_size)))
    pages = max(1, min(3, pages))  # TOP120 기준 3페이지 상한

    # 3) 크롤링
    saved = 0
    for idx_kw, kw in enumerate(keywords):
        # 취소 요청이 들어오면 즉시 중단한다(협력적 cancel).
        if _is_category_crawl_cancelled(job_id):
            with SessionLocal() as s:
                try:
                    s.query(AnalyticsJobRun).filter(
                        AnalyticsJobRun.job_name == job_name,
                        AnalyticsJobRun.run_date == target_date,
                    ).update(
                        {
                            "status": "CANCELLED",
                            "finished_at": datetime.utcnow(),
                            "detail": json.dumps(
                                {"job_id": job_id, "saved_cells": saved, "cancelled": True},
                                ensure_ascii=False,
                            ),
                        },
                        synchronize_session=False,
                    )
                    s.commit()
                except Exception:
                    try:
                        s.rollback()
                    except Exception:
                        pass
            return
        kw0 = str(kw or "").strip()
        if not kw0:
            continue

        found_rank_by_url: dict[str, int] = {u: 0 for u in product_urls}
        # 빠른 조기 종료를 위해 "찾은 productId" 집합도 유지한다.
        found_pid: set[str] = set()

        for pi in range(1, pages + 1):
            # access_limited/캡차를 완화하기 위해 요청 간 간격에 지터를 준다.
            # - 키워드/페이지당 1회 요청이므로, 작은 지연이 전체 성공률을 크게 올릴 수 있다.
            try:
                time.sleep(random.uniform(0.35, 0.85))
            except Exception:
                pass
            if _is_category_crawl_cancelled(job_id):
                with SessionLocal() as s:
                    try:
                        s.query(AnalyticsJobRun).filter(
                            AnalyticsJobRun.job_name == job_name,
                            AnalyticsJobRun.run_date == target_date,
                        ).update(
                            {
                                "status": "CANCELLED",
                                "finished_at": datetime.utcnow(),
                                "detail": json.dumps(
                                    {"job_id": job_id, "saved_cells": saved, "cancelled": True},
                                    ensure_ascii=False,
                                ),
                            },
                            synchronize_session=False,
                        )
                        s.commit()
                    except Exception:
                        try:
                            s.rollback()
                        except Exception:
                            pass
                return
            # 수집 API 호출은 "화면을 키워드마다 열지 않는" 것이 핵심이다.
            # - host_cdp(전용 크롬) 세션이 준비되어 있으면, SHOPPING_SEARCH_PAGE에서 fetch(/api/search/all) 우선
            #   (goto 없이 API만 호출, 쿠키/로그인/접속제한 해제 상태를 재사용)
            # - 그 외에는 context.request를 사용
            status_text = None
            body_text = ""
            fetch_via = "ctx_request"
            page_for_fetch = None
            try:
                page_for_fetch = SHOPPING_SEARCH_PAGE
                if page_for_fetch is not None and hasattr(page_for_fetch, "is_closed") and page_for_fetch.is_closed():  # type: ignore[attr-defined]
                    page_for_fetch = None
            except Exception:
                page_for_fetch = None

            if page_for_fetch is not None:
                try:
                    fetch_via = "page_fetch_api"
                    status_text, body_text = _pw_call(
                        lambda: _shopping_api_fetch_page_via_page_fetch(
                            page_for_fetch,
                            keyword=kw0,
                            paging_index=pi,
                            paging_size=page_size,
                            cat_id=cid,
                        ),
                        timeout=90.0,
                    )
                except Exception:
                    status_text, body_text = (None, "")

            if not status_text:
                # fallback: context.request
                def _fetch_once():
                    ctx = _ensure_pw_context()
                    return _shopping_api_fetch_page_via_context_request(
                        ctx,
                        keyword=kw0,
                        paging_index=pi,
                        paging_size=page_size,
                        cat_id=cid,
                    )

                fetch_via = "ctx_request"
                try:
                    status_text, body_text = _pw_call(_fetch_once, timeout=120.0)  # type: ignore[misc]
                except Exception:
                    status_text, body_text = (None, "")

            # 418/403/429 또는 차단 HTML이면: 즉시 중단 + 세션 오픈 힌트 제공
            try:
                st = int(status_text or 0)
            except Exception:
                st = 0
            block_reason = _shopping_block_reason(body_text or "") if body_text else None
            # 418인데 body가 비어있어 reason을 못 잡는 경우가 있어도,
            # 일단 access_limited로 간주해야 HTML(__NEXT_DATA__) 우회 루트가 열린다.
            if st == 418 and not block_reason:
                block_reason = "access_limited"
            blocked = bool(st in (403, 418, 429) or (body_text and _is_shopping_block_html(body_text)))

            # page_fetch_api 우선 적용으로 인해, "blocked -> page_fetch_api 폴백" 단계는 의미가 줄어들었다.
            # 여기서는 힌트만 남기고, 추가로 키워드마다 탭을 여는 동작은 하지 않는다.
            fallback_used = bool(fetch_via == "page_fetch_api")

            # 폴백 2) (옵션) HTML(__NEXT_DATA__) 기반 링크 추출은 "키워드마다 검색 페이지 goto"가 필요해 UX/차단에 불리할 수 있다.
            # - 기본은 비활성화(ENABLE_HTML_SEARCH_FALLBACK=1일 때만 사용)
            links_from_html: list[str] = []
            html_fallback_error: str | None = None
            enable_html_fallback = (os.getenv("ENABLE_HTML_SEARCH_FALLBACK", "") or "").strip().lower() in ("1", "true", "yes", "y", "on")
            if enable_html_fallback and blocked and (block_reason == "access_limited"):
                # 중요: Playwright 객체(page/context)는 worker thread 경계를 넘기면 예외/무응답이 발생할 수 있다.
                # 따라서 "페이지 생성 + goto + __NEXT_DATA__ 파싱"까지 모두 _pw_call 내부에서 수행한다.
                def _collect_links_html() -> list[str]:
                    global SHOPPING_SEARCH_PAGE
                    ctx = _ensure_pw_context()
                    page2 = None
                    try:
                        page2 = SHOPPING_SEARCH_PAGE
                        if page2 is not None and hasattr(page2, "is_closed") and page2.is_closed():  # type: ignore[attr-defined]
                            page2 = None
                    except Exception:
                        page2 = None
                    if page2 is None:
                        page2 = ctx.new_page()
                        try:
                            SHOPPING_SEARCH_PAGE = page2
                        except Exception:
                            pass
                    return _shopping_search_page_collect_links(
                        page2,
                        keyword=kw0,
                        paging_index=pi,
                        paging_size=page_size,
                        cat_id=cid,
                    )

                try:
                    links_from_html = _pw_call(_collect_links_html, timeout=90.0)
                except Exception as e:
                    links_from_html = []
                    try:
                        html_fallback_error = str(e)
                    except Exception:
                        html_fallback_error = "html_fallback_failed"
            if not isinstance(links_from_html, list):
                links_from_html = []

            # HTML 링크 기반으로 랭킹 반영(이 경우 JSON 파싱을 하지 않는다)
            if links_from_html:
                fetch_via = "html_next_data"
                for i, link in enumerate(links_from_html[:page_size]):
                    # HTML 경로는 catalog 링크가 섞일 수 있으므로 /products/<id>만 인정한다.
                    rid = _canonical_product_id(link)
                    if not rid:
                        continue
                    rank = (pi - 1) * page_size + i + 1
                    for u, pid in targets.items():
                        if found_rank_by_url.get(u, 0) > 0:
                            continue
                        if pid == rid:
                            found_rank_by_url[u] = rank
                            found_pid.add(pid)
                # 모두 찾았으면 페이지 루프 종료(요청량 감소)
                if targets and len(found_pid) >= len(set(targets.values())):
                    break
                # 다음 페이지로 진행
                continue

            if blocked:
                # 캡차/차단이 감지되어도 키워드마다 자동 탭 오픈은 하지 않는다.
                # (사용자가 1~3번에서 연 "전용 크롬"에서 직접 해결하고, 필요 시 UI 버튼으로 탭을 열게 한다.)
                session_hint = None

                with SessionLocal() as s:
                    try:
                        s.query(AnalyticsJobRun).filter(
                            AnalyticsJobRun.job_name == job_name,
                            AnalyticsJobRun.run_date == target_date,
                        ).update(
                            {
                                "status": "FAILED",
                                "finished_at": datetime.utcnow(),
                                "detail": json.dumps(
                                    {
                                        "job_id": job_id,
                                        "error": "captcha_or_blocked",
                                        "http_status": st or None,
                                        "blockReason": block_reason,
                                        "keyword": kw0,
                                        "fallbackUsed": bool(fallback_used),
                                        "fetchVia": fetch_via,
                                        "htmlFallbackError": html_fallback_error,
                                        "session": session_hint,
                                        "hint": "접속 제한/캡차가 감지되었습니다. 모달의 1~3번 단계(전용 크롬)에서 로그인/보안확인을 끝내고, 필요 시 '쇼핑 검색 탭 열기(호스트 크롬)'로 1회 세션을 열어둔 뒤 다시 수집을 실행하세요.",
                                    },
                                    ensure_ascii=False,
                                ),
                            },
                            synchronize_session=False,
                        )
                        s.commit()
                    except Exception:
                        try:
                            s.rollback()
                        except Exception:
                            pass
                return

            data = None
            try:
                data = json.loads(body_text) if body_text else None
            except Exception:
                data = None
            if not data:
                continue

            ranked_ids = _extract_ranked_product_ids_from_shopping_api_response(data)
            if not ranked_ids:
                continue

            # 이 페이지에서 찾은 랭크 반영
            for i, rid in enumerate(ranked_ids[:page_size]):
                if not rid:
                    continue
                rank = (pi - 1) * page_size + i + 1
                for u, pid in targets.items():
                    if found_rank_by_url.get(u, 0) > 0:
                        continue
                    if pid == rid:
                        found_rank_by_url[u] = rank
                        found_pid.add(pid)

            # 모두 찾았으면 페이지 루프 종료(요청량 감소)
            if targets and len(found_pid) >= len(set(targets.values())):
                break

        # 4) 저장 (tracked_product_rank_daily upsert, source=crawl_category)
        with SessionLocal() as s:
            try:
                for u in product_urls:
                    rnk = int(found_rank_by_url.get(u, 0) or 0)
                    existing = s.get(TrackedProductRankDaily, (target_date, u, kw0))
                    if existing is not None and str(getattr(existing, "source", "") or "").lower() in {"excel", "text"}:
                        continue
                    row = TrackedProductRankDaily(
                        date=target_date,
                        product_url=u,
                        keyword=kw0,
                        rank=rnk,
                        source="crawl_category",
                    )
                    s.merge(row)
                    saved += 1
                s.commit()
            except Exception:
                try:
                    s.rollback()
                except Exception:
                    pass

        # progress update (best-effort)
        with SessionLocal() as s:
            try:
                s.query(AnalyticsJobRun).filter(
                    AnalyticsJobRun.job_name == job_name,
                    AnalyticsJobRun.run_date == target_date,
                ).update(
                    {
                        "detail": json.dumps(
                            {
                                "job_id": job_id,
                                "keyword_index": idx_kw + 1,
                                "keywords_total": len(keywords),
                                "saved_cells": saved,
                                "category_id": cid,
                                "category_path": category_path,
                            },
                            ensure_ascii=False,
                        )
                    },
                    synchronize_session=False,
                )
                s.commit()
            except Exception:
                try:
                    s.rollback()
                except Exception:
                    pass

    # 5) finish
    if _is_category_crawl_cancelled(job_id):
        with SessionLocal() as s:
            try:
                s.query(AnalyticsJobRun).filter(
                    AnalyticsJobRun.job_name == job_name,
                    AnalyticsJobRun.run_date == target_date,
                ).update(
                    {
                        "status": "CANCELLED",
                        "finished_at": datetime.utcnow(),
                        "detail": json.dumps(
                            {"job_id": job_id, "saved_cells": saved, "cancelled": True},
                            ensure_ascii=False,
                        ),
                    },
                    synchronize_session=False,
                )
                s.commit()
            except Exception:
                try:
                    s.rollback()
                except Exception:
                    pass
        return
    with SessionLocal() as s:
        try:
            s.query(AnalyticsJobRun).filter(
                AnalyticsJobRun.job_name == job_name,
                AnalyticsJobRun.run_date == target_date,
            ).update(
                {
                    "status": "SUCCESS",
                    "finished_at": datetime.utcnow(),
                    "detail": json.dumps(
                        {
                            "job_id": job_id,
                            "saved_cells": saved,
                            "products": len(product_urls),
                            "keywords": len(keywords),
                            "category_id": cid,
                            "category_path": category_path,
                        },
                        ensure_ascii=False,
                    ),
                },
                synchronize_session=False,
            )
            s.commit()
        except Exception:
            try:
                s.rollback()
            except Exception:
                pass


def _openapi_fetch_shop_items(
    *,
    keyword: str,
    start: int,
    display: int,
    client_id: str | None = None,
    client_secret: str | None = None,
) -> tuple[int | None, list[dict]]:
    """
    네이버 쇼핑 검색 OpenAPI(shop.json)를 호출해 items를 가져온다.
    - client_id/secret을 넘기면 그대로 사용(워커 스레드에서 캐시 의존 제거).
    - 반환: (http_status, items)
    """
    q = (keyword or "").strip()
    if not q:
        return (None, [])

    if not client_id or not client_secret:
        client_id = client_id or _first_nonempty(["NAVER_SEARCH_CLIENT_ID", "NAVER_KEY", "NAVER_CLIENT_ID"])
        client_secret = client_secret or _first_nonempty(["NAVER_SEARCH_CLIENT_SECRET", "NAVER_SECRET", "NAVER_CLIENT_SECRET"])
    if not client_id or not client_secret:
        return (None, [])

    st = int(start or 1)
    dp = int(display or 40)
    if st < 1:
        st = 1
    # 네이버 OpenAPI 제약: display<=100, start<=1000
    if dp < 1:
        dp = 40
    dp = max(1, min(100, dp))
    st = max(1, min(1000, st))

    # 재시도/백오프 설정(429 완화 + 일시 네트워크 오류 회복)
    # - 운영에서는 "PARTIAL 없이 끝까지" 수집하는 것이 중요하므로, 429는 짧은 백오프로 몇 번 재시도한다.
    # - 기본값은 보수적으로 두되, OPENAPI_RANK_DELAY_* 를 낮출 때 이 재시도가 안전장치 역할을 한다.
    try:
        retry_max = int(os.getenv("OPENAPI_RANK_RETRY_MAX", "4"))
    except Exception:
        retry_max = 4
    retry_max = max(1, min(8, retry_max))
    try:
        retry_base_sec = float(os.getenv("OPENAPI_RANK_RETRY_BASE_SEC", "0.35"))
    except Exception:
        retry_base_sec = 0.35
    try:
        retry_max_sec = float(os.getenv("OPENAPI_RANK_RETRY_MAX_SEC", "6.0"))
    except Exception:
        retry_max_sec = 6.0
    retry_base_sec = max(0.0, min(30.0, retry_base_sec))
    retry_max_sec = max(retry_base_sec, min(60.0, retry_max_sec))

    # NOTE: 실제 HTTP 호출은 module-level _openapi_http_get로만 수행한다.
    # - 테스트에서 patch가 가능해야 하며, keep-alive(Session) 재사용도 한 곳에서 관리해야 한다.

    last_status: int | None = None
    for attempt in range(1, retry_max + 1):
        try:
            resp = _openapi_http_get(
                NAVER_SHOP_ENDPOINT,
                params={"query": q, "display": dp, "start": st, "sort": "sim"},
                headers={"X-Naver-Client-Id": client_id, "X-Naver-Client-Secret": client_secret},
                timeout=6,
            )
            last_status = int(getattr(resp, "status_code", None) or 0) or None
        except Exception:
            last_status = None
            resp = None  # type: ignore[assignment]

        # 성공
        if resp is not None and last_status is not None and last_status < 400:
            try:
                data = resp.json() or {}
                items = data.get("items") or []
                if not isinstance(items, list):
                    items = []
                items2: list[dict] = []
                for it in items:
                    if isinstance(it, dict):
                        items2.append(it)
                return (last_status, items2)
            except Exception:
                # JSON 파싱 실패는 일시적일 수 있어 재시도 대상으로 둔다.
                pass

        # 재시도 대상: 429, 5xx, 네트워크/타임아웃(None)
        should_retry = (last_status is None) or (last_status == 429) or (last_status >= 500)
        if (not should_retry) or (attempt >= retry_max):
            return (last_status, [])

        # Retry-After(초) 존중 (없으면 지수 백오프 + jitter)
        ra_sec = None
        try:
            if resp is not None and hasattr(resp, "headers"):
                ra = resp.headers.get("Retry-After")  # type: ignore[union-attr]
                if ra is not None:
                    ra_sec = float(str(ra).strip())
        except Exception:
            ra_sec = None

        backoff = retry_base_sec * (2 ** (attempt - 1))
        backoff = min(retry_max_sec, backoff)
        if ra_sec is not None and ra_sec > 0:
            backoff = max(backoff, min(60.0, ra_sec))
        # jitter: +/- 20%
        jitter = backoff * (0.8 + random.random() * 0.4)
        try:
            time.sleep(jitter)
        except Exception:
            pass

    # 여기는 도달하지 않지만, 타입 안정성을 위해 fallback 반환
    return (last_status, [])


# ---- OpenAPI HTTP wrapper (testable + keep-alive) ----
_OPENAPI_HTTP_SESSION = None


def _openapi_http_get(url: str, *, params: dict, headers: dict, timeout: int):
    """
    OpenAPI HTTP GET 래퍼(테스트/운영 공용).
    - keep-alive(Session) 재사용
    - 테스트에서는 이 함수를 patch해서 네트워크 없이 동작을 고정한다.
    """
    global _OPENAPI_HTTP_SESSION
    if _OPENAPI_HTTP_SESSION is None:
        try:
            _OPENAPI_HTTP_SESSION = requests.Session()
        except Exception:
            _OPENAPI_HTTP_SESSION = None
    getter = (_OPENAPI_HTTP_SESSION.get if _OPENAPI_HTTP_SESSION is not None else requests.get)
    return getter(url, params=params, headers=headers, timeout=timeout)


def _openapi_fetch_rank_for_one_keyword(
    kw0: str,
    product_urls: list[str],
    smart_to_urls: dict[str, list[str]],
    catalog_to_urls: dict[str, list[str]],
    max_rank: int,
    client_id: str = "",
    client_secret: str = "",
) -> tuple[str, dict[str, int], bool, int | None]:
    """
    단일 키워드에 대해 OpenAPI로 순위만 조회·매칭한다. DB/세션 사용 없음(병렬 실행용).
    client_id/secret을 넘기면 워커에서 캐시를 읽지 않고 사용해 saved_cells=0 방지.
    반환: (kw0, found_rank_by_url, had_openapi_error, last_http_status)
    """
    found_rank_by_url: dict[str, int] = {u: 0 for u in product_urls}
    had_openapi_error = False
    last_http_status: int | None = None
    start = 1
    remaining = max_rank
    cid = (client_id or "").strip()
    csec = (client_secret or "").strip()
    while remaining > 0 and start <= 1000:
        display = min(100, remaining)
        http_status, items = _openapi_fetch_shop_items(
            keyword=kw0, start=start, display=display,
            client_id=cid or None, client_secret=csec or None,
        )
        last_http_status = int(http_status) if http_status is not None else None
        if http_status is None or int(http_status) >= 400:
            had_openapi_error = True
            break
        if not items:
            break
        for i, item in enumerate(items):
            link = str(item.get("link") or "").strip()
            rid = _extract_product_id_from_url(link)
            item_catalog_id = None
            try:
                raw_pid = item.get("productId")
                if raw_pid is not None:
                    item_catalog_id = str(raw_pid).strip()
            except Exception:
                item_catalog_id = None
            rank = start + i
            matched_any = False
            if rid:
                rid_s = str(rid)
                for u in smart_to_urls.get(rid_s, []) or []:
                    if found_rank_by_url.get(u, 0) > 0:
                        continue
                    found_rank_by_url[u] = int(rank)
                    matched_any = True
            if item_catalog_id:
                for u in catalog_to_urls.get(item_catalog_id, []) or []:
                    if found_rank_by_url.get(u, 0) > 0:
                        continue
                    found_rank_by_url[u] = int(rank)
                    matched_any = True
            all_done = all((found_rank_by_url.get(u, 0) or 0) > 0 for u in product_urls)
            if all_done:
                break
        all_done2 = all((found_rank_by_url.get(u, 0) or 0) > 0 for u in product_urls)
        if all_done2:
            break
        remaining -= display
        start += display
        # 호출 간격: 네이버 문서에는 초당 제한 미명시. 기본 10~30ms(기존 30~80ms의 1/3, 페이징 시에만).
        # 체감 "1.2초에 한 번"은 키워드당 1사이클(API RTT + DB 저장) 때문. 0.4초 이하면 여유 있음.
        delay_min = max(0.0, min(1.0, float(os.getenv("OPENAPI_RANK_DELAY_MIN", "0.01"))))
        delay_max = max(delay_min, min(1.0, float(os.getenv("OPENAPI_RANK_DELAY_MAX", "0.03"))))
        try:
            time.sleep(random.uniform(delay_min, delay_max))
        except Exception:
            pass
    return (kw0, found_rank_by_url, had_openapi_error, last_http_status)


def _write_keyword_result_impl(
    kw0: str,
    found_rank_by_url: dict[str, int],
    had_openapi_error: bool,
    product_urls: list[str],
    target_date: date,
    source: str = "openapi",
) -> int:
    """키워드별 순위 결과를 DB에 저장. product_urls/ target_date를 인자로 받아 배치·단일 job 공용."""
    kw = str(kw0 or "").strip()
    if not kw:
        return 0
    # NOTE(성능):
    # - merge per-row는 키워드 수가 많을 때 병목이 되기 쉽다.
    # - tracked_product_rank_daily는 (date, product_url, keyword) 복합 PK라
    #   INSERT .. ON CONFLICT DO UPDATE(upsert)로 대체 가능.
    rows: list[dict] = []
    for u in product_urls:
        url = str(u or "").strip()
        if not url:
            continue
        rnk = int(found_rank_by_url.get(url, 0) or 0)
        # 구조적 재발 방지:
        # - OpenAPI 실패(had_openapi_error)면 "0(미발견)"는 저장하지 않는다.
        if had_openapi_error and rnk <= 0:
            continue
        rows.append(
            {
                "date": target_date,
                "product_url": url,
                "keyword": kw,
                "rank": int(rnk),
                "source": str(source or "openapi").strip() or "openapi",
                "updated_at": datetime.utcnow(),
            }
        )
    if not rows:
        return 0

    # Postgres는 같은 statement 내 동일 PK 중복이 있으면 실패할 수 있어, 방어적으로 dedupe 한다.
    dedup: dict[tuple, dict] = {}
    for r in rows:
        key = (r.get("date"), r.get("product_url"), r.get("keyword"))
        dedup[key] = r
    rows2 = list(dedup.values())

    with SessionLocal() as s:
        try:
            stmt = insert(TrackedProductRankDaily).values(rows2)
            upsert_stmt = stmt.on_conflict_do_update(
                index_elements=[
                    TrackedProductRankDaily.date,
                    TrackedProductRankDaily.product_url,
                    TrackedProductRankDaily.keyword,
                ],
                set_={
                    "rank": stmt.excluded.rank,
                    "source": stmt.excluded.source,
                    "updated_at": stmt.excluded.updated_at,
                },
                # Manual/official inputs are authoritative. Background OpenAPI
                # collection may fill blanks, but must never replace uploaded ranks.
                where=TrackedProductRankDaily.source.notin_(["excel", "text"]),
            )
            s.execute(upsert_stmt)
            s.commit()
            return len(rows2)
        except Exception as e:
            try:
                s.rollback()
            except Exception:
                pass
            print(f"[openapi-rank-job] write_keyword_result failed keyword={kw0!r} err={e!r}", flush=True)
            return 0


SHOPPING_RANK_HOME_URL = "https://search.shopping.naver.com/"
NAVER_MOBILE_RANK_HOME_URL = "https://msearch.shopping.naver.com/search"
SHOPPING_RANK_MOBILE_CDP_SOURCE = "naver_msearch_lexical_product_top40"


def _shopping_rank_text(value: object) -> str:
    return re.sub(r"\s+", " ", str(value or "")).strip()


def _shopping_rank_pick(d: dict, keys: list[str]) -> str:
    for key in keys:
        try:
            v = d.get(key)
        except Exception:
            v = None
        s = _shopping_rank_text(v)
        if s:
            return s
    return ""


def _shopping_rank_extract_product_items(payload: object, *, limit: int = 1200) -> list[dict]:
    """
    Naver Shopping result JSON/DOM-like objects에서 상품 후보를 순서대로 추출한다.

    공식 shop.json 종료 이후에는 search.shopping.naver.com 화면의 Network 응답 구조가
    고정 API 계약이 아니므로, 특정 JSON path에만 의존하지 않고 productId/link/title
    신호를 가진 dict를 재귀적으로 수집한다.
    """
    out: list[dict] = []
    seen: set[str] = set()

    def add_item(raw: dict) -> None:
        if len(out) >= limit:
            return
        title = _shopping_rank_pick(raw, ["productTitle", "title", "name", "itemName", "productName"])
        link = _shopping_rank_pick(raw, ["link", "productUrl", "url", "crUrl", "mallProductUrl", "adcrUrl"])
        product_id = _shopping_rank_pick(raw, ["productId", "nvMid", "id", "catalogId"])
        mall_product_id = _shopping_rank_pick(raw, ["mallProductId", "channelProductNo", "smartstoreProductId"])
        mall_name = _shopping_rank_pick(raw, ["mallName", "channelName", "storeName", "mall"])
        image_url = _shopping_rank_pick(raw, ["imageUrl", "image", "thumbnail", "thumbnailUrl"])
        ad_id = _shopping_rank_pick(raw, ["adId"])
        ad_type = _shopping_rank_pick(raw, ["adType"])
        ad_product_name = _shopping_rank_pick(raw, ["adProductName"])
        adsr_type_cd = _shopping_rank_pick(raw, ["adsrTypeCd"])
        if not (title or link or product_id or mall_product_id):
            return
        # 검색 결과가 아닌 광고/배너/필터 dict 오탐을 줄인다.
        if not (link or product_id or mall_product_id):
            return
        key = "|".join([product_id, mall_product_id, link, title])[:500]
        if key in seen:
            return
        seen.add(key)
        out.append(
            {
                "title": title,
                "link": link,
                "productId": product_id,
                "mallProductId": mall_product_id,
                "mallName": mall_name,
                "imageUrl": image_url,
                "adId": ad_id,
                "adType": ad_type,
                "adProductName": ad_product_name,
                "adsrTypeCd": adsr_type_cd,
            }
        )

    def walk(obj: object, depth: int = 0) -> None:
        if len(out) >= limit or depth > 12:
            return
        if isinstance(obj, dict):
            keys = set(obj.keys())
            productish = bool(
                keys.intersection({"productId", "mallProductId", "nvMid", "catalogId", "channelProductNo"})
                or (keys.intersection({"productTitle", "productName", "title", "name"}) and keys.intersection({"link", "url", "productUrl", "crUrl"}))
            )
            if productish:
                add_item(obj)
            for v in obj.values():
                walk(v, depth + 1)
        elif isinstance(obj, list):
            for v in obj:
                walk(v, depth + 1)
                if len(out) >= limit:
                    break

    def walk_composite(obj: object, depth: int = 0) -> None:
        if len(out) >= limit or depth > 12:
            return
        if isinstance(obj, dict):
            composite = obj.get("compositeList")
            if isinstance(composite, dict):
                rows = composite.get("list")
                if isinstance(rows, list):
                    for row in rows:
                        raw = row.get("item") if isinstance(row, dict) else row
                        if isinstance(raw, dict):
                            add_item(raw)
                        if len(out) >= limit:
                            return
            for v in obj.values():
                walk_composite(v, depth + 1)
                if len(out) >= limit:
                    return
        elif isinstance(obj, list):
            for v in obj:
                walk_composite(v, depth + 1)
                if len(out) >= limit:
                    return

    # Naver Shopping의 실제 상품 카드 순서는 compositeList.list[*].item 이 기준이다.
    # lowMallList/purchaseConditionInfos 같은 하위 객체를 rank 후보로 세면 순위가 왜곡된다.
    walk_composite(payload)
    if out:
        return out[:limit]
    walk(payload)
    return out[:limit]


def _compact_rank_match_text(value: object) -> str:
    return re.sub(r"[^0-9A-Za-z가-힣]+", "", str(value or "").lower())


def _rank_package_count(value: object) -> int | None:
    compact = _compact_rank_match_text(value)
    for m in re.finditer(r"(\d+)(?:개|팩|pack|p)", compact, flags=re.IGNORECASE):
        try:
            n = int(m.group(1))
        except Exception:
            continue
        if 1 <= n <= 99:
            return n
    return None


def _rank_alias_matches_text(alias: object, text: object) -> bool:
    alias_compact = _compact_rank_match_text(alias)
    text_compact = _compact_rank_match_text(text)
    return bool(len(alias_compact) >= 10 and alias_compact in text_compact)


def _shopping_rank_is_ad_item(item: dict | None) -> bool:
    if not isinstance(item, dict):
        return False
    for key in ("adId", "adType", "adProductName", "adsrTypeCd"):
        value = item.get(key)
        if value is not None and str(value).strip():
            return True
    return False


def _shopping_rank_is_blocked_text(value: object) -> bool:
    text = str(value or "").lower()
    return any(
        token in text
        for token in [
            "쇼핑 서비스 접속이 일시적으로 제한",
            "비정상적인 접근",
            "너무 많은 요청",
            "접속이 제한",
            "captcha",
            "자동입력",
        ]
    )


def _shopping_rank_is_blocked_error(value: object) -> bool:
    text = str(value or "").lower()
    return any(token in text for token in ["captcha", "security", "blocked", "rate_limited", "access_limited", "접속"])


def _shopping_rank_match_items(
    *,
    items: list[dict],
    product_urls: list[str],
    smart_to_urls: dict[str, list[str]],
    catalog_to_urls: dict[str, list[str]],
    aliases_by_url: dict[str, list[str]] | None = None,
    max_rank: int,
) -> dict[str, int]:
    found: dict[str, int] = {u: 0 for u in product_urls}
    url_bases = {u: _canonicalize_smartstore_base_url(u) for u in product_urls}
    seen_item: set[str] = set()
    rank = 0
    for item in items or []:
        if rank >= max_rank:
            break
        if _shopping_rank_is_ad_item(item):
            continue
        link = _shopping_rank_text(item.get("link"))
        title = _shopping_rank_text(item.get("title"))
        product_id = _shopping_rank_text(item.get("productId"))
        mall_product_id = _shopping_rank_text(item.get("mallProductId"))
        rid = _extract_product_id_from_url(link)
        stable_key_parts = [product_id, mall_product_id, str(rid or ""), link]
        item_key = "|".join([x for x in stable_key_parts if str(x or "").strip()])[:500]
        if not item_key:
            item_key = title[:500]
        if item_key in seen_item:
            continue
        seen_item.add(item_key)
        rank += 1

        id_candidates = [str(x).strip() for x in [rid, product_id, mall_product_id] if str(x or "").strip()]
        for pid in id_candidates:
            for u in smart_to_urls.get(pid, []) or []:
                if found.get(u, 0) <= 0:
                    found[u] = int(rank)
            for u in catalog_to_urls.get(pid, []) or []:
                if found.get(u, 0) <= 0:
                    found[u] = int(rank)

        if link:
            link_base = _canonicalize_smartstore_base_url(link)
            for u, base in url_bases.items():
                if found.get(u, 0) > 0:
                    continue
                if base and (base == link_base or base in link or base.replace("https://", "") in link):
                    found[u] = int(rank)

        # 상품명 fallback은 유사 상품(예: 1개/2개/5개/11개 패키지)을 섞는 원인이 된다.
        # 기준은 명확하다: 상위 수집 범위 안에서 상품 ID/URL로 확인되지 않으면 미노출(rank=0)이다.

        if all((found.get(u, 0) or 0) > 0 for u in product_urls):
            break
    return found


def _shopping_rank_dom_items(page, *, limit: int = 1200) -> list[dict]:
    try:
        rows = page.evaluate(
            """
            (limit) => {
              const seen = new Set();
              const out = [];
              const anchors = Array.from(document.querySelectorAll('a[href*="/products/"], a[href*="/catalog/"], a[href*="smartstore.naver.com"]'));
              for (const a of anchors) {
                if (out.length >= limit) break;
                const href = String(a.href || a.getAttribute('href') || '').trim();
                if (!href) continue;
                let cursor = a;
                let root = a;
                let bestText = String(a.innerText || '').replace(/\s+/g, ' ').trim();
                for (let i = 0; i < 9 && cursor; i += 1) {
                  const txt = String(cursor.innerText || '').replace(/\s+/g, ' ').trim();
                  if (txt && txt.length > bestText.length && txt.length < 1200) {
                    bestText = txt;
                    root = cursor;
                  }
                  cursor = cursor.parentElement;
                }
                const img = root ? root.querySelector('img') : null;
                const imageUrl = img ? String(img.src || img.getAttribute('src') || '').trim() : '';
                const key = href + '|' + bestText.slice(0, 120);
                if (seen.has(key)) continue;
                seen.add(key);
                out.push({ link: href, title: bestText.slice(0, 500), imageUrl });
              }
              return out;
            }
            """,
            int(limit),
        )
        if isinstance(rows, list):
            return [r for r in rows if isinstance(r, dict)]
    except Exception:
        pass
    return []


def _shopping_rank_page_json_items(page, *, limit: int = 1200) -> list[dict]:
    try:
        rows = page.evaluate(
            """
            (limit) => {
              const out = [];
              const seen = new Set();
              const pick = (obj, keys) => {
                for (const k of keys) {
                  const v = obj && obj[k];
                  if (v !== undefined && v !== null && String(v).trim()) return String(v).trim();
                }
                return '';
              };
              const add = (raw) => {
                if (!raw || typeof raw !== 'object' || out.length >= limit) return;
                const title = pick(raw, ['productTitle', 'title', 'name', 'itemName', 'productName']);
                const link = pick(raw, ['link', 'productUrl', 'url', 'crUrl', 'mallProductUrl', 'adcrUrl']);
                const productId = pick(raw, ['productId', 'nvMid', 'id', 'catalogId']);
                const mallProductId = pick(raw, ['mallProductId', 'channelProductNo', 'smartstoreProductId']);
                const mallName = pick(raw, ['mallName', 'channelName', 'storeName', 'mall']);
                const imageUrl = pick(raw, ['imageUrl', 'image', 'thumbnail', 'thumbnailUrl']);
                const adId = pick(raw, ['adId']);
                const adType = pick(raw, ['adType']);
                const adProductName = pick(raw, ['adProductName']);
                const adsrTypeCd = pick(raw, ['adsrTypeCd']);
                if (!(title || link || productId || mallProductId)) return;
                if (!(link || productId || mallProductId)) return;
                const key = [productId, mallProductId, link, title].filter(Boolean).join('|').slice(0, 500);
                if (!key || seen.has(key)) return;
                seen.add(key);
                out.push({ title, link, productId, mallProductId, mallName, imageUrl, adId, adType, adProductName, adsrTypeCd });
              };
              const walk = (obj, depth = 0) => {
                if (!obj || out.length >= limit || depth > 16) return;
                if (Array.isArray(obj)) {
                  for (const v of obj) {
                    walk(v, depth + 1);
                    if (out.length >= limit) break;
                  }
                  return;
                }
                if (typeof obj !== 'object') return;
                const keys = Object.keys(obj);
                const productish = keys.some((k) => ['productId', 'mallProductId', 'nvMid', 'catalogId', 'channelProductNo', 'smartstoreProductId'].includes(k))
                  || (keys.some((k) => ['productTitle', 'productName', 'title', 'name'].includes(k)) && keys.some((k) => ['link', 'url', 'productUrl', 'crUrl', 'mallProductUrl'].includes(k)));
                if (productish) add(obj);
                for (const v of Object.values(obj)) {
                  walk(v, depth + 1);
                  if (out.length >= limit) break;
                }
              };
              const walkComposite = (obj, depth = 0) => {
                if (!obj || out.length >= limit || depth > 16) return;
                if (Array.isArray(obj)) {
                  for (const v of obj) {
                    walkComposite(v, depth + 1);
                    if (out.length >= limit) break;
                  }
                  return;
                }
                if (typeof obj !== 'object') return;
                const rows = obj.compositeList && Array.isArray(obj.compositeList.list) ? obj.compositeList.list : null;
                if (rows) {
                  for (const row of rows) {
                    const raw = row && typeof row === 'object' && row.item ? row.item : row;
                    add(raw);
                    if (out.length >= limit) break;
                  }
                }
                for (const v of Object.values(obj)) {
                  walkComposite(v, depth + 1);
                  if (out.length >= limit) break;
                }
              };
              const scripts = Array.from(document.querySelectorAll('script#__NEXT_DATA__, script[type="application/json"]'));
              for (const s of scripts) {
                const text = String(s.textContent || '').trim();
                if (!text || text.length < 20) continue;
                try {
                  const data = JSON.parse(text);
                  walkComposite(data, 0);
                  if (out.length <= 0) walk(data, 0);
                } catch (_) {}
                if (out.length >= limit) break;
              }
              return out.slice(0, limit);
            }
            """,
            int(limit),
        )
        if isinstance(rows, list):
            return [r for r in rows if isinstance(r, dict)]
    except Exception:
        pass
    return []


def _shopping_cdp_fetch_rank_for_one_keyword(
    kw0: str,
    product_urls: list[str],
    smart_to_urls: dict[str, list[str]],
    catalog_to_urls: dict[str, list[str]],
    max_rank: int,
    aliases_by_url: dict[str, list[str]] | None = None,
) -> tuple[str, dict[str, int], bool, str | None]:
    """
    네이버 쇼핑 홈에서 실제 검색창 입력 방식으로 검색하고, Network 응답/DOM에서 순위를 추출한다.
    반환 형태는 기존 OpenAPI fetch 함수와 유사하게 맞춘다.
    """
    kw = str(kw0 or "").strip()
    found: dict[str, int] = {u: 0 for u in product_urls}
    if not kw:
        return (kw0, found, True, "empty_keyword")
    if not _playwright_enabled():
        return (kw0, found, True, "playwright_disabled")

    captured: list[dict] = []

    def on_response(resp) -> None:
        try:
            if len(captured) >= max(300, max_rank * 2):
                return
            url = str(getattr(resp, "url", "") or "")
            if "search.shopping.naver.com" not in url:
                return
            status = int(getattr(resp, "status", 0) or 0)
            if status >= 400:
                return
            ctype = ""
            try:
                ctype = str((getattr(resp, "headers", {}) or {}).get("content-type") or "")
            except Exception:
                ctype = ""
            if "json" not in ctype.lower() and "/api/" not in url and "search" not in url:
                return
            data = resp.json()
            items = _shopping_rank_extract_product_items(data, limit=max(300, max_rank * 2))
            if items:
                captured.extend(items)
        except Exception:
            return

    try:
        context = _ensure_pw_context()
        pages = list(getattr(context, "pages", []) or [])
        page = None
        for p in pages:
            try:
                if "search.shopping.naver.com" in str(getattr(p, "url", "") or ""):
                    page = p
                    break
            except Exception:
                continue
        if page is None:
            page = context.new_page()

        try:
            page.on("response", on_response)
        except Exception:
            pass

        try:
            cur = str(getattr(page, "url", "") or "")
            if "search.shopping.naver.com" not in cur:
                page.goto(SHOPPING_RANK_HOME_URL, wait_until="domcontentloaded", timeout=25000)
        except Exception:
            page.goto(SHOPPING_RANK_HOME_URL, wait_until="domcontentloaded", timeout=25000)

        input_selectors = [
            'input[placeholder*="상품명"]',
            'input[placeholder*="브랜드"]',
            'input[placeholder*="입력"]',
            'input[type="search"]',
            'input[name="query"]',
            'input',
        ]
        search_input = None
        for sel in input_selectors:
            try:
                loc = page.locator(sel).first
                if loc.count() > 0:
                    search_input = loc
                    break
            except Exception:
                continue
        if search_input is not None:
            try:
                search_input.click(timeout=7000)
                page.keyboard.press("Control+A")
                page.keyboard.type(kw, delay=random.randint(35, 90))
                page.keyboard.press("Enter")
            except Exception:
                try:
                    search_input.fill(kw, timeout=7000)
                    search_input.press("Enter", timeout=7000)
                except Exception:
                    search_input = None

        if search_input is None:
            try:
                search_url = "https://search.shopping.naver.com/search/all?" + urllib.parse.urlencode({"query": kw})
                page.goto(search_url, wait_until="domcontentloaded", timeout=25000)
            except Exception as e:
                return (kw0, found, True, f"shopping_search_submit_failed:{type(e).__name__}")

        try:
            page.wait_for_load_state("domcontentloaded", timeout=15000)
        except Exception:
            pass
        try:
            page.wait_for_timeout(random.randint(1200, 2200))
        except Exception:
            pass
        try:
            body_probe = str(page.locator("body").inner_text(timeout=3000) or "")[:1200]
            if _shopping_rank_is_blocked_text(body_probe):
                return (kw0, found, True, "shopping_access_limited")
        except Exception:
            pass

        merged_items: list[dict] = []
        for _ in range(0, 10):
            page_json_items = _shopping_rank_page_json_items(page, limit=max(300, max_rank * 2))
            if page_json_items:
                merged_items.extend(page_json_items)
            dom_items = _shopping_rank_dom_items(page, limit=max(300, max_rank * 2))
            if dom_items:
                merged_items.extend(dom_items)
            # DOM is the source of rank order. Network payloads are useful only as
            # fallback because recursive JSON extraction can include recommendations,
            # filters, and duplicated product-like objects before real result items.
            if captured:
                merged_items.extend(captured)
            try:
                body_probe = str(page.locator("body").inner_text(timeout=1500) or "")[:1200]
                if _shopping_rank_is_blocked_text(body_probe):
                    return (kw0, found, True, "shopping_access_limited")
            except Exception:
                pass
            found = _shopping_rank_match_items(
                items=merged_items,
                product_urls=product_urls,
                smart_to_urls=smart_to_urls,
                catalog_to_urls=catalog_to_urls,
                aliases_by_url=aliases_by_url,
                max_rank=max_rank,
            )
            if all((found.get(u, 0) or 0) > 0 for u in product_urls):
                break
            if len(merged_items) >= max_rank:
                break
            try:
                page.evaluate("() => window.scrollBy(0, Math.max(700, window.innerHeight * 1.4))")
                page.wait_for_timeout(random.randint(700, 1400))
            except Exception:
                break

        if not merged_items:
            body_text = ""
            try:
                body_text = str(page.locator("body").inner_text(timeout=3000) or "")[:500]
            except Exception:
                body_text = ""
            if _shopping_rank_is_blocked_text(body_text):
                return (kw0, found, True, "shopping_captcha_or_security_page")
            return (kw0, found, True, "shopping_result_items_empty")
        return (kw0, found, False, None)
    except Exception as e:
        return (kw0, found, True, f"shopping_cdp_error:{type(e).__name__}:{str(e)[:160]}")
    finally:
        try:
            page.remove_listener("response", on_response)  # type: ignore[name-defined]
        except Exception:
            pass


def _sql_base_url_expr(field):
    """
    DB 컬럼(field)에서 query/hash를 제거한 "base URL"을 계산하는 SQL expression.
    - _smartstore_product_url_filters 와 같은 정책을 공유해, 변형 URL(쿼리/해시)도 안전하게 매칭한다.
    """
    try:
        dialect = str(getattr(engine, "dialect", None).name or "").lower()
    except Exception:
        dialect = ""
    if "postgres" in dialect:
        base = func.split_part(field, "?", 1)
        base = func.split_part(base, "#", 1)
        return base
    if "sqlite" in dialect:
        pos_q = func.instr(field, "?")
        base_q = case((pos_q > 0, func.substr(field, 1, pos_q - 1)), else_=field)
        pos_h = func.instr(base_q, "#")
        base = case((pos_h > 0, func.substr(base_q, 1, pos_h - 1)), else_=base_q)
        return base
    return field


def _prefetch_catalog_id_by_url(product_urls: list[str]) -> dict[str, str]:
    """
    TrackedProductMeta.product_id_catalog 을 product_url 변형(쿼리/해시/스킴 유무)까지 포함해 한 번에 조회한다.

    목적(성능):
    - batch-by-keyword 수집에서 키워드마다 _build_product_id_maps()를 호출하면,
      동일 상품 URL에 대한 메타 조회가 수백~수천 번 반복될 수 있다.
    - 이 함수는 "전체 URL 셋"을 1회 쿼리로 프리페치하여 반복 조회를 제거한다.
    """
    urls_in: list[str] = []
    bases: list[str] = []
    for u in product_urls or []:
        raw = str(u or "").strip()
        if not raw:
            continue
        urls_in.append(raw)
        b = _canonicalize_smartstore_base_url(raw)
        if b:
            bases.append(b)
    urls_in = list(dict.fromkeys(urls_in))
    bases = list(dict.fromkeys(bases))
    if not urls_in and not bases:
        return {}

    field = TrackedProductMeta.product_url
    base_expr = _sql_base_url_expr(field)
    conds = []
    if urls_in:
        conds.append(field.in_(urls_in))
    if bases:
        conds.append(base_expr.in_(bases))
    if not conds:
        return {}

    base_to_pid: dict[str, str] = {}
    direct_to_pid: dict[str, str] = {}
    with SessionLocal() as s:
        try:
            rows = (
                s.query(TrackedProductMeta.product_url, TrackedProductMeta.product_id_catalog)
                .filter(or_(*conds))
                .all()
            )
        except Exception:
            rows = []

    for pu, pid in rows or []:
        u0 = str(pu or "").strip()
        if not u0:
            continue
        if pid is None:
            continue
        pid_s = str(pid).strip()
        if not pid_s:
            continue
        direct_to_pid[u0] = pid_s
        b0 = _canonicalize_smartstore_base_url(u0)
        if b0:
            base_to_pid[b0] = pid_s

    out: dict[str, str] = {}
    for u in urls_in:
        b = _canonicalize_smartstore_base_url(u)
        if b and b in base_to_pid:
            out[u] = base_to_pid[b]
            continue
        if u in direct_to_pid:
            out[u] = direct_to_pid[u]
            continue
        # 스킴 없는 입력("smartstore.naver.com/...")을 https로 보정한 경우도 매칭
        if b and b != u and b in direct_to_pid:
            out[u] = direct_to_pid[b]
            continue
    return out


def _build_product_id_maps(
    product_urls: list[str],
) -> tuple[dict[str, str], dict[str, str], dict[str, list[str]], dict[str, list[str]]]:
    """product_urls에 대한 smart_targets, catalog_by_url, smart_to_urls, catalog_to_urls 반환."""
    smart_targets: dict[str, str] = {}
    for u in product_urls:
        pid = _canonical_product_id(u)
        if pid:
            smart_targets[u] = pid
    catalog_by_url: dict[str, str] = {}
    try:
        with SessionLocal() as s:
            for u in product_urls:
                flt = _smartstore_product_url_filters(TrackedProductMeta, product_url=u)
                if not flt:
                    continue
                meta: TrackedProductMeta | None = s.query(TrackedProductMeta).filter(or_(*flt)).one_or_none()
                if meta is None:
                    continue
                pid = getattr(meta, "product_id_catalog", None)
                if pid is None:
                    continue
                catalog_by_url[u] = str(pid).strip()
    except Exception:
        catalog_by_url = catalog_by_url or {}
    smart_to_urls: dict[str, list[str]] = {}
    for u, pid in smart_targets.items():
        smart_to_urls.setdefault(str(pid), []).append(u)
    catalog_to_urls: dict[str, list[str]] = {}
    for u, cid in catalog_by_url.items():
        if cid:
            catalog_to_urls.setdefault(str(cid), []).append(u)
    return (smart_targets, catalog_by_url, smart_to_urls, catalog_to_urls)


def _run_openapi_rank_job(
    *,
    job_id: str,
    job_name: str,
    seed_product_url: str,
    product_urls: list[str],
    keywords: list[str],
    target_date: date,
    limit: int,
) -> None:
    """
    BackgroundTasks에서 실행되는 OpenAPI 기반 순위 수집/저장 작업.
    - 저장 위치: tracked_product_rank_daily (source='openapi')
    - 목적: 수기 키워드(≈100)도 418/캡차 없이 안정적으로 수집
    - OPENAPI_RANK_CONCURRENCY > 1 이면 키워드 단위 병렬 수집으로 시간 단축
    """
    # 0) job run row STARTED
    with SessionLocal() as s:
        try:
            s.execute(
                text(
                    "INSERT INTO analytics_job_run(job_name, run_date, status) "
                    "VALUES (:job_name, :run_date, :status) "
                    "ON CONFLICT (job_name, run_date) DO UPDATE SET status = EXCLUDED.status, finished_at = NULL, detail = NULL"
                ),
                {"job_name": job_name, "run_date": target_date, "status": "STARTED"},
            )
            s.commit()
        except Exception:
            try:
                s.rollback()
            except Exception:
                pass

    # 1) 대상 식별자 세트 구성
    # - smartstore /products/<id> (SmartStore mallProductId 성격)
    # - TrackedProductMeta.product_id_catalog (OpenAPI shop.json의 productId와 동일한 catalog ID 성격)
    smart_targets: dict[str, str] = {}
    for u in product_urls:
        pid = _canonical_product_id(u)
        if pid:
            smart_targets[u] = pid

    # catalog id는 메타가 없으면 비어 있을 수 있다(그 경우 smartstore id만 사용)
    catalog_by_url: dict[str, str] = {}
    try:
        with SessionLocal() as s:
            for u in product_urls:
                # URL 정규화 차이 대응을 위해 안전 필터를 사용한다.
                flt = _smartstore_product_url_filters(TrackedProductMeta, product_url=u)
                if not flt:
                    continue
                meta: TrackedProductMeta | None = s.query(TrackedProductMeta).filter(or_(*flt)).one_or_none()
                if meta is None:
                    continue
                pid = getattr(meta, "product_id_catalog", None)
                if pid is None:
                    continue
                catalog_by_url[u] = str(pid).strip()
    except Exception:
        # 메타 조회 실패는 치명적이지 않으므로 무시(스마트스토어 ID 매칭만으로 진행)
        catalog_by_url = catalog_by_url or {}

    if not smart_targets and not catalog_by_url:
        print(
            f"[openapi-rank-job] FAILED no_product_id job_id={job_id} seed={seed_product_url[:60]!r}...",
            flush=True,
        )
        with SessionLocal() as s:
            try:
                s.query(AnalyticsJobRun).filter(
                    AnalyticsJobRun.job_name == job_name,
                    AnalyticsJobRun.run_date == target_date,
                ).update(
                    {
                        "status": "FAILED",
                        "finished_at": datetime.utcnow(),
                        "detail": json.dumps(
                            {"job_id": job_id, "error": "no_product_id", "seed_product_url": seed_product_url},
                            ensure_ascii=False,
                        ),
                    },
                    synchronize_session=False,
                )
                s.commit()
            except Exception:
                try:
                    s.rollback()
                except Exception:
                    pass
        return

    # (통일) API 세팅(DB 저장값) 우선 사용
    client_id = _first_nonempty(["NAVER_SEARCH_CLIENT_ID", "NAVER_KEY", "NAVER_CLIENT_ID"])
    client_secret = _first_nonempty(["NAVER_SEARCH_CLIENT_SECRET", "NAVER_SECRET", "NAVER_CLIENT_SECRET"])
    if not client_id or not client_secret:
        print(f"[openapi-rank-job] FAILED openapi_not_configured job_id={job_id}", flush=True)
        with SessionLocal() as s:
            try:
                s.query(AnalyticsJobRun).filter(
                    AnalyticsJobRun.job_name == job_name,
                    AnalyticsJobRun.run_date == target_date,
                ).update(
                    {
                        "status": "FAILED",
                        "finished_at": datetime.utcnow(),
                        "detail": json.dumps(
                            {"job_id": job_id, "error": "openapi_not_configured"},
                            ensure_ascii=False,
                        ),
                    },
                    synchronize_session=False,
                )
                s.commit()
            except Exception:
                try:
                    s.rollback()
                except Exception:
                    pass
        return

    # 병렬 워커에서 API 설정(DB 캐시)을 읽을 수 있도록 미리 캐시를 채운다.
    try:
        _load_api_settings_cached()
    except Exception:
        pass

    # (중요) print에서 사용하므로 반드시 로그 출력 전에 정의
    # 기본값을 4로 둬 "너무 느림" 체감을 완화한다. (429가 발생하면 had_openapi_error로 PARTIAL 처리)
    concurrency = max(1, min(20, int(os.getenv("OPENAPI_RANK_CONCURRENCY", "4"))))
    keywords_list = [str(kw or "").strip() for kw in keywords if str(kw or "").strip()]

    n_smart = len(smart_targets)
    n_catalog = len(catalog_by_url)
    print(
        f"[openapi-rank-job] start job_id={job_id} keywords={len(keywords_list)} "
        f"client_id_len={len(client_id or '')} client_secret_len={len(client_secret or '')} concurrency={concurrency} "
        f"smart_targets={n_smart} catalog_by_url={n_catalog}",
        flush=True,
    )
    if n_smart == 0 and n_catalog == 0:
        print("[openapi-rank-job] WARNING: no product id mapping (smart_targets and catalog_by_url both empty); matching will fail", flush=True)

    # 2) 수집/저장
    saved = 0
    max_rank = max(10, min(1000, int(limit or 120)))

    # 빠른 매칭을 위해 reverse map 구성
    smart_to_urls: dict[str, list[str]] = {}
    for u, pid in smart_targets.items():
        smart_to_urls.setdefault(str(pid), []).append(u)
    catalog_to_urls: dict[str, list[str]] = {}
    for u, cid in catalog_by_url.items():
        if cid:
            catalog_to_urls.setdefault(str(cid), []).append(u)

    def _write_keyword_result(kw0: str, found_rank_by_url: dict[str, int], had_openapi_error: bool) -> int:
        return _write_keyword_result_impl(kw0, found_rank_by_url, had_openapi_error, product_urls, target_date)

    openapi_err_cnt = 0
    openapi_err_sample: list[dict] = []
    worker_exc_cnt = 0
    worker_exc_sample: list[dict] = []

    if concurrency <= 1:
        # 기존 순차 처리
        for kw0 in keywords_list:
            if _is_category_crawl_cancelled(job_id):
                with SessionLocal() as s:
                    try:
                        s.query(AnalyticsJobRun).filter(
                            AnalyticsJobRun.job_name == job_name,
                            AnalyticsJobRun.run_date == target_date,
                        ).update(
                            {
                                "status": "CANCELLED",
                                "finished_at": datetime.utcnow(),
                                "detail": json.dumps({"job_id": job_id, "saved_cells": saved, "cancelled": True}, ensure_ascii=False),
                            },
                            synchronize_session=False,
                        )
                        s.commit()
                    except Exception:
                        try:
                            s.rollback()
                        except Exception:
                            pass
                return
            try:
                _, found_rank_by_url, had_openapi_error, last_status = _openapi_fetch_rank_for_one_keyword(
                    kw0,
                    product_urls,
                    smart_to_urls,
                    catalog_to_urls,
                    max_rank,
                    client_id=client_id,
                    client_secret=client_secret,
                )
                if had_openapi_error:
                    openapi_err_cnt += 1
                    if len(openapi_err_sample) < 25:
                        openapi_err_sample.append(
                            {
                                "keyword": (kw0[:120] + "…") if len(kw0) > 120 else kw0,
                                "http_status": last_status,
                                "products": len(product_urls),
                            }
                        )
                n_wrote = _write_keyword_result(kw0, found_rank_by_url, had_openapi_error)
                if had_openapi_error and n_wrote > 0:
                    print(f"[openapi-rank-job] keyword {kw0[:40]!r}... openapi_error but saved rank=0", flush=True)
                saved += n_wrote
                if n_wrote > 0 and saved <= 20:
                    print(f"[openapi-rank-job] wrote keyword {kw0[:30]!r}... saved={saved}", flush=True)
                elif n_wrote > 0 and saved % 50 == 0:
                    print(f"[openapi-rank-job] progress saved={saved} keywords", flush=True)
            except Exception as e:
                worker_exc_cnt += 1
                if len(worker_exc_sample) < 25:
                    worker_exc_sample.append(
                        {
                            "keyword": (kw0[:120] + "…") if len(kw0) > 120 else kw0,
                            "error": repr(e),
                        }
                    )
                print(f"[openapi-rank-job] keyword loop failed keyword={kw0!r} err={e!r}", flush=True)
    else:
        # 키워드 단위 병렬 수집 (OPENAPI_RANK_CONCURRENCY > 1). 자격증명을 넘겨 워커가 캐시를 읽지 않게 함.
        with ThreadPoolExecutor(max_workers=concurrency) as executor:
            future_to_kw = {
                executor.submit(
                    _openapi_fetch_rank_for_one_keyword,
                    kw0,
                    product_urls,
                    smart_to_urls,
                    catalog_to_urls,
                    max_rank,
                    client_id,
                    client_secret,
                ): kw0
                for kw0 in keywords_list
            }
            for future in as_completed(future_to_kw):
                if _is_category_crawl_cancelled(job_id):
                    for f in future_to_kw:
                        f.cancel()
                    with SessionLocal() as s:
                        try:
                            s.query(AnalyticsJobRun).filter(
                                AnalyticsJobRun.job_name == job_name,
                                AnalyticsJobRun.run_date == target_date,
                            ).update(
                                {
                                    "status": "CANCELLED",
                                    "finished_at": datetime.utcnow(),
                                    "detail": json.dumps({"job_id": job_id, "saved_cells": saved, "cancelled": True}, ensure_ascii=False),
                                },
                                synchronize_session=False,
                            )
                            s.commit()
                        except Exception:
                            try:
                                s.rollback()
                            except Exception:
                                pass
                    return
                try:
                    kw0, found_rank_by_url, had_openapi_error, last_status = future.result()
                    if had_openapi_error:
                        openapi_err_cnt += 1
                        if len(openapi_err_sample) < 25:
                            openapi_err_sample.append(
                                {
                                    "keyword": (kw0[:120] + "…") if len(kw0) > 120 else kw0,
                                    "http_status": last_status,
                                    "products": len(product_urls),
                                }
                            )
                    n_w = _write_keyword_result(kw0, found_rank_by_url, had_openapi_error)
                    if had_openapi_error and n_w > 0:
                        print(f"[openapi-rank-job] keyword {kw0[:40]!r}... openapi_error but saved rank=0", flush=True)
                    saved += n_w
                except Exception as e:
                    worker_exc_cnt += 1
                    kw0 = str(future_to_kw.get(future) or "").strip()
                    if len(worker_exc_sample) < 25:
                        worker_exc_sample.append(
                            {
                                "keyword": (kw0[:120] + "…") if len(kw0) > 120 else kw0,
                                "error": repr(e),
                            }
                        )
                    print(f"[openapi-rank-job] worker result or write failed keyword={kw0!r} err={e!r}", flush=True)

    # 3) finish
    if _is_category_crawl_cancelled(job_id):
        with SessionLocal() as s:
            try:
                s.query(AnalyticsJobRun).filter(
                    AnalyticsJobRun.job_name == job_name,
                    AnalyticsJobRun.run_date == target_date,
                ).update(
                    {
                        "status": "CANCELLED",
                        "finished_at": datetime.utcnow(),
                        "detail": json.dumps({"job_id": job_id, "saved_cells": saved, "cancelled": True}, ensure_ascii=False),
                    },
                    synchronize_session=False,
                )
                s.commit()
            except Exception:
                try:
                    s.rollback()
                except Exception:
                    pass
        return

    # saved_cells가 0일 때 원인 파악용: 메인 스레드에서 OpenAPI 1회 호출 후 로그
    if saved == 0 and len(keywords_list) > 0:
        print(
            f"[openapi-rank-job] saved_cells=0 → 수정 후 저장 0건. 원인 후보: "
            "1) client_id/secret 비어있음 2) OpenAPI 4xx 3) smart_targets/catalog 비어있어 상품 매칭 실패 4) write_keyword_result 예외",
            flush=True,
        )
        try:
            st, items = _openapi_fetch_shop_items(
                keyword=keywords_list[0],
                start=1,
                display=10,
                client_id=client_id,
                client_secret=client_secret,
            )
            items_len = len(items) if items else 0
            print(
                f"[openapi-rank-job] saved_cells=0 diagnostic: first_keyword={keywords_list[0][:40]!r}... "
                f"http_status={st} items_count={items_len} client_id_len={len(client_id or '')} client_secret_len={len(client_secret or '')}",
                flush=True,
            )
        except Exception as diag_e:
            print(f"[openapi-rank-job] saved_cells=0 diagnostic failed: {diag_e!r}", flush=True)

    detail_payload = {
        "job_id": job_id,
        "saved_cells": saved,
        "products": len(product_urls),
        "keywords": len(keywords_list),
        "method": "openapi",
        "openapi_error_keywords": int(openapi_err_cnt),
        "openapi_error_sample": openapi_err_sample,
        "worker_exceptions": int(worker_exc_cnt),
        "worker_exception_sample": worker_exc_sample,
    }
    if saved == 0 and len(keywords_list) > 0:
        detail_payload["saved_cells_hint"] = "openapi_error_or_write_failure_check_api_logs"

    status_final = "SUCCESS"
    if keywords_list:
        # OpenAPI 에러(예: 429) 또는 워커 예외가 있으면 "완료"로 표시하면 안 된다.
        # - 오늘자 row가 일부 누락되어 crawl/today-status가 미완료로 남을 수 있음 → UI가 "성공인데 멈춤"으로 보이는 원인.
        if int(openapi_err_cnt) > 0 or int(worker_exc_cnt) > 0:
            status_final = "PARTIAL" if int(saved) > 0 else "FAILED"
        elif int(saved) == 0:
            # 에러 카운트가 잡히지 않았는데 저장이 0이면 write 실패 가능성이 높다.
            status_final = "FAILED"

    with SessionLocal() as s:
        try:
            s.query(AnalyticsJobRun).filter(
                AnalyticsJobRun.job_name == job_name,
                AnalyticsJobRun.run_date == target_date,
            ).update(
                {
                    "status": status_final,
                    "finished_at": datetime.utcnow(),
                    "detail": json.dumps(detail_payload, ensure_ascii=False),
                },
                synchronize_session=False,
            )
            s.commit()
        except Exception:
            try:
                s.rollback()
            except Exception:
                pass


def _run_openapi_rank_job_batch_by_keyword(
    *,
    job_id: str,
    job_name: str,
    keyword_to_product_urls: dict[str, list[str]],
    target_date: date,
    limit: int,
) -> None:
    """
    동일 키워드 1회 수집 후 해당 키워드를 가진 모든 상품에 순위 저장.
    - 기본 수집원은 네이버 쇼핑 홈 기반 CDP(Network/DOM)이다.
    - 기존 OpenAPI shop.json은 2026-07-31 종료되어, RANK_COLLECTOR_SOURCE=openapi일 때만 사용한다.
    keyword_to_product_urls: 키워드 -> 해당 키워드를 등록한 상품 URL 목록.
    """
    source_mode = str(os.getenv("RANK_COLLECTOR_SOURCE") or "shopping_cdp").strip().lower()
    client_id = _first_nonempty(["NAVER_SEARCH_CLIENT_ID", "NAVER_KEY", "NAVER_CLIENT_ID"])
    client_secret = _first_nonempty(["NAVER_SEARCH_CLIENT_SECRET", "NAVER_SECRET", "NAVER_CLIENT_SECRET"])
    if source_mode in {"openapi", "shop_json", "shop.json"} and (not client_id or not client_secret):
        with SessionLocal() as s:
            try:
                s.query(AnalyticsJobRun).filter(
                    AnalyticsJobRun.job_name == job_name,
                    AnalyticsJobRun.run_date == target_date,
                ).update(
                    {
                        "status": "FAILED",
                        "finished_at": datetime.utcnow(),
                        "detail": json.dumps({"job_id": job_id, "error": "openapi_not_configured"}, ensure_ascii=False),
                    },
                    synchronize_session=False,
                )
                s.commit()
            except Exception:
                try:
                    s.rollback()
                except Exception:
                    pass
        return
    if source_mode in {"openapi", "shop_json", "shop.json"}:
        try:
            _load_api_settings_cached()
        except Exception:
            pass
    max_rank = max(10, min(1000, int(limit or 120)))
    keywords_ordered = list(keyword_to_product_urls.keys())
    saved = 0
    openapi_err_cnt = 0
    openapi_err_sample: list[dict] = []
    # 성능 최적화: 전체 상품 URL에 대해 catalog id를 1회 프리페치한다.
    all_urls: list[str] = []
    for _, urls in (keyword_to_product_urls or {}).items():
        for u in urls or []:
            u0 = str(u or "").strip()
            if u0:
                all_urls.append(u0)
    all_urls = list(dict.fromkeys(all_urls))
    catalog_id_by_url = _prefetch_catalog_id_by_url(all_urls)
    aliases_by_url: dict[str, list[str]] = {u: [] for u in all_urls}
    try:
        with SessionLocal() as s:
            for u in all_urls:
                flt = _smartstore_product_url_filters(TrackedProductMeta, product_url=u)
                if not flt:
                    continue
                meta: TrackedProductMeta | None = s.query(TrackedProductMeta).filter(or_(*flt)).order_by(TrackedProductMeta.updated_at.desc()).limit(1).one_or_none()
                if meta is None:
                    continue
                aliases = [
                    getattr(meta, "title", None),
                    getattr(meta, "name", None),
                ]
                aliases_by_url[u] = [str(x or "").strip() for x in aliases if str(x or "").strip()]
    except Exception:
        aliases_by_url = aliases_by_url or {}
    smart_id_by_url: dict[str, str] = {}
    for u in all_urls:
        pid = _canonical_product_id(u)
        if pid:
            smart_id_by_url[u] = str(pid)
    cdp_batch_size = max(1, int(os.getenv("SHOPPING_RANK_CDP_BATCH_SIZE", "50")))
    cdp_delay_min = max(0.0, float(os.getenv("SHOPPING_RANK_CDP_DELAY_MIN_SEC", "8")))
    cdp_delay_max = max(cdp_delay_min, float(os.getenv("SHOPPING_RANK_CDP_DELAY_MAX_SEC", "15")))
    cdp_batch_cooldown = max(0.0, float(os.getenv("SHOPPING_RANK_CDP_BATCH_COOLDOWN_SEC", "300")))
    for idx, kw0 in enumerate(keywords_ordered):
        if _is_category_crawl_cancelled(job_id):
            with SessionLocal() as s:
                try:
                    s.query(AnalyticsJobRun).filter(
                        AnalyticsJobRun.job_name == job_name,
                        AnalyticsJobRun.run_date == target_date,
                    ).update(
                        {
                            "status": "CANCELLED",
                            "finished_at": datetime.utcnow(),
                            "detail": json.dumps({"job_id": job_id, "saved_cells": saved, "cancelled": True}, ensure_ascii=False),
                        },
                        synchronize_session=False,
                    )
                    s.commit()
                except Exception:
                    try:
                        s.rollback()
                    except Exception:
                        pass
            return
        product_urls_this = list(keyword_to_product_urls.get(kw0, []))
        if not product_urls_this:
            continue
        smart_to_urls: dict[str, list[str]] = {}
        catalog_to_urls: dict[str, list[str]] = {}
        for u in product_urls_this:
            u0 = str(u or "").strip()
            if not u0:
                continue
            pid = smart_id_by_url.get(u0) or _canonical_product_id(u0)
            if pid:
                smart_to_urls.setdefault(str(pid), []).append(u0)
            cid = catalog_id_by_url.get(u0)
            if cid:
                catalog_to_urls.setdefault(str(cid), []).append(u0)
        if source_mode in {"openapi", "shop_json", "shop.json"}:
            _, found_rank_by_url, had_collect_error, last_status = _openapi_fetch_rank_for_one_keyword(
                kw0, product_urls_this, smart_to_urls, catalog_to_urls, max_rank,
                client_id=client_id or "", client_secret=client_secret or "",
            )
            method_name = "openapi_batch_by_keyword"
            error_key = last_status
        else:
            try:
                _, found_rank_by_url, had_collect_error, error_key = _pw_call(
                    _shopping_cdp_fetch_rank_for_one_keyword,
                    kw0, product_urls_this, smart_to_urls, catalog_to_urls, max_rank,
                    aliases_by_url={u: aliases_by_url.get(u, []) for u in product_urls_this},
                    timeout=90.0,
                )
            except Exception as e:
                found_rank_by_url = {u: 0 for u in product_urls_this}
                had_collect_error = True
                error_key = f"shopping_cdp_worker_error:{type(e).__name__}:{str(e)[:160]}"
            method_name = "shopping_cdp_home_dom_network"
        if had_collect_error:
            openapi_err_cnt += 1
            if len(openapi_err_sample) < 25:
                openapi_err_sample.append(
                    {
                        "keyword": (kw0[:120] + "…") if len(kw0) > 120 else kw0,
                        "error": error_key,
                        "products": len(product_urls_this),
                    }
                )
            if _shopping_rank_is_blocked_error(error_key):
                with SessionLocal() as s:
                    try:
                        s.query(AnalyticsJobRun).filter(
                            AnalyticsJobRun.job_name == job_name,
                            AnalyticsJobRun.run_date == target_date,
                        ).update(
                            {
                                "status": "BLOCKED",
                                "finished_at": datetime.utcnow(),
                                "detail": json.dumps(
                                    {
                                        "job_id": job_id,
                                        "saved_cells": saved,
                                        "unique_keywords": len(keywords_ordered),
                                        "method": method_name,
                                        "blocked_at_keyword_index": idx + 1,
                                        "blocked_keyword": kw0,
                                        "error": error_key,
                                        "openapi_error_keywords": int(openapi_err_cnt),
                                        "openapi_error_sample": openapi_err_sample,
                                    },
                                    ensure_ascii=False,
                                ),
                            },
                            synchronize_session=False,
                        )
                        s.commit()
                    except Exception:
                        try:
                            s.rollback()
                        except Exception:
                            pass
                return
        n_wrote = _write_keyword_result_impl(kw0, found_rank_by_url, had_collect_error, product_urls_this, target_date)
        saved += n_wrote
        if (idx + 1) <= 5 or (idx + 1) % 50 == 0:
            print(f"[openapi-rank-job] batch-by-keyword job_id={job_id} keyword {idx+1}/{len(keywords_ordered)} saved={saved}", flush=True)
        if source_mode not in {"openapi", "shop_json", "shop.json"}:
            if (idx + 1) % cdp_batch_size == 0 and (idx + 1) < len(keywords_ordered):
                print(
                    f"[openapi-rank-job] CDP cooldown job_id={job_id} keyword={idx+1}/{len(keywords_ordered)} seconds={cdp_batch_cooldown}",
                    flush=True,
                )
                try:
                    _pw_call(_close_pw_context, timeout=30.0)
                except Exception:
                    pass
                if cdp_batch_cooldown > 0:
                    time.sleep(cdp_batch_cooldown)
            elif cdp_delay_max > 0:
                time.sleep(random.uniform(cdp_delay_min, cdp_delay_max))
    detail_payload = {
        "job_id": job_id,
        "saved_cells": saved,
        "unique_keywords": len(keywords_ordered),
        "method": method_name if 'method_name' in locals() else "shopping_cdp_home_dom_network",
        "openapi_error_keywords": int(openapi_err_cnt),
        "openapi_error_sample": openapi_err_sample,
    }
    status_final = "SUCCESS"
    if keywords_ordered:
        if int(openapi_err_cnt) > 0:
            status_final = "PARTIAL" if int(saved) > 0 else "FAILED"
        elif int(saved) == 0:
            status_final = "FAILED"
    with SessionLocal() as s:
        try:
            s.query(AnalyticsJobRun).filter(
                AnalyticsJobRun.job_name == job_name,
                AnalyticsJobRun.run_date == target_date,
            ).update(
                {"status": status_final, "finished_at": datetime.utcnow(), "detail": json.dumps(detail_payload, ensure_ascii=False)},
                synchronize_session=False,
            )
            s.commit()
        except Exception:
            try:
                s.rollback()
            except Exception:
                pass


@app.post("/search-rank/crawl/category", response_model=CategoryCrawlResponse)
def crawl_category_ranks(
    payload: CategoryCrawlRequest,
    background_tasks: BackgroundTasks,
    db: Session = Depends(get_db),
):
    """
    (변경) 키워드 순위 수집은 **무조건 OpenAPI(shop.json)** 기반으로 수행한다.
    - 이유: Playwright/쇼핑 내부 API 기반 수집은 418(access_limited)/캡차에 취약해 운영 안정성이 떨어짐.
    - 저장 위치: tracked_product_rank_daily (source='openapi')
    - 주의: 기존 category 스코프/Playwright 경로는 더 이상 사용하지 않는다(항상 단일 상품 기준).
    """
    seed = str(getattr(payload, "product_url", "") or "").strip()
    if not seed:
        raise HTTPException(status_code=400, detail="product_url is required")

    limit = int(getattr(payload, "limit", 120) or 120)
    limit = max(10, min(1000, limit))

    d = getattr(payload, "target_date", None) or _today_kst()
    if isinstance(d, datetime):
        d = d.date()

    # 대상 상품: 단일 상품만
    product_urls = [seed]

    keywords = _resolve_keywords_for_seed(db, seed_product_url=seed, payload_keywords=getattr(payload, "keywords", None))
    if not keywords:
        raise HTTPException(status_code=400, detail="no_keywords_to_crawl (manual keywords empty)")
    # 과도한 요청 방지(카테고리당 100개 테스트 등)
    keywords = keywords[:200]

    job_id = hashlib.sha256(f"{seed}|{time.time()}|{random.random()}".encode("utf-8")).hexdigest()[:16]
    job_name = f"category-crawl:{job_id}"

    # 중요: 상태 조회 레이스 방지
    # - 프론트가 /status를 즉시 폴링할 수 있으므로, BackgroundTasks 시작 전에 job row를 먼저 기록한다.
    try:
        db.execute(
            text(
                "INSERT INTO analytics_job_run(job_name, run_date, status, detail) "
                "VALUES (:job_name, :run_date, :status, :detail) "
                "ON CONFLICT (job_name, run_date) DO UPDATE SET status = EXCLUDED.status, finished_at = NULL, detail = EXCLUDED.detail"
            ),
            {
                "job_name": job_name,
                "run_date": d,
                "status": "STARTED",
                "detail": json.dumps(
                    {
                        "job_id": job_id,
                        "seed_product_url": seed,
                        "products": len(product_urls),
                        "keywords": len(keywords),
                        "limit": limit,
                    },
                    ensure_ascii=False,
                ),
            },
        )
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass

    background_tasks.add_task(
        _run_openapi_rank_job,
        job_id=job_id,
        job_name=job_name,
        seed_product_url=seed,
        product_urls=product_urls,
        keywords=keywords,
        target_date=d,
        limit=limit,
    )
    return CategoryCrawlResponse(
        job_id=job_id,
        status="STARTED",
        product_urls=product_urls,
        keywords=keywords,
        target_date=d.strftime("%Y-%m-%d"),
        limit=limit,
    )


@app.post("/search-rank/crawl/category/batch-by-keyword", response_model=CategoryCrawlResponse)
def crawl_category_batch_by_keyword(
    payload: CategoryCrawlBatchByKeywordRequest,
    background_tasks: BackgroundTasks,
    db: Session = Depends(get_db),
):
    """
    동일 키워드는 1회만 OpenAPI 호출 후, 해당 키워드를 등록한 모든 상품에 순위를 동시 저장.
    - product_urls: 수집 대상 상품 URL 목록(최대 20)
    - 상품별 키워드는 DB 수기/추적 키워드로 해석. 키워드 유니크 기준으로 호출 수 최소화.
    """
    urls_raw = getattr(payload, "product_urls", None) or []
    product_urls = [str(u or "").strip() for u in urls_raw if str(u or "").strip()]
    product_urls = list(dict.fromkeys(product_urls))[:20]
    if not product_urls:
        raise HTTPException(status_code=400, detail="product_urls is required (max 20)")
    limit = int(getattr(payload, "limit", 40) or 40)
    limit = max(10, min(1000, limit))
    d = getattr(payload, "target_date", None) or _today_kst()
    if isinstance(d, datetime):
        d = d.date()
    # 상품별 키워드 수집 → 키워드별로 어떤 상품들이 가지는지 역매핑
    keyword_to_product_urls: dict[str, list[str]] = {}
    all_keywords_set: set[str] = set()
    for u in product_urls:
        kws = _resolve_keywords_for_seed(db, seed_product_url=u, payload_keywords=None)
        kws = (kws or [])[:200]
        for kw in kws:
            kw = str(kw or "").strip()
            if not kw:
                continue
            all_keywords_set.add(kw)
            keyword_to_product_urls.setdefault(kw, [])
            if u not in keyword_to_product_urls[kw]:
                keyword_to_product_urls[kw].append(u)
    if not keyword_to_product_urls:
        raise HTTPException(status_code=400, detail="no_keywords_to_crawl (all products have no manual/tracked keywords)")
    job_id = hashlib.sha256(f"batch|{','.join(product_urls[:3])}|{time.time()}|{random.random()}".encode("utf-8")).hexdigest()[:16]
    job_name = f"category-crawl:{job_id}"
    try:
        db.execute(
            text(
                "INSERT INTO analytics_job_run(job_name, run_date, status, detail) "
                "VALUES (:job_name, :run_date, :status, :detail) "
                "ON CONFLICT (job_name, run_date) DO UPDATE SET status = EXCLUDED.status, finished_at = NULL, detail = EXCLUDED.detail"
            ),
            {
                "job_name": job_name,
                "run_date": d,
                "status": "STARTED",
                "detail": json.dumps(
                    {
                        "job_id": job_id,
                        "products": len(product_urls),
                        "unique_keywords": len(keyword_to_product_urls),
                        "limit": limit,
                        "mode": "batch_by_keyword",
                    },
                    ensure_ascii=False,
                ),
            },
        )
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass
    background_tasks.add_task(
        _run_openapi_rank_job_batch_by_keyword,
        job_id=job_id,
        job_name=job_name,
        keyword_to_product_urls=keyword_to_product_urls,
        target_date=d,
        limit=limit,
    )
    return CategoryCrawlResponse(
        job_id=job_id,
        status="STARTED",
        product_urls=product_urls,
        keywords=sorted(keyword_to_product_urls.keys()),
        target_date=d.strftime("%Y-%m-%d"),
        limit=limit,
    )


@app.get("/search-rank/crawl/category/status", response_model=CategoryCrawlStatusResponse)
def crawl_category_status(
    job_id: str = Query(..., description="crawl/category 응답의 job_id"),
    db: Session = Depends(get_db),
):
    jid = str(job_id or "").strip()
    if not jid:
        raise HTTPException(status_code=400, detail="job_id is required")
    job_name = f"category-crawl:{jid}"
    row: AnalyticsJobRun | None = (
        db.query(AnalyticsJobRun)
        .filter(AnalyticsJobRun.job_name == job_name)
        .order_by(AnalyticsJobRun.run_date.desc())
        .limit(1)
        .one_or_none()
    )
    if row is None:
        return CategoryCrawlStatusResponse(job_id=jid, status="NOT_FOUND", detail=None)
    return CategoryCrawlStatusResponse(job_id=jid, status=str(getattr(row, "status", "") or ""), detail=getattr(row, "detail", None))


@app.post("/search-rank/crawl/category/cancel", response_model=CategoryCrawlCancelResponse)
def cancel_category_crawl(
    payload: CategoryCrawlCancelRequest,
    db: Session = Depends(get_db),
):
    jid = str(getattr(payload, "job_id", "") or "").strip()
    if not jid:
        raise HTTPException(status_code=400, detail="job_id is required")
    job_name = f"category-crawl:{jid}"

    # 1) in-memory cancel flag (같은 프로세스에서 실행 중인 worker를 즉시 멈추기 위함)
    _cancel_category_crawl_job(jid)

    # 2) DB status 업데이트 (상태 폴링/재기동 시에도 취소 상태가 유지되도록)
    row: AnalyticsJobRun | None = (
        db.query(AnalyticsJobRun)
        .filter(AnalyticsJobRun.job_name == job_name)
        .order_by(AnalyticsJobRun.run_date.desc())
        .limit(1)
        .one_or_none()
    )
    if row is None:
        return CategoryCrawlCancelResponse(job_id=jid, status="NOT_FOUND")

    try:
        db.query(AnalyticsJobRun).filter(AnalyticsJobRun.job_name == job_name, AnalyticsJobRun.run_date == row.run_date).update(
            {
                "status": "CANCELLED",
                "finished_at": datetime.utcnow(),
                "detail": json.dumps({"job_id": jid, "cancelled": True}, ensure_ascii=False),
            },
            synchronize_session=False,
        )
        db.query(CollectionJobRun).filter(
            CollectionJobRun.task_id == "rank_openapi",
            CollectionJobRun.status.in_(["STARTED", "RUNNING", "POLLING", "QUEUED", "CLAIMED"]),
            CollectionJobRun.detail_json.like(f'%"analytics_job_id": "{jid}"%'),
        ).update(
            {
                "status": "CANCELLED",
                "finished_at": datetime.utcnow(),
                "error": "user_cancelled",
            },
            synchronize_session=False,
        )
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass
    return CategoryCrawlCancelResponse(job_id=jid, status="CANCELLED")


@app.post("/search-rank/crawl/category/cancel-active", response_model=CategoryCrawlCancelResponse)
def cancel_active_category_crawl(
    db: Session = Depends(get_db),
):
    today = _today_kst()
    row: AnalyticsJobRun | None = (
        db.query(AnalyticsJobRun)
        .filter(
            AnalyticsJobRun.run_date == today,
            AnalyticsJobRun.job_name.like("category-crawl:%"),
            AnalyticsJobRun.status.in_(["STARTED", "RUNNING", "POLLING", "QUEUED", "CLAIMED"]),
        )
        .order_by(AnalyticsJobRun.started_at.desc())
        .limit(1)
        .one_or_none()
    )
    if row is None:
        db.query(CollectionJobRun).filter(
            CollectionJobRun.task_id == "rank_openapi",
            CollectionJobRun.status.in_(["STARTED", "RUNNING", "POLLING", "QUEUED", "CLAIMED"]),
        ).update(
            {
                "status": "CANCELLED",
                "finished_at": datetime.utcnow(),
                "error": "user_cancelled",
            },
            synchronize_session=False,
        )
        db.commit()
        return CategoryCrawlCancelResponse(job_id="", status="NOT_FOUND")

    job_name = str(getattr(row, "job_name", "") or "")
    jid = job_name.split("category-crawl:", 1)[1] if "category-crawl:" in job_name else job_name
    _cancel_category_crawl_job(jid)
    db.query(AnalyticsJobRun).filter(AnalyticsJobRun.job_name == job_name, AnalyticsJobRun.run_date == row.run_date).update(
        {
            "status": "CANCELLED",
            "finished_at": datetime.utcnow(),
            "detail": json.dumps({"job_id": jid, "cancelled": True}, ensure_ascii=False),
        },
        synchronize_session=False,
    )
    db.query(CollectionJobRun).filter(
        CollectionJobRun.task_id == "rank_openapi",
        CollectionJobRun.status.in_(["STARTED", "RUNNING", "POLLING", "QUEUED", "CLAIMED"]),
    ).update(
        {
            "status": "CANCELLED",
            "finished_at": datetime.utcnow(),
            "error": "user_cancelled",
        },
        synchronize_session=False,
    )
    db.commit()
    return CategoryCrawlCancelResponse(job_id=jid, status="CANCELLED")


@app.post("/search-rank/crawl/today-status", response_model=list[CrawlTodayStatusItem])
def crawl_today_status(
    payload: CrawlTodayStatusRequest,
    db: Session = Depends(get_db),
):
    """
    4-2 메뉴 진입 시 "오늘 키워드 순위 수집이 필요한지"를 빠르게 판정하기 위한 상태 API.

    기준:
    - 대상 키워드: 해당 상품의 수기 키워드(월검색량 리스트, tracked_product_manual_keyword active)
    - 수집 완료: tracked_product_rank_daily에 (today, product_url, keyword) 행이 있고 source='openapi'이며 rank>0 인 키워드가
      대상 키워드를 모두 커버하면 완료로 본다.
    """
    urls_raw = getattr(payload, "product_urls", None) or []
    urls = [str(u or "").strip() for u in urls_raw if str(u or "").strip()]
    urls = list(dict.fromkeys(urls))[:10]
    if not urls:
        return []
    d = getattr(payload, "target_date", None) or _today_kst()
    if isinstance(d, datetime):
        d = d.date()

    out: list[CrawlTodayStatusItem] = []
    for u in urls:
        # 수기 키워드가 0개인 경우, 신규 상품에 한해 추적 키워드로 자동 시드한다.
        # (사용자가 "전부 삭제"한 상품까지 다시 채우면 삭제가 실패한 것처럼 보임)
        if not _manual_keyword_meta_exists_any(db, product_url=u):
            try:
                _seed_manual_keywords_from_tracked(db, product_url=u)
            except Exception:
                # 시드 실패는 치명적이지 않으므로 무시(상태 조회는 계속)
                pass
        filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=u)
        kws_rows = (
            db.query(TrackedProductManualKeyword)
            .filter(or_(*filters), TrackedProductManualKeyword.is_active.is_(True))
            .order_by(TrackedProductManualKeyword.keyword.asc())
            .all()
        )
        manual_kws = [str(r.keyword or "").strip() for r in kws_rows if str(r.keyword or "").strip()]
        manual_kws = list(dict.fromkeys(manual_kws))

        # (중요) tracked 키워드도 "등록된 키워드"에 포함한다.
        tracked_kws: list[str] = []
        try:
            tk_filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=u)
            if tk_filters:
                tk_rows = (
                    db.query(TrackedProductKeyword.keyword)
                    .filter(or_(*tk_filters), TrackedProductKeyword.is_active.is_(True))
                    .order_by(TrackedProductKeyword.keyword.asc())
                    .all()
                )
                tracked_kws = [str(x[0] or "").strip() for x in tk_rows if x and str(x[0] or "").strip()]
                tracked_kws = list(dict.fromkeys(tracked_kws))
        except Exception:
            tracked_kws = []

        kws = list(dict.fromkeys([*manual_kws, *tracked_kws]))
        total = len(kws)
        sample_kw = kws[0] if kws else None
        if total == 0:
            out.append(
                CrawlTodayStatusItem(
                    product_url=u,
                    total_keywords=0,
                    covered_keywords=0,
                    missing_keywords=[],
                    sample_keyword=None,
                    # 수기 키워드가 0개면 "수집 완료"가 아니라 "설정 필요" 상태로 본다.
                    # (그래야 모달/자동수집에서 대상에서 빠지지 않고, 사용자가 원인을 즉시 확인할 수 있다)
                    is_complete=False,
                )
            )
            continue

        rank_filters = _smartstore_product_url_filters(TrackedProductRankDaily, product_url=u)
        rows = (
            db.query(TrackedProductRankDaily.keyword, TrackedProductRankDaily.rank)
            .filter(
                or_(*rank_filters),
                TrackedProductRankDaily.date == d,
                TrackedProductRankDaily.source == "openapi",
                TrackedProductRankDaily.keyword.in_(kws),
            )
            .all()
        )
        # "수집 완료"는 '노출(rank>0)' 여부가 아니라,
        # 해당 키워드에 대해 오늘자 스냅샷(row)이 존재하는지로 판정한다.
        # - rank==0(미노출)도 수집 결과이므로 완료로 본다.
        collected: set[str] = set()
        exposed: set[str] = set()
        for kw, _rk in rows:
            k0 = str(kw or "").strip()
            if k0:
                collected.add(k0)
                try:
                    n = int(_rk) if _rk is not None else 0
                except Exception:
                    n = 0
                if n > 0:
                    exposed.add(k0)
        collected_cnt = len(collected)
        exposed_cnt = len(exposed)
        no_exposure_cnt = max(0, collected_cnt - exposed_cnt)
        missing = [kw for kw in kws if kw not in collected]
        out.append(
            CrawlTodayStatusItem(
                product_url=u,
                total_keywords=total,
                covered_keywords=collected_cnt,
                exposed_keywords=exposed_cnt,
                no_exposure_keywords=no_exposure_cnt,
                missing_keywords=missing[:200],
                sample_keyword=sample_kw,
                is_complete=(collected_cnt == total),
            )
        )
    return out


@app.get("/search-rank/tracked", response_model=List[TrackedProductKeywordRead])
def list_tracked_product_keywords(
    product_url: Optional[str] = Query(None, description="상품 URL 기준 조회(선택)"),
    include_today_rank: bool = Query(False, description="true이면 오늘(KST) 저장된 순위/변동(today_rank/today_delta)을 함께 반환"),
    db: Session = Depends(get_db),
):
    """
    메뉴4 '내 상품 추적'에서 사용하는 추적 키워드 리스트를 조회한다.
    """
    q = db.query(TrackedProductKeyword).filter(TrackedProductKeyword.is_active.is_(True))
    if product_url:
        u0 = str(product_url or "").strip()
        if u0:
            try:
                u0 = _canonicalize_smartstore_base_url(u0) or u0
            except Exception:
                u0 = u0
            flt = _smartstore_product_url_filters(TrackedProductKeyword, product_url=u0)
            if flt:
                q = q.filter(or_(*flt))
            else:
                # product_url이 비정상이라면 빈 결과로 처리
                return []
    rows = q.order_by(TrackedProductKeyword.created_at.desc()).all()
    if not include_today_rank:
        return rows

    # --- 오늘 rank/delta 계산(저장값 기반, 동기화/크롤링을 자동으로 돌리지 않음) ---
    today = _today_kst()
    prev = today - timedelta(days=1)

    def _norm_url(u: str) -> str:
        # smartstore URL은 query/hash가 달라도 동일 상품이므로 base URL로 통일한다.
        # (이 정규화가 없으면 저장값이 있는데도 include_today_rank에서 못 찾아 '-'가 뜰 수 있다.)
        try:
            return _canonicalize_smartstore_base_url(u) or u
        except Exception:
            return u

    urls: list[str] = []
    kws: list[str] = []
    for r in rows:
        u = str(getattr(r, "product_url", "") or "").strip()
        kw = str(getattr(r, "keyword", "") or "").strip()
        if not u or not kw:
            continue
        urls.append(_norm_url(u))
        kws.append(kw)
    urls = list(dict.fromkeys(urls))
    kws = list(dict.fromkeys(kws))

    def _load_rank_map(target_date: date) -> dict[tuple[str, str], int]:
        if not urls or not kws:
            return {}
        # 대표 rank 정책(중요):
        # - 같은 날짜에 여러 source가 섞일 수 있다(openapi/crawl_category/excel/text).
        # - 이때 rank==0(미노출) 또는 999(결측/미노출 취급)가 하나라도 있으면
        #   단순 min()은 0/999로 오염되어 UI에서 '-'가 뜨는 문제가 생긴다.
        # - 따라서 "유효 순위(1~998)"만 후보로 두고 그 중 min을 대표값으로 사용한다.
        # URL 정규화 차이를 포함해 조회한다.
        field = TrackedProductRankDaily.product_url
        try:
            dialect = str(getattr(engine, "dialect", None).name or "").lower()
        except Exception:
            dialect = ""
        if "postgres" in dialect:
            base = func.split_part(field, "?", 1)
            base = func.split_part(base, "#", 1)
        elif "sqlite" in dialect:
            pos_q = func.instr(field, "?")
            base_q = case((pos_q > 0, func.substr(field, 1, pos_q - 1)), else_=field)
            pos_h = func.instr(base_q, "#")
            base = case((pos_h > 0, func.substr(base_q, 1, pos_h - 1)), else_=base_q)
        else:
            base = field

        data = (
            db.query(
                TrackedProductRankDaily.product_url,
                TrackedProductRankDaily.keyword,
                TrackedProductRankDaily.rank,
                TrackedProductRankDaily.source,
            )
            .filter(
                TrackedProductRankDaily.date == target_date,
                base.in_(urls),
                TrackedProductRankDaily.keyword.in_(kws),
            )
            .all()
        )
        out: dict[tuple[str, str], int] = {}
        priorities: dict[tuple[str, str], int] = {}
        for u, kw, rk, source in data:
            u0 = _norm_url(str(u or "").strip())
            k0 = str(kw or "").strip()
            if not u0 or not k0:
                continue
            try:
                n = int(rk) if rk is not None else None
            except Exception:
                n = None
            if n is None:
                continue
            # 유효 순위만 대표값 후보로 인정한다.
            if n <= 0:
                continue
            if n >= 999:
                continue
            key = (u0, k0)
            cur = out.get(key)
            priority = _rank_source_priority(source)
            cur_priority = priorities.get(key, -1)
            if cur is None or priority > cur_priority or (priority == cur_priority and n < cur):
                out[key] = n
                priorities[key] = priority
        return out

    today_map = _load_rank_map(today)
    prev_map = _load_rank_map(prev)

    out: list[dict] = []
    for r in rows:
        u = _norm_url(str(getattr(r, "product_url", "") or "").strip())
        kw = str(getattr(r, "keyword", "") or "").strip()
        tr = today_map.get((u, kw)) if u and kw else None
        pr = prev_map.get((u, kw)) if u and kw else None
        delta: int | None
        if tr is None or pr is None:
            delta = None
        else:
            # +면 "순위 상승"(숫자가 줄어듦), -면 "순위 하락"
            delta = int(pr - tr)
        out.append(
            {
                "id": getattr(r, "id"),
                "product_url": getattr(r, "product_url", None),
                "keyword": getattr(r, "keyword"),
                "monthly_search_volume": getattr(r, "monthly_search_volume", None),
                "is_active": bool(getattr(r, "is_active", True)),
                "created_at": getattr(r, "created_at"),
                "today_rank": tr,
                "today_delta": delta,
            }
        )
    return out


@app.get("/search-rank/tracked/keyword-ranks", response_model=dict)
def list_tracked_products_keyword_ranks(
    keyword: str = Query(..., min_length=1, description="목록 우측에 표시할 조회 키워드"),
    days: int = Query(7, ge=1, le=30),
    db: Session = Depends(get_db),
):
    """
    내 상품 추적 목록에서 사용자가 입력한 키워드의 최근 순위를 등록 상품별로 반환한다.

    수집을 새로 실행하지 않고, 오늘 기준 최근 N일의 저장된 `tracked_product_rank_daily`만 집계한다.
    """
    kw = str(keyword or "").strip()
    if not kw:
        raise HTTPException(status_code=400, detail="keyword is required")

    today = _today_kst()
    date_from = today - timedelta(days=days - 1)
    dates = [date_from + timedelta(days=i) for i in range(days)]

    product_rows = (
        db.query(TrackedProductKeyword.product_url)
        .filter(
            TrackedProductKeyword.is_active.is_(True),
            TrackedProductKeyword.product_url.is_not(None),
            TrackedProductKeyword.product_url != "",
        )
        .distinct()
        .all()
    )
    product_urls = sorted({
        _canonicalize_smartstore_base_url(str(row[0] or "").strip()) or str(row[0] or "").strip()
        for row in product_rows
        if str(row[0] or "").strip()
    })

    def _best_rank(existing: tuple[int, int] | None, rank_value, source) -> tuple[int, int] | None:
        try:
            rank_int = int(rank_value) if rank_value is not None else None
        except Exception:
            rank_int = None
        if rank_int is None or rank_int <= 0 or rank_int >= 999:
            return existing
        priority = _rank_source_priority(source)
        if existing is None or priority > existing[1] or (priority == existing[1] and rank_int < existing[0]):
            return rank_int, priority
        return existing

    items: list[dict] = []
    for product_url in product_urls:
        filters = _smartstore_product_url_filters(TrackedProductRankDaily, product_url=product_url)
        if not filters:
            continue
        rank_rows = (
            db.query(
                TrackedProductRankDaily.date,
                TrackedProductRankDaily.rank,
                TrackedProductRankDaily.source,
            )
            .filter(
                or_(*filters),
                TrackedProductRankDaily.keyword == kw,
                TrackedProductRankDaily.date >= date_from,
                TrackedProductRankDaily.date <= today,
            )
            .all()
        )
        by_date: dict[date, tuple[int, int]] = {}
        for d, rank_value, source in rank_rows:
            parsed = _collection_parse_date(d)
            if parsed is None:
                continue
            best = _best_rank(by_date.get(parsed), rank_value, source)
            if best is not None:
                by_date[parsed] = best
        items.append(
            {
                "product_url": product_url,
                "ranks": [
                    {
                        "date": d.isoformat(),
                        "rank": int(by_date[d][0]) if d in by_date else None,
                    }
                    for d in dates
                ],
            }
        )

    return {
        "keyword": kw,
        "date_from": date_from.isoformat(),
        "date_to": today.isoformat(),
        "dates": [d.isoformat() for d in dates],
        "items": items,
    }


@app.post("/search-rank/tracked", response_model=List[TrackedProductKeywordRead])
def add_tracked_product_keywords(
    payload: TrackedProductKeywordCreate,
    db: Session = Depends(get_db),
):
    """
    추적 대상 상품 URL + 키워드 리스트를 등록한다.

    - 동일 product_url/keyword 조합이 여러 번 들어오는 경우에도
      일단은 중복 허용 (향후 Unique 제약 추가 가능)
    - 하나의 상품 URL 당 최대 MAX_KEYWORDS_PER_PRODUCT 개까지만 허용
    """
    created: List[TrackedProductKeyword] = []

    # 공백/빈 문자열을 제외한 유효 키워드만 추린다.
    valid_keywords: List[str] = []
    for kw in payload.keywords:
        text = (kw or "").strip()
        if not text:
            continue
        valid_keywords.append(text)

    product_url = _canonicalize_smartstore_base_url(payload.product_url or None)

    if product_url and valid_keywords:
        # 상품당 키워드 최대 개수 검증
        ensure_product_keyword_limit(
            db,
            product_url=product_url,
            new_keywords_count=len(valid_keywords),
        )

    for text in valid_keywords:
        obj = TrackedProductKeyword(
            product_url=product_url or None,
            keyword=text,
            is_active=True,
        )
        db.add(obj)
        created.append(obj)

    if not created:
        return []

    db.commit()
    for obj in created:
        db.refresh(obj)

    # (요청) 추적 키워드 입력 시, 수기 키워드(후보) 메타에도 자동 저장한다.
    # - 기존 수기 키워드가 있더라도 덮어쓰지 않고 upsert(is_active=true)한다.
    try:
        now = datetime.utcnow()
        if product_url:
            for obj in created:
                kw = str(getattr(obj, "keyword", "") or "").strip()
                if not kw:
                    continue
                vol = getattr(obj, "monthly_search_volume", None)
                try:
                    iv = int(vol) if vol is not None else None
                except Exception:
                    iv = None
                db.merge(
                    TrackedProductManualKeyword(
                        product_url=product_url,
                        keyword=kw,
                        monthly_search_volume=iv,
                        monthly_search_volume_label=None,
                        is_active=True,
                        updated_at=now,
                    )
                )
            db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass

    return created


@app.delete("/search-rank/tracked/by-product")
def delete_tracked_product_by_url(
    product_url: str = Query(..., description="삭제할 추적 상품의 URL"),
    db: Session = Depends(get_db),
):
    """
    상품 URL 기준으로 '내 상품 추적'에 등록된 상품을 삭제(비활성화)한다.

    - tracked_product_keyword 테이블에서 해당 URL 의 모든 행을 찾아 is_active=False 로 업데이트한다.
    - 기존 데이터는 보존하면서 UI 에서는 더 이상 노출되지 않게 하기 위한 soft delete 방식이다.
    """
    raw = str(product_url or "").strip()
    if not raw:
        raise HTTPException(status_code=400, detail="product_url is required")

    # tracked_product_keyword는 과거에 query/hash가 포함된 URL이 저장된 경우가 있어
    # exact match만으로는 "삭제했는데 남아 있는" 현상이 생길 수 있다.
    # 따라서 smartstore 제품 URL은 base URL로 정규화한 뒤, path 기반 productId 매칭까지 포함해 삭제한다.
    url = _canonicalize_smartstore_base_url(raw) or raw
    filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=url)
    if not filters:
        return {"deleted": 0}

    deleted = (
        db.query(TrackedProductKeyword)
        .filter(or_(*filters), TrackedProductKeyword.is_active.is_(True))
        .update({"is_active": False}, synchronize_session=False)
    )
    # (중요) 수기 키워드(후보) 메타도 함께 비활성화해야 "삭제했는데 A-1에 남는" 유령 상품이 생기지 않는다.
    try:
        mk_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=url)
        if mk_filters:
            db.query(TrackedProductManualKeyword).filter(or_(*mk_filters), TrackedProductManualKeyword.is_active.is_(True)).update(
                {"is_active": False}, synchronize_session=False
            )
    except Exception:
        # 수기 키워드는 부가 데이터이므로 실패해도 tracked_product_keyword 삭제는 유지
        pass
    db.commit()
    return {"deleted": int(deleted or 0)}


@app.delete("/search-rank/tracked/{tracked_keyword_id}", response_model=TrackedProductKeywordRead)
def delete_tracked_product_keyword(
    tracked_keyword_id: int,
    db: Session = Depends(get_db),
):
    """
    개별 추적 키워드(TrackedProductKeyword)를 비활성화한다.

    - 실제 삭제 대신 is_active=False 로만 표시하는 soft delete 방식이다.
    - 이미 비활성화된 경우 404 를 반환한다.
    """
    row: TrackedProductKeyword | None = (
        db.query(TrackedProductKeyword)
        .filter(TrackedProductKeyword.id == tracked_keyword_id)
        .one_or_none()
    )
    if row is None or not row.is_active:
        raise HTTPException(status_code=404, detail="tracked keyword not found")

    row.is_active = False
    db.add(row)
    db.commit()
    db.refresh(row)
    return row


AD_RANK_DIAGNOSIS_GENDERS = ("female", "male")
AD_RANK_DIAGNOSIS_AGE_BANDS = ("30-34", "35-39", "40-44", "45-49", "50-54", "55-59", "60+", "unknown")
AD_RANK_DIAGNOSIS_PLACEMENTS = ("mobile-shopping", "pc-shopping", "mobile-search", "pc-search")
AD_RANK_DEFAULT_PRESETS = [
    (f"{gender}:{age_band}:{placement}", gender, age_band, placement, "core")
    for gender in AD_RANK_DIAGNOSIS_GENDERS
    for age_band in AD_RANK_DIAGNOSIS_AGE_BANDS
    for placement in AD_RANK_DIAGNOSIS_PLACEMENTS
]

AD_RANK_DIAGNOSIS_RANK_LIMIT = 92


def _normalize_ad_tracking_product_url(raw: str | None) -> str:
    u0 = str(raw or "").strip()
    if not u0:
        raise HTTPException(status_code=400, detail="product_url is required")
    if not re.match(r"^https?://", u0, flags=re.I):
        raise HTTPException(status_code=400, detail="product_url must be http(s) URL")
    return _canonicalize_smartstore_base_url(u0) or u0


def _default_ad_tracking_name(product_url: str, index1: int = 1) -> str:
    try:
        parsed = urlparse(product_url)
        parts = [p for p in (parsed.path or "").split("/") if p]
        suffix = parts[-1] if parts else parsed.netloc
        return f"광고 상품 {index1} · {suffix}"
    except Exception:
        return f"광고 상품 {index1}"


def _serialize_ad_tracked_product(db: Session, product: AdTrackedProduct) -> dict:
    meta_filters = _smartstore_product_url_filters(TrackedProductMeta, product_url=product.product_url)
    meta_query = db.query(TrackedProductMeta)
    if meta_filters:
        meta_query = meta_query.filter(or_(*meta_filters))
    else:
        meta_query = meta_query.filter(TrackedProductMeta.product_url == product.product_url)
    meta = meta_query.order_by(TrackedProductMeta.updated_at.desc(), TrackedProductMeta.id.desc()).first()

    ad_kws = (
        db.query(AdTrackedKeyword)
        .filter(AdTrackedKeyword.product_url == product.product_url)
        .order_by(AdTrackedKeyword.is_active.desc(), AdTrackedKeyword.created_at.asc(), AdTrackedKeyword.keyword.asc())
        .all()
    )

    organic_title = str(getattr(meta, "title", "") or "").strip() if meta else ""
    image_url = str(getattr(meta, "image_url", "") or "").strip() if meta else ""
    return {
        "product_url": product.product_url,
        "name": str(product.name or "").strip() or organic_title or _default_ad_tracking_name(product.product_url),
        "campaign_label": product.campaign_label,
        "organic_title": organic_title or None,
        "image_url": image_url or None,
        "is_active": bool(product.is_active),
        "created_at": product.created_at,
        "updated_at": product.updated_at,
        "keywords": ad_kws,
    }


def _parse_ad_tracking_keyword_item(raw) -> tuple[str, bool]:
    if isinstance(raw, dict):
        return str(raw.get("keyword") or "").strip(), bool(raw.get("is_active", True))
    if hasattr(raw, "keyword"):
        return str(getattr(raw, "keyword", "") or "").strip(), bool(getattr(raw, "is_active", True))
    keyword = str(raw or "").strip()
    return keyword, True


def _replace_ad_tracking_keywords(db: Session, *, product_url: str, keywords: list) -> None:
    dedup: dict[str, bool] = {}
    for raw in keywords or []:
        kw, is_active = _parse_ad_tracking_keyword_item(raw)
        if not kw:
            continue
        dedup[kw] = bool(is_active)

    now = datetime.utcnow()
    existing_rows = (
        db.query(AdTrackedKeyword)
        .filter(AdTrackedKeyword.product_url == product_url)
        .order_by(AdTrackedKeyword.created_at.asc(), AdTrackedKeyword.keyword.asc())
        .all()
    )
    existing_by_keyword = {str(row.keyword or "").strip(): row for row in existing_rows if str(row.keyword or "").strip()}

    for row in existing_rows:
        kw = str(row.keyword or "").strip()
        if kw not in dedup:
            db.delete(row)

    for kw, is_active in dedup.items():
        existing = existing_by_keyword.get(kw)
        if existing is not None:
            existing.is_active = bool(is_active)
            existing.updated_at = now
            db.add(existing)
            continue
        db.add(AdTrackedKeyword(product_url=product_url, keyword=kw, is_active=bool(is_active), updated_at=now))


def _rebuild_tracked_product_auto_keywords_from_main_sub(db: Session, *, days: int = 30) -> dict:
    """
    Rebuild focus-stage keyword groups from the same MAIN/SUB purchase
    classification used by the product tracking screen.

    Contract:
    - MAIN (top 20% by recent purchase payments among purchase-positive keywords) -> core/group1
    - SUB  (remaining purchase-positive keywords) -> watch/group2
    """
    target_to = _today_kst()
    target_from = target_to - timedelta(days=max(1, int(days or 30)) - 1)
    product_rows = (
        db.query(TrackedProductManualKeyword.product_url)
        .filter(
            TrackedProductManualKeyword.is_active.is_(True),
            TrackedProductManualKeyword.product_url.is_not(None),
            TrackedProductManualKeyword.product_url != "",
        )
        .distinct()
        .all()
    )
    tracked_product_rows = (
        db.query(TrackedProductKeyword.product_url)
        .filter(
            TrackedProductKeyword.is_active.is_(True),
            TrackedProductKeyword.product_url.is_not(None),
            TrackedProductKeyword.product_url != "",
        )
        .distinct()
        .all()
    )
    product_urls = sorted({
        _canonicalize_smartstore_base_url(str(row[0] or "").strip()) or str(row[0] or "").strip()
        for row in list(product_rows or []) + list(tracked_product_rows or [])
        if str(row[0] or "").strip()
    })
    now = datetime.utcnow()
    changed_products = 0
    core_count = 0
    watch_count = 0
    details: list[dict] = []

    for product_url in product_urls:
        pid = _canonical_product_id(product_url)
        if not pid:
            continue
        try:
            product_id = int(pid)
        except Exception:
            continue
        if product_id < 0 or product_id > 9223372036854775807:
            continue

        keyword_set: set[str] = set()
        manual_filters = _smartstore_product_url_filters(TrackedProductManualKeyword, product_url=product_url)
        if manual_filters:
            manual_keywords = (
                db.query(TrackedProductManualKeyword.keyword)
                .filter(or_(*manual_filters), TrackedProductManualKeyword.is_active.is_(True))
                .all()
            )
            keyword_set.update(str(row[0] or "").strip() for row in manual_keywords if str(row[0] or "").strip())
        tracked_filters = _smartstore_product_url_filters(TrackedProductKeyword, product_url=product_url)
        if tracked_filters:
            tracked_keywords = (
                db.query(TrackedProductKeyword.keyword)
                .filter(or_(*tracked_filters), TrackedProductKeyword.is_active.is_(True))
                .all()
            )
            keyword_set.update(str(row[0] or "").strip() for row in tracked_keywords if str(row[0] or "").strip())
        if not keyword_set:
            continue

        purchase_rows = (
            db.query(NaverSmartstorePurchaseKeywordDaily.keyword, func.sum(NaverSmartstorePurchaseKeywordDaily.payments))
            .filter(
                NaverSmartstorePurchaseKeywordDaily.product_id == product_id,
                NaverSmartstorePurchaseKeywordDaily.date >= target_from,
                NaverSmartstorePurchaseKeywordDaily.date <= target_to,
                NaverSmartstorePurchaseKeywordDaily.keyword.in_(sorted(keyword_set)),
            )
            .group_by(NaverSmartstorePurchaseKeywordDaily.keyword)
            .all()
        )
        purchase_scores: list[tuple[str, float]] = []
        for keyword, payments in purchase_rows or []:
            kw = str(keyword or "").strip()
            if not kw:
                continue
            try:
                value = float(payments or 0)
            except Exception:
                value = 0.0
            if value > 0:
                purchase_scores.append((kw, value))
        purchase_scores.sort(key=lambda item: (-item[1], item[0]))

        core_keywords: set[str] = set()
        watch_keywords: set[str] = set()
        if purchase_scores:
            main_count = max(1, int(math.ceil(len(purchase_scores) * 0.2)))
            core_keywords = {kw for kw, _ in purchase_scores[:main_count]}
            watch_keywords = {kw for kw, _ in purchase_scores[main_count:]}

        auto_filters = _smartstore_product_url_filters(TrackedProductAutoKeyword, product_url=product_url)
        if auto_filters:
            db.query(TrackedProductAutoKeyword).filter(
                or_(*auto_filters),
                TrackedProductAutoKeyword.is_active.is_(True),
            ).update({"is_active": False, "updated_at": now}, synchronize_session=False)

        for kw in sorted(core_keywords):
            db.merge(
                TrackedProductAutoKeyword(
                    product_url=product_url,
                    keyword=kw,
                    group_type="core",
                    is_active=True,
                    updated_at=now,
                )
            )
        for kw in sorted(watch_keywords):
            db.merge(
                TrackedProductAutoKeyword(
                    product_url=product_url,
                    keyword=kw,
                    group_type="watch",
                    is_active=True,
                    updated_at=now,
                )
            )
        changed_products += 1
        core_count += len(core_keywords)
        watch_count += len(watch_keywords)
        details.append(
            {
                "product_url": product_url,
                "keywords": len(keyword_set),
                "purchase_positive": len(purchase_scores),
                "core": len(core_keywords),
                "watch": len(watch_keywords),
            }
        )

    if changed_products:
        db.commit()
    return {
        "window_days": max(1, int(days or 30)),
        "date_from": target_from.isoformat(),
        "date_to": target_to.isoformat(),
        "products": changed_products,
        "core": core_count,
        "watch": watch_count,
        "details": details,
        "rule": "purchase_MAIN_to_core_SUB_to_watch",
    }


def _sync_ad_tracking_from_organic_core(db: Session) -> dict:
    """
    Deprecated. 광고 추적 상품/키워드는 이제 내 광고 상품 추적 화면에서만 관리한다.
    """
    return {
        "ok": True,
        "disabled": True,
        "products": 0,
        "keyword_products": 0,
        "keywords": 0,
        "keyword_source": "ad_tracked_keyword",
        "reason": "ad_tracking_keywords_are_managed_in_ad_tracking_menu",
        "rank_limit": AD_RANK_DIAGNOSIS_RANK_LIMIT,
        "collection_unit": "keyword_search_once_for_all_products",
    }


def _ensure_ad_rank_default_presets(db: Session) -> None:
    existing = {
        str(row.condition_id): row
        for row in db.query(AdRankDiagnosisPreset).all()
        if row.condition_id
    }
    desired_ids = {condition_id for condition_id, *_ in AD_RANK_DEFAULT_PRESETS}
    changed = False
    for condition_id, gender, age_band, placement, scope in AD_RANK_DEFAULT_PRESETS:
        existing_row = existing.get(condition_id)
        if existing_row is not None:
            row_changed = False
            if existing_row.scope != scope:
                existing_row.scope = scope
                row_changed = True
            if not existing_row.is_active:
                existing_row.is_active = True
                row_changed = True
            if row_changed:
                db.add(existing_row)
                changed = True
            continue
        db.add(
            AdRankDiagnosisPreset(
                condition_id=condition_id,
                gender=gender,
                age_band=age_band,
                placement=placement,
                target_rank=20,
                scope=scope,
                is_active=True,
            )
        )
        changed = True
    for row in existing.values():
        gender = str(getattr(row, "gender", "") or "").strip()
        age_band = str(getattr(row, "age_band", "") or "").strip()
        placement = str(getattr(row, "placement", "") or "").strip()
        if (
            str(getattr(row, "scope", "") or "").strip() == "core"
            and bool(getattr(row, "is_active", False))
            and gender in AD_RANK_DIAGNOSIS_GENDERS
            and placement in AD_RANK_DIAGNOSIS_PLACEMENTS
            and str(getattr(row, "condition_id", "") or "").strip() not in desired_ids
            and age_band not in AD_RANK_DIAGNOSIS_AGE_BANDS
        ):
            row.is_active = False
            db.add(row)
            changed = True
    if changed:
        db.commit()


def _ad_rank_keyword_target_condition_id(gender: str, age_band: str, placement: str) -> str:
    return f"{str(gender or '').strip()}:{str(age_band or '').strip()}:{str(placement or '').strip()}"


def _ad_rank_product_keywords(db: Session, product_url: str) -> list[str]:
    url = _normalize_ad_tracking_product_url(product_url)
    rows = (
        db.query(AdTrackedKeyword.keyword)
        .filter(AdTrackedKeyword.product_url == url, AdTrackedKeyword.is_active.is_(True))
        .order_by(AdTrackedKeyword.keyword.asc())
        .all()
    )
    return [str(row[0] or "").strip() for row in rows if str(row[0] or "").strip()]


def _ad_rank_package_count_from_name(value: str | None) -> int | None:
    compact = re.sub(r"\s+", "", str(value or ""))
    match = re.search(r"(\d+)\s*개", compact)
    if not match:
        return None
    try:
        return int(match.group(1))
    except ValueError:
        return None


def _ad_rank_is_henna_dye_variant(product: dict) -> bool:
    name = str(product.get("name") or "")
    aliases = " ".join(str(v or "") for v in (product.get("match_names") or []))
    text = re.sub(r"\s+", "", f"{name} {aliases}")
    package_count = _ad_rank_package_count_from_name(text)
    if package_count not in {1, 2, 5, 11}:
        return False
    return "헤나" in text and "염색약" in text


def _ad_rank_keywords_for_collection_plan(
    product_items: list[dict],
    keywords_by_url: dict[str, list[str]],
) -> tuple[list[str], dict]:
    """
    광고 노출 진단은 같은 키워드 조회 결과에서 여러 SKU 순위를 함께 산출한다.
    헤나 염색약 1/2/5/11개 SKU는 대표 SKU 키워드만 검색해
    중복 키워드 확장을 막는다.
    """

    henna_variant_urls = [
        str(item.get("product_url") or "").strip()
        for item in product_items
        if _ad_rank_is_henna_dye_variant(item)
    ]
    henna_variant_urls = [url for url in henna_variant_urls if url]
    representative_url = ""
    representative_keywords: list[str] = []
    representative_count: int | None = None
    if henna_variant_urls:
        candidates: list[tuple[int, int, str, list[str], int | None]] = []
        for item in product_items:
            url = str(item.get("product_url") or "").strip()
            if url not in henna_variant_urls:
                continue
            package_count = _ad_rank_package_count_from_name(str(item.get("name") or ""))
            if package_count not in {1, 5}:
                continue
            kws = list(dict.fromkeys(keywords_by_url.get(url) or []))
            if not kws:
                continue
            package_priority = 0 if package_count == 1 else 1
            candidates.append((-len(kws), package_priority, url, kws, package_count))
        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1], item[2]))
            _, _, representative_url, representative_keywords, representative_count = candidates[0]
        else:
            fallback = sorted(
                [
                    (-len(list(dict.fromkeys(keywords_by_url.get(url) or []))), url)
                    for url in henna_variant_urls
                    if keywords_by_url.get(url)
                ],
                key=lambda item: (item[0], item[1]),
            )
            if fallback:
                _, representative_url = fallback[0]
                representative_keywords = list(dict.fromkeys(keywords_by_url.get(representative_url) or []))

    keywords: list[str] = []
    if representative_url:
        # 광고순위 진단은 헤나 염색약 대표 상품(1개)의 그룹1 키워드를 기준으로만 수집한다.
        # 검색 1회로 등록 광고 상품 전체의 노출 순위를 함께 판정하므로, 다른 상품 core 키워드를
        # 합산하면 수집 기준과 화면의 대표 그룹1 기준이 달라진다.
        keywords.extend(representative_keywords)
    else:
        for product in product_items:
            url = str(product.get("product_url") or "").strip()
            if not url:
                continue
            keywords.extend(keywords_by_url.get(url) or [])
    deduped_keywords = sorted({str(kw or "").strip() for kw in keywords if str(kw or "").strip()})
    return deduped_keywords, {
        "strategy": "representative_sku_keywords",
        "henna_variant_product_count": len(henna_variant_urls),
        "representative_product_url": representative_url or None,
        "representative_package_count": representative_count,
        "representative_keyword_count": len(representative_keywords),
        "excluded_variant_keyword_union_count": len(
            {
                str(kw or "").strip()
                for url in henna_variant_urls
                if url != representative_url
                for kw in (keywords_by_url.get(url) or [])
                if str(kw or "").strip()
            }
        ),
    }


def _ad_rank_collection_plan(db: Session) -> dict:
    _ensure_ad_rank_default_presets(db)
    products = (
        db.query(AdTrackedProduct)
        .filter(AdTrackedProduct.is_active.is_(True))
        .order_by(AdTrackedProduct.name.asc())
        .all()
    )
    product_items = []
    for row in products:
        product_url = str(row.product_url or "").strip()
        if not product_url:
            continue
        aliases: list[str] = []
        meta = None
        meta_filters = _smartstore_product_url_filters(TrackedProductMeta, product_url=product_url)
        if meta_filters:
            meta = db.query(TrackedProductMeta).filter(or_(*meta_filters)).order_by(TrackedProductMeta.updated_at.desc()).first()
        meta_title = str(getattr(meta, "title", "") or "").strip()
        mall_name = str(getattr(meta, "mall_name", "") or "").strip()
        image_url = str(getattr(meta, "image_url", "") or "").strip()
        for value in (str(row.name or "").strip(), meta_title, f"{mall_name} {meta_title}".strip()):
            if value and value not in aliases:
                aliases.append(value)
        product_items.append(
            {
                "product_url": product_url,
                "name": str(row.name or "").strip(),
                "match_names": aliases,
                "mall_name": mall_name,
                "image_url": image_url or None,
            }
        )
    keywords_by_url = {
        str(product.get("product_url") or "").strip(): _ad_rank_product_keywords(db, str(product.get("product_url") or ""))
        for product in product_items
        if str(product.get("product_url") or "").strip()
    }
    keywords, keyword_plan_meta = _ad_rank_keywords_for_collection_plan(product_items, keywords_by_url)
    conditions = [
        {
            "condition_id": str(row.condition_id or "").strip(),
            "gender": str(row.gender or "").strip(),
            "age_band": str(row.age_band or "").strip(),
            "placement": str(row.placement or "").strip(),
            "target_rank": int(row.target_rank or 20),
        }
        for row in (
            db.query(AdRankDiagnosisPreset)
            .filter(AdRankDiagnosisPreset.is_active.is_(True), AdRankDiagnosisPreset.scope == "core")
            .order_by(AdRankDiagnosisPreset.age_band.asc(), AdRankDiagnosisPreset.gender.asc(), AdRankDiagnosisPreset.placement.asc())
            .all()
        )
    ]
    return {
        "products": product_items,
        "keywords": keywords,
        "conditions": conditions,
        "rank_limit": AD_RANK_DIAGNOSIS_RANK_LIMIT,
        "search_unit": "keyword_once_for_all_products",
        "keyword_plan": keyword_plan_meta,
    }


def _clear_ad_rank_diagnosis_rows_for_fresh_start(db: Session, target: date) -> int:
    """
    새 광고순위 full 수집을 시작할 때는 당일 이전 수집 row를 지운다.
    Host Agent partial upload는 이 함수를 거치지 않고 merge로 이어 저장한다.
    """
    deleted = (
        db.query(AdRankDiagnosisDaily)
        .filter(AdRankDiagnosisDaily.date == target)
        .delete(synchronize_session=False)
    )
    db.commit()
    return int(deleted or 0)


def _collection_wants_ad_rank_retry_incomplete(payload: CollectionRunPayload | None) -> bool:
    if payload is None:
        return False
    if bool(getattr(payload, "retry_incomplete", False)):
        return True
    mode = str(getattr(payload, "mode", "") or "").strip().lower()
    return mode in {"retry", "retry_incomplete", "retry-incomplete"}


def _ad_rank_expected_keys_from_plan(plan: dict, target: date) -> set[tuple]:
    expected: set[tuple] = set()
    products = [
        str(item.get("product_url") or "").strip()
        for item in (plan.get("products") or [])
        if isinstance(item, dict) and str(item.get("product_url") or "").strip()
    ]
    keywords = [str(kw or "").strip() for kw in (plan.get("keywords") or []) if str(kw or "").strip()]
    conditions = []
    for cond in plan.get("conditions") or []:
        if not isinstance(cond, dict):
            continue
        gender = str(cond.get("gender") or "").strip()
        age_band = str(cond.get("age_band") or "").strip()
        placement = str(cond.get("placement") or "").strip()
        if gender and age_band and placement:
            conditions.append((gender, age_band, placement))
    for product_url in products:
        for keyword in keywords:
            for gender, age_band, placement in conditions:
                expected.add((target, product_url, keyword, gender, age_band, placement))
    return expected


def _ad_rank_list_incomplete_cells(db: Session, target: date, plan: dict | None = None) -> list[dict]:
    """
    수집 plan 기준 기대 셀 중 누락(missing) 또는 조회실패(failed)만 반환.
    not_visible / success 는 재시도 대상이 아니다.
    """
    base_plan = plan or _ad_rank_collection_plan(db)
    expected = _ad_rank_expected_keys_from_plan(base_plan, target)
    if not expected:
        return []
    rows = (
        db.query(
            AdRankDiagnosisDaily.date,
            AdRankDiagnosisDaily.product_url,
            AdRankDiagnosisDaily.keyword,
            AdRankDiagnosisDaily.gender,
            AdRankDiagnosisDaily.age_band,
            AdRankDiagnosisDaily.placement,
            AdRankDiagnosisDaily.status,
            AdRankDiagnosisDaily.error,
        )
        .filter(AdRankDiagnosisDaily.date == target)
        .all()
    )
    saved: dict[tuple, tuple[str, str | None]] = {}
    for row in rows:
        key = (
            row[0],
            str(row[1] or "").strip(),
            str(row[2] or "").strip(),
            str(row[3] or "").strip(),
            str(row[4] or "").strip(),
            str(row[5] or "").strip(),
        )
        if key not in expected:
            continue
        saved[key] = (str(row[6] or "").strip().lower(), (str(row[7] or "").strip() or None))
    incomplete: list[dict] = []
    for key in sorted(expected, key=lambda x: (str(x[2]), str(x[3]), str(x[4]), str(x[5]), str(x[1]))):
        status, err = saved.get(key, (None, None))
        if status is None:
            reason = "missing"
        elif status == "failed":
            reason = "failed"
        else:
            continue
        incomplete.append(
            {
                "date": key[0].isoformat() if hasattr(key[0], "isoformat") else str(key[0]),
                "product_url": key[1],
                "keyword": key[2],
                "gender": key[3],
                "age_band": key[4],
                "placement": key[5],
                "reason": reason,
                "status": status,
                "error": err,
            }
        )
    return incomplete


def _ad_rank_group_incomplete_into_units(
    incomplete: list[dict],
    *,
    products_by_url: dict[str, dict],
    conditions_by_key: dict[tuple[str, str, str], dict],
) -> list[dict]:
    groups: dict[tuple[str, str, str, str], list[str]] = {}
    for cell in incomplete:
        keyword = str(cell.get("keyword") or "").strip()
        gender = str(cell.get("gender") or "").strip()
        age_band = str(cell.get("age_band") or "").strip()
        placement = str(cell.get("placement") or "").strip()
        product_url = str(cell.get("product_url") or "").strip()
        if not (keyword and gender and age_band and placement and product_url):
            continue
        key = (keyword, gender, age_band, placement)
        groups.setdefault(key, [])
        if product_url not in groups[key]:
            groups[key].append(product_url)
    units: list[dict] = []
    for (keyword, gender, age_band, placement), urls in sorted(groups.items(), key=lambda x: x[0]):
        cond = conditions_by_key.get((gender, age_band, placement))
        if not cond:
            cond = {
                "condition_id": f"{gender}:{age_band}:{placement}",
                "gender": gender,
                "age_band": age_band,
                "placement": placement,
                "target_rank": 20,
            }
        products = [products_by_url[u] for u in urls if u in products_by_url]
        if not products:
            continue
        units.append(
            {
                "keyword": keyword,
                "condition": dict(cond),
                "products": products,
            }
        )
    return units


def _ad_rank_ordered_search_units_from_plan(plan: dict) -> list[dict]:
	products = [item for item in (plan.get("products") or []) if isinstance(item, dict)]
	keywords = [str(kw or "").strip() for kw in (plan.get("keywords") or []) if str(kw or "").strip()]
	left_to_right = ["mobile-search", "pc-search", "mobile-shopping", "pc-shopping"]
	placement_order = {placement: idx for idx, placement in enumerate(left_to_right)}
	conditions = sorted(
		[cond for cond in (plan.get("conditions") or []) if isinstance(cond, dict)],
		key=lambda cond: (
			str(cond.get("gender") or ""),
			str(cond.get("age_band") or ""),
			placement_order.get(str(cond.get("placement") or ""), 999),
		),
	)
	demographic_keys: list[tuple[str, str]] = []
	conditions_by_demo: dict[tuple[str, str], dict[str, dict]] = {}
	for cond in conditions:
		gender = str(cond.get("gender") or "").strip()
		age_band = str(cond.get("age_band") or "").strip()
		placement = str(cond.get("placement") or "").strip()
		if not (gender and age_band and placement):
			continue
		key = (gender, age_band)
		if key not in conditions_by_demo:
			conditions_by_demo[key] = {}
			demographic_keys.append(key)
		conditions_by_demo[key][placement] = cond
	units: list[dict] = []
	for keyword in keywords:
		for demo_key in demographic_keys:
			conditions_for_demo = conditions_by_demo.get(demo_key) or {}
			for placement in left_to_right:
				condition = conditions_for_demo.get(placement)
				if not condition:
					continue
				units.append(
					{
						"keyword": keyword,
						"condition": dict(condition),
						"products": products,
					}
				)
	return units


def _ad_rank_attempted_unit_keys(db: Session, target: date, plan: dict) -> set[tuple[str, str, str, str]]:
	expected = _ad_rank_expected_keys_from_plan(plan, target)
	if not expected:
		return set()
	rows = (
		db.query(
			AdRankDiagnosisDaily.product_url,
			AdRankDiagnosisDaily.keyword,
			AdRankDiagnosisDaily.gender,
			AdRankDiagnosisDaily.age_band,
			AdRankDiagnosisDaily.placement,
		)
		.filter(AdRankDiagnosisDaily.date == target)
		.all()
	)
	attempted: set[tuple[str, str, str, str]] = set()
	for product_url, keyword, gender, age_band, placement in rows:
		key = (
			target,
			str(product_url or "").strip(),
			str(keyword or "").strip(),
			str(gender or "").strip(),
			str(age_band or "").strip(),
			str(placement or "").strip(),
		)
		if key in expected:
			attempted.add((key[2], key[3], key[4], key[5]))
	return attempted


def _ad_rank_retry_plan(db: Session, target: date) -> dict:
    base = _ad_rank_collection_plan(db)
    products_by_url = {
        str(item.get("product_url") or "").strip(): item
        for item in (base.get("products") or [])
        if isinstance(item, dict) and str(item.get("product_url") or "").strip()
    }
    conditions_by_key = {
        (
            str(cond.get("gender") or "").strip(),
            str(cond.get("age_band") or "").strip(),
            str(cond.get("placement") or "").strip(),
        ): cond
        for cond in (base.get("conditions") or [])
        if isinstance(cond, dict)
        and str(cond.get("gender") or "").strip()
        and str(cond.get("age_band") or "").strip()
        and str(cond.get("placement") or "").strip()
    }
    incomplete = _ad_rank_list_incomplete_cells(db, target, base)
    incomplete_units = _ad_rank_group_incomplete_into_units(
        incomplete,
        products_by_url=products_by_url,
        conditions_by_key=conditions_by_key,
    )
    ordered_units = _ad_rank_ordered_search_units_from_plan(base)
    attempted_keys = _ad_rank_attempted_unit_keys(db, target, base)
    last_attempted_index = -1
    for idx, unit in enumerate(ordered_units):
        condition = unit.get("condition") or {}
        unit_key = (
            str(unit.get("keyword") or "").strip(),
            str(condition.get("gender") or "").strip(),
            str(condition.get("age_band") or "").strip(),
            str(condition.get("placement") or "").strip(),
        )
        if unit_key in attempted_keys:
            last_attempted_index = idx
    units = ordered_units[last_attempted_index + 1 :]
    used_incomplete_fallback = False
    if not units and incomplete_units:
        # 이미 끝까지 한 번 지나간 뒤의 보정 상황에서는 실패/누락 셀 재시도 계획을 유지한다.
        units = incomplete_units
        used_incomplete_fallback = True
    resume_progress_total = len(ordered_units)
    resume_progress_offset = max(0, resume_progress_total - len(units)) if used_incomplete_fallback else (max(0, last_attempted_index + 1) if units else 0)
    resume_cell_count = sum(len(unit.get("products") or []) for unit in units)
    return {
        "retry": True,
        "retry_scope": "resume_from_last_attempted",
        "target_date": target.isoformat(),
        "products": list(products_by_url.values()),
        "keywords": sorted({str(unit.get("keyword") or "").strip() for unit in units if str(unit.get("keyword") or "").strip()}),
        "conditions": list(base.get("conditions") or []),
        "units": units,
        "rank_limit": AD_RANK_DIAGNOSIS_RANK_LIMIT,
        "search_unit": "retry_incomplete_cells",
        "retry_cell_count": resume_cell_count,
        "retry_unit_count": len(units),
        "retry_total_unit_count": resume_progress_total,
        "resume_progress_offset": resume_progress_offset,
        "resume_progress_total": resume_progress_total,
        "resume_attempted_unit_count": len(attempted_keys),
        "retry_failed_count": sum(1 for cell in incomplete if cell.get("reason") == "failed"),
        "retry_missing_count": sum(1 for cell in incomplete if cell.get("reason") == "missing"),
    }


@app.get("/collection/tasks/ad_rank_diagnosis_cdp/retry-preview", response_model=dict)
def ad_rank_retry_incomplete_preview(
    date: Optional[str] = Query(None),
    db: Session = Depends(get_db),
):
    target = _collection_parse_date(date) or _today_kst()
    plan = _ad_rank_retry_plan(db, target)
