@app.get("/ad-rank/tracked/keyword-ranks", response_model=dict)
def list_ad_tracked_products_keyword_ranks(
    keyword: Optional[str] = Query(None, description="목록 우측에 표시할 광고 순위 조회 키워드(레거시 단일 값)"),
    keywords: Optional[List[str]] = Query(None, description="조회할 광고 키워드 목록"),
    genders: Optional[List[str]] = Query(None, description="조회할 성별 목록"),
    age_bands: Optional[List[str]] = Query(None, description="조회할 연령대 목록"),
    placements: Optional[List[str]] = Query(None, description="조회할 노출 지면 목록"),
    days: int = Query(7, ge=1, le=30),
    db: Session = Depends(get_db),
):
    """
    내 광고 상품 추적 목록에서 사용자가 선택한 조건의 최근 광고 순위를 상품별로 반환한다.

    데이터 소스는 `ad_rank_diagnosis_daily`이며, 선택된 키워드/성별/연령/지면 조건 안에서
    노출된 최상위 광고 순위를 대표값으로 쓴다.
    """
    selected_keywords = [
        str(value or "").strip()
        for value in ([keyword] if keyword else []) + list(keywords or [])
        if str(value or "").strip()
    ]
    selected_keywords = list(dict.fromkeys(selected_keywords))
    if not selected_keywords:
        raise HTTPException(status_code=400, detail="keyword is required")
    selected_genders = list(dict.fromkeys(str(value or "").strip() for value in list(genders or []) if str(value or "").strip()))
    selected_age_bands = list(dict.fromkeys(str(value or "").strip() for value in list(age_bands or []) if str(value or "").strip()))
    selected_placements = list(dict.fromkeys(str(value or "").strip() for value in list(placements or []) if str(value or "").strip()))
    invalid_genders = [value for value in selected_genders if value not in AD_RANK_DIAGNOSIS_GENDERS]
    invalid_age_bands = [value for value in selected_age_bands if value not in AD_RANK_DIAGNOSIS_AGE_BANDS]
    invalid_placements = [value for value in selected_placements if value not in AD_RANK_DIAGNOSIS_PLACEMENTS]
    if invalid_genders:
        raise HTTPException(status_code=400, detail=f"invalid genders: {', '.join(invalid_genders)}")
    if invalid_age_bands:
        raise HTTPException(status_code=400, detail=f"invalid age_bands: {', '.join(invalid_age_bands)}")
    if invalid_placements:
        raise HTTPException(status_code=400, detail=f"invalid placements: {', '.join(invalid_placements)}")

    today = _today_kst()
    date_from = today - timedelta(days=days - 1)
    dates = [date_from + timedelta(days=i) for i in range(days)]
    products = (
        db.query(AdTrackedProduct.product_url)
        .filter(AdTrackedProduct.is_active.is_(True))
        .order_by(AdTrackedProduct.name.asc())
        .all()
    )
    product_urls = [
        _normalize_ad_tracking_product_url(str(row[0] or "").strip())
        for row in products
        if str(row[0] or "").strip()
    ]

    items: list[dict] = []
    for product_url in product_urls:
        rows = (
            db.query(AdRankDiagnosisDaily.date, AdRankDiagnosisDaily.rank, AdRankDiagnosisDaily.visible, AdRankDiagnosisDaily.ad_type)
            .filter(
                AdRankDiagnosisDaily.product_url == product_url,
                AdRankDiagnosisDaily.keyword.in_(selected_keywords),
                AdRankDiagnosisDaily.date >= date_from,
                AdRankDiagnosisDaily.date <= today,
                *([AdRankDiagnosisDaily.gender.in_(selected_genders)] if selected_genders else []),
                *([AdRankDiagnosisDaily.age_band.in_(selected_age_bands)] if selected_age_bands else []),
                *([AdRankDiagnosisDaily.placement.in_(selected_placements)] if selected_placements else []),
            )
            .all()
        )
        by_date: dict[date, dict] = {}
        for d, rank_value, visible, ad_type in rows:
            parsed = _collection_parse_date(d)
            if parsed is None or not bool(visible):
                continue
            try:
                rank_int = int(rank_value) if rank_value is not None else None
            except Exception:
                rank_int = None
            if rank_int is None or rank_int <= 0 or rank_int > AD_RANK_DIAGNOSIS_RANK_LIMIT:
                continue
            current = by_date.get(parsed)
            if current is None or rank_int < int(current.get("rank") or AD_RANK_DIAGNOSIS_RANK_LIMIT + 1):
                by_date[parsed] = {"rank": rank_int, "ad_type": str(ad_type or "").strip() or None}
        items.append(
            {
                "product_url": product_url,
                "ranks": [
                    {
                        "date": d.isoformat(),
                        "rank": int(by_date[d]["rank"]) if d in by_date else None,
                        "ad_type": by_date[d].get("ad_type") if d in by_date else None,
                    }
                    for d in dates
                ],
            }
        )

    return {
        "keyword": selected_keywords[0],
        "keywords": selected_keywords,
        "genders": selected_genders,
        "age_bands": selected_age_bands,
        "placements": selected_placements,
        "date_from": date_from.isoformat(),
        "date_to": today.isoformat(),
        "dates": [d.isoformat() for d in dates],
        "items": items,
    }


